function IT.merge(tbl)
for lang, words in pairs(IT.strings) do
tbl[lang] = tbl[lang] or {}
tbl[lang].items = words
local cond = {}
for _, rule in ipairs(IT.heal) do
cond[rule.key] = words[rule.mode == "mana" and "mana_below" or rule.mode == "above" and "hp_above" or "hp_below"]
end
tbl[lang].cond = cond
end
return tbl
end
function IT.base(name)
return (name:gsub("^item_", ""):gsub("_custom$", ""))
end
function IT.matches(base, key)
if base == key then return true end
return key == "dagon" and base:find("^dagon_%d$") ~= nil
end
function IT.build(section, side, iconOf, identifier, heroName)
IT.id = identifier
local ui = IT.ui
local group = section:Create("items.group", side)
local use = group:Label("items.use", "\u{f009}")
local useGear = use:Gear("items.use", IT.bars)
ui.items = useGear:MultiSelect("items.list", {}, true)
if type(X6P) == "table" and X6P.widgets[#X6P.widgets] ~= nil then ui.itemsReal = X6P.widgets[#X6P.widgets].w end
ui.items:ToolTip("items.list_tip")
ui.items:DragAllowed(true)
local cond = group:Label("items.cond", "\u{f1de}")
local condGear = cond:Gear("items.cond", IT.bars)
ui.saveItems = condGear:Input("items.save_items", "")
ui.saveItems:Visible(false)
ui.saveStun = condGear:Input("items.save_stun", "")
ui.saveStun:Visible(false)
ui.saveLinken = condGear:Input("items.save_linken", "")
ui.saveLinken:Visible(false)
ui.smart = condGear:Switch("items.smart", true)
ui.smart:Icon("\u{f0d0}")
ui.smart:ToolTip("items.smart_tip")
ui.immune = condGear:Switch("items.immune", true)
ui.immune:Icon("\u{f3ed}")
ui.immune:ToolTip("items.immune_tip")
ui.stun = condGear:MultiSelect("items.stun", {}, true)
ui.stun:ToolTip("items.stun_tip")
for _, rule in ipairs(IT.heal) do
local slider = condGear:Slider("cond." .. rule.key, 1, 100, rule.def, "%d%%")
slider:Image(iconOf("item_" .. rule.key))
ui.heal[rule.key] = slider
end
local linken = group:Label("items.linken", "panorama/images/items/sphere_png.vtex_c")
local linkenGear = linken:Gear("items.linken", IT.bars)
local known, used, rows, keys = {}, {}, {}, {}
for _, key in ipairs(IT.linken) do
local only = IT.linkenOnly[key]
if only == nil or only == heroName then
keys[#keys + 1] = key
known[(key:gsub("_", " "))] = key
end
end
for _, pair in ipairs(IT.unpack(ui.saveLinken:Get())) do
local key = known[pair[1]]
if key ~= nil and not used[key] then
used[key] = true
rows[#rows + 1] = { pair[1], iconOf("item_" .. (IT.iconFix[key] or key)), pair[2] }
end
end
for _, key in ipairs(keys) do
if not used[key] then rows[#rows + 1] = { (key:gsub("_", " ")), iconOf("item_" .. (IT.iconFix[key] or key)), true } end
end
ui.linken = linkenGear:MultiSelect("items.linken_list", rows, true)
ui.linken:ToolTip("items.linken_tip")
ui.linken:DragAllowed(true)
if IT.octarine.first then
local oct = group:Label("items.octarine", "panorama/images/items/octarine_core_png.vtex_c")
local octGear = oct:Gear("items.octarine", IT.bars)
ui.octarine = octGear:MultiSelect("items.octarine_list", {}, true)
ui.octarine:OneItemSelection(true)
ui.octarine:ToolTip("items.octarine_tip")
ui.saveOctarine = octGear:Input("items.save_octarine", "")
ui.saveOctarine:Visible(false)
if IT.octarine.clone then
ui.octarineClone = octGear:MultiSelect("items.octarine_clone", {}, true)
ui.octarineClone:OneItemSelection(true)
ui.octarineClone:ToolTip("items.octarine_tip")
ui.saveOctarineClone = octGear:Input("items.save_octarine_clone", "")
ui.saveOctarineClone:Visible(false)
end
end
return ui.items
end
function IT.sync(hero, labels, ids, iconOf)
local ui = IT.ui
ui.itemNames = ids
local old, enabled = {}, {}
for _, id in ipairs(ui.stun:List()) do old[id] = true end
for _, id in ipairs(ui.stun:ListEnabled()) do enabled[id] = true end
local rows, selected = {}, {}
for i, label in ipairs(labels) do
local on = old[label] == true and enabled[label] == true
rows[i] = { label, iconOf(ids[label]), on }
if on then selected[#selected + 1] = label end
end
ui.stun:Update(rows, true, true)
ui.stun:Set(selected)
if ui.octarine == nil then return end
local restore = not IT.octarine.synced
IT.octarine.synced = true
IT.fillOctarine(ui.octarine, ui.saveOctarine, labels, ids, iconOf, restore)
if ui.octarineClone ~= nil then IT.fillOctarine(ui.octarineClone, ui.saveOctarineClone, labels, ids, iconOf, restore) end
end
function IT.fillOctarine(list, box, labels, ids, iconOf, restore)
local keep = list:ListEnabled()[1]
if restore then keep = box:Get() end
local picks, found = {}, false
for _, label in ipairs(labels) do
if IT.base(ids[label]) ~= IT.octarine.key then
picks[#picks + 1] = { label, iconOf(ids[label]), label == keep }
if label == keep then found = true end
end
end
list:Update(picks, true, true)
list:Set(found and { keep } or {})
end
function IT.pack(list)
local parts = {}
for _, id in ipairs(list:List()) do
parts[#parts + 1] = id .. "=" .. (list:Get(id) and "1" or "0")
end
return table.concat(parts, "|")
end
function IT.unpack(text)
local out = {}
if type(text) ~= "string" then return out end
for part in text:gmatch("[^|]+") do
local id, on = part:match("^(.*)=([01])$")
if id ~= nil and id ~= "" then out[#out + 1] = { id, on == "1" } end
end
return out
end
function IT.prime(list, box)
if #list:List() > 0 then return {} end
local saved = IT.unpack(box:Get())
local rows, selected = {}, {}
for i, pair in ipairs(saved) do
rows[i] = { pair[1], "", pair[2] }
if pair[2] then selected[#selected + 1] = pair[1] end
end
if #rows > 0 then
list:Update(rows, true, true)
list:Set(selected)
end
return saved
end
function IT.store(list, box)
local text = IT.pack(list)
if text ~= "" and text ~= box:Get() then box:Set(text) end
end
function IT.orderedRows(rows, box)
local saved = IT.unpack(box:Get())
if #saved == 0 then return rows end
local byId, out = {}, {}
for _, row in ipairs(rows) do byId[row[1]] = row end
for _, pair in ipairs(saved) do
local row = byId[pair[1]]
if row ~= nil then
out[#out + 1] = { row[1], row[2], pair[2] }
byId[pair[1]] = nil
end
end
for _, row in ipairs(rows) do
if byId[row[1]] ~= nil then out[#out + 1] = row end
end
return out
end
function IT.primeOrder(list, box, rows)
if #IT.unpack(box:Get()) == 0 then return rows end
local ordered = IT.orderedRows(rows, box)
local selected = {}
for _, row in ipairs(ordered) do
if row[3] then selected[#selected + 1] = row[1] end
end
list:Update(ordered, true, true)
list:Set(selected)
return ordered
end
function IT.spellOrder(list)
local ok, ids = pcall(list.ListEnabled, list)
if ok and type(ids) == "table" then return ids end
return {}
end
function IT.register(heroes, spells, box, rows, icons)
if box ~= nil then IT.spellList = { list = spells, box = box, rows = rows, primed = false } end
if type(X6P) ~= "table" then return end
X6P.panel = X6P.panel or {}
X6P.panel[#X6P.panel + 1] = { heroes = heroes, spells = spells, spellsReal = X6P.widgets[#X6P.widgets] and X6P.widgets[#X6P.widgets].w, ui = IT.ui, icons = icons, order = box ~= nil }
end
function IT.tick()
local ui = IT.ui
local sl = IT.spellList
if sl ~= nil then
if not sl.primed then
sl.primed = true
IT.primeOrder(sl.list, sl.box, sl.rows)
end
IT.store(sl.list, sl.box)
end
if ui.saveItems == nil then return {} end
local saved = {}
if not IT.primed then
IT.primed = true
saved = IT.prime(ui.items, ui.saveItems)
IT.prime(ui.stun, ui.saveStun)
end
IT.store(ui.items, ui.saveItems)
IT.store(ui.stun, ui.saveStun)
IT.store(ui.linken, ui.saveLinken)
if ui.octarine ~= nil and IT.octarine.synced then
IT.keepOctarine(ui.octarine, ui.saveOctarine)
if ui.octarineClone ~= nil then IT.keepOctarine(ui.octarineClone, ui.saveOctarineClone) end
end
return saved
end
function IT.keepOctarine(list, box)
local pick = list:ListEnabled()[1] or ""
if pick ~= box:Get() then box:Set(pick) end
end
function IT.held(target)
if NPC.IsStunned(target) then return true end
for _, state in ipairs(IT.heldStates) do
if NPC.HasState(target, state) then return true end
end
return false
end
