IT.shareGet = type(load) == "function" and load("return X6Shared") or nil
IT.shareSet = type(load) == "function" and load("X6Shared = ...") or nil
function IT.shared(create)
local shared = nil
if IT.shareGet ~= nil then
local ok, value = pcall(IT.shareGet)
if ok and type(value) == "table" then shared = value end
end
if shared == nil and create and IT.shareSet ~= nil then
shared = { keys = {}, cp = {}, bias = {}, dur = {} }
if not pcall(IT.shareSet, shared) then return nil end
end
return shared
end
function IT.publishKey(id, widget)
local shared = IT.shared(true)
if shared == nil or widget == nil then return end
shared.keys = shared.keys or {}
shared.keys[id] = widget
end
function IT.castPoint(ability)
local api = math.max(0, Ability.GetCastPoint(ability))
local shared = IT.shared()
local learned = shared ~= nil and shared.cp ~= nil and shared.cp[Ability.GetName(ability)] or nil
if type(learned) == "number" and learned < api then return learned end
return api
end
function IT.learnedDur(name)
local shared = IT.shared()
local value = shared ~= nil and shared.dur ~= nil and name ~= nil and shared.dur[name] or nil
return type(value) == "number" and value or 0
end
function IT.bias(name)
local shared = IT.shared()
local value = shared ~= nil and shared.bias ~= nil and name ~= nil and shared.bias[name] or nil
return type(value) == "number" and value or 0
end
function IT.fogHold(target, now)
if target == nil then return false end
local ok, alive = pcall(Entity.IsAlive, target)
if not ok or not alive or not Entity.IsDormant(target) then
IT.fog.at = nil
return false
end
if IT.fog.at == nil then IT.fog.at = now end
return now - IT.fog.at <= IT.fogGrace
end
function IT.special(ability, key)
local ok, value = pcall(Ability.GetLevelSpecialValueFor, ability, key, -1)
if ok and type(value) == "number" and value > 0 then return value end
return nil
end
function IT.warn(name, key, expected, live)
local id = name .. "." .. key
if IT.warned[id] then return end
IT.warned[id] = true
if type(ai_bridge) == "table" and type(ai_bridge.mcp_log) == "function" then
pcall(ai_bridge.mcp_log, "warn", "flight table differs from the game", { ability = name, key = key, table = expected, live = live })
end
end
function IT.liveOf(ability, name, row, field, keyField)
local value = row[field]
local key = row[keyField]
if key ~= nil then
local live = IT.special(ability, key)
if live ~= nil then
if value ~= nil and math.abs(live - value) > value * 0.05 then IT.warn(name, key, value, live) end
return live
end
end
return value
end
function IT.flightOf(ability)
local name = Ability.GetName(ability)
local row = IT.flight[name]
if row == nil then return nil end
return IT.liveOf(ability, name, row, "sp", "spk"), IT.liveOf(ability, name, row, "dl", "dlk")
end
function IT.durOf(ability)
local name = Ability.GetName(ability)
local row = IT.flight[name]
if row == nil or row.du == nil then return nil end
local base = nil
if row.duk ~= nil then base = IT.special(ability, row.duk) end
if base == nil then
local list = row.du
base = list[math.min(math.max(Ability.GetLevel(ability), 1), #list)]
end
return math.max(base, IT.learnedDur(name))
end
function IT.holdLeft(target, now)
local left = 0
for _, mod in ipairs(NPC.GetModifiers(target) or {}) do
local name = Modifier.GetName(mod)
for _, word in ipairs(IT.holdWords) do
if name:find(word, 1, true) ~= nil then
local rest = Modifier.GetDieTime(mod) - now
if rest > left then left = rest end
break
end
end
end
local ch = IT.chain
if now < ch.untilT and (left > 0 or now < ch.apply + ch.confirm) then
left = math.max(left, ch.untilT - now)
end
return left
end
IT.speedKeys = { "projectile_speed", "speed" }
function IT.itemSpeed(item)
for _, key in ipairs(IT.speedKeys) do
local ok, value = pcall(Ability.GetLevelSpecialValueFor, item, key, -1)
if ok and type(value) == "number" and value >= 300 then return value end
end
return nil
end
IT.meteorLand = 0.5
function IT.itemFall(item, fallback)
