end
function IT.chainDelay(hero, target, name, rule)
local delay = 0.1
if IT.latency ~= nil then
local ok, value = pcall(IT.latency)
if ok and type(value) == "number" and value >= 0 then delay = value * 2 + 0.06 end
end
local speed, fall = rule.speed, rule.fall
for _, slot in ipairs(IT.ownSlots) do
local item = NPC.GetItemByIndex(hero, slot)
if item ~= nil and Ability.GetName(item) == name then
delay = delay + math.max(0, IT.castPoint(item))
if speed ~= nil then speed = IT.itemSpeed(item) or speed end
if fall ~= nil then fall = IT.itemFall(item, fall) end
break
end
end
if fall ~= nil then return delay + fall end
if speed ~= nil then
return delay + (Entity.GetAbsOrigin(hero) - Entity.GetAbsOrigin(target)):Length2D() / speed
end
return delay
end
function IT.chainWait(hero, target, name, now)
local rule = IT.controls[IT.base(name)]
if rule == nil or target == nil then return false end
local left = IT.holdLeft(target, now)
local delay = IT.chainDelay(hero, target, name, rule)
if left > delay + IT.bias(name) + IT.chain.pad then return true end
if rule.fall ~= nil and not IT.meteorLead then
local reach = rule.radius - NPC.GetHullRadius(target) - IT.chain.meteorMargin
if NPC.GetMoveSpeed(target) * math.max(0, delay - left) > reach then return true end
end
return false
end
function IT.publishPlan(target, name, left, delay)
local shared = IT.shared(true)
if shared == nil then return end
shared.plan = shared.plan or {}
shared.plan[Entity.GetIndex(target)] = { name = name, endAt = GameRules.GetGameTime() + left, sched = left > delay }
end
function IT.chainMark(hero, target, name)
local rule = IT.controls[IT.base(name)]
if rule == nil or target == nil then return end
local now = GameRules.GetGameTime()
local delay = IT.chainDelay(hero, target, name, rule)
IT.publishPlan(target, name, IT.holdLeft(target, now), delay)
IT.chain.apply = now + delay
IT.chain.untilT = math.max(IT.chain.untilT, now + delay + math.max(rule.dur, IT.learnedDur(name)))
if type(ai_bridge) == "table" and type(ai_bridge.mcp_log) == "function" then
pcall(ai_bridge.mcp_log, "info", "control chain", { item = name, lands_in = math.floor(delay * 100) / 100 })
end
end
IT.octarine = { key = "octarine_core", active = "modifier_item_octarine_core_custom_active", first = true, synced = false, clone = false, isClone = nil }
function IT.octarineWait(hero, name, label)
local oc = IT.octarine
if not oc.first or IT.ui.items == nil or IT.base(name) == oc.key then return false end
local list = IT.ui.octarine
if IT.ui.octarineClone ~= nil and oc.isClone ~= nil and oc.isClone(hero) then list = IT.ui.octarineClone end
local pick = list ~= nil and list:ListEnabled()[1] or nil
if pick ~= nil and pick ~= label then return false end
if NPC.HasModifier(hero, oc.active) then return false end
local item = IT.ownItem(hero, oc.key)
if item == nil or Ability.GetLevel(item) <= 0 or Ability.GetCooldown(item) > 0 or not Ability.IsReady(item) then return false end
for _, label in ipairs(IT.ui.items:ListEnabled()) do
if (label:gsub(" ", "_")) == oc.key then return true end
end
return false
end
function IT.needDispel(hero)
if NPC.IsSilenced(hero) or NPC.HasState(hero, IT.heldStates[3]) then return true end
for _, mod in ipairs(NPC.GetModifiers(hero) or {}) do
if Modifier.IsDebuff(mod) and Modifier.GetName(mod):find("slow", 1, true) ~= nil then return true end
end
return false
end
function IT.allow(hero, target, name, label)
local ui = IT.ui
if IT.chainWait(hero, target, name, GameRules.GetGameTime()) then return false end
if IT.octarineWait(hero, name, label) then return false end
if IT.eulWait(hero, target, name) then return false end
if target ~= nil and IT.targetsEnemy(hero, name) and IT.spellBlocked(target, GameRules.GetGameTime(), name) then return false end
local base = IT.base(name)
if IT.team[base] then
local now = GameRules.GetGameTime()
if now < IT.state.teamAt then return false end
if ui.smart ~= nil and ui.smart:Get() and not IT.smartAllow(hero, target, base, label) then return false end
IT.state.teamAt = now + IT.teamGap
