end
if ui.smart == nil or not ui.smart:Get() then return true end
return IT.smartAllow(hero, target, base, label)
end
function IT.smartAllow(hero, target, base, label)
local ui = IT.ui
local rule = IT.healMap[base]
if rule ~= nil then
local limit = ui.heal[base]:Get()
if rule.mode == "mana" then
return NPC.GetMana(hero) / math.max(1, NPC.GetMaxMana(hero)) * 100 < limit
end
local pct = Entity.GetHealth(hero) / math.max(1, Entity.GetMaxHealth(hero)) * 100
if rule.mode == "above" then return pct > limit end
return pct < limit or (base == "guardian_greaves" and IT.needDispel(hero))
end
