return true
end
function IT.stopPoint(hero, target, range)
local o, t = Entity.GetAbsOrigin(hero), Entity.GetAbsOrigin(target)
local dx, dy = t.x - o.x, t.y - o.y
local len = math.sqrt(dx * dx + dy * dy)
local keep = math.max(0, range - IT.stopMargin)
if len <= keep or len < 1 then return o end
return Vector(t.x - dx / len * keep, t.y - dy / len * keep, t.z)
end
function IT.linkenSource(target, now)
if now < IT.state.skipUntil then return nil end
