if NPC.HasModifier(target, name) then return "mod" end
end
for _, slot in ipairs(IT.targetSlots) do
local item = NPC.GetItemByIndex(target, slot)
if item ~= nil and IT.holders[IT.base(Ability.GetName(item))] and Ability.GetCooldown(item) <= 0 then
return "item"
end
end
return nil
end
function IT.heroDisabled(unit)
if unit == nil then return false end
if NPC.IsStunned(unit) then return true end
for _, state in ipairs(IT.disableStates) do
if NPC.HasState(unit, state) then return true end
end
