end
function IT.cycloned(target, now)
local st = IT.state
if st.cycTarget == target and st.cycAt == now then return st.cycValue end
local found = false
for _, mod in ipairs(NPC.GetModifiers(target) or {}) do
local name = Modifier.GetName(mod)
if name:find("cyclone", 1, true) ~= nil or name:find("wind_waker", 1, true) ~= nil then
found = true
break
end
end
st.cycTarget, st.cycAt, st.cycValue = target, now, found
return found
end
function IT.immune(target)
local ok, state = pcall(NPC.HasState, target, IT.stateImmune)
return ok and state == true
end
function IT.pierces(name)
return IT.pierce[name] == true or IT.pierce[IT.base(name)] == true
end
function IT.lethal(target, ability, key)
if target == nil or ability == nil then return false end
local ok, damage = pcall(Ability.GetLevelSpecialValueFor, ability, key, -1)
if not ok or type(damage) ~= "number" or damage <= 0 then return false end
local kind = Ability.GetDamageType(ability)
local factor = kind == IT.damagePure and 1 or kind == IT.damageMagical and NPC.GetMagicalArmorDamageMultiplier(target) or nil
return factor ~= nil and damage * factor >= Entity.GetHealth(target) * IT.lethalPad
end
function IT.immuneBlocked(target, name)
