local mana = NPC.GetMana(hero) - Ability.GetManaCost(own)
for base in pairs(IT.controls) do
local item = base ~= "cyclone" and base ~= "wind_waker" and IT.ownItem(hero, base) or nil
if item ~= nil and Ability.GetLevel(item) > 0 and Ability.IsReady(item) and Ability.IsCastable(item, mana) then return true end
end
