IT.moveStates = {
[IT.disableStates[1]] = true,
[IT.hasEnum and Enum.ModifierState.MODIFIER_STATE_ROOTED or 0] = true,
[IT.disableStates[2]] = true,
[IT.disableStates[3]] = true,
[IT.hasEnum and Enum.ModifierState.MODIFIER_STATE_FROZEN or 19] = true,
}
IT.stateGuess = 0.4
function IT.moveLeft(target, now)
