if type(NPC.GetStatesDuration) == "function" then
local ok, states = pcall(NPC.GetStatesDuration, target, IT.moveStates)
if ok and type(states) == "table" then
for state in pairs(IT.moveStates) do
local value = states[state]
if type(value) == "number" and value > left then left = value end
end
end
end
if left <= 0 then
for state in pairs(IT.moveStates) do
if NPC.HasState(target, state) then
left = IT.stateGuess
break
end
end
end
