local A = {}
function A.api(tbl, name)
return type(tbl) == "table" and type(tbl[name]) == "function" and tbl[name] or nil
end
function A.orderSafe()
local f = A.api(Humanizer, "IsSafeToCastOrder")
if f == nil then return true end
local ok, safe = pcall(f)
return not ok or safe ~= false
end
C.hasEnum = type(Enum) == "table"
C.orderMove = C.hasEnum and type(Enum.UnitOrder) == "table" and Enum.UnitOrder.DOTA_UNIT_ORDER_MOVE_TO_POSITION or 1
C.orderAttack = C.hasEnum and type(Enum.UnitOrder) == "table" and Enum.UnitOrder.DOTA_UNIT_ORDER_ATTACK_TARGET or 4
C.issuer = C.hasEnum and type(Enum.PlayerOrderIssuer) == "table" and Enum.PlayerOrderIssuer.DOTA_ORDER_ISSUER_PASSED_UNIT_ONLY or 3
C.teamEnemy = C.hasEnum and type(Enum.TeamType) == "table" and Enum.TeamType.TEAM_ENEMY or 0
C.keyF = C.hasEnum and type(Enum.ButtonCode) == "table" and Enum.ButtonCode.KEY_F or 16
C.modState = C.hasEnum and type(Enum.ModifierState) == "table" and Enum.ModifierState or {}
C.holdStates = {
C.modState.MODIFIER_STATE_STUNNED or 5, C.modState.MODIFIER_STATE_ROOTED or 0,
C.modState.MODIFIER_STATE_NIGHTMARED or 11, C.modState.MODIFIER_STATE_FROZEN or 19,
}
C.latency = A.api(NetChannel, "GetAvgLatency")
C.cursorHero = A.api(Input, "GetNearestHeroToCursor")
C.cursorPos = A.api(Input, "GetWorldCursorPos")
C.special = A.api(Ability, "GetLevelSpecialValueFor")
C.inputCaptured = A.api(Input, "IsInputCaptured")
C.bHidden = C.hasEnum and type(Enum.AbilityBehavior) == "table" and Enum.AbilityBehavior.DOTA_ABILITY_BEHAVIOR_HIDDEN or 1
C.bPassive = C.hasEnum and type(Enum.AbilityBehavior) == "table" and Enum.AbilityBehavior.DOTA_ABILITY_BEHAVIOR_PASSIVE or 2
C.bNo = C.hasEnum and type(Enum.AbilityBehavior) == "table" and Enum.AbilityBehavior.DOTA_ABILITY_BEHAVIOR_NO_TARGET or 4
C.bUnit = C.hasEnum and type(Enum.AbilityBehavior) == "table" and Enum.AbilityBehavior.DOTA_ABILITY_BEHAVIOR_UNIT_TARGET or 8
C.bPoint = C.hasEnum and type(Enum.AbilityBehavior) == "table" and Enum.AbilityBehavior.DOTA_ABILITY_BEHAVIOR_POINT or 16
C.bToggle = C.hasEnum and type(Enum.AbilityBehavior) == "table" and Enum.AbilityBehavior.DOTA_ABILITY_BEHAVIOR_TOGGLE or 512
C.targetFriendly = C.hasEnum and type(Enum.TargetTeam) == "table" and Enum.TargetTeam.DOTA_UNIT_TARGET_TEAM_FRIENDLY or 1
C.targetEnemy = C.hasEnum and type(Enum.TargetTeam) == "table" and Enum.TargetTeam.DOTA_UNIT_TARGET_TEAM_ENEMY or 2
function A.log(level, message, data)
if type(ai_bridge) ~= "table" or type(ai_bridge.mcp_log) ~= "function" then return end
pcall(ai_bridge.mcp_log, level, message, data)
end
function A.valid(unit)
if unit == nil then return false end
local ok, alive = pcall(Entity.IsAlive, unit)
return ok and alive and not Entity.IsDormant(unit)
end
function A.distance(a, b)
return (Entity.GetAbsOrigin(a) - Entity.GetAbsOrigin(b)):Length2D()
end
function A.ability(hero, name)
local ability = NPC.GetAbility(hero, name)
if ability ~= nil and Ability.GetLevel(ability) > 0 and not Ability.IsHidden(ability) then return ability end
return nil
end
function A.ready(ability, hero)
return ability ~= nil and Ability.IsReady(ability) and Ability.GetCooldown(ability) <= 0
and Ability.IsCastable(ability, NPC.GetMana(hero))
end
function A.settle()
local ok, latency = false, nil
if C.latency ~= nil then ok, latency = pcall(C.latency) end
if not ok or type(latency) ~= "number" or latency < 0 then latency = 0.1 end
return math.max(C.settleMin, math.min(C.settleMax, latency * 2 + C.settlePad))
end
function A.initMenu()
local side = (C.hasEnum and Enum.GroupSide) or {}
local raw = RawMenu.Create("Heroes", "Hero List", "Bane", "1x6 Combo")
local section = localization.Wrap(raw, true)
local main = section:Create("menu.main", side.Left)
UI.enabled = main:Switch("menu.enabled", true, "panorama/images/heroes/icons/npc_dota_hero_bane_png.vtex_c")
UI.key = main:Bind("menu.key", C.keyF, "panorama/images/spellicons/bane_fiends_grip_png.vtex_c")
IT.publishKey("bane_1x6_combo", UI.key)
UI.key:ToolTip("menu.key_tip")
A.spellRows = {
{ "spell.q", "panorama/images/spellicons/bane_enfeeble_png.vtex_c", true },
{ "spell.e", "panorama/images/spellicons/bane_nightmare_png.vtex_c", true },
{ "spell.w", "panorama/images/spellicons/bane_brain_sap_png.vtex_c", true },
{ "spell.r", "panorama/images/spellicons/bane_fiends_grip_png.vtex_c", true },
{ "spell.shift", "panorama/images/spellicons/bane_brain_sap_png.vtex_c", true },
}
UI.saveSpells = main:Input("menu.save_spells", "")
UI.saveSpells:Visible(false)
UI.spells = main:MultiSelect("menu.spells", IT.orderedRows(A.spellRows, UI.saveSpells), true)
UI.spells:DragAllowed(true)
IT.register({ C.hero }, UI.spells, UI.saveSpells, A.spellRows)
UI.spells:ToolTip("menu.spells_tip")
UI.duel = main:Switch("menu.legend_e", false, "panorama/images/spellicons/bane_nightmare_png.vtex_c")
UI.duel:ToolTip("menu.legend_e_tip")
UI.duel:Visible(false)
UI.shiftMana = main:Slider("menu.shift_mana", 5, 90, 25, "%d%%")
UI.shiftMana:Icon("\u{f0e7}")
UI.sapLate = main:Switch("menu.sap_late", false)
UI.sapLate:Icon("\u{f0d0}")
UI.sapLate:ToolTip("menu.sap_late_tip")
UI.attack = main:Switch("menu.attack", true)
UI.attack:Icon("\u{f71c}")
UI.range = main:Slider("menu.range", 600, 3000, 1400, "%d")
UI.range:Icon("\u{f05b}")
UI.items = IT.build(section, side.Right, A.itemIcon, C.identifier, C.hero)
return true
end
function A.reset(reason)
if S.phase == "running" then
A.log("info", "bane combo stopped", { reason = reason })
end
S.phase = "idle"
S.target = nil
S.startedAt = 0
S.nextAt = 0
S.moveAt = 0
S.attacking = nil
S.done = {}
S.cycleAt = 0
S.sleepUntil, S.meteorUntil, S.fleeAt, S.fleePos, S.motion = 0, 0, 0, nil, "none"
end
function A.pickTarget(hero)
local target = nil
if C.cursorHero then
local ok, value = pcall(C.cursorHero, Entity.GetTeamNum(hero), C.teamEnemy)
if ok then target = value end
end
if target and A.valid(target) and not Entity.IsSameTeam(hero, target) and not NPC.IsIllusion(target)
and A.distance(hero, target) <= UI.range:Get() then
return target
end
local cursor = C.cursorPos and C.cursorPos() or Entity.GetAbsOrigin(hero)
local best = nil
local bestDistance = math.huge
for _, enemy in ipairs(Heroes.GetAll()) do
if enemy ~= hero and A.valid(enemy) and not Entity.IsSameTeam(hero, enemy) and not NPC.IsIllusion(enemy)
and A.distance(hero, enemy) <= UI.range:Get() then
local distance = (Entity.GetAbsOrigin(enemy) - cursor):Length2D()
if distance < bestDistance then
best = enemy
bestDistance = distance
end
end
end
return best
end
function A.order(hero, kind, point, target, ability, fast)
local player = Players.GetLocal()
if player == nil then return end
Player.PrepareUnitOrders(player, kind, target, point, ability, C.issuer, hero, false, true, false, fast, C.identifier)
end
function A.detectDuel(hero)
local ability = NPC.GetAbility(hero, C.duelName)
local has = ability ~= nil and Ability.GetLevel(ability) > 0 and not Ability.IsHidden(ability)
if has == S.legendE then return end
S.legendE = has
if UI.duel ~= nil then UI.duel:Visible(has) end
A.log("info", "bane e legendary", { e = has })
end
function A.castDuel(hero, target, now)
if not S.legendE or not UI.duel:Get() or now < S.duelAt then return false end
local ability = NPC.GetAbility(hero, C.duelName)
if ability == nil or Ability.GetLevel(ability) <= 0 or Ability.IsHidden(ability) or not A.ready(ability, hero) then return false end
if NPC.HasModifier(hero, C.duelMod) or NPC.HasModifier(target, C.duelMod) then return false end
if IT.spellBlocked(target, now, Ability.GetName(ability)) then return false end
if A.distance(hero, target) > Ability.GetCastRange(ability) + C.rangePad then return false end
Ability.CastTarget(ability, target, false, false, true, C.identifier)
S.duelAt = now + C.duelHold
S.nextAt = now + math.max(0, IT.castPoint(ability)) + A.settle()
S.attacking = nil
A.log("info", "bane nightmare duel")
return true
end
function A.detectLegend(hero)
local changed = false
if not S.legendW and A.ability(hero, C.shiftName) ~= nil then
S.legendW, changed = true, true
end
local stack = NPC.GetModifier(hero, C.stackMod)
local count = stack ~= nil and Modifier.GetStackCount(stack) or 0
if count ~= S.stacks then
A.log("info", "bane grip stacks", { count = count })
S.stacks = count
end
if not S.legendR and stack ~= nil then
S.legendR, changed = true, true
end
if changed or not S.legendShown then
S.legendShown = true
local yes, no = localization.Get("menu.yes"), localization.Get("menu.no")
local text = string.format(localization.Get("menu.legend"), S.legendW and yes or no, S.legendR and yes or no)
if UI.legend ~= nil then pcall(UI.legend.ForceLocalization, UI.legend, text) end
if changed then A.log("info", "bane legendary detected", { w = S.legendW, r = S.legendR }) end
end
end
function A.gripHeld(target, now)
if target == nil then return false end
local mod = NPC.GetModifier(target, C.gripMod)
if S.gripDie <= 0 then
if mod == nil or now >= S.gripSeenUntil then return false end
S.gripDie = Modifier.GetDieTime(mod)
S.gripModAt, S.gripDrift = now, false
A.log("info", "bane grip seen", { left = math.floor((S.gripDie - now) * 100) / 100, channel_seen = S.channelAt > 0 })
return true
end
if mod ~= nil then
S.gripModAt = now
if not S.gripDrift and math.abs(Modifier.GetDieTime(mod) - S.gripDie) > 0.1 then
S.gripDrift = true
A.log("info", "bane grip die time changed", { was = math.floor((S.gripDie - now) * 100) / 100, now = math.floor((Modifier.GetDieTime(mod) - now) * 100) / 100 })
end
end
if now < S.gripDie and now - S.gripModAt < C.gripMissGrace then return true end
A.log("info", "bane grip lock end", {
reason = now >= S.gripDie and "time" or "modifier gone",
left = math.floor((S.gripDie - now) * 100) / 100,
channel_seen = S.channelAt > 0,
})
S.gripDie = 0
return false
end
function A.gripLocked(hero, r, now, target)
local channel = NPC.IsChannellingAbility(hero) or (r ~= nil and Ability.IsChannelling(r))
if channel then S.channelAt = now end
local held = A.gripHeld(target, now)
return held or channel or now < S.gripUntil or now - S.channelAt < C.channelGrace
end
function A.castSpell(hero, target, ability, key, now, breaking)
if ability == nil or not UI.spells:Get(key) or not A.ready(ability, hero) then return false end
if not breaking and IT.spellBlocked(target, now, Ability.GetName(ability)) then return false end
if now - (S.castAt[key] or -10) < C.recastGap then return false end
if A.distance(hero, target) > Ability.GetCastRange(ability) + C.rangePad then return false end
if key == "spell.r" and not breaking and IT.controlEarly(target, now, math.max(0, IT.castPoint(ability)) + A.settle()) then return false end
Ability.CastTarget(ability, target, false, false, true, C.identifier)
S.castAt[key] = now
local delay = math.max(0, IT.castPoint(ability)) + A.settle()
S.nextAt = now + delay
S.attacking = nil
if key == "spell.r" then
S.gripUntil = now + delay + C.gripLock
S.gripSeenUntil = S.gripUntil + C.gripSeenWindow
S.gripDie = 0
S.gripOwn, S.gripBlocked = true, false
end
A.log("info", "bane combo cast", { spell = key, mana = math.floor(NPC.GetMana(hero)) })
return true
end
function A.linkenQ(hero, target, q, now)
local source = IT.linkenSource(target, now)
if source == nil or not A.castSpell(hero, target, q, "spell.q", now, true) then return false end
local st = IT.state
st.waitUntil = now + math.max(0, IT.castPoint(q)) + IT.wait
st.skipUntil = st.waitUntil + (source == "item" and IT.itemGrace or IT.modGrace)
A.log("info", "bane linken enfeeble", { source = source })
return true
end
function A.orderLocked(data)
local hero = Heroes.GetLocal()
if hero == nil or not UI.key:IsDown() then
S.gripOwn = false
return false
end
local now = GameRules.GetGameTime()
if not A.gripLocked(hero, NPC.GetAbility(hero, C.rName), now, S.target) then
S.gripOwn = false
return false
end
local unit = data.npc
if unit == nil and data.ability ~= nil then unit = Ability.GetOwner(data.ability) end
if unit ~= nil and Entity.GetIndex(unit) ~= Entity.GetIndex(hero) then return false end
if not S.gripBlocked then
S.gripBlocked = true
A.log("info", "bane order blocked during grip", { order = data.order })
end
return true
end
function A.castShift(hero, now)
if not UI.spells:Get("spell.shift") then return false end
local shift = A.ability(hero, C.shiftName)
if shift == nil or not A.ready(shift, hero) or now - (S.castAt.shift or -10) < C.recastGap then return false end
local max = NPC.GetMaxMana(hero)
if max <= 0 or NPC.GetMana(hero) / max * 100 >= UI.shiftMana:Get() then return false end
Ability.CastNoTarget(shift, false, false, true, C.identifier)
S.castAt.shift = now
S.nextAt = now + A.settle()
S.attacking = nil
A.log("info", "bane combo shift", { mana_pct = math.floor(NPC.GetMana(hero) / max * 100) })
return true
end
function A.idle(hero, target, now)
if UI.attack:Get() then
local id = Entity.GetIndex(target)
if S.attacking == id and now - (S.attackAt or 0) < 1.0 then return end
A.order(hero, C.orderAttack, Entity.GetAbsOrigin(target), target, nil, true)
S.attacking = id
S.attackAt = now
return
end
if now < S.moveAt then return end
A.order(hero, C.orderMove, Entity.GetAbsOrigin(target), nil, nil, true)
S.moveAt = now + C.moveGap
end
function A.holdLeft(target, now)
local held = false
for _, state in ipairs(C.holdStates) do
if NPC.HasState(target, state) then held = true end
end
local left = 0
for _, mod in ipairs(NPC.GetModifiers(target) or {}) do
local name = Modifier.GetName(mod)
for _, word in ipairs(C.holdWords) do
if name:find(word, 1, true) ~= nil then
local rest = Modifier.GetDieTime(mod) - now
if rest > left then left = rest end
held = true
end
end
end
if not held then return 0 end
return left
end
function A.meteorPoint(target, item, now)
local delay, radius = C.meteorDelay, C.meteorRadius
if C.special ~= nil then
local ok, value = pcall(C.special, item, "max_duration", -1)
if ok and type(value) == "number" and value > 0 then delay = value end
ok, value = pcall(C.special, item, "impact_radius", -1)
if ok and type(value) == "number" and value > 0 then radius = value end
end
delay = IT.itemFall(item, delay)
local reach = radius - NPC.GetHullRadius(target) - C.meteorMargin
local fall = delay + math.max(0, IT.castPoint(item)) + A.settle() * 0.5
local free = math.max(0, fall - A.holdLeft(target, now))
if NPC.GetMoveSpeed(target) * free <= reach then return Entity.GetAbsOrigin(target) end
return nil
end
function A.itemBase(name)
return (name:gsub("^item_", ""):gsub("_custom$", ""))
end
function A.itemLabel(name)
return (A.itemBase(name):gsub("_", " "))
end
function A.itemIcon(name)
local base = A.itemBase(name)
return "panorama/images/items/" .. (ICON_FIX[base] or base) .. "_png.vtex_c"
end
function A.itemSkipped(name)
for _, fragment in ipairs(ITEM_SKIP) do
if name:find(fragment, 1, true) ~= nil then return true end
end
return false
end
function A.has(value, bit)
return type(value) == "number" and bit > 0 and math.floor(value / bit) % 2 >= 1
end
function A.itemKind(item)
local behavior = Ability.GetBehavior(item)
if A.has(behavior, C.bPassive) or A.has(behavior, C.bHidden) or A.has(behavior, C.bToggle) then return nil end
if A.has(behavior, C.bUnit) then
local team = Ability.GetTargetTeam(item)
if A.has(team, C.targetEnemy) then return "enemy" end
if A.has(team, C.targetFriendly) then return "self" end
return nil
end
if A.has(behavior, C.bPoint) then return "point" end
if A.has(behavior, C.bNo) then return "no" end
return nil
end
function A.scanItems(hero)
local labels, ids, signature = {}, {}, ""
for _, slot in ipairs(C.itemSlots) do
local item = NPC.GetItemByIndex(hero, slot)
if item ~= nil then
local name = Ability.GetName(item)
local label = A.itemLabel(name)
if not A.itemSkipped(name) and A.itemKind(item) ~= nil and ids[label] == nil then
labels[#labels + 1] = label
ids[label] = name
signature = signature .. label .. "=" .. name .. ","
end
end
end
return labels, ids, signature
end
function A.refreshItems(hero)
IT.tick()
local labels, ids, signature = A.scanItems(hero)
if signature == S.itemSig then return end
local rank, old, enabled = {}, {}, {}
for i, id in ipairs(UI.items:List()) do
rank[id] = i
old[id] = true
end
for _, id in ipairs(UI.items:ListEnabled()) do enabled[id] = true end
table.sort(labels, function(a, b) return (rank[a] or 1000) < (rank[b] or 1000) end)
local rows, selected = {}, {}
for i, label in ipairs(labels) do
local on = not old[label] or enabled[label] == true
rows[i] = { label, A.itemIcon(ids[label]), on }
if on then selected[#selected + 1] = label end
end
UI.items:Update(rows, true, true)
UI.items:Set(selected)
S.itemSig = signature
S.itemIds = ids
IT.sync(hero, labels, ids, A.itemIcon)
A.log("info", "bane items refreshed", { items = labels, enabled = selected })
end
function A.findItem(hero, label, name)
for _, slot in ipairs(C.itemSlots) do
local item = NPC.GetItemByIndex(hero, slot)
if item ~= nil and Ability.GetName(item) == name then return item end
end
for _, slot in ipairs(C.itemSlots) do
local item = NPC.GetItemByIndex(hero, slot)
if item ~= nil and A.itemLabel(Ability.GetName(item)) == label then return item end
end
return nil
end
function A.isJump(name)
return name:find("blink", 1, true) ~= nil or name:find("fallen_sky", 1, true) ~= nil
end
function A.itemReady(item, hero)
return item ~= nil and Ability.GetLevel(item) > 0 and Ability.IsCastable(item, NPC.GetMana(hero))
end
function A.clampPoint(hero, point, range)
if range <= 0 then return point end
local origin = Entity.GetAbsOrigin(hero)
local dx, dy = point.x - origin.x, point.y - origin.y
local length = math.sqrt(dx * dx + dy * dy)
local cap = math.max(0, range - 25)
if length <= cap or length <= 0 then return point end
local scale = cap / length
return Vector(origin.x + dx * scale, origin.y + dy * scale, point.z)
end
function A.comboReach(hero, ability)
local reach = 0
if ability ~= nil then reach = Ability.GetCastRange(ability) end
for _, label in ipairs(UI.items:ListEnabled()) do
local name = S.itemIds[label]
local item = name ~= nil and not A.isJump(name) and A.findItem(hero, label, name) or nil
if item ~= nil and A.itemReady(item, hero) then
local kind = A.itemKind(item)
if kind == "enemy" or kind == "point" then reach = math.max(reach, Ability.GetCastRange(item) + 75) end
end
end
return reach
end
function A.blinkPoint(hero, target)
local origin = Entity.GetAbsOrigin(hero)
local pos = Entity.GetAbsOrigin(target)
local dx, dy = pos.x - origin.x, pos.y - origin.y
local len = math.max(1, math.sqrt(dx * dx + dy * dy))
local range = NPC.GetAttackRange(hero) + NPC.GetAttackRangeBonus(hero)
local keep = range > 300 and math.max(C.blinkKeep, range - 100) or C.blinkKeep
return Vector(pos.x - dx / len * keep, pos.y - dy / len * keep, pos.z)
end
function A.orderMove(hero, point, now)
if now < S.moveAt then return end
A.order(hero, C.orderMove, point, nil, nil, false)
S.moveAt = now + C.moveGap
end
function A.isMeteor(name)
for _, fragment in ipairs(C.meteorItems) do
if name:find(fragment, 1, true) ~= nil then return true end
end
return false
end
function A.isShiva(name)
return name:find("shivas_guard", 1, true) ~= nil or name:find("gold_shiva", 1, true) ~= nil
end
function A.isHex(name)
return name:find("sheepstick", 1, true) ~= nil or name:find("hex", 1, true) ~= nil
end
function A.shivaHasTarget(hero, item)
local radius = C.shivaRadius
if C.special ~= nil then
local ok, value = pcall(C.special, item, "blast_radius", -1)
if ok and type(value) == "number" and value > 0 then radius = value end
end
for _, enemy in ipairs(Heroes.GetAll()) do
if A.valid(enemy) and not Entity.IsSameTeam(hero, enemy) and not NPC.IsIllusion(enemy)
and A.distance(hero, enemy) <= radius then
return true
end
end
return false
end
function A.isFalcon(name)
return name:find("falcon_blade", 1, true) ~= nil
end
function A.trackFlee(hero, target, now)
if now < S.fleeAt then return end
local distance = A.distance(hero, target)
local pos = Entity.GetAbsOrigin(target)
if S.fleePos == nil then
S.motion = "none"
elseif (pos - S.fleePos):Length2D() <= C.fleeStep then
S.motion = "still"
elseif distance - S.fleeDist > C.fleeStep then
S.motion = "away"
elseif S.fleeDist - distance > C.fleeStep then
S.motion = "toward"
else
S.motion = "side"
end
S.fleeDist, S.fleePos = distance, pos
S.fleeAt = now + C.fleeGap
end
function A.falconPoint(hero, target)
local origin = Entity.GetAbsOrigin(hero)
if S.motion == "still" then return origin end
local pos = Entity.GetAbsOrigin(target)
if S.motion == "away" then return pos end
if S.motion ~= "toward" then return nil end
local dx, dy = origin.x - pos.x, origin.y - pos.y
local len = math.max(1, math.sqrt(dx * dx + dy * dy))
return Vector(origin.x + dx / len * C.falconDash, origin.y + dy / len * C.falconDash, origin.z)
end
function A.sleepLeft(target, now)
local mod = NPC.GetModifier(target, C.sleepMod)
if mod == nil then return 0 end
return math.max(0, Modifier.GetDieTime(mod) - now)
end
function A.castChain(hero, target, e, now)
if e == nil or not UI.spells:Get("spell.e") or NPC.HasModifier(target, C.sleepMod) then return false end
local left = A.holdLeft(target, now)
if left <= 0 or left > math.max(0, IT.castPoint(e)) + A.settle() * 0.5 + C.chainPad then return false end
if not A.castSpell(hero, target, e, "spell.e", now) then return false end
S.sleepUntil = now + math.max(0, IT.castPoint(e)) + A.settle() + C.sleepPad
A.log("info", "bane nightmare chain", { hold = math.floor(left * 100) / 100 })
return true
end
function A.meteorItem(hero)
for _, label in ipairs(UI.items:ListEnabled()) do
local name = S.itemIds[label]
if name ~= nil and A.isMeteor(name) then
local item = A.findItem(hero, label, name)
if A.itemReady(item, hero) then return item end
end
end
return nil
end
function A.castSleep(hero, target, e, now)
if e == nil or not UI.spells:Get("spell.e") or A.holdLeft(target, now) > 0 then return false end
local item = A.meteorItem(hero)
if item == nil then return false end
local range = Ability.GetCastRange(item)
if range > 0 and A.distance(hero, target) > range + 75 then return false end
if not A.castSpell(hero, target, e, "spell.e", now) then return false end
S.sleepUntil = now + math.max(0, IT.castPoint(e)) + A.settle() + C.sleepPad
return true
end
function A.useItems(hero, target, ability, now, meteorOnly)
if now >= S.cycleAt then
S.done = {}
S.cycleAt = now + C.cycleGap
end
local distance = A.distance(hero, target)
for _, label in ipairs(UI.items:ListEnabled()) do
local name = S.itemIds[label]
if name ~= nil and not S.done[name] then
local item = A.findItem(hero, label, name)
if item == nil then
S.done[name] = true
elseif meteorOnly and not A.isMeteor(name) then
elseif not IT.allow(hero, target, name, label) then
elseif A.itemReady(item, hero) then
local kind = A.itemKind(item)
local range = Ability.GetCastRange(item)
local jump = A.isJump(name)
if kind == nil then
S.done[name] = true
elseif jump and distance <= A.comboReach(hero, ability) then
elseif A.isShiva(name) and not A.shivaHasTarget(hero, item) then
elseif A.isMeteor(name) and A.meteorPoint(target, item, now) == nil then
elseif A.isFalcon(name) then
local point = A.falconPoint(hero, target)
if point ~= nil then
Ability.CastPosition(item, point, false, false, true, C.identifier)
S.done[name] = true
S.nextAt = now + math.max(0.08, math.max(0, IT.castPoint(item)) + 0.06)
S.attacking = nil
A.log("info", "bane falcon", { motion = S.motion })
return true
end
elseif (kind == "enemy" or kind == "point") and not jump and range > 0 and distance > range + 75 then
A.orderMove(hero, IT.stopPoint(hero, target, range), now)
return true
else
if kind == "enemy" then
Ability.CastTarget(item, target, false, false, true, C.identifier)
elseif kind == "self" then
Ability.CastTarget(item, hero, false, false, true, C.identifier)
elseif kind == "point" and jump then
Ability.CastPosition(item, A.clampPoint(hero, A.blinkPoint(hero, target), range), false, false, true, C.identifier)
elseif kind == "point" then
Ability.CastPosition(item, A.clampPoint(hero, Entity.GetAbsOrigin(target), range), false, false, true, C.identifier)
else
Ability.CastNoTarget(item, false, false, true, C.identifier)
end
if A.isMeteor(name) then
S.meteorUntil = now + IT.itemFall(item, C.meteorFall)
S.sleepUntil = 0
A.log("info", "bane meteor", { hold = math.floor(A.holdLeft(target, now) * 100) / 100 })
end
S.done[name] = true
local delay = math.max(0.08, math.max(0, IT.castPoint(item)) + 0.06)
if kind == "enemy" and A.isHex(name) then delay = math.max(delay, C.hexWait) end
S.nextAt = now + delay
S.attacking = nil
IT.chainMark(hero, target, name)
A.log("info", "bane combo item", { item = name, kind = kind })
return true
end
end
end
end
return false
end
function A.run(hero, target, now)
if NPC.HasModifier(hero, C.shiftMod) then return end
local q = A.ability(hero, C.qName)
local w = A.ability(hero, C.wName)
local e = A.ability(hero, C.eName)
local r = A.ability(hero, C.rName)
local shift = A.ability(hero, C.shiftName)
if (q ~= nil and Ability.IsInAbilityPhase(q)) or (w ~= nil and Ability.IsInAbilityPhase(w))
or (r ~= nil and Ability.IsInAbilityPhase(r)) or (e ~= nil and Ability.IsInAbilityPhase(e)) or (shift ~= nil and Ability.IsInAbilityPhase(shift)) then return end
if A.gripLocked(hero, r, now, target) then return end
if UI.spells:Get("spell.q") and A.linkenQ(hero, target, q, now) then return end
if IT.breakLinken(hero, target, now) then return end
do local mw = IT.meteorCast(hero, target, now, C.identifier) if mw ~= nil then S.nextAt = now + mw return end end
if A.castDuel(hero, target, now) then return end
if A.castSpell(hero, target, q, "spell.q", now) then return end
if now < S.meteorUntil then return end
if now < S.sleepUntil or A.sleepLeft(target, now) > C.sleepRelease then
if A.useItems(hero, target, nil, now, true) then return end
A.orderMove(hero, Entity.GetAbsOrigin(hero), now)
S.attacking = nil
return
end
if A.castChain(hero, target, e, now) then return end
if A.castSleep(hero, target, e, now) then return end
if A.useItems(hero, target, w or r, now) then return end
local late = UI.sapLate:Get() and r ~= nil and UI.spells:Get("spell.r") and A.ready(r, hero)
local order = IT.spellOrder(UI.spells)
if late then
local ri, wi
for i, id in ipairs(order) do
if id == "spell.r" then ri = i elseif id == "spell.w" then wi = i end
end
if ri ~= nil and wi ~= nil and wi < ri then order[wi], order[ri] = order[ri], order[wi] end
end
for _, id in ipairs(order) do
if id == "spell.w" and A.castSpell(hero, target, w, "spell.w", now) then return end
if id == "spell.r" and A.castSpell(hero, target, r, "spell.r", now) then return end
if id == "spell.shift" and A.castShift(hero, now) then return end
end
A.idle(hero, target, now)
end
function A.update()
local hero = Heroes.GetLocal()
if not A.valid(hero) or Entity.GetUnitName(hero) ~= C.hero then
if S.phase ~= "idle" then A.reset("no bane") end
return
end
local clock = GameRules.GetGameTime()
if clock >= S.itemAt and S.itemError == nil then
S.itemAt = clock + C.itemGap
A.detectLegend(hero)
A.detectDuel(hero)
local ok, err = pcall(A.refreshItems, hero)
if not ok then
S.itemError = tostring(err)
A.log("error", "bane items refresh failed", { error = S.itemError })
end
end
if not UI.enabled:Get() or not UI.key:IsDown() then
if S.phase ~= "idle" then A.reset("key released") end
return
end
if C.inputCaptured ~= nil and C.inputCaptured() then return end
if not A.orderSafe() then return end
if IT.heroDisabled(hero) then return end
local now = GameRules.GetGameTime()
if S.phase == "idle" then
S.target = A.pickTarget(hero)
if S.target == nil then return end
S.phase = "running"
S.startedAt = now
A.log("info", "bane combo started", { target = Entity.GetUnitName(S.target) })
end
local target = S.target
if IT.fogHold(target, now) then
if A.orderMove ~= nil then A.orderMove(hero, Entity.GetAbsOrigin(target), now) end
return
end
if not A.valid(target) or Entity.IsSameTeam(hero, target) or A.distance(hero, target) > UI.range:Get() + 1000 then
A.reset("target lost")
return
end
if now - S.startedAt > C.maxRun then
A.reset("timeout")
return
end
A.trackFlee(hero, target, now)
if now < S.nextAt or NPC.HasModifier(hero, "modifier_item_meteor_hammer_custom_cast") then return end
A.run(hero, target, now)
end
function A.drawError()
local title = S.menuError and localization.Get("panel.menu_failed") or localization.Get("panel.error")
local message = S.menuError or S.error or S.itemError or "unknown"
Render.FilledRect(Vec2(20, 370), Vec2(780, 418), Color(20, 20, 24, 235), 4)
Render.Text(S.font, 14, title, Vec2(30, 377), Color(224, 50, 45, 245))
Render.Text(S.font, 12, message:sub(1, 160), Vec2(30, 397), Color(220, 220, 225, 240))
end
function script.OnScriptsLoaded()
local ok, result = pcall(A.initMenu)
S.ready = ok and result == true
if not S.ready then S.menuError = ok and "initMenu returned false" or tostring(result) end
S.font = Render.LoadFont("MuseoSansEx", 0, 500)
A.log("info", "bane_1x6_combo loaded", { ready = S.ready, error = S.menuError })
end
function script.OnUpdate()
if not S.ready or not Engine.IsInGame() then return end
