end
end
function script.OnPrepareUnitOrders(data)
if not S.ready or data == nil or not S.gripOwn then return true end
local ok, locked = pcall(A.orderLocked, data)
if ok and locked then return false end
return true
end
function script.OnGameEnd()
A.reset("game end")
IT.reset()
S.error = nil
S.itemError = nil
S.itemSig = ""
S.itemIds = {}
S.itemAt = 0
S.gripUntil, S.channelAt, S.castAt, S.gripOwn = 0, -1, {}, false
S.gripSeenUntil, S.gripDie = 0, 0
S.sleepUntil, S.meteorUntil, S.fleeAt, S.fleeDist, S.fleePos, S.motion = 0, 0, 0, 0, nil, "none"
S.legendW, S.legendR, S.legendShown, S.stacks, S.legendE, S.duelAt = false, false, false, 0, nil, 0
end
function A.drawFrame()
if S.menuError ~= nil or S.error ~= nil or S.itemError ~= nil then A.drawError() end
end
function script.OnDraw()
local ok, err = pcall(A.drawFrame)
if not ok and S.error == nil then
S.error = tostring(err)
A.log("error", "bane combo draw failed", { error = S.error })
end
end
return script
end)
