local A = {}
local B = { hits = {}, press = nil, drag = nil, pending = nil, height = nil, info = nil }
function A.api(tbl, name)
return type(tbl) == "table" and type(tbl[name]) == "function" and tbl[name] or nil
end
C.latency = A.api(NetChannel, "GetAvgLatency")
C.cursor = A.api(Input, "GetCursorPos")
C.menuOpen = A.api(Menu, "Opened")
C.castStart = A.api(Ability, "GetCastStartTime")
C.keyDown = A.api(Input, "IsKeyDown")
function A.log(level, message, data)
if type(ai_bridge) ~= "table" or type(ai_bridge.mcp_log) ~= "function" then return end
pcall(ai_bridge.mcp_log, level, message, data)
end
function A.latency()
local ok, value = false, nil
if C.latency ~= nil then ok, value = pcall(C.latency) end
if not ok or type(value) ~= "number" or value < 0 then value = 0.08 end
return math.max(C.minLatency, value)
end
function A.base(name)
return (name:gsub("^item_", ""):gsub("_custom$", ""))
end
function A.buildIndex()
local function add(e)
if S.byName[e.n] == nil then S.byName[e.n] = e end
for _, alias in ipairs(e.al or {}) do
if S.byName[alias] == nil then S.byName[alias] = e end
end
if e.a ~= nil then
for _, t in ipairs(e.a.t) do
if S.thinkers[t] == nil then S.thinkers[t] = e end
end
end
end
for _, list in pairs(CATALOG.heroes) do
for _, e in ipairs(list) do add(e) end
end
for _, e in ipairs(CATALOG.items) do add(e) end
for _, e in ipairs(CATALOG.mobs) do add(e) end
end
function A.isOn(key, default)
local value = S.state[key]
if value == nil then return default end
return value
end
function A.load()
S.state = {}
for part in (UI.store:Get() or ""):gmatch("[^|]+") do
local key, on = part:match("^(.*)=([01])$")
if key ~= nil then S.state[key] = on == "1" end
end
end
function A.save()
local parts = {}
for key, on in pairs(S.state) do parts[#parts + 1] = key .. "=" .. (on and "1" or "0") end
table.sort(parts)
UI.store:Set(table.concat(parts, "|"))
end
function A.toggle(key, default)
S.state[key] = not A.isOn(key, default)
A.save()
end
function A.initMenu()
local side = (type(Enum) == "table" and Enum.GroupSide) or {}
local raw = RawMenu.Create("Scripts", "1x6", "Dodger", "Main")
local section = localization.Wrap(raw, true)
local main = section:Create("menu.main", side.Left)
UI.enabled = main:Switch("menu.enabled", true, "panorama/images/items/falcon_blade_png.vtex_c")
UI.enabled:ToolTip("menu.enabled_tip")
UI.window = main:Switch("menu.window", true)
UI.window:Icon("\u{f2d0}")
UI.lead = main:Slider("menu.lead", 0, 300, 100, "%d")
UI.lead:Icon("\u{f017}")
UI.lead:ToolTip("menu.lead_tip")
UI.channel = main:Switch("menu.channel", true)
UI.channel:Icon("\u{f110}")
UI.heavy = main:Switch("menu.heavy", true, "panorama/images/items/black_king_bar_png.vtex_c")
UI.heavy:ToolTip("menu.heavy_tip")
UI.heavyHp = main:Slider("menu.heavy_hp", 10, 100, 60, "%d")
UI.heavyHp:Icon("\u{f21e}")
UI.step = main:Switch("menu.step", true)
UI.step:Icon("\u{f554}")
UI.step:ToolTip("menu.step_tip")
UI.clone = main:Switch("menu.clone", true, "panorama/images/spellicons/arc_warden_tempest_double_png.vtex_c")
UI.clone:ToolTip("menu.clone_tip")
UI.store = main:Input("dodger_state_v1", "")
UI.store:Visible(false)
UI.order = main:Input("dodger_order_v1", "")
UI.order:Visible(false)
UI.spellOrder = main:Input("dodger_spell_order_v1", "")
UI.spellOrder:Visible(false)
UI.posX = main:Slider("dodger_x_v1", 0, 16384, 60)
UI.posX:Visible(false)
UI.posY = main:Slider("dodger_y_v1", 0, 16384, 180)
UI.posY:Visible(false)
A.buildIndex()
A.load()
A.loadSpellOrders()
return true
end
function A.findItem(hero, key)
for _, slot in ipairs(C.slots) do
local item = NPC.GetItemByIndex(hero, slot)
if item ~= nil and A.base(Ability.GetName(item)) == key then return item end
end
return nil
end
function A.owned(hero, def)
if def.skill ~= nil then return true end
if hero == nil then return false end
local now = A.clock()
local hit = S.ownCache[def.item]
if hit == nil or now - hit.at > C.ownGap then
hit = { at = now, value = A.findItem(hero, def.item) ~= nil }
S.ownCache[def.item] = hit
end
return hit.value
end
function A.ready(hero, ability)
return ability ~= nil and Ability.GetLevel(ability) > 0 and not Ability.IsHidden(ability) and Ability.IsReady(ability)
and Ability.GetCooldown(ability) <= 0 and Ability.IsCastable(ability, NPC.GetMana(hero))
end
function A.has(mask, bit)
return type(mask) == "number" and mask % (bit * 2) >= bit
end
function A.talentOk(hero, ability, need)
if need == nil then return true end
local ok = false
if need == "fast" then
ok = Ability.GetLevel(ability) > 0 and Ability.GetCastPoint(ability) < C.fastCast
elseif need == "w4" then
local level = Ability.GetLevel(ability)
local base = C.fieldCd[math.max(1, math.min(level, #C.fieldCd))]
local pc, length = pcall(Ability.GetCooldownLength, ability)
ok = level > 0 and A.has(Ability.GetBehavior(ability), C.bPoint) and pc and type(length) == "number" and length > 0
and length <= base - C.fieldCdCut
end
local key = Ability.GetName(ability) .. ":" .. tostring(Entity.GetIndex(hero))
if S.talentSeen[key] ~= ok then
S.talentSeen[key] = ok
A.log("info", "dodger talent skill", { skill = Ability.GetName(ability), usable = ok, cast = Ability.GetCastPoint(ability) })
end
return ok
end
function A.ownSkills(hero)
local list = {}
for _, s in ipairs(CATALOG.skills) do
local ability = NPC.GetAbility(hero, s.n)
if ability ~= nil and A.talentOk(hero, ability, s.need) then list[#list + 1] = { def = s, handle = ability } end
end
return list
end
function A.away(hero, dir, dist)
local origin = Entity.GetAbsOrigin(hero)
local len = math.sqrt(dir.x * dir.x + dir.y * dir.y)
if len < 0.001 then return origin end
return Vector(origin.x + dir.x / len * dist, origin.y + dir.y / len * dist, origin.z)
end
function A.escapeDir(hero, threat)
local origin = Entity.GetAbsOrigin(hero)
if threat.kind == "line" then
local d = threat.dir
local rel = origin - threat.from
local side = d.x * rel.y - d.y * rel.x
if side >= 0 then return Vector(-d.y, d.x, 0) end
return Vector(d.y, -d.x, 0)
end
local from = threat.center or threat.from
if from == nil then return Entity.GetRotation(hero):GetForward() end
return origin - from
end
function A.loadSpellOrders()
S.spellOrders = {}
for part in (UI.spellOrder:Get() or ""):gmatch("[^|]+") do
local spell, keys = part:match("^([^=]+)=(.*)$")
if spell ~= nil then
local list = {}
for key in keys:gmatch("[^,]+") do list[#list + 1] = key end
S.spellOrders[spell] = list
end
end
end
function A.reorderSpell(spell, from, to)
local keys = {}
for _, def in ipairs(A.defs(Heroes.GetLocal(), spell)) do
if def.key ~= from then keys[#keys + 1] = def.key end
end
local at = #keys + 1
for index, key in ipairs(keys) do
if key == to then at = index end
end
table.insert(keys, at, from)
S.spellOrders[spell] = keys
local parts = {}
for name, list in pairs(S.spellOrders) do parts[#parts + 1] = name .. "=" .. table.concat(list, ",") end
table.sort(parts)
UI.spellOrder:Set(table.concat(parts, "|"))
end
function A.defs(hero, spell)
local list = {}
for _, tool in ipairs(CATALOG.tools) do
local base = A.base(tool.n)
list[#list + 1] = { key = "tool:" .. base, item = base, mode = tool.m, i = tool.i, t = tool.t, r = tool.r }
end
if hero ~= nil then
for _, s in ipairs(A.ownSkills(hero)) do
list[#list + 1] = { key = "skill:" .. s.def.n, skill = s.def, handle = s.handle, i = s.def.i, s = s.def.s, t = s.def.t, r = s.def.r }
end
end
local rank = {}
for index, key in ipairs(A.orderKeys()) do rank[key] = index end
for index, def in ipairs(list) do def.rank = rank[def.key] or (1000 + index) end
if spell ~= nil and S.spellOrders[spell] ~= nil then
local own = {}
for index, key in ipairs(S.spellOrders[spell]) do own[key] = index end
for _, def in ipairs(list) do def.rank = own[def.key] or (2000 + def.rank) end
end
table.sort(list, function(a, b) return a.rank < b.rank end)
return list
end
function A.orderKeys()
local keys = {}
for key in (UI.order:Get() or ""):gmatch("[^,]+") do keys[#keys + 1] = key end
return keys
end
function A.reorder(from, to)
local keys = {}
for _, def in ipairs(A.defs(Heroes.GetLocal())) do
if def.key ~= from then keys[#keys + 1] = def.key end
end
local at = #keys + 1
for index, key in ipairs(keys) do
if key == to then at = index end
end
table.insert(keys, at, from)
local seen = {}
for _, key in ipairs(keys) do seen[key] = true end
for _, key in ipairs(A.orderKeys()) do
if not seen[key] then keys[#keys + 1] = key end
end
UI.order:Set(table.concat(keys, ","))
end
function A.applies(def, kind, e, threat, hero)
if def.item == "lotus_orb" then return false end
if def.item == "manta" then return kind == "proj" or kind == "cast" end
if def.item == "falcon_blade" then
if kind == "cast" then return false end
if kind ~= "aoe" then return true end
local radius = threat ~= nil and threat.radius or e.a.r
local dist = (threat ~= nil and hero ~= nil) and (Entity.GetAbsOrigin(hero) - threat.center):Length2D() or 0
return radius + (hero ~= nil and NPC.GetHullRadius(hero) or 24) + C.aoeMargin - dist <= C.dash
end
if def.mode == "self" then return true end
if def.mode == "bkb" then return not C.pierce[e ~= nil and e.n or ""] end
if def.mode == "blink" then
if kind == "cast" then return false end
return kind ~= "proj" or hero == nil or not NPC.HasModifier(hero, C.blinkBreak)
end
if def.mode == "push" then return A.pushEscapes(kind, e, threat, hero) end
if def.skill ~= nil then return def.skill.k == "self" or kind ~= "cast" end
return false
end
function A.pushEscapes(kind, e, threat, hero)
if kind ~= "aoe" and kind ~= "line" then return false end
if threat == nil or hero == nil then return true end
local origin = Entity.GetAbsOrigin(hero)
local fp = Entity.GetForwardPosition(hero, C.push)
local hull = NPC.GetHullRadius(hero)
if kind == "aoe" then
local radius = threat.radius or (e.a ~= nil and e.a.r) or 0
return (fp - threat.center):Length2D() > radius + hull + C.aoeMargin
end
local d, from = threat.dir, threat.from
local len = math.sqrt(d.x * d.x + d.y * d.y)
if len < 0.001 then return false end
local rx, ry = fp.x - from.x, fp.y - from.y
local lateral = math.abs(d.x * ry - d.y * rx) / len
local width = e.l ~= nil and e.l.w or 0
return lateral > width / 2 + hull + C.lineMargin and (origin - fp):Length2D() > 0
end
function A.live(unit)
if unit == nil then return false end
local ok, alive = pcall(Entity.IsAlive, unit)
if not ok or not alive then return false end
local okHp, hp = pcall(Entity.GetHealth, unit)
if okHp and type(hp) == "number" and hp <= 0 then return false end
if unit ~= Heroes.GetLocal() then
local okMod, has = pcall(NPC.HasModifier, unit, C.doubleMod)
return okMod and has == true
end
return true
end
A.clock = type(os) == "table" and type(os.clock) == "function" and os.clock or GlobalVars.GetCurTime
function A.units(hero)
local list = { hero }
if not UI.clone:Get() then return list end
local name = NPC.GetUnitName(hero)
for _, unit in ipairs(Heroes.GetAll() or {}) do
if unit ~= nil and unit ~= hero and NPC.GetUnitName(unit) == name and A.live(unit) then
list[#list + 1] = unit
end
end
return list
end
function A.handle(unit, def)
if def.skill ~= nil then return NPC.GetAbility(unit, def.skill.n) end
return A.findItem(unit, def.item)
end
function A.heavy(def)
return def.mode == "bkb" or def.mode == "self"
end
function A.worth(hero, e)
if not UI.heavy:Get() or e == nil then return true end
local info = DANGER[e.n]
local level = info ~= nil and info.d or 2
if level >= 2 then return true end
local hp, max = Entity.GetHealth(hero), math.max(1, Entity.GetMaxHealth(hero))
if level == 1 and hp / max * 100 <= UI.heavyHp:Get() then return true end
return info ~= nil and info.dm ~= nil and info.dm >= hp * 0.6
end
function A.toolLead(def, handle)
if not A.heavy(def) then return nil end
local cp = handle ~= nil and math.max(0, Ability.GetCastPoint(handle)) or 0
return A.latency() + cp + C.instantLead + UI.lead:Get() / 1000
end
function A.sidestep(hero, threat, left)
if not UI.step:Get() or (threat.kind ~= "line" and threat.kind ~= "aoe") then return false end
local e = S.byName[threat.name]
if e == nil then return false end
local origin = Entity.GetAbsOrigin(hero)
local hull = NPC.GetHullRadius(hero)
local need, dir
if threat.kind == "aoe" then
local rel = origin - threat.center
need = threat.radius + hull + C.aoeMargin + C.stepMargin - rel:Length2D()
dir = rel:Length2D() < 1 and Entity.GetRotation(hero):GetForward() or rel
else
local d = threat.dir
local rel = origin - threat.from
local side = d.x * rel.y - d.y * rel.x
need = (e.l ~= nil and e.l.w or 0) / 2 + hull + C.lineMargin + C.stepMargin - math.abs(side)
dir = side >= 0 and Vector(-d.y, d.x, 0) or Vector(d.y, -d.x, 0)
end
if need <= 0 or NPC.GetMoveSpeed(hero) * math.max(0, left) < need * 0.8 then return false end
local player = Players.GetLocal()
if player == nil then return false end
Player.PrepareUnitOrders(player, C.orderMove, nil, A.away(hero, dir, need + 40), nil, C.issuer, hero, false, false, false, false, C.identifier)
return true
end
function A.react(hero, threat, now)
if not A.live(hero) then return nil, "dead" end
if UI.channel:Get() and NPC.IsChannellingAbility(hero) then return "channel" end
local e = S.byName[threat.name]
local why = {}
local left = threat.at - now
for _, def in ipairs(A.defs(hero, threat.name)) do
local short = def.item or (def.skill and def.skill.n) or def.key
if not A.isOn(def.key, true) or not A.isOn("use:" .. threat.name .. ":" .. def.key, true) then
why[#why + 1] = short .. " off"
elseif not A.applies(def, threat.kind, e, threat, hero) then
why[#why + 1] = short .. " n/a"
elseif A.heavy(def) and not A.worth(hero, e) then
why[#why + 1] = short .. " saved"
else
local handle = A.handle(hero, def)
if handle == nil then
why[#why + 1] = short .. " missing"
elseif not A.ready(hero, handle) then
why[#why + 1] = string.format("%s cd %.1f", short, Ability.GetCooldown(handle))
end
if A.ready(hero, handle) then
local need = A.toolLead(def, handle)
if need ~= nil and left > need then return nil, short .. " wait", true end
if def.mode == "self" or def.mode == "push" then
Ability.CastTarget(handle, hero, false, false, true, C.identifier)
elseif def.mode == "bkb" or def.item == "manta" or (def.skill ~= nil and def.skill.k == "self") then
Ability.CastNoTarget(handle, false, false, true, C.identifier)
elseif def.skill ~= nil and def.skill.k == "vector" then
local dir = A.escapeDir(hero, threat)
local range = Ability.GetCastRange(handle)
local start = A.away(hero, dir, math.min(range > 0 and range or C.blink, C.blink))
local len = math.max(0.001, math.sqrt(dir.x * dir.x + dir.y * dir.y))
local finish = Vector(start.x + dir.x / len * C.vectorTail, start.y + dir.y / len * C.vectorTail, start.z)
local player = Players.GetLocal()
if player ~= nil then
Player.PrepareUnitOrders(player, C.orderVector, nil, finish, handle, C.issuer, hero, false, false, false, false, C.identifier)
Player.PrepareUnitOrders(player, C.orderCastPosition, nil, start, handle, C.issuer, hero, false, false, false, false, C.identifier)
end
elseif def.mode == "blink" then
local range = Ability.GetCastRange(handle)
local dist = math.max(C.dash, (range > 0 and range or C.blink) - C.blinkEdge)
Ability.CastPosition(handle, A.away(hero, A.escapeDir(hero, threat), dist), false, false, true, C.identifier)
else
local dist = C.dash
if def.skill ~= nil then
local range = Ability.GetCastRange(handle)
dist = math.min(range > 0 and range or C.blink, C.blink)
end
Ability.CastPosition(handle, A.away(hero, A.escapeDir(hero, threat), dist), false, false, true, C.identifier)
end
return def.key
end
end
end
if A.sidestep(hero, threat, left) then return "sidestep" end
return nil, table.concat(why, ", ")
end
function A.lotusFirst(hero, e)
for _, def in ipairs(A.defs(hero, e.n)) do
if def.item == "lotus_orb" then return true end
if A.isOn(def.key, true) and A.isOn("use:" .. e.n .. ":" .. def.key, true) then
local handle = A.handle(hero, def)
if A.ready(hero, handle) then
for _, kind in ipairs(A.kinds(e)) do
if A.applies(def, kind, e, nil, nil) then return false end
end
end
end
end
return true
end
function A.tryLotus(hero, now, name)
if not A.live(hero) then return end
local e = S.byName[name]
if e ~= nil and not A.lotusFirst(hero, e) then return end
local id = Entity.GetIndex(hero)
if now < (S.lotusUntil[id] or 0) or not A.isOn("tool:lotus_orb", true) or not A.isOn("use:" .. name .. ":tool:lotus_orb", true)
or NPC.HasModifier(hero, C.lotusMod) then return end
if UI.channel:Get() and NPC.IsChannellingAbility(hero) then return end
local item = A.findItem(hero, "lotus_orb")
if not A.ready(hero, item) then return end
Ability.CastNoTarget(item, false, false, true, C.identifier)
S.lotusUntil[id] = now + 0.5
S.recent[id .. ":" .. name] = now
A.log("info", "dodger lotus", { spell = name, clone = hero ~= Heroes.GetLocal() })
end
function A.enemyAbilities(unit, now)
local id = Entity.GetIndex(unit)
local entry = S.cache[id]
if entry ~= nil and now < entry.at then return entry.list end
local list = {}
for i = 0, C.abilitySlots - 1 do
local ability = NPC.GetAbilityByIndex(unit, i)
if ability ~= nil then
local e = S.byName[Ability.GetName(ability)]
if e ~= nil and (e.u or e.l) then list[#list + 1] = { handle = ability, e = e } end
end
end
for _, slot in ipairs(C.slots) do
local item = NPC.GetItemByIndex(unit, slot)
if item ~= nil then
local e = S.byName[Ability.GetName(item)]
if e ~= nil and (e.u or e.l) then list[#list + 1] = { handle = item, e = e } end
end
end
S.cache[id] = { at = now + C.scanGap, list = list }
return list
end
function A.inPhase(handle)
local ok, phase = pcall(Ability.IsInAbilityPhase, handle)
return ok and phase == true
end
function A.execAt(ability, now)
local cp = math.max(0, Ability.GetCastPoint(ability))
local t = nil
if C.castStart ~= nil then
local ok, value = pcall(C.castStart, ability)
if ok and type(value) == "number" and value > 0 then t = value end
end
if t == nil then return now + cp end
if t <= now then t = t + cp end
return math.max(t, now)
end
function A.cancelled(threat)
if threat.handle == nil or A.inPhase(threat.handle) then return false end
local ok, cd = pcall(Ability.GetCooldown, threat.handle)
return ok and type(cd) == "number" and cd <= 0
end
function A.addThreat(threat)
local now = GameRules.GetGameTime()
local key = Entity.GetIndex(threat.unit) .. ":" .. threat.name
if S.recent[key] ~= nil and now - S.recent[key] < 0.8 then return end
S.recent[key] = now
S.threats[#S.threats + 1] = threat
A.log("info", "dodger threat", { kind = threat.kind, spell = threat.name, in_ms = math.floor((threat.at - now) * 1000), clone = threat.unit ~= Heroes.GetLocal() })
end
function A.checkCast(hero, unit, item, now)
local e, ability = item.e, item.handle
if not A.isOn(e.n, e.on) then return end
local key = Entity.GetIndex(unit) .. ":" .. Entity.GetIndex(hero) .. ":" .. e.n
local at = A.execAt(ability, now)
local mark = key .. ":" .. math.floor(at * 10)
if S.seen[mark] then return end
local origin = Entity.GetAbsOrigin(unit)
local rel = Entity.GetAbsOrigin(hero) - origin
local dist = rel:Length2D()
local forward = Entity.GetRotation(unit):GetForward():Normalized()
if e.u then
if dist <= Ability.GetCastRange(ability) + 300 and (dist < 1 or forward:Dot2D(rel:Normalized()) >= C.facing) then
S.seen[mark] = true
S.seenCount = S.seenCount + 1
A.tryLotus(hero, now, e.n)
if not e.p then A.addThreat({ kind = "cast", name = e.n, at = at, from = origin, unit = hero, handle = ability }) end
end
return
end
local along = forward.x * rel.x + forward.y * rel.y
local lateral = math.abs(forward.x * rel.y - forward.y * rel.x)
local hull = NPC.GetHullRadius(hero)
if along > 0 and along <= e.l.d + hull and lateral <= e.l.w / 2 + hull + C.lineMargin then
S.seen[mark] = true
S.seenCount = S.seenCount + 1
A.addThreat({ kind = "line", name = e.n, at = at + math.max(0, along - hull) / e.l.s, from = origin, dir = forward, unit = hero, handle = ability })
end
end
function A.scanCasts(hero, now, mine)
if S.seenCount > 300 then S.seen, S.seenCount = {}, 0 end
local origin = Entity.GetAbsOrigin(hero)
for _, unit in ipairs(Heroes.GetAll()) do
if unit ~= nil and Entity.IsAlive(unit) and not Entity.IsDormant(unit) and not Entity.IsSameTeam(hero, unit)
and (Entity.GetAbsOrigin(unit) - origin):Length2D() <= C.heroRadius then
for _, item in ipairs(A.enemyAbilities(unit, now)) do
if A.inPhase(item.handle) then
for _, me in ipairs(mine) do A.checkCast(me, unit, item, now) end
end
end
end
end
if now >= S.mobAt then
S.mobAt = now + C.mobGap
local list = {}
local ok, mobs = pcall(NPCs.InRadius, origin, C.mobRadius, Entity.GetTeamNum(hero), C.teamEnemy, true, true)
if ok and mobs ~= nil then
for _, unit in ipairs(mobs) do
if unit ~= nil and not NPC.IsHero(unit) and Entity.IsAlive(unit) and #A.enemyAbilities(unit, now) > 0 then list[#list + 1] = unit end
end
end
S.mobs = list
for id, entry in pairs(S.cache) do
if now - entry.at > C.cacheKeep then S.cache[id] = nil end
end
end
for _, unit in ipairs(S.mobs) do
local okAlive, alive = pcall(Entity.IsAlive, unit)
if okAlive and alive then
for _, item in ipairs(A.enemyAbilities(unit, now)) do
if A.inPhase(item.handle) then
for _, me in ipairs(mine) do A.checkCast(me, unit, item, now) end
end
end
end
end
end
function A.onProjectile(data)
if data == nil or data.isAttack == true or data.source == nil or data.target == nil then return end
local main = Heroes.GetLocal()
if main == nil or Entity.IsSameTeam(main, data.source) then return end
local hero = nil
for _, me in ipairs(A.units(main)) do
if data.target == me and A.live(me) then hero = me end
end
if hero == nil then return end
local speed = data.moveSpeed
if type(speed) ~= "number" or speed <= 0 then speed = data.original_move_speed end
if type(speed) ~= "number" or speed <= 0 then return end
local name = data.ability ~= nil and Ability.GetName(data.ability) or data.name or "unknown"
local e = S.byName[name]
if e == nil then
if not S.unlisted[name] then
S.unlisted[name] = true
A.log("info", "dodger unlisted projectile", { spell = name })
end
return
end
if not A.isOn(e.n, e.on) then return end
local now = GameRules.GetGameTime()
local from = Entity.GetAbsOrigin(data.source)
local dist = (Entity.GetAbsOrigin(hero) - from):Length2D() - NPC.GetHullRadius(hero) - C.hitPad
A.addThreat({ kind = "proj", name = e.n, at = now + math.max(0, dist) / speed, from = from, unit = hero })
end
function A.onModifier(entity, modifier)
local e = S.thinkers[Modifier.GetName(modifier)]
if e == nil or not A.isOn(e.n, e.on) then return end
local main = Heroes.GetLocal()
if main == nil or Entity.IsSameTeam(main, entity) then return end
local center = Entity.GetAbsOrigin(entity)
for _, hero in ipairs(A.units(main)) do
if A.live(hero) and (Entity.GetAbsOrigin(hero) - center):Length2D() <= e.a.r + NPC.GetHullRadius(hero) + C.aoeMargin then
A.addThreat({ kind = "aoe", name = e.n, at = GameRules.GetGameTime() + e.a.d, center = center, radius = e.a.r, unit = hero })
end
end
end
function A.update()
local now = GameRules.GetGameTime()
if now < S.tickAt then return end
S.tickAt = now + C.tick
local hero = Heroes.GetLocal()
if hero == nil or not A.live(hero) then
S.threats = {}
return
end
local mine = {}
for _, me in ipairs(A.units(hero)) do
if A.live(me) then mine[#mine + 1] = me end
end
A.scanCasts(hero, now, mine)
if #S.threats == 0 then return end
local lead = A.latency() + C.minLead + UI.lead:Get() / 1000
local keep = {}
for _, threat in ipairs(S.threats) do
local left = threat.at - now
local unit = threat.unit
if left > -C.late and left < C.maxFlight and unit ~= nil and A.live(unit) then
local id = Entity.GetIndex(unit)
if not threat.done and (left <= lead or threat.kind == "proj") then
threat.done = true
if A.cancelled(threat) then
A.log("info", "dodger skipped", { spell = threat.name, reason = "wind-up cancelled" })
elseif NPC.IsStunned(unit) then
A.log("info", "dodger skipped", { spell = threat.name, reason = "stunned" })
elseif now < (S.orderAt[id] or 0) then
elseif now < (S.dodgeUntil[id] or 0) then
A.log("info", "dodger skipped", { spell = threat.name, reason = "already dodged" })
else
local used, why, wait = A.react(unit, threat, now)
if wait then
threat.done = false
else
if used ~= nil and used ~= "channel" then S.orderAt[id] = now + C.orderGap end
if used ~= nil and used ~= "channel" then S.dodgeUntil[id] = now + 0.6 end
A.log("info", used ~= nil and used ~= "channel" and "dodger dodge" or "dodger skipped", {
spell = threat.name, kind = threat.kind, tool = used or "none", left_ms = math.floor(left * 1000), why = why,
})
end
end
end
if not threat.done then keep[#keep + 1] = threat end
end
end
S.threats = keep
end
function B.image(path)
local handle = S.images[path]
if handle == nil then
local ok, value = pcall(Render.LoadImage, path)
handle = ok and value or false
S.images[path] = handle
end
return handle or nil
end
function B.svg(key)
local id = "svg:" .. key
local handle = S.images[id]
if handle == nil then
local data = "data:image/png;base64," .. (CATALOG.svg[key] or "")
local svg = '<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="48" height="48" viewBox="0 0 48 48"><image x="0" y="0" width="48" height="48" href="'
.. data .. '" xlink:href="' .. data .. '"/></svg>'
local ok, value = pcall(Render.LoadSvgString, svg, Vec2(48, 48), id)
handle = ok and value or false
S.images[id] = handle
end
return handle or nil
end
function B.entryImage(e)
if e.s ~= nil then
local handle = B.svg(e.s)
if handle ~= nil then return handle end
end
if e.i == nil or e.i == "" then return nil end
return B.image(e.i)
end
function B.name(e)
local ru = localization.Get("win.lang") == "ru"
return (ru and e.r or e.t) or e.n
end
function B.visible()
if not S.ready or not UI.enabled:Get() or not UI.window:Get() then return false end
return C.menuOpen ~= nil and C.menuOpen() == true
end
function B.region(x, y, w, h, kind, value, tip)
B.hits[#B.hits + 1] = { x = x, y = y, w = w, h = h, kind = kind, value = value, tip = tip }
end
function B.hit(x, y)
for i = #B.hits, 1, -1 do
local h = B.hits[i]
if x >= h.x and y >= h.y and x < h.x + h.w and y < h.y + h.h then return h end
end
return nil
end
function B.style(name, fallback)
if not S.styleOk then return fallback end
local ok, color = pcall(Menu.Style, name)
if not ok or color == nil or color.r == nil then return fallback end
return color
end
function B.theme()
local frame = GlobalVars.GetFrameCount()
if S.themeFrame == frame and S.theme ~= nil then return S.theme end
S.themeFrame = frame
S.theme = {
body = B.style("main_background", Color(24, 24, 27, 235)),
plate = B.style("group_background", Color(37, 37, 42, 235)),
border = B.style("outline", Color(48, 48, 55, 180)),
accent = B.style("primary", Color(214, 58, 50, 250)),
text = B.style("primary_widgets_text", Color(238, 238, 242, 250)),
muted = B.style("third_tab_text", Color(146, 146, 156, 210)),
enabled = B.style("multiselect_item_selected", Color(63, 191, 95, 245)),
disabled = B.style("multiselect_item", Color(224, 50, 45, 245)),
shadow = Color(0, 0, 0, 130),
}
return S.theme
end
function B.rect(x, y, w, h, color, round)
Render.FilledRect(Vec2(x, y), Vec2(x + w, y + h), color, round or 4)
end
function B.panel(x, y, w, h, round)
local th = B.theme()
local a, b = Vec2(x, y), Vec2(x + w, y + h)
if S.hasFx then
Render.Shadow(a, b, th.shadow, 12, round)
Render.Blur(a, b, 3, 1, round)
end
Render.FilledRect(a, b, th.body, round)
Render.Rect(a, b, th.border, round, C.drawNone, 1)
end
function B.text(text, x, y, size, color)
Render.Text(S.font, size or 12, text, Vec2(x, y), color or B.theme().text)
end
function B.glyph(glyph, cx, cy, size, color)
local ts = Render.TextSize(S.iconFont, size, glyph)
Render.Text(S.iconFont, size, glyph, Vec2(math.floor(cx - ts.x / 2 + 0.5), math.floor(cy - ts.y / 2 + 0.5)), color)
end
function B.icon(x, y, size, e, key, default, kind)
local on = A.isOn(key, default)
local image = B.entryImage(e)
local pos, far = Vec2(x, y), Vec2(x + size, y + size)
local th = B.theme()
B.rect(x, y, size, size, th.plate, 4)
if image ~= nil then
Render.Image(image, pos, Vec2(size, size), Color(255, 255, 255, on and 255 or 150), 4)
end
if not on then Render.FilledRect(pos, far, Color(0, 0, 0, 120), 4) end
Render.Rect(pos, far, on and th.enabled or th.disabled, 4, C.drawNone, 2)
if e.lg then Render.FilledRect(Vec2(x + size - 8, y), Vec2(x + size, y + 8), Color(255, 160, 30, 255), 2) end
if e.badge ~= nil then
B.rect(x, y + size - 12, 12, 12, B.theme().body, 3)
B.text(tostring(e.badge), x + 2, y + size - 13, 10)
end
local tip = B.name(e) .. (e.lg and (" (" .. localization.Get("win.legend") .. ")") or "")
B.region(x, y, size, size, kind or "toggle", { key = key, default = default, e = e }, tip)
end
function B.section(x, y, id, title)
local w = C.width - C.pad * 2
local th = B.theme()
B.rect(x + C.pad, y, w, 22, th.plate, 5)
local ts = Render.TextSize(S.font, 13, title)
B.text(title, x + (C.width - ts.x) / 2, y + 4, 13)
local closed = A.isOn("sec:" .. id, false)
B.glyph(closed and "\u{f078}" or "\u{f077}", x + C.width - C.pad - 12, y + 11, 11, th.muted)
B.region(x + C.pad, y, w, 22, "section", id)
return y + 26, closed
end
function B.grid(x, y, entries, kind)
local cols = math.floor((C.width - C.pad * 2 + C.gap) / (C.icon + C.gap))
local ox = x + C.pad + math.floor((C.width - C.pad * 2 - (cols * (C.icon + C.gap) - C.gap)) / 2)
for i, e in ipairs(entries) do
local cx = ox + ((i - 1) % cols) * (C.icon + C.gap)
local cy = y + math.floor((i - 1) / cols) * (C.icon + C.gap)
B.icon(cx, cy, C.icon, e, e.n, e.on, kind)
end
if #entries == 0 then return y end
return y + math.ceil(#entries / cols) * (C.icon + C.gap) + 4
end
function A.enemyHas(heroName, abilityName)
local me = Heroes.GetLocal()
for _, unit in ipairs(Heroes.GetAll()) do
if unit ~= nil and me ~= nil and not Entity.IsSameTeam(me, unit) and NPC.GetUnitName(unit) == heroName then
local ability = NPC.GetAbility(unit, abilityName)
if ability ~= nil and Ability.GetLevel(ability) > 0 and not Ability.IsHidden(ability) then return true end
end
end
return false
end
function B.enemyHeroes()
local me = Heroes.GetLocal()
local list, seen = {}, {}
if me == nil then return list end
for _, unit in ipairs(Heroes.GetAll()) do
if unit ~= nil and not Entity.IsSameTeam(me, unit) then
local name = NPC.GetUnitName(unit)
if not seen[name] and CATALOG.heroes[name] ~= nil then
seen[name] = true
list[#list + 1] = name
end
end
end
table.sort(list)
return list
end
function B.layout(x, y)
local hero = Heroes.GetLocal()
local closed
y, closed = B.section(x, y, "general", localization.Get("win.general"))
if not closed then
local entries = {}
for _, def in ipairs(A.defs(hero)) do
if A.owned(hero, def) then
entries[#entries + 1] = { n = def.key, on = true, i = def.i, s = def.s, t = def.t, r = def.r, tool = def, badge = #entries + 1 }
end
end
y = B.grid(x, y, entries, "tool")
end
y, closed = B.section(x, y, "heroes", localization.Get("win.heroes"))
if not closed then
local heroes = B.enemyHeroes()
if #heroes == 0 then
B.text(localization.Get("win.empty"), x + C.pad + 4, y, 11, B.theme().muted)
y = y + 20
end
local cols = math.floor((C.width - C.pad * 2 - C.portrait - C.gap + C.gap) / (C.icon + C.gap))
for _, name in ipairs(heroes) do
local list = {}
for _, e in ipairs(CATALOG.heroes[name]) do
if not e.lg or A.enemyHas(name, e.n) then list[#list + 1] = e end
end
local portrait = B.image("panorama/images/heroes/" .. name .. "_png.vtex_c")
if portrait ~= nil then
Render.Image(portrait, Vec2(x + C.pad, y), Vec2(C.portrait, C.icon), Color(255, 255, 255, 255), 3)
end
local ix = x + C.pad + C.portrait + C.gap
for i, e in ipairs(list) do
local cx = ix + ((i - 1) % cols) * (C.icon + C.gap)
local cy = y + math.floor((i - 1) / cols) * (C.icon + C.gap)
B.icon(cx, cy, C.icon, e, e.n, e.on)
end
y = y + math.max(1, math.ceil(#list / cols)) * (C.icon + C.gap) + 4
end
end
y, closed = B.section(x, y, "items", localization.Get("win.items"))
if not closed then y = B.grid(x, y, CATALOG.items) end
y, closed = B.section(x, y, "mobs", localization.Get("win.mobs"))
if not closed then y = B.grid(x, y, CATALOG.mobs) end
return y
end
function A.kinds(e)
local list = {}
if e.u and not e.p then list[#list + 1] = "cast" end
if e.p then list[#list + 1] = "proj" end
if e.l then list[#list + 1] = "line" end
if e.a then list[#list + 1] = "aoe" end
return list
end
function A.dodgers(e)
local hero = Heroes.GetLocal()
local rows = {}
for _, def in ipairs(A.defs(hero, e.n)) do
local ok, note = false, nil
if def.item == "lotus_orb" then
ok, note = e.u == true, "win.at_cast"
else
for _, kind in ipairs(A.kinds(e)) do
if A.applies(def, kind, e, nil, nil) then ok = true end
end
if not ok and def.item == "falcon_blade" and e.a ~= nil then ok, note = true, "win.too_big" end
end
if ok and A.owned(hero, def) then
rows[#rows + 1] = { e = def, key = "use:" .. e.n .. ":" .. def.key, note = note,
dim = note == "win.too_big" or not A.isOn(def.key, true) }
end
end
return rows
end
function B.drawInfo()
local info = B.info
if info == nil then return end
local e = info.e
local kinds = {}
for _, k in ipairs(A.kinds(e)) do kinds[#kinds + 1] = localization.Get("win.k_" .. k) end
local rows = A.dodgers(e)
local title, sub = B.name(e), table.concat(kinds, ", ")
local size, gap, pad = 36, 6, 14
local count = #rows
local strip = count > 0 and count * size + (count - 1) * gap or 0
local w = math.max(190, Render.TextSize(S.font, 14, title).x + pad * 2, Render.TextSize(S.font, 11, sub).x + pad * 2, strip + pad * 2)
local h = count > 0 and 116 or 88
local screen = Render.ScreenSize()
local x, y = math.min(info.x + 12, screen.x - w - 4), math.min(info.y + 8, screen.y - h - 4)
local th = B.theme()
B.panel(x, y, w, h, 6)
B.region(x, y, w, h, "info")
local tw = Render.TextSize(S.font, 14, title)
B.text(title, x + (w - tw.x) / 2, y + 8, 14)
local sw = Render.TextSize(S.font, 11, sub)
B.text(sub, x + (w - sw.x) / 2, y + 27, 11, th.muted)
Render.FilledRect(Vec2(x + pad, y + 46), Vec2(x + w - pad, y + 47), th.border, 0)
if count == 0 then
local text = localization.Get("win.none")
local ns = Render.TextSize(S.font, 13, text)
B.text(text, x + (w - ns.x) / 2, y + 58, 13, th.muted)
return
end
local ox = x + (w - strip) / 2
for i, row in ipairs(rows) do
local ix, iy = ox + (i - 1) * (size + gap), y + 58
local use = A.isOn(row.key, true)
local faded = row.dim or not use
local image = B.entryImage(row.e)
if image ~= nil then
Render.Image(image, Vec2(ix, iy), Vec2(size, size), Color(255, 255, 255, faded and 110 or 255), 4)
else
B.rect(ix, iy, size, size, th.plate, 4)
end
Render.Rect(Vec2(ix, iy), Vec2(ix + size, iy + size), use and th.enabled or th.disabled, 4, C.drawNone, 2)
B.rect(ix, iy + size - 13, 13, 13, th.body, 3)
B.text(tostring(i), ix + 3, iy + size - 14, 10)
local tip = B.name(row.e) .. (row.note ~= nil and (" (" .. localization.Get(row.note) .. ")") or "")
B.region(ix, iy, size, size, "use", { key = row.key, default = true, def = row.e.key, spell = e.n, e = row.e }, tip)
end
local hint = localization.Get("win.use_tip")
local hs = Render.TextSize(S.font, 10, hint)
B.text(hint, x + (w - hs.x) / 2, y + h - 17, 10, th.muted)
end
function B.position(screen, height)
local x, y = UI.posX:Get(), UI.posY:Get()
if B.drag ~= nil and C.cursor ~= nil then
local mx, my = C.cursor()
x, y = mx - B.drag.dx, my - B.drag.dy
end
x = math.max(0, math.min(x, screen.x - C.width))
y = math.max(0, math.min(y, screen.y - math.min(height, screen.y)))
if B.drag ~= nil then B.drag.x, B.drag.y = x, y end
return x, y
end
function B.action(action)
if action.kind == "toggle" or action.kind == "use" then
A.toggle(action.value.key, action.value.default)
S.cache = {}
elseif action.kind == "reorder" then
A.reorder(action.from, action.to)
elseif action.kind == "reorderSpell" then
A.reorderSpell(action.spell, action.from, action.to)
elseif action.kind == "section" then
A.toggle("sec:" .. action.value, false)
elseif action.kind == "close" then
UI.window:Set(false)
end
end
function B.draw()
if not B.visible() then
B.hits, B.drag, B.press, B.info = {}, nil, nil, nil
return
end
if B.pending ~= nil then
local pending = B.pending
B.pending = nil
B.action(pending)
end
local screen = Render.ScreenSize()
local height = B.height or 300
local x, y = B.position(screen, height)
B.hits = {}
local th = B.theme()
B.panel(x, y, C.width, height, 6)
B.region(x, y, C.width, height, "background")
B.rect(x, y, C.width, C.head, th.plate, 6)
Render.FilledRect(Vec2(x + 10, y + C.head - 2), Vec2(x + 34, y + C.head), th.accent, 1)
B.region(x, y, C.width - 30, C.head, "drag")
B.text(localization.Get("win.title"), x + 10, y + 5, 14)
B.glyph("\u{f00d}", x + C.width - 16, y + C.head / 2, 13, th.muted)
B.region(x + C.width - 30, y, 30, C.head, "close")
local bottom = B.layout(x, y + C.head + 8)
bottom = bottom + 4
B.height = bottom - y + 6
B.drawInfo()
local press = B.press
if press ~= nil and C.keyDown ~= nil and GameRules.GetGameTime() - (press.at or 0) > 0.3 and not C.keyDown(C.mouse) then
B.press, press = nil, nil
end
if press ~= nil and (press.kind == "tool" or press.kind == "use") and C.cursor ~= nil then
local mx, my = C.cursor()
if math.abs(mx - press.x) + math.abs(my - press.y) > 6 then
local image = B.entryImage(press.e)
if image ~= nil then Render.Image(image, Vec2(mx - 15, my - 15), Vec2(30, 30), Color(255, 255, 255, 190), 3) end
end
end
if C.cursor ~= nil and (press == nil or (press.kind ~= "tool" and press.kind ~= "use")) then
local mx, my = C.cursor()
local hit = B.hit(mx, my)
if hit ~= nil and hit.tip ~= nil and (B.info == nil or hit.kind == "use") then
local on = A.isOn(hit.value.key, hit.value.default)
local text = hit.tip .. " — " .. localization.Get(on and "win.on" or "win.off")
if hit.kind == "tool" or hit.kind == "use" then
text = text .. "  |  " .. localization.Get("win.drag")
elseif hit.value.e ~= nil then
text = text .. "  |  " .. localization.Get("win.rmb")
end
local ts = Render.TextSize(S.font, 12, text)
B.panel(mx + 14, my + 10, ts.x + 12, ts.y + 8, 4)
B.text(text, mx + 20, my + 14, 12)
end
end
end
function B.key(data)
if C.cursor == nil then return true end
if data.key == C.mouse2 then
if not B.visible() then return true end
local mx, my = C.cursor()
local hit = B.hit(mx, my)
if hit == nil then
if data.event == C.down then B.info = nil end
return true
end
if data.event == C.down then
if hit.kind == "toggle" and hit.value.e ~= nil then
B.info = { e = hit.value.e, x = mx, y = my }
elseif hit.kind ~= "info" then
B.info = nil
end
end
return false
end
if data.key ~= C.mouse then return true end
if data.event == C.up and B.press ~= nil then
local press = B.press
B.press = nil
if press.kind == "tool" then
local mx, my = C.cursor()
local hit = B.hit(mx, my)
if math.abs(mx - press.x) + math.abs(my - press.y) <= 6 then
B.pending = { kind = "toggle", value = { key = press.key, default = true } }
elseif hit ~= nil and hit.kind == "tool" and hit.value.key ~= press.key then
B.pending = { kind = "reorder", from = press.key, to = hit.value.key }
end
return false
end
if press.kind == "use" then
local mx, my = C.cursor()
local hit = B.hit(mx, my)
if math.abs(mx - press.x) + math.abs(my - press.y) <= 6 then
B.pending = { kind = "toggle", value = { key = press.key, default = true } }
elseif hit ~= nil and hit.kind == "use" and hit.value.spell == press.spell and hit.value.def ~= press.def then
B.pending = { kind = "reorderSpell", spell = press.spell, from = press.def, to = hit.value.def }
end
return false
end
if B.drag ~= nil then
UI.posX:Set(math.floor(B.drag.x or UI.posX:Get()))
UI.posY:Set(math.floor(B.drag.y or UI.posY:Get()))
B.drag = nil
return false
end
return false
end
if not B.visible() then return true end
local mx, my = C.cursor()
local hit = B.hit(mx, my)
if hit == nil then
if data.event == C.down then B.info = nil end
return true
end
if data.event == C.down then
if B.press ~= nil then return false end
if hit.kind ~= "info" and hit.kind ~= "use" then B.info = nil end
local now = GameRules.GetGameTime()
B.press = { kind = hit.kind, at = now }
if hit.kind == "tool" then
B.press = { kind = "tool", key = hit.value.key, e = hit.value.e, x = mx, y = my, at = now }
elseif hit.kind == "use" then
B.press = { kind = "use", key = hit.value.key, def = hit.value.def, spell = hit.value.spell, e = hit.value.e, x = mx, y = my, at = now }
elseif hit.kind == "toggle" or hit.kind == "section" or hit.kind == "close" then
B.pending = hit
end
if hit.kind == "drag" then
local px, py = UI.posX:Get(), UI.posY:Get()
B.drag = { dx = mx - px, dy = my - py, x = px, y = py }
end
end
return false
end
function A.drawError()
local title = S.menuError and localization.Get("panel.menu_failed") or localization.Get("panel.error")
local message = S.menuError or S.error or "unknown"
Render.FilledRect(Vec2(20, 610), Vec2(780, 658), Color(20, 20, 24, 235), 4)
Render.Text(S.font, 14, title, Vec2(30, 617), Color(224, 50, 45, 245))
Render.Text(S.font, 12, message:sub(1, 160), Vec2(30, 637), Color(220, 220, 225, 240))
end
function script.OnScriptsLoaded()
local ok, result = pcall(A.initMenu)
S.ready = ok and result == true
