local RawMenu = X6P.menu(Menu)
local C = {
identifier = "defense_1x6",
slots = { 0, 1, 2, 3, 4, 5, 16 },
dispels = {
{ "guardian_greaves", true },
{ "lotus_orb", true },
{ "manta", true },
{ "disperser", true },
{ "satanic", false },
{ "black_king_bar", false },
},
alias = { satanic = "alchemist_gold_satanic" },
rowsGap = 1.0,
lockout = 1.0,
hexState = 6,
tick = 0.03,
verify = 0.35,
bUnit = 8,
}
local UI = {}
local S = {
ready = false,
menuError = nil,
error = nil,
font = nil,
tickAt = 0,
dispelAt = 0,
ignored = {},
check = nil,
modMap = {},
off = {},
rows = nil,
rowsSig = "",
rowsAt = 0,
applied = false,
listed = {},
}
local A = {}
function A.log(level, message, data)
if type(ai_bridge) ~= "table" or type(ai_bridge.mcp_log) ~= "function" then return end
pcall(ai_bridge.mcp_log, level, message, data)
end
function A.has(value, bit)
return math.floor(value / bit) % 2 == 1
end
function A.base(name)
return (name:gsub("^item_", ""):gsub("_custom$", ""))
end
function A.label(key)
return (key:gsub("_", " "))
end
function A.initMenu()
local side = (type(Enum) == "table" and Enum.GroupSide) or {}
local raw = RawMenu.Create("Scripts", "1x6", "Defense", "Main")
local section = localization.Wrap(raw, true)
local dispel = section:Create("menu.dispel", side.Left)
UI.dispel = dispel:Switch("menu.dispel_on", true, "panorama/images/items/guardian_greaves_png.vtex_c")
UI.dispel:ToolTip("menu.dispel_tip")
UI.channel = dispel:Switch("menu.channel", true)
UI.channel:Icon("\u{f110}")
local rows = {}
for i, pair in ipairs(C.dispels) do
rows[i] = { A.label(pair[1]), "panorama/images/items/" .. pair[1] .. "_png.vtex_c", pair[2] }
end
UI.items = dispel:MultiSelect("menu.items", rows, true)
UI.items:ToolTip("menu.items_tip")
UI.items:DragAllowed(true)
UI.conds = dispel:MultiSelect("menu.conds", {}, true)
UI.conds:ToolTip("menu.conds_tip")
UI.offStore = dispel:Input("defense_off_v1", "")
UI.offStore:Visible(false)
for key in (UI.offStore:Get() or ""):gmatch("[^,]+") do S.off[key] = true end
local groups = { DISPEL.items }
for _, list in pairs(DISPEL.heroes) do groups[#groups + 1] = list end
for _, list in ipairs(groups) do
for _, e in ipairs(list) do
for _, mod in ipairs(e.m) do
S.modMap[mod] = S.modMap[mod] or {}
table.insert(S.modMap[mod], e.n)
end
end
end
UI.minTime = dispel:Slider("menu.min_time", 0, 3000, 800, "%d")
UI.minTime:Icon("\u{f017}")
UI.minTime:ToolTip("menu.min_time_tip")
return true
end
function A.findItem(hero, key)
for _, slot in ipairs(C.slots) do
local item = NPC.GetItemByIndex(hero, slot)
local base = item ~= nil and A.base(Ability.GetName(item)) or nil
if base ~= nil and (base == key or base == C.alias[key]) then return item end
end
return nil
end
function A.itemReady(hero, item)
return item ~= nil and Ability.GetLevel(item) > 0 and Ability.IsReady(item) and Ability.GetCooldown(item) <= 0
and Ability.IsCastable(item, NPC.GetMana(hero))
end
function A.busy(hero)
if NPC.IsStunned(hero) or NPC.HasState(hero, C.hexState) then return true end
return UI.channel:Get() and NPC.IsChannellingAbility(hero)
end
function A.enemyHas(unit, name)
local ability = NPC.GetAbility(unit, name)
return ability ~= nil and Ability.GetLevel(ability) > 0 and not Ability.IsHidden(ability)
end
function A.buildRows(hero, now)
if now < S.rowsAt then return end
S.rowsAt = now + C.rowsGap
local rows, sig, seen, units = {}, {}, {}, {}
for _, unit in ipairs(Heroes.GetAll()) do
if unit ~= nil and not Entity.IsSameTeam(hero, unit) then
local name = NPC.GetUnitName(unit)
if units[name] == nil then units[name] = unit end
end
end
local names = {}
for name in pairs(units) do names[#names + 1] = name end
table.sort(names)
for _, name in ipairs(names) do
for _, e in ipairs(DISPEL.heroes[name] or {}) do
if not seen[e.n] and (not e.lg or A.enemyHas(units[name], e.n)) then
seen[e.n] = true
rows[#rows + 1] = { e.n, e.i, not S.off[e.n] }
sig[#sig + 1] = e.n
end
end
end
for _, e in ipairs(DISPEL.items) do
rows[#rows + 1] = { e.n, e.i, not S.off[e.n] }
sig[#sig + 1] = e.n
end
local text = table.concat(sig, ",")
if text ~= S.rowsSig then
S.rowsSig = text
S.rows = rows
S.applied = false
end
end
function A.readToggles()
if not S.applied then return end
local changed = false
for _, id in ipairs(UI.conds:List() or {}) do
local off = not UI.conds:Get(id)
if (S.off[id] == true) ~= off then
S.off[id] = off or nil
changed = true
end
end
if changed then
local keys = {}
for key in pairs(S.off) do keys[#keys + 1] = key end
table.sort(keys)
UI.offStore:Set(table.concat(keys, ","))
end
end
function A.applyRows()
if S.rows == nil or S.applied then return end
local selected = {}
for _, row in ipairs(S.rows) do
if row[3] then selected[#selected + 1] = row[1] end
end
UI.conds:Update(S.rows, true, true)
UI.conds:Set(selected)
S.listed = {}
for _, row in ipairs(S.rows) do S.listed[row[1]] = true end
S.applied = true
end
function A.debuffs(hero, now)
local found, longest = {}, 0
for _, mod in ipairs(NPC.GetModifiers(hero) or {}) do
local name = Modifier.GetName(mod)
local sources = S.modMap[name]
local caster = Modifier.GetCaster(mod)
if sources ~= nil and not S.ignored[name] and (caster == nil or not Entity.IsSameTeam(hero, caster)) then
local wanted = false
for _, ability in ipairs(sources) do
if S.listed[ability] and not S.off[ability] then wanted = true end
end
if wanted then
local left = Modifier.GetDuration(mod) > 0 and Modifier.GetDieTime(mod) - now or 99
found[#found + 1] = name
if left > longest then longest = left end
end
end
end
return found, longest
end
function A.verify(hero, now)
local check = S.check
if check == nil or now < check.at then return end
S.check = nil
for _, name in ipairs(check.names) do
if NPC.HasModifier(hero, name) then
S.ignored[name] = true
A.log("info", "defense dispel ignored", { modifier = name, item = check.item })
end
end
end
function A.dispel(hero, now)
A.verify(hero, now)
if now < S.dispelAt or S.check ~= nil or A.busy(hero) then return end
local names, longest = A.debuffs(hero, now)
if #names == 0 or longest * 1000 < UI.minTime:Get() then return end
for _, label in ipairs(UI.items:ListEnabled()) do
local key = label:gsub(" ", "_")
local item = A.findItem(hero, key)
if A.itemReady(hero, item) then
if A.has(Ability.GetBehavior(item), C.bUnit) then
Ability.CastTarget(item, hero, false, false, true, C.identifier)
else
Ability.CastNoTarget(item, false, false, true, C.identifier)
end
S.dispelAt = now + C.lockout
S.check = { at = now + C.verify, names = names, item = key }
A.log("info", "defense dispel cast", { item = key, debuffs = names, left = math.floor(longest * 100) / 100 })
return
end
end
end
function A.update()
local now = GameRules.GetGameTime()
if now < S.tickAt then return end
S.tickAt = now + C.tick
local hero = Heroes.GetLocal()
if hero == nil then return end
A.buildRows(hero, now)
A.readToggles()
if not Entity.IsAlive(hero) then return end
if UI.dispel:Get() then A.dispel(hero, now) end
end
function A.drawError()
local title = S.menuError and localization.Get("panel.menu_failed") or localization.Get("panel.error")
local message = S.menuError or S.error or "unknown"
Render.FilledRect(Vec2(20, 550), Vec2(780, 598), Color(20, 20, 24, 235), 4)
Render.Text(S.font, 14, title, Vec2(30, 557), Color(224, 50, 45, 245))
Render.Text(S.font, 12, message:sub(1, 160), Vec2(30, 577), Color(220, 220, 225, 240))
end
function script.OnScriptsLoaded()
local ok, result = pcall(A.initMenu)
S.ready = ok and result == true
if not S.ready then S.menuError = ok and "initMenu returned false" or tostring(result) end
S.font = Render.LoadFont("MuseoSansEx", 0, 500)
A.log("info", "defense_1x6 loaded", { ready = S.ready, error = S.menuError })
end
function script.OnGameEnd()
S.ignored = {}
S.check = nil
S.rowsSig, S.rowsAt = "", 0
end
function script.OnUpdate()
if not S.ready or S.error ~= nil or not Engine.IsInGame() then return end
local ok, err = pcall(A.update)
if not ok then
S.error = tostring(err)
A.log("error", "defense update failed", { error = S.error })
end
end
function script.OnDraw()
if S.ready and S.error == nil then
local ok, err = pcall(A.applyRows)
if not ok then S.error = tostring(err) end
end
if S.menuError == nil and S.error == nil then return end
pcall(A.drawError)
end
return script
end)
if ok and type(result) == "table" then
modules[#modules + 1] = { name = "defense_1x6", script = result, loadMs = pack_clock and (pack_clock() - started) * 1000 or 0 }
else
failed_load["defense_1x6"] = tostring(result)
end
end
