local UI = {}
if type(X6P) == "table" then
X6P.iconData = { ability = C.abilityIcons, svg = C.svgIcons, custom = C.customIcons, item = C.itemIcons, svgSize = C.svgSize }
end
local COLOR = {
white = Color(255, 255, 255, 255),
black = Color(0, 0, 0, 220),
blank = Color(40, 40, 46, 230),
unlearned = Color(0, 0, 0, 170),
mana = Color(30, 80, 220, 110),
cooling = Color(0, 0, 0, 140),
stripReady = Color(70, 200, 90, 230),
stripOff = Color(90, 90, 96, 200),
stripCooling = Color(220, 60, 50, 230),
