}
local A = {}
function A.api(tbl, name)
return type(tbl) == "table" and type(tbl[name]) == "function" and tbl[name] or nil
end
C.cursorPos = A.api(Input, "GetCursorPos")
C.isInnate = A.api(Ability, "IsInnate")
C.manaEnough = A.api(Ability, "IsOwnersManaEnough")
function A.log(level, message, data)
if type(ai_bridge) ~= "table" or type(ai_bridge.mcp_log) ~= "function" then return end
pcall(ai_bridge.mcp_log, level, message, data)
end
function A.initMenu()
local side = (type(Enum) == "table" and Enum.GroupSide) or {}
local raw = RawMenu.Create("Scripts", "1x6", "Hero Overlay", "Main")
local section = localization.Wrap(raw, true)
UI.targets = {
enemies = localization.Get("menu.enemies"),
allies = localization.Get("menu.allies"),
self = localization.Get("menu.self"),
}
local targets = { UI.targets.enemies, UI.targets.allies, UI.targets.self }
local items = section:Create("menu.items", side.Left)
UI.itemsOn = items:Switch("menu.enabled", true)
UI.itemsOn:Icon("\u{f00c}")
UI.itemsShow = items:MultiCombo("menu.show", targets, { UI.targets.enemies })
UI.itemsShow:Icon("\u{f234}")
UI.itemsAlign = items:Combo("menu.align", { "menu.right", "menu.left", "menu.top", "menu.bottom" }, 0)
UI.itemsLayout = items:Combo("menu.layout", { "menu.layout_row", "menu.layout_grid", "menu.layout_column", "menu.layout_grid2" }, 0)
UI.itemsLayout:Icon("\u{f00a}")
UI.itemsAlign:Icon("\u{f036}")
local abilities = section:Create("menu.abilities", side.Right)
UI.abilitiesOn = abilities:Switch("menu.enabled", true)
UI.abilitiesOn:Icon("\u{f00c}")
UI.minimized = abilities:Switch("menu.minimized", false)
UI.minimized:Icon("\u{f141}")
UI.minimized:ToolTip("menu.minimized_tip")
UI.abilitiesShow = abilities:MultiCombo("menu.show", targets, { UI.targets.enemies })
UI.abilitiesShow:Icon("\u{f234}")
UI.abilitiesAlign = abilities:Combo("menu.align", { "menu.top", "menu.bottom" }, 0)
UI.abilitiesAlign:Icon("\u{f036}")
local legend = section:Create("menu.legend", side.Right)
UI.legendOn = legend:Switch("menu.enabled", true)
UI.legendOn:Icon("\u{f00c}")
UI.legendOn:ToolTip("menu.legend_tip")
UI.legendShow = legend:MultiCombo("menu.show", targets, { UI.targets.enemies })
UI.legendShow:Icon("\u{f234}")
local custom = section:Create("menu.custom", side.Left)
UI.hover = custom:Slider("menu.hover", 50, 400, 195, "%dpx")
UI.hover:Icon("\u{f065}")
UI.size = custom:Slider("menu.size", 16, 40, 24, "%dpx")
UI.size:Icon("\u{f00a}")
UI.itemSize = custom:Slider("menu.item_size", 14, 40, 20, "%dpx")
UI.itemSize:Icon("\u{f00a}")
UI.offset = custom:Slider("menu.offset", -60, 60, 0, "%dpx")
UI.offset:Icon("\u{f338}")
UI.offset:ToolTip("menu.offset_tip")
return true
end
function A.image(path)
local handle = S.images[path]
if handle == nil then
local ok, value = pcall(Render.LoadImage, path)
handle = ok and value or false
S.images[path] = handle
end
return handle or nil
end
function A.abilityIcon(ability, hero)
local icon = C.abilityIcons[Ability.GetName(ability)]
if icon == nil then return nil end
if icon == false then
return "panorama/images/heroes/icons/" .. NPC.GetUnitName(hero) .. "_png.vtex_c"
end
return "panorama/images/spellicons/" .. icon .. "_png.vtex_c"
end
function A.ready(path, handle)
local state = S.loaded[path]
if state ~= nil then return state end
if handle == nil then
S.loaded[path] = false
return false
end
local ok, size = pcall(Render.ImageSize, handle)
if ok and size ~= nil and size.x > 0 then
S.loaded[path] = true
A.log("info", "hero overlay custom icon loaded", { path = path })
return true
end
local now = GameRules.GetGameTime()
S.probeAt[path] = S.probeAt[path] or now
if now - S.probeAt[path] > C.probeTime then
S.loaded[path] = false
A.log("info", "hero overlay custom icon failed", { path = path })
end
return false
end
function A.svg(name)
local key = "svg:" .. name
local handle = S.images[key]
if handle == nil then
local size = C.svgSize
local data = "data:image/png;base64," .. C.svgIcons[name]
local svg = '<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="' .. size
.. '" height="' .. size .. '" viewBox="0 0 ' .. size .. " " .. size .. '"><image x="0" y="0" width="' .. size
.. '" height="' .. size .. '" href="' .. data .. '" xlink:href="' .. data .. '"/></svg>'
local ok, value = pcall(Render.LoadSvgString, svg, Vec2(size, size), key)
handle = ok and value or false
S.images[key] = handle
if not ok then A.log("info", "hero overlay svg icon error", { name = name, error = tostring(value) }) end
end
return handle or nil, key
end
function A.pick(entry)
if entry.svg ~= nil then
local handle, key = A.svg(entry.svg)
if A.ready(key, handle) then return handle end
end
if entry.custom ~= nil then
local handle = A.image(entry.custom)
if A.ready(entry.custom, handle) then return handle end
end
return A.image(entry.icon)
end
function A.itemIcon(item)
local name = Ability.GetName(item)
local icon = C.itemIcons[name]
if icon == false then return C.fallbackItem end
if icon == nil then icon = name:gsub("^item_", ""):gsub("_custom$", "") end
return "panorama/images/items/" .. icon .. "_png.vtex_c"
end
function A.skipAbility(ability)
if Ability.IsHidden(ability) then return true end
if C.isInnate ~= nil and C.isInnate(ability) then return true end
local name = Ability.GetName(ability)
for _, fragment in ipairs(C.skipAbility) do
if name:find(fragment, 1, true) ~= nil then return true end
end
return false
end
function A.scan(hero)
local entry = { abilities = {}, items = {} }
for i = 0, C.abilitySlots - 1 do
local ability = NPC.GetAbilityByIndex(hero, i)
local icon = ability ~= nil and not A.skipAbility(ability) and A.abilityIcon(ability, hero) or nil
if icon ~= nil and #entry.abilities < C.maxAbilities then
local name = Ability.GetName(ability)
entry.abilities[#entry.abilities + 1] = { handle = ability, icon = icon, custom = C.customIcons[name], svg = C.svgIcons[name] and name or nil }
end
end
for _, slot in ipairs(C.itemSlots) do
local item = NPC.GetItemByIndex(hero, slot)
if item ~= nil then
entry.items[#entry.items + 1] = { handle = item, icon = A.itemIcon(item), custom = C.customIcons[Ability.GetName(item)] }
end
end
return entry
end
function A.legendStacks(hero, entry, now)
if entry.legendAt ~= nil and now < entry.legendAt then return entry.legend end
entry.legendAt = now + C.legendGap
local list = {}
for _, mod in ipairs(NPC.GetModifiers(hero) or {}) do
local name = Modifier.GetName(mod)
local count = Modifier.GetStackCount(mod)
if count > 0 and name:find(C.legendWord, 1, true) ~= nil then
local ability = Modifier.GetAbility(mod)
local key = ability ~= nil and Ability.GetName(ability) or ""
local icon = ability ~= nil and A.abilityIcon(ability, hero) or nil
if icon == nil then icon = "panorama/images/heroes/icons/" .. NPC.GetUnitName(hero) .. "_png.vtex_c" end
list[#list + 1] = { icon = icon, custom = C.customIcons[key], svg = C.svgIcons[key] and key or nil, count = count }
if not S.legendSeen[name] then
S.legendSeen[name] = true
A.log("info", "hero overlay legend stack", { hero = NPC.GetUnitName(hero), modifier = name, stacks = count, ability = key })
end
end
end
entry.legend = list
return list
end
function A.drawLegend(list, sp, size, edge)
local n = #list
if n == 0 then return end
local width = n * size + (n - 1) * C.gap
local x, y = sp.x - width / 2, edge - C.gap - size
local fontSize = math.floor(size * 0.6)
for i, entry in ipairs(list) do
local ix = x + (i - 1) * (size + C.gap)
local pos = Vec2(ix, y)
local image = A.pick(entry)
if image ~= nil then
Render.Image(image, pos, Vec2(size, size), COLOR.white, 3)
else
Render.FilledRect(pos, Vec2(ix + size, y + size), COLOR.blank, 3)
end
Render.FilledRect(pos, Vec2(ix + size, y + size), COLOR.legendShade, 3)
local text = tostring(entry.count)
local ts = Render.TextSize(S.font, fontSize, text)
local tp = Vec2(ix + (size - ts.x) / 2, y + (size - ts.y) / 2)
Render.Text(S.font, fontSize, text, Vec2(tp.x + 1, tp.y + 1), COLOR.legendShadow)
Render.Text(S.font, fontSize, text, tp, COLOR.legendText)
Render.Rect(pos, Vec2(ix + size, y + size), COLOR.legendEdge, 3)
end
end
function A.shows(combo, hero, me)
if hero == me then return combo:Get(UI.targets.self) end
if Entity.IsSameTeam(hero, me) then return combo:Get(UI.targets.allies) end
return combo:Get(UI.targets.enemies)
end
function A.cooldownText(cd)
if cd >= 1 then return tostring(math.ceil(cd)) end
return string.format("%.1f", cd)
end
function A.sample(entry)
if entry.sampleAt ~= nil and S.now < entry.sampleAt then return end
entry.sampleAt = S.now + C.sampleGap
local handle = entry.handle
local level = Ability.GetLevel(handle)
local cd = Ability.GetCooldown(handle)
entry.level, entry.cd = level, cd
entry.noMana = level > 0 and cd <= 0 and C.manaEnough ~= nil and not C.manaEnough(handle)
entry.picked = A.pick(entry)
entry.text = cd > 0 and A.cooldownText(cd) or nil
end
function A.drawIcon(entry, x, y, size, withText)
A.sample(entry)
local image = entry.picked
local far = Vec2(x + size, y + size)
local pos = Vec2(x, y)
if image ~= nil then
Render.Image(image, pos, Vec2(size, size), COLOR.white, 3)
if entry.level <= 0 then Render.FilledRect(pos, far, COLOR.unlearned, 3) end
else
Render.FilledRect(pos, far, COLOR.blank, 3)
end
if entry.noMana then Render.FilledRect(pos, far, COLOR.mana, 3) end
if entry.cd > 0 then
Render.FilledRect(pos, far, COLOR.cooling, 3)
local text = entry.text
if withText and text ~= nil then
local fontSize = math.floor(size * 0.55)
if entry.tsText ~= text or entry.tsFont ~= fontSize then
entry.ts, entry.tsText, entry.tsFont = Render.TextSize(S.font, fontSize, text), text, fontSize
end
Render.Text(S.font, fontSize, text, Vec2(x + (size - entry.ts.x) / 2, y + (size - entry.ts.y) / 2), COLOR.white)
end
end
Render.Rect(pos, far, COLOR.black, 3)
end
function A.drawStrip(entry, x, y, width, height)
A.sample(entry)
local color = COLOR.stripReady
if entry.level <= 0 then
color = COLOR.stripOff
elseif entry.cd > 0 then
color = COLOR.stripCooling
elseif entry.noMana then
color = COLOR.stripMana
end
local pos, far = Vec2(x, y), Vec2(x + width, y + height)
Render.FilledRect(pos, far, color, 2)
Render.Rect(pos, far, COLOR.black, 2)
end
function A.hovered(sp)
if C.cursorPos == nil then return false end
local cx, cy = C.cursorPos()
if type(cx) ~= "number" or type(cy) ~= "number" then return false end
local dx, dy = cx - sp.x, cy - sp.y
return dx * dx + dy * dy <= UI.hover:Get() * UI.hover:Get()
end
function A.drawAbilities(list, sp, size, lift)
local n = #list
if n == 0 then return nil end
local top = UI.abilitiesAlign:Get() == 0
local minimized = UI.minimized:Get() and not A.hovered(sp)
local height = minimized and math.max(4, math.floor(size * C.stripHeight)) or size
local width = n * size + (n - 1) * C.gap
local x = sp.x - width / 2
local y = top and (sp.y - lift - height) or (sp.y + C.barDrop + UI.offset:Get())
for i, entry in ipairs(list) do
local ix = x + (i - 1) * (size + C.gap)
local ok = pcall(minimized and A.drawStrip or A.drawIcon, entry, ix, y, size, minimized and height or true)
if not ok then S.stale = true end
end
return top and y or (y + height)
end
function A.drawItems(list, sp, size, lift, abilityEdge)
local n = #list
if n == 0 then return end
local align = UI.itemsAlign:Get()
local layout = UI.itemsLayout:Get()
local cols = layout == 1 and math.min(3, n) or layout == 2 and 1 or layout == 3 and math.min(2, n) or n
local rows = math.ceil(n / cols)
local width = cols * size + (cols - 1) * C.gap
local height = rows * size + (rows - 1) * C.gap
local x, y
local mid = sp.y - C.barMid + UI.offset:Get() - height / 2
if align == 0 then
x, y = sp.x + C.barRight, mid
elseif align == 1 then
x, y = sp.x - C.barLeft - width, mid
elseif align == 2 then
local edge = (abilityEdge ~= nil and UI.abilitiesAlign:Get() == 0) and abilityEdge or (sp.y - lift)
x, y = sp.x - width / 2, edge - C.gap - height
else
local edge = (abilityEdge ~= nil and UI.abilitiesAlign:Get() == 1) and abilityEdge or (sp.y + C.barDrop + UI.offset:Get())
x, y = sp.x - width / 2, edge + C.gap
end
for i, entry in ipairs(list) do
local col, row = (i - 1) % cols, math.floor((i - 1) / cols)
if not pcall(A.drawIcon, entry, x + col * (size + C.gap), y + row * (size + C.gap), size, true) then S.stale = true end
end
end
function A.draw()
local me = Heroes.GetLocal()
if me == nil then return end
local now = GameRules.GetGameTime()
S.now = now
local rescan = now >= S.scanAt
if rescan then S.scanAt = now + C.scanGap end
local abilitiesOn, itemsOn, legendOn = UI.abilitiesOn:Get(), UI.itemsOn:Get(), UI.legendOn:Get()
if not (abilitiesOn or itemsOn or legendOn) then return end
local size = UI.size:Get()
local itemSize = UI.itemSize:Get()
local lift = C.barLift - UI.offset:Get()
for _, hero in ipairs(Heroes.GetAll()) do
if hero ~= nil and Entity.IsAlive(hero) and not Entity.IsDormant(hero) and not NPC.IsIllusion(hero) then
local showAbilities = abilitiesOn and A.shows(UI.abilitiesShow, hero, me)
local showItems = itemsOn and A.shows(UI.itemsShow, hero, me)
local showLegend = legendOn and A.shows(UI.legendShow, hero, me)
if showAbilities or showItems or showLegend then
local id = Entity.GetIndex(hero)
local entry = S.cache[id]
if entry == nil or rescan or entry.stale then
entry = A.scan(hero)
S.cache[id] = entry
end
local origin = Entity.GetAbsOrigin(hero)
local sp, visible = Render.WorldToScreen(origin + Vector(0, 0, NPC.GetHealthBarOffset(hero)))
if visible then
S.stale = false
local edge = showAbilities and A.drawAbilities(entry.abilities, sp, size, lift) or nil
if showItems then A.drawItems(entry.items, sp, itemSize, lift, edge) end
if showLegend then
local top = (edge ~= nil and UI.abilitiesAlign:Get() == 0) and edge or (sp.y - lift)
if not pcall(A.drawLegend, A.legendStacks(hero, entry, now), sp, size, top) then S.stale = true end
end
entry.stale = S.stale
end
end
end
end
end
function A.drawError()
local title = S.menuError and localization.Get("panel.menu_failed") or localization.Get("panel.error")
local message = S.menuError or S.error or "unknown"
Render.FilledRect(Vec2(20, 490), Vec2(780, 538), Color(20, 20, 24, 235), 4)
Render.Text(S.font, 14, title, Vec2(30, 497), Color(224, 50, 45, 245))
Render.Text(S.font, 12, message:sub(1, 160), Vec2(30, 517), Color(220, 220, 225, 240))
end
function script.OnScriptsLoaded()
local ok, result = pcall(A.initMenu)
S.ready = ok and result == true
if not S.ready then S.menuError = ok and "initMenu returned false" or tostring(result) end
S.font = Render.LoadFont("MuseoSansEx", 0, 700)
A.log("info", "hero_overlay_1x6 loaded", { ready = S.ready, error = S.menuError })
end
function script.OnGameEnd()
S.cache = {}
S.scanAt = 0
S.error = nil
end
function A.drawFrame()
if S.ready and S.error == nil and Engine.IsInGame() then A.draw() end
if S.menuError ~= nil or S.error ~= nil then A.drawError() end
end
function script.OnDraw()
local ok, err = pcall(A.drawFrame)
if not ok and S.error == nil then
S.error = tostring(err)
A.log("error", "hero overlay draw failed", { error = S.error })
end
end
return script
end)
if ok and type(result) == "table" then
modules[#modules + 1] = { name = "hero_overlay_1x6", script = result, loadMs = pack_clock and (pack_clock() - started) * 1000 or 0 }
else
failed_load["hero_overlay_1x6"] = tostring(result)
end
end
