UI.cloneKey = main:Bind("menu.clone_key", C.keyV, "panorama/images/spellicons/arc_warden_tempest_double_png.vtex_c")
UI.cloneKey:ToolTip("menu.clone_key_tip")
UI.key:ToolTip("menu.key_tip")
A.spellRows = {
{ "spell.flux", "panorama/images/spellicons/arc_warden_flux_png.vtex_c", true },
{ "spell.field", "panorama/images/spellicons/arc_warden_magnetic_field_png.vtex_c", true },
{ "spell.spark", "panorama/images/spellicons/arc_warden_spark_wraith_png.vtex_c", true },
{ "spell.double", "panorama/images/spellicons/arc_warden_tempest_double_png.vtex_c", true },
}
UI.saveSpells = main:Input("menu.save_spells", "")
UI.saveSpells:Visible(false)
UI.spells = main:MultiSelect("menu.spells", IT.orderedRows(A.spellRows, UI.saveSpells), true)
UI.spells:DragAllowed(true)
IT.register({ C.hero }, UI.spells, UI.saveSpells, A.spellRows)
UI.spells:ToolTip("menu.spells_tip")
UI.legendary = main:Switch("spell.legendary_auto", true, "panorama/images/heroes/icons/npc_dota_hero_arc_warden_png.vtex_c")
UI.legendary:ToolTip("menu.spells_tip")
UI.blink = main:Switch("menu.blink", true, "panorama/images/items/blink_png.vtex_c")
UI.bkb = main:Switch("menu.bkb", false, "panorama/images/items/black_king_bar_png.vtex_c")
UI.range = main:Slider("menu.range", 800, 4000, 2600, "%d")
UI.charges = main:Slider("menu.charges", 1, 12, 1, "%d")
UI.charges:ToolTip("menu.charges_tip")
UI.sparkDelay = main:Slider("menu.spark_delay", 0, 40, 0, "%d%%")
UI.sparkDelay:Visible(false)
UI.sparkCast = main:Slider("menu.spark_cast", 0, 200, 0, "%d")
UI.sparkCast:Visible(false)
