UI.fluxKeep:Image("panorama/images/spellicons/arc_warden_flux_png.vtex_c")
UI.fluxKeep:ToolTip("menu.flux_keep_tip")
IT.octarine.clone = true
IT.octarine.isClone = function(unit) return unit ~= nil and unit == S.copyUnit end
UI.items = IT.build(section, side.Right, A.itemIcon, "arc_warden_1x6_combo", C.hero)
return true
end
function A.isArc(hero)
return A.validUnit(hero) and NPC.GetUnitName(hero) == C.hero
end
function A.pickTarget(hero)
local target = nil
if C.cursorHero then
local ok, result = pcall(C.cursorHero, Entity.GetTeamNum(hero), C.teamEnemy)
if ok then target = result end
end
if target ~= nil and A.validUnit(target) and not Entity.IsSameTeam(hero, target) and not NPC.IsIllusion(target) and A.distance(hero, target) <= UI.range:Get() then
return target
end
local cursor = C.cursorPos and C.cursorPos() or Entity.GetAbsOrigin(hero)
local best = nil
local bestDistance = math.huge
for _, enemy in ipairs(Heroes.GetAll()) do
if enemy ~= hero and A.validUnit(enemy) and not Entity.IsSameTeam(hero, enemy) and not NPC.IsIllusion(enemy) and A.distance(hero, enemy) <= UI.range:Get() then
local distance = A.pointDistance(enemy, cursor)
if distance < bestDistance then
best = enemy
bestDistance = distance
end
end
end
return best
end
function A.findClone(hero, now)
if S.clone ~= nil and A.validUnit(S.clone) and NPC.HasModifier(S.clone, C.cloneMod) then return S.clone end
if now < S.cloneAt and S.cloneAt - now <= C.cloneGap + 0.2 then return nil end
S.cloneAt = now + C.cloneGap
local playerId = Hero.GetPlayerID(hero)
for _, npc in ipairs(NPCs.GetAll()) do
if npc ~= hero and A.validUnit(npc) and Entity.IsSameTeam(hero, npc) and NPC.IsControllableByPlayer(npc, playerId) and NPC.HasModifier(npc, C.cloneMod) then
S.clone = npc
return npc
end
end
S.clone = nil
return nil
end
function A.legendAbility(hero, name)
local ability = NPC.GetAbility(hero, name)
if ability == nil or Ability.GetLevel(ability) <= 0 or Ability.IsHidden(ability) then return nil end
return ability
end
function A.hasLegend(name)
return S.legends[name] == true
end
function A.showLegends(found)
local names = {}
for _, name in ipairs({ "flux", "field", "spark", "double" }) do
if found[name] then names[#names + 1] = name end
end
if #names == 0 then
UI.legendary:ForceLocalization(localization.Get("spell.legendary_none"))
UI.legendary:Image("panorama/images/heroes/icons/npc_dota_hero_arc_warden_png.vtex_c")
elseif #names == 1 then
UI.legendary:ForceLocalization(localization.Get("spell.legendary_" .. names[1]))
UI.legendary:Image(C.legendIcons[names[1]])
else
local labels = {}
for i, name in ipairs(names) do labels[i] = localization.Get("panel." .. name) end
UI.legendary:ForceLocalization(string.format(localization.Get("spell.legendary_multi"), table.concat(labels, " + ")))
UI.legendary:Image(C.legendIcons[names[1]])
end
return names
end
function A.detectLegend(hero, now)
if now < S.legendAt and S.legendAt - now <= C.detectGap + 0.2 then return S.legends end
S.legendAt = now + C.detectGap
local found = {}
local evidence = {}
local sparkLegend = A.legendAbility(hero, C.sparkLegend)
local doubleLegend = A.legendAbility(hero, C.doubleLegend)
local flux = NPC.GetAbility(hero, C.flux)
local field = NPC.GetAbility(hero, C.field)
if sparkLegend ~= nil then
found.spark = true
evidence[#evidence + 1] = "spark: visible levelled astral cascade"
end
if doubleLegend ~= nil then
found.double = true
evidence[#evidence + 1] = "double: visible levelled double overdrive"
end
if flux ~= nil and Ability.GetLevel(flux) > 0 then
local behavior = Ability.GetBehavior(flux)
if A.has(behavior, C.bPoint) and A.has(behavior, C.bAoe) then
found.flux = true
evidence[#evidence + 1] = "flux behavior " .. tostring(behavior)
end
end
if field ~= nil and Ability.GetLevel(field) > 0 then
local behavior = Ability.GetBehavior(field)
if A.has(behavior, C.bNo) and not A.has(behavior, C.bPoint) then
found.field = true
evidence[#evidence + 1] = "field behavior " .. tostring(behavior)
end
end
local names = A.showLegends(found)
local signature = table.concat(names, "+")
if signature ~= (S.legend or "") then
S.legend = signature ~= "" and signature or nil
A.log("info", "arc legendary detected", { legendaries = names, evidence = evidence })
end
S.legends = found
return found
end
function A.start(hero, now)
local target = A.pickTarget(hero)
if target == nil then
S.phase = "target"
if now >= S.noTargetLogAt then
S.noTargetLogAt = now + 2
A.log("info", "arc combo waiting", { reason = "no target" })
end
return false
end
S.target = target
S.phase = "running"
S.startedAt = now
S.main = A.newUnitState()
S.clone = nil
S.cloneAt = 0
local clone = A.findClone(hero, now)
S.copy = clone ~= nil and A.newUnitState() or nil
S.copyUnit = clone
S.cloneReadyAt = now
S.summon = clone ~= nil and "done" or "idle"
S.overdrive = false
S.overdriveUntil = 0
S.manual = false
S.turn = false
S.sparkReadyAt = 0
S.nextOrder = now
A.log("info", "arc combo started", { target = NPC.GetUnitName(target), legend = S.legend or "none", double = clone ~= nil and "existing" or "missing" })
return true
end
function A.ready(ability, unit)
return ability ~= nil and Ability.GetLevel(ability) > 0 and Ability.IsCastable(ability, NPC.GetMana(unit))
end
function A.itemBase(name)
return (name:gsub("^item_", ""):gsub("_custom$", ""))
end
function A.itemLabel(name)
return (A.itemBase(name):gsub("_", " "))
end
function A.itemIcon(name)
local base = A.itemBase(name)
return "panorama/images/items/" .. (ICON_FIX[base] or base) .. "_png.vtex_c"
end
function A.itemSkipped(name)
for _, fragment in ipairs(ITEM_SKIP) do
if name:find(fragment, 1, true) ~= nil then return true end
end
return false
end
function A.itemKind(item)
local behavior = Ability.GetBehavior(item)
if A.has(behavior, C.bPassive) or A.has(behavior, C.bHidden) or A.has(behavior, C.bToggle) then return nil end
if A.has(behavior, C.bUnit) then
local team = Ability.GetTargetTeam(item)
if A.has(team, 2) then return "enemy" end
if A.has(team, 1) then return "self" end
return nil
end
if A.has(behavior, C.bPoint) then return "point" end
if A.has(behavior, C.bNo) then return "no" end
return nil
end
function A.isMeteorItem(name)
for _, fragment in ipairs(METEOR_FRAGMENTS) do
if name:find(fragment, 1, true) ~= nil then return true end
end
return false
end
function A.isBeforeMeteor(name)
for _, fragment in ipairs(BEFORE_METEOR) do
if name:find(fragment, 1, true) ~= nil then return true end
end
return false
end
function A.beforeMeteorPending(unit, state)
for _, label in ipairs(UI.items:ListEnabled()) do
local name = S.itemIds[label]
if name ~= nil and A.isBeforeMeteor(name) and not state.done[name] then
local item = A.findSelectedItem(unit, label, name)
if item ~= nil and A.ready(item, unit) then return name end
end
end
return nil
end
function A.cycloneLand(target)
for _, name in ipairs(CYCLONE_MODS) do
local modifier = NPC.GetModifier(target, name)
if modifier ~= nil then
local die = Modifier.GetDieTime(modifier)
if type(die) == "number" and die > 0 then return die end
end
end
return nil
end
function A.itemPhase(name)
for _, fragment in ipairs(DAMAGE_ITEM_FRAGMENTS) do
if name:find(fragment, 1, true) ~= nil then return "damage" end
end
return "control"
end
function A.isJumpItem(name)
return name:find("blink", 1, true) ~= nil or name:find("fallen_sky", 1, true) ~= nil
end
function A.scanItems(hero)
local labels, ids, signature = {}, {}, ""
for _, slot in ipairs(C.slots) do
local item = NPC.GetItemByIndex(hero, slot)
if item ~= nil then
local name = Ability.GetName(item)
local label = A.itemLabel(name)
if not A.itemSkipped(name) and A.itemKind(item) ~= nil and ids[label] == nil then
labels[#labels + 1] = label
ids[label] = name
signature = signature .. label .. ","
end
end
end
return labels, ids, signature
end
function A.refreshItems(hero)
IT.tick()
local labels, ids, signature = A.scanItems(hero)
if signature == S.itemSig then return end
local rank, old, enabled = {}, {}, {}
for i, id in ipairs(UI.items:List()) do
rank[id] = i
old[id] = true
end
for _, id in ipairs(UI.items:ListEnabled()) do enabled[id] = true end
table.sort(labels, function(a, b) return (rank[a] or 1000) < (rank[b] or 1000) end)
local rows, selected = {}, {}
for i, label in ipairs(labels) do
local on = not old[label] or enabled[label] == true
rows[i] = { label, A.itemIcon(ids[label]), on }
if on then selected[#selected + 1] = label end
end
UI.items:Update(rows, true, true)
UI.items:Set(selected)
S.itemSig = signature
S.itemIds = ids
IT.sync(hero, labels, ids, A.itemIcon)
A.log("info", "arc items refreshed", { items = labels, enabled = selected })
end
function A.itemEnabled(name)
local label = A.itemLabel(name)
return S.itemIds[label] ~= nil and UI.items:Get(label) == true
end
function A.findItem(unit, patterns)
for _, slot in ipairs(C.slots) do
local item = NPC.GetItemByIndex(unit, slot)
if item ~= nil then
local name = Ability.GetName(item)
for _, pattern in ipairs(patterns) do
if name:find(pattern, 1, true) then return item, name end
end
end
end
return nil, nil
end
function A.findSelectedItem(unit, label, name)
for _, slot in ipairs(C.slots) do
local item = NPC.GetItemByIndex(unit, slot)
if item ~= nil and Ability.GetName(item) == name then return item end
end
for _, slot in ipairs(C.slots) do
local item = NPC.GetItemByIndex(unit, slot)
if item ~= nil and A.itemLabel(Ability.GetName(item)) == label then return item end
end
return nil
end
function A.issueCast(ability, kind, target, point, now, gap)
if kind == "target" then
Ability.CastTarget(ability, target)
elseif kind == "point" then
Ability.CastPosition(ability, point)
else
Ability.CastNoTarget(ability)
end
S.nextOrder = now + (gap or C.castGap)
end
function A.castDelay(ability)
return math.max(C.castGap, math.max(0, IT.castPoint(ability)) + C.castMargin)
end
function A.issueAttack(unit, target, now)
Player.PrepareUnitOrders(Players.GetLocal(), C.orderAttack, target, Entity.GetAbsOrigin(target), nil, C.issuerUnit, unit, false, false, false, false, "arc_1x6_combo", false)
S.nextOrder = now + C.orderGap
end
function A.jumpItem(unit)
local blink, name = A.findItem(unit, { "blink" })
if blink ~= nil and A.itemEnabled(name) and A.ready(blink, unit) then return blink, name, false end
local fallen, fallenName = A.findItem(unit, { "fallen_sky" })
if fallen ~= nil and A.itemEnabled(fallenName) and A.ready(fallen, unit) then return fallen, fallenName, true end
return nil, nil, false
end
function A.blinkPoint(unit, target, range, stop)
local origin = Entity.GetAbsOrigin(unit)
local targetPos = Entity.GetAbsOrigin(target)
local delta = targetPos - origin
local distance = delta:Length2D()
if distance <= 0 or range <= 0 then return nil, 0 end
local direction = delta:Normalized()
if distance >= range + stop then return origin + direction * range, range end
if distance > math.abs(range - stop) and stop > 0 then
local along = (range * range - stop * stop + distance * distance) / (2 * distance)
local side = math.sqrt(math.max(0, range * range - along * along))
local sign = unit == S.clone and -1 or 1
local x = delta.x / distance
local y = delta.y / distance
return Vector(origin.x + x * along - y * side * sign, origin.y + y * along + x * side * sign, origin.z), range
end
local length = math.min(math.max(0, distance - stop), range)
return origin + direction * length, length
end
function A.rangedPoint(unit, target, range, stop)
local origin = Entity.GetAbsOrigin(unit)
local targetPos = Entity.GetAbsOrigin(target)
local delta = targetPos - origin
local distance = delta:Length2D()
if distance <= 0 or range <= 0 then return origin, 0 end
local direction = delta:Normalized()
if distance < stop then return origin - direction * range, range end
if distance >= range + stop then return origin + direction * range, range end
local along = (range * range - stop * stop + distance * distance) / (2 * distance)
local side = math.sqrt(math.max(0, range * range - along * along))
local sign = unit == S.clone and -1 or 1
local x = delta.x / distance
local y = delta.y / distance
return Vector(origin.x + x * along - y * side * sign, origin.y + y * along + x * side * sign, origin.z), range
end
function A.approach(unit, state, target, required, now)
local distance = A.distance(unit, target)
if distance <= required + C.targetSlack then return false end
if UI.blink:Get() and not state.done.jump then
local jump, name, fallen = A.jumpItem(unit)
if jump ~= nil then
local range = Ability.GetCastRange(jump)
if range <= 0 then range = fallen and 1200 or 1200 end
local rangedStop = math.max(180, NPC.GetAttackRange(unit) - 75)
local stop = math.min(math.max(180, required - 40), rangedStop)
local point, length = A.blinkPoint(unit, target, range, stop)
if point ~= nil and length >= 180 then
Ability.CastPosition(jump, point)
state.done.jump = true
state.next = now + (fallen and 1.1 or 0.18)
S.nextOrder = state.next
A.log("info", "arc combo jump", { item = name, distance = distance, jump = length, range = range, keep = stop })
return true
end
end
state.done.jump = true
end
if NPC.HasModifier(unit, C.doubleLegendMod) then return true end
if now >= state.moveAt then
NPC.MoveTo(unit, IT.stopPoint(unit, target, required), false, false, false, false, "arc_1x6_combo", false)
state.moveAt = now + C.moveGap
S.nextOrder = now + C.orderGap
return true
end
return true
end
function A.castBkb(unit, state, target, now)
if state.done.bkb then return false end
if not UI.bkb:Get() then
state.done.bkb = true
return false
end
if A.distance(unit, target) > 1000 then return false end
local item, name = A.findItem(unit, { "black_king_bar" })
if item == nil or not A.itemEnabled(name) then
state.done.bkb = true
return false
end
if not A.ready(item, unit) then return false end
A.issueCast(item, "no", target, Entity.GetAbsOrigin(target), now)
state.next = now + A.castDelay(item)
state.done.bkb = true
A.log("info", "arc combo item", { item = name, unit = unit == S.clone and "double" or "main" })
return true
end
function A.useItems(unit, state, target, now, phase)
for _, label in ipairs(UI.items:ListEnabled()) do
local name = S.itemIds[label]
if name ~= nil and A.itemPhase(name) == phase and not A.isJumpItem(name) and name:find("black_king_bar", 1, true) == nil and not state.done[name] then
local item = A.findSelectedItem(unit, label, name)
if item == nil then
state.done[name] = true
elseif A.relayWait(name, now) then
elseif not IT.allow(unit, target, name, label) then
elseif not A.ready(item, unit) then
else
local kind = A.itemKind(item)
local range = Ability.GetCastRange(item)
local land = A.isMeteorItem(name) and A.cycloneLand(target) or nil
local hold = nil
if land ~= nil and now < land - C.meteorImpact then
hold = "cyclone"
elseif A.isMeteorItem(name) then
hold = A.beforeMeteorPending(unit, state)
end
if kind == nil then
state.done[name] = true
elseif hold ~= nil then
if state.meteorHeld ~= hold then
state.meteorHeld = hold
A.log("info", "arc meteor hold", { item = name, reason = hold, land_in = land ~= nil and land - now or nil, unit = unit == S.clone and "double" or "main" })
end
elseif A.chainWait(unit, target, name, item, now) then
elseif A.silenceWait(target, name, now) then
elseif (kind == "enemy" or kind == "point") and range > 0 and A.approach(unit, state, target, range, now) then
return true
elseif kind == "no" and name:find("shivas_guard", 1, true) ~= nil and A.distance(unit, target) > C.shivaReach then
state.done[name] = true
else
if kind == "self" then
Ability.CastTarget(item, unit)
S.nextOrder = now + C.castGap
else
A.issueCast(item, kind == "enemy" and "target" or kind, target, Entity.GetAbsOrigin(target), now)
end
state.next = now + A.castDelay(item)
state.done[name] = true
A.chainMark(unit, target, name, item, now)
IT.chainMark(unit, target, name)
A.silenceMark(name, item, now)
A.relayMark(name, item, now)
A.log("info", "arc combo item", { item = name, kind = kind, unit = unit == S.clone and "double" or "main" })
return true
end
end
end
end
return false
end
function A.unitReach(unit)
local best = NPC.GetAttackRange(unit)
if type(best) ~= "number" then best = 0 end
for _, name in ipairs({ C.flux, C.field }) do
local ability = NPC.GetAbility(unit, name)
if ability ~= nil and A.ready(ability, unit) then
best = math.max(best, Ability.GetCastRange(ability))
end
end
for _, label in ipairs(UI.items:ListEnabled()) do
local name = S.itemIds[label]
if name ~= nil and not A.isJumpItem(name) then
local item = A.findSelectedItem(unit, label, name)
if item ~= nil and A.ready(item, unit) then
local kind = A.itemKind(item)
if kind == "no" or kind == "self" then
best = math.max(best, C.shivaReach)
elseif kind ~= nil then
best = math.max(best, Ability.GetCastRange(item))
end
end
end
end
return best
end
function A.useReunion(unit, state, target, now, other)
if state.done.reunion then return false end
local ability = NPC.GetAbility(unit, C.reunion)
if ability == nil or Ability.GetLevel(ability) <= 0 or Ability.IsHidden(ability) then
state.done.reunion = true
return false
end
if other == nil or not A.validUnit(other) or not A.ready(ability, unit) then return false end
local mine = A.distance(unit, target)
local theirs = A.distance(other, target)
if theirs >= mine - C.reunionGain then return false end
local reach = A.unitReach(unit)
if mine <= reach + C.targetSlack then return false end
A.issueCast(ability, "no", target, Entity.GetAbsOrigin(unit), now, C.reunionChannel)
state.next = now + C.reunionChannel
state.done.reunion = true
A.log("info", "arc reunion", { mine = math.floor(mine), theirs = math.floor(theirs), reach = math.floor(reach), unit = unit == S.clone and "double" or "main" })
return true
end
function A.trackTarget(target, now)
if now - S.trackAt < C.trackGap then return end
local origin = Entity.GetAbsOrigin(target)
if S.trackPos ~= nil then
S.moving = (origin - S.trackPos):Length2D() > (now - S.trackAt) * C.trackSpeed
end
S.trackPos, S.trackAt = origin, now
end
function A.useFlux(unit, state, target, now)
if state.done.flux then return false end
if not UI.spells:Get("spell.flux") then
state.done.flux = true
return false
end
local ability = NPC.GetAbility(unit, C.flux)
if ability == nil or Ability.GetLevel(ability) <= 0 then
state.done.flux = true
return false
end
if not A.ready(ability, unit) then return false end
local behavior = Ability.GetBehavior(ability)
local range = Ability.GetCastRange(ability)
if range <= 0 then range = 800 end
if not A.has(behavior, C.bPoint) then
if A.approach(unit, state, target, range, now) then return true end
if IT.spellBlocked(target, now, Ability.GetName(ability)) then return false end
A.issueCast(ability, "target", target, Entity.GetAbsOrigin(target), now)
state.next = now + A.castDelay(ability)
state.done.flux = true
A.log("info", "arc combo spell", { spell = C.flux, kind = "target", legend = S.legend, unit = unit == S.clone and "double" or "main" })
return true
end
local clone = S.copyUnit
if clone ~= nil and A.validUnit(clone) and not NPC.HasModifier(clone, C.fluxLegendMod) then
if unit == clone or A.distance(unit, clone) <= range + C.targetSlack then
Ability.CastTarget(ability, clone)
S.nextOrder = now + C.castGap
state.next = now + A.castDelay(ability)
state.done.flux = true
A.log("info", "arc combo spell", { spell = C.flux, kind = "double", legend = S.legend, unit = unit == S.clone and "double" or "main" })
return true
end
end
if NPC.HasModifier(unit, C.fluxLegendMod) then
state.done.flux = true
return false
end
local distance = A.distance(unit, target)
local jump = A.jumpItem(unit)
local point, kind = nil, "self"
if distance > C.fluxRadius and jump == nil then
if S.moving and C.forwardPos ~= nil then
kind = "lead"
point = C.forwardPos(target, C.fluxLead)
else
kind = "point"
point = Entity.GetAbsOrigin(target)
end
point = A.clampPoint(unit, point, range, 40)
end
if point ~= nil then
Ability.CastPosition(ability, point)
else
Ability.CastTarget(ability, unit)
end
S.nextOrder = now + C.castGap
state.next = now + A.castDelay(ability)
state.done.flux = true
A.log("info", "arc combo spell", { spell = C.flux, kind = kind, legend = S.legend, distance = distance, moving = S.moving, blink = jump ~= nil, unit = unit == S.clone and "double" or "main" })
return true
end
function A.fluxChase(unit, state, target, now)
if not NPC.HasModifier(unit, C.fluxLegendMod) or NPC.HasModifier(unit, C.doubleLegendMod) then return false end
local goal = A.predictRun(target, C.fluxChaseLead)
local keep = math.min(UI.fluxKeep:Get(), C.fluxRadius - NPC.GetHullRadius(target) - C.fluxChaseMargin)
if (goal - Entity.GetAbsOrigin(unit)):Length2D() <= keep then return false end
if now >= state.moveAt then
NPC.MoveTo(unit, goal, false, false, false, false, "arc_1x6_combo", false)
state.moveAt = now + C.moveGap
S.nextOrder = now + C.orderGap
end
return true
end
function A.fluxBlock(unit, state, target, now)
if not NPC.HasModifier(target, C.fluxMod) or NPC.HasModifier(unit, C.fluxLegendMod) then return false end
local vel, speed = A.movementVector(target)
if speed <= 10 then return false end
local dir = vel:Normalized()
local origin = Entity.GetAbsOrigin(target)
if (Entity.GetAbsOrigin(unit) - origin):Dot2D(dir) < -C.blockBehind then return false end
if now >= state.moveAt then
local goal = A.predictRun(target, C.blockLead) + dir * (NPC.GetHullRadius(target) + NPC.GetHullRadius(unit))
NPC.MoveTo(unit, goal, false, false, false, false, "arc_1x6_combo", false)
state.moveAt = now + C.moveGap
S.nextOrder = now + C.orderGap
if not state.blockLogged then
state.blockLogged = true
A.log("info", "arc double body block", { speed = math.floor(speed) })
end
end
return true
end
function A.fluxHold(unit, state, target, now)
if not NPC.HasModifier(unit, C.fluxLegendMod) then return false end
return A.approach(unit, state, target, C.fluxKeep, now)
end
function A.lag()
local ok, value = false, nil
if C.latency ~= nil then ok, value = pcall(C.latency) end
if not ok or type(value) ~= "number" or value < 0 then return 0.05 end
return math.min(0.25, value)
end
function A.updateRunTrack(unit, now)
local id = Entity.GetIndex(unit)
local pos = Entity.GetAbsOrigin(unit)
local track = S.enemyTrack[id]
if track ~= nil and now - track.last_time > C.runReset then track = nil end
track = track or {
last_pos = pos,
last_time = now,
vel = Vector(0, 0, 0),
normal_speed = NPC.GetMoveSpeed(unit),
}
local dt = math.max(0.016, now - track.last_time)
local raw = (pos - track.last_pos) / dt
track.vel = raw * 0.58 + track.vel * 0.42
track.last_pos = pos
track.last_time = now
S.enemyTrack[id] = track
if not NPC.IsStunned(unit) and A.speedModifierLeft(unit, now) == nil then
track.normal_speed = NPC.GetMoveSpeed(unit)
end
end
function A.speedModifierLeft(unit, now)
local track = S.enemyTrack[Entity.GetIndex(unit)]
if track and track.speed_scan_at and now - track.speed_scan_at < 0.04 then return track.speed_left end
local best, generic = nil, nil
for _, modifier in ipairs(NPC.GetModifiers(unit) or {}) do
if not Modifier.IsDebuff(modifier) then
local name = Modifier.GetName(modifier):lower()
local left = Modifier.GetDieTime(modifier) - now
if left > 0.02 and left <= C.prediction.max_lead + 1
and (generic == nil or left < generic) then
generic = left
end
for _, word in ipairs(SPEED_WORDS) do
if name:find(word, 1, true) ~= nil then
if left > 0.02 and left <= C.prediction.max_lead + 1
and (best == nil or left < best) then
best = left
end
break
end
end
end
end
if best == nil and track and track.normal_speed
and NPC.GetMoveSpeed(unit) > track.normal_speed * C.prediction.boost_ratio then
best = generic or C.prediction.boost_fallback
end
if track then
track.speed_scan_at = now
track.speed_left = best
end
return best
end
function A.predictionDistance(unit, time, speed)
local lead = math.min(time, C.prediction.max_lead)
local now = GameRules.GetGameTime()
local boost_left = A.speedModifierLeft(unit, now)
if boost_left == nil or boost_left >= lead then return speed * lead end
local track = S.enemyTrack[Entity.GetIndex(unit)]
local normal = track and track.normal_speed or NPC.GetBaseSpeed(unit)
normal = math.min(speed, math.max(0, normal))
return speed * boost_left + normal * (lead - boost_left)
end
function A.movementVector(unit)
local track = S.enemyTrack[Entity.GetIndex(unit)]
local vel = track and track.vel or Vector(0, 0, 0)
local speed = vel:Length2D()
local move_speed = NPC.GetMoveSpeed(unit)
local forward = Entity.GetRotation(unit):GetForward():Normalized()
local run_vel = forward * move_speed
if speed > move_speed then
vel = vel:Normalized() * move_speed
speed = move_speed
end
if NPC.IsRunning(unit) then
if speed > 80 then
local align = vel:Normalized():Dot2D(forward)
if align > 0.35 then
local blend = math.max(0, math.min(1, (align - 0.35) / 0.65))
local blended = vel * (0.45 + blend * 0.2) + run_vel * (0.55 - blend * 0.2)
return blended, math.min(blended:Length2D(), move_speed)
end
end
return run_vel, move_speed
end
if speed > 18 then return vel * 0.35, speed * 0.35 end
return Vector(0, 0, 0), 0
end
function A.predictRun(unit, time)
local pos = Entity.GetAbsOrigin(unit)
time = IT.moveTime(unit, time, GameRules.GetGameTime())
if time <= 0.02 then return pos end
local vel, speed = A.movementVector(unit)
if speed <= 10 then return pos end
return pos + vel:Normalized() * A.predictionDistance(unit, time, speed)
end
function A.sparkTiming()
local cast = math.max(0, C.sparkCastBase - UI.sparkCast:Get() / 1000)
local activation = C.sparkActivation * (1 - UI.sparkDelay:Get() / 100)
return cast, activation
end
function A.sparkPoint(unit, target, ability, castLeft)
local _, activation = A.sparkTiming()
local point = A.predictRun(target, castLeft + A.lag() + activation)
local range = Ability.GetCastRange(ability)
if range <= 0 then range = 2000 end
return A.clampPoint(unit, point, range, 25)
end
function A.sparkCastSample(duration)
local best, gap = nil, math.huge
for _, row in ipairs(C.sparkCasts) do
local d = math.abs(row.cast - duration)
if d < gap then best, gap = row, d end
end
if best == nil then return end
if S.sparkCastVote ~= best.ms then
S.sparkCastVote = best.ms
return
end
if UI.sparkCast:Get() ~= best.ms then
UI.sparkCast:Set(best.ms)
A.log("info", "arc spark cast talent detected", { ms = best.ms, phase = math.floor(duration * 1000) })
end
end
function A.sparkLifeSample(life)
if life > C.sparkDelays[1].delay + 0.5 then return end
if S.sparkLifeMin == nil or life < S.sparkLifeMin then S.sparkLifeMin = life end
local pick = C.sparkDelays[#C.sparkDelays]
for _, row in ipairs(C.sparkDelays) do
if row.delay <= S.sparkLifeMin + C.sparkDelaySlack then
pick = row
break
end
end
if UI.sparkDelay:Get() ~= pick.pct then
UI.sparkDelay:Set(pick.pct)
A.log("info", "arc spark delay talent detected", { pct = pick.pct, life = math.floor(S.sparkLifeMin * 1000) })
end
end
function A.watchSpark(unit, target, now)
if unit == nil or target == nil then return end
local id = Entity.GetIndex(unit)
local watch = S.sparkWatch[id]
if watch == nil then return end
local cast = A.sparkTiming()
local phase = Ability.IsInAbilityPhase(watch.ability)
if phase and watch.phaseAt == nil then watch.phaseAt = now end
if not phase and watch.phaseAt ~= nil then
if not watch.moved then A.sparkCastSample(now - watch.phaseAt) end
S.sparkWatch[id] = nil
return
end
if now > watch.at + C.sparkCastBase + A.lag() * 2 + 0.15 or not A.validUnit(unit) then
S.sparkWatch[id] = nil
return
end
if not phase or watch.tries >= C.sparkRetries then return end
local left = math.max(0, cast - math.max(0, now - watch.phaseAt))
local point = A.sparkPoint(unit, target, watch.ability, left)
if (point - watch.point):Length2D() <= C.sparkRetarget then return end
Ability.CastPosition(watch.ability, point)
A.log("info", "arc spark retarget", { shift = math.floor((point - watch.point):Length2D()), try = watch.tries + 1, unit = unit == S.clone and "double" or "main" })
watch.point, watch.at, watch.tries, watch.phaseAt, watch.moved = point, now, watch.tries + 1, nil, true
S.sparkLast[id] = point
end
function A.sparkCreated(entity, modifier)
if Modifier.GetName(modifier) ~= C.sparkThinkerMod then return end
local caster = Modifier.GetCaster(modifier)
if caster == nil or NPC.GetUnitName(caster) ~= C.hero then return end
local hero = Heroes.GetLocal()
if hero == nil or not Entity.IsSameTeam(hero, caster) then return end
local now = GameRules.GetGameTime()
local pos = Entity.GetAbsOrigin(entity)
S.sparkThinkers[Entity.GetIndex(entity)] = now
local aim = S.sparkLast[Entity.GetIndex(caster)]
A.log("info", "arc spark placed", { offset = aim ~= nil and math.floor((pos - aim):Length2D()) or -1, unit = caster == S.clone and "double" or "main" })
end
function A.sparkDestroyed(entity, modifier)
if Modifier.GetName(modifier) ~= C.sparkThinkerMod then return end
local id = Entity.GetIndex(entity)
local created = S.sparkThinkers[id]
if created == nil then return end
S.sparkThinkers[id] = nil
local life = GameRules.GetGameTime() - created
if life < C.sparkMaxLife then A.sparkLifeSample(life) end
end
function A.holdLeft(target, now)
local left = 0
for _, mod in ipairs(NPC.GetModifiers(target) or {}) do
local name = Modifier.GetName(mod)
for _, word in ipairs(C.holdWords) do
if name:find(word, 1, true) ~= nil then
local rest = Modifier.GetDieTime(mod) - now
if rest > left then left = rest end
break
end
end
end
if now < S.chainUntil and (left > 0 or now < S.chainApply + C.chainConfirm) then
left = math.max(left, S.chainUntil - now)
end
return left
end
function A.controlRule(name)
return C.controls[IT.base(name)]
end
function A.controlDelay(unit, target, item, rule)
local delay = math.max(0, IT.castPoint(item)) + A.lag()
if rule.fall ~= nil then return delay + rule.fall end
if rule.speed ~= nil then return delay + A.distance(unit, target) / rule.speed end
return delay
end
function A.cloneFirst(unit, name)
local clone = S.copyUnit
if clone == nil or unit == clone or not A.validUnit(clone) then return false end
local base = IT.base(name)
for _, slot in ipairs(C.slots) do
local item = NPC.GetItemByIndex(clone, slot)
if item ~= nil and IT.base(Ability.GetName(item)) == base then return A.ready(item, clone) end
end
return false
end
function A.chainWait(unit, target, name, item, now)
local rule = A.controlRule(name)
if rule == nil then return false end
if A.cloneFirst(unit, name) then return true end
local left = A.holdLeft(target, now)
local delay = A.controlDelay(unit, target, item, rule)
if left > delay + C.chainPad then return true end
if rule.fall ~= nil then
local reach = rule.radius - NPC.GetHullRadius(target) - C.meteorMargin
if NPC.GetMoveSpeed(target) * math.max(0, delay - left) > reach then return true end
end
return false
end
function A.isSilenceItem(name)
for _, frag in ipairs(C.silenceItems) do
if name:find(frag, 1, true) ~= nil then return true end
end
return false
end
function A.silenceWait(target, name, now)
if not A.isSilenceItem(name) then return false end
if now < S.silenceUntil - C.chainPad then return true end
for _, mod in ipairs(NPC.GetModifiers(target) or {}) do
local mname = Modifier.GetName(mod)
for _, frag in ipairs(C.silenceItems) do
if mname:find(frag, 1, true) ~= nil and Modifier.GetDieTime(mod) - now > C.chainPad then return true end
end
end
return false
end
function A.silenceMark(name, item, now)
if not A.isSilenceItem(name) then return end
local duration = C.silenceDuration
if C.specialValue ~= nil then
local ok, value = pcall(C.specialValue, item, "silence_duration", -1)
if ok and type(value) == "number" and value > 0 then duration = value end
end
S.silenceUntil = now + math.max(0, IT.castPoint(item)) + A.lag() + duration
end
function A.relayWait(name, now)
local rule = C.relay[IT.base(name)]
if rule == nil then return false end
local left = (S.relayUntil[IT.base(name)] or 0) - now
for _, unit in ipairs({ Heroes.GetLocal(), S.clone }) do
if unit ~= nil and A.validUnit(unit) then
local modifier = NPC.GetModifier(unit, rule.mod)
if modifier ~= nil then left = math.max(left, Modifier.GetDieTime(modifier) - now) end
end
end
return left > C.relayPad
end
function A.relayMark(name, item, now)
local rule = C.relay[IT.base(name)]
if rule == nil then return end
local duration = rule.dur
if C.specialValue ~= nil then
local ok, value = pcall(C.specialValue, item, rule.key, -1)
if ok and type(value) == "number" and value > 0 then duration = value end
end
S.relayUntil[IT.base(name)] = now + math.max(0, IT.castPoint(item)) + A.lag() + duration
end
function A.chainMark(unit, target, name, item, now)
local rule = A.controlRule(name)
if rule == nil then return end
local delay = A.controlDelay(unit, target, item, rule)
S.chainApply = now + delay
S.chainUntil = math.max(S.chainUntil, now + delay + rule.dur)
A.log("info", "arc control chain", { item = name, lands_in = math.floor(delay * 100) / 100, unit = unit == S.clone and "double" or "main" })
end
function A.useSpark(unit, state, target, now)
if state.done.spark then return false end
if not UI.spells:Get("spell.spark") then
state.done.spark = true
return false
end
local ability = NPC.GetAbility(unit, C.spark)
if ability == nil or Ability.GetLevel(ability) <= 0 then
state.done.spark = true
return false
end
if not A.ready(ability, unit) then return false end
local range = Ability.GetCastRange(ability)
if range <= 0 then range = 2000 end
if A.approach(unit, state, target, range, now) then return true end
local cast, activation = A.sparkTiming()
local point = A.sparkPoint(unit, target, ability, cast)
A.issueCast(ability, "point", target, point, now)
S.sparkWatch[Entity.GetIndex(unit)] = { ability = ability, point = point, at = now, tries = 0 }
S.sparkLast[Entity.GetIndex(unit)] = point
state.next = now + math.max(C.castGap, cast + C.castMargin)
state.done.spark = true
S.sparkReadyAt = math.max(S.sparkReadyAt, now + cast + activation + C.sparkRadius / C.sparkSpeed)
A.log("info", "arc combo spell", { spell = C.spark, hit_eta = S.sparkReadyAt - now, unit = unit == S.clone and "double" or "main" })
return true
end
function A.useField(unit, state, target, now)
if state.done.field then return false end
if not UI.spells:Get("spell.field") then
state.done.field = true
state.done.flicker = true
return false
end
local ability = NPC.GetAbility(unit, C.field)
if ability == nil or Ability.GetLevel(ability) <= 0 then
state.done.field = true
state.done.flicker = true
return false
end
if state.fieldSent > 0 then
local linked = NPC.GetAbility(unit, C.fieldLegend)
local confirmed = NPC.HasModifier(unit, C.fieldMod) or Ability.GetCooldown(ability) > 0 or Ability.IsHidden(ability) or (linked ~= nil and not Ability.IsHidden(linked))
if confirmed then
state.done.field = true
state.fieldAt = now
A.log("info", "arc combo spell confirmed", { spell = C.field, tries = state.fieldTries, unit = unit == S.clone and "double" or "main" })
return false
end
if Ability.IsInAbilityPhase(ability) then return true end
if now - state.fieldStarted >= C.fieldTimeout then
state.done.field = true
state.done.flicker = true
A.log("warn", "arc combo spell skipped", { spell = C.field, reason = "cast not confirmed", tries = state.fieldTries, unit = unit == S.clone and "double" or "main" })
return false
end
if now - state.fieldSent < C.fieldRetry or not A.ready(ability, unit) then return false end
elseif not A.ready(ability, unit) then
return false
end
local behavior = Ability.GetBehavior(ability)
local kind = "no"
if not (A.has(behavior, C.bNo) and not A.has(behavior, C.bPoint)) then
kind = A.has(behavior, C.bUnit) and "self" or "point"
end
if kind == "self" then
Ability.CastTarget(ability, unit)
S.nextOrder = now + C.castGap
elseif kind == "point" then
local point = A.fieldPoint(unit, target, ability)
S.w4Probe[unit] = { from = Entity.GetAbsOrigin(unit), to = point, at = now + math.max(0, IT.castPoint(ability)) + C.w4Settle }
A.issueCast(ability, kind, target, point, now)
else
A.issueCast(ability, kind, target, Entity.GetAbsOrigin(unit), now)
end
if state.fieldStarted == 0 then state.fieldStarted = now end
state.fieldSent = now
state.fieldTries = state.fieldTries + 1
if state.fieldTries == 1 then
A.log("info", "arc combo spell sent", { spell = C.field, kind = kind, legend = S.legend, unit = unit == S.clone and "double" or "main" })
end
return true
end
function A.fieldPoint(unit, target, ability)
local origin = Entity.GetAbsOrigin(unit)
local away = target ~= nil and (origin - Entity.GetAbsOrigin(target)) or Vector(1, 0, 0)
local len = away:Length2D()
if len < 1 then away, len = Vector(1, 0, 0), 1 end
local jump = C.w4Probe
local ax, ay = away.x / len, away.y / len
if S.w4 then
local range = Ability.GetCastRange(ability)
if range <= 0 then range = 500 end
jump = range - C.w4Edge
local a = math.rad(C.w4Spread) * (unit == S.clone and -1 or 1)
ax, ay = ax * math.cos(a) - ay * math.sin(a), ax * math.sin(a) + ay * math.cos(a)
end
return Vector(origin.x + ax * jump, origin.y + ay * jump, origin.z)
end
function A.checkW4(now)
for unit, probe in pairs(S.w4Probe) do
if now >= probe.at then
S.w4Probe[unit] = nil
local ok, pos = pcall(Entity.GetAbsOrigin, unit)
if ok and pos ~= nil and not S.w4 then
local moved = (pos - probe.from):Length2D()
if moved >= C.w4Probe * 0.6 and (pos - probe.to):Length2D() <= C.w4Probe * 0.6 then
S.w4 = true
A.log("info", "arc field teleport talent detected", { moved = math.floor(moved), unit = unit == S.clone and "double" or "main" })
end
end
end
end
end
function A.useFlicker(unit, state, target, now)
if state.done.flicker then return false end
if not A.hasLegend("field") or not UI.legendary:Get() then
state.done.flicker = true
return false
end
if not state.done.field or now - state.fieldAt < C.castGap then return false end
local rooted = NPC.HasModifier(unit, C.doubleLegendMod)
local ability = NPC.GetAbility(unit, C.fieldLegend)
if ability == nil or Ability.GetLevel(ability) <= 0 then
if not rooted and not NPC.HasModifier(unit, C.fieldMod) then state.done.flicker = true end
return false
end
if Ability.IsHidden(ability) or not A.ready(ability, unit) then
if not rooted and not NPC.HasModifier(unit, C.fieldMod) then state.done.flicker = true end
return false
end
if rooted then return false end
local behavior = Ability.GetBehavior(ability)
local kind = A.has(behavior, C.bPoint) and "point" or "no"
local point = Entity.GetAbsOrigin(unit)
local jump = 0
local stop = 0
if kind == "point" then
local range = Ability.GetCastRange(ability)
if range <= 0 then range = 350 end
stop = math.max(350, NPC.GetAttackRange(unit) - 75)
point, jump = A.rangedPoint(unit, target, range, stop)
end
A.issueCast(ability, kind, target, point, now)
state.done.flicker = true
state.next = now + 0.55
A.log("info", "arc legendary cast", { legendary = "field", kind = kind, epic_teleport = kind == "point", jump = jump, keep = stop, unit = unit == S.clone and "double" or "main" })
return true
end
function A.sparkStacks(hero)
local modifier = NPC.GetModifier(hero, C.sparkStackMod)
if modifier == nil then return nil, 0 end
local die = Modifier.GetDieTime(modifier)
return Modifier.GetStackCount(modifier), type(die) == "number" and die or 0
end
function A.cascadeDamage(hero, stacks)
if stacks == nil or stacks <= 0 then return 0 end
local spark = NPC.GetAbility(hero, C.spark)
if spark == nil then return 0 end
local level = Ability.GetLevel(spark)
if level <= 0 then return 0 end
local base = 0
if C.specialValue ~= nil then
local ok, value = pcall(C.specialValue, spark, "spark_damage_base", level)
if ok and type(value) == "number" then base = value end
end
if base <= 0 then base = SPARK_BASE[math.min(level, #SPARK_BASE)] or 0 end
local intellect = C.heroInt ~= nil and C.heroInt(hero) or 0
if type(intellect) ~= "number" then intellect = 0 end
local hit = base + C.sparkIntShare * intellect
return hit * C.cascadeAmp * math.pow(math.min(stacks, C.cascadeMax) / C.cascadeMax, C.cascadeExp)
end
function A.cascadeLethal(hero, target, stacks)
local raw = A.cascadeDamage(hero, stacks)
if raw <= 0 then return false, 0 end
local multiplier = 1
if C.magicMult ~= nil then
local ok, value = pcall(C.magicMult, target)
if ok and type(value) == "number" and value > 0 then multiplier = value end
end
local damage = raw * multiplier
return damage >= Entity.GetHealth(target) * C.killMargin, damage
end
function A.useCascade(hero, state, target, now)
if state.done.cascade then return false end
if not A.hasLegend("spark") or not UI.legendary:Get() then
state.done.cascade = true
return false
end
local ability = A.legendAbility(hero, C.sparkLegend)
if ability == nil then return false end
if state.cascadeSent > 0 then
if NPC.IsChannellingAbility(hero) or Ability.IsChannelling(ability) or Ability.GetCooldown(ability) > 0 then
state.done.cascade = true
A.log("info", "arc legendary confirmed", { legendary = "spark", tries = state.cascadeTries })
elseif now - state.cascadeSent > 0.55 then
state.cascadeSent = 0
if state.cascadeTries >= 2 then
state.done.cascade = true
A.log("warn", "arc legendary skipped", { legendary = "spark", reason = "cast not confirmed" })
end
end
return false
end
local stacks, dieAt = A.sparkStacks(hero)
local threshold = UI.charges:Get()
local fallbackReady = stacks == nil and S.sparkReadyAt > 0 and now >= S.sparkReadyAt
local lethal, damage = A.cascadeLethal(hero, target, stacks)
local full = stacks ~= nil and stacks >= C.cascadeMax
local expiring = stacks ~= nil and stacks > 0 and dieAt > 0 and dieAt - now <= C.stackExpire
if not fallbackReady and not lethal and not full and not expiring and (stacks == nil or stacks < threshold) then
if now - S.startedAt > C.maxRun and stacks ~= nil and stacks > 0 then threshold = stacks else return false end
end
if lethal and not state.cascadeLogged then
state.cascadeLogged = true
A.log("info", "arc cascade lethal", { stacks = stacks, damage = math.floor(damage), health = Entity.GetHealth(target) })
end
if not A.ready(ability, hero) then return false end
local range = Ability.GetCastRange(ability)
if range <= 0 then range = 1000 end
if A.approach(hero, state, target, range, now) then return true end
if IT.spellBlocked(target, now, Ability.GetName(ability)) then return false end
if NPC.HasModifier(target, C.lotusMod) then
if not state.lotusLogged then
state.lotusLogged = true
A.log("info", "arc cascade lotus wait", { stacks = stacks or -1 })
end
return false
end
state.lotusLogged = false
A.issueCast(ability, "target", target, Entity.GetAbsOrigin(target), now, 0.3)
state.cascadeSent = now
state.cascadeTries = state.cascadeTries + 1
A.log("info", "arc legendary sent", { legendary = "spark", stacks = stacks or -1, lethal = lethal, full = full, expiring = expiring, tries = state.cascadeTries })
return true
end
function A.summon(hero, target, now)
if not UI.spells:Get("spell.double") then
S.summon = "done"
return false
end
local clone = A.findClone(hero, now)
if clone ~= nil then
S.summon = "done"
return false
end
if S.summon == "sent" then
if now - S.summonAt > 1.2 then
S.summon = "done"
A.log("warn", "arc double missing", { waited = now - S.summonAt })
end
return false
end
local ability = NPC.GetAbility(hero, C.double)
if not A.ready(ability, hero) then
S.summon = "done"
return false
end
local range = Ability.GetCastRange(ability)
if range <= 0 then range = 700 end
local point = A.clampPoint(hero, Entity.GetAbsOrigin(target), range, 35)
A.issueCast(ability, "point", target, point, now, A.castDelay(ability))
S.summon = "sent"
S.summonAt = now
A.log("info", "arc double sent", { range = range, distance = A.pointDistance(hero, point) })
return true
end
function A.useDoubleLegend(hero, clone, now)
if S.overdrive or not A.hasLegend("double") or not UI.legendary:Get() then return false end
if clone == nil or not A.validUnit(clone) or A.distance(hero, clone) > 2000 then return false end
if A.hasLegend("field") and not S.main.done.flicker then
local flicker = NPC.GetAbility(hero, C.fieldLegend)
if NPC.HasModifier(hero, C.fieldMod) or (flicker ~= nil and not Ability.IsHidden(flicker) and A.ready(flicker, hero)) then
return false
end
end
local ability = A.legendAbility(hero, C.doubleLegend)
if ability == nil or not A.ready(ability, hero) then return false end
A.issueCast(ability, "no", S.target, Entity.GetAbsOrigin(S.target), now, A.castDelay(ability))
S.overdrive = true
S.overdriveUntil = now + 6.2
A.log("info", "arc legendary cast", { legendary = "double", clone_distance = A.distance(hero, clone) })
return true
end
function A.attack(unit, state, target, now, isMain)
if isMain and A.hasLegend("double") and now < S.overdriveUntil then return false end
if now < state.attackAt or NPC.IsAttacking(unit) then return false end
A.issueAttack(unit, target, now)
state.attackAt = now + 0.55
return true
end
function A.toggleCloneLock(hero, now)
if S.cloneLock ~= nil then
S.cloneLock = nil
A.log("info", "arc clone lock off", { reason = "key" })
return
end
local target = A.pickTarget(hero)
if target == nil then
A.log("info", "arc clone lock no target", {})
return
end
S.cloneLock = { target = target, state = A.newUnitState() }
A.log("info", "arc clone lock on", { target = NPC.GetUnitName(target) })
end
function A.runCloneLock(hero, now)
local lock = S.cloneLock
local target = lock.target
if not A.validUnit(target) or Entity.IsSameTeam(hero, target) then
S.cloneLock = nil
A.log("info", "arc clone lock off", { reason = "target lost" })
return
end
local clone = A.findClone(hero, now)
if clone == nil then
S.cloneLock = nil
A.log("info", "arc clone lock off", { reason = "no double" })
return
end
if now < S.nextOrder or not A.orderSafe() then return end
A.trackTarget(target, now)
A.updateRunTrack(target, now)
A.watchSpark(clone, target, now)
A.runUnit(clone, lock.state, target, now, false)
end
function A.runUnit(unit, state, target, now, isMain)
if unit == nil or state == nil or not A.validUnit(unit) or now < state.next or NPC.IsChannellingAbility(unit) or NPC.HasModifier(unit, "modifier_item_meteor_hammer_custom_cast") or IT.heroDisabled(unit) then return false end
local fluxFirst = A.hasLegend("flux")
if target ~= nil and IT.breakLinken(unit, target, now) then return true end
if isMain and S.cascadeLethal and A.useCascade(unit, state, target, now) then return true end
if not isMain and A.fluxChase(unit, state, target, now) then return true end
if fluxFirst and A.useFlux(unit, state, target, now) then return true end
if A.useReunion(unit, state, target, now, isMain and S.clone or Heroes.GetLocal()) then return true end
if A.castBkb(unit, state, target, now) then return true end
if A.useItems(unit, state, target, now, "control") then return true end
if not fluxFirst and A.useFlux(unit, state, target, now) then return true end
if not isMain and A.fluxBlock(unit, state, target, now) then return true end
if A.useSpark(unit, state, target, now) then return true end
if A.useField(unit, state, target, now) then return true end
if A.useFlicker(unit, state, target, now) then return true end
if A.useItems(unit, state, target, now, "damage") then return true end
if isMain and A.useCascade(unit, state, target, now) then return true end
if A.fluxHold(unit, state, target, now) then return true end
if A.attack(unit, state, target, now, isMain) then return true end
if now - state.cycleAt > C.cycleGap then
state.cycleAt = now
state.done = {}
state.fieldStarted, state.fieldSent, state.fieldTries = 0, 0, 0
state.cascadeSent, state.cascadeTries = 0, 0
state.meteorHeld = nil
state.cascadeLogged = false
state.blockLogged = false
end
return false
end
function A.update()
local hero = Heroes.GetLocal()
if not A.isArc(hero) then
if S.phase ~= "idle" then A.reset("no arc warden", true) end
return
end
local now = GameRules.GetGameTime()
A.detectLegend(hero, now)
A.checkW4(now)
if now >= S.itemAt or S.itemAt - now > C.itemGap + 0.2 then
S.itemAt = now + C.itemGap
local ok, err = pcall(A.refreshItems, hero)
if ok then
S.itemError = nil
elseif S.itemError == nil then
S.itemError = tostring(err)
A.log("error", "arc items refresh failed", { error = S.itemError })
end
end
if not UI.enabled:Get() then
if S.phase ~= "idle" then A.reset("disabled", true) end
return
end
local cloneDown = UI.cloneKey:IsDown()
if cloneDown and not S.cloneKeyDown then A.toggleCloneLock(hero, now) end
S.cloneKeyDown = cloneDown
if S.cloneLock ~= nil and not UI.key:IsDown() then A.runCloneLock(hero, now) end
if not UI.key:IsDown() then
if S.phase ~= "idle" and S.phase ~= "target" then A.reset("key released", true) end
if S.phase == "target" then S.phase = "idle" end
S.manual = false
return
end
if S.manual then
S.phase = "manual"
return
end
if S.phase == "idle" or S.phase == "target" then
if not A.start(hero, now) then return end
end
if S.target == nil or not A.validUnit(S.target) or Entity.IsSameTeam(hero, S.target) then
A.reset("target lost", true)
S.phase = "target"
return
end
if A.distance(hero, S.target) > UI.range:Get() + 1000 then
A.reset("target too far", true)
S.phase = "target"
return
end
S.phase = "running"
A.trackTarget(S.target, now)
A.updateRunTrack(S.target, now)
A.watchSpark(hero, S.target, now)
if S.copyUnit ~= nil then A.watchSpark(S.copyUnit, S.target, now) end
if A.hasLegend("spark") then
local stacks = A.sparkStacks(hero)
local lethal, damage = A.cascadeLethal(hero, S.target, stacks)
S.cascadeLethal = lethal
if now - S.cascadeCheckAt >= C.checkGap then
S.cascadeCheckAt = now
A.log("info", "arc cascade check", { stacks = stacks or -1, damage = math.floor(damage), health = Entity.GetHealth(S.target), lethal = lethal })
end
else
S.cascadeLethal = false
end
local clone = A.findClone(hero, now)
if now < S.nextOrder or not A.orderSafe() then return end
if S.summon ~= "done" then
if IT.heroDisabled(hero) then return end
if A.summon(hero, S.target, now) then return end
clone = A.findClone(hero, now)
if S.summon ~= "done" then return end
end
if clone ~= nil and clone ~= S.copyUnit then
S.copyUnit = clone
S.copy = A.newUnitState()
S.cloneReadyAt = now + 0.25
S.turn = false
A.log("info", "arc double found", { distance = A.distance(hero, clone), ready_in = 0.25 })
end
if clone ~= nil and now < S.cloneReadyAt then return end
if not NPC.IsChannellingAbility(hero) and not IT.heroDisabled(hero) and A.useDoubleLegend(hero, clone, now) then return end
S.turn = not S.turn
if S.turn and clone ~= nil and A.runUnit(clone, S.copy, S.target, now, false) then return end
if A.runUnit(hero, S.main, S.target, now, true) then return end
if not S.turn and clone ~= nil then A.runUnit(clone, S.copy, S.target, now, false) end
end
function A.drawError()
local title = S.menuError and localization.Get("panel.menu_failed") or localization.Get("panel.error")
local message = S.menuError or S.error or "unknown"
Render.FilledRect(Vec2(20, 370), Vec2(780, 418), Color(20, 20, 24, 235), 4)
Render.Text(S.font, 14, title, Vec2(30, 377), Color(224, 50, 45, 245))
Render.Text(S.font, 12, message:sub(1, 160), Vec2(30, 397), Color(220, 220, 225, 240))
end
function script.OnScriptsLoaded()
local ok, result = pcall(A.initMenu)
S.ready = ok and result == true
if not S.ready then S.menuError = ok and "initMenu returned false" or tostring(result) end
S.font = Render.LoadFont("MuseoSansEx", 0, 500)
A.log("info", "arc_warden_1x6_combo loaded", { ready = S.ready, error = S.menuError })
end
function script.OnUpdate()
if not S.ready or not Engine.IsInGame() then return end
local ok, err = pcall(A.update)
if not ok then
if S.error == nil then A.log("error", "arc combo update failed", { error = tostring(err) }) end
S.error = tostring(err)
A.reset("error", true)
end
end
function script.OnPrepareUnitOrders(data)
if not S.ready or S.phase ~= "running" or data == nil or data.npc == nil then return true end
local hero = Heroes.GetLocal()
if data.npc == hero or data.npc == S.clone then
S.manual = true
S.phase = "manual"
A.log("info", "arc combo manual override", { order = data.order, unit = data.npc == S.clone and "double" or "main" })
end
return true
end
function script.OnModifierCreate(entity, modifier)
if not S.ready or entity == nil or modifier == nil then return end
local ok, err = pcall(A.sparkCreated, entity, modifier)
if not ok and S.error == nil then S.error = tostring(err) end
end
function script.OnModifierDestroy(entity, modifier)
if not S.ready or entity == nil or modifier == nil then return end
local ok, err = pcall(A.sparkDestroyed, entity, modifier)
if not ok and S.error == nil then S.error = tostring(err) end
end
function script.OnGameEnd()
A.reset("game end", true)
S.w4, S.w4Probe = false, {}
S.cloneLock, S.cloneKeyDown = nil, false
IT.reset()
S.legend = nil
S.legends = {}
S.legendAt = 0
S.itemSig = ""
S.itemIds = {}
S.itemAt = 0
S.itemError = nil
S.error = nil
end
function A.drawFrame()
if S.menuError ~= nil or S.error ~= nil then A.drawError() end
end
function script.OnDraw()
local ok, err = pcall(A.drawFrame)
if not ok and S.error == nil then
S.error = tostring(err)
A.log("error", "arc combo draw failed", { error = S.error })
end
end
return script
end)
if ok and type(result) == "table" then
modules[#modules + 1] = { name = "arc_warden_1x6_combo", script = result, loadMs = pack_clock and (pack_clock() - started) * 1000 or 0 }
else
failed_load["arc_warden_1x6_combo"] = tostring(result)
end
end
