function A.base(name)
return (name:gsub("^item_", ""):gsub("_custom$", ""))
end
function A.label(name)
return (A.base(name):gsub("_", " "))
end
function A.kind(h)
local b, bit = Ability.GetBehavior(h), C.bits
if A.has(b, bit.passive) or A.has(b, bit.hidden) or A.has(b, bit.toggle) then return nil end
if A.has(b, bit.unit) then
local team = Ability.GetTargetTeam(h)
if A.has(team, 2) then return "enemy" end
if A.has(team, 1) then return "self" end
return nil
end
if A.has(b, bit.point) then return "point" end
if A.has(b, bit.no) then return "no" end
return nil
end
function A.skipped(name)
for _, frag in ipairs(C.itemSkip) do
if name:find(frag, 1, true) ~= nil then return true end
end
return false
end
function A.refreshItems(hero)
local labels, ids, sig = {}, {}, ""
for _, slot in ipairs(C.slots) do
local h = NPC.GetItemByIndex(hero, slot)
if h ~= nil then
local name = Ability.GetName(h)
local label = A.label(name)
if not A.skipped(name) and A.kind(h) ~= nil and ids[label] == nil then
labels[#labels + 1] = label
ids[label] = name
sig = sig .. label .. ","
end
end
end
if sig == S.sig then return end
local rank = {}
for i, id in ipairs(UI.items:List()) do rank[id] = i end
table.sort(labels, function(a, b) return (rank[a] or 1000) < (rank[b] or 1000) end)
local rows = {}
for i, label in ipairs(labels) do
local on = true
if S.seen[label] then on = UI.items:Get(label) == true end
local base = A.base(ids[label])
rows[i] = { label, "panorama/images/items/" .. (C.iconFix[base] or base) .. "_png.vtex_c", on }
end
UI.items:Update(rows, true, true)
S.sig, S.ids = sig, ids
for _, label in ipairs(labels) do S.seen[label] = true end
A.fillOctarine(labels, ids)
end
function A.fillOctarine(labels, ids)
local keep = UI.octarine:ListEnabled()[1]
if not S.octSynced then keep, S.octSynced = UI.saveOctarine:Get(), true end
local picks, found = {}, false
for _, label in ipairs(labels) do
if ids[label]:find("octarine_core", 1, true) == nil then
local base = A.base(ids[label])
picks[#picks + 1] = { label, "panorama/images/items/" .. (C.iconFix[base] or base) .. "_png.vtex_c", label == keep }
if label == keep then found = true end
end
end
UI.octarine:Update(picks, true, true)
UI.octarine:Set(found and { keep } or {})
end
function A.camps()
if S.camps ~= nil and #S.camps > 0 then return S.camps end
local list = {}
for _, handle in pairs(Camps.GetAll() or {}) do
local box = Camp.GetCampBox(handle)
if box ~= nil and box.min ~= nil and box.max ~= nil then
local pos = Vector((box.min.x + box.max.x) * 0.5, (box.min.y + box.max.y) * 0.5, (box.min.z + box.max.z) * 0.5)
local extent = math.max(math.abs(box.max.x - box.min.x), math.abs(box.max.y - box.min.y)) * 0.5
list[#list + 1] = { pos = pos, radius = math.max(C.campInside, extent + 150), kind = Camp.GetType(handle), index = #list + 1 }
end
end
S.camps = list
A.log("info", "arc farm camps mapped", { count = #list })
return list
end
function A.neutrals(unit, camp, slack)
local out = {}
for _, n in ipairs(NPCs.InRadius(camp.pos, camp.radius + (slack or 0), Entity.GetTeamNum(unit), C.teamBoth, true, true) or {}) do
if NPC.IsNeutral(n) and Entity.IsAlive(n) and not NPC.IsWaitingToSpawn(n) then out[#out + 1] = n end
end
return out
end
function A.nextSpawn(now)
local t = GameRules.GetDOTATime(false, false)
if type(t) ~= "number" then return now + 30 end
return now + (60 - t % 60) + C.spawnSlack
end
function A.clock()
local t = GameRules.GetDOTATime(false, false)
if type(t) ~= "number" then return nil, nil end
return t % 60, math.floor(t / 60)
end
function A.findDouble(hero)
for _, unit in ipairs(Heroes.GetAll() or {}) do
if unit ~= nil and unit ~= hero and NPC.GetUnitName(unit) == C.hero and Entity.IsAlive(unit) and Entity.IsSameTeam(hero, unit) then
for _, mod in ipairs(C.doubleMods) do
if NPC.HasModifier(unit, mod) then return unit end
end
end
end
return nil
end
function A.order(unit, st, now, kind, target, pos)
if now < st.orderAt then return end
st.orderAt = now + C.orderGap
local player = Players.GetLocal()
if player == nil then return end
if kind == C.orderAttack then pos = Entity.GetAbsOrigin(target) end
S.selfAt = now
Player.PrepareUnitOrders(player, kind, target, pos, nil, C.issuer, unit, false, false, false, false, C.identifier)
end
function A.radius()
return math.huge
end
function A.groups()
if S.groups ~= nil then return S.groups end
local camps, list, seen = A.camps(), {}, {}
for a = 1, #camps do
for b = a + 1, #camps do
for c = b + 1, #camps do
local pa, pb, pc = camps[a].pos, camps[b].pos, camps[c].pos
if (pa - pb):Length2D() <= C.mergeRadius and (pa - pc):Length2D() <= C.mergeRadius and (pb - pc):Length2D() <= C.mergeRadius then
local key = a .. "," .. b .. "," .. c
if not seen[key] then
seen[key] = true
local center = Vector((pa.x + pb.x + pc.x) / 3, (pa.y + pb.y + pc.y) / 3, pa.z)
if (pa - center):Length2D() <= C.mergeSpread and (pb - center):Length2D() <= C.mergeSpread and (pc - center):Length2D() <= C.mergeSpread then
list[#list + 1] = { camps = { a, b, c }, center = center }
end
end
end
end
end
end
S.groups = list
A.log("info", "arc farm merge groups", { count = #list })
return list
end
function A.kindOn(kind)
local id = S.kindIds ~= nil and S.kindIds[kind] or nil
return id == nil or UI.kinds:Get(id) == true
end
function A.campOpen(i, now, heroPos, radius)
local camp = A.camps()[i]
local kind = type(camp.kind) == "number" and camp.kind or 1
local avoided = S.avoidPos ~= nil and now < S.avoidUntil and (camp.pos - S.avoidPos):Length2D() <= C.avoidRadius
return now >= (S.cleared[i] or 0) and not S.illClaim[i] and not avoided and A.kindOn(kind) and (camp.pos - heroPos):Length2D() <= radius, kind
end
function A.jobs(hero, now, exclude)
local heroPos = Entity.GetAbsOrigin(hero)
local radius, tier = A.radius(), nil
local list, grouped = {}, {}
if UI.merge:Get() then
for _, g in ipairs(A.groups()) do
local ok, value, clear = true, 0, 0
for _, i in ipairs(g.camps) do
local open, kind = A.campOpen(i, now, heroPos, radius, tier)
if not open or exclude[i] then
ok = false
break
end
value = value + (C.campValue[kind] or 1)
clear = math.max(clear, C.campClear[kind] or 8)
end
if ok then
list[#list + 1] = { type = "merge", camps = g.camps, pos = g.center, value = value * 1.15, clear = clear + 6 }
for _, i in ipairs(g.camps) do grouped[i] = true end
end
end
end
for i, camp in ipairs(A.camps()) do
local open, kind = A.campOpen(i, now, heroPos, radius, tier)
if open and not exclude[i] then
local stacks = S.stacks[i] or 0
local small = kind == 0 and stacks == 0
list[#list + 1] = {
type = small and "drive" or "camp", camps = { i }, pos = camp.pos,
value = (C.campValue[kind] or 1) * (1 + stacks * C.stackBonus),
clear = small and 3 or (C.campClear[kind] or 8) * (1 + stacks * 0.6),
}
end
end
return list
end
function A.pickJob(hero, unit, now, current)
local memo = S.pickMemo
if memo ~= nil and memo.at == now and memo.cur == current and memo.unit == unit then return memo.res end
local res = A.pickJobRaw(hero, unit, now, current)
S.pickMemo = { at = now, cur = current, unit = unit, res = res }
return res
end
function A.pickJobRaw(hero, unit, now, current)
local exclude = {}
if current ~= nil then
for _, i in ipairs(current.camps) do exclude[i] = true end
end
local jobs = A.jobs(hero, now, exclude)
local origin = Entity.GetAbsOrigin(unit)
local best, bestDist = nil, nil
for _, job in ipairs(jobs) do
local d = (job.pos - origin):Length2D()
if bestDist == nil or d < bestDist then best, bestDist = job, d end
end
return best
end
function A.ready(unit, h)
return h ~= nil and Ability.GetLevel(h) > 0 and not Ability.IsHidden(h) and Ability.IsReady(h)
and Ability.GetCooldown(h) <= 0 and Ability.IsCastable(h, NPC.GetMana(unit))
end
function A.fieldPoint(unit, h, origin, center)
local ok, radius = pcall(Ability.GetLevelSpecialValueFor, h, "radius", -1)
if not ok or type(radius) ~= "number" or radius <= 0 then radius = C.fieldRadius end
local dir = origin - center
local len = dir:Length2D()
if len < 1 then return origin end
local k = math.max(0, radius - C.fieldInset)
return Vector(origin.x + dir.x / len * k, origin.y + dir.y / len * k, origin.z)
end
function A.castSpells(unit, st, now, creeps)
local origin = Entity.GetAbsOrigin(unit)
local nearDist, fattest = nil, nil
local cx, cy = 0, 0
for _, c in ipairs(creeps) do
local p = Entity.GetAbsOrigin(c)
cx, cy = cx + p.x, cy + p.y
local d = (p - origin):Length2D()
if nearDist == nil or d < nearDist then nearDist = d end
if fattest == nil or Entity.GetHealth(c) > Entity.GetHealth(fattest) then fattest = c end
end
local center = Vector(cx / #creeps, cy / #creeps, origin.z)
local dagon = A.useDagon(unit, now, creeps)
if dagon ~= nil then return Ability.GetName(dagon), dagon end
local dagonWait = A.dagonReady(unit, creeps)
for _, s in ipairs(C.spells) do
if UI.spells:Get(s.t) then
local h = NPC.GetAbility(unit, s.n)
if A.ready(unit, h) then
local b = Ability.GetBehavior(h)
local range = Ability.GetCastRange(h)
local mode = nil
if s.n == "arc_warden_magnetic_field_custom" then
if nearDist <= A.attackRange(unit) + 100 then mode = A.has(b, C.bits.point) and "self" or "no" end
elseif s.n == "arc_warden_flux_custom" then
if A.has(b, C.bits.unit) and (range <= 0 or (Entity.GetAbsOrigin(fattest) - origin):Length2D() <= range + 50)
and not A.saveFlux(unit, st, now, h, creeps) then
mode = "target"
end
elseif range <= 0 or (center - origin):Length2D() <= range then
mode = "center"
end
if mode ~= nil and mode ~= "center" and dagonWait then mode = nil end
if mode ~= nil then
if mode == "self" then
Ability.CastPosition(h, A.fieldPoint(unit, h, origin, center), false, false, true, C.identifier)
elseif mode == "no" then
Ability.CastNoTarget(h, false, false, true, C.identifier)
elseif mode == "target" then
Ability.CastTarget(h, fattest, false, false, true, C.identifier)
else
Ability.CastPosition(h, center, false, false, true, C.identifier)
end
return s.n, h
end
end
end
end
for _, label in ipairs(UI.items:ListEnabled()) do
local name = S.ids[label]
if name ~= nil and not A.special(name) then
local h = nil
for _, slot in ipairs(C.slots) do
local it = NPC.GetItemByIndex(unit, slot)
if it ~= nil and Ability.GetName(it) == name then h = it end
end
if A.ready(unit, h) then
local kind = A.kind(h)
local range = Ability.GetCastRange(h)
local target = kind == "enemy" and fattest or nil
local dist = target ~= nil and (Entity.GetAbsOrigin(target) - origin):Length2D() or (center - origin):Length2D()
if kind ~= nil and (kind == "no" or kind == "self" or range <= 0 or dist <= range + 50) then
local oct = A.octFor(unit, now, label)
if oct ~= nil then return Ability.GetName(oct), oct end
if kind == "enemy" then
Ability.CastTarget(h, target, false, false, true, C.identifier)
elseif kind == "self" then
Ability.CastTarget(h, unit, false, false, true, C.identifier)
elseif kind == "point" then
Ability.CastPosition(h, center, false, false, true, C.identifier)
else
Ability.CastNoTarget(h, false, false, true, C.identifier)
end
return name, h
end
end
end
end
return nil, nil
end
function A.latency()
local ok, value = false, nil
if C.latency ~= nil then ok, value = pcall(C.latency) end
if not ok or type(value) ~= "number" or value < 0 then value = 0.06 end
return math.max(C.minLatency, value)
end
function A.attackRange(unit)
local range = NPC.GetAttackRange(unit)
if C.rangeBonus ~= nil then range = range + (C.rangeBonus(unit) or 0) end
return range
end
function A.attackTiming(unit)
local point = C.animPoint ~= nil and C.animPoint(unit) or 0.3
local spa = C.secondsPerAttack ~= nil and C.secondsPerAttack(unit, false) or 1.5
return point, spa
end
function A.visibleCreeps(unit, camp, slack)
local out = {}
for _, n in ipairs(A.neutrals(unit, camp, slack)) do
if NPC.IsVisible(n) then out[#out + 1] = n end
end
return out
end
function A.underAttack(unit, st, now)
local hp = Entity.GetHealth(unit)
if st.hp ~= nil and hp < st.hp then st.hitAt = now end
st.hp = hp
return now - (st.hitAt or -10) <= C.hitMemory
end
function A.newState()
return { orderAt = 0, castAt = 0, phase = "idle", camp = nil, stacked = -1, launchAt = -10, attackAt = -10, target = nil, spelled = false, known = {} }
end
function A.live(h)
if h == nil then return false end
local ok, alive = pcall(Entity.IsAlive, h)
return ok and alive
end
function A.track(st, creeps, now)
for _, c in ipairs(creeps) do
st.known[Entity.GetIndex(c)] = { h = c, pos = Entity.GetAbsOrigin(c), at = now }
end
end
function A.targets(unit, st, now)
local visible, hidden, hiddenDist = {}, nil, nil
local origin = Entity.GetAbsOrigin(unit)
for id, k in pairs(st.known) do
local alive = A.live(k.h) and not NPC.IsWaitingToSpawn(k.h)
if not alive or now - k.at > C.knownFor then
if not alive and (k.pos - origin):Length2D() <= C.chaseReach then A.creditKill(k, now) end
st.known[id] = nil
elseif NPC.IsVisible(k.h) and (Entity.GetAbsOrigin(k.h) - origin):Length2D() <= C.chaseReach then
k.pos, k.at = Entity.GetAbsOrigin(k.h), now
visible[#visible + 1] = k.h
else
if NPC.IsVisible(k.h) then k.pos, k.at = Entity.GetAbsOrigin(k.h), now end
local d = (k.pos - origin):Length2D()
if hiddenDist == nil or d < hiddenDist then hidden, hiddenDist = k, d end
end
end
return visible, hidden
end
function A.chase(unit, st, now, hidden)
if hidden == nil then return false end
if st.chaseLogged ~= hidden.h then
st.chaseLogged = hidden.h
A.log("info", "arc farm chase hidden creep", { dist = math.floor((hidden.pos - Entity.GetAbsOrigin(unit)):Length2D()) })
end
A.order(unit, st, now, C.orderMove, nil, hidden.pos)
return true
end
function A.leaveCamp(st, reason, skipUntil)
S.pickMemo = nil
if st.job ~= nil and skipUntil ~= nil then
for _, i in ipairs(st.job.camps) do
S.cleared[i] = skipUntil
if skipUntil > GameRules.GetGameTime() + 10 then S.stacks[i] = 0 end
end
end
A.log("info", "arc farm left job", { job = st.job and st.job.type or "none", camps = st.job and #st.job.camps or 0, reason = reason })
st.job, st.camp, st.phase, st.target, st.spelled, st.known = nil, nil, "idle", nil, false, {}
end
function A.spark(unit)
local h = NPC.GetAbility(unit, C.spark)
if h == nil or Ability.GetLevel(h) <= 0 or not UI.spells:Get("Spark Wraith") then return nil end
return h
end
function A.creepsNear(unit, pos, radius)
local out = {}
for _, n in ipairs(NPCs.InRadius(pos, radius, Entity.GetTeamNum(unit), C.teamBoth, true, true) or {}) do
if NPC.IsNeutral(n) and Entity.IsAlive(n) and not NPC.IsWaitingToSpawn(n) and NPC.IsVisible(n) then out[#out + 1] = n end
end
return out
end
function A.centroid(list, fallback)
if #list == 0 then return fallback end
local x, y = 0, 0
for _, c in ipairs(list) do
local p = Entity.GetAbsOrigin(c)
x, y = x + p.x, y + p.y
end
return Vector(x / #list, y / #list, fallback.z)
end
function A.fattest(list)
local best = nil
for _, c in ipairs(list) do
if best == nil or Entity.GetHealth(c) > Entity.GetHealth(best) then best = c end
end
return best
end
function A.stepDrive(unit, st, now, camp)
local origin = Entity.GetAbsOrigin(unit)
local creeps = A.visibleCreeps(unit, camp, C.emptySlack)
A.track(st, creeps, now)
if st.engaged and now - st.jobAt > C.driveTimeout then
A.leaveCamp(st, "drive timeout", A.nextSpawn(now))
return
end
if st.phase == "travel" then st.phase = "spark1" end
local spark = A.spark(unit)
if st.phase == "spark1" then
if #creeps == 0 then
if C.pointVisible ~= nil and C.pointVisible(camp.pos) then
A.leaveCamp(st, "seen empty", A.nextSpawn(now))
else
A.travel(unit, st, now, camp.pos)
end
return
end
if not st.engaged then st.engaged, st.jobAt = true, now end
if spark == nil or (not A.ready(unit, spark) and Ability.GetCooldown(spark) > 2) then
st.phase = "flux"
elseif A.ready(unit, spark) then
local aim = A.centroid(creeps, camp.pos)
if (aim - origin):Length2D() <= Ability.GetCastRange(spark) then
S.selfAt = now
Ability.CastPosition(spark, aim, false, false, true, C.identifier)
st.phase, st.orderAt = "flux", now + Ability.GetCastPoint(spark) + C.castGap
A.log("info", "arc farm drive spark", { camp = st.camp })
else
A.order(unit, st, now, C.orderMove, nil, aim)
end
return
else
A.order(unit, st, now, C.orderMove, nil, camp.pos)
return
end
end
if st.engaged and now >= st.castAt then
local near = A.targets(unit, st, now)
if A.useDagon(unit, now, near) ~= nil then
st.castAt = now + C.castGap
return
end
end
if st.phase == "flux" then
local flux = NPC.GetAbility(unit, C.flux)
local usable = flux ~= nil and UI.spells:Get("Flux") and A.ready(unit, flux) and A.has(Ability.GetBehavior(flux), C.bits.unit)
local fight, hidden = A.targets(unit, st, now)
if not usable then
st.phase, st.sparkAt = "spark2", now
elseif #fight == 0 then
if not A.chase(unit, st, now, hidden) then A.leaveCamp(st, "drive done", A.nextSpawn(now)) end
return
else
local target = A.fattest(fight)
local range = Ability.GetCastRange(flux)
if (Entity.GetAbsOrigin(target) - origin):Length2D() <= range + 50 then
if A.dagonReady(unit, fight) then
A.order(unit, st, now, C.orderMove, nil, Entity.GetAbsOrigin(target))
elseif now >= st.orderAt then
S.selfAt = now
Ability.CastTarget(flux, target, false, false, true, C.identifier)
st.phase, st.sparkAt, st.orderAt = "spark2", now, now + Ability.GetCastPoint(flux) + C.castGap
A.log("info", "arc farm drive flux", { camp = st.camp })
end
else
A.order(unit, st, now, C.orderMove, nil, Entity.GetAbsOrigin(target))
end
return
end
end
if st.phase == "spark2" then
local near = A.creepsNear(unit, camp.pos, camp.radius + 600)
A.track(st, near, now)
if #near <= 1 or spark == nil or now - st.sparkAt > C.sparkWait then
st.phase, st.target = "finish", nil
return
end
if A.ready(unit, spark) and now >= st.orderAt then
local aim = A.centroid(near, camp.pos)
if (aim - camp.pos):Length2D() > camp.radius then aim = camp.pos end
S.selfAt = now
Ability.CastPosition(spark, aim, false, false, true, C.identifier)
A.log("info", "arc farm drive finish spark", { camp = st.camp, creeps = #near })
st.phase, st.target, st.orderAt = "finish", nil, now + Ability.GetCastPoint(spark) + C.castGap
return
end
end
if st.phase == "finish" or st.phase == "spark2" then
A.track(st, A.visibleCreeps(unit, camp), now)
local fight, hidden = A.targets(unit, st, now)
if #fight == 0 then
if A.chase(unit, st, now, hidden) then return end
A.leaveCamp(st, "drive done", A.nextSpawn(now))
return
end
local target = fight[1]
for _, c in ipairs(fight) do
if Entity.GetHealth(c) < Entity.GetHealth(target) then target = c end
end
if st.target ~= target or now - st.attackAt > 2 then
st.target, st.attackAt, st.orderAt = target, now, 0
A.order(unit, st, now, C.orderAttack, target)
end
end
end
function A.stepMerge(hero, unit, st, now, hit)
local job, camps, origin = st.job, A.camps(), Entity.GetAbsOrigin(unit)
if now - st.jobAt > C.mergeTimeout then
A.leaveCamp(st, "merge timeout", now + 5)
return
end
if st.phase == "travel" then
table.sort(job.camps, function(a, b) return (camps[a].pos - origin):Length2D() < (camps[b].pos - origin):Length2D() end)
st.phase, st.step = "hit", 1
end
if st.phase == "hit" then
local camp = camps[job.camps[st.step]]
local creeps = A.visibleCreeps(unit, camp)
if st.step == 3 then
local spark = A.spark(unit)
if spark ~= nil and A.ready(unit, spark) and (camp.pos - origin):Length2D() <= Ability.GetCastRange(spark) then
S.selfAt = now
Ability.CastPosition(spark, A.centroid(creeps, camp.pos), false, false, true, C.identifier)
st.phase, st.gatherAt, st.orderAt = "gather", now, now + Ability.GetCastPoint(spark) + C.castGap
A.log("info", "arc farm merge spark", { camp = job.camps[3] })
return
end
if spark ~= nil and Ability.GetCooldown(spark) <= 2 then return end
end
if #creeps == 0 then
if C.pointVisible ~= nil and C.pointVisible(camp.pos) then
st.step = st.step + 1
if st.step > 3 then st.phase, st.gatherAt = "gather", now end
else
A.travel(unit, st, now, camp.pos)
end
return
end
local target = creeps[1]
for _, c in ipairs(creeps) do
if (Entity.GetAbsOrigin(c) - origin):Length2D() < (Entity.GetAbsOrigin(target) - origin):Length2D() then target = c end
end
if st.launchAt > st.attackAt and st.target == target then
A.log("info", "arc farm merge aggro", { camp = job.camps[st.step] })
st.step, st.target = st.step + 1, nil
if st.step > 3 then st.phase, st.gatherAt = "gather", now end
return
end
if st.target ~= target then
st.target, st.attackAt, st.orderAt = target, now, 0
A.order(unit, st, now, C.orderAttack, target)
end
return
end
if st.phase == "gather" then
local near = A.creepsNear(unit, origin, 500)
if (job.pos - origin):Length2D() > 150 then
A.order(unit, st, now, C.orderMove, nil, job.pos)
end
if #near >= 3 or now - st.gatherAt > C.gatherWait then
st.phase, st.target, st.orderAt = "fight", nil, 0
A.log("info", "arc farm merge fight", { creeps = #near })
end
return
end
A.track(st, A.creepsNear(unit, job.pos, C.mergeRadius), now)
local creeps, hidden = A.targets(unit, st, now)
if #creeps == 0 then
if A.chase(unit, st, now, hidden) then return end
local seenAll = true
for _, i in ipairs(job.camps) do
if C.pointVisible == nil or not C.pointVisible(camps[i].pos) then seenAll = false end
end
if seenAll or now - st.jobAt > 8 then A.leaveCamp(st, "merge cleared", A.nextSpawn(now)) end
return
end
if A.stepCast(unit, st, now, creeps) then return end
A.stepAttack(hero, unit, st, now, creeps, hit)
end
function A.stepTravel(hero, unit, st, now, camp)
local creeps = A.visibleCreeps(unit, camp, C.emptySlack)
if #creeps > 0 then
st.phase = "fight"
return false
end
if C.pointVisible ~= nil and C.pointVisible(camp.pos) then
A.leaveCamp(st, "seen empty", A.nextSpawn(now))
return true
end
local next = A.pickJob(hero, unit, now, st.job)
local here = Entity.GetAbsOrigin(unit)
if next ~= nil and (next.pos - here):Length2D() + C.switchGain < (camp.pos - here):Length2D() then
A.leaveCamp(st, "nearer camp", nil)
return true
end
if A.travelSpark(unit, st, now, camp) then return true end
A.travel(unit, st, now, camp.pos)
return true
end
function A.travelSpark(unit, st, now, camp)
local spark = A.spark(unit)
if spark == nil or now < st.castAt or now < st.orderAt or not A.ready(unit, spark) then return false end
if (camp.pos - Entity.GetAbsOrigin(unit)):Length2D() > Ability.GetCastRange(spark) then return false end
S.selfAt = now
Ability.CastPosition(spark, camp.pos, false, false, true, C.identifier)
st.castAt = now + Ability.GetCastPoint(spark) + C.castGap
st.orderAt = st.castAt
A.log("info", "arc farm travel spark", { camp = st.camp })
return true
end
function A.clearTime(unit, creeps)
local hp = 0
for _, c in ipairs(creeps) do hp = hp + Entity.GetHealth(c) end
local _, spa = A.attackTiming(unit)
local dps = math.max(1, NPC.GetTrueDamage(unit)) / math.max(0.2, spa)
return hp / dps
end
function A.respawnPoint(camp, origin)
local dir = origin - camp.pos
local len = dir:Length2D()
if len < 1 then dir, len = Vector(1, 0, 0), 1 end
local k = camp.radius + 60
return Vector(camp.pos.x + dir.x / len * k, camp.pos.y + dir.y / len * k, camp.pos.z)
end
function A.stepRespawn(unit, st, now, camp, sec, minute)
if st.phase ~= "respawn" then return false end
if minute == nil or sec == nil or (minute > st.waitMinute and sec >= C.spawnSlack) or now > st.waitUntil then
st.phase, st.orderAt, st.known = "travel", 0, {}
A.log("info", "arc farm refarm", { camp = st.camp })
return false
end
A.order(unit, st, now, C.orderMove, nil, A.respawnPoint(camp, Entity.GetAbsOrigin(unit)))
return true
end
function A.blink(unit)
local h = A.findItem(unit, "blink")
if h ~= nil and A.kind(h) == "point" then return h end
return nil
end
function A.travel(unit, st, now, pos)
local origin = Entity.GetAbsOrigin(unit)
local dist = (pos - origin):Length2D()
local h = dist > C.blinkMin and A.blink(unit) or nil
if h ~= nil and now >= st.orderAt then
local jump = math.min(Ability.GetCastRange(h), dist - C.blinkShort)
if jump >= C.blinkMin - C.blinkShort then
local dir = pos - origin
S.selfAt = now
Ability.CastPosition(h, Vector(origin.x + dir.x / dist * jump, origin.y + dir.y / dist * jump, origin.z), false, false, true, C.identifier)
st.orderAt = now + C.orderGap
S.selfJumpAt = now + 1
A.log("info", "arc farm blink", { jump = math.floor(jump) })
return
end
end
A.order(unit, st, now, C.orderMove, nil, pos)
end
function A.stepRune(unit, st, now)
local idle = st.job == nil or st.phase == "travel" or (st.phase == "spark1" and not st.engaged)
if not idle or A.api(Runes, "GetAll") == nil then return false end
local origin, best, bestDist = Entity.GetAbsOrigin(unit), nil, C.runeReach
for _, r in ipairs(Runes.GetAll() or {}) do
if Runes.Contains(r) and not Entity.IsDormant(r) and Rune.GetRuneType(r) == C.runeBounty and now >= (S.runeSkip[r] or 0) then
local d = (Entity.GetAbsOrigin(r) - origin):Length2D()
if d < bestDist then best, bestDist = r, d end
end
end
if best == nil then
st.rune = nil
return false
end
if st.rune ~= best then
st.rune, st.runeAt = best, now
A.log("info", "arc farm bounty rune", { dist = math.floor(bestDist) })
end
if now - st.runeAt > C.runeTimeout then
S.runeSkip[best] = now + C.runeSkip
return false
end
if bestDist > C.blinkMin then
A.travel(unit, st, now, Entity.GetAbsOrigin(best))
else
A.order(unit, st, now, C.orderPickupRune, best, Entity.GetAbsOrigin(best))
end
return true
end
function A.special(name)
for _, frag in ipairs(C.special) do
if name:find(frag, 1, true) ~= nil then return true end
end
return false
end
function A.itemOn(frag)
for _, label in ipairs(UI.items:ListEnabled()) do
local name = S.ids[label]
if name ~= nil and name:find(frag, 1, true) ~= nil then return true end
end
return false
end
function A.findItem(unit, frag)
if not A.itemOn(frag) then return nil end
for _, slot in ipairs(C.slots) do
local it = NPC.GetItemByIndex(unit, slot)
if it ~= nil and Ability.GetName(it):find(frag, 1, true) ~= nil and A.ready(unit, it) then return it end
end
return nil
end
function A.octFor(unit, now, label)
if NPC.HasModifier(unit, C.octActive) then return nil end
local pick = UI.octarine:ListEnabled()[1]
if pick ~= nil and pick ~= label then return nil end
local h = A.findItem(unit, "octarine_core")
if h == nil or A.kind(h) ~= "no" then return nil end
S.selfAt = now
Ability.CastNoTarget(h, false, false, true, C.identifier)
A.log("info", "arc farm octarine", { before = label })
return h
end
function A.dagonReady(unit, creeps)
if #creeps < C.dagonMin then return false end
local h = A.findItem(unit, "dagon")
return h ~= nil and A.kind(h) == "enemy"
end
function A.useDagon(unit, now, creeps)
if #creeps < C.dagonMin then return nil end
local h = A.findItem(unit, "dagon")
if h == nil or A.kind(h) ~= "enemy" then return nil end
local origin, range = Entity.GetAbsOrigin(unit), Ability.GetCastRange(h)
local best, bestN = nil, 0
for _, c in ipairs(creeps) do
local p = Entity.GetAbsOrigin(c)
if (p - origin):Length2D() <= range + 50 then
local n = 0
for _, o in ipairs(creeps) do
if (Entity.GetAbsOrigin(o) - p):Length2D() <= C.dagonRadius then n = n + 1 end
end
if n > bestN then best, bestN = c, n end
end
end
if best == nil then return nil end
local oct = A.octFor(unit, now, A.label(Ability.GetName(h)))
if oct ~= nil then return oct end
S.selfAt = now
Ability.CastTarget(h, best, false, false, true, C.identifier)
A.log("info", "arc farm dagon", { creeps = #creeps, hit = bestN })
return h
end
function A.smallCamp(pos, st, now, reach)
local skip = {}
if st ~= nil and st.job ~= nil then
for _, i in ipairs(st.job.camps) do skip[i] = true end
end
local best, bestDist = nil, reach
for i, camp in ipairs(A.camps()) do
if camp.kind == 0 and not skip[i] and not S.illClaim[i] and now >= (S.cleared[i] or 0) then
local d = (camp.pos - pos):Length2D()
if d < bestDist then best, bestDist = i, d end
end
end
return best
end
function A.stepFlicker(unit, st, now)
if now < st.castAt then return false end
local h = NPC.GetAbility(unit, C.fieldLegend)
if h == nil or Ability.IsHidden(h) or not A.ready(unit, h) then return false end
local mod = NPC.GetModifier(unit, C.fieldMod)
if mod == nil then return false end
local left = Modifier.GetDieTime(mod) - now
local origin = Entity.GetAbsOrigin(unit)
local refresh = left <= C.flickerLast + A.latency()
local helper = S.illCount == 0 and A.smallCamp(origin, st, now, C.flickerReach) ~= nil
if not refresh and not helper then return false end
S.selfAt = now
if A.has(Ability.GetBehavior(h), C.bits.point) then
Ability.CastPosition(h, Vector(origin.x + 1, origin.y, origin.z), false, false, true, C.identifier)
else
Ability.CastNoTarget(h, false, false, true, C.identifier)
end
st.castAt, st.orderAt, st.target = now + 0.7, now + 0.7, nil
S.adoptUntil = now + C.adoptFor
A.log("info", "arc farm flicker", { left = math.floor(left * 10) / 10, reason = refresh and "refresh" or "illusion" })
return true
end
function A.stepManta(unit, st, now)
if now < st.castAt or S.illCount > 0 or st.job == nil then return false end
if A.smallCamp(Entity.GetAbsOrigin(unit), st, now, C.mantaReach) == nil then return false end
local it = A.findItem(unit, "manta")
if it == nil then return false end
S.selfAt = now
Ability.CastNoTarget(it, false, false, true, C.identifier)
st.castAt, st.target = now + 0.3, nil
S.adoptUntil = now + C.adoptFor
A.log("info", "arc farm manta", {})
return true
end
function A.stepIllusion(u, s, st, now, claim)
local camps, pos = A.camps(), Entity.GetAbsOrigin(u)
if s.camp ~= nil then
local camp = camps[s.camp]
if claim[s.camp] or (#A.visibleCreeps(u, camp) == 0 and C.pointVisible ~= nil and C.pointVisible(camp.pos)) then
if not claim[s.camp] then S.cleared[s.camp] = A.nextSpawn(now) end
s.camp, s.orderAt = nil, 0
end
end
if s.camp == nil then
S.illClaim = claim
s.camp = A.smallCamp(pos, st, now, C.illReach)
if s.camp ~= nil then A.log("info", "arc farm illusion camp", { camp = s.camp }) end
end
local dest = s.camp ~= nil and camps[s.camp].pos or (st.job ~= nil and st.job.pos) or nil
if s.camp ~= nil then claim[s.camp] = true end
if dest == nil or now < s.orderAt then return end
s.orderAt = now + C.illOrderGap
local player = Players.GetLocal()
if player == nil then return end
Player.PrepareUnitOrders(player, C.orderAttackMove, nil, dest, nil, C.issuer, u, false, false, false, false, C.identifier)
end
function A.runIllusions(hero, unit, now)
local player = Players.GetLocal()
local pid = player ~= nil and Player.GetPlayerID(player) or -1
local alive, claim, count = {}, {}, 0
local dpos = Entity.GetAbsOrigin(unit)
for _, u in ipairs(Heroes.GetAll() or {}) do
if u ~= nil and u ~= hero and u ~= unit and NPC.GetUnitName(u) == C.hero and Entity.IsAlive(u) and NPC.IsIllusion(u)
and NPC.IsControllableByPlayer(u, pid) then
local id = Entity.GetIndex(u)
local s = S.ill[id]
if s == nil and now < S.adoptUntil and (Entity.GetAbsOrigin(u) - dpos):Length2D() <= C.adoptRadius then
s = { orderAt = 0 }
A.log("info", "arc farm illusion adopted", { id = id })
end
if s ~= nil then
alive[id], count = s, count + 1
if S.st ~= nil then A.stepIllusion(u, s, S.st, now, claim) end
end
end
end
S.ill, S.illClaim, S.illCount = alive, claim, count
end
function A.saveFlux(unit, st, now, flux, creeps)
local hero = Heroes.GetLocal()
if hero == nil or st.job == nil or st.job.type == "drive" then return false end
local nextJob = A.pickJob(hero, unit, now, st.job)
if nextJob == nil or nextJob.type ~= "drive" then return false end
local hp = 0
for _, c in ipairs(creeps) do hp = hp + Entity.GetHealth(c) end
local dps = math.max(1, NPC.GetTrueDamage(unit) * NPC.GetAttacksPerSecond(unit))
local travel = (nextJob.pos - Entity.GetAbsOrigin(unit)):Length2D() / math.max(200, NPC.GetMoveSpeed(unit))
local arrive = hp / dps + travel
local cd = Ability.GetCooldownLength(flux)
if cd <= arrive then return false end
if st.fluxSavedFor ~= nextJob.camps[1] then
st.fluxSavedFor = nextJob.camps[1]
A.log("info", "arc farm flux saved", { cd = math.floor(cd * 10) / 10, arrive = math.floor(arrive * 10) / 10, camp = nextJob.camps[1] })
end
return true
end
function A.awayPoint(camp, origin)
local dir = origin - camp.pos
local len = math.max(1, dir:Length2D())
local bx, by = dir.x / len, dir.y / len
local first = nil
for _, deg in ipairs({ 0, 30, -30, 60, -60, 90, -90, 120, -120, 150, -150, 180 }) do
local a = math.rad(deg)
local x, y = bx * math.cos(a) - by * math.sin(a), bx * math.sin(a) + by * math.cos(a)
local p = Vector(camp.pos.x + x * C.awayDist, camp.pos.y + y * C.awayDist, camp.pos.z)
first = first or p
local free = true
for _, other in ipairs(A.camps()) do
if other ~= camp and (p - other.pos):Length2D() <= other.radius + C.blockSlack then
free = false
break
end
end
if free then return p end
end
return first
end
function A.stepStomp(unit, st, now)
local origin = Entity.GetAbsOrigin(unit)
local reach = C.stompRadius + NPC.GetHullRadius(unit) + C.stompSlack
local threat, casting = nil, false
for _, n in ipairs(NPCs.InRadius(origin, reach, Entity.GetTeamNum(unit), C.teamBoth, true, true) or {}) do
if NPC.IsNeutral(n) and Entity.IsAlive(n) and NPC.GetAbility(n, C.stompAbility) ~= nil then
local cast = NPC.HasModifier(n, C.neutralCast)
local armed = NPC.GetMana(n) >= C.stompMana and not NPC.HasModifier(n, C.neutralCastCd)
and (Entity.GetAbsOrigin(n) - origin):Length2D() <= C.stompClose
if cast or armed then
threat, casting = n, cast
if cast then break end
end
end
end
if threat == nil then return false end
if now < (st.stompAt or 0) then return true end
st.stompAt, st.target, st.orderAt = now + C.stompGap, nil, 0
local p = Entity.GetAbsOrigin(threat)
local dir = origin - p
local len = math.max(1, dir:Length2D())
local dest = Vector(p.x + dir.x / len * (reach + 80), p.y + dir.y / len * (reach + 80), origin.z)
local player = Players.GetLocal()
if player == nil then return true end
S.selfAt = now
Player.PrepareUnitOrders(player, C.orderMove, nil, dest, nil, C.issuer, unit, false, false, false, false, C.identifier)
if st.stompLogged ~= threat then
st.stompLogged = threat
A.log("info", "arc farm stomp dodge", { casting = casting, dist = math.floor(len) })
end
return true
end
function A.stepStack(unit, st, now, camp, creeps, sec, minute)
local origin = Entity.GetAbsOrigin(unit)
if st.phase == "pull" then
if now - st.pullAt >= C.pullHold then
st.away = A.awayPoint(camp, origin)
st.phase, st.awayAt, st.orderAt = "away", now, 0
end
return true
end
if st.phase == "away" then
if (minute ~= nil and minute > st.stacked and sec ~= nil and sec >= 0.8) or now - st.awayAt > C.awayTimeout then
st.phase, st.orderAt, st.target = "fight", 0, nil
S.stacks[st.camp] = (S.stacks[st.camp] or 0) + 1
A.log("info", "arc farm stack done", { camp = st.camp, stacks = S.stacks[st.camp] })
else
A.order(unit, st, now, C.orderMove, nil, st.away)
end
return true
end
if not UI.stack:Get() or sec == nil or minute == nil or st.stacked >= minute or #creeps == 0
or sec < UI.stackSec:Get() or sec >= math.max(UI.stackSec:Get() + 2, C.stackLatest) then
return false
end
if UI.restack:Get() and sec + A.clearTime(unit, creeps) + C.restackGap <= 60 then
st.stacked = minute
A.log("info", "arc farm skip stack, refarm", { camp = st.camp, second = math.floor(sec) })
return false
end
local nearest, bestDist = nil, nil
for _, c in ipairs(creeps) do
local d = (Entity.GetAbsOrigin(c) - origin):Length2D()
if bestDist == nil or d < bestDist then nearest, bestDist = c, d end
end
st.stacked, st.phase, st.pullAt, st.orderAt = minute, "pull", now, 0
A.order(unit, st, now, C.orderAttack, nearest)
A.log("info", "arc farm stack pull", { camp = st.camp, second = math.floor(sec * 10) / 10 })
return true
end
function A.stepCast(unit, st, now, creeps)
if now < st.castAt or NPC.IsChannellingAbility(unit) then return false end
S.selfAt = now
local used, h = A.castSpells(unit, st, now, creeps)
if used == nil then return false end
st.castAt = now + math.max(0, Ability.GetCastPoint(h)) + C.castGap
st.orderAt, st.target, st.spelled = st.castAt, nil, true
if A.has(Ability.GetBehavior(h), C.channelBit) then
st.channelItem, st.channelUntil = h, st.castAt + C.channelHold
end
A.log("info", "arc farm cast", { what = used, camp = st.camp })
return true
end
function A.reach(unit, creep)
return A.attackRange(unit) + NPC.GetHullRadius(unit) + NPC.GetHullRadius(creep)
end
function A.stepAttack(hero, unit, st, now, creeps, hit)
local origin = Entity.GetAbsOrigin(unit)
local target, bestDist = nil, nil
for _, c in ipairs(creeps) do
local d = (Entity.GetAbsOrigin(c) - origin):Length2D()
if bestDist == nil or d < bestDist then target, bestDist = c, d end
end
local nextCamp = A.pickJob(hero, unit, now, st.job)
local point, spa = A.attackTiming(unit)
local readyAt = st.launchAt + spa - point - A.latency()
if st.launchAt > st.attackAt and now < readyAt and (nextCamp ~= nil or hit) then
if st.phase ~= "kite" then
local dest
if nextCamp ~= nil then
local dir = nextCamp.pos - origin
local len = math.max(1, dir:Length2D())
local limit = A.reach(unit, target) - C.rangeEdge
local tpos = Entity.GetAbsOrigin(target)
local step = math.min(len, math.max(0, readyAt - now) * NPC.GetMoveSpeed(unit))
if tpos.z - origin.z > C.highGround then step = 0 end
for _ = 1, 6 do
local p = Vector(origin.x + dir.x / len * step, origin.y + dir.y / len * step, origin.z)
if (p - tpos):Length2D() <= limit then break end
step = step * 0.6
end
if step < 40 then
st.phase = "kite"
return
end
dest = Vector(origin.x + dir.x / len * step, origin.y + dir.y / len * step, origin.z)
else
local away = origin - Entity.GetAbsOrigin(target)
local len = math.max(1, away:Length2D())
local step = math.max(60, math.min(C.kiteStep, A.reach(unit, target) - C.rangeEdge - bestDist))
dest = Vector(origin.x + away.x / len * step, origin.y + away.y / len * step, origin.z)
end
st.phase, st.orderAt = "kite", 0
A.order(unit, st, now, C.orderMove, nil, dest)
end
return
end
if st.phase == "kite" or target ~= st.target or now - st.attackAt > 2 then
st.phase, st.orderAt, st.target, st.attackAt = "fight", 0, target, now
A.order(unit, st, now, C.orderAttack, target)
end
end
function A.run(hero, unit, now)
local st = S.st
if st == nil or S.unit ~= unit then
st = A.newState()
S.st, S.unit = st, unit
A.log("info", "arc farm double found", { range = A.attackRange(unit), base = NPC.GetAttackRange(unit) })
end
local camps = A.camps()
local here = Entity.GetAbsOrigin(unit)
if st.lastPos ~= nil and (here - st.lastPos):Length2D() > C.jumpReset and st.job ~= nil and now > (S.selfJumpAt or 0) then
A.leaveCamp(st, "double moved", nil)
end
st.lastPos = here
local hit = A.underAttack(unit, st, now)
if st.channelUntil ~= nil and now < st.channelUntil then
local ok, on = pcall(Ability.IsChannelling, st.channelItem)
if now < st.castAt or (ok and on) then return end
st.channelUntil = nil
end
if A.stepStomp(unit, st, now) then return end
if A.stepFlicker(unit, st, now) or A.stepManta(unit, st, now) then return end
if A.stepRune(unit, st, now) then return end
if st.job == nil then
local job = A.pickJob(hero, unit, now, nil)
if job == nil then
if (Entity.GetAbsOrigin(hero) - Entity.GetAbsOrigin(unit)):Length2D() > C.followGap then
A.order(unit, st, now, C.orderMove, nil, Entity.GetAbsOrigin(hero))
end
return
end
st.job, st.camp, st.phase, st.spelled, st.jobAt, st.target, st.engaged = job, job.camps[1], "travel", false, now, nil, false
A.log("info", "arc farm job", { job = job.type, camps = #job.camps, first = job.camps[1] })
end
if st.job.type == "drive" then
A.stepDrive(unit, st, now, camps[st.camp])
return
end
if st.job.type == "merge" then
A.stepMerge(hero, unit, st, now, hit)
return
end
local camp = camps[st.camp]
local sec, minute = A.clock()
if A.stepRespawn(unit, st, now, camp, sec, minute) then return end
if st.phase == "travel" and A.stepTravel(hero, unit, st, now, camp) then return end
local creeps = A.visibleCreeps(unit, camp)
A.track(st, creeps, now)
if A.stepStack(unit, st, now, camp, creeps, sec, minute) then return end
local fight, hidden = A.targets(unit, st, now)
if #fight == 0 then
if A.chase(unit, st, now, hidden) then return end
if C.pointVisible ~= nil and C.pointVisible(camp.pos) then
if UI.restack:Get() and sec ~= nil and minute ~= nil and 60 - sec <= C.restackWindow then
st.phase, st.waitMinute, st.waitUntil, st.orderAt = "respawn", minute, now + C.restackWindow + 2, 0
A.log("info", "arc farm wait respawn", { camp = st.camp, second = math.floor(sec * 10) / 10 })
return
end
A.leaveCamp(st, "cleared", A.nextSpawn(now))
else
st.phase = "travel"
end
return
end
if A.stepCast(unit, st, now, fight) then return end
A.stepAttack(hero, unit, st, now, fight, hit)
end
function A.update()
local now = GameRules.GetGameTime()
local hero = Heroes.GetLocal()
if hero == nil or NPC.GetUnitName(hero) ~= C.hero then return end
if now >= S.refreshAt then
S.refreshAt = now + C.refresh
A.refreshItems(hero)
if S.octSynced then
local pick = UI.octarine:ListEnabled()[1] or ""
if pick ~= UI.saveOctarine:Get() then UI.saveOctarine:Set(pick) end
end
end
local down = UI.key:IsDown()
if down and not S.keyDown then
S.on = not S.on
S.st, S.unit = nil, nil
if S.on then S.earned, S.farmAt, S.goldPrev, S.killCap, S.jumpGold = 0, now, nil, 0, 0 end
A.log("info", S.on and "arc farm started" or "arc farm stopped", { camps = #A.camps() })
end
S.keyDown = down
if not S.on or now < S.tickAt or now < S.pauseUntil or not A.orderSafe() then return end
S.tickAt = now + C.tick
local unit = A.findDouble(hero)
if unit == nil then
S.st, S.unit = nil, nil
return
end
if A.watchEnemies(unit, now) then return end
A.runIllusions(hero, unit, now)
A.run(hero, unit, now)
A.trackGold(now)
end
function A.markHit(unit, enemy, now, how)
if not A.live(enemy) or Entity.IsSameTeam(unit, enemy) then return end
local name = NPC.GetUnitName(enemy):gsub("^npc_dota_hero_", ""):gsub("_", " ")
local dist = (Entity.GetAbsOrigin(enemy) - Entity.GetAbsOrigin(unit)):Length2D()
if S.alert == nil or S.alert.name ~= name or now > S.alert.untilAt then
A.log("info", "arc farm double hit by enemy", { hero = name, dist = math.floor(dist), how = how })
end
local startAt = (S.alert ~= nil and now <= S.alert.untilAt) and S.alert.startAt or now
S.alert = { name = name, dist = dist, untilAt = now + C.alertHold, enemy = enemy, unitName = NPC.GetUnitName(enemy), startAt = startAt }
end
function A.foeReady(h, mana)
return Ability.GetLevel(h) > 0 and not Ability.IsHidden(h) and Ability.GetCooldown(h) <= C.foeCdSlack and Ability.GetManaCost(h) <= mana
end
function A.foeMark(t, h, f)
if f:find("d", 1, true) ~= nil then
t.d = true
local ok, imm = pcall(Ability.GetImmunityType, h)
if f:find("p", 1, true) ~= nil or (ok and imm == C.immEnemiesYes) then t.p = true end
end
if f:find("x", 1, true) ~= nil then t.x = true end
end
function A.foeThreat(unit)
local origin, t = Entity.GetAbsOrigin(unit), { d = false, p = false, x = false }
for _, e in ipairs(Heroes.GetAll() or {}) do
if e ~= nil and not Entity.IsSameTeam(unit, e) and Entity.IsAlive(e) and not NPC.IsIllusion(e) and NPC.IsVisible(e)
and (Entity.GetAbsOrigin(e) - origin):Length2D() <= C.foeReach then
local mana = NPC.GetMana(e)
for i = 0, 23 do
local h = NPC.GetAbilityByIndex(e, i)
local f = h ~= nil and C.foe[Ability.GetName(h)] or nil
if f ~= nil and A.foeReady(h, mana) then A.foeMark(t, h, f) end
end
for _, slot in ipairs(C.slots) do
local it = NPC.GetItemByIndex(e, slot)
if it ~= nil and A.foeReady(it, mana) then
local nm = Ability.GetName(it)
for frag, f in pairs(C.foeItems) do
if nm:find(frag, 1, true) ~= nil then A.foeMark(t, it, f) end
end
end
end
end
end
return t
end
function A.useDefense(unit, now)
if now < (S.defenseAt or 0) or S.defendedFor == S.alert.startAt then return false end
local enemy, origin = S.alert.enemy, Entity.GetAbsOrigin(unit)
local threat = A.foeThreat(unit)
local enemyOk = A.live(enemy) and NPC.IsVisible(enemy) and not NPC.HasState(enemy, C.stateImmune)
local byName = {}
for _, d in ipairs(C.defense) do byName[d.t] = d end
for _, label in ipairs(UI.defense:ListEnabled()) do
local d = byName[label]
local h = nil
if d ~= nil then
for _, slot in ipairs(C.slots) do
local it = NPC.GetItemByIndex(unit, slot)
if it ~= nil and Ability.GetName(it):find(d.frag, 1, true) ~= nil and A.ready(unit, it) then h = it end
end
end
local allowed = false
if h ~= nil then
if d.need == "nopierce" then
allowed = not threat.p
elseif d.need == "notimmune" then
allowed = enemyOk and (Entity.GetAbsOrigin(enemy) - origin):Length2D() <= Ability.GetCastRange(h) + 100
else
allowed = not threat.d and not threat.x
end
end
if allowed then
S.selfAt = now
if d.use == "enemy" then
Ability.CastTarget(h, enemy, false, false, true, C.identifier)
elseif A.has(Ability.GetBehavior(h), C.bits.unit) then
Ability.CastTarget(h, unit, false, false, true, C.identifier)
else
Ability.CastNoTarget(h, false, false, true, C.identifier)
end
S.defenseAt, S.defendedFor = now + C.defenseGap, S.alert.startAt
A.log("info", "arc farm defense", { item = Ability.GetName(h), hero = S.alert.name, disable = threat.d, pierce = threat.p, dispel = threat.x })
return true
end
end
return false
end
function A.canReunion(unit)
local h = NPC.GetAbility(unit, C.reunion)
return A.ready(unit, h) and not NPC.IsStunned(unit) and not NPC.HasState(unit, C.stateHexed) and not A.cycloned(unit)
end
function A.cycloned(unit)
for _, m in ipairs(C.cycloneMods) do
if NPC.HasModifier(unit, m) then return true end
end
return false
end
function A.facing(e, pos)
local ep = Entity.GetAbsOrigin(e)
local fp = Entity.GetForwardPosition(e, 100)
local fx, fy, tx, ty = fp.x - ep.x, fp.y - ep.y, pos.x - ep.x, pos.y - ep.y
local fl, tl = math.sqrt(fx * fx + fy * fy), math.sqrt(tx * tx + ty * ty)
if fl < 1 or tl < 1 then return true end
return (fx * tx + fy * ty) / (fl * tl) >= C.faceCos
end
function A.watchEnemies(unit, now)
if NPC.IsChannellingAbility(unit) then return true end
local hp = Entity.GetHealth(unit)
local dropped = S.lastHp ~= nil and hp < S.lastHp
S.lastHp = hp
if dropped then
local origin, best, bestDist = Entity.GetAbsOrigin(unit), nil, nil
for _, e in ipairs(Heroes.GetAll() or {}) do
if e ~= nil and not Entity.IsSameTeam(unit, e) and Entity.IsAlive(e) and not NPC.IsIllusion(e) and NPC.IsVisible(e) then
local d = (Entity.GetAbsOrigin(e) - origin):Length2D()
local reach = A.attackRange(e) + NPC.GetHullRadius(e) + NPC.GetHullRadius(unit) + C.hitSlack
if d <= reach and NPC.IsAttacking(e) and A.facing(e, origin) and (bestDist == nil or d < bestDist) then best, bestDist = e, d end
end
end
if best ~= nil then A.markHit(unit, best, now, "hp") end
end
if S.alert == nil or now > S.alert.untilAt then return false end
if A.canReunion(unit) and A.useDefense(unit, now) then return true end
if not UI.reunion:Get() and S.defendedFor ~= S.alert.startAt then return false end
local h = NPC.GetAbility(unit, C.reunion)
if not A.ready(unit, h) then
if S.reunionLogged ~= S.alert.untilAt - C.alertHold then
S.reunionLogged = S.alert.untilAt - C.alertHold
A.log("info", "arc farm reunion unavailable", {
found = h ~= nil, hidden = h ~= nil and Ability.IsHidden(h) or nil,
cd = h ~= nil and Ability.GetCooldown(h) or nil, level = h ~= nil and Ability.GetLevel(h) or nil,
})
end
return false
end
if now < (S.reunionAt or 0) then return false end
local stunned, hexed, cycloned = NPC.IsStunned(unit), NPC.HasState(unit, C.stateHexed), A.cycloned(unit)
if stunned or hexed or cycloned then
if S.reunionBlocked ~= S.alert.startAt then
S.reunionBlocked = S.alert.startAt
A.log("info", "arc farm reunion blocked", { stunned = stunned, hexed = hexed, cycloned = cycloned })
end
return false
end
S.reunionAt = now + C.reunionGap
S.defendedFor = S.alert.startAt
S.selfAt = now
Ability.CastNoTarget(h, false, false, true, C.identifier)
if A.live(S.alert.enemy) then
S.avoidPos, S.avoidUntil = Entity.GetAbsOrigin(S.alert.enemy), now + C.avoidFor
end
if S.st ~= nil then A.leaveCamp(S.st, "enemy reunion", nil) end
A.log("info", "arc farm reunion", { hero = S.alert.name })
return true
end
function A.clamp(v, lo, hi)
if v < lo then return lo end
if v > hi then return hi end
return v
end
function A.cparts(c)
local ok, r, g, b, a = pcall(function() return c.r, c.g, c.b, c.a end)
if ok and type(r) == "number" then return r, g, b, a or 255 end
return 255, 255, 255, 255
end
function A.cfade(c, a)
local r, g, b = A.cparts(c)
return Color(r, g, b, A.clamp(math.floor(a + 0.5), 0, 255))
end
function A.clerp(x, y, t)
local r1, g1, b1, a1 = A.cparts(x)
local r2, g2, b2, a2 = A.cparts(y)
t = A.clamp(t, 0, 1)
return Color(math.floor(r1 + (r2 - r1) * t + 0.5), math.floor(g1 + (g2 - g1) * t + 0.5),
math.floor(b1 + (b2 - b1) * t + 0.5), math.floor(a1 + (a2 - a1) * t + 0.5))
end
function A.style(name, fallback)
local now = GlobalVars.GetCurTime()
S.theme = S.theme or {}
local c = S.theme[name]
if c ~= nil and now < c.at then return c.col or fallback end
local col = A.readStyle(name)
S.theme[name] = { at = now + 1, col = col }
return col or fallback
end
function A.readStyle(name)
local ok, col = pcall(Menu.Style, name)
if ok and col ~= nil then
local okr, r = pcall(function() return col.r end)
if okr and type(r) == "number" then return col end
end
return nil
end
function A.heroIcon(unitName)
if unitName == nil then return nil end
S.icons = S.icons or {}
if S.icons[unitName] == nil then
local ok, h = pcall(Render.LoadImage, "panorama/images/heroes/icons/" .. unitName .. "_png.vtex_c")
S.icons[unitName] = (ok and h ~= nil and h ~= 0) and h or false
end
return S.icons[unitName] or nil
end
function A.glowRect(x1, y1, x2, y2, color, spread, rounding)
if spread <= 0 then return end
local r, g, b, a = A.cparts(color)
local n = A.clamp(math.floor(spread / 3), 5, 12)
for i = n, 1, -1 do
local t = i / n
local d = spread * t
Render.FilledRect(Vec2(x1 - d, y1 - d), Vec2(x2 + d, y2 + d),
Color(r, g, b, A.clamp(math.floor(a * (1 - t) * (1 - t) + 0.5), 0, 255)), rounding + d)
end
end
function A.hgrad(x1, y1, x2, y2, cl, cr, rounding)
local w = x2 - x1
if w <= 0 then return end
local steps = A.clamp(math.floor(w / 4), 6, 40)
local sw = w / steps
for i = 0, steps - 1 do
local t = steps > 1 and i / (steps - 1) or 0
local rr = (i == 0 or i == steps - 1) and rounding or 0
Render.FilledRect(Vec2(x1 + sw * i, y1), Vec2(x1 + sw * i + sw + 0.6, y2), A.clerp(cl, cr, t), rr)
end
end
function A.rrPoint(d, x, y, w, h, r, total)
local sw, sh = w - 2 * r, h - 2 * r
local arc = math.pi * 0.5 * r
local ad = arc > 0 and arc or 1
d = d % total
if d <= sw then return x + r + d, y end
d = d - sw
if d <= arc then
local a = -math.pi * 0.5 + d / ad * math.pi * 0.5
return x + w - r + math.cos(a) * r, y + r + math.sin(a) * r
end
d = d - arc
if d <= sh then return x + w, y + r + d end
d = d - sh
if d <= arc then
local a = d / ad * math.pi * 0.5
return x + w - r + math.cos(a) * r, y + h - r + math.sin(a) * r
end
d = d - arc
if d <= sw then return x + w - r - d, y + h end
d = d - sw
if d <= arc then
local a = math.pi * 0.5 + d / ad * math.pi * 0.5
return x + r + math.cos(a) * r, y + h - r + math.sin(a) * r
end
d = d - arc
if d <= sh then return x, y + h - r - d end
d = d - sh
local a = math.pi + d / ad * math.pi * 0.5
return x + r + math.cos(a) * r, y + r + math.sin(a) * r
end
function A.flowBorder(x, y, w, h, r, color, head0, pulse, s, k)
local rr = A.clamp(r, 0, math.min(w, h) * 0.5)
local total = 2 * (w - 2 * rr) + 2 * (h - 2 * rr) + 2 * math.pi * rr
if total <= 0 then return end
local cr, cg, cb, ca = A.cparts(color)
local samples = 22
local spacing = total * 0.18 / samples
for n = 0, 1 do
local head = head0 + total / 2 * n
for q = samples - 1, 0, -1 do
local f = q / samples
local px, py = A.rrPoint(head - q * spacing, x, y, w, h, rr, total)
local hot = (1 - f) * (1 - f)
local rad = (3.4 - 2.0 * f) * s
Render.FilledRect(Vec2(px - rad, py - rad), Vec2(px + rad, py + rad),
Color(math.floor(cr + (255 - cr) * hot * 0.75), math.floor(cg + (255 - cg) * hot * 0.75),
math.floor(cb + (255 - cb) * hot * 0.75), A.clamp(math.floor(ca * hot * pulse * k), 0, 255)), rad)
end
local hx, hy = A.rrPoint(head, x, y, w, h, rr, total)
Render.FilledRect(Vec2(hx - 5 * s, hy - 5 * s), Vec2(hx + 5 * s, hy + 5 * s), Color(cr, cg, cb, A.clamp(math.floor(110 * pulse * k), 0, 255)), 5 * s)
Render.FilledRect(Vec2(hx - 2.4 * s, hy - 2.4 * s), Vec2(hx + 2.4 * s, hy + 2.4 * s), Color(255, 255, 255, A.clamp(math.floor(235 * pulse * k), 0, 255)), 2.4 * s)
end
end
function A.sheen(x, y, w, h, s, clock, k)
local ph = (clock % 5) / 5
if ph >= 0.45 then return end
local t = ph / 0.45
local env = math.sin(t * math.pi)
if env <= 0.01 then return end
local cx = x - 60 * s + (w + 120 * s) * t
local rows = 12
local rowh = (h - 4 * s) / rows
for r = 0, rows - 1 do
local ry = y + 2 * s + r * rowh
local rcx = cx + 40 * s * (r / (rows - 1) - 0.5)
for i = 0, 6 do
local u = i / 3 - 1
local sx = rcx + u * 26 * s
local a = 100 * env * (1 - u * u) * k
if a >= 1 and sx > x + 2 * s and sx < x + w - 2 * s then
Render.FilledRect(Vec2(sx, ry), Vec2(sx + math.max(2.5 * s, 1), ry + rowh + 1), Color(255, 255, 255, A.clamp(math.floor(a), 0, 255)), 0)
end
end
end
end
function A.creditKill(k, now)
local hero = Heroes.GetLocal()
if hero ~= nil and (Entity.GetAbsOrigin(hero) - k.pos):Length2D() <= C.heroKillReach then return end
local ok, bounty = pcall(NPC.GetGoldBountyMax, k.h)
if not ok or type(bounty) ~= "number" or bounty <= 0 then bounty = C.bountyFallback end
S.killCap, S.killUntil = (now <= S.killUntil and S.killCap or 0) + bounty * 2, now + C.killCredit
end
function A.trackGold(now)
local player = Players.GetLocal()
if player == nil then return end
local gold = Player.GetTotalGold(player)
if type(gold) ~= "number" then return end
local prev = S.goldPrev
S.goldPrev = gold
if prev == nil or gold <= prev then return end
local credit = 0
if now <= S.killUntil and S.killCap > 0 then
credit = math.min(gold - prev, S.killCap)
S.killCap = S.killCap - credit
end
local rest = gold - prev - credit
if rest >= C.goldJump then
local extra = math.min(rest, C.goldJumpMax)
credit = credit + extra
S.jumpGold = (S.jumpGold or 0) + extra
if now - (S.jumpLogAt or 0) >= 60 then
S.jumpLogAt = now
A.log("info", "arc farm gold without a kill credit", { gold = math.floor(S.jumpGold), earned = math.floor(S.earned + credit) })
end
end
S.earned = S.earned + credit
end
function A.itemIcon(name)
S.itemIcons = S.itemIcons or {}
if S.itemIcons[name] == nil then
local base = A.base(name)
local ok, h = pcall(Render.LoadImage, "panorama/images/items/" .. (C.iconFix[base] or base) .. "_png.vtex_c")
S.itemIcons[name] = (ok and h ~= nil and h ~= 0) and h or false
end
return S.itemIcons[name] or nil
end
function A.clockText(sec)
sec = math.max(0, math.floor(sec))
return string.format("%d:%02d", math.floor(sec / 60), sec % 60)
end
function A.vgrad(x1, y1, x2, y2, ctop, cbot, rounding)
local h = y2 - y1
if h <= 0 then return end
local steps = A.clamp(math.floor(h / 8), 10, 18)
local sh = h / steps
for i = 0, steps - 1 do
local sy = y1 + sh * i
local mid = sy + sh * 0.5
local de = math.min(mid - y1, y2 - mid)
local ins = 0
if rounding > 0 and de < rounding then ins = rounding - math.sqrt(rounding * rounding - (rounding - de) * (rounding - de)) end
Render.FilledRect(Vec2(x1 + ins, sy), Vec2(x2 - ins, sy + sh + 0.6), A.clerp(ctop, cbot, i / (steps - 1)), 0)
end
end
function A.pill(x, y, text, font, size, fg, bg, s)
local ts = Render.TextSize(font, size, text)
local ph, pad = ts.y + 6 * s, 8 * s
Render.FilledRect(Vec2(x, y), Vec2(x + ts.x + pad * 2, y + ph), bg, ph / 2)
Render.Text(font, size, text, Vec2(x + pad, y + 3 * s), fg)
return ts.x + pad * 2
end
function A.meter(x, y, w, h, frac, c1, c2, k, value, s)
Render.FilledRect(Vec2(x, y), Vec2(x + w, y + h), Color(0, 0, 0, math.floor(130 * k)), h / 2)
if frac > 0 then
local fx = x + w * A.clamp(frac, 0, 1)
A.glowRect(x, y, fx, y + h, A.cfade(c2, 40 * k), 4 * s, h / 2)
A.hgrad(x, y, fx, y + h, c1, c2, h / 2)
Render.FilledRect(Vec2(x + h / 2, y + 1), Vec2(fx - h / 2, y + h * 0.4), Color(255, 255, 255, math.floor(45 * k)), h / 4)
end
local ts = Render.TextSize(S.fontReg, 11 * s, value)
Render.Text(S.fontReg, 11 * s, value, Vec2(x + w + 8 * s, y + (h - ts.y) / 2), Color(235, 235, 240, math.floor(230 * k)))
end
function A.dragPanel(x, y, w, h)
local opened = A.api(Menu, "Opened") ~= nil and Menu.Opened()
if not UI.alertPreview:Get() and not opened then
S.drag, S.dragX, S.dragY = nil, nil, nil
return
end
local ok, cx, cy = pcall(Input.GetCursorPos)
if not ok or type(cx) ~= "number" or type(cy) ~= "number" then return end
local down = Input.IsKeyDown(C.mouse1)
if S.drag ~= nil then
if down then
S.dragX, S.dragY = A.clamp(cx - S.drag.dx, 0, 3840), A.clamp(cy - S.drag.dy, 0, 2160)
else
if S.dragX ~= nil then
UI.alertX:Set(math.floor(S.dragX))
UI.alertY:Set(math.floor(S.dragY))
end
S.drag, S.dragX, S.dragY = nil, nil, nil
end
elseif down and not S.mouseWas and cx >= x and cx <= x + w and cy >= y and cy <= y + h then
S.drag = { dx = cx - x, dy = cy - y }
end
S.mouseWas = down
end
function A.drawAlert()
local now, clock = GameRules.GetGameTime(), GlobalVars.GetCurTime()
local preview = UI.alertPreview:Get()
local live = S.on or preview
local hit = S.alert ~= nil and now <= S.alert.untilAt and S.on
local dt = A.clamp(clock - (S.animAt or clock), 0, 0.1)
S.animAt = clock
S.anim = A.clamp((S.anim or 0) + (live and dt or -dt) * C.alertSpeed, 0, 1)
S.hitK = A.clamp((S.hitK or 0) + ((hit or (preview and not S.on and clock % 4 > 2)) and dt or -dt) * C.hitFade, 0, 1)
if S.anim <= 0 then return end
local k = 1 - (1 - S.anim) ^ 3
local mode = UI.alertAnim:Get()
local s = UI.alertScale:Get() / 100
if mode == 3 then s = s * (0.8 + 0.2 * k) end
local w, h, m = 340 * s, 168 * s, 12 * s
local bx, byy = S.dragX or UI.alertX:Get(), S.dragY or UI.alertY:Get()
A.dragPanel(bx, byy, w, h)
local x, y = bx, byy
if mode == 1 then y = y - (1 - k) * 40 * s elseif mode == 2 then x = x + (1 - k) * 80 * s end
local rnd = UI.alertRound:Get() * s
local white, black = Color(255, 255, 255, 255), Color(0, 0, 0, 255)
local accent, bgBase, text = UI.alertAccent:Get(), Color(22, 24, 32, 255), Color(245, 245, 248, 255)
if UI.alertTheme:Get() then
accent = A.style("primary", accent)
bgBase = A.style("additional_background", bgBase)
text = A.style("primary_widgets_text", text)
end
local red = Color(235, 55, 50, 255)
accent = A.clerp(accent, red, S.hitK)
local accentLt = A.clerp(accent, white, 0.35)
local bgA = UI.alertBg:Get() * k
local bgTop = A.clerp(A.clerp(bgBase, accent, 0.16 + 0.2 * S.hitK), white, 0.05)
local bgBot = A.clerp(A.clerp(bgBase, accent, 0.05 + 0.1 * S.hitK), black, 0.3)
if UI.alertShadow:Get() then
A.glowRect(x, y + 6 * s, x + w, y + h + 6 * s, Color(0, 0, 0, math.floor(160 * k)), 18 * s, rnd)
end
if UI.alertGlow:Get() then
local pulse = 0.5 + 0.5 * math.sin(clock * (2.5 + 6 * S.hitK))
A.glowRect(x, y, x + w, y + h, A.cfade(accent, (40 + 40 * pulse + 60 * S.hitK) * k), UI.alertGlowSize:Get() * s, rnd)
end
A.vgrad(x, y, x + w, y + h, A.cfade(bgTop, bgA), A.cfade(bgBot, bgA), rnd)
Render.Rect(Vec2(x, y), Vec2(x + w, y + h), A.cfade(accent, 80 * k), rnd)
Render.FilledRect(Vec2(x + rnd, y + 1), Vec2(x + w - rnd, y + 2 * s), A.cfade(accentLt, 90 * k), 1)
if UI.alertSheen:Get() then A.sheen(x, y, w, h, s, clock, k) end
if UI.alertFlow:Get() then
A.flowBorder(x, y, w, h, rnd, A.clerp(accent, white, 0.12), clock * 190 * s, 0.62 + 0.38 * (0.5 + 0.5 * math.sin(clock * 4)), s, k)
end
local unit = A.live(S.unit) and S.unit or nil
local shown = S.alert
if preview and not S.on then shown = { name = "pudge", unitName = "npc_dota_hero_pudge", dist = 540 } end
local hot = S.hitK > 0.5 and shown ~= nil
local side = 44 * s
local ix0, iy0 = x + m, y + m
local icon = UI.alertIcon:Get() and A.heroIcon(hot and shown.unitName or C.hero) or nil
local tx = x + m
if icon ~= nil then
A.glowRect(ix0, iy0, ix0 + side, iy0 + side, A.cfade(accent, 70 * k), 6 * s, side / 2)
Render.Image(icon, Vec2(ix0, iy0), Vec2(side, side), Color(255, 255, 255, math.floor(255 * k)), side / 2)
Render.Rect(Vec2(ix0, iy0), Vec2(ix0 + side, iy0 + side), A.cfade(accentLt, 200 * k), side / 2, nil, 2 * s)
tx = ix0 + side + 12 * s
end
local title, sub
if hot then
title = localization.Get("panel.hit_title")
sub = string.format(localization.Get("panel.hit_sub"), shown.name, math.floor(shown.dist))
else
title = localization.Get("panel.title")
local job = S.st ~= nil and S.st.job ~= nil and S.st.job.type or nil
sub = unit == nil and not preview and localization.Get("panel.no_double") or localization.Get("panel.job_" .. (job or "idle"))
end
Render.Text(S.fontBold, 16 * s, title, Vec2(tx + 1.2 * s, iy0 + 2 * s + 1.2 * s), Color(0, 0, 0, math.floor(160 * k)))
Render.Text(S.fontBold, 16 * s, title, Vec2(tx, iy0 + 2 * s), A.cfade(A.clerp(text, accentLt, 0.35), 255 * k))
local dotC = hot and red or ((unit ~= nil or preview) and Color(90, 220, 120, 255) or Color(150, 150, 160, 255))
local dp = 0.6 + 0.4 * math.sin(clock * 4)
local dx, dy = tx + 4 * s, iy0 + 30 * s
Render.FilledRect(Vec2(dx - 6 * s * dp, dy - 6 * s * dp), Vec2(dx + 6 * s * dp, dy + 6 * s * dp), A.cfade(dotC, 60 * k), 6 * s)
Render.FilledRect(Vec2(dx - 3 * s, dy - 3 * s), Vec2(dx + 3 * s, dy + 3 * s), A.cfade(dotC, 255 * k), 3 * s)
Render.Text(S.fontReg, 12 * s, sub, Vec2(dx + 10 * s, dy - 7 * s), A.cfade(A.clerp(text, accent, 0.15), 215 * k))
local elapsed = S.on and now - S.farmAt or 0
local tt = A.clockText(elapsed)
local tsz = Render.TextSize(S.fontBold, 12 * s, tt)
A.pill(x + w - m - tsz.x - 16 * s, iy0, tt, S.fontBold, 12 * s, A.cfade(text, 235 * k), A.cfade(black, 110 * k), s)
local ly = iy0 + side + 8 * s
A.hgrad(x + m, ly, x + w - m, ly + 1, A.cfade(accent, 0), A.cfade(accent, 120 * k), 0)
local hp, hpMax, mp, mpMax = 0, 1, 0, 1
if unit ~= nil then
hp, hpMax = Entity.GetHealth(unit), math.max(1, Entity.GetMaxHealth(unit))
mp, mpMax = NPC.GetMana(unit), math.max(1, NPC.GetMaxMana(unit))
elseif preview then
hp, hpMax, mp, mpMax = 1540, 2200, 610, 900
end
local mw = w - 2 * m - 78 * s
local my = ly + 10 * s
A.meter(x + m, my, mw, 9 * s, hp / hpMax, A.cfade(Color(35, 150, 65, 255), 255 * k), A.cfade(Color(120, 235, 130, 255), 255 * k), k,
string.format("%d/%d", math.floor(hp), math.floor(hpMax)), s)
A.meter(x + m, my + 16 * s, mw, 9 * s, mp / mpMax, A.cfade(Color(35, 85, 200, 255), 255 * k), A.cfade(Color(95, 175, 255, 255), 255 * k), k,
string.format("%d/%d", math.floor(mp), math.floor(mpMax)), s)
local iy, ih = my + 34 * s, 24 * s
local iw = ih * 1.36
local ix = x + m
for n, slot in ipairs(C.slots) do
local it = unit ~= nil and NPC.GetItemByIndex(unit, slot) or nil
local sx = ix
local sw = iw
if n == #C.slots then
sx = ix + 6 * s
sw = ih
end
Render.FilledRect(Vec2(sx, iy), Vec2(sx + sw, iy + ih), Color(0, 0, 0, math.floor(120 * k)), n == #C.slots and ih / 2 or 4 * s)
if it ~= nil then
local ic = A.itemIcon(Ability.GetName(it))
if ic ~= nil then
Render.Image(ic, Vec2(sx, iy), Vec2(sw, ih), Color(255, 255, 255, math.floor(255 * k)), n == #C.slots and ih / 2 or 4 * s)
end
local cd = Ability.GetCooldown(it)
if cd > 0 then
Render.FilledRect(Vec2(sx, iy), Vec2(sx + sw, iy + ih), Color(0, 0, 0, math.floor(150 * k)), n == #C.slots and ih / 2 or 4 * s)
local t = tostring(math.ceil(cd))
local ts = Render.TextSize(S.fontBold, 12 * s, t)
Render.Text(S.fontBold, 12 * s, t, Vec2(sx + (sw - ts.x) / 2, iy + (ih - ts.y) / 2), Color(255, 255, 255, math.floor(240 * k)))
end
end
Render.Rect(Vec2(sx, iy), Vec2(sx + sw, iy + ih), A.cfade(accent, (it ~= nil and 90 or 35) * k), n == #C.slots and ih / 2 or 4 * s)
ix = sx + sw + 4 * s
end
local fy = iy + ih + 10 * s
local gpm = elapsed > 30 and math.floor(S.earned / elapsed * 60) or 0
local gold = Color(255, 200, 70, 255)
local px = x + m
px = px + A.pill(px, fy, string.format(localization.Get("panel.gold"), math.floor(S.earned)), S.fontBold, 12 * s, A.cfade(gold, 255 * k), A.cfade(A.clerp(black, gold, 0.18), 170 * k), s) + 6 * s
A.pill(px, fy, string.format("%d GPM", gpm), S.fontBold, 12 * s, A.cfade(text, 230 * k), A.cfade(black, 110 * k), s)
if S.drag ~= nil or preview then
Render.Text(S.fontReg, 11 * s, localization.Get("panel.drag_hint"), Vec2(x, y + h + 6 * s), Color(220, 220, 225, math.floor(200 * k)))
end
end
