function script.OnPrepareUnitOrders(data)
if not S.ready or not S.on or data == nil or S.unit == nil or data.npc ~= S.unit then return true end
local now = GameRules.GetGameTime()
if now - S.selfAt <= C.selfOrder then return true end
if data.ability ~= nil and A.passiveOrder(data.ability) then return true end
S.pauseUntil = now + C.manualPause
if S.st ~= nil then S.st.phase, S.st.orderAt = "travel", 0 end
