function A.dist(a, b)
local dx, dy = a.x - b.x, a.y - b.y
return math.sqrt(dx * dx + dy * dy)
end
function A.norm(dx, dy)
local d = math.sqrt(dx * dx + dy * dy)
if d <= 0.001 then return 1, 0, 0 end
return dx / d, dy / d, d
end
function A.hasState(unit, state)
