end
function A.hasBehavior(handle, flag)
if not handle then return false end
local ok, value = pcall(Ability.GetBehavior, handle, false)
if not ok or type(value) ~= "number" or flag <= 0 then return false end
return math.floor(value / flag) % 2 == 1
end
function A.hpPct(unit)
