if not max or max <= 0 then return 100 end
return Entity.GetHealth(unit) / max * 100
end
function A.aim(origin, pos, range)
if range <= 0 then return pos end
local d = A.dist(origin, pos)
if d <= range or d <= 1 then return pos end
local k = range / d
return Vector(origin.x + (pos.x - origin.x) * k, origin.y + (pos.y - origin.y) * k, pos.z)
end
function A.invulnLeft(target)
if not target then return 0 end
local best = 0
