local ok, states = pcall(GET_STATES, target, STATE_QUERY)
if ok and type(states) == "table" then best = states[STATE_INVULN] or 0 end
end
if best <= 0 and HAS_STATE then
local ok, flag = pcall(HAS_STATE, target, STATE_INVULN)
if ok and flag == true then best = CFG.assumeInvuln end
end
