if left > best then best = left end
end
end
return best
end
function A.track(target, now)
local trk = S.run.trk
local pos = Entity.GetAbsOrigin(target)
local index = Entity.GetIndex(target)
local dt = now - trk.t
if trk.index ~= index or dt <= 0 or dt > 0.5 then
trk.index, trk.x, trk.y, trk.t, trk.vx, trk.vy = index, pos.x, pos.y, now, 0, 0
return
end
if dt < 0.05 then return end
local vx, vy = (pos.x - trk.x) / dt, (pos.y - trk.y) / dt
trk.vx = trk.vx * 0.5 + vx * 0.5
trk.vy = trk.vy * 0.5 + vy * 0.5
trk.x, trk.y, trk.t = pos.x, pos.y, now
end
