S.talAt = now + CFG.talentScan
local found, key = {}, ""
local emp = NPC.GetAbility(hero, "invoker_emp_custom")
local okCast, autocast = pcall(Ability.GetAutoCastState, emp)
found.empPush = okCast and autocast == true
key = key .. (found.empPush and "emp:push," or "emp:pull,")
local seen = A.detectTalents(hero)
for _, short in ipairs(TALENT_ROWS) do
if seen[short] ~= nil then S.talSeen[short] = seen[short] end
if S.talSeen[short] then
found[short] = true
key = key .. short .. ","
end
end
key = key .. (seen.w4 == nil and "emp?," or "") .. (seen.e7 == nil and "meteor?," or "")
S.tal = found
if key ~= S.talKey or S.talKey == nil then
S.talKey = key
A.log("info", "talents", { active = key ~= "" and key or "none" })
end
end
