local cursorTarget = A.cursorTarget(hero)
if cursorTarget then return cursorTarget end
local origin = Entity.GetAbsOrigin(hero)
local best, bestDist = nil, math.huge
for _, enemy in ipairs(Heroes.InRadius(origin, UI.radius:Get(), team, TEAM_ENEMY, true, false)) do
if A.validTarget(enemy) then
local d = A.dist(origin, Entity.GetAbsOrigin(enemy))
if d < bestDist then best, bestDist = enemy, d end
end
end
return best
end
function A.full()
local out, seen = {}, {}
for _, id in ipairs(UI.steps and UI.steps:List() or {}) do
local step = BY_ID[id]
if step and not seen[id] then
seen[id] = true
out[#out + 1] = step
end
end
for _, step in ipairs(STEPS) do
if not seen[step.id] then out[#out + 1] = step end
end
return out
end
function A.order()
local widget = A.preset()
local out = {}
if widget then
for _, id in ipairs(widget:List() or {}) do
local step = BY_ID[id]
if step and widget:Get(id) then out[#out + 1] = step end
end
else
out = A.full()
end
if not (S.run and S.run.wave) then return out end
local wave = {}
for _, step in ipairs(out) do
if step.wave then wave[#wave + 1] = step end
end
return wave
end
function A.resolve(hero, step)
for _, name in ipairs(step.names) do
local handle = step.src == "item" and NPC.GetItem(hero, name, true) or NPC.GetAbility(hero, name)
if handle then return handle end
end
return nil
end
function A.castRange(hero, step, handle)
local range = step.range or 0
if step.src == "spell" and handle then
local ok, value = pcall(Ability.GetCastRange, handle)
if ok and type(value) == "number" and value > range then range = value end
range = range + (NPC.GetCastRangeBonus(hero) or 0)
end
return range
end
function A.slotAbility(hero, name)
for index = 3, 4 do
local ability = NPC.GetAbilityByIndex(hero, index)
if ability and Ability.GetName(ability) == name then return ability end
end
return nil
end
function A.invokeReady(hero, step)
if A.slotAbility(hero, step.names[1]) then return true end
local invoke = NPC.GetAbility(hero, INVOKE)
if not invoke then return false end
local orb = NPC.GetAbility(hero, ORBS[step.recipe:sub(1, 1)])
if not orb or Ability.GetLevel(orb) < 1 then return false end
return Ability.GetCooldown(invoke) <= CFG.invokeWait
end
function A.controlled(target)
return A.hasState(target, STATE_STUNNED) or A.hasState(target, STATE_HEXED)
end
function A.cooldownSoon(hero, id, seconds)
if not A.selected(id) then return false end
local step = BY_ID[id]
local handle = step and A.resolve(hero, step)
if not handle or Ability.GetCooldown(handle) > seconds then return false end
if NPC.GetMana(hero) < Ability.GetManaCost(handle) then return false end
return step.src == "item" or A.invokeReady(hero, step)
end
function A.wallGeom(handle)
if S.wallGeom then return S.wallGeom end
local g = { place = 200, band = 105, half = 600 }
local okP, place = pcall(Ability.GetLevelSpecialValueFor, handle, "wall_place_distance", -1)
if okP and type(place) == "number" and place > 0 then g.place = place end
local okR, radius = pcall(Ability.GetLevelSpecialValueFor, handle, "wall_element_radius", -1)
if okR and type(radius) == "number" and radius > 0 then g.band = radius end
local okN, count = pcall(Ability.GetLevelSpecialValueFor, handle, "num_wall_elements", -1)
local okS, spacing = pcall(Ability.GetLevelSpecialValueFor, handle, "wall_element_spacing", -1)
if okN and okS and type(count) == "number" and type(spacing) == "number" and count > 0 and spacing > 0 then
g.half = count * spacing / 2
end
S.wallGeom = g
A.log("info", "wall geometry", { place = g.place, band = g.band, half = g.half })
return g
end
function A.wallVector(handle)
return A.hasBehavior(handle, BEHAVIOR_VECTOR)
end
function A.wallMiss(hero, target, geom)
local origin = Entity.GetAbsOrigin(hero)
local pos = Entity.GetAbsOrigin(target)
local forward = Entity.GetRotation(hero):GetForward()
local dx, dy = pos.x - origin.x, pos.y - origin.y
local along = dx * forward.x + dy * forward.y
local side = math.abs(dx * forward.y - dy * forward.x)
local reach = math.max(0, side - geom.half)
return math.sqrt((along - geom.place) ^ 2 + reach * reach)
end
function A.wallFacePoint(hero, target, geom)
local origin = Entity.GetAbsOrigin(hero)
local pos = Entity.GetAbsOrigin(target)
local ux, uy, distance = A.norm(pos.x - origin.x, pos.y - origin.y)
local radial = math.sqrt(geom.place * geom.place + geom.half * geom.half)
if distance < math.max(0, geom.place - geom.band) or distance > radial + geom.band then return nil, distance end
local axis = math.max(geom.place, math.min(distance, radial))
local c = geom.place / axis
local s = math.sqrt(math.max(0, 1 - c * c))
local px, py = -uy, ux
local ax, ay = ux * c + px * s, uy * c + py * s
local bx, by = ux * c - px * s, uy * c - py * s
local forward = Entity.GetRotation(hero):GetForward()
if forward.x * bx + forward.y * by > forward.x * ax + forward.y * ay then ax, ay = bx, by end
return Vector(origin.x + ax * CFG.wallFaceDistance, origin.y + ay * CFG.wallFaceDistance, origin.z), distance
end
function A.planGate(hero, step, handle, target, now)
local run = S.run
if step.id == "Book (R7)" then
if not A.validTarget(target) then return A.no(step, "waiting for combo target") end
if A.hpPct(hero) <= (UI.ghosthp and UI.ghosthp:Get() or 30) then
return A.no(step, "too low to anchor ourselves, the book teleports us back here")
end
end
if step.once and run.lastCast[step.id] then return false end
if step.buff and NPC.HasModifier(hero, step.buff) then return false end
if step.debuff and target and NPC.HasModifier(target, step.debuff) then return false end
if step.escape then
local threshold = UI.ghosthp and UI.ghosthp:Get() or 30
local hp = A.hpPct(hero)
if hp > threshold then return A.no(step, "health above the escape threshold") end
if step.buff and NPC.HasModifier(hero, step.buff) then return false end
if NPC.HasModifier(hero, BOOK_BUFF) then
return A.no(step, "the book would teleport us back, escaping is pointless")
end
if hp >= (run.hpStart or hp) and hp > threshold * CFG.panicShare then
return A.no(step, "health has not dropped since the combo started")
end
end
if step.src == "spell" and not step.pure and step.kind ~= "self" and step.kind ~= "no"
and A.hasState(target, STATE_MAGIC_IMMUNE)
then
return false
end
local meteor = A.meteorActive(now) and run.meteor or nil
if step.id == "Tornado" then
if meteor or now < (run.fieldUntil or 0) or A.landLeft(target, now) > 0 then return A.no(step, "protecting active damage or lift") end
elseif step.id == "EMP" then
if run.detonateAt then return false end
if A.displaces(step) and (meteor or now < (run.fieldUntil or 0)) then return false end
if A.displaces(step) and now < (run.landUntil or 0) then
return A.no(step, "the knockback would shove the target out of our own delayed hit")
end
elseif step.id == "Chaos Meteor" then
if meteor then return false end
if S.tal.e7 and not A.cataclysmFull(hero) and S.quickUsed then
return A.no(step, "one meteor already went out, saving it until the stacks are up")
end
if A.cataclysmFull(hero) then
if NPC.HasModifier(hero, BOOK_BUFF) then
return A.no(step, "the book window is for cycling spells, not for a 4s channel")
end
if A.landLeft(target, now) > 0 or not A.controlled(target) then
return A.no(step, "the full cataclysm needs the target locked on the ground")
end
end
elseif step.id == "Deafening Blast" then
if meteor and meteor.pair and not meteor.blastDone then
local due = A.blastCastAt(hero, target) or now
local inSlot = A.slotAbility(hero, step.names[1]) ~= nil
if now < due - (inSlot and 0.04 or CFG.invokePrep) then return false end
elseif not meteor and not S.tal.e7
and (not run.lastCast["Chaos Meteor"] or now - run.lastCast["Chaos Meteor"] >= CFG.castGrace)
and A.cooldownSoon(hero, "Chaos Meteor", 1.0)
then
return false
end
elseif step.id == "Ethereal Blade" then
if S.tal.e7 and S.quickUsed and not A.cataclysmFull(hero) then
return A.no(step, "ethereal blocks our attacks while we are stacking the cataclysm")
end
elseif step.id == "Black King Bar" then
local channelSetup = S.tal.e7 and A.cooldownSoon(hero, "Chaos Meteor", 1.0)
if A.hpPct(hero) > 50 and not channelSetup then return false end
elseif step.id == "Blink" then
if not target or A.dist(Entity.GetAbsOrigin(hero), Entity.GetAbsOrigin(target)) <= 500 then return false end
elseif step.id == "Ice Wall" then
local origin = Entity.GetAbsOrigin(hero)
local pos = Entity.GetAbsOrigin(target)
local distance = A.dist(origin, pos)
if A.wallVector(handle) then
local range = A.castRange(hero, step, handle)
if distance > range then return false end
elseif run.wave then
local forward = Entity.GetRotation(hero):GetForward()
local nx, ny = A.norm(pos.x - origin.x, pos.y - origin.y)
if distance > CFG.waveGrab or forward.x * nx + forward.y * ny <= 0 then
return A.no(step, "the wave is not in front of the hero")
end
else
local geom = A.wallGeom(handle)
local face = A.wallFacePoint(hero, target, geom)
if not face then return A.no(step, "wall cannot reach at distance " .. math.floor(distance)) end
local miss = A.wallMiss(hero, target, geom)
if miss > geom.band * CFG.wallFar and not A.controlled(target) then
return A.no(step, "too big a turn for a target that is still free")
end
if miss > geom.band * CFG.wallAccept and NPC.HasModifier(hero, BOOK_BUFF) then
return A.no(step, "no time to turn for the wall inside the book window")
end
end
elseif step.control and A.controlled(target) then
return false
end
return true
end
function A.score(hero, step, target, now, index)
if step.escape then return 100000 end
if step.id == "Book (R7)" then return 95000 end
if step.id == "Black King Bar" then return 90000 end
local due = A.stepCastAt(hero, step, target, now)
if due then return 50000 - (due - now) * 1000 - index * 0.01 end
local run = S.run
local score = (step.score or 50) - index * CFG.orderWeight
if not run or not target then return score end
local amped = false
for id, window in pairs(AMP_WINDOW) do
local at = run.lastCast[id]
if at and now - at <= window then amped = true end
end
local locked = A.controlled(target)
local airborne = A.landLeft(target, now) > 0
local hp = A.hpPct(target)
local distance = A.dist(Entity.GetAbsOrigin(hero), Entity.GetAbsOrigin(target))
if step.group == "amp" and not amped then score = score + 240 end
if step.control and not step.lift and not locked then score = score + 200 end
if NPC.HasModifier(hero, BOOK_BUFF)
and (BURST[step.id] or step.group == "damage" or step.group == "amp")
then
score = score + CFG.bookPush
end
if S.tal.e7 and STACKERS[step.id] and (A.cataclysmStacks(hero) or 0) < CFG.cataclysmStacks then
score = score + CFG.stackPush
end
if BURST[step.id] then
if amped then score = score + 180 end
if hp <= 30 then score = score + 260 end
end
if (step.buff or step.once) and (locked or hp <= 40) then score = score - 180 end
if step.id == "Blink" and distance > 700 then score = score + 240 end
if step.group == "damage" and not amped then score = score - 90 end
if (step.delay or 0) >= 1.0 and not locked and not airborne
and not (step.id == "EMP" and A.cooldownSoon(hero, "Tornado", CFG.chainWindow))
then
score = score - 140
end
return score
end
function A.plan(hero, steps, target, now)
local out = {}
local scheduled, prepareAt
for index, step in ipairs(steps) do
local handle = A.ready(hero, step, target, now)
if handle then
local candidate = { step = step, handle = handle, score = A.score(hero, step, target, now, index) }
local due = A.stepCastAt(hero, step, target, now)
if due then
local prep = step.src == "spell" and not A.slotAbility(hero, step.names[1]) and CFG.invokePrep or 0.05
local startAt = due - prep
if not prepareAt or startAt < prepareAt then scheduled, prepareAt = candidate, startAt end
else
out[#out + 1] = candidate
end
end
end
table.sort(out, function(a, b) return a.score > b.score end)
if scheduled then
for _, candidate in ipairs(out) do
local step = candidate.step
local cost = step.kind == "wall" and CFG.wallTurnTimeout or
(step.src == "spell" and not A.slotAbility(hero, step.names[1]) and CFG.invokePrep + 0.15 or 0.15)
if step.escape or step.id == "Book (R7)" or step.id == "Black King Bar" or now + cost < prepareAt then return { candidate } end
end
return { scheduled }
end
return out
end
function A.needClose(step, gap)
local run = S.run
if not run or type(gap) ~= "number" or gap < CFG.approachMin then return end
if not run.close or gap < run.close.gap then run.close = { id = step.id, gap = gap } end
end
function A.approach(hero, now)
local run = S.run
if not UI.approach or UI.approach:Get() ~= true then return false end
if not run.close or not A.validTarget(run.target) then return false end
if A.invulnLeft(run.target) > 0 then return false end
if (run.closeSpent or 0) >= CFG.approachTime then return false end
local origin = Entity.GetAbsOrigin(hero)
local pos = Entity.GetAbsOrigin(run.target)
local nx, ny, distance = A.norm(pos.x - origin.x, pos.y - origin.y)
local travel = math.min(distance - 50, run.close.gap + CFG.approachMargin)
if travel <= 0 then return false end
if now >= (run.closeAt or 0) then
run.closeSpent = (run.closeSpent or 0) + CFG.approachOrder
run.closeAt = now + CFG.approachOrder
run.closing = true
NPC.MoveTo(hero, Vector(origin.x + nx * travel, origin.y + ny * travel, origin.z), false, false, false, true, CFG.identifier, false)
if run.closeLogged ~= run.close.id then
run.closeLogged = run.close.id
A.log("info", "closing in", { step = run.close.id, gap = math.floor(run.close.gap), spent = run.closeSpent })
end
end
A.say("i6.panel.closing", run.close.id)
return true
end
function A.no(step, reason)
local run = S.run
if run then run.why[step.id] = reason end
return nil
end
function A.ready(hero, step, target, now)
local run = S.run
if now < (run.retryAt[step.id] or 0) then return A.no(step, "cast retry backoff") end
if run.lastCast[step.id] and now - run.lastCast[step.id] < CFG.castGrace then return A.no(step, "just cast") end
local handle = A.resolve(hero, step)
if not handle then return A.no(step, "not owned") end
if Ability.GetCooldown(handle) > 0.05 then return A.no(step, "cooldown") end
local mana = NPC.GetMana(hero)
if mana < Ability.GetManaCost(handle) then return A.no(step, "mana") end
if step.src == "item" and UI.managate:Get() > 0 then
local maxMana = NPC.GetMaxMana(hero)
if maxMana > 0 and mana / maxMana * 100 < UI.managate:Get() then return A.no(step, "mana gate") end
end
if step.confirm and NPC.HasModifier(hero, step.confirm) then return A.no(step, "already active") end
if (step.kind == "no" or step.kind == "self") and step.range > 0 then
if not A.validTarget(target) then return A.no(step, "no target") end
local gap = A.dist(Entity.GetAbsOrigin(hero), Entity.GetAbsOrigin(target)) - step.range
if gap > 0 then
A.needClose(step, gap)
return A.no(step, "target too far")
end
end
if step.kind ~= "no" and step.kind ~= "self" then
if not A.validTarget(target) then return A.no(step, "no target") end
local invuln = A.landLeft(target, now)
if run.liftPending and now < run.liftPending and invuln <= 0 then return A.no(step, "tornado in flight") end
if step.kind == "unit" then
if invuln > 0 then return A.no(step, "target airborne") end
local gap = A.dist(Entity.GetAbsOrigin(hero), Entity.GetAbsOrigin(target)) - A.castRange(hero, step, handle)
if gap > 0 then
A.needClose(step, gap)
return A.no(step, "out of cast range")
end
else
if invuln > 0 then
local due = A.stepCastAt(hero, step, target, now)
local inSlot = step.src == "spell" and A.slotAbility(hero, step.names[1]) ~= nil
local prep = step.src == "spell" and not inSlot and CFG.invokePrep or 0.04
if due and now < due - prep then run.why[step.id] = "scheduled for landing" end
end
if step.radius then
local origin = Entity.GetAbsOrigin(hero)
local flight = A.effectTime(hero, step, target)
local want = A.predict(step, target, flight)
local range = A.castRange(hero, step, handle)
local aim = A.aim(origin, want, range)
local short = A.dist(aim, want)
if short > step.radius * CFG.aoeFill then
A.needClose(step, short)
return A.no(step, "aoe cannot reach, short by " .. math.floor(short))
end
end
end
end
if step.src == "spell" and not A.invokeReady(hero, step) then return A.no(step, "cannot invoke now") end
if not A.planGate(hero, step, handle, target, now) then
if not run.why[step.id] then run.why[step.id] = "plan gate" end
return nil
end
return handle
end
function A.blastAim(hero, target, range)
local origin = Entity.GetAbsOrigin(hero)
local pos = Entity.GetAbsOrigin(target)
local meteor = S.run and S.run.meteor
if not meteor then return A.aim(origin, A.predict(BY_ID["Deafening Blast"], target, A.dist(origin, pos) / CFG.blastSpeed), range) end
local rx, ry = pos.x - origin.x, pos.y - origin.y
local along = rx * meteor.dx + ry * meteor.dy
local side = math.abs(rx * meteor.dy - ry * meteor.dx)
if along > 0 and side <= CFG.blastRadius then
local reach = math.min(range, math.max(350, along + 420))
return Vector(origin.x + meteor.dx * reach, origin.y + meteor.dy * reach, pos.z)
end
return A.aim(origin, pos, range)
end
function A.armMeteor(hero, target, point, now)
local origin = Entity.GetAbsOrigin(hero)
local dx, dy = A.norm(point.x - origin.x, point.y - origin.y)
local impact = now + CFG.meteorLand + 0.05
local flight = target and (0.05 + A.dist(origin, Entity.GetAbsOrigin(target)) / CFG.blastSpeed) or 0.5
local lag = CFG.blastLag
local blastWindow = math.max(0.05, impact + lag - flight - now + 0.12)
local pair = not A.cataclysmFull(hero) and A.cooldownSoon(hero, "Deafening Blast", blastWindow)
S.run.meteor = {
point = point,
dx = dx,
dy = dy,
impactAt = impact,
rollUntil = impact + A.meteorRollTime(hero),
pair = pair,
blastDone = false,
}
A.log("info", "meteor plan", {
impact = math.floor((impact - now) * 100) / 100,
blast_in = pair and math.floor((impact + lag - flight - now) * 100) / 100 or -1,
pair = pair,
legendary = A.cataclysmFull(hero),
})
end
function A.castStep(hero, handle, step, target, now)
local run = S.run
local origin = Entity.GetAbsOrigin(hero)
local castRange = A.castRange(hero, step, handle)
if step.kind == "no" then
Ability.CastNoTarget(handle, false, false, true, CFG.identifier)
elseif step.kind == "self" then
Ability.CastTarget(handle, hero, false, false, true, CFG.identifier)
elseif step.kind == "unit" then
Ability.CastTarget(handle, target, false, false, true, CFG.identifier)
elseif step.kind == "wall" then
if A.wallVector(handle) then
local center = A.aim(origin, Entity.GetAbsOrigin(target), castRange)
local nx, ny = A.norm(center.x - origin.x, center.y - origin.y)
local vectorEnd = Vector(center.x - ny * CFG.wallVector, center.y + nx * CFG.wallVector, center.z)
local player = Players.GetLocal()
if player then
Player.PrepareUnitOrders(player, ORDER_VECTOR, nil, vectorEnd, handle, ISSUER_PASSED, hero, false, false, false, true, CFG.identifier)
Ability.CastPosition(handle, center, false, false, true, CFG.identifier)
end
else
local geom = A.wallGeom(handle)
local miss = A.wallMiss(hero, target, geom)
if run.wave then
A.log("info", "wall cast across the wave", {
miss = math.floor(miss),
dist = math.floor(A.dist(origin, Entity.GetAbsOrigin(target))),
})
Ability.CastNoTarget(handle, false, false, false, CFG.identifier)
elseif not run.wallReady then
run.phase = "wall_turn"
run.deadline = now + CFG.wallTurnTimeout
run.wallMoveAt = 0
run.wallTurnAt = now
run.wallSettleAt = nil
run.nextAt = now
A.say("i6.panel.wall")
A.log("info", "wall turn started", { miss = math.floor(miss) })
return
else
run.wallReady = nil
run.wallMoving = nil
A.log("info", "wall cast", {
miss = math.floor(miss),
dist = math.floor(A.dist(origin, Entity.GetAbsOrigin(target))),
place = geom.place,
band = geom.band,
})
Ability.CastNoTarget(handle, false, false, false, CFG.identifier)
end
end
else
local range = castRange
local flight = A.effectTime(hero, step, target)
local point
if step.id == "Blink" then
local pos = Entity.GetAbsOrigin(target)
local nx, ny, distance = A.norm(pos.x - origin.x, pos.y - origin.y)
local travel = math.min(range, math.max(0, distance - 375))
point = Vector(origin.x + nx * travel, origin.y + ny * travel, pos.z)
elseif step.id == "Deafening Blast" and A.meteorActive(now) then
point = A.blastAim(hero, target, range)
else
point = A.aim(origin, A.predict(step, target, flight), range)
end
Ability.CastPosition(handle, point, false, false, true, CFG.identifier)
if step.radius and (step.delay or 0) > 0 and not A.displaces(step) then
run.landUntil = math.max(run.landUntil or 0, now + step.delay)
end
if step.field then run.fieldUntil = now + (step.delay or 0) + step.field end
if step.id == "Chaos Meteor" then
A.armMeteor(hero, target, point, now)
if A.cataclysmFull(hero) then
run.holdPending = A.cataclysmTime(hero, handle)
S.quickUsed = false
elseif S.tal.e7 then
run.holdPending = nil
run.noWait = true
run.breakUntil = now + CFG.breakWindow
S.quickUsed = true
A.log("info", "meteor quick cast", { stacks = A.cataclysmStacks(hero) or -1 })
end
end
if step.id == "Deafening Blast" and run.meteor then run.meteor.blastDone = true end
if step.lift then
local quas = NPC.GetAbility(hero, ORBS.q)
local qlevel = quas and Ability.GetLevel(quas) or 0
qlevel = math.max(0, math.min(7, qlevel))
local lift = 0
local ok, value = pcall(Ability.GetLevelSpecialValueFor, handle, "lift_duration", qlevel)
if ok and type(value) == "number" and value > 1.1 and value < 6 then lift = value end
local formula = CFG.liftBase + CFG.liftPerQuas * qlevel
if lift < formula - 0.05 then lift = formula end
run.liftPending = now + flight + CFG.liftGrace
run.liftGuess = lift
run.landAt = now + flight + lift
A.log("info", "tornado lift window", { flight = flight, lift = lift, quas = qlevel })
end
if step.id == "EMP" and S.tal.w7 then
local travel = A.dist(origin, Entity.GetAbsOrigin(target)) / CFG.empSpeedW7
run.detonateAt = now + travel + 0.1
end
end
run.tries = run.tries + 1
run.castHandle = handle
run.castAt = now
run.phase = "cast"
local gap = UI.gap:Get() / 1000
if NPC.HasModifier(hero, BOOK_BUFF) then gap = math.min(gap, CFG.bookGap) end
run.nextAt = now + (step.src == "item" and math.min(CFG.itemGap, gap) or math.max(0.04, gap))
A.say("i6.panel.cast", step.id)
A.log("info", "cast", { step = step.id, try = run.tries })
if run.noWait then
run.noWait = nil
A.finishStep(now, true)
end
end
function A.cancelWallMove(run)
if not run or not (run.wallMoving or run.closing) then return end
run.wallMoving = nil
run.closing = nil
local hero = Heroes.GetLocal()
local player = Players.GetLocal()
if hero and player then Player.HoldPosition(player, hero, false, false, true, CFG.identifier) end
end
function A.runWallTurn(hero, step, now)
local run = S.run
if not step or not A.validTarget(run.target) then
A.finishStep(now, false)
return
end
local handle = A.slotAbility(hero, step.names[1]) or A.resolve(hero, step)
if not handle or Ability.GetCooldown(handle) > 0.05 or NPC.GetMana(hero) < Ability.GetManaCost(handle) then
A.finishStep(now, false)
return
end
local geom = A.wallGeom(handle)
local miss = A.wallMiss(hero, run.target, geom)
if miss <= geom.band * CFG.wallAccept then
if not run.wallSettleAt then
run.wallMoving = true
A.cancelWallMove(run)
run.wallSettleAt = now + CFG.wallSettle
run.nextAt = now + CFG.wallTurnTick
A.log("info", "wall settling", { miss = math.floor(miss) })
return
end
if now < run.wallSettleAt then
run.nextAt = now + CFG.wallTurnTick
return
end
A.log("info", "wall aligned", { time = math.floor((now - (run.wallTurnAt or now)) * 100) / 100, miss = math.floor(miss) })
run.wallMoving = nil
run.wallReady = true
A.castStep(hero, handle, step, run.target, now)
return
end
run.wallSettleAt = nil
if miss > geom.band * CFG.wallFar and not A.controlled(run.target) then
A.log("info", "wall aim abandoned", { reason = "free target, big turn", miss = math.floor(miss), controlled = false })
A.no(step, "too big a turn for a target that is still free")
A.finishStep(now, false)
return
end
local face, distance = A.wallFacePoint(hero, run.target, geom)
if not face then
A.log("info", "wall turn cancelled", { distance = math.floor(distance) })
A.finishStep(now, false)
return
end
if now >= (run.wallMoveAt or 0) then
run.wallTries = (run.wallTries or 0) + 1
if run.wallTries > CFG.wallMoves then
A.log("info", "wall aim abandoned", { reason = "out of re-aims", miss = math.floor(miss), tries = run.wallTries })
A.no(step, "the turn never brought the wall onto the target")
A.finishStep(now, false)
return
end
NPC.MoveTo(hero, face, false, false, false, true, CFG.identifier, false)
run.wallMoving = true
run.wallMoveAt = now + CFG.wallTurnOrder
end
run.nextAt = now + CFG.wallTurnTick
A.say("i6.panel.wall")
end
function A.finishStep(now, castOk)
local run = S.run
if run.phase == "wall_turn" then A.cancelWallMove(run) end
local holdPending = run.holdPending
run.holdPending = nil
run.invokeRetry = nil
run.invokeAt = nil
run.wallMoveAt = nil
run.wallTurnAt = nil
run.wallSettleAt = nil
run.wallReady = nil
run.wallTries = nil
if run.step then
if castOk then
run.lastCast[run.step.id] = now
A.log("info", "cast confirmed", { step = run.step.id, t = now })
if holdPending and run.step.id == "Chaos Meteor" then
run.holdUntil = now + holdPending
A.log("info", "cataclysm channel", { hold = math.floor(holdPending * 100) / 100 })
end
else
run.retryAt[run.step.id] = now + 0.8
A.no(run.step, "cast not confirmed")
if run.step.id == "Chaos Meteor" then run.meteor = nil end
if run.step.field then run.fieldUntil = 0 end
if run.step.lift then run.liftPending, run.landAt = nil, nil end
if run.step.id == "EMP" then run.detonateAt = nil end
end
end
if castOk and run.step and run.step.escape then
A.stop(now, "escape")
return
end
run.phase = "pick"
run.step = nil
run.orbStep = 1
run.invokeSent = false
run.castAt = nil
run.tries = 0
end
function A.beginStep(hero, step, handle, target, now)
local run = S.run
run.step = step
run.orbStep = 1
run.invokeSent = false
run.castAt = nil
run.tries = 0
run.deadline = now + CFG.stepTimeout
local due = A.stepCastAt(hero, step, target, now)
if due then run.deadline = math.max(run.deadline, due + 0.8) end
if (step.src == "item" or A.slotAbility(hero, step.names[1])) and due and now < due then
run.phase = "armed"
run.nextAt = due
A.say("i6.panel.timing")
elseif step.src == "item" or A.slotAbility(hero, step.names[1]) then
A.castStep(hero, A.slotAbility(hero, step.names[1]) or handle, step, target, now)
else
run.phase = "invoke"
A.say("i6.panel.invoke", step.id)
end
end
function A.runArmed(hero, step, now)
local run = S.run
if not step or not A.validTarget(run.target) then
A.finishStep(now, false)
return
end
local due = A.stepCastAt(hero, step, run.target, now) or now
if due and now < due then
run.nextAt = due
return
end
local handle = A.slotAbility(hero, step.names[1]) or A.resolve(hero, step)
if not handle then
A.finishStep(now, false)
return
end
A.castStep(hero, handle, step, run.target, now)
end
function A.runInvoke(hero, step, now)
local run = S.run
local invoke = NPC.GetAbility(hero, INVOKE)
if not invoke then
A.finishStep(now, false)
return
end
local invokeCd = Ability.GetCooldown(invoke)
if run.orbStep == 1 and invokeCd > 0.05 then
if invokeCd > CFG.invokeWait then A.finishStep(now, false) end
return
end
if run.orbStep <= 3 then
local orb = NPC.GetAbility(hero, ORBS[step.recipe:sub(run.orbStep, run.orbStep)])
if not orb or Ability.GetLevel(orb) < 1 then
A.finishStep(now, false)
return
end
Ability.CastNoTarget(orb, false, false, true, CFG.identifier)
run.orbStep = run.orbStep + 1
run.nextAt = now + CFG.orbInterval
return
end
if not run.invokeSent then
if invokeCd > 0.05 then return end
Ability.CastNoTarget(invoke, false, false, true, CFG.identifier)
run.invokeSent = true
run.invokeAt = now
run.nextAt = now + CFG.invokeGap
return
end
local slot = A.slotAbility(hero, step.names[1])
if slot then
local due = A.stepCastAt(hero, step, run.target, now)
if due and now < due then
run.phase = "armed"
run.nextAt = due
A.say("i6.panel.timing")
else
A.castStep(hero, slot, step, run.target, now)
end
return
end
if now - (run.invokeAt or now) < CFG.invokeConfirm then return end
run.invokeRetry = (run.invokeRetry or 0) + 1
A.log("info", "invoke did not take", { step = step.id, try = run.invokeRetry })
if run.invokeRetry >= CFG.invokeRetries then
A.finishStep(now, false)
return
end
run.orbStep = 1
run.invokeSent = false
run.invokeAt = nil
run.nextAt = now
end
function A.runCastWait(hero, step, now)
local run = S.run
local handle = run.castHandle or A.resolve(hero, step)
local slot = step.src == "spell" and A.slotAbility(hero, step.names[1]) or nil
local landed = false
if handle then landed = Ability.GetCooldown(handle) > 0.05 end
if not landed and slot then landed = Ability.GetCooldown(slot) > 0.05 end
if step.confirm then landed = landed or NPC.HasModifier(hero, step.confirm) end
if not landed and step.debuff and A.validTarget(run.target) then
landed = NPC.HasModifier(run.target, step.debuff) == true
end
if landed then
A.finishStep(now, true)
return
end
if handle and Ability.IsInAbilityPhase(handle) and now - run.castAt < 0.8 then return end
local window = step.src == "item" and CFG.itemConfirm or CFG.castConfirm
if now - run.castAt < window then return end
if run.tries < CFG.castTries and handle then
if not run.missLog[step.id] then
run.missLog[step.id] = true
local function st(code)
if not HAS_STATE then return "?" end
local ok, flag = pcall(HAS_STATE, run.target, code)
return ok and tostring(flag) or "err"
end
A.log("info", "cast not confirmed", {
step = step.id,
cd = handle and math.floor(Ability.GetCooldown(handle) * 100) / 100 or -1,
cd_slot = slot and math.floor(Ability.GetCooldown(slot) * 100) / 100 or -1,
phase = handle and Ability.IsInAbilityPhase(handle) == true,
debuff = step.debuff ~= nil and NPC.HasModifier(run.target, step.debuff) == true or false,
invuln = A.invulnLeft(run.target),
st_invuln = st(STATE_INVULN),
st_stunned = st(STATE_STUNNED),
st_hexed = st(STATE_HEXED),
st_magic_immune = st(STATE_MAGIC_IMMUNE),
in_df = A.slotAbility(hero, step.names[1]) ~= nil,
castable = Ability.IsCastable(handle, NPC.GetMana(hero)),
dist = math.floor(A.dist(Entity.GetAbsOrigin(hero), Entity.GetAbsOrigin(run.target))),
range = step.range + (NPC.GetCastRangeBonus(hero) or 0),
})
end
if step.kind ~= "no" and step.kind ~= "self" and not A.validTarget(run.target) then
A.finishStep(now, false)
return
end
A.castStep(hero, slot or handle, step, run.target, now)
else
A.log("warn", "cast rejected", { step = step.id, t = now })
A.finishStep(now, false)
end
end
function A.attackFiller(hero, now)
local run = S.run
if not UI.attack:Get() or not A.validTarget(run.target) then return end
if now < run.nextAttack then return end
if NPC.IsAttacking(hero) or NPC.IsTurning(hero) then return end
local range = NPC.GetAttackRange(hero) + (NPC.GetAttackRangeBonus(hero) or 0)
if A.dist(Entity.GetAbsOrigin(hero), Entity.GetAbsOrigin(run.target)) > range then return end
local player = Players.GetLocal()
if not player then return end
Player.AttackTarget(player, hero, run.target, false, false, true, CFG.identifier)
run.nextAttack = now + 0.3
end
function A.tick(hero, now)
local run = S.run
if not run then return end
if now >= run.nextRetarget then
run.nextRetarget = now + CFG.retarget
if not A.validTarget(run.target) then
run.target = A.pickTarget(hero, run.wave)
else
local cursor = run.wave and A.waveTarget(hero) or A.cursorTarget(hero)
if cursor and cursor ~= run.target and A.retargetSafe(run, now) then
A.log("info", "cursor retarget", { wave = run.wave })
run.target = cursor
run.meteor = nil
end
end
end
if A.validTarget(run.target) then
A.track(run.target, now)
A.watchLift(now)
if A.invulnLeft(run.target) > 0 then run.liftPending = nil end
end
if run.holdUntil and now < run.holdUntil then
if run.phase == "cast" then A.runCastWait(hero, run.step, now) end
A.say("i6.panel.channel")
return
end
if run.breakUntil and now >= run.breakUntil then run.breakUntil = nil end
if UI.nochannel:Get() and not run.breakUntil and NPC.IsChannellingAbility(hero) then
if run.phase == "cast" and run.castHandle and Ability.GetCooldown(run.castHandle) > 0.05 then A.finishStep(now, true) end
A.say("i6.panel.channel")
if not run.channelLogged then
run.channelLogged = true
A.log("info", "channel in progress, holding", {})
end
return
end
if now < run.nextAt or NPC.HasModifier(hero, "modifier_item_meteor_hammer_custom_cast") then return end
if run.phase ~= "pick" and now >= run.deadline then
A.log("info", "step timeout", { step = run.step and run.step.id or "?" })
A.finishStep(now, false)
end
if run.detonateAt and now >= run.detonateAt then
run.detonateAt = nil
local emp = NPC.GetAbility(hero, "invoker_emp_custom")
if emp and Ability.GetCooldown(emp) <= 0.05 and A.validTarget(run.target) then
Ability.CastNoTarget(emp, false, false, true, CFG.identifier)
A.log("info", "emp detonate", { })
end
end
if run.detonateAt then
A.say("i6.panel.timing")
return
end
if run.phase == "invoke" then
A.runInvoke(hero, run.step, now)
return
end
if run.phase == "armed" then
A.runArmed(hero, run.step, now)
return
end
if run.phase == "wall_turn" then
A.runWallTurn(hero, run.step, now)
return
end
if run.phase == "cast" then
A.runCastWait(hero, run.step, now)
return
end
local steps = A.order()
if #steps == 0 then
A.say("i6.panel.nosteps")
return
end
run.close = nil
local plan = A.plan(hero, steps, run.target, now)
local choice = plan[1]
if choice then
A.log("info", "planner choice", { step = choice.step.id, score = math.floor(choice.score * 10) / 10 })
A.beginStep(hero, choice.step, choice.handle, run.target, now)
return
end
if not A.validTarget(run.target) then
A.say(run.wave and "i6.panel.nowave" or "i6.panel.notarget")
elseif A.invulnLeft(run.target) > 0 or (run.liftPending and now < run.liftPending) then
A.say("i6.panel.timing")
if not run.timingLogged then
run.timingLogged = true
A.log("info", "holding for landing", {
invuln = A.invulnLeft(run.target),
lift_pending = run.liftPending and (run.liftPending - now) or 0,
visible = NPC.IsVisible(run.target) == true,
})
end
elseif A.approach(hero, now) then
return
else
A.say("i6.panel.wait")
end
A.attackFiller(hero, now)
end
function A.start(hero, now, wave)
S.orbSeq = nil
S.combos = (S.combos or 0) + 1
S.run = {
wave = wave == true,
index = S.combos,
hpStart = A.hpPct(hero),
target = A.pickTarget(hero, wave),
phase = "pick",
step = nil,
nextAt = now,
nextRetarget = now,
nextAttack = now,
deadline = now + CFG.stepTimeout,
lastCast = {},
retryAt = {},
rangeLog = {},
missLog = {},
why = {},
landAt = nil,
liftStart = nil,
liftGuess = nil,
fieldUntil = 0,
channelLogged = false,
liftPending = nil,
timingLogged = false,
trk = { index = nil, x = 0, y = 0, t = 0, vx = 0, vy = 0 },
orbStep = 1,
invokeSent = false,
castAt = nil,
tries = 0,
}
A.log("info", "combo started", {
steps = #A.order(),
slot = B.active and B.active:Get() or 0,
wave = S.run.wave,
run = S.combos,
cataclysm_stacks = S.tal.e7 and (A.cataclysmStacks(hero) or "unreadable") or "no talent",
})
end
function A.stop(now, reason)
if not S.run then return end
local run = S.run
A.cancelWallMove(run)
S.run = nil
A.say("i6.panel.done")
A.log("info", "combo stopped", { reason = reason })
local missed = ""
for _, step in ipairs(STEPS) do
if A.selected(step.id) and not run.lastCast[step.id] then
missed = missed .. step.id .. "=" .. (run.why[step.id] or "never considered") .. "; "
end
end
if missed ~= "" then A.log("info", "steps that did not fire", { why = missed:sub(1, 900) }) end
if UI.restore:Get() then
S.orbSeq = { key = ORB_KEYS[(UI.orb:Get() or 2) + 1] or "e", left = 3, nextAt = now }
end
end
function A.orbTick(hero, now)
local seq = S.orbSeq
if not seq or S.run or now < seq.nextAt then return end
local orb = NPC.GetAbility(hero, ORBS[seq.key])
if not orb or Ability.GetLevel(orb) < 1 then
S.orbSeq = nil
return
end
Ability.CastNoTarget(orb, false, false, true, CFG.identifier)
seq.left = seq.left - 1
seq.nextAt = now + CFG.orbInterval
if seq.left <= 0 then S.orbSeq = nil end
end
function A.update()
local now = GameRules.GetGameTime()
if not UI.enabled or not UI.enabled:Get() then
A.stop(now, "off")
S.orbSeq = nil
A.say("i6.panel.off")
return
end
local hero = A.mine()
if not hero then
A.stop(now, "hero")
return
end
if not Entity.IsAlive(hero) then
A.stop(now, "dead")
S.orbSeq = nil
A.say("i6.panel.dead")
return
end
A.refreshTalents(hero, now)
local bound, boundWave = A.bound(UI.key), A.bound(UI.keyWave)
if not bound and not boundWave then
A.say("i6.panel.nokey")
return
end
local captured = (INPUT_CAPTURED and INPUT_CAPTURED()) == true
local held = bound and not captured and UI.key:IsDown() == true
local heldWave = boundWave and not captured and not held and UI.keyWave:IsDown() == true
local active, was = held or heldWave, S.held or S.heldWave
if active and not was then
if not NPC.IsSilenced(hero) and not NPC.IsStunned(hero) then A.start(hero, now, heldWave) end
elseif not active and was then
A.stop(now, "release")
end
S.held, S.heldWave = held == true, heldWave == true
if not S.run and not held and (S.status == "i6.panel.off" or S.status == "i6.panel.nohero") then
A.say("i6.panel.idle")
end
if not A.orderSafe() then return end
A.tick(hero, now)
A.orbTick(hero, now)
end
function B.list(slot)
if slot == 0 then
local ids = {}
for _, step in ipairs(A.full()) do ids[#ids + 1] = step.id end
return ids
end
local widget = B.widgets[slot]
local result = {}
for _, id in ipairs(widget:List() or {}) do
if BY_ID[id] and widget:Get(id) then result[#result + 1] = id end
end
return result
end
function B.save(slot, ids)
local rows, seen = {}, {}
for _, id in ipairs(ids) do
local step = BY_ID[id]
if step and not seen[id] then
seen[id] = true
rows[#rows + 1] = { id, step.icon, true }
end
end
for _, step in ipairs(STEPS) do
if not seen[step.id] then rows[#rows + 1] = { step.id, step.icon, false } end
end
B.widgets[slot]:Update(rows, true, true)
B.widgets[slot]:Set(ids)
A.log("info", "builder saved", { slot = slot, requested = #ids, actual = #B.list(slot) })
end
function B.blocked()
if B.popup and B.popup() then return true end
return INPUT_CAPTURED and INPUT_CAPTURED() and not (B.menuOpen and B.menuOpen())
end
function B.init(group)
B.popup = api(Input, "IsPopupOpen")
B.menuOpen = api(Menu, "Opened")
B.widgets[0] = UI.steps
UI.steps:Visible(false)
B.active = group:Slider("builder_active_v1", 0, 5, 0)
B.active:Visible(false)
B.positions = {}
for _, name in ipairs({ "main", "editor" }) do
B.positions[name] = {}
for _, axis in ipairs({ "x", "y" }) do
local value = axis == "x" and (name == "main" and 40 or 320) or 200
local widget = group:Slider("builder_" .. name .. "_" .. axis, 0, 16384, value)
widget:Visible(false)
B.positions[name][axis] = widget
end
end
for slot = 1, 5 do
local rows = {}
for _, step in ipairs(STEPS) do rows[#rows + 1] = { step.id, step.icon, false } end
B.widgets[slot] = group:MultiSelect("builder_preset_" .. slot, rows, true)
B.widgets[slot]:Visible(false)
end
B.symbol = Render.LoadFont("FontAwesomeEx", 0, 500)
end
function B.visible()
if not S.ready or not UI.builder or not UI.builder:Get() or not UI.enabled:Get() then return false end
return A.mine() ~= nil
end
function B.hit(x, y)
for i = #B.hits, 1, -1 do
local h = B.hits[i]
if x >= h.x and y >= h.y and x < h.x + h.w and y < h.y + h.h then return h end
end
end
function B.region(x, y, w, h, kind, value, tip)
B.hits[#B.hits + 1] = { x = x, y = y, w = w, h = h, kind = kind, value = value, tip = tip }
end
function B.rect(x, y, w, h, r, g, b, alpha)
Render.FilledRect(Vec2(x, y), Vec2(x + w, y + h), Color(r, g, b, alpha or 245), 4)
end
function B.text(text, x, y, size, dim)
Render.Text(S.font, size or 12, text, Vec2(x, y), dim and Color(151, 153, 160, 255) or Color(225, 226, 230, 255))
end
function B.tabs(x, y)
for slot = 0, 5 do
local bx = x + slot * 41
local selected = B.active:Get() == slot
B.rect(bx, y, 37, 21, selected and 218 or 40, selected and 57 or 41, selected and 60 or 45)
B.text(slot == 0 and "D" or tostring(slot), bx + 14, y + 3)
B.region(bx, y, 37, 21, "tab", slot)
end
end
function B.icon(id, x, y, kind, value, selected, number)
local step = BY_ID[id]
if B.images[id] == nil then
local ok, handle = pcall(Render.LoadImage, step.icon)
B.images[id] = ok and handle or false
end
B.rect(x - 2, y - 2, 38, 38, selected and 204 or 49, selected and 62 or 51, selected and 64 or 57)
if B.images[id] and B.images[id] ~= 0 then
Render.Image(B.images[id], Vec2(x, y), Vec2(34, 34), Color(255, 255, 255, 255), 3)
else
B.text(id:sub(1, 3), x + 2, y + 10, 10)
end
if number then
B.rect(x, y + 22, 14, 12, 18, 19, 23)
B.text(tostring(number), x + 2, y + 21, 10)
end
B.region(x - 2, y - 2, 38, 38, kind, value, id)
end
function B.action(action)
if action.kind == "toggle" then B.open = not B.open; return end
if action.kind == "close" then B.open = false; return end
if action.kind == "preview" then B.open = true; return end
if action.kind == "background" or action.kind == "drag" then return end
if S.run then A.stop(GameRules.GetGameTime(), "builder changed") end
if action.kind == "tab" then B.active:Set(action.value); return end
local slot = B.active:Get()
local ids = B.list(slot)
A.log("info", "builder click", { kind = action.kind, value = tostring(action.value), slot = slot })
if slot == 0 and action.kind ~= "reorder" then
A.log("info", "D is the full dynamic set and cannot be edited", { kind = action.kind })
return
end
if action.kind == "add" then
for _, id in ipairs(ids) do if id == action.value then return end end
ids[#ids + 1] = action.value
elseif action.kind == "remove" then
table.remove(ids, action.value)
elseif action.kind == "reorder" then
local id = table.remove(ids, action.value)
if id then table.insert(ids, math.min(action.to, #ids + 1), id) end
elseif action.kind == "copy" then
ids = B.list(0)
elseif action.kind == "clear" then
ids = {}
else return end
B.save(slot, ids)
end
function B.key(data)
if data.key ~= B.mouse then return true end
if data.event == B.up and B.press then
local press = B.press
B.press = nil
if not B.visible() or B.blocked() then B.drag = nil; return false end
local x, y = B.cursor()
local hit = B.hit(x, y)
if B.drag then
local pos = B.positions[B.drag.name]
pos.x:Set(math.floor(B.drag.x)); pos.y:Set(math.floor(B.drag.y))
B.drag = nil
elseif press.kind == "remove" and hit and hit.kind == "remove" and hit.value ~= press.value then
B.pending = { kind = "reorder", value = press.value, to = hit.value }
elseif not press.handled and hit and hit.kind == press.kind and hit.value == press.value then
B.pending = press
end
return false
end
if not B.visible() or not B.cursor or B.blocked() then return true end
local x, y = B.cursor()
local hit = B.hit(x, y)
if data.event == B.down and hit then
if B.press then return false end
B.press = hit
if hit.kind == "drag" then
B.drag = { name = hit.value, dx = x - hit.x, dy = y - hit.y, x = hit.x, y = hit.y }
elseif hit.kind ~= "remove" and hit.kind ~= "background" then
B.pending = { kind = hit.kind, value = hit.value }
B.press.handled = true
end
return false
end
return hit == nil
end
function B.position(name, height, screen)
local pos = B.positions[name]
local x, y = pos.x:Get(), pos.y:Get()
if B.drag and B.drag.name == name and B.cursor then
local mx, my = B.cursor()
x, y = mx - B.drag.dx, my - B.drag.dy
end
x, y = math.max(0, math.min(x, screen.x - 268)), math.max(0, math.min(y, screen.y - height))
if B.drag and B.drag.name == name then B.drag.x, B.drag.y = x, y end
return x, y
end
function B.draw()
if not B.visible() then B.hits = {}; B.drag = nil; return end
if B.pending then local pending = B.pending; B.pending = nil; B.action(pending) end
B.hits = {}
local screen = Render.ScreenSize()
local slot = B.active:Get()
local ids, selected = B.list(slot), {}
for _, id in ipairs(ids) do selected[id] = true end
local height = 63 + math.max(1, math.ceil(#ids / 6)) * 41
local x, y = B.position("main", height, screen)
B.rect(x, y, 268, height, 16, 17, 20, 235)
B.region(x, y, 268, height, "background")
B.rect(x, y, 268, 25, 30, 31, 35)
B.region(x, y, 237, 25, "drag", "main")
B.text(T("i6.builder.title") .. (slot == 0 and "" or "  /  " .. slot), x + 10, y + 5, 13)
Render.Text(B.symbol, 13, "\u{f08e}", Vec2(x + 245, y + 6), Color(216, 216, 223, 255))
B.region(x + 237, y, 31, 25, "toggle", nil, T("i6.builder.edit"))
B.tabs(x + 12, y + 30)
for i, id in ipairs(ids) do B.icon(id, x + 14 + ((i - 1) % 6) * 41, y + 60 + math.floor((i - 1) / 6) * 41, "preview", i, false) end
if #ids == 0 then B.text(T("i6.builder.empty"), x + 12, y + 69, 11, true) end
if B.open then
local eh = 317 + math.max(1, math.ceil(#ids / 6)) * 41
x, y = B.position("editor", eh + 49, screen)
B.rect(x, y, 268, eh, 16, 17, 20)
B.region(x, y, 268, eh, "background")
B.rect(x, y, 268, 25, 30, 31, 35)
B.region(x, y, 237, 25, "drag", "editor")
B.text(T("i6.builder.editor"), x + 10, y + 5, 13)
B.text("x", x + 247, y + 5)
B.region(x + 237, y, 31, 25, "close")
B.tabs(x + 12, y + 31)
B.text(T("i6.builder.spells"), x + 12, y + 62, 12, true)
local spells, items = 0, 0
for _, step in ipairs(STEPS) do
local index, iy
if step.src == "spell" then index = spells; spells = spells + 1; iy = 85 else index = items; items = items + 1; iy = 194 end
B.icon(step.id, x + 14 + (index % 6) * 41, y + iy + math.floor(index / 6) * 41, "add", step.id, selected[step.id])
end
B.text(T("i6.builder.items"), x + 12, y + 172, 12, true)
B.text(T("i6.builder.slot", slot == 0 and "D" or tostring(slot)), x + 12, y + 281, 12)
for i, id in ipairs(ids) do B.icon(id, x + 14 + ((i - 1) % 6) * 41, y + 307 + math.floor((i - 1) / 6) * 41, "remove", i, true, i) end
local footer = y + eh - 3
B.rect(x, footer, 268, 52, 16, 17, 20)
B.region(x, footer, 268, 52, "background")
B.text(T("i6.builder.hint"), x + 9, footer + 2, 10, true)
B.rect(x + 10, footer + 23, 143, 22, 43, 44, 49)
B.text(T("i6.builder.copy"), x + 20, footer + 26, 11)
B.region(x + 10, footer + 23, 143, 22, "copy")
B.rect(x + 161, footer + 23, 97, 22, 65, 32, 35)
B.text(T("i6.builder.clear"), x + 174, footer + 26, 11)
B.region(x + 161, footer + 23, 97, 22, "clear")
end
if B.cursor then
local mx, my = B.cursor()
local hit = B.hit(mx, my)
if B.press and B.press.kind == "remove" then
local id = ids[B.press.value]
if id and B.images[id] and B.images[id] ~= 0 then
Render.Image(B.images[id], Vec2(mx + 10, my - 17), Vec2(34, 34), Color(255, 255, 255, 190), 3)
end
end
if hit and hit.tip then
local width = Render.TextSize(S.font, 12, hit.tip).x + 16
local tx, ty = math.max(0, math.min(mx + 12, screen.x - width)), math.max(0, math.min(my + 22, screen.y - 26))
B.rect(tx, ty, width, 24, 30, 31, 35)
B.text(hit.tip, tx + 8, ty + 5, 12)
end
end
end
function A.buildMenu()
local tab = Menu.Find("Heroes", "Hero List", "Invoker") or Menu.Create("Heroes", "Hero List", "Invoker")
if not tab then return false end
