if not column then return false end
local left = column:Create("i6.menu.combo", 1)
local aim = column:Create("i6.menu.aim", 1)
local right = column:Create("i6.menu.extra", 2)
if not left or type(left.Switch) ~= "function" then return false end
if not right or type(right.Switch) ~= "function" then right = left end
if not aim or type(aim.Switch) ~= "function" then aim = left end
local rows = {}
for _, step in ipairs(STEPS) do
rows[#rows + 1] = { step.id, step.icon or "", step.def }
end
UI.enabled = left:Switch("i6.menu.enabled", false, "\u{f0e7}")
