UI.managate = right:Slider("i6.menu.managate", 0, 90, 0, "%d%%")
UI.ghosthp = right:Slider("i6.menu.ghosthp", 5, 80, 30, "%d%%")
UI.nochannel = right:Switch("i6.menu.nochannel", true)
UI.restore = right:Switch("i6.menu.restore", true)
UI.orb = right:Combo("i6.menu.orb", { "Quas", "Wex", "Exort" }, 2)
UI.builder = left:Switch("i6.menu.builder", true)
