end
function A.clearTimers()
S.meteorUntil = 0
S.hitsUntil = 0
S.hitsCheck = 0
S.hits = nil
S.hitsStarted = false
S.hitsSeen = false
S.hitsStartAt = 0
S.hitsDropped = false
S.throwUntil = 0
S.qCastAt = 0
S.swapUntil = 0
S.punchAt = 0
S.freeAt = 0
end
function A.pickTarget(hero)
local target = nil
if C.cursorHero then
local ok, value = pcall(C.cursorHero, Entity.GetTeamNum(hero), C.teamEnemy)
if ok then target = value end
end
if target and A.valid(target) and not Entity.IsSameTeam(hero, target) and not NPC.IsIllusion(target)
and A.distance(hero, target) <= UI.range:Get() then
return target
end
local cursor = C.cursorPos and C.cursorPos() or Entity.GetAbsOrigin(hero)
local best = nil
local bestDistance = math.huge
for _, enemy in ipairs(Heroes.GetAll()) do
if enemy ~= hero and A.valid(enemy) and not Entity.IsSameTeam(hero, enemy) and not NPC.IsIllusion(enemy)
and A.distance(hero, enemy) <= UI.range:Get() then
local distance = (Entity.GetAbsOrigin(enemy) - cursor):Length2D()
if distance < bestDistance then
best = enemy
bestDistance = distance
end
end
end
return best
end
function A.track(target, now)
local pos = Entity.GetAbsOrigin(target)
local trk = S.track
local id = Entity.GetIndex(target)
local dt = now - trk.t
if trk.id ~= id or trk.t <= 0 or dt <= 0 or dt > C.trackReset then
trk.id = id
trk.x, trk.y, trk.t, trk.vx, trk.vy = pos.x, pos.y, now, 0, 0
return
end
if dt < C.trackGap then return end
local vx = (pos.x - trk.x) / dt
local vy = (pos.y - trk.y) / dt
trk.vx = trk.vx * 0.45 + vx * 0.55
trk.vy = trk.vy * 0.45 + vy * 0.55
trk.x, trk.y, trk.t = pos.x, pos.y, now
end
function A.predict(target, delay)
local pos = Entity.GetAbsOrigin(target)
delay = IT.moveTime(target, delay, GameRules.GetGameTime())
if delay <= 0.02 then return pos end
local dx, dy = S.track.vx, S.track.vy
if S.track.id ~= Entity.GetIndex(target) then dx, dy = 0, 0 end
local sampled = math.sqrt(dx * dx + dy * dy)
local speed = NPC.GetMoveSpeed(target)
if type(speed) ~= "number" or speed <= 0 then speed = 0 end
if sampled > C.wMoving then
dx, dy = dx / sampled * speed, dy / sampled * speed
elseif speed > 0 and C.isRunning ~= nil and C.getRotation ~= nil and C.isRunning(target) then
local forward = C.getRotation(target):GetForward()
local flat = math.sqrt(forward.x * forward.x + forward.y * forward.y)
if flat < 0.01 then return pos end
dx, dy = forward.x / flat * speed, forward.y / flat * speed
else
return pos
end
return Vector(pos.x + dx * delay, pos.y + dy * delay, pos.z)
end
function A.settle()
local ok, latency = false, nil
if C.latency ~= nil then ok, latency = pcall(C.latency) end
if not ok or type(latency) ~= "number" or latency < 0 then latency = 0.1 end
return math.max(C.settleMin, math.min(C.settleMax, latency * 2 + C.settlePad))
end
function A.maxJump(w)
if C.special ~= nil then
local ok, value = pcall(C.special, w, "max_jump_distance", -1)
if ok and type(value) == "number" and value > 0 then return value end
end
return Ability.GetCastRange(w)
end
function A.updateRunTrack(unit, now)
local id = Entity.GetIndex(unit)
local pos = Entity.GetAbsOrigin(unit)
local track = S.enemyTrack[id]
if track ~= nil and now - track.last_time > C.trackReset then track = nil end
track = track or {
last_pos = pos,
last_time = now,
vel = Vector(0, 0, 0),
normal_speed = NPC.GetMoveSpeed(unit),
}
local dt = math.max(0.016, now - track.last_time)
local raw = (pos - track.last_pos) / dt
track.vel = raw * 0.58 + track.vel * 0.42
track.last_pos = pos
track.last_time = now
S.enemyTrack[id] = track
if not NPC.HasState(unit, C.stunned) and A.speedModifierLeft(unit, now) == nil then
track.normal_speed = NPC.GetMoveSpeed(unit)
end
end
function A.speedModifierLeft(unit, now)
local track = S.enemyTrack[Entity.GetIndex(unit)]
if track and track.speed_scan_at and now - track.speed_scan_at < 0.04 then return track.speed_left end
local best, generic = nil, nil
for _, modifier in ipairs(NPC.GetModifiers(unit) or {}) do
if not Modifier.IsDebuff(modifier) then
local name = Modifier.GetName(modifier):lower()
local left = Modifier.GetDieTime(modifier) - now
if left > 0.02 and left <= C.prediction.max_lead + 1
and (generic == nil or left < generic) then
generic = left
end
for _, word in ipairs(SPEED_WORDS) do
if name:find(word, 1, true) ~= nil then
if left > 0.02 and left <= C.prediction.max_lead + 1
and (best == nil or left < best) then
best = left
end
break
end
end
end
end
if best == nil and track and track.normal_speed
and NPC.GetMoveSpeed(unit) > track.normal_speed * C.prediction.boost_ratio then
best = generic or C.prediction.boost_fallback
end
if track then
track.speed_scan_at = now
track.speed_left = best
end
return best
end
function A.predictionDistance(unit, time, speed)
local lead = math.min(time, C.prediction.max_lead)
local now = GameRules.GetGameTime()
local boost_left = A.speedModifierLeft(unit, now)
if boost_left == nil or boost_left >= lead then return speed * lead end
local track = S.enemyTrack[Entity.GetIndex(unit)]
local normal = track and track.normal_speed or NPC.GetBaseSpeed(unit)
normal = math.min(speed, math.max(0, normal))
return speed * boost_left + normal * (lead - boost_left)
end
function A.movementVector(unit)
local track = S.enemyTrack[Entity.GetIndex(unit)]
local vel = track and track.vel or Vector(0, 0, 0)
local speed = vel:Length2D()
local move_speed = NPC.GetMoveSpeed(unit)
local forward = Entity.GetRotation(unit):GetForward():Normalized()
local run_vel = forward * move_speed
if speed > move_speed then
vel = vel:Normalized() * move_speed
speed = move_speed
end
if NPC.IsRunning(unit) then
if speed > 80 then
local align = vel:Normalized():Dot2D(forward)
if align > 0.35 then
local blend = math.max(0, math.min(1, (align - 0.35) / 0.65))
local blended = vel * (0.45 + blend * 0.2) + run_vel * (0.55 - blend * 0.2)
return blended, math.min(blended:Length2D(), move_speed)
end
end
return run_vel, move_speed
end
if speed > 18 then return vel * 0.35, speed * 0.35 end
return Vector(0, 0, 0), 0
end
function A.predictRun(unit, time)
local pos = Entity.GetAbsOrigin(unit)
time = IT.moveTime(unit, time, GameRules.GetGameTime())
if time <= 0.02 then return pos end
local vel, speed = A.movementVector(unit)
if speed <= 10 then return pos end
return pos + vel:Normalized() * A.predictionDistance(unit, time, speed)
end
function A.jumpPlan(hero, target, w)
local origin = Entity.GetAbsOrigin(hero)
local range = Ability.GetCastRange(w) - C.rangeKeep
local lead = math.max(0, IT.castPoint(w)) + A.settle() * 0.5
local dist = A.distance(hero, target)
if dist <= range then
local start = A.predictRun(target, lead)
local arrive = lead + dist / C.runSpeed
for _ = 1, 4 do
arrive = lead + (A.predictRun(target, arrive) - origin):Length2D() / C.runSpeed
end
local reach = A.predictRun(target, arrive)
local land = A.predictRun(target, arrive + C.jumpTime)
local shift = land - reach
local length = shift:Length2D()
local cap = A.maxJump(w) - C.landPad
local point
if length >= C.minLead then
if length > cap then shift = shift / length * cap end
point = start + shift
else
local dir = start - origin
local len = dir:Length2D()
point = len > 1 and start + dir / len * C.selfLead or start
end
return { anchor = target, point = point, time = arrive + C.jumpTime, lead = math.floor(length) }
end
local jump = A.maxJump(w) - C.landPad
local best = nil
for _, unit in ipairs(NPCs.InRadius(origin, range, Entity.GetTeamNum(hero), C.teamBoth, true, true) or {}) do
if unit ~= hero and unit ~= target and A.valid(unit) and (NPC.IsHero(unit) or NPC.IsCreep(unit))
and not NPC.IsStructure(unit) then
local time = lead + A.distance(hero, unit) / C.runSpeed + C.jumpTime
local goal = A.predict(target, time)
local gap = (goal - Entity.GetAbsOrigin(unit)):Length2D()
if gap <= jump and (best == nil or time < best.time) then
best = { anchor = unit, point = goal, time = time }
end
end
end
return best
end
function A.order(hero, kind, point, target, ability, fast)
local player = Players.GetLocal()
if player == nil then return end
Player.PrepareUnitOrders(player, kind, target, point, ability, C.issuer, hero, false, true, false, fast, C.identifier)
end
function A.castW(hero, target, w, now)
if not UI.spells:Get("spell.w") or not A.ready(w, hero) or NPC.HasState(target, C.stunned) then return false end
local plan = A.jumpPlan(hero, target, w)
if plan == nil or IT.cycloneEarly(target, now, plan.time, Ability.GetName(w)) then return false end
A.order(hero, C.orderVector, plan.point, plan.anchor, w, false)
A.order(hero, C.orderCastTarget, Vector(0, 0, 0), plan.anchor, w, false)
A.log("info", "marci rebound cast", { anchor = NPC.GetUnitName(plan.anchor), self = plan.anchor == target, lead = plan.lead })
S.nextAt = now + plan.time + A.settle()
S.freeAt = S.nextAt
S.attacking = nil
return true
end
function A.trackSwap(hero, q, now)
if q == nil or S.qCastAt <= 0 or now - S.qCastAt > C.swapWindow or now < S.swapUntil then return end
if Ability.IsInAbilityPhase(q) then return end
if not A.ready(q, hero) then
S.qCooled = true
return
end
if not S.qCooled then return end
S.swapUntil = S.qCastAt + C.swapDuration
S.qCastAt = 0
A.log("info", "marci dispose swap detected")
end
function A.swapPending(hero, now)
if now >= S.swapUntil or not UI.spells:Get("spell.q") then return false end
local q = A.ability(hero, C.qNames)
return q ~= nil and A.ready(q, hero)
end
function A.hitsMarginNow(now)
if S.punchAt > 0 and now - S.punchAt <= C.punchWindow then return C.hitsMarginFar end
return C.hitsMargin
end
function A.castQ(hero, target, q, now)
if not UI.spells:Get("spell.q") or not A.ready(q, hero) or now < S.qAt or now < S.meteorUntil then return false end
if A.distance(hero, target) > Ability.GetCastRange(q) + NPC.GetHullRadius(target) + C.qApproach then return false end
if IT.spellBlocked(target, now, Ability.GetName(q)) then return false end
if IT.controlEarly(target, now, math.max(0, IT.castPoint(q)) + A.settle()) then return false end
Ability.CastTarget(q, target, false, false, true, C.identifier)
A.log("info", "marci dispose cast", { dist = math.floor(A.distance(hero, target)) })
S.qAt = now + C.qGap
S.throwUntil = now + math.max(0, IT.castPoint(q)) + C.throwAir + A.settle()
S.freeAt = math.max(S.freeAt, now + math.max(0, IT.castPoint(q)) + A.settle())
if now < S.swapUntil then
S.swapUntil = 0
S.punchAt = now
A.log("info", "marci dispose punch cast")
else
S.qCastAt = now
S.qCooled = false
end
S.nextAt = now + C.orderGap
S.attacking = nil
return true
end
function A.castR(hero, target, r, q, w, now)
if not UI.spells:Get("spell.r") or not A.ready(r, hero) or NPC.HasModifier(hero, C.rMod) then return false end
local dist = A.distance(hero, target)
if S.legendQ then
local radius = C.pulseRadius
if C.special ~= nil then
local ok, value = pcall(C.special, r, "pulse_radius", -1)
if ok and type(value) == "number" and value > 0 then radius = value end
end
if dist > radius - C.pulseMargin then return false end
elseif dist > C.flurryReach + NPC.GetHullRadius(target) then
return false
end
if IT.cycloneEarly(target, now, math.max(0, IT.castPoint(r))) then return false end
Ability.CastNoTarget(r, false, false, true, C.identifier)
A.log("info", "marci unleash cast", { dist = math.floor(dist), legend = S.legendQ })
S.nextAt = now + math.max(C.orderGap, math.max(0, IT.castPoint(r)) + C.castMargin)
S.attacking = nil
return true
end
function A.castE(hero, target, e, now)
if not UI.spells:Get("spell.e") or not A.ready(e, hero) then return false end
if A.distance(hero, target) > C.eReach then return false end
Ability.CastNoTarget(e, false, false, true, C.identifier)
A.log("info", "marci bodyguard cast", { dist = math.floor(A.distance(hero, target)) })
S.nextAt = now + C.orderGap
S.attacking = nil
return true
end
function A.castLunge(hero, target, lunge, now)
if not UI.spells:Get("spell.lunge") or not A.ready(lunge, hero) then return false end
if C.isActivated ~= nil and not C.isActivated(lunge) then return false end
local origin = Entity.GetAbsOrigin(hero)
if IT.cycloneEarly(target, now, C.lungeTime) then return false end
local goal = A.predict(target, C.lungeTime + A.settle() * 0.5)
local dir = goal - origin
local dist = dir:Length2D()
local range = Ability.GetCastRange(lunge)
if dist < 1 or dist > range + C.lungeRadius - C.lungeMargin then return false end
local jump = math.max(C.lungeMin, math.min(dist, range - 25))
local point = origin + dir / dist * jump
Ability.CastPosition(lunge, point, false, false, true, C.identifier)
A.log("info", "marci lunge cast", { dist = math.floor(dist) })
S.nextAt = now + C.lungeTime + C.orderGap
S.freeAt = math.max(S.freeAt, now + C.lungeTime + A.settle())
S.attacking = nil
return true
end
function A.detectLegend(hero)
local changed = false
if not S.legendQ then
local hits = NPC.GetAbility(hero, C.hitsName)
if hits ~= nil and Ability.GetLevel(hits) > 0 and not Ability.IsHidden(hits) then
S.legendQ, changed = true, true
end
end
if changed or not S.legendShown then
S.legendShown = true
local key = S.legendQ and "menu.legend_q" or "menu.legend_none"
if UI.legend ~= nil then pcall(UI.legend.ForceLocalization, UI.legend, localization.Get(key)) end
if changed then A.log("info", "marci legendary detected", { q = S.legendQ }) end
end
end
function A.hitsReady(hero)
if not UI.spells:Get("spell.hits") then return nil end
local hits = NPC.GetAbility(hero, C.hitsName)
if hits == nil or Ability.GetLevel(hits) <= 0 or not A.ready(hits, hero) then return nil end
if C.isActivated ~= nil and not C.isActivated(hits) then return nil end
return hits
end
function A.holdLeft(target, now)
local held = false
for _, state in ipairs(C.holdStates) do
if NPC.HasState(target, state) then held = true end
end
local left = 0
for _, mod in ipairs(NPC.GetModifiers(target) or {}) do
local name = Modifier.GetName(mod)
for _, word in ipairs(C.holdWords) do
if name:find(word, 1, true) ~= nil then
local rest = Modifier.GetDieTime(mod) - now
if rest > left then left = rest end
held = true
end
end
end
if not held then return 0 end
return left
end
function A.meteorPoint(hero, target, item, now)
if now < S.throwUntil then return nil end
local delay, radius = C.meteorDelay, C.meteorRadius
if C.special ~= nil then
local ok, value = pcall(C.special, item, "max_duration", -1)
if ok and type(value) == "number" and value > 0 then delay = value end
ok, value = pcall(C.special, item, "impact_radius", -1)
if ok and type(value) == "number" and value > 0 then radius = value end
end
local pos = Entity.GetAbsOrigin(target)
delay = IT.itemFall(item, delay)
local reach = radius - NPC.GetHullRadius(target) - C.meteorMargin
local fall = delay + math.max(0, IT.castPoint(item)) + A.settle() * 0.5
local free = math.max(0, fall - A.holdLeft(target, now))
if NPC.GetMoveSpeed(target) * free <= reach then return pos, "hold" end
local hits = A.hitsReady(hero)
if hits ~= nil and now >= S.qAt and not A.airborne(target, now) and A.casterFree(hero, now) and not A.swapPending(hero, now)
and A.distance(hero, target) <= Ability.GetCastRange(hits) - NPC.GetHullRadius(target) - A.hitsMarginNow(now) then
return pos, "flurry"
end
return nil
end
function A.turnDelay(hero, point)
if C.turnRate == nil or C.getRotation == nil then return 0 end
local rate = C.turnRate(hero)
if type(rate) ~= "number" or rate <= 0 then return 0 end
local forward = C.getRotation(hero):GetForward()
local dir = point - Entity.GetAbsOrigin(hero)
local fl = math.sqrt(forward.x * forward.x + forward.y * forward.y)
local dl = math.sqrt(dir.x * dir.x + dir.y * dir.y)
if fl < 0.01 or dl < 1 then return 0 end
local cos = math.max(-1, math.min(1, (forward.x * dir.x + forward.y * dir.y) / (fl * dl)))
return C.turnTick * math.acos(cos) / rate
end
function A.hitsAim(hero, target, hits)
local base = math.max(0, IT.castPoint(hits)) + A.settle() * 0.5
local goal = Entity.GetAbsOrigin(target)
for _ = 1, 2 do
goal = A.predict(target, base + A.turnDelay(hero, goal))
end
return goal
end
function A.airborne(target, now)
if now < S.throwUntil then return true end
for _, name in ipairs(C.airMods) do
if NPC.HasModifier(target, name) then return true end
end
return false
end
function A.casterFree(hero, now)
if now < S.freeAt or NPC.HasState(hero, C.stunned) then return false end
for _, name in ipairs(C.airMods) do
if NPC.HasModifier(hero, name) then return false end
end
return not NPC.HasModifier(hero, C.runMod)
end
function A.castHits(hero, target, now)
if now < S.qAt or A.airborne(target, now) or not A.casterFree(hero, now) then return false end
local hits = A.hitsReady(hero)
if hits == nil or A.swapPending(hero, now) then return false end
local range = Ability.GetCastRange(hits)
local goal = A.hitsAim(hero, target, hits)
local dist = (goal - Entity.GetAbsOrigin(hero)):Length2D()
if dist > range + C.hitsApproach then return false end
if dist > range - NPC.GetHullRadius(target) - A.hitsMarginNow(now) then
A.order(hero, C.orderMove, goal, nil, nil, true)
S.qAt = now + C.moveGap
S.attacking = nil
return true
end
Ability.CastPosition(hits, goal, false, false, true, C.identifier)
local cast = math.max(0, IT.castPoint(hits))
S.hits = hits
S.hitsCheck = now + cast + A.settle() + C.hitsTurn
S.hitsUntil = S.hitsCheck + C.hitsChannel + C.hitsPad
S.hitsStarted = false
S.hitsSeen = false
S.hitsStartAt = 0
S.hitsDropped = false
A.log("info", "marci dispose hits cast", { dist = math.floor(dist) })
S.qAt = now + C.qGap
S.nextAt = now + C.orderGap
S.attacking = nil
return true
end
function A.idle(hero, target, now)
local id = Entity.GetIndex(target)
if S.attacking == id and now - (S.attackAt or 0) < 1.0 then return end
A.order(hero, C.orderAttack, Entity.GetAbsOrigin(target), target, nil, true)
S.attacking = id
S.attackAt = now
end
function A.itemBase(name)
return (name:gsub("^item_", ""):gsub("_custom$", ""))
end
function A.itemLabel(name)
return (A.itemBase(name):gsub("_", " "))
end
function A.itemIcon(name)
local base = A.itemBase(name)
return "panorama/images/items/" .. (ICON_FIX[base] or base) .. "_png.vtex_c"
end
function A.itemSkipped(name)
for _, fragment in ipairs(ITEM_SKIP) do
if name:find(fragment, 1, true) ~= nil then return true end
end
return false
end
function A.has(value, bit)
return type(value) == "number" and bit > 0 and math.floor(value / bit) % 2 >= 1
end
function A.itemKind(item)
local behavior = Ability.GetBehavior(item)
if A.has(behavior, C.bPassive) or A.has(behavior, C.bHidden) or A.has(behavior, C.bToggle) then return nil end
if A.has(behavior, C.bUnit) then
local team = Ability.GetTargetTeam(item)
if A.has(team, C.targetEnemy) then return "enemy" end
if A.has(team, C.targetFriendly) then return "self" end
return nil
end
if A.has(behavior, C.bPoint) then return "point" end
if A.has(behavior, C.bNo) then return "no" end
return nil
end
function A.scanItems(hero)
local labels, ids, signature = {}, {}, ""
for _, slot in ipairs(C.itemSlots) do
local item = NPC.GetItemByIndex(hero, slot)
if item ~= nil then
local name = Ability.GetName(item)
local label = A.itemLabel(name)
if not A.itemSkipped(name) and A.itemKind(item) ~= nil and ids[label] == nil then
labels[#labels + 1] = label
ids[label] = name
signature = signature .. label .. "=" .. name .. ","
end
end
end
return labels, ids, signature
end
function A.refreshItems(hero)
IT.tick()
local labels, ids, signature = A.scanItems(hero)
if signature == S.itemSig then return end
local rank, old, enabled = {}, {}, {}
for i, id in ipairs(UI.items:List()) do
rank[id] = i
old[id] = true
end
for _, id in ipairs(UI.items:ListEnabled()) do enabled[id] = true end
table.sort(labels, function(a, b) return (rank[a] or 1000) < (rank[b] or 1000) end)
local rows, selected = {}, {}
for i, label in ipairs(labels) do
local on = not old[label] or enabled[label] == true
rows[i] = { label, A.itemIcon(ids[label]), on }
if on then selected[#selected + 1] = label end
end
UI.items:Update(rows, true, true)
UI.items:Set(selected)
S.itemSig = signature
S.itemIds = ids
IT.sync(hero, labels, ids, A.itemIcon)
A.log("info", "marci items refreshed", { items = labels, enabled = selected })
end
function A.findItem(hero, label, name)
for _, slot in ipairs(C.itemSlots) do
local item = NPC.GetItemByIndex(hero, slot)
if item ~= nil and Ability.GetName(item) == name then return item end
end
for _, slot in ipairs(C.itemSlots) do
local item = NPC.GetItemByIndex(hero, slot)
if item ~= nil and A.itemLabel(Ability.GetName(item)) == label then return item end
end
return nil
end
function A.isJump(name)
return name:find("blink", 1, true) ~= nil or name:find("fallen_sky", 1, true) ~= nil
end
function A.itemReady(item, hero)
return item ~= nil and Ability.GetLevel(item) > 0 and Ability.IsCastable(item, NPC.GetMana(hero))
end
function A.clampPoint(hero, point, range)
if range <= 0 then return point end
local origin = Entity.GetAbsOrigin(hero)
local dx, dy = point.x - origin.x, point.y - origin.y
local length = math.sqrt(dx * dx + dy * dy)
local cap = math.max(0, range - 25)
if length <= cap or length <= 0 then return point end
local scale = cap / length
return Vector(origin.x + dx * scale, origin.y + dy * scale, point.z)
end
function A.comboReach(hero, ability)
local reach = 0
if ability ~= nil then reach = Ability.GetCastRange(ability) end
for _, label in ipairs(UI.items:ListEnabled()) do
local name = S.itemIds[label]
local item = name ~= nil and not A.isJump(name) and A.findItem(hero, label, name) or nil
if item ~= nil and A.itemReady(item, hero) then
local kind = A.itemKind(item)
if kind == "enemy" or kind == "point" then reach = math.max(reach, Ability.GetCastRange(item) + 75) end
end
end
return reach
end
function A.blinkPoint(hero, target)
local origin = Entity.GetAbsOrigin(hero)
local pos = Entity.GetAbsOrigin(target)
local dx, dy = pos.x - origin.x, pos.y - origin.y
local len = math.max(1, math.sqrt(dx * dx + dy * dy))
local range = NPC.GetAttackRange(hero) + NPC.GetAttackRangeBonus(hero)
local keep = range > 300 and math.max(C.blinkKeep, range - 100) or C.blinkKeep
return Vector(pos.x - dx / len * keep, pos.y - dy / len * keep, pos.z)
end
function A.orderMove(hero, point, now)
if now < S.moveAt then return end
A.order(hero, C.orderMove, point, nil, nil, false)
S.moveAt = now + C.moveGap
end
function A.isMeteor(name)
for _, fragment in ipairs(C.meteorItems) do
if name:find(fragment, 1, true) ~= nil then return true end
end
return false
end
function A.isShiva(name)
return name:find("shivas_guard", 1, true) ~= nil or name:find("gold_shiva", 1, true) ~= nil
end
function A.isHex(name)
return name:find("sheepstick", 1, true) ~= nil or name:find("hex", 1, true) ~= nil
end
function A.shivaHasTarget(hero, item)
local radius = C.shivaRadius
if C.special ~= nil then
local ok, value = pcall(C.special, item, "blast_radius", -1)
if ok and type(value) == "number" and value > 0 then radius = value end
end
for _, enemy in ipairs(Heroes.GetAll()) do
if A.valid(enemy) and not Entity.IsSameTeam(hero, enemy) and not NPC.IsIllusion(enemy)
and A.distance(hero, enemy) <= radius then
return true
end
end
return false
end
function A.useItems(hero, target, ability, now)
if now >= S.cycleAt then
S.done = {}
S.cycleAt = now + C.cycleGap
end
local distance = A.distance(hero, target)
for _, label in ipairs(UI.items:ListEnabled()) do
local name = S.itemIds[label]
if name ~= nil and not S.done[name] then
local item = A.findItem(hero, label, name)
if item == nil then
S.done[name] = true
elseif not IT.allow(hero, target, name, label) then
elseif A.itemReady(item, hero) then
local kind = A.itemKind(item)
local range = Ability.GetCastRange(item)
local jump = A.isJump(name)
if kind == nil then
S.done[name] = true
elseif jump and distance <= A.comboReach(hero, ability) then
elseif A.isShiva(name) and not A.shivaHasTarget(hero, item) then
elseif A.isMeteor(name) and A.meteorPoint(hero, target, item, now) == nil then
elseif (kind == "enemy" or kind == "point") and not jump and range > 0 and distance > range + 75 then
A.orderMove(hero, IT.stopPoint(hero, target, range), now)
return true
else
if kind == "enemy" then
Ability.CastTarget(item, target, false, false, true, C.identifier)
elseif kind == "self" then
Ability.CastTarget(item, hero, false, false, true, C.identifier)
elseif kind == "point" and jump then
Ability.CastPosition(item, A.clampPoint(hero, A.blinkPoint(hero, target), range), false, false, true, C.identifier)
elseif kind == "point" then
Ability.CastPosition(item, A.clampPoint(hero, Entity.GetAbsOrigin(target), range), false, false, true, C.identifier)
if A.isMeteor(name) then
local _, why = A.meteorPoint(hero, target, item, now)
S.meteorUntil = now + IT.itemFall(item, C.meteorFall)
A.log("info", "marci meteor", { why = why, hold = math.floor(A.holdLeft(target, now) * 100) / 100 })
end
else
Ability.CastNoTarget(item, false, false, true, C.identifier)
end
S.done[name] = true
local delay = math.max(0.08, math.max(0, IT.castPoint(item)) + 0.06)
if kind == "enemy" and A.isHex(name) then delay = math.max(delay, C.hexWait) end
S.nextAt = now + delay
S.attacking = nil
IT.chainMark(hero, target, name)
A.log("info", "marci combo item", { item = name, kind = kind })
return true
end
end
end
end
return false
end
function A.run(hero, target, now)
if NPC.HasModifier(hero, C.runMod) then return end
local w = A.ability(hero, C.wNames)
local q = A.ability(hero, C.qNames)
local r = A.ability(hero, C.rNames)
local e = A.ability(hero, C.eNames)
local lunge = A.ability(hero, C.lungeNames)
if (q ~= nil and Ability.IsInAbilityPhase(q)) or (w ~= nil and Ability.IsInAbilityPhase(w))
or (r ~= nil and Ability.IsInAbilityPhase(r)) then return end
A.trackSwap(hero, q, now)
if r ~= nil and A.castR(hero, target, r, q, w, now) then return end
if IT.breakLinken(hero, target, now) then return end
do local mw = IT.meteorCast(hero, target, now, C.identifier) if mw ~= nil then S.nextAt = now + mw return end end
if A.useItems(hero, target, w or q, now) then return end
for _, id in ipairs(IT.spellOrder(UI.spells)) do
if id == "spell.hits" and A.castHits(hero, target, now) then return end
if id == "spell.w" and w ~= nil and A.castW(hero, target, w, now) then return end
if id == "spell.e" and e ~= nil and A.castE(hero, target, e, now) then return end
if id == "spell.q" and q ~= nil and A.castQ(hero, target, q, now) then return end
if id == "spell.lunge" and lunge ~= nil and A.castLunge(hero, target, lunge, now) then return end
end
A.idle(hero, target, now)
end
function A.hitsLocked(now, hero)
local hits = S.hits
if hits == nil or now >= S.hitsUntil then return false end
local channel = (hero ~= nil and NPC.IsChannellingAbility(hero)) or Ability.IsChannelling(hits)
if channel then
if not S.hitsStarted then
S.hitsStarted = true
S.hitsUntil = now + C.hitsChannel + C.hitsPad + A.settle() * 0.5
A.log("info", "marci dispose hits started", { channel = true })
end
if not S.hitsSeen then S.hitsStartAt = now end
S.hitsSeen = true
S.hitsGap = false
return true
end
if S.hitsSeen and not S.hitsGap then
S.hitsGap = true
A.log("info", "marci hits channel gap", {
elapsed = math.floor((now - S.hitsStartAt) * 100) / 100,
stunned = hero ~= nil and NPC.HasState(hero, C.stunned),
})
end
if S.hitsSeen and now >= S.hitsStartAt + C.hitsChannel - C.hitsEndEarly then
S.hitsUntil = 0
A.log("info", "marci dispose hits ended")
return false
end
if not S.hitsStarted then
local started = Ability.IsChannelling(hits) or Ability.GetCooldown(hits) > 0
or (C.isActivated ~= nil and not C.isActivated(hits))
if started then
S.hitsStarted = true
S.hitsUntil = now + C.hitsChannel + C.hitsPad + A.settle() * 0.5
A.log("info", "marci dispose hits started", { channel = Ability.IsChannelling(hits), cd = Ability.GetCooldown(hits) })
elseif now >= S.hitsCheck and not Ability.IsInAbilityPhase(hits) then
A.log("info", "marci dispose hits not started")
S.hitsUntil = 0
return false
end
end
return true
end
function A.update()
local hero = Heroes.GetLocal()
if not A.valid(hero) or Entity.GetUnitName(hero) ~= C.hero then
if S.phase ~= "idle" then A.reset("no marci") end
return
end
local clock = GameRules.GetGameTime()
if clock >= S.itemAt and S.itemError == nil then
S.itemAt = clock + C.itemGap
A.detectLegend(hero)
local ok, err = pcall(A.refreshItems, hero)
if not ok then
S.itemError = tostring(err)
A.log("error", "marci items refresh failed", { error = S.itemError })
end
end
if not UI.enabled:Get() or not UI.key:IsDown() then
if S.phase ~= "idle" then A.reset("key released") end
return
end
if C.inputCaptured ~= nil and C.inputCaptured() then return end
if not A.orderSafe() then return end
if IT.heroDisabled(hero) then return end
local now = GameRules.GetGameTime()
if S.phase == "idle" then
S.target = A.pickTarget(hero)
if S.target == nil then return end
S.phase = "running"
S.startedAt = now
A.log("info", "marci combo started", { target = Entity.GetUnitName(S.target) })
end
local target = S.target
if IT.fogHold(target, now) then
if A.orderMove ~= nil then A.orderMove(hero, Entity.GetAbsOrigin(target), now) end
return
end
if not A.valid(target) or Entity.IsSameTeam(hero, target) or A.distance(hero, target) > UI.range:Get() + 1000 then
A.reset("target lost")
return
end
A.track(target, now)
A.updateRunTrack(target, now)
if now - S.startedAt > C.maxRun then
A.reset("timeout")
return
end
if A.hitsLocked(now, hero) then return end
if now < S.nextAt or NPC.IsChannellingAbility(hero) or NPC.HasModifier(hero, "modifier_item_meteor_hammer_custom_cast") then return end
A.run(hero, target, now)
end
function A.drawError()
local title = S.menuError and localization.Get("panel.menu_failed") or localization.Get("panel.error")
local message = S.menuError or S.error or S.itemError or "unknown"
Render.FilledRect(Vec2(20, 370), Vec2(780, 418), Color(20, 20, 24, 235), 4)
Render.Text(S.font, 14, title, Vec2(30, 377), Color(224, 50, 45, 245))
Render.Text(S.font, 12, message:sub(1, 160), Vec2(30, 397), Color(220, 220, 225, 240))
