skillIds = {},
skillSig = "",
skillRows = nil,
skillApply = 0,
skillRetries = 0,
skillOff = {},
razeIndex = nil,
razeStarted = 0,
}
local A = {}
function A.api(tbl, name)
return type(tbl) == "table" and type(tbl[name]) == "function" and tbl[name] or nil
end
function A.orderSafe()
local f = A.api(Humanizer, "IsSafeToCastOrder")
if f == nil then return true end
local ok, safe = pcall(f)
return not ok or safe ~= false
end
C.hasEnum = type(Enum) == "table"
C.bHidden = C.hasEnum and type(Enum.AbilityBehavior) == "table" and Enum.AbilityBehavior.DOTA_ABILITY_BEHAVIOR_HIDDEN or 1
C.bPassive = C.hasEnum and type(Enum.AbilityBehavior) == "table" and Enum.AbilityBehavior.DOTA_ABILITY_BEHAVIOR_PASSIVE or 2
C.bNo = C.hasEnum and type(Enum.AbilityBehavior) == "table" and Enum.AbilityBehavior.DOTA_ABILITY_BEHAVIOR_NO_TARGET or 4
C.bUnit = C.hasEnum and type(Enum.AbilityBehavior) == "table" and Enum.AbilityBehavior.DOTA_ABILITY_BEHAVIOR_UNIT_TARGET or 8
C.bPoint = C.hasEnum and type(Enum.AbilityBehavior) == "table" and Enum.AbilityBehavior.DOTA_ABILITY_BEHAVIOR_POINT or 16
C.bToggle = C.hasEnum and type(Enum.AbilityBehavior) == "table" and Enum.AbilityBehavior.DOTA_ABILITY_BEHAVIOR_TOGGLE or 512
C.orderVector = C.hasEnum and type(Enum.UnitOrder) == "table" and Enum.UnitOrder.DOTA_UNIT_ORDER_VECTOR_TARGET_POSITION or 30
C.orderCastTarget = C.hasEnum and type(Enum.UnitOrder) == "table" and Enum.UnitOrder.DOTA_UNIT_ORDER_CAST_TARGET or 6
C.orderCastTree = C.hasEnum and type(Enum.UnitOrder) == "table" and Enum.UnitOrder.DOTA_UNIT_ORDER_CAST_TARGET_TREE or 7
C.treesInRadius = A.api(Trees, "InRadius")
C.isUltimate = A.api(Ability, "IsUltimate")
C.orderMove = C.hasEnum and type(Enum.UnitOrder) == "table" and Enum.UnitOrder.DOTA_UNIT_ORDER_MOVE_TO_POSITION or 1
C.keyNone = C.hasEnum and type(Enum.ButtonCode) == "table" and Enum.ButtonCode.KEY_NONE or 0
C.isRunning = A.api(NPC, "IsRunning")
C.getRotation = A.api(Entity, "GetRotation")
C.bVector = C.hasEnum and type(Enum.AbilityBehavior) == "table" and Enum.AbilityBehavior.DOTA_ABILITY_BEHAVIOR_VECTOR_TARGETING or 1073741824
C.teamEnemy = C.hasEnum and type(Enum.TeamType) == "table" and Enum.TeamType.TEAM_ENEMY or 0
C.targetFriendly = C.hasEnum and type(Enum.TargetTeam) == "table" and Enum.TargetTeam.DOTA_UNIT_TARGET_TEAM_FRIENDLY or 1
C.targetEnemy = C.hasEnum and type(Enum.TargetTeam) == "table" and Enum.TargetTeam.DOTA_UNIT_TARGET_TEAM_ENEMY or 2
C.damageNone = C.hasEnum and type(Enum.DamageTypes) == "table" and Enum.DamageTypes.DAMAGE_TYPE_NONE or 0
C.keyF = C.hasEnum and type(Enum.ButtonCode) == "table" and Enum.ButtonCode.KEY_F or 16
C.cursorHero = A.api(Input, "GetNearestHeroToCursor")
C.cursorPos = A.api(Input, "GetWorldCursorPos")
function A.log(level, message, data)
if type(ai_bridge) ~= "table" or type(ai_bridge.mcp_log) ~= "function" then return end
pcall(ai_bridge.mcp_log, level, message, data)
end
function A.has(value, bit)
return type(value) == "number" and bit > 0 and math.floor(value / bit) % 2 >= 1
end
function A.valid(unit)
if unit == nil then return false end
local ok, alive = pcall(Entity.IsAlive, unit)
return ok and alive and not Entity.IsDormant(unit)
end
function A.distance(a, b)
return (Entity.GetAbsOrigin(a) - Entity.GetAbsOrigin(b)):Length2D()
end
function A.ready(ability, hero)
return ability ~= nil and Ability.GetLevel(ability) > 0 and not Ability.IsHidden(ability)
and Ability.IsCastable(ability, NPC.GetMana(hero))
end
function A.initMenu()
local side = (C.hasEnum and Enum.GroupSide) or {}
local raw = RawMenu.Create("Heroes", "Hero List", "Morphling", "1x6 Combo")
local section = localization.Wrap(raw, true)
local main = section:Create("menu.main", side.Left)
UI.enabled = main:Switch("menu.enabled", true, "panorama/images/heroes/icons/npc_dota_hero_morphling_png.vtex_c")
UI.key = main:Bind("menu.key", C.keyF, "panorama/images/spellicons/morphling_adaptive_strike_agi_png.vtex_c")
IT.publishKey("morphling_1x6_combo", UI.key)
UI.key:ToolTip("menu.key_tip")
A.spellRows = {
{ "spell.adaptive", "panorama/images/spellicons/morphling_adaptive_strike_agi_png.vtex_c", true },
{ "spell.wave", "panorama/images/spellicons/morphling_waveform_png.vtex_c", true },
{ "spell.replicate", "panorama/images/spellicons/morphling_replicate_png.vtex_c", true },
{ "spell.copied", "panorama/images/spellicons/morphling_morph_replicate_png.vtex_c", true },
}
UI.saveSpells = main:Input("menu.save_spells", "")
UI.saveSpells:Visible(false)
UI.spells = main:MultiSelect("menu.spells", IT.orderedRows(A.spellRows, UI.saveSpells), true)
UI.spells:DragAllowed(true)
IT.register({ C.hero }, UI.spells, UI.saveSpells, A.spellRows)
UI.spells:ToolTip("menu.spells_tip")
UI.range = main:Slider("menu.range", 600, 3000, 1800, "%d")
UI.aimKey = main:Bind("menu.aim_w", C.keyNone, "panorama/images/spellicons/morphling_adaptive_strike_agi_png.vtex_c")
UI.aimKey:ToolTip("menu.aim_w_tip")
UI.items = IT.build(section, side.Right, A.itemIcon, C.identifier, C.hero)
local copy = section:Create("menu.copy_group", side.Right)
UI.copyHero = copy:MultiSelect("menu.copy_hero", { { localization.Get("menu.copy_wait"), "", false } }, true)
UI.copyHero:ToolTip("menu.copy_hero_tip")
pcall(UI.copyHero.OneItemSelection, UI.copyHero, true)
UI.copySkills = copy:MultiSelect("menu.copy_skills", { { localization.Get("menu.copy_pick"), "", false } }, true)
UI.copySkills:ToolTip("menu.copy_skills_tip")
return true
end
function A.reset(reason, clearTarget)
if S.phase == "running" or S.phase == "manual" then
A.log("info", "morph combo stopped", { reason = reason, legend = S.legend or "none" })
end
S.phase = "idle"
if clearTarget then S.target = nil end
S.startedAt = 0
S.nextAt = 0
S.moveAt = 0
S.cycleAt = 0
S.done = {}
S.manual = false
S.copyLock = nil
S.copyEffect = nil
S.track = { id = nil, x = 0, y = 0, t = 0, vx = 0, vy = 0 }
end
function A.detectLegend(hero, now)
if now < S.legendAt then return end
S.legendAt = now + C.detectGap
local found = nil
local evidence = "none"
local w = NPC.GetAbility(hero, C.adaptive)
if w ~= nil and Ability.GetLevel(w) > 0 then
local behavior = Ability.GetBehavior(w)
if A.has(behavior, C.bPoint) then
found = "w"
evidence = "adaptive_point:" .. tostring(behavior)
end
end
if found == nil and (S.copyActive or NPC.HasModifier(hero, C.form)) and S.legend ~= nil then return end
if found ~= S.legend or evidence ~= S.legendEvidence then
S.legend = found
S.legendEvidence = evidence
A.log("info", "morph legendary detected", { legend = found or "none", evidence = evidence })
end
end
function A.itemBase(name)
return (name:gsub("^item_", ""):gsub("_custom$", ""))
end
function A.itemLabel(name)
return (A.itemBase(name):gsub("_", " "))
end
function A.itemIcon(name)
local base = A.itemBase(name)
return "panorama/images/items/" .. (ICON_FIX[base] or base) .. "_png.vtex_c"
end
function A.itemSkipped(name)
for _, fragment in ipairs(ITEM_SKIP) do
if name:find(fragment, 1, true) ~= nil then return true end
end
return false
end
function A.itemKind(item)
local behavior = Ability.GetBehavior(item)
if A.has(behavior, C.bPassive) or A.has(behavior, C.bHidden) or A.has(behavior, C.bToggle) then return nil end
if A.has(behavior, C.bUnit) then
local team = Ability.GetTargetTeam(item)
if A.has(team, C.targetEnemy) then return "enemy" end
if A.has(team, C.targetFriendly) then return "self" end
return nil
end
if A.has(behavior, C.bPoint) then return "point" end
if A.has(behavior, C.bNo) then return "no" end
return nil
end
function A.scanItems(hero)
local labels, ids, signature = {}, {}, ""
for _, slot in ipairs(C.slots) do
local item = NPC.GetItemByIndex(hero, slot)
if item ~= nil then
local name = Ability.GetName(item)
local label = A.itemLabel(name)
if not A.itemSkipped(name) and A.itemKind(item) ~= nil and ids[label] == nil then
labels[#labels + 1] = label
ids[label] = name
signature = signature .. label .. "=" .. name .. ","
end
end
end
return labels, ids, signature
end
function A.refreshItems(hero)
IT.tick()
local labels, ids, signature = A.scanItems(hero)
if signature == S.itemSig then return end
local rank, old, enabled = {}, {}, {}
for i, id in ipairs(UI.items:List()) do
rank[id] = i
old[id] = true
end
for _, id in ipairs(UI.items:ListEnabled()) do enabled[id] = true end
table.sort(labels, function(a, b) return (rank[a] or 1000) < (rank[b] or 1000) end)
local rows, selected = {}, {}
for i, label in ipairs(labels) do
local on = not old[label] or enabled[label] == true
rows[i] = { label, A.itemIcon(ids[label]), on }
if on then selected[#selected + 1] = label end
end
UI.items:Update(rows, true, true)
UI.items:Set(selected)
S.itemSig = signature
S.itemIds = ids
IT.sync(hero, labels, ids, A.itemIcon)
A.log("info", "morph items refreshed", { items = labels, enabled = selected })
end
function A.findSelectedItem(hero, label, name)
for _, slot in ipairs(C.slots) do
local item = NPC.GetItemByIndex(hero, slot)
if item ~= nil and Ability.GetName(item) == name then return item end
end
for _, slot in ipairs(C.slots) do
local item = NPC.GetItemByIndex(hero, slot)
if item ~= nil and A.itemLabel(Ability.GetName(item)) == label then return item end
end
return nil
end
function A.pickTarget(hero)
local target = nil
if C.cursorHero then
local ok, value = pcall(C.cursorHero, Entity.GetTeamNum(hero), C.teamEnemy)
if ok then target = value end
end
if target and A.valid(target) and not Entity.IsSameTeam(hero, target) and not NPC.IsIllusion(target)
and A.distance(hero, target) <= UI.range:Get() then
return target
end
local cursor = C.cursorPos and C.cursorPos() or Entity.GetAbsOrigin(hero)
local best = nil
local bestDistance = math.huge
for _, enemy in ipairs(Heroes.GetAll()) do
if enemy ~= hero and A.valid(enemy) and not Entity.IsSameTeam(hero, enemy) and not NPC.IsIllusion(enemy)
and A.distance(hero, enemy) <= UI.range:Get() then
local distance = (Entity.GetAbsOrigin(enemy) - cursor):Length2D()
if distance < bestDistance then
best = enemy
bestDistance = distance
end
end
end
return best
end
function A.start(hero, now)
local target = A.pickTarget(hero)
if target == nil then
S.phase = "target"
return false
end
S.target = target
S.phase = "running"
S.startedAt = now
S.nextAt = 0
S.moveAt = 0
S.cycleAt = now + C.cycleGap
S.done = {}
A.log("info", "morph combo started", { legend = S.legend or "none", target = Entity.GetUnitName(target) })
return true
end
function A.track(target, now)
local pos = Entity.GetAbsOrigin(target)
local trk = S.track
local id = Entity.GetIndex(target)
local dt = now - trk.t
if trk.id ~= id then
trk.id = id
trk.x, trk.y, trk.t, trk.vx, trk.vy = pos.x, pos.y, now, 0, 0
return
end
if trk.t <= 0 or dt <= 0 or dt > C.trackReset then
trk.x, trk.y, trk.t, trk.vx, trk.vy = pos.x, pos.y, now, 0, 0
return
end
if dt < C.trackGap then return end
local vx = (pos.x - trk.x) / dt
local vy = (pos.y - trk.y) / dt
trk.vx = trk.vx * 0.45 + vx * 0.55
trk.vy = trk.vy * 0.45 + vy * 0.55
trk.x, trk.y, trk.t = pos.x, pos.y, now
end
function A.attack(hero, target, now)
if now >= S.moveAt then
local player = Players.GetLocal()
if player ~= nil then
Player.AttackTarget(player, hero, target, false, false, false, C.identifier)
S.moveAt = now + C.moveGap
end
end
end
function A.approach(hero, target, range, now)
if range <= 0 or A.distance(hero, target) <= range + 75 then return false end
A.attack(hero, target, now)
return true
end
function A.approachRadius(hero, target, range, now)
if range <= 0 or A.distance(hero, target) <= math.max(0, range - 20) then return false end
A.attack(hero, target, now)
return true
end
function A.clampPoint(hero, point, range)
if range <= 0 then return point end
local origin = Entity.GetAbsOrigin(hero)
local dx = point.x - origin.x
local dy = point.y - origin.y
local length = math.sqrt(dx * dx + dy * dy)
local cap = math.max(0, range - 25)
if length <= cap or length <= 0 then return point end
local scale = cap / length
return Vector(origin.x + dx * scale, origin.y + dy * scale, point.z)
end
function A.castDelay(ability)
return math.max(C.orderGap, math.max(0, IT.castPoint(ability)) + C.castMargin)
end
function A.isJumpItem(name)
return name:find("blink", 1, true) ~= nil or name:find("fallen_sky", 1, true) ~= nil
end
function A.meteorPlan(name, target, now)
local meteor = false
for _, fragment in ipairs(METEOR_ITEMS) do
if name:find(fragment, 1, true) ~= nil then meteor = true end
end
if not meteor then return false, nil end
local fear = nil
for _, modifier in ipairs(FEAR_MODS) do
fear = fear or NPC.GetModifier(target, modifier)
end
if fear == nil then return false, nil end
local left = Modifier.GetDieTime(fear) - now
if type(left) ~= "number" or left <= 0 then return false, nil end
local speed = NPC.GetMoveSpeed(target)
if type(speed) ~= "number" then speed = 0 end
local free = math.max(0, C.meteorDelay - left)
if speed * free > C.meteorRadius - C.meteorMargin then return true, nil end
local vx, vy = A.targetVelocity(target)
local pos = Entity.GetAbsOrigin(target)
return false, Vector(pos.x + vx * left, pos.y + vy * left, pos.z), left, speed * free
end
function A.useItems(hero, target, now)
for _, label in ipairs(UI.items:ListEnabled()) do
local name = S.itemIds[label]
if name ~= nil and not S.done["item:" .. name] then
local item = A.findSelectedItem(hero, label, name)
if item == nil then
S.done["item:" .. name] = true
elseif not IT.allow(hero, target, name, label) then
elseif A.ready(item, hero) then
local kind = A.itemKind(item)
local range = Ability.GetCastRange(item)
if kind == nil then
S.done["item:" .. name] = true
elseif A.meteorPlan(name, target, now) then
elseif (kind == "enemy" or kind == "point") and not A.isJumpItem(name)
and A.approach(hero, target, range, now) then
return true
else
if kind == "enemy" then
Ability.CastTarget(item, target, false, false, true, C.identifier)
elseif kind == "self" then
Ability.CastTarget(item, hero, false, false, true, C.identifier)
elseif kind == "point" then
local _, planned, fearLeft, escape = A.meteorPlan(name, target, now)
Ability.CastPosition(item, A.clampPoint(hero, planned or Entity.GetAbsOrigin(target), range), false, false, true, C.identifier)
if planned ~= nil then
A.log("info", "morph meteor on fear", { fear_left = fearLeft, escape = math.floor(escape) })
end
else
Ability.CastNoTarget(item, false, false, true, C.identifier)
end
S.done["item:" .. name] = true
S.nextAt = now + A.castDelay(item)
IT.chainMark(hero, target, name)
A.log("info", "morph combo item", { item = name, kind = kind })
return true
end
end
end
end
return false
end
function A.wSpeedOf(ability)
local value = Ability.GetLevelSpecialValueFor(ability, "projectile_speed", -1)
if type(value) == "number" and value > 0 then return value end
return C.wSpeed
end
function A.targetVelocity(target)
local dx, dy = S.track.vx, S.track.vy
if S.track.id ~= Entity.GetIndex(target) then dx, dy = 0, 0 end
local sampled = math.sqrt(dx * dx + dy * dy)
local speed = NPC.GetMoveSpeed(target)
if type(speed) ~= "number" or speed <= 0 then speed = 0 end
if sampled > C.wMoving then
dx, dy = dx / sampled * speed, dy / sampled * speed
elseif speed > 0 and C.isRunning ~= nil and C.getRotation ~= nil and C.isRunning(target) then
local forward = C.getRotation(target):GetForward()
local flat = math.sqrt(forward.x * forward.x + forward.y * forward.y)
if flat > 0.01 then
dx, dy = forward.x / flat * speed, forward.y / flat * speed
else
dx, dy = 0, 0
end
else
dx, dy = 0, 0
end
return dx, dy
end
function A.wAim(hero, target, ability)
local origin = Entity.GetAbsOrigin(hero)
local pos = Entity.GetAbsOrigin(target)
local flight = IT.castPoint(ability) + (pos - origin):Length2D() / A.wSpeedOf(ability)
local dx, dy = A.targetVelocity(target)
dx, dy = dx * flight, dy * flight
local lead = math.sqrt(dx * dx + dy * dy)
if lead > C.wMaxLead and lead > 0 then
local scale = C.wMaxLead / lead
dx, dy = dx * scale, dy * scale
end
local point = Vector(pos.x + dx, pos.y + dy, pos.z)
return A.clampPoint(hero, point, Ability.GetCastRange(ability)), math.floor(lead), flight
end
function A.castAim(hero, target, ability, now, source)
local point, lead, flight = A.wAim(hero, target, ability)
Ability.CastPosition(ability, point, false, false, true, C.identifier)
S.wCast = { target = target, point = point, at = now, retries = 0 }
A.log("info", "morph adaptive cast", { legend = "w", kind = "point", lead = lead, impact = flight, source = source })
end
function A.wRetarget(hero, now)
local cast = S.wCast
if cast == nil then return end
local ability = NPC.GetAbility(hero, C.adaptive)
if ability == nil or not A.valid(cast.target) then
S.wCast = nil
return
end
if not Ability.IsInAbilityPhase(ability) then
if now - cast.at > IT.castPoint(ability) + 0.3 then S.wCast = nil end
return
end
if cast.retries >= C.wRetries then return end
local point = A.wAim(hero, cast.target, ability)
local drift = (point - cast.point):Length2D()
if drift <= C.wRetarget then return end
Ability.CastPosition(ability, point, false, false, true, C.identifier)
cast.point = point
cast.retries = cast.retries + 1
A.log("info", "morph adaptive retarget", { drift = math.floor(drift), retry = cast.retries })
end
function A.aimTick(hero, now)
local target = A.pickTarget(hero)
if target == nil then return end
A.track(target, now)
if S.wCast ~= nil then return end
local ability = NPC.GetAbility(hero, C.adaptive)
if not A.ready(ability, hero) or not A.has(Ability.GetBehavior(ability), C.bPoint) then return end
if Ability.IsInAbilityPhase(ability) then return end
if A.distance(hero, target) > Ability.GetCastRange(ability) + C.wMaxLead then return end
A.castAim(hero, target, ability, now, "aim")
end
function A.castAdaptive(hero, target, now)
if not UI.spells:Get("spell.adaptive") or S.done.adaptive then return false end
local ability = NPC.GetAbility(hero, C.adaptive)
if not A.ready(ability, hero) then return false end
local range = Ability.GetCastRange(ability)
if A.approach(hero, target, range, now) then return true end
if IT.controlEarly(target, now, IT.landLead(hero, target, ability, C.adaptiveSpeed)) then return false end
local behavior = Ability.GetBehavior(ability)
if S.legend == "w" and A.has(behavior, C.bPoint) then
A.castAim(hero, target, ability, now, "combo")
elseif A.has(behavior, C.bUnit) then
if IT.spellBlocked(target, now, Ability.GetName(ability)) then return false end
Ability.CastTarget(ability, target, false, false, true, C.identifier)
A.log("info", "morph adaptive cast", { legend = S.legend or "none", kind = "unit" })
else
return false
end
S.done.adaptive = true
S.nextAt = now + A.castDelay(ability)
return true
end
function A.targetRanged(target)
local best, seen = 0, 0
for index = 0, 23 do
local ability = NPC.GetAbilityByIndex(target, index)
if ability ~= nil and not Ability.IsHidden(ability) then
local behavior = Ability.GetBehavior(ability)
if not A.has(behavior, C.bPassive) and not A.has(behavior, C.bHidden) then
local range = Ability.GetCastRange(ability)
if type(range) == "number" then
seen = seen + 1
if range > best then best = range end
end
end
end
end
local attack = NPC.GetAttackRange(target)
if type(attack) ~= "number" then attack = 0 end
if seen > 0 and best > 0 then return best >= C.rangedSkill, best, attack end
return attack >= C.rangedAttack, best, attack
end
function A.castWave(hero, target, now)
if not UI.spells:Get("spell.wave") or S.done.wave then return false end
local ability = NPC.GetAbility(hero, C.wave)
if not A.ready(ability, hero) then return false end
local range = Ability.GetCastRange(ability)
local ranged, reach, attack = A.targetRanged(target)
local need = range
if ranged then need = math.max(250, range - C.waveThrough) end
if A.approach(hero, target, need, now) then return true end
if IT.cycloneEarly(target, now, IT.landLead(hero, target, ability, nil)) then return false end
local origin = Entity.GetAbsOrigin(hero)
local goal = Entity.GetAbsOrigin(target)
if ranged then
local delta = goal - origin
local length = delta:Length2D()
if length > 1 then
goal = origin + delta / length * math.min(length + C.waveThrough, range)
end
end
Ability.CastPosition(ability, A.clampPoint(hero, goal, range), false, false, true, C.identifier)
S.done.wave = true
S.nextAt = now + A.castDelay(ability)
A.log("info", "morph waveform cast", {
distance = math.floor(A.distance(hero, target)),
ranged = ranged,
reach = math.floor(reach),
attack = math.floor(attack),
through = ranged and C.waveThrough or 0,
})
return true
end
function A.castReplicate(hero, target, now)
if not UI.spells:Get("spell.replicate") or S.done.replicate then return false end
if S.copyActive then return false end
local ability = NPC.GetAbility(hero, C.replicate)
if not A.ready(ability, hero) then return false end
local behavior = Ability.GetBehavior(ability)
local kind = nil
if A.has(behavior, C.bNo) and not A.has(behavior, C.bUnit) then
Ability.CastNoTarget(ability, false, false, true, C.identifier)
kind = "no_target"
elseif A.has(behavior, C.bUnit) then
local copyTarget = A.copyChoice(hero)
if copyTarget == nil or not A.valid(copyTarget) or not NPC.IsVisible(copyTarget) then copyTarget = target end
if A.approach(hero, copyTarget, Ability.GetCastRange(ability), now) then return true end
if not Entity.IsSameTeam(hero, copyTarget) and IT.spellBlocked(copyTarget, now) then return false end
Ability.CastTarget(ability, copyTarget, false, false, true, C.identifier)
kind = "unit:" .. NPC.GetUnitName(copyTarget)
else
return false
end
S.done.replicate = true
S.nextAt = now + A.castDelay(ability) + 0.08
A.log("info", "morph replicate cast", { legend = S.legend, kind = kind })
return true
end
function A.vectorReady()
return C.orderVector ~= nil and C.orderCastTarget ~= nil
end
function A.vectorAnchor(hero, target, range)
local origin = Entity.GetAbsOrigin(hero)
local goal = Entity.GetAbsOrigin(target)
local best, bestDist = nil, nil
local trees = {}
if C.treesInRadius ~= nil and C.orderCastTree ~= nil then trees = C.treesInRadius(origin, range, true) or {} end
for _, tree in ipairs(trees) do
local gap = (Entity.GetAbsOrigin(tree) - goal):Length2D()
if gap >= C.vectorMin and gap <= C.vectorNear and (bestDist == nil or gap < bestDist) then
best, bestDist = tree, gap
end
end
if best ~= nil then return best, true end
for _, enemy in ipairs(Heroes.GetAll()) do
if enemy ~= target and enemy ~= hero and not Entity.IsSameTeam(hero, enemy)
and Entity.IsAlive(enemy) and not NPC.IsIllusion(enemy) and NPC.IsVisible(enemy) then
local pos = Entity.GetAbsOrigin(enemy)
local gap = (pos - goal):Length2D()
if gap >= C.vectorMin and gap <= C.vectorNear and (pos - origin):Length2D() <= range then
return enemy, false
end
end
end
return nil, false
end
function A.castVector(hero, ability, target, anchor, isTree)
local player = Players.GetLocal()
if player == nil then return false end
local anchorPos = Entity.GetAbsOrigin(anchor)
local goal = Entity.GetAbsOrigin(target)
local delta = goal - anchorPos
if anchor == target then delta = goal - Entity.GetAbsOrigin(hero) end
local length = delta:Length2D()
local point = goal
if length > 1 then
local base = anchor == target and goal or anchorPos
local span = anchor == target and C.vectorLead or (length + C.vectorLead)
point = base + delta / length * span
end
local unitArg = anchor
if isTree then unitArg = nil end
Player.PrepareUnitOrders(player, C.orderVector, unitArg, point, ability,
Enum.PlayerOrderIssuer.DOTA_ORDER_ISSUER_PASSED_UNIT_ONLY, hero, false, true)
Player.PrepareUnitOrders(player, isTree and C.orderCastTree or C.orderCastTarget, anchor, Vector(0, 0, 0), ability,
Enum.PlayerOrderIssuer.DOTA_ORDER_ISSUER_PASSED_UNIT_ONLY, hero, false, true)
return true
end
function A.copyKind(ability)
local behavior = Ability.GetBehavior(ability)
if A.has(behavior, C.bVector) then return "vector" end
if A.has(behavior, C.bPoint) then return "point" end
if A.has(behavior, C.bUnit) then
local team = Ability.GetTargetTeam(ability)
if A.has(team, C.targetEnemy) then return "unit" end
return nil
end
if A.has(behavior, C.bNo) then return "no_target" end
return nil
end
function A.isUlt(ability)
return C.isUltimate ~= nil and C.isUltimate(ability) == true
end
function A.isCopiedOffense(ability)
if ability == nil or Ability.GetLevel(ability) <= 0 or Ability.IsHidden(ability) then return false end
if A.isUlt(ability) then return false end
local name = Ability.GetName(ability)
if name == "" or name:find("morphling_", 1, true) == 1 then return false end
local behavior = Ability.GetBehavior(ability)
if A.has(behavior, C.bHidden) or A.has(behavior, C.bPassive) or A.has(behavior, C.bToggle)
then return false end
if A.has(behavior, C.bVector) and not A.vectorReady() then return false end
if A.copyKind(ability) == nil then return false end
local ok, damageType = pcall(Ability.GetDamageType, ability)
return DAMAGE_EXCEPTIONS[name] == true or DISABLE_EXCEPTIONS[name] == true
or (ok and damageType ~= nil and damageType ~= C.damageNone)
end
function A.copyAbilities(hero)
local result = {}
for index = 0, 5 do
local ability = NPC.GetAbilityByIndex(hero, index)
if A.isCopiedOffense(ability) and not S.skillOff[Ability.GetName(ability)] then result[#result + 1] = ability end
end
return result
end
function A.imagePath(path)
if S.images[path] == nil then
local ok, handle = pcall(Render.LoadImage, path)
S.images[path] = ok and handle or false
end
return path
end
function A.menuOn(widget, label)
local ok, on = pcall(widget.Get, widget, label)
return ok and on == true
end
function A.copyChoice(hero)
if UI.copyHero == nil then return nil end
for label, index in pairs(S.heroIds) do
if A.menuOn(UI.copyHero, label) then
for _, enemy in ipairs(Heroes.GetAll()) do
if Entity.GetIndex(enemy) == index then return enemy end
end
end
end
return nil
end
function A.syncCopyMenu(hero, now)
if UI.copyHero == nil or now < S.menuAt then return end
S.menuAt = now + C.itemGap
local rows, ids, parts = {}, {}, {}
for _, enemy in ipairs(Heroes.GetAll()) do
if enemy ~= hero and not Entity.IsSameTeam(hero, enemy) and not NPC.IsIllusion(enemy) then
local unit = NPC.GetUnitName(enemy)
local label = (unit:gsub("^npc_dota_hero_", ""):gsub("_", " "))
if ids[label] == nil then
rows[#rows + 1] = { label, A.imagePath("panorama/images/heroes/icons/" .. unit .. "_png.vtex_c"), A.menuOn(UI.copyHero, label) }
ids[label] = Entity.GetIndex(enemy)
parts[#parts + 1] = label
end
end
end
if #rows == 0 then rows[1] = { localization.Get("menu.copy_wait"), "", false } end
local sig = table.concat(parts, ";")
if sig ~= S.heroSig then
S.heroSig, S.heroIds, S.heroRows = sig, ids, rows
S.heroApply, S.heroRetries = 0, 2
end
local choice = A.copyChoice(hero)
local srows, sids, sparts = {}, {}, {}
if choice ~= nil then
local levelled = false
for index = 0, 5 do
local ability = NPC.GetAbilityByIndex(choice, index)
if ability ~= nil and Ability.GetLevel(ability) > 0 then levelled = true end
end
for index = 0, 5 do
local ability = NPC.GetAbilityByIndex(choice, index)
if ability ~= nil and not Ability.IsHidden(ability) and not A.isUlt(ability) and (not levelled or Ability.GetLevel(ability) > 0) then
local name = Ability.GetName(ability)
local behavior = Ability.GetBehavior(ability)
if name ~= "" and not A.has(behavior, C.bPassive) and not A.has(behavior, C.bHidden) then
local base = name:gsub("_custom$", ""):gsub("^custom_", "")
local label = (base:gsub("_", " "))
if sids[label] == nil then
local fresh = S.skillIds[label] == nil
srows[#srows + 1] = { label, A.imagePath("panorama/images/spellicons/" .. (SPELL_ICON[name] or base) .. "_png.vtex_c"), fresh or A.menuOn(UI.copySkills, label) }
sids[label] = name
sparts[#sparts + 1] = label
end
end
end
end
end
if #srows == 0 then srows[1] = { localization.Get("menu.copy_pick"), "", false } end
local ssig = table.concat(sparts, ";")
if ssig ~= S.skillSig then
S.skillSig, S.skillIds, S.skillRows = ssig, sids, srows
S.skillApply, S.skillRetries = 0, 2
end
if S.skillRows == nil then
local off = {}
for label, name in pairs(S.skillIds) do
if not A.menuOn(UI.copySkills, label) then off[name] = true end
end
S.skillOff = off
end
end
function A.applyRows(widget, rows, applyKey, retryKey)
local clock = os.clock()
if rows == nil or clock < S[applyKey] then return rows end
for _, row in ipairs(rows) do
if S.heroIds[row[1]] ~= nil or S.skillIds[row[1]] ~= nil then row[3] = A.menuOn(widget, row[1]) or row[3] end
end
pcall(widget.Update, widget, rows, true)
if S[retryKey] > 0 then
S[retryKey] = S[retryKey] - 1
S[applyKey] = clock + 2
return rows
end
return nil
end
function A.copyRemaining(ability)
return math.max(0, Ability.GetCooldown(ability), Ability.ChargeRestoreTimeRemaining(ability))
end
function A.syncCopied(hero, now)
local abilities = A.copyAbilities(hero)
local pending = S.copyPending
local present = {}
for _, ability in ipairs(abilities) do
local name = Ability.GetName(ability)
present[name] = true
local entry = S.copyMemory[name]
if entry == nil then
entry = { readyAt = now, mana = Ability.GetManaCost(ability) }
S.copyMemory[name] = entry
A.log("info", "morph copied ability tracked", { ability = name })
else
entry.mana = Ability.GetManaCost(ability)
end
local remaining = A.copyRemaining(ability)
if pending ~= nil and pending.name == name then
if remaining > 0 then
entry.readyAt = now + remaining
S.copyPending = nil
elseif now >= pending.confirmAt then
entry.readyAt = math.max(entry.readyAt, pending.fallbackAt)
S.copyPending = nil
end
elseif remaining > 0 then
entry.readyAt = now + remaining
end
end
if S.copyPrune then
for name in pairs(S.copyMemory) do
if not present[name] then S.copyMemory[name] = nil end
end
S.copyPrune = false
end
if S.copyPending ~= nil and now >= S.copyPending.confirmAt then
local entry = S.copyMemory[S.copyPending.name]
if entry ~= nil then entry.readyAt = math.max(entry.readyAt, S.copyPending.fallbackAt) end
S.copyPending = nil
end
return abilities
end
function A.updateCopySession(hero, now)
local active = NPC.HasModifier(hero, C.copyActive)
local form = active and NPC.HasModifier(hero, C.form)
if active ~= S.copyActive then
S.copyActive = active
S.copyForm = form
S.copyInitialized = form
S.copyMemory = {}
S.copyUsed = {}
S.copyPending = nil
S.copyPrune = form
S.copyLock = nil
S.copyEffect = nil
S.toggleWant = nil
S.toggleAt = 0
A.log("info", active and "morph copy session started" or "morph copy session ended", {})
elseif active and form ~= S.copyForm then
S.copyForm = form
S.copyInitialized = S.copyInitialized or form
S.copyUsed = {}
S.copyPending = nil
S.copyPrune = form
S.copyLock = nil
S.copyEffect = nil
S.toggleWant = nil
S.toggleAt = 0
if not form then
S.done = {}
S.cycleAt = now + C.cycleGap
end
A.log("info", "morph copy form changed", { copied = form })
end
if active and form then A.syncCopied(hero, now) end
end
function A.copyDue(hero, now)
if not S.copyInitialized then return true end
local mana = NPC.GetMana(hero)
for _, entry in pairs(S.copyMemory) do
if entry.readyAt <= now and mana >= entry.mana then return true end
end
return false
end
function A.castMorphToggle(hero, wantCopy, now)
local form = NPC.HasModifier(hero, C.form)
if form == wantCopy then
S.toggleWant = nil
S.toggleAt = 0
return false
end
if S.toggleWant ~= nil and now < S.toggleAt then return true end
S.toggleWant = nil
if now < S.toggleReady then return false end
if not S.copyActive then return false end
local ability = NPC.GetAbility(hero, C.morphToggle)
if not A.ready(ability, hero) then return false end
Ability.CastNoTarget(ability, false, false, true, C.identifier)
S.toggleWant = wantCopy
S.toggleAt = now + C.toggleConfirm
S.toggleReady = now + C.toggleGap
S.nextAt = now + A.castDelay(ability)
A.log("info", "morph form toggle", { copied = wantCopy })
return true
end
function A.copyCastLocked(hero, now)
local lock = S.copyLock
if lock == nil then return false end
if now < lock.untilAt or NPC.HasModifier(hero, lock.modifier) then return true end
S.copyLock = nil
return false
end
function A.checkCopyEffect(hero, now)
local effect = S.copyEffect
if effect == nil then return false end
if not A.valid(effect.target) then
S.copyEffect = nil
return false
end
local modifier = NPC.GetModifier(effect.target, effect.modifier)
if modifier ~= nil then
local caster = Modifier.GetCaster(modifier)
local ability = Modifier.GetAbility(modifier)
if caster == hero and ability ~= nil and Ability.GetName(ability) == effect.name then
local entry = S.copyMemory[effect.name]
if entry ~= nil then entry.effectAttempts = 0 end
S.copyEffect = nil
A.log("info", "morph copied effect confirmed", { ability = effect.name, modifier = effect.modifier })
return false
end
end
if now < effect.deadline then return true end
local entry = S.copyMemory[effect.name]
local ability = NPC.GetAbility(hero, effect.name)
local remaining = ability ~= nil and A.copyRemaining(ability) or 0
local retry = entry ~= nil and remaining <= 0 and effect.attempt < 2
if entry ~= nil then
if retry then
entry.readyAt = now + effect.retry
S.copyUsed[effect.name] = nil
elseif remaining > 0 then
entry.readyAt = now + remaining
entry.effectAttempts = 0
else
entry.readyAt = now + 2
entry.effectAttempts = 0
end
end
if S.copyPending ~= nil and S.copyPending.name == effect.name then S.copyPending = nil end
S.copyEffect = nil
S.copyLock = nil
A.log("warn", "morph copied effect not confirmed", {
ability = effect.name,
cooldown = remaining,
retry = retry,
})
return false
end
function A.razeMove(hero, point, face, now, queue)
if not queue and now < S.moveAt then return end
local player = Players.GetLocal()
if player == nil then return end
local issuer = Enum.PlayerOrderIssuer.DOTA_ORDER_ISSUER_PASSED_UNIT_ONLY
Player.PrepareUnitOrders(player, C.orderMove, nil, point, nil, issuer, hero, queue == true, true)
local dx, dy = face.x - point.x, face.y - point.y
local len = math.sqrt(dx * dx + dy * dy)
if len > 1 then
local turn = Vector(point.x + dx / len * C.razeTurn, point.y + dy / len * C.razeTurn, point.z)
Player.PrepareUnitOrders(player, C.orderMove, nil, turn, nil, issuer, hero, true, true)
end
S.moveAt = now + C.moveGap
end
function A.razeAim(hero, target, ability)
local origin = Entity.GetAbsOrigin(hero)
local pos = Entity.GetAbsOrigin(target)
local vx, vy = A.targetVelocity(target)
local lead = IT.castPoint(ability)
local goal = Vector(pos.x + vx * lead, pos.y + vy * lead, pos.z)
local dx, dy = goal.x - origin.x, goal.y - origin.y
local dist = math.sqrt(dx * dx + dy * dy)
if dist < 1 then dist, dx, dy = 1, 1, 0 end
local along, lateral = dist, 0
if C.getRotation ~= nil then
local forward = C.getRotation(hero):GetForward()
local flat = math.sqrt(forward.x * forward.x + forward.y * forward.y)
if flat > 0.01 then
local fx, fy = forward.x / flat, forward.y / flat
along = dx * fx + dy * fy
lateral = math.abs(dx * fy - dy * fx)
end
end
return goal, dist, dx / dist, dy / dist, along, lateral
end
function A.razeRange(ability, fallback)
local range = Ability.GetLevelSpecialValueFor(ability, "shadowraze_range", -1)
if type(range) ~= "number" or range <= 0 then return fallback end
return range
end
function A.razeStep(hero, target, now)
if S.razeIndex == nil or now - S.razeStarted > C.razeSequence then
S.razeIndex, S.razeStarted = 1, now
end
local raze, ability = nil, nil
while S.razeIndex <= #RAZES do
raze = RAZES[S.razeIndex]
ability = NPC.GetAbility(hero, raze.name)
if ability ~= nil and not S.skillOff[raze.name] and A.ready(ability, hero) then break end
S.razeIndex = S.razeIndex + 1
raze, ability = nil, nil
end
if raze == nil then
S.razeIndex = nil
return false
end
local range = A.razeRange(ability, raze.range)
local goal, dist, ux, uy, along, lateral = A.razeAim(hero, target, ability)
local band = C.razeRadius - C.razeMargin
if lateral <= band and math.abs(along - range) <= band then
Ability.CastNoTarget(ability, false, false, true, C.identifier)
S.nextAt = now + A.castDelay(ability)
S.razeIndex = S.razeIndex + 1
A.log("info", "morph raze cast", { raze = raze.name, dist = math.floor(dist), along = math.floor(along), lateral = math.floor(lateral) })
local nextRaze = RAZES[S.razeIndex]
if nextRaze ~= nil then
local nextAbility = NPC.GetAbility(hero, nextRaze.name)
local nextRange = nextAbility ~= nil and A.razeRange(nextAbility, nextRaze.range) or nextRaze.range
local stand = Vector(goal.x - ux * nextRange, goal.y - uy * nextRange, goal.z)
A.razeMove(hero, stand, goal, now, true)
end
return true
end
local stand = Vector(goal.x - ux * range, goal.y - uy * range, goal.z)
if math.abs(dist - range) <= band then stand = Entity.GetAbsOrigin(hero) end
A.razeMove(hero, stand, goal, now, false)
return true
end
function A.castCopied(hero, target, now)
local abilities = A.syncCopied(hero, now)
if S.copyPending ~= nil then return false, true end
if A.razeStep(hero, target, now) then return true, false end
local mana = NPC.GetMana(hero)
local blocked = false
for _, ability in ipairs(abilities) do
local name = Ability.GetName(ability)
local entry = S.copyMemory[name]
if not RAZE_SET[name] and not S.copyUsed[name] and entry ~= nil and entry.readyAt <= now then
local remaining = A.copyRemaining(ability)
if remaining > 0 then
entry.readyAt = now + remaining
S.copyUsed[name] = true
elseif mana < entry.mana then
S.copyUsed[name] = true
elseif not Ability.IsCastable(ability, mana) then
blocked = true
else
local kind = A.copyKind(ability)
local range = Ability.GetCastRange(ability)
local lock = COPY_CAST_LOCKS[name]
if kind == "vector" then
local anchor, isTree = A.vectorAnchor(hero, target, range)
if anchor == nil then
if A.approach(hero, target, range, now) then return true, false end
anchor, isTree = target, false
end
if not A.castVector(hero, ability, target, anchor, isTree) then
S.copyUsed[name] = true
return false, blocked
end
A.log("info", "morph copied vector cast", {
ability = name,
anchor = anchor == target and "direct" or (isTree and "tree" or NPC.GetUnitName(anchor)),
})
elseif kind == "point" then
if A.approach(hero, target, range, now) then return true, false end
Ability.CastPosition(ability, A.clampPoint(hero, Entity.GetAbsOrigin(target), range), false, false, true, C.identifier)
elseif kind == "unit" then
if A.approach(hero, target, range, now) then return true, false end
if IT.spellBlocked(target, now, Ability.GetName(ability)) then return false, blocked end
Ability.CastTarget(ability, target, false, false, true, C.identifier)
else
if lock ~= nil and lock.approach and A.approachRadius(hero, target, range, now) then return true, false end
Ability.CastNoTarget(ability, false, false, true, C.identifier)
end
local fallbackAt = now + math.max(C.copyFallback, Ability.GetCooldownLength(ability))
entry.readyAt = fallbackAt
S.copyUsed[name] = true
S.copyPending = {
name = name,
confirmAt = now + C.copyConfirm,
fallbackAt = fallbackAt,
}
local delay = A.castDelay(ability)
if lock ~= nil then
delay = math.max(delay, lock.delay)
S.copyLock = {
modifier = lock.modifier,
untilAt = now + lock.delay,
}
if lock.effect ~= nil then
entry.effectAttempts = (entry.effectAttempts or 0) + 1
S.copyEffect = {
name = name,
target = target,
modifier = lock.effect,
deadline = now + lock.confirm,
retry = lock.retry,
attempt = entry.effectAttempts,
}
end
end
S.nextAt = now + delay
A.log("info", "morph copied ability cast", { ability = name, kind = kind })
return true, false
end
end
end
return false, blocked
end
function A.run(hero, target, now)
if now >= S.cycleAt then
S.done = {}
S.cycleAt = now + C.cycleGap
end
if S.toggleWant ~= nil and A.castMorphToggle(hero, S.toggleWant, now) then return true end
if target ~= nil and IT.breakLinken(hero, target, now) then return true end
if target ~= nil then local mw = IT.meteorCast(hero, target, now, C.identifier) if mw ~= nil then S.nextAt = now + mw return true end end
if NPC.HasModifier(hero, C.form) then
if A.copyCastLocked(hero, now) then return true end
if not UI.spells:Get("spell.copied") then
if A.useItems(hero, target, now) then return true end
if A.castMorphToggle(hero, false, now) then return true end
else
local casted, blocked = A.castCopied(hero, target, now)
if casted then return true end
if A.useItems(hero, target, now) then return true end
if blocked or S.copyPending ~= nil then
A.attack(hero, target, now)
return false
end
if A.castMorphToggle(hero, false, now) then return true end
end
A.attack(hero, target, now)
return false
end
if A.useItems(hero, target, now) then return true end
for _, id in ipairs(IT.spellOrder(UI.spells)) do
if id == "spell.adaptive" and A.castAdaptive(hero, target, now) then return true end
if id == "spell.wave" and A.castWave(hero, target, now) then return true end
if id == "spell.replicate" and not S.copyActive and A.castReplicate(hero, target, now) then return true end
end
if S.copyActive and UI.spells:Get("spell.copied") and A.copyDue(hero, now) and A.castMorphToggle(hero, true, now) then return true end
A.attack(hero, target, now)
return false
end
function A.update()
local hero = Heroes.GetLocal()
if not A.valid(hero) or Entity.GetUnitName(hero) ~= C.hero then
if S.phase ~= "idle" then A.reset("no morphling", true) end
return
end
local now = GameRules.GetGameTime()
A.updateCopySession(hero, now)
A.detectLegend(hero, now)
if now >= S.itemAt and S.itemError == nil then
S.itemAt = now + C.itemGap
local ok, err = pcall(A.refreshItems, hero)
if not ok then
S.itemError = tostring(err)
A.log("error", "morph items refresh failed", { error = S.itemError })
end
end
if not UI.enabled:Get() then
if S.phase ~= "idle" then A.reset("disabled", true) end
return
end
A.syncCopyMenu(hero, now)
A.wRetarget(hero, now)
if not UI.key:IsDown() and UI.aimKey ~= nil and UI.aimKey:IsDown() then
A.aimTick(hero, now)
return
end
if not UI.key:IsDown() then
if S.phase ~= "idle" and S.phase ~= "target" then A.reset("key released", true) end
if S.phase == "target" then S.phase = "idle" end
S.manual = false
return
end
if S.manual then
S.phase = "manual"
return
end
if not A.orderSafe() then return end
if IT.heroDisabled(hero) then return end
if S.phase == "idle" or S.phase == "target" or S.phase == "talent" then
if not A.start(hero, now) then return end
end
local target = S.target
if not A.valid(target) or Entity.IsSameTeam(hero, target) then
A.reset("target lost", true)
S.phase = "target"
return
end
if A.distance(hero, target) > UI.range:Get() + 1000 then
A.reset("target too far", true)
S.phase = "target"
return
end
if now - S.startedAt > C.maxRun then
A.reset("timeout", true)
return
end
S.phase = "running"
A.track(target, now)
if A.checkCopyEffect(hero, now) then return end
if now < S.nextAt or NPC.IsChannellingAbility(hero) or NPC.HasModifier(hero, "modifier_item_meteor_hammer_custom_cast") then return end
A.run(hero, target, now)
end
function A.drawError()
local title = S.menuError and localization.Get("panel.menu_failed") or localization.Get("panel.error")
local message = S.menuError or S.error or S.itemError or "unknown"
Render.FilledRect(Vec2(20, 370), Vec2(780, 418), Color(20, 20, 24, 235), 4)
Render.Text(S.font, 14, title, Vec2(30, 377), Color(224, 50, 45, 245))
Render.Text(S.font, 12, message:sub(1, 160), Vec2(30, 397), Color(220, 220, 225, 240))
end
function script.OnScriptsLoaded()
local ok, result = pcall(A.initMenu)
S.ready = ok and result == true
if not S.ready then S.menuError = ok and "initMenu returned false" or tostring(result) end
S.font = Render.LoadFont("MuseoSansEx", 0, 500)
A.log("info", "morphling_1x6_combo loaded", { ready = S.ready, error = S.menuError, auto_legend = true, auto_items = true })
end
function script.OnUpdate()
if not S.ready or not Engine.IsInGame() then return end
local ok, err = pcall(A.update)
if not ok then
if S.error == nil then A.log("error", "morph combo update failed", { error = tostring(err) }) end
S.error = tostring(err)
A.reset("error", true)
end
