end
function A.blockers(hero, target, range)
local list = {}
local origin = Entity.GetAbsOrigin(hero)
local ok, units = pcall(NPCs.InRadius, origin, range + 200, Entity.GetTeamNum(hero), C.teamBoth, false, true)
if not ok or type(units) ~= "table" then return list end
for _, unit in ipairs(units) do
if unit ~= hero and unit ~= target and Entity.IsAlive(unit)
and (NPC.IsCreep(unit) or NPC.IsConsideredHero(unit) or NPC.IsHero(unit))
and not NPC.IsStructure(unit) and not NPC.IsWard(unit) and not NPC.IsCourier(unit) then
