function A.rayHits(origin, dx, dy, point, hull, range, width, blockers)
local px, py = point.x - origin.x, point.y - origin.y
local along = px * dx + py * dy
if along <= 0 or along > range + hull then return false end
local lateral = math.abs(px * dy - py * dx)
if lateral > width / 2 + hull - C.hitPad then return false end
for _, unit in ipairs(blockers) do
local ux, uy = unit.pos.x - origin.x, unit.pos.y - origin.y
local ua = ux * dx + uy * dy
if ua > 0 and ua < along and math.abs(ux * dy - uy * dx) <= width / 2 + unit.hull + C.blockPad then
