local range = Ability.GetCastRange(q)
if range <= 0 then range = A.hookValue(q, "hook_distance", 1300) end
local lead = math.max(0, IT.castPoint(q)) + A.settle() * 0.5
local point = Entity.GetAbsOrigin(target)
for _ = 1, C.iterations do
point = A.predictRun(target, lead + (point - origin):Length2D() / speed)
end
local dist = (point - origin):Length2D()
local hull = NPC.GetHullRadius(target)
if dist > range + hull then return nil, dist, range end
local len = math.max(1, dist)
local bx, by = (point.x - origin.x) / len, (point.y - origin.y) / len
local blockers = A.blockers(hero, target, range)
local fan = S.legend and { 0, -C.fanAngle, C.fanAngle } or { 0 }
for _, shift in ipairs(fan) do
local ax, ay = A.rotate(bx, by, -shift)
local hit = false
