C.targetEnemy = C.hasEnum and type(Enum.TargetTeam) == "table" and Enum.TargetTeam.DOTA_UNIT_TARGET_TEAM_ENEMY or 2
C.stunned = C.hasEnum and type(Enum.ModifierState) == "table" and Enum.ModifierState.MODIFIER_STATE_STUNNED or 5
function A.log(level, message, data)
if type(ai_bridge) ~= "table" or type(ai_bridge.mcp_log) ~= "function" then return end
pcall(ai_bridge.mcp_log, level, message, data)
end
function A.valid(unit)
if unit == nil then return false end
local ok, alive = pcall(Entity.IsAlive, unit)
return ok and alive and not Entity.IsDormant(unit)
end
function A.distance(a, b)
return (Entity.GetAbsOrigin(a) - Entity.GetAbsOrigin(b)):Length2D()
end
function A.ready(ability, hero)
return ability ~= nil and Ability.GetLevel(ability) > 0 and Ability.IsReady(ability)
and Ability.GetCooldown(ability) <= 0 and Ability.IsCastable(ability, NPC.GetMana(hero))
end
function A.settle()
local ok, latency = false, nil
if C.latency ~= nil then ok, latency = pcall(C.latency) end
if not ok or type(latency) ~= "number" or latency < 0 then latency = 0.1 end
return math.max(C.settleMin, math.min(C.settleMax, latency * 2 + C.settlePad))
end
function A.ramIcon()
local data = "data:image/png;base64," .. C.ramIcon
local svg = '<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="48" height="48" viewBox="0 0 48 48">'
.. '<image x="0" y="0" width="48" height="48" href="' .. data .. '" xlink:href="' .. data .. '"/></svg>'
return Render.LoadSvgString(svg, Vec2(48, 48), "pangolier_1x6_rolling_ram")
end
function A.initMenu()
local side = (C.hasEnum and Enum.GroupSide) or {}
local raw = RawMenu.Create("Heroes", "Hero List", "Pangolier", "1x6 Combo")
local section = localization.Wrap(raw, true)
local main = section:Create("menu.main", side.Left)
UI.enabled = main:Switch("menu.enabled", true, "panorama/images/heroes/icons/npc_dota_hero_pangolier_png.vtex_c")
UI.key = main:Bind("menu.key", C.keyF, "panorama/images/spellicons/pangolier_gyroshell_png.vtex_c")
IT.publishKey("pangolier_1x6_combo", UI.key)
UI.key:ToolTip("menu.key_tip")
A.spellRows = {
{ "spell.r", "panorama/images/spellicons/pangolier_gyroshell_png.vtex_c", true },
{ "spell.q", "panorama/images/spellicons/pangolier_swashbuckle_png.vtex_c", true },
{ "spell.w", "panorama/images/spellicons/pangolier_shield_crash_png.vtex_c", true },
{ "spell.e", "panorama/images/spellicons/pangolier_lucky_shot_png.vtex_c", true },
}
UI.saveSpells = main:Input("menu.save_spells", "")
UI.saveSpells:Visible(false)
UI.spells = main:MultiSelect("menu.spells", IT.orderedRows(A.spellRows, UI.saveSpells), true)
UI.spells:DragAllowed(true)
IT.register({ C.hero }, UI.spells, UI.saveSpells, A.spellRows)
UI.ram = main:Switch("spell.ram", true)
local okIcon, ramIcon = pcall(A.ramIcon)
if okIcon and ramIcon then UI.ram:ImageHandle(ramIcon) end
UI.w7 = main:Switch("menu.w7", true, "panorama/images/spellicons/pangolier_shield_crash_png.vtex_c")
UI.w7:ToolTip("menu.w7_tip")
UI.bounce = main:Switch("menu.bounce", true, "\u{f2f1}")
UI.bounce:ToolTip("menu.bounce_tip")
UI.ramMargin = main:Slider("menu.ram_margin", 0, 400, 120, "%d")
UI.ramMargin:ToolTip("menu.ram_margin_tip")
UI.range = main:Slider("menu.range", 800, 2500, 1500, "%d")
UI.range:Icon("\u{f05b}")
UI.items = IT.build(section, side.Right, A.itemIcon, C.identifier, C.hero)
return true
end
function A.reset(reason)
if S.phase ~= "idle" then A.log("info", "pangolier combo stopped", { reason = reason }) end
S.phase = "idle"
S.target = nil
S.startedAt = 0
S.nextAt = 0
S.moveAt = 0
S.attacking = nil
S.rams = 0
S.spellCast = false
S.rollSeen = false
S.steerAt = 0
S.done = {}
S.cycleAt = 0
end
function A.pickTarget(hero)
local target = nil
if C.cursorHero then
local ok, value = pcall(C.cursorHero, Entity.GetTeamNum(hero), C.teamEnemy)
if ok then target = value end
end
if target and A.valid(target) and not Entity.IsSameTeam(hero, target) and not NPC.IsIllusion(target)
and A.distance(hero, target) <= UI.range:Get() then
return target
end
local cursor = C.cursorPos and C.cursorPos() or Entity.GetAbsOrigin(hero)
local best, bestDistance = nil, math.huge
for _, enemy in ipairs(Heroes.GetAll()) do
if enemy ~= hero and A.valid(enemy) and not Entity.IsSameTeam(hero, enemy) and not NPC.IsIllusion(enemy)
and A.distance(hero, enemy) <= UI.range:Get() then
local distance = (Entity.GetAbsOrigin(enemy) - cursor):Length2D()
if distance < bestDistance then
best, bestDistance = enemy, distance
end
end
end
return best
end
function A.updateRunTrack(unit, now)
local id = Entity.GetIndex(unit)
local pos = Entity.GetAbsOrigin(unit)
local track = S.enemyTrack[id]
if track ~= nil and now - track.last_time > C.trackReset then track = nil end
track = track or {
last_pos = pos,
last_time = now,
vel = Vector(0, 0, 0),
normal_speed = NPC.GetMoveSpeed(unit),
}
local dt = math.max(0.016, now - track.last_time)
local raw = (pos - track.last_pos) / dt
track.vel = raw * 0.58 + track.vel * 0.42
track.last_pos = pos
track.last_time = now
S.enemyTrack[id] = track
if not NPC.HasState(unit, C.stunned) and A.speedModifierLeft(unit, now) == nil then
track.normal_speed = NPC.GetMoveSpeed(unit)
end
end
function A.speedModifierLeft(unit, now)
local track = S.enemyTrack[Entity.GetIndex(unit)]
if track and track.speed_scan_at and now - track.speed_scan_at < 0.04 then return track.speed_left end
local best, generic = nil, nil
for _, modifier in ipairs(NPC.GetModifiers(unit) or {}) do
if not Modifier.IsDebuff(modifier) then
local name = Modifier.GetName(modifier):lower()
local left = Modifier.GetDieTime(modifier) - now
if left > 0.02 and left <= C.prediction.max_lead + 1
and (generic == nil or left < generic) then
generic = left
end
for _, word in ipairs(SPEED_WORDS) do
if name:find(word, 1, true) ~= nil then
if left > 0.02 and left <= C.prediction.max_lead + 1
and (best == nil or left < best) then
best = left
end
break
end
end
end
end
if best == nil and track and track.normal_speed
and NPC.GetMoveSpeed(unit) > track.normal_speed * C.prediction.boost_ratio then
best = generic or C.prediction.boost_fallback
end
if track then
track.speed_scan_at = now
track.speed_left = best
end
return best
end
function A.predictionDistance(unit, time, speed)
local lead = math.min(time, C.prediction.max_lead)
local now = GameRules.GetGameTime()
local boost_left = A.speedModifierLeft(unit, now)
if boost_left == nil or boost_left >= lead then return speed * lead end
local track = S.enemyTrack[Entity.GetIndex(unit)]
local normal = track and track.normal_speed or NPC.GetBaseSpeed(unit)
normal = math.min(speed, math.max(0, normal))
return speed * boost_left + normal * (lead - boost_left)
end
function A.movementVector(unit)
local track = S.enemyTrack[Entity.GetIndex(unit)]
local vel = track and track.vel or Vector(0, 0, 0)
local speed = vel:Length2D()
local move_speed = NPC.GetMoveSpeed(unit)
local forward = Entity.GetRotation(unit):GetForward():Normalized()
local run_vel = forward * move_speed
if speed > move_speed then
vel = vel:Normalized() * move_speed
speed = move_speed
end
if NPC.IsRunning(unit) then
if speed > 80 then
local align = vel:Normalized():Dot2D(forward)
if align > 0.35 then
local blend = math.max(0, math.min(1, (align - 0.35) / 0.65))
local blended = vel * (0.45 + blend * 0.2) + run_vel * (0.55 - blend * 0.2)
return blended, math.min(blended:Length2D(), move_speed)
end
end
return run_vel, move_speed
end
if speed > 18 then return vel * 0.35, speed * 0.35 end
return Vector(0, 0, 0), 0
end
function A.predictRun(unit, time)
local pos = Entity.GetAbsOrigin(unit)
time = IT.moveTime(unit, time, GameRules.GetGameTime())
if time <= 0.02 then return pos end
local vel, speed = A.movementVector(unit)
if speed <= 10 then return pos end
return pos + vel:Normalized() * A.predictionDistance(unit, time, speed)
end
function A.order(hero, kind, point, target, ability, fast)
local player = Players.GetLocal()
if player == nil then return end
Player.PrepareUnitOrders(player, kind, target, point, ability, C.issuer, hero, false, true, false, fast, C.identifier)
end
function A.idle(hero, target, now)
local id = Entity.GetIndex(target)
if S.attacking == id and now - (S.attackAt or 0) < 1.0 then return end
A.order(hero, C.orderAttack, Entity.GetAbsOrigin(target), target, nil, true)
S.attacking = id
S.attackAt = now
end
function A.legendUi()
local sig = tostring(S.legend) .. tostring(S.lucky) .. tostring(S.w7Seen)
if sig == S.legendSig then return end
S.legendSig = sig
if UI.ram ~= nil then UI.ram:Visible(S.legend == true) end
if UI.w7 ~= nil then UI.w7:Visible(S.w7Seen == true or (not S.legend and not S.lucky)) end
end
function A.detectLegend(hero)
local ram = NPC.GetAbility(hero, C.ramName)
local has = ram ~= nil and Ability.GetLevel(ram) > 0
local lucky = NPC.GetAbility(hero, C.luckyName)
S.lucky = lucky ~= nil and not Ability.IsHidden(lucky)
if has ~= S.legend then
S.legend, S.legendShown = has, false
A.log("info", "pangolier legendary", { r7 = has })
end
A.legendUi()
if not S.legendShown and UI.legend ~= nil then
S.legendShown = true
pcall(UI.legend.ForceLocalization, UI.legend, localization.Get(S.legend and "menu.legend_yes" or "menu.legend_none"))
end
end
function A.impactPoint(hero, target, delay)
local origin = Entity.GetAbsOrigin(hero)
local point = Entity.GetAbsOrigin(target)
for _ = 1, C.iterations do
local travel = (point - origin):Length2D() / C.ramSpeed
point = A.predictRun(target, delay + travel)
end
return point
end
function A.steer(hero, point, now, force)
local origin = Entity.GetAbsOrigin(hero)
local dx, dy = point.x - origin.x, point.y - origin.y
local len = math.sqrt(dx * dx + dy * dy)
if len < 1 then return end
dx, dy = dx / len, dy / len
local last = S.steerDir
local changed = last == nil or (dx * last.x + dy * last.y) < math.cos(math.rad(C.steerAngle))
if not force and not changed and now < S.steerAt + C.steerHold then return end
if now < S.steerAt then return end
S.steerAt = now + C.steerGap
S.steerDir = { x = dx, y = dy }
A.order(hero, C.orderMove, Vector(origin.x + dx * C.bounceAhead, origin.y + dy * C.bounceAhead, origin.z), nil, nil, true)
end
function A.castQ(hero, target, now)
local q = NPC.GetAbility(hero, C.qName)
if q == nil or not UI.spells:Get("spell.q") or not A.ready(q, hero) then return false end
if IT.cycloneEarly(target, now, math.max(0, IT.castPoint(q)) + A.settle()) then return false end
local range = Ability.GetCastRange(q)
local origin = Entity.GetAbsOrigin(hero)
local point = A.predictRun(target, math.max(0, IT.castPoint(q)) + A.settle())
local dx, dy = point.x - origin.x, point.y - origin.y
local len = math.sqrt(dx * dx + dy * dy)
if len < 1 or len > range + C.qStrike * 0.5 then return false end
local ux, uy = dx / len, dy / len
local reach = math.min(len, range)
local start = Vector(origin.x + ux * reach, origin.y + uy * reach, origin.z)
local finish = Vector(start.x + ux * C.qStrike, start.y + uy * C.qStrike, start.z)
A.order(hero, C.orderVector, finish, nil, q, false)
A.order(hero, C.orderCastPosition, start, nil, q, false)
S.nextAt = now + math.max(0, IT.castPoint(q)) + A.settle()
S.attacking = nil
S.spellCast = true
A.log("info", "pangolier swashbuckle", { dist = math.floor(len), range = math.floor(range) })
return true
end
function A.castE(hero, target, now)
local e = NPC.GetAbility(hero, C.eName)
if e == nil or Ability.IsHidden(e) or not UI.spells:Get("spell.e") then return false end
local behavior = Ability.GetBehavior(e)
if A.has(behavior, C.bPassive) or not A.has(behavior, C.bUnit) or not A.ready(e, hero) then return false end
if IT.spellBlocked(target, now, C.eName) or IT.cycloneEarly(target, now, math.max(0, IT.castPoint(e)) + A.settle()) then return false end
local range = Ability.GetCastRange(e)
if range <= 0 then range = C.eRange end
if A.distance(hero, target) > range + NPC.GetHullRadius(target) then return false end
Ability.CastTarget(e, target, false, false, true, C.identifier)
S.nextAt = now + math.max(0, IT.castPoint(e)) + A.settle()
S.attacking = nil
S.spellCast = true
A.log("info", "pangolier lucky shot", { dist = math.floor(A.distance(hero, target)) })
return true
end
function A.castW(hero, target, now, rolling)
local w = NPC.GetAbility(hero, C.wName)
if w == nil or not UI.spells:Get("spell.w") or not A.ready(w, hero) then return false end
local ok, radius = pcall(Ability.GetLevelSpecialValueFor, w, "radius", -1)
if not ok or type(radius) ~= "number" or radius <= 0 then radius = C.wRadius end
local lead = rolling and 0.75 or 0.4
if IT.cycloneEarly(target, now, lead) then return false end
local point = A.predictRun(target, lead)
if (point - Entity.GetAbsOrigin(hero)):Length2D() > radius - C.wEdge then return false end
if A.has(Ability.GetBehavior(w), C.bPoint) then
Ability.CastPosition(w, point, false, false, true, C.identifier)
else
Ability.CastNoTarget(w, false, false, true, C.identifier)
end
S.nextAt = now + 0.15
S.attacking = nil
S.spellCast = true
A.log("info", "pangolier shield crash", { rolling = rolling })
return true
end
function A.wValue(w, key, fallback)
local ok, value = pcall(Ability.GetLevelSpecialValueFor, w, key, -1)
if ok and type(value) == "number" and value > 0 then return value end
return fallback
end
function A.chainW(hero, target, now)
if not UI.w7:Get() or not UI.spells:Get("spell.w") then return false end
local mod = NPC.GetModifier(hero, C.w7Mod)
if mod == nil then
S.w7Seen = false
return false
end
if not S.w7Seen then
S.w7Seen = true
A.legendUi()
A.log("info", "pangolier w7 chain started")
end
local w = NPC.GetAbility(hero, C.wName)
if w == nil or not A.ready(w, hero) then return false end
if IT.cycloneEarly(target, now, C.wJumpTime + A.settle(), Ability.GetName(w)) then return false end
local stacks = Modifier.GetStackCount(mod)
local final = stacks >= C.w7Max - 1
local reach = (final and A.wValue(w, "radius", C.wRadius) or C.w7Radius) - C.w7Edge
local jump = A.wValue(w, "jump_horizontal_distance", C.wJump)
local origin = Entity.GetAbsOrigin(hero)
local pred = A.predictRun(target, C.wJumpTime + A.settle() * 0.5)
local dx, dy = pred.x - origin.x, pred.y - origin.y
local len = math.sqrt(dx * dx + dy * dy)
local point = A.has(Ability.GetBehavior(w), C.bPoint)
local miss
if point then
miss = math.max(0, len - jump - A.wValue(w, "scepter_range", 300))
else
miss = (pred - Entity.GetForwardPosition(hero, jump)):Length2D()
end
if miss <= reach then
if point then
Ability.CastPosition(w, pred, false, false, true, C.identifier)
else
Ability.CastNoTarget(w, false, false, true, C.identifier)
end
S.nextAt = now + C.wJumpTime + 0.05
S.attacking = nil
S.spellCast = true
A.log("info", "pangolier w7 jump", { stacks = stacks, final = final, miss = math.floor(miss) })
return true
end
if len > jump + reach + C.w7Chase then return false end
A.orderMove(hero, pred, now)
S.attacking = nil
return true
end
function A.angleTo(hero, x, y)
local origin = Entity.GetAbsOrigin(hero)
local fp = Entity.GetForwardPosition(hero, 100)
local fx, fy = fp.x - origin.x, fp.y - origin.y
local fl, l = math.sqrt(fx * fx + fy * fy), math.sqrt(x * x + y * y)
if fl < 1 or l < 1 then return 0 end
return math.deg(math.acos(math.max(-1, math.min(1, (fx * x + fy * y) / (fl * l)))))
end
function A.bounce(hero, target, now)
if not UI.bounce:Get() or NPC.HasModifier(hero, C.dashMod) or NPC.HasModifier(hero, C.prepMod) then return false end
local origin = Entity.GetAbsOrigin(hero)
local line = S.bounceLine
if line ~= nil then
local reversed = A.angleTo(hero, line.ux, line.uy) > C.bounceDone
if reversed or now > line.untilAt then
S.bounceLine = nil
if reversed then A.log("info", "pangolier bounced", {}) end
return false
end
A.steer(hero, Vector(origin.x + line.ux * C.bounceAhead, origin.y + line.uy * C.bounceAhead, origin.z), now)
return true
end
local tp = A.predictRun(target, 0.5)
local ax, ay = origin.x - tp.x, origin.y - tp.y
local dT = math.sqrt(ax * ax + ay * ay)
if dT < 1 then return false end
local behind = A.angleTo(hero, -ax, -ay)
if behind < C.bounceAngle then return false end
local direct = behind / C.rollTurn + dT / C.rollSpeed
local tol = C.ramHit + NPC.GetHullRadius(target) - C.ramHitEdge
local spread = math.atan(tol / math.max(dT, tol))
local best = nil
for _, k in ipairs({ 0, 0.5, -0.5, 0.9, -0.9 }) do
local a = spread * k
local ux = (ax * math.cos(a) - ay * math.sin(a)) / dT
local uy = (ax * math.sin(a) + ay * math.cos(a)) / dT
local wall = A.wallOnLine(origin, ux, uy, C.bounceStep, C.bounceReach)
if wall ~= nil then
local t = A.angleTo(hero, ux, uy) / C.rollTurn + (2 * wall + dT) / C.rollSpeed + C.bounceRecover
if best == nil or t < best.t then best = { t = t, ux = ux, uy = uy, wall = wall } end
end
end
if best == nil or best.t >= direct then return false end
S.bounceLine = { ux = best.ux, uy = best.uy, untilAt = now + best.t + C.bounceSlack }
A.steer(hero, Vector(origin.x + best.ux * C.bounceAhead, origin.y + best.uy * C.bounceAhead, origin.z), now, true)
if S.bounceLogged ~= S.rollStarted then
S.bounceLogged = S.rollStarted
A.log("info", "pangolier wall bounce", { wall = best.wall, time = math.floor(best.t * 10) / 10, direct = math.floor(direct * 10) / 10 })
end
return true
end
function A.wallOnLine(origin, ux, uy, from, to)
for d = from, to, C.bounceStep do
local ok, free = pcall(GridNav.IsTraversable, Vector(origin.x + ux * d, origin.y + uy * d, origin.z))
if ok and free == false then return d end
end
return nil
end
function A.ramAim(hero, target, delay)
return A.impactPoint(hero, target, delay)
end
function A.qBehind(hero, target, now)
local q = NPC.GetAbility(hero, C.qName)
if q == nil or not UI.spells:Get("spell.q") or not A.ready(q, hero) then return false end
local range = Ability.GetCastRange(q)
local origin = Entity.GetAbsOrigin(hero)
local tp = Entity.GetAbsOrigin(target)
local pred = A.predictRun(target, math.max(0, IT.castPoint(q)) + A.settle() + (tp - origin):Length2D() / C.qDashSpeed)
local dx, dy = pred.x - origin.x, pred.y - origin.y
local len = math.sqrt(dx * dx + dy * dy)
if len < 1 then return false end
local ux, uy = dx / len, dy / len
local start = Vector(pred.x + ux * C.behind, pred.y + uy * C.behind, origin.z)
local jump = len + C.behind
if jump > range then return false end
local finish = Vector(start.x - ux * C.qStrike, start.y - uy * C.qStrike, start.z)
A.order(hero, C.orderVector, finish, nil, q, false)
A.order(hero, C.orderCastPosition, start, nil, q, false)
S.nextAt = now + math.max(0, IT.castPoint(q)) + jump / C.qDashSpeed + C.qSettle
S.attacking = nil
S.spellCast = true
A.log("info", "pangolier q behind", { dist = math.floor(len), jump = math.floor(jump) })
return true
end
function A.wBehind(hero, target, now)
local w = NPC.GetAbility(hero, C.wName)
if w == nil or not UI.spells:Get("spell.w") or not A.ready(w, hero) then return false end
local origin = Entity.GetAbsOrigin(hero)
local pred = A.predictRun(target, C.wJumpTime + A.settle())
local dx, dy = pred.x - origin.x, pred.y - origin.y
local len = math.sqrt(dx * dx + dy * dy)
if len < 1 then return false end
if A.has(Ability.GetBehavior(w), C.bPoint) then
local range = math.max(Ability.GetCastRange(w), C.wJump)
if len + C.behind > range then return false end
Ability.CastPosition(w, Vector(pred.x + dx / len * C.behind, pred.y + dy / len * C.behind, origin.z), false, false, true, C.identifier)
else
if len > C.wJump - C.behind * 0.5 or A.angleTo(hero, dx, dy) > C.rFacing then return false end
Ability.CastNoTarget(w, false, false, true, C.identifier)
end
S.nextAt = now + C.wJumpTime + 0.05
S.attacking = nil
S.spellCast = true
A.log("info", "pangolier w behind", { dist = math.floor(len) })
return true
end
function A.tryR(hero, target, r, now)
local origin = Entity.GetAbsOrigin(hero)
local lead = math.max(0, IT.castPoint(r)) + A.settle()
local pred = A.predictRun(target, lead)
local dx, dy = pred.x - origin.x, pred.y - origin.y
local dist = math.sqrt(dx * dx + dy * dy)
local reach = C.ramHit + NPC.GetHullRadius(hero) + NPC.GetHullRadius(target) + C.rollSpeed * C.rStartWindow
local q = NPC.GetAbility(hero, C.qName)
local w = NPC.GetAbility(hero, C.wName)
local moveReady = (q ~= nil and UI.spells:Get("spell.q") and A.ready(q, hero)) or (w ~= nil and UI.spells:Get("spell.w") and A.ready(w, hero))
local facing = dist < 1 or A.angleTo(hero, dx, dy) <= C.rFacing
if dist <= reach or (not moveReady and dist <= C.rCatch) then
if not facing then
A.orderMove(hero, pred, now)
return true
end
Ability.CastNoTarget(r, false, false, true, C.identifier)
S.nextAt = now + math.max(0, IT.castPoint(r)) + 0.1
S.attacking = nil
S.spellCast = true
A.log("info", "pangolier roll", { dist = math.floor(dist), reach = math.floor(reach) })
return true
end
if A.castW(hero, target, now, false) then return true end
if A.qBehind(hero, target, now) then return true end
if A.wBehind(hero, target, now) then return true end
A.orderMove(hero, pred, now)
return true
end
function A.roll(hero, target, now)
local ram = NPC.GetAbility(hero, C.ramName)
if NPC.HasModifier(hero, C.prepMod) then
local mod = NPC.GetModifier(hero, C.prepMod)
local left = mod ~= nil and math.max(0, Modifier.GetDieTime(mod) - now) or C.ramPrep
A.steer(hero, A.ramAim(hero, target, left + A.settle() * 0.5), now, true)
return
end
if NPC.HasModifier(hero, C.dashMod) then
A.steer(hero, A.impactPoint(hero, target, 0), now)
return
end
if not S.ramLogged then
S.ramLogged = true
A.log("info", "pangolier ram state", {
legend = S.legend, found = ram ~= nil,
level = ram ~= nil and Ability.GetLevel(ram) or nil, hidden = ram ~= nil and Ability.IsHidden(ram) or nil,
activated = ram ~= nil and Ability.IsActivated(ram) or nil, cd = ram ~= nil and Ability.GetCooldown(ram) or nil,
ready = ram ~= nil and A.ready(ram, hero) or nil,
})
end
if A.bounce(hero, target, now) then return end
if S.legend and UI.ram:Get() and S.rams < C.ramMax and ram ~= nil and not Ability.IsHidden(ram)
and Ability.IsActivated(ram) and A.ready(ram, hero) and now >= S.nextAt then
local point = A.ramAim(hero, target, C.ramPrep + A.settle() * 0.5)
local reach = math.min(C.ramSpeed * C.ramDash - UI.ramMargin:Get(), C.ramFireMax)
local dist = (point - Entity.GetAbsOrigin(hero)):Length2D()
if dist <= reach then
Ability.CastNoTarget(ram, false, false, true, C.identifier)
S.rams = S.rams + 1
S.nextAt = now + 0.1
S.steerAt = 0
A.steer(hero, point, now, true)
A.log("info", "pangolier ram", { n = S.rams, dist = math.floor(dist), reach = math.floor(reach) })
return
end
end
if now >= S.nextAt then
if A.castW(hero, target, now, true) then return end
if IT.breakLinken(hero, target, now) then return end
do local mw = IT.meteorCast(hero, target, now, C.identifier) if mw ~= nil then S.nextAt = now + mw return end end
if A.useItems(hero, target, nil, now) then return end
end
A.steer(hero, A.predictRun(target, A.distance(hero, target) / C.rollSpeed), now)
end
function A.holdLeft(target, now)
local held = false
for _, state in ipairs(C.holdStates) do
if NPC.HasState(target, state) then held = true end
end
local left = 0
for _, mod in ipairs(NPC.GetModifiers(target) or {}) do
local name = Modifier.GetName(mod)
for _, word in ipairs(C.holdWords) do
if name:find(word, 1, true) ~= nil then
local rest = Modifier.GetDieTime(mod) - now
if rest > left then left = rest end
held = true
end
end
end
if not held then return 0 end
return left
end
function A.meteorPoint(target, item, now)
local delay, radius = C.meteorDelay, C.meteorRadius
if C.special ~= nil then
local ok, value = pcall(C.special, item, "max_duration", -1)
if ok and type(value) == "number" and value > 0 then delay = value end
ok, value = pcall(C.special, item, "impact_radius", -1)
if ok and type(value) == "number" and value > 0 then radius = value end
end
delay = IT.itemFall(item, delay)
local reach = radius - NPC.GetHullRadius(target) - C.meteorMargin
local fall = delay + math.max(0, IT.castPoint(item)) + A.settle() * 0.5
local free = math.max(0, fall - A.holdLeft(target, now))
if NPC.GetMoveSpeed(target) * free <= reach then return Entity.GetAbsOrigin(target) end
return nil
end
function A.itemBase(name)
return (name:gsub("^item_", ""):gsub("_custom$", ""))
end
function A.itemLabel(name)
return (A.itemBase(name):gsub("_", " "))
end
function A.itemIcon(name)
local base = A.itemBase(name)
return "panorama/images/items/" .. (ICON_FIX[base] or base) .. "_png.vtex_c"
end
function A.itemSkipped(name)
for _, fragment in ipairs(ITEM_SKIP) do
if name:find(fragment, 1, true) ~= nil then return true end
end
return false
end
function A.has(value, bit)
return type(value) == "number" and bit > 0 and math.floor(value / bit) % 2 >= 1
end
function A.itemKind(item)
local behavior = Ability.GetBehavior(item)
if A.has(behavior, C.bPassive) or A.has(behavior, C.bHidden) or A.has(behavior, C.bToggle) then return nil end
if A.has(behavior, C.bUnit) then
local team = Ability.GetTargetTeam(item)
if A.has(team, C.targetEnemy) then return "enemy" end
if A.has(team, C.targetFriendly) then return "self" end
return nil
end
if A.has(behavior, C.bPoint) then return "point" end
if A.has(behavior, C.bNo) then return "no" end
return nil
end
function A.scanItems(hero)
local labels, ids, signature = {}, {}, ""
for _, slot in ipairs(C.itemSlots) do
local item = NPC.GetItemByIndex(hero, slot)
if item ~= nil then
local name = Ability.GetName(item)
local label = A.itemLabel(name)
if not A.itemSkipped(name) and A.itemKind(item) ~= nil and ids[label] == nil then
labels[#labels + 1] = label
ids[label] = name
signature = signature .. label .. "=" .. name .. ","
end
end
end
return labels, ids, signature
end
function A.refreshItems(hero)
IT.tick()
local labels, ids, signature = A.scanItems(hero)
if signature == S.itemSig then return end
local rank, old, enabled = {}, {}, {}
for i, id in ipairs(UI.items:List()) do
rank[id] = i
old[id] = true
end
for _, id in ipairs(UI.items:ListEnabled()) do enabled[id] = true end
table.sort(labels, function(a, b) return (rank[a] or 1000) < (rank[b] or 1000) end)
local rows, selected = {}, {}
for i, label in ipairs(labels) do
local on = not old[label] or enabled[label] == true
rows[i] = { label, A.itemIcon(ids[label]), on }
if on then selected[#selected + 1] = label end
end
UI.items:Update(rows, true, true)
UI.items:Set(selected)
S.itemSig = signature
S.itemIds = ids
IT.sync(hero, labels, ids, A.itemIcon)
A.log("info", "pangolier items refreshed", { items = labels, enabled = selected })
end
function A.findItem(hero, label, name)
for _, slot in ipairs(C.itemSlots) do
local item = NPC.GetItemByIndex(hero, slot)
if item ~= nil and Ability.GetName(item) == name then return item end
end
for _, slot in ipairs(C.itemSlots) do
local item = NPC.GetItemByIndex(hero, slot)
if item ~= nil and A.itemLabel(Ability.GetName(item)) == label then return item end
end
return nil
end
function A.isJump(name)
return name:find("blink", 1, true) ~= nil or name:find("fallen_sky", 1, true) ~= nil
end
function A.itemReady(item, hero)
return item ~= nil and Ability.GetLevel(item) > 0 and Ability.IsCastable(item, NPC.GetMana(hero))
end
function A.clampPoint(hero, point, range)
if range <= 0 then return point end
local origin = Entity.GetAbsOrigin(hero)
local dx, dy = point.x - origin.x, point.y - origin.y
local length = math.sqrt(dx * dx + dy * dy)
local cap = math.max(0, range - 25)
if length <= cap or length <= 0 then return point end
local scale = cap / length
return Vector(origin.x + dx * scale, origin.y + dy * scale, point.z)
end
function A.comboReach(hero, ability)
local reach = 0
if ability ~= nil then reach = Ability.GetCastRange(ability) end
for _, label in ipairs(UI.items:ListEnabled()) do
local name = S.itemIds[label]
local item = name ~= nil and not A.isJump(name) and A.findItem(hero, label, name) or nil
if item ~= nil and A.itemReady(item, hero) then
local kind = A.itemKind(item)
if kind == "enemy" or kind == "point" then reach = math.max(reach, Ability.GetCastRange(item) + 75) end
end
end
return reach
end
function A.blinkPoint(hero, target)
local origin = Entity.GetAbsOrigin(hero)
local pos = Entity.GetAbsOrigin(target)
local dx, dy = pos.x - origin.x, pos.y - origin.y
local len = math.max(1, math.sqrt(dx * dx + dy * dy))
local range = NPC.GetAttackRange(hero) + NPC.GetAttackRangeBonus(hero)
local keep = range > 300 and math.max(C.blinkKeep, range - 100) or C.blinkKeep
return Vector(pos.x - dx / len * keep, pos.y - dy / len * keep, pos.z)
end
function A.orderMove(hero, point, now)
if now < S.moveAt then return end
A.order(hero, C.orderMove, point, nil, nil, false)
S.moveAt = now + C.moveGap
end
function A.isMeteor(name)
for _, fragment in ipairs(C.meteorItems) do
if name:find(fragment, 1, true) ~= nil then return true end
end
return false
end
function A.isShiva(name)
return name:find("shivas_guard", 1, true) ~= nil or name:find("gold_shiva", 1, true) ~= nil
end
function A.isHex(name)
return name:find("sheepstick", 1, true) ~= nil or name:find("hex", 1, true) ~= nil
end
function A.shivaHasTarget(hero, item)
local radius = C.shivaRadius
if C.special ~= nil then
local ok, value = pcall(C.special, item, "blast_radius", -1)
if ok and type(value) == "number" and value > 0 then radius = value end
end
for _, enemy in ipairs(Heroes.GetAll()) do
if A.valid(enemy) and not Entity.IsSameTeam(hero, enemy) and not NPC.IsIllusion(enemy)
and A.distance(hero, enemy) <= radius then
return true
end
end
return false
end
function A.useItems(hero, target, ability, now)
if now >= S.cycleAt then
S.done = {}
S.cycleAt = now + C.cycleGap
end
local distance = A.distance(hero, target)
for _, label in ipairs(UI.items:ListEnabled()) do
local name = S.itemIds[label]
if name ~= nil and not S.done[name] then
local item = A.findItem(hero, label, name)
if item == nil then
S.done[name] = true
elseif not IT.allow(hero, target, name, label) then
elseif A.itemReady(item, hero) then
local kind = A.itemKind(item)
local range = Ability.GetCastRange(item)
local jump = A.isJump(name)
if kind == nil then
S.done[name] = true
elseif jump and distance <= A.comboReach(hero, ability) then
elseif not S.spellCast and name:find("ethereal", 1, true) ~= nil then
elseif A.isShiva(name) and not A.shivaHasTarget(hero, item) then
elseif A.isMeteor(name) and A.meteorPoint(target, item, now) == nil then
elseif (kind == "enemy" or kind == "point") and not jump and range > 0 and distance > range + 75 then
A.orderMove(hero, IT.stopPoint(hero, target, range), now)
return true
else
if kind == "enemy" then
Ability.CastTarget(item, target, false, false, true, C.identifier)
elseif kind == "self" then
Ability.CastTarget(item, hero, false, false, true, C.identifier)
elseif kind == "point" and jump then
Ability.CastPosition(item, A.clampPoint(hero, A.blinkPoint(hero, target), range), false, false, true, C.identifier)
elseif kind == "point" then
Ability.CastPosition(item, A.clampPoint(hero, Entity.GetAbsOrigin(target), range), false, false, true, C.identifier)
else
Ability.CastNoTarget(item, false, false, true, C.identifier)
end
S.done[name] = true
local delay = math.max(0.08, math.max(0, IT.castPoint(item)) + 0.06)
if kind == "enemy" and A.isHex(name) then delay = math.max(delay, C.hexWait) end
S.nextAt = now + delay
S.attacking = nil
IT.chainMark(hero, target, name)
A.log("info", "pangolier combo item", { item = name, kind = kind })
return true
end
end
end
end
return false
end
function A.update()
local hero = Heroes.GetLocal()
if not A.valid(hero) or Entity.GetUnitName(hero) ~= C.hero then
if S.phase ~= "idle" then A.reset("no pangolier") end
return
end
local clock = GameRules.GetGameTime()
A.detectLegend(hero)
if clock >= S.itemAt and S.itemError == nil then
S.itemAt = clock + C.itemGap
local ok, err = pcall(A.refreshItems, hero)
if not ok then
S.itemError = tostring(err)
A.log("error", "pangolier items refresh failed", { error = S.itemError })
end
end
if not UI.enabled:Get() or not UI.key:IsDown() then
if S.phase ~= "idle" then A.reset("key released") end
return
end
if C.inputCaptured ~= nil and C.inputCaptured() then return end
if not A.orderSafe() then return end
if IT.heroDisabled(hero) then return end
local now = GameRules.GetGameTime()
if S.phase == "idle" then
S.target = A.pickTarget(hero)
if S.target == nil then return end
S.phase = "running"
S.startedAt = now
A.log("info", "pangolier combo started", { target = Entity.GetUnitName(S.target) })
end
local target = S.target
if IT.fogHold(target, now) then
if A.orderMove ~= nil then A.orderMove(hero, Entity.GetAbsOrigin(target), now) end
return
end
if not A.valid(target) or Entity.IsSameTeam(hero, target) or A.distance(hero, target) > UI.range:Get() + 1000 then
A.reset("target lost")
return
end
if now - S.startedAt > C.maxRun then
A.reset("timeout")
return
end
A.updateRunTrack(target, now)
local r = NPC.GetAbility(hero, C.rName)
local rolling = NPC.HasModifier(hero, C.rollMod)
if rolling then
if not S.rollSeen then S.rollSeen, S.rams, S.ramLogged, S.rollStarted, S.spellCast, S.bounceLine, S.steerDir = true, 0, false, now, true, nil, nil end
A.roll(hero, target, now)
return
end
S.rollSeen = false
if r ~= nil and Ability.IsInAbilityPhase(r) then return end
local q = NPC.GetAbility(hero, C.qName)
if q ~= nil and Ability.IsInAbilityPhase(q) then return end
if NPC.HasModifier(hero, C.qDash) then return end
if now < S.nextAt or NPC.HasModifier(hero, "modifier_item_meteor_hammer_custom_cast") then return end
if IT.breakLinken(hero, target, now) then return end
do local mw = IT.meteorCast(hero, target, now, C.identifier) if mw ~= nil then S.nextAt = now + mw return end end
if A.chainW(hero, target, now) then return end
if A.useItems(hero, target, r, now) then return end
for _, id in ipairs(IT.spellOrder(UI.spells)) do
if id == "spell.r" and r ~= nil and A.ready(r, hero) and A.tryR(hero, target, r, now) then return end
if id == "spell.q" and A.castQ(hero, target, now) then return end
if id == "spell.w" and A.castW(hero, target, now, false) then return end
if id == "spell.e" and A.castE(hero, target, now) then return end
end
A.idle(hero, target, now)
end
function A.drawError()
local title = S.menuError and localization.Get("panel.menu_failed") or localization.Get("panel.error")
local message = S.menuError or S.error or S.itemError or "unknown"
Render.FilledRect(Vec2(20, 370), Vec2(780, 418), Color(20, 20, 24, 235), 4)
Render.Text(S.font, 14, title, Vec2(30, 377), Color(224, 50, 45, 245))
Render.Text(S.font, 12, message:sub(1, 160), Vec2(30, 397), Color(220, 220, 225, 240))
end
function script.OnScriptsLoaded()
local ok, result = pcall(A.initMenu)
