end)
if ok and type(result) == "table" then
modules[#modules + 1] = { name = "pangolier_1x6_combo", script = result, loadMs = pack_clock and (pack_clock() - started) * 1000 or 0 }
else
failed_load["pangolier_1x6_combo"] = tostring(result)
end
end
