function A.reset(reason)
if S.phase ~= "idle" then A.log("info", "jakiro combo stopped", { reason = reason }) end
S.phase = "idle"
S.target = nil
S.startedAt = 0
S.nextAt = 0
S.moveAt = 0
S.attacking = nil
S.done = {}
S.cycleAt = 0
S.mode, S.stepSpell, S.seqDone = "main", nil, nil
S.opened = false
S.areas, S.areaAt, S.areaUsed = {}, 0, false
end
function A.pickTarget(hero)
local target = nil
if C.cursorHero then
local ok, value = pcall(C.cursorHero, Entity.GetTeamNum(hero), C.teamEnemy)
if ok then target = value end
end
if target and A.valid(target) and not Entity.IsSameTeam(hero, target) and not NPC.IsIllusion(target)
and A.distance(hero, target) <= UI.range:Get() then
return target
end
local cursor = C.cursorPos and C.cursorPos() or Entity.GetAbsOrigin(hero)
local best, bestDistance = nil, math.huge
for _, enemy in ipairs(Heroes.GetAll()) do
if enemy ~= hero and A.valid(enemy) and not Entity.IsSameTeam(hero, enemy) and not NPC.IsIllusion(enemy)
and A.distance(hero, enemy) <= UI.range:Get() then
local distance = (Entity.GetAbsOrigin(enemy) - cursor):Length2D()
if distance < bestDistance then
best, bestDistance = enemy, distance
end
end
end
return best
end
function A.updateRunTrack(unit, now)
local id = Entity.GetIndex(unit)
local pos = Entity.GetAbsOrigin(unit)
local track = S.enemyTrack[id]
if track ~= nil and now - track.last_time > C.trackReset then track = nil end
track = track or {
last_pos = pos,
last_time = now,
vel = Vector(0, 0, 0),
normal_speed = NPC.GetMoveSpeed(unit),
}
local dt = math.max(0.016, now - track.last_time)
local raw = (pos - track.last_pos) / dt
track.vel = raw * 0.58 + track.vel * 0.42
track.last_pos = pos
track.last_time = now
S.enemyTrack[id] = track
if not NPC.HasState(unit, C.stunned) and A.speedModifierLeft(unit, now) == nil then
track.normal_speed = NPC.GetMoveSpeed(unit)
end
end
function A.speedModifierLeft(unit, now)
local track = S.enemyTrack[Entity.GetIndex(unit)]
if track and track.speed_scan_at and now - track.speed_scan_at < 0.04 then return track.speed_left end
local best, generic = nil, nil
for _, modifier in ipairs(NPC.GetModifiers(unit) or {}) do
if not Modifier.IsDebuff(modifier) then
local name = Modifier.GetName(modifier):lower()
local left = Modifier.GetDieTime(modifier) - now
if left > 0.02 and left <= C.prediction.max_lead + 1
and (generic == nil or left < generic) then
generic = left
end
for _, word in ipairs(SPEED_WORDS) do
if name:find(word, 1, true) ~= nil then
if left > 0.02 and left <= C.prediction.max_lead + 1
and (best == nil or left < best) then
best = left
end
break
end
end
end
end
if best == nil and track and track.normal_speed
and NPC.GetMoveSpeed(unit) > track.normal_speed * C.prediction.boost_ratio then
best = generic or C.prediction.boost_fallback
end
if track then
track.speed_scan_at = now
track.speed_left = best
end
return best
end
function A.predictionDistance(unit, time, speed)
local lead = math.min(time, C.prediction.max_lead)
local now = GameRules.GetGameTime()
local boost_left = A.speedModifierLeft(unit, now)
if boost_left == nil or boost_left >= lead then return speed * lead end
local track = S.enemyTrack[Entity.GetIndex(unit)]
local normal = track and track.normal_speed or NPC.GetBaseSpeed(unit)
normal = math.min(speed, math.max(0, normal))
return speed * boost_left + normal * (lead - boost_left)
end
function A.movementVector(unit)
local track = S.enemyTrack[Entity.GetIndex(unit)]
local vel = track and track.vel or Vector(0, 0, 0)
local speed = vel:Length2D()
local move_speed = NPC.GetMoveSpeed(unit)
local forward = Entity.GetRotation(unit):GetForward():Normalized()
local run_vel = forward * move_speed
if speed > move_speed then
vel = vel:Normalized() * move_speed
speed = move_speed
end
if NPC.IsRunning(unit) then
if speed > 80 then
local align = vel:Normalized():Dot2D(forward)
if align > 0.35 then
local blend = math.max(0, math.min(1, (align - 0.35) / 0.65))
local blended = vel * (0.45 + blend * 0.2) + run_vel * (0.55 - blend * 0.2)
return blended, math.min(blended:Length2D(), move_speed)
end
end
return run_vel, move_speed
end
if speed > 18 then return vel * 0.35, speed * 0.35 end
return Vector(0, 0, 0), 0
end
function A.predictRun(unit, time)
local pos = Entity.GetAbsOrigin(unit)
time = IT.moveTime(unit, time, GameRules.GetGameTime())
if time <= 0.02 then return pos end
local vel, speed = A.movementVector(unit)
if speed <= 10 then return pos end
return pos + vel:Normalized() * A.predictionDistance(unit, time, speed)
end
function A.order(hero, kind, point, target, ability, fast)
local player = Players.GetLocal()
if player == nil then return end
Player.PrepareUnitOrders(player, kind, target, point, ability, C.issuer, hero, false, true, false, fast, C.identifier)
end
function A.attackBlocked(target, now)
return NPC.HasModifier(target, C.ghostMod) or A.cycloneLand(target, now) ~= nil
end
function A.idle(hero, target, now)
local id = Entity.GetIndex(target)
if A.attackBlocked(target, now) then
if S.attacking ~= nil then
A.order(hero, C.orderMove, Entity.GetAbsOrigin(hero), nil, nil, true)
S.attacking = nil
end
return
end
if S.attacking == id and now - (S.attackAt or 0) < 1.0 then return end
A.order(hero, C.orderAttack, Entity.GetAbsOrigin(target), target, nil, true)
S.attacking = id
S.attackAt = now
end
function A.detectLegend(hero)
if hero == nil then return end
local q = NPC.GetAbility(hero, C.qName)
local r = NPC.GetAbility(hero, C.rName)
local qLegend = NPC.HasModifier(hero, C.lastSpellMod) or NPC.HasModifier(hero, C.stackMod)
or (q ~= nil and Ability.GetLevel(q) > 0 and Ability.GetManaCost(q) <= C.qBaseMana * C.legendMana)
local rLegend = false
if r ~= nil and Ability.GetLevel(r) > 0 then
local base = C.rBaseMana[math.min(Ability.GetLevel(r), #C.rBaseMana)]
rLegend = A.has(Ability.GetBehavior(r), C.bAoe) or Ability.GetManaCost(r) <= base * C.legendMana
or Ability.GetCurrentCharges(r) > 1
end
if qLegend ~= S.legend or rLegend ~= S.legendR then
S.legend, S.legendR, S.legendShown = qLegend, rLegend, false
A.log("info", "jakiro legendaries", { q = qLegend, r = rLegend,
q_mana = q ~= nil and Ability.GetManaCost(q) or -1, r_mana = r ~= nil and Ability.GetManaCost(r) or -1 })
end
if not S.legendShown and UI.legend ~= nil then
S.legendShown = true
local key = qLegend and (rLegend and "menu.legend_yes" or "menu.legend_q") or (rLegend and "menu.legend_r" or "menu.legend_none")
pcall(UI.legend.ForceLocalization, UI.legend, localization.Get(key))
end
end
function A.value(ability, key, fallback)
if C.special ~= nil then
local ok, value = pcall(C.special, ability, key, -1)
if ok and type(value) == "number" and value > 0 then return value end
end
return fallback
end
function A.element(hero)
return NPC.HasModifier(hero, C.frostMod) and "ice" or "fire"
end
function A.spellReady(ability, hero)
if ability == nil or Ability.GetLevel(ability) <= 0 or Ability.IsHidden(ability) then return false end
if Ability.GetCurrentCharges(ability) > 0 then return Ability.IsCastable(ability, NPC.GetMana(hero)) end
return A.ready(ability, hero)
end
function A.wFollow(hero, mana)
local w = NPC.GetAbility(hero, C.wName)
return w ~= nil and UI.spells:Get("spell.w") and A.spellReady(w, hero) and mana >= Ability.GetManaCost(w)
end
IT.eulExtra = function(hero, mana) return A.wFollow(hero, mana) end
function A.markCast(ability, hero, now, orb)
S.opened = true
S.pending = {
h = ability, elem = A.element(hero), at = now, orb = orb,
charges = Ability.GetCurrentCharges(ability), name = Ability.GetName(ability),
}
end
function A.confirm(now)
local p = S.pending
if p == nil then return end
local fired = Ability.GetCooldown(p.h) > 0 or Ability.GetCurrentCharges(p.h) < p.charges
if fired then
S.lastElem, S.pending, S.lastSpell = p.elem, nil, p.name
if p.area ~= nil then
S.areas[#S.areas + 1] = { pos = p.area, expires = now + C.areaDuration }
S.areaUsed = true
end
A.log("info", "jakiro cast confirmed", { spell = p.name, element = p.elem })
elseif now - p.at > (p.orb and C.orbTimeout or C.confirmTimeout) then
S.pending = nil
A.log("info", "jakiro cast not confirmed", { spell = p.name })
end
end
function A.flipElement()
return S.lastElem == "ice" and "fire" or "ice"
end
function A.needSwitch(hero, now, want)
local element = A.element(hero)
if S.switchFrom ~= nil then
if element ~= S.switchFrom or now >= S.switchUntil then
S.switchFrom = nil
else
return true
end
end
if not UI.switch:Get() or want == nil or element == want then return false end
local innate = NPC.GetAbility(hero, C.innateName)
if innate == nil or Ability.GetLevel(innate) <= 0 or not Ability.IsReady(innate) then return false end
Ability.CastNoTarget(innate, false, false, true, C.identifier)
S.switchFrom, S.switchUntil, S.want = element, now + C.switchTimeout, want
S.nextAt = now + C.switchWait
A.log("info", "jakiro element switch", { from = element })
return true
end
function A.aim(hero, target, lead, speed)
local origin = Entity.GetAbsOrigin(hero)
local point = Entity.GetAbsOrigin(target)
for _ = 1, C.iterations do
local flight = speed ~= nil and (point - origin):Length2D() / speed or 0
point = A.predictRun(target, lead + flight)
end
return point, (point - origin):Length2D()
end
function A.early(target, now, impact, slack)
local land = A.cycloneLand(target, now)
return land ~= nil and impact < land - (slack or 0)
end
function A.castQ(hero, target, q, now)
local speed = A.value(q, "speed", C.qSpeed) * (S.legend and C.qLegendSpeed or 1)
local range = Ability.GetCastRange(q)
local lead = math.max(0, IT.castPoint(q)) + A.settle() * 0.5
local point, dist = A.aim(hero, target, lead, speed)
if dist > range + C.qEndRadius * 0.5 + NPC.GetHullRadius(target) then return nil end
if A.needSwitch(hero, now, "fire") then return true end
if A.early(target, now, now + lead + dist / speed, 0) then return false end
local origin = Entity.GetAbsOrigin(hero)
local len = math.max(1, dist)
local reach = math.max(C.minAim, math.min(dist, range))
local cast = Vector(origin.x + (point.x - origin.x) / len * reach, origin.y + (point.y - origin.y) / len * reach, point.z)
Ability.CastPosition(q, cast, false, false, true, C.identifier)
A.markCast(q, hero, now, false)
S.attacking = nil
S.nextAt = now + math.max(0, IT.castPoint(q)) + A.settle()
A.log("info", "jakiro dual breath", { distance = math.floor(dist), element = A.element(hero), legend = S.legend, mark = NPC.HasModifier(target, C.markMod) })
return true
end
function A.castW(hero, target, w, now)
local range = Ability.GetCastRange(w)
if range <= 0 then range = 1100 end
local lead = math.max(0, IT.castPoint(w)) + C.wDelay + A.settle() * 0.5
local point, dist = A.aim(hero, target, lead, nil)
if dist > range + C.wWidth * 0.5 + NPC.GetHullRadius(target) then return nil end
if A.needSwitch(hero, now, A.flipElement()) then return true end
if A.early(target, now, now + lead, 0) then return false end
local origin = Entity.GetAbsOrigin(hero)
local len = math.max(1, dist)
local reach = math.max(C.minAim, math.min(dist, range))
local cast = Vector(origin.x + (point.x - origin.x) / len * reach, origin.y + (point.y - origin.y) / len * reach, point.z)
Ability.CastPosition(w, cast, false, false, true, C.identifier)
A.markCast(w, hero, now, false)
S.attacking = nil
S.nextAt = now + math.max(0, IT.castPoint(w)) + A.settle()
A.log("info", "jakiro ice path", { distance = math.floor(dist), element = A.element(hero) })
return true
end
function A.detectLegendE(hero)
local ability = NPC.GetAbility(hero, C.eLegend)
local has = ability ~= nil and Ability.GetLevel(ability) > 0 and not Ability.IsHidden(ability)
if has == S.legendE then return end
S.legendE = has
if UI.legendE ~= nil then UI.legendE:Visible(has) end
A.log("info", "jakiro e legendary", { e = has })
end
function A.castELegend(hero, target, now)
if not S.legendE or not UI.legendE:Get() or not UI.spells:Get("spell.e") or now < S.eAt then return false end
local ability = NPC.GetAbility(hero, C.eLegend)
if ability == nil or Ability.GetLevel(ability) <= 0 or Ability.IsHidden(ability) or not A.ready(ability, hero) then return false end
if NPC.HasModifier(hero, C.eActiveMod) then return false end
local stacks = NPC.GetModifier(hero, C.eStackMod)
if stacks == nil or Modifier.GetStackCount(stacks) < C.eStackNeed then return false end
if A.distance(hero, target) > C.eReach then return false end
Ability.CastNoTarget(ability, false, false, true, C.identifier)
S.eAt = now + C.eHold
S.nextAt = now + A.settle()
A.log("info", "jakiro liquid fire burst")
return true
end
function A.castE(hero, target, e, now)
local reach = NPC.GetAttackRange(hero) + NPC.GetHullRadius(hero) + NPC.GetHullRadius(target) + C.eReach
if A.distance(hero, target) > reach or A.attackBlocked(target, now) then return nil end
if A.needSwitch(hero, now, A.flipElement()) then return true end
if A.early(target, now, now + A.settle() * 0.5 + 0.1, 0) then return false end
Ability.CastTarget(e, target, false, false, true, C.identifier)
A.markCast(e, hero, now, true)
S.attacking = Entity.GetIndex(target)
S.nextAt = now + A.settle()
A.log("info", "jakiro liquid fire", { element = A.element(hero) })
return true
end
function A.rElement(target, now)
if not S.legendR then return "ice" end
local held = A.holdLeft(target, now) > 0.6 or NPC.GetMoveSpeed(target) < C.slowSpeed
local mod = NPC.GetModifier(target, C.r7StackMod)
local stacks = mod ~= nil and Modifier.GetStackCount(mod) or 0
if held or stacks >= C.stackCharge then return "fire" end
return "ice"
end
function A.castR(hero, target, r, now)
if S.lastSpell == C.rName then return nil end
local area = S.legendR or A.has(Ability.GetBehavior(r), C.bAoe)
local range = Ability.GetCastRange(r)
if range <= 0 then range = area and 800 or C.rLineRange end
local lead = math.max(0, IT.castPoint(r)) + A.settle() * 0.5
local point, dist = A.aim(hero, target, lead, nil)
local reachPad = area and C.rRadius * 0.6 or 0
if dist > range + reachPad then return nil end
local want = A.rElement(target, now)
if A.needSwitch(hero, now, want) then return true end
if A.early(target, now, now + lead, 0.3) then return false end
local cast = point
if area and dist > range then
local origin = Entity.GetAbsOrigin(hero)
cast = Vector(origin.x + (point.x - origin.x) / dist * range, origin.y + (point.y - origin.y) / dist * range, point.z)
elseif not area and dist < C.minAim then
local origin = Entity.GetAbsOrigin(hero)
local len = math.max(1, dist)
cast = Vector(origin.x + (point.x - origin.x) / len * C.minAim, origin.y + (point.y - origin.y) / len * C.minAim, point.z)
end
Ability.CastPosition(r, cast, false, false, true, C.identifier)
A.markCast(r, hero, now, false)
if area then S.pending.area = cast end
S.attacking = nil
S.nextAt = now + math.max(0, IT.castPoint(r)) + A.settle()
A.log("info", "jakiro macropyre", { distance = math.floor(dist), element = A.element(hero), area = area, charges = Ability.GetCurrentCharges(r) })
return true
end
function A.holdLeft(target, now)
local held = false
for _, state in ipairs(C.holdStates) do
if NPC.HasState(target, state) then held = true end
end
local left = 0
for _, mod in ipairs(NPC.GetModifiers(target) or {}) do
local name = Modifier.GetName(mod)
for _, word in ipairs(C.holdWords) do
if name:find(word, 1, true) ~= nil then
local rest = Modifier.GetDieTime(mod) - now
if rest > left then left = rest end
held = true
end
end
end
if not held then return 0 end
return left
end
function A.isCyclone(name)
for _, fragment in ipairs(C.cycloneItems) do
if name:find(fragment, 1, true) ~= nil then return true end
end
return false
end
function A.cycloneLand(target, now)
local own = (S.cycloneTarget == target and now < S.cycloneLand) and S.cycloneLand or nil
for _, name in ipairs(C.cycloneMods) do
local mod = NPC.GetModifier(target, name)
if mod ~= nil then
local die = Modifier.GetDieTime(mod)
if type(die) ~= "number" or die <= now then
local duration = Modifier.GetDuration(mod)
if type(duration) == "number" and duration > 0 then die = Modifier.GetCreationTime(mod) + duration end
end
if type(die) == "number" and die > now then return die end
return own or now + C.cycloneDuration
end
end
return own
end
function A.meteorFall(item)
local delay = C.meteorDelay
if C.special ~= nil then
local ok, value = pcall(C.special, item, "max_duration", -1)
if ok and type(value) == "number" and value > 0 then delay = value end
end
delay = IT.itemFall(item, delay)
return delay + math.max(0, IT.castPoint(item)) + A.settle() * 0.5
end
function A.meteorPoint(target, item, now)
local delay, radius = C.meteorDelay, C.meteorRadius
if C.special ~= nil then
local ok, value = pcall(C.special, item, "max_duration", -1)
if ok and type(value) == "number" and value > 0 then delay = value end
ok, value = pcall(C.special, item, "impact_radius", -1)
if ok and type(value) == "number" and value > 0 then radius = value end
end
delay = IT.itemFall(item, delay)
local reach = radius - NPC.GetHullRadius(target) - C.meteorMargin
local fall = delay + math.max(0, IT.castPoint(item)) + A.settle() * 0.5
local free = math.max(0, fall - A.holdLeft(target, now))
if NPC.GetMoveSpeed(target) * free <= reach then return Entity.GetAbsOrigin(target) end
return nil
end
function A.itemBase(name)
return (name:gsub("^item_", ""):gsub("_custom$", ""))
end
function A.itemLabel(name)
return (A.itemBase(name):gsub("_", " "))
end
function A.itemIcon(name)
local base = A.itemBase(name)
return "panorama/images/items/" .. (ICON_FIX[base] or base) .. "_png.vtex_c"
end
function A.itemSkipped(name)
for _, fragment in ipairs(ITEM_SKIP) do
if name:find(fragment, 1, true) ~= nil then return true end
end
return false
end
function A.has(value, bit)
return type(value) == "number" and bit > 0 and math.floor(value / bit) % 2 >= 1
end
function A.itemKind(item)
local behavior = Ability.GetBehavior(item)
if A.has(behavior, C.bPassive) or A.has(behavior, C.bHidden) or A.has(behavior, C.bToggle) then return nil end
if A.has(behavior, C.bUnit) then
local team = Ability.GetTargetTeam(item)
if A.has(team, C.targetEnemy) then return "enemy" end
if A.has(team, C.targetFriendly) then return "self" end
return nil
end
if A.has(behavior, C.bPoint) then return "point" end
if A.has(behavior, C.bNo) then return "no" end
return nil
end
function A.scanItems(hero)
local labels, ids, signature = {}, {}, ""
for _, slot in ipairs(C.itemSlots) do
local item = NPC.GetItemByIndex(hero, slot)
if item ~= nil then
local name = Ability.GetName(item)
local label = A.itemLabel(name)
if not A.itemSkipped(name) and A.itemKind(item) ~= nil and ids[label] == nil then
labels[#labels + 1] = label
ids[label] = name
signature = signature .. label .. "=" .. name .. ","
end
end
end
return labels, ids, signature
end
function A.refreshItems(hero)
IT.tick()
local labels, ids, signature = A.scanItems(hero)
if signature == S.itemSig then return end
local rank, old, enabled = {}, {}, {}
for i, id in ipairs(UI.items:List()) do
rank[id] = i
old[id] = true
end
for _, id in ipairs(UI.items:ListEnabled()) do enabled[id] = true end
table.sort(labels, function(a, b) return (rank[a] or 1000) < (rank[b] or 1000) end)
local rows, selected = {}, {}
for i, label in ipairs(labels) do
local on = not old[label] or enabled[label] == true
rows[i] = { label, A.itemIcon(ids[label]), on }
if on then selected[#selected + 1] = label end
end
UI.items:Update(rows, true, true)
UI.items:Set(selected)
S.itemSig = signature
S.itemIds = ids
IT.sync(hero, labels, ids, A.itemIcon)
A.log("info", "jakiro items refreshed", { items = labels, enabled = selected })
end
function A.findItem(hero, label, name)
for _, slot in ipairs(C.itemSlots) do
local item = NPC.GetItemByIndex(hero, slot)
if item ~= nil and Ability.GetName(item) == name then return item end
end
for _, slot in ipairs(C.itemSlots) do
local item = NPC.GetItemByIndex(hero, slot)
if item ~= nil and A.itemLabel(Ability.GetName(item)) == label then return item end
end
return nil
end
function A.meteorFollow(hero, cyclone)
for _, label in ipairs(UI.items:ListEnabled()) do
local name = S.itemIds[label]
if name ~= nil and A.isMeteor(name) then
local item = A.findItem(hero, label, name)
if item ~= nil and Ability.GetLevel(item) > 0 and Ability.GetCooldown(item) <= 0
and NPC.GetMana(hero) >= Ability.GetManaCost(item) + Ability.GetManaCost(cyclone) then
return true
end
end
end
return false
end
function A.eSoon(hero)
local e = NPC.GetAbility(hero, C.eName)
return e ~= nil and UI.spells:Get("spell.e") and A.spellReady(e, hero)
end
function A.cyclonePlanned(hero, target, now)
if S.opened or A.cycloneLand(target, now) ~= nil then return false end
for _, label in ipairs(UI.items:ListEnabled()) do
local name = S.itemIds[label]
if name ~= nil and A.isCyclone(name) then
local item = A.findItem(hero, label, name)
if item ~= nil and Ability.GetLevel(item) > 0 and Ability.GetCooldown(item) <= 0
and (A.meteorFollow(hero, item) or A.wFollow(hero, NPC.GetMana(hero) - Ability.GetManaCost(item))) then
return true
end
end
end
return false
end
function A.isJump(name)
return name:find("blink", 1, true) ~= nil or name:find("fallen_sky", 1, true) ~= nil
end
function A.itemReady(item, hero)
return item ~= nil and Ability.GetLevel(item) > 0 and Ability.IsCastable(item, NPC.GetMana(hero))
end
function A.clampPoint(hero, point, range)
if range <= 0 then return point end
local origin = Entity.GetAbsOrigin(hero)
local dx, dy = point.x - origin.x, point.y - origin.y
local length = math.sqrt(dx * dx + dy * dy)
local cap = math.max(0, range - 25)
if length <= cap or length <= 0 then return point end
local scale = cap / length
return Vector(origin.x + dx * scale, origin.y + dy * scale, point.z)
end
function A.comboReach(hero, ability)
local reach = 0
if ability ~= nil then reach = Ability.GetCastRange(ability) end
for _, label in ipairs(UI.items:ListEnabled()) do
local name = S.itemIds[label]
local item = name ~= nil and not A.isJump(name) and A.findItem(hero, label, name) or nil
if item ~= nil and A.itemReady(item, hero) then
local kind = A.itemKind(item)
if kind == "enemy" or kind == "point" then reach = math.max(reach, Ability.GetCastRange(item) + 75) end
end
end
return reach
end
function A.blinkPoint(hero, target)
local origin = Entity.GetAbsOrigin(hero)
local pos = Entity.GetAbsOrigin(target)
local dx, dy = pos.x - origin.x, pos.y - origin.y
local len = math.max(1, math.sqrt(dx * dx + dy * dy))
local range = NPC.GetAttackRange(hero) + NPC.GetAttackRangeBonus(hero)
local keep = range > 300 and math.max(C.blinkKeep, range - 100) or C.blinkKeep
return Vector(pos.x - dx / len * keep, pos.y - dy / len * keep, pos.z)
end
function A.orderMove(hero, point, now)
if now < S.moveAt then return end
A.order(hero, C.orderMove, point, nil, nil, false)
S.moveAt = now + C.moveGap
end
function A.isMeteor(name)
for _, fragment in ipairs(C.meteorItems) do
if name:find(fragment, 1, true) ~= nil then return true end
end
return false
end
function A.isShiva(name)
return name:find("shivas_guard", 1, true) ~= nil or name:find("gold_shiva", 1, true) ~= nil
end
function A.isHex(name)
return name:find("sheepstick", 1, true) ~= nil or name:find("hex", 1, true) ~= nil
end
function A.shivaHasTarget(hero, item)
local radius = C.shivaRadius
if C.special ~= nil then
local ok, value = pcall(C.special, item, "blast_radius", -1)
if ok and type(value) == "number" and value > 0 then radius = value end
end
for _, enemy in ipairs(Heroes.GetAll()) do
if A.valid(enemy) and not Entity.IsSameTeam(hero, enemy) and not NPC.IsIllusion(enemy)
and A.distance(hero, enemy) <= radius then
return true
end
end
return false
end
function A.useItems(hero, target, ability, now)
if now >= S.cycleAt then
S.done = {}
S.cycleAt = now + C.cycleGap
end
local distance = A.distance(hero, target)
for _, label in ipairs(UI.items:ListEnabled()) do
local name = S.itemIds[label]
if name ~= nil and not S.done[name] then
local item = A.findItem(hero, label, name)
if item == nil then
S.done[name] = true
elseif not IT.allow(hero, target, name, label) then
elseif A.itemReady(item, hero) then
local kind = A.itemKind(item)
local range = Ability.GetCastRange(item)
local jump = A.isJump(name)
if kind == nil then
S.done[name] = true
elseif kind == "enemy" and A.isCyclone(name) and (S.opened or not (A.meteorFollow(hero, item) or A.wFollow(hero, NPC.GetMana(hero) - Ability.GetManaCost(item)))) then
elseif name:find("ethereal", 1, true) ~= nil and (A.cyclonePlanned(hero, target, now) or A.eSoon(hero)
or A.early(target, now, now + A.settle() * 0.5 + distance / C.etherealSpeed, 0.1)) then
elseif (kind == "enemy" or kind == "point") and not jump and not A.isMeteor(name)
and A.early(target, now, now + math.max(0, IT.castPoint(item)) + A.settle() * 0.5, 0.1) then
elseif jump and distance <= A.comboReach(hero, ability) then
elseif A.isShiva(name) and not A.shivaHasTarget(hero, item) then
elseif A.isMeteor(name) and A.cycloneLand(target, now) ~= nil
and now < A.cycloneLand(target, now) - A.meteorFall(item) + C.meteorAfter then
elseif A.isMeteor(name) and A.cycloneLand(target, now) == nil and A.meteorPoint(target, item, now) == nil then
elseif (kind == "enemy" or kind == "point") and not jump and range > 0 and distance > range + 75 then
A.orderMove(hero, IT.stopPoint(hero, target, range), now)
return true
else
if kind == "enemy" then
Ability.CastTarget(item, target, false, false, true, C.identifier)
elseif kind == "self" then
Ability.CastTarget(item, hero, false, false, true, C.identifier)
elseif kind == "point" and jump then
Ability.CastPosition(item, A.clampPoint(hero, A.blinkPoint(hero, target), range), false, false, true, C.identifier)
elseif kind == "point" then
Ability.CastPosition(item, A.clampPoint(hero, Entity.GetAbsOrigin(target), range), false, false, true, C.identifier)
else
Ability.CastNoTarget(item, false, false, true, C.identifier)
end
S.done[name] = true
local delay = math.max(0.08, math.max(0, IT.castPoint(item)) + 0.06)
if kind == "enemy" and A.isHex(name) then delay = math.max(delay, C.hexWait) end
S.nextAt = now + delay
S.attacking = nil
IT.chainMark(hero, target, name)
if not A.isCyclone(name) and not A.isMeteor(name) and kind ~= "self" and kind ~= "no" then S.opened = true end
if kind == "enemy" and A.isCyclone(name) then
local duration = C.cycloneDuration
if C.special ~= nil then
local ok, value = pcall(C.special, item, "cyclone_duration", -1)
if ok and type(value) == "number" and value > 0 then duration = value end
end
S.cycloneTarget, S.cycloneLand = target, now + A.settle() * 0.5 + duration
end
if A.isMeteor(name) and A.cycloneLand(target, now) ~= nil then
local land = A.cycloneLand(target, now)
A.log("info", "jakiro meteor timed to cyclone", {
land_in = math.floor((land - now) * 100) / 100,
impact_after_land = math.floor((now + A.meteorFall(item) - land) * 100) / 100,
})
end
A.log("info", "jakiro combo item", { item = name, kind = kind })
return true
end
end
end
end
return false
end
function A.update()
local hero = Heroes.GetLocal()
if not A.valid(hero) or Entity.GetUnitName(hero) ~= C.hero then
if S.phase ~= "idle" then A.reset("no jakiro") end
return
end
local clock = GameRules.GetGameTime()
A.detectLegend(hero)
if clock >= S.itemAt and S.itemError == nil then
S.itemAt = clock + C.itemGap
local ok, err = pcall(A.refreshItems, hero)
if not ok then
S.itemError = tostring(err)
A.log("error", "jakiro items refresh failed", { error = S.itemError })
end
end
if not UI.enabled:Get() or not UI.key:IsDown() then
if S.phase ~= "idle" then A.reset("key released") end
return
end
if C.inputCaptured ~= nil and C.inputCaptured() then return end
if not A.orderSafe() then return end
if IT.heroDisabled(hero) then return end
local now = GameRules.GetGameTime()
if S.phase == "idle" then
S.target = A.pickTarget(hero)
if S.target == nil then return end
S.phase = "running"
S.startedAt = now
S.lastElem, S.pending, S.switchFrom = nil, nil, nil
S.mode, S.stepSpell, S.seqDone = "seq", nil, nil
S.areas, S.areaAt, S.areaUsed, S.lastSpell = {}, 0, false, nil
A.log("info", "jakiro combo started", { target = Entity.GetUnitName(S.target), element = A.element(hero), mode = S.mode })
end
local target = S.target
if IT.fogHold(target, now) then
if A.orderMove ~= nil then A.orderMove(hero, Entity.GetAbsOrigin(target), now) end
return
end
if not A.valid(target) or Entity.IsSameTeam(hero, target) or A.distance(hero, target) > UI.range:Get() + 1000 then
A.reset("target lost")
return
end
if now - S.startedAt > C.maxRun then
A.reset("timeout")
return
end
A.updateRunTrack(target, now)
local q = NPC.GetAbility(hero, C.qName)
local w = NPC.GetAbility(hero, C.wName)
local e = NPC.GetAbility(hero, C.eName)
local r = NPC.GetAbility(hero, C.rName)
A.confirm(now)
for _, ability in ipairs({ q, w, r }) do
if ability ~= nil and Ability.IsInAbilityPhase(ability) then return end
end
if now < S.nextAt or NPC.HasModifier(hero, "modifier_item_meteor_hammer_custom_cast") then return end
if S.pending ~= nil and S.pending.orb then return end
if IT.breakLinken(hero, target, now) then return end
do local mw = IT.meteorCast(hero, target, now, C.identifier) if mw ~= nil then S.nextAt = now + mw return end end
A.detectLegendE(hero)
if S.stepSpell == nil and S.pending == nil and A.castELegend(hero, target, now) then return end
local legendR = r ~= nil and Ability.GetLevel(r) > 0 and S.legendR
if legendR and S.stepSpell == nil and A.keepArea(hero, target, r, now) then return end
if A.runSequence(hero, target, { q = q, w = w, e = e, r = r }, now, A.sequence(legendR)) then return end
if A.useItems(hero, target, q, now) then return end
A.idle(hero, target, now)
end
function A.inArea(target, now)
local pos, hull = Entity.GetAbsOrigin(target), NPC.GetHullRadius(target)
local keep = {}
local inside = false
for _, a in ipairs(S.areas) do
if now < a.expires then
keep[#keep + 1] = a
if (a.pos - pos):Length2D() <= C.rRadius + hull * 0.5 then inside = true end
end
end
S.areas = keep
return inside
end
function A.keepArea(hero, target, r, now)
if S.pending ~= nil or now < S.areaAt or not UI.spells:Get("spell.r") then return false end
if not S.areaUsed or A.inArea(target, now) then return false end
if not A.spellReady(r, hero) or S.lastSpell == C.rName then return false end
local mod = NPC.GetModifier(target, C.r7StackMod)
local stacks = mod ~= nil and Modifier.GetStackCount(mod) or 0
if stacks < C.stackCharge and Ability.GetCurrentCharges(r) < C.chargeReserve then return false end
local result = A.castR(hero, target, r, now)
if result == true then
S.areaAt = now + C.areaRecast
A.log("info", "jakiro keep area", { stacks = stacks, charges = Ability.GetCurrentCharges(r) })
return true
end
return false
end
function A.sequence(legendR)
if legendR then return C.sequenceR7 end
local others = {}
for _, id in ipairs(IT.spellOrder(UI.spells)) do
local key = id:sub(7)
if key ~= "q" then others[#others + 1] = key end
end
if #others == 0 then return C.sequence end
local out = {}
for _, key in ipairs(others) do
out[#out + 1] = key
out[#out + 1] = "q"
end
local sig = table.concat(out, ",")
if S.seqSig ~= sig then
S.seqSig = sig
S.seqDone = nil
end
return out
end
function A.runSequence(hero, target, spells, now, sequence)
S.seqDone = S.seqDone or {}
if S.stepSpell ~= nil then
if S.pending ~= nil then return true end
S.seqDone[S.stepIndex] = true
S.stepSpell = nil
end
local open = 0
for i, key in ipairs(sequence) do
if not S.seqDone[i] then
local ability = spells[key]
if ability == nil or Ability.GetLevel(ability) <= 0 or Ability.IsHidden(ability) or not UI.spells:Get("spell." .. key) then
S.seqDone[i] = true
else
open = open + 1
if A.spellReady(ability, hero) and not IT.immuneBlocked(target, Ability.GetName(ability)) then
local cast = key == "q" and A.castQ or key == "w" and A.castW or key == "e" and A.castE or A.castR
local result = cast(hero, target, ability, now)
if result == true then
if S.pending ~= nil and S.pending.h == ability then
S.stepSpell, S.stepIndex = ability, i
A.log("info", "jakiro sequence step", { step = i, spell = key, element = A.element(hero) })
end
return true
end
end
end
end
end
if open == 0 then
S.seqDone = nil
A.log("info", "jakiro sequence cycle done")
end
return false
end
function A.drawError()
local title = S.menuError and localization.Get("panel.menu_failed") or localization.Get("panel.error")
local message = S.menuError or S.error or S.itemError or "unknown"
Render.FilledRect(Vec2(20, 370), Vec2(780, 418), Color(20, 20, 24, 235), 4)
Render.Text(S.font, 14, title, Vec2(30, 377), Color(224, 50, 45, 245))
Render.Text(S.font, 12, message:sub(1, 160), Vec2(30, 397), Color(220, 220, 225, 240))
end
function script.OnScriptsLoaded()
local ok, result = pcall(A.initMenu)
S.ready = ok and result == true
if not S.ready then S.menuError = ok and "initMenu returned false" or tostring(result) end
S.font = Render.LoadFont("MuseoSansEx", 0, 500)
A.log("info", "jakiro_1x6_combo loaded", { ready = S.ready, error = S.menuError })
end
function script.OnUpdate()
if not S.ready or not Engine.IsInGame() then return end
local ok, err = pcall(A.update)
if not ok then
if S.error == nil then A.log("error", "jakiro combo update failed", { error = tostring(err) }) end
S.error = tostring(err)
A.reset("error")
end
end
function script.OnGameEnd()
A.reset("game end")
IT.reset()
S.error = nil
S.itemError = nil
S.itemSig = ""
S.itemIds = {}
S.itemAt = 0
S.enemyTrack = {}
