tostring(S.lastElem or "-"), tostring(S.want or "-")),
string.format("switch %s | pending %s | legend Q %s R %s | R stacks %d", S.switchFrom ~= nil and "wait" or "-",
S.pending ~= nil and S.pending.name:gsub("jakiro_", ""):gsub("_custom", "") or "-", tostring(S.legend), tostring(S.legendR), stacks),
}
for i, line in ipairs(lines) do
Render.FilledRect(Vec2(20, 300 + (i - 1) * 18), Vec2(560, 316 + (i - 1) * 18), Color(12, 12, 15, 200), 3)
Render.Text(S.font, 12, line, Vec2(26, 302 + (i - 1) * 18), Color(220, 220, 225, 240))
end
end
function A.drawFrame()
if S.menuError ~= nil or S.error ~= nil or S.itemError ~= nil then A.drawError() end
if S.ready and S.error == nil then A.drawStatus() end
end
function script.OnDraw()
local ok, err = pcall(A.drawFrame)
if not ok and S.error == nil then
S.error = tostring(err)
A.log("error", "jakiro combo draw failed", { error = S.error })
end
end
return script
end)
