state.veil_attack_at = 0
state.veil_attack_target = nil
end
function helpers.is_local_muerta(hero)
return hero and Entity.GetUnitName(hero) == cfg.hero_name
end
function helpers.get_dead_shot(hero)
for _, name in ipairs(cfg.ability_names) do
local ability = NPC.GetAbility(hero, name)
if ability and not Ability.IsHidden(ability) and Ability.GetLevel(ability) > 0 then return ability end
end
return nil
end
function helpers.get_ability(hero, names)
for _, name in ipairs(names) do
local ability = NPC.GetAbility(hero, name)
if ability and not Ability.IsHidden(ability) and Ability.GetLevel(ability) > 0 then return ability end
end
return nil
end
function helpers.ability_ready(ability, hero)
return ability ~= nil and not Ability.IsHidden(ability) and Ability.GetLevel(ability) > 0
and Ability.IsCastable(ability, NPC.GetMana(hero))
end
function helpers.latency()
local ok, value = pcall(NetChannel.GetAvgLatency, cfg.flow_outgoing)
if ok and type(value) == "number" then return clamp(value, 0, cfg.prediction.latency_cap) end
return 0.05
end
function helpers.special(ability, names, fallback)
for _, name in ipairs(names) do
local value = Ability.GetLevelSpecialValueFor(ability, name, -1)
if value and value > 0 then return value end
end
return fallback
end
function helpers.get_params(hero, ability)
local custom = Ability.GetName(ability) == cfg.ability_names[1]
local cast_range = Ability.GetCastRange(ability)
if cast_range <= 0 then
cast_range = helpers.special(ability, { "AbilityCastRange", "cast_range" }, cfg.deadshot.cast_range)
end
local range_bonus = NPC.GetCastRangeBonus(hero)
local damage = Ability.GetDamage(ability) or 0
if damage <= 0 then
damage = helpers.special(ability, { "damage", "impact_damage", "ricochet_damage", "bullet_damage" }, cfg.deadshot.damage)
end
local speed = helpers.special(ability, { "speed", "projectile_speed", "bullet_speed", "ricochet_speed", "projectile_speed_initial" }, cfg.deadshot.speed)
local ricochet, ricochet_multiplier, radius
if custom then
ricochet = helpers.special(ability, { "range" }, cfg.deadshot.ricochet) + range_bonus
ricochet_multiplier = 0
radius = helpers.special(ability, { "ricochet_radius_start", "ricochet_radius_end" }, cfg.deadshot.radius)
else
ricochet = helpers.special(ability, { "ricochet_distance", "ricochet_range", "ricochet_max_distance", "bounce_range", "bullet_range", "range", "distance" }, 0)
ricochet_multiplier = helpers.special(ability, { "ricochet_distance_multiplier" }, 0)
if ricochet <= 0 then
ricochet = ricochet_multiplier > 0 and cast_range * ricochet_multiplier or cfg.deadshot.ricochet
end
if ricochet_multiplier <= 0 then ricochet_multiplier = ricochet / math.max(cast_range, 1) end
radius = helpers.special(ability, { "radius", "ricochet_radius", "ricochet_radius_start", "ricochet_radius_end", "projectile_radius", "impact_radius", "width" }, cfg.deadshot.radius)
end
local latency = 0.05
local ok, value = pcall(NetChannel.GetAvgLatency, cfg.flow_outgoing)
if ok and type(value) == "number" then latency = value end
return {
fixed_ricochet = custom,
cast_range = cast_range,
damage = damage,
speed = speed,
ricochet = ricochet,
ricochet_multiplier = ricochet_multiplier,
radius = radius,
fear_duration = helpers.special(ability, { "ricochet_fear_duration" }, 0.8),
cast_point = IT.castPoint(ability, true) or cfg.deadshot.cast_point,
latency = clamp(latency, 0, cfg.prediction.latency_cap),
}
end
function helpers.ricochet_length(first_distance, params)
if params.fixed_ricochet then return params.ricochet end
return clamp(first_distance * params.ricochet_multiplier, params.radius + 120, params.ricochet)
end
function helpers.is_disabled(unit)
if NPC.IsStunned(unit) then return true end
for _, state_id in ipairs(disabled_states) do
if NPC.HasState(unit, state_id) then return true end
end
return false
end
function helpers.is_magic_immune(unit)
return NPC.HasState(unit, cfg.magic_immune)
end
function helpers.is_valid_unit(unit)
return unit and Entity.IsAlive(unit) and not Entity.IsDormant(unit) and NPC.IsVisible(unit) and not NPC.IsIllusion(unit)
end
function helpers.is_enemy_hero(unit)
return helpers.is_valid_unit(unit) and NPC.IsHero(unit) and not helpers.is_magic_immune(unit)
end
function helpers.is_enemy_creep(unit)
return helpers.is_valid_unit(unit) and NPC.IsCreep(unit) and not helpers.is_magic_immune(unit)
end
function helpers.effective_damage(target, damage)
if helpers.is_magic_immune(target) then return 0 end
return damage * NPC.GetMagicalArmorDamageMultiplier(target)
end
function helpers.health(unit)
local hp = Entity.GetHealth(unit)
local barriers = NPC.GetBarriers(unit)
if barriers then
hp = hp + barriers.magic.current + barriers.all.current
end
return hp
end
function helpers.is_lethal(target, damage)
return damage >= helpers.health(target) - 12
end
function helpers.update_enemy_track(hero)
local now = GameRules.GetGameTime()
local enemies = Entity.GetHeroesInRadius(hero, cfg.search_radius, cfg.team_enemy, true) or {}
local update_unit = function(unit)
local id = Entity.GetIndex(unit)
local pos = Entity.GetAbsOrigin(unit)
local track = state.enemy_track[id] or {
last_pos = pos,
last_time = now,
vel = Vector(0, 0, 0),
normal_speed = NPC.GetMoveSpeed(unit),
}
local dt = math.max(0.016, now - track.last_time)
local raw = (pos - track.last_pos) / dt
track.vel = raw * 0.58 + track.vel * 0.42
track.last_pos = pos
track.last_time = now
track.entity = unit
state.enemy_track[id] = track
if NPC.GetModifier(unit, cfg.fear_mod) == nil and not helpers.is_disabled(unit)
and helpers.speed_modifier_left(unit, now) == nil then
track.normal_speed = NPC.GetMoveSpeed(unit)
end
end
update_unit(hero)
for _, enemy in ipairs(enemies) do
if helpers.is_valid_unit(enemy) then update_unit(enemy) end
end
end
function helpers.update_calling_spirits(hero, now)
if now < state.spirit_scan_at and state.spirit_scan_at - now <= cfg.calling_track_interval * 2 then return end
state.spirit_scan_at = now + cfg.calling_track_interval
local units = Entity.GetUnitsInRadius(hero, cfg.calling_search, cfg.team_friend, true, true) or {}
local hero_id = Entity.GetIndex(hero)
local spirits = {}
local seen = {}
for _, unit in ipairs(units) do
if Entity.GetUnitName(unit) == "npc_dota_companion" then
local modifier = NPC.GetModifier(unit, cfg.calling_revenant_mod)
local caster = modifier ~= nil and Modifier.GetCaster(modifier) or nil
if modifier ~= nil and (caster == nil or Entity.GetIndex(caster) == hero_id) then
local id = Entity.GetIndex(unit)
local pos = Entity.GetAbsOrigin(unit)
local track = state.spirit_track[id]
if track == nil then
track = { pos = pos, time = now, vel = Vector(0, 0, 0) }
else
local dt = now - track.time
if dt > 0.01 and dt <= 0.35 then
local raw = (pos - track.pos) / dt
local speed = raw:Length2D()
if speed > 700 then raw = raw:Normalized() * 700 end
track.vel = raw * 0.72 + track.vel * 0.28
else
track.vel = Vector(0, 0, 0)
end
track.pos = pos
track.time = now
end
track.entity = unit
state.spirit_track[id] = track
spirits[#spirits + 1] = track
seen[id] = true
end
end
end
for id, track in pairs(state.spirit_track) do
if not seen[id] and now - track.time > 0.35 then state.spirit_track[id] = nil end
end
if #spirits >= 3 then
local center = Vector(0, 0, 0)
for _, track in ipairs(spirits) do center = center + track.pos end
center = center / #spirits
for _, track in ipairs(spirits) do
local radial = track.pos - center
local radius = radial:Length2D()
if radius > 80 then
local tangent = radial:Normalized():Rotated(math.pi * 0.5)
track.center = center
track.angular = clamp(track.vel:Dot2D(tangent) / radius, -1.5, 1.5)
else
track.center = nil
track.angular = nil
end
end
end
state.calling_spirits = spirits
if #spirits >= cfg.calling_legendary_fear_stack then state.legendary_w = true end
end
function helpers.speed_modifier_left(unit, now)
local track = state.enemy_track[Entity.GetIndex(unit)]
if track and track.speed_scan_at and now - track.speed_scan_at < 0.04 then return track.speed_left end
local best, generic = nil, nil
for _, modifier in ipairs(NPC.GetModifiers(unit) or {}) do
if not Modifier.IsDebuff(modifier) then
local name = Modifier.GetName(modifier):lower()
local left = Modifier.GetDieTime(modifier) - now
if left > 0.02 and left <= cfg.prediction.max_lead + 1
and (generic == nil or left < generic) then
generic = left
end
for _, word in ipairs(SPEED_WORDS) do
if name:find(word, 1, true) ~= nil then
if left > 0.02 and left <= cfg.prediction.max_lead + 1
and (best == nil or left < best) then
best = left
end
break
end
end
end
end
if best == nil and track and track.normal_speed
and NPC.GetMoveSpeed(unit) > track.normal_speed * cfg.prediction.boost_ratio then
best = generic or cfg.prediction.boost_fallback
end
if track then
track.speed_scan_at = now
track.speed_left = best
end
return best
end
function helpers.prediction_distance(unit, time, speed)
local lead = math.min(time, cfg.prediction.max_lead)
local now = GameRules.GetGameTime()
local fear = NPC.GetModifier(unit, cfg.fear_mod)
if fear ~= nil then
lead = math.min(lead, math.max(0, Modifier.GetDieTime(fear) - now))
end
local boost_left = helpers.speed_modifier_left(unit, now)
if boost_left == nil or boost_left >= lead then return speed * lead end
local track = state.enemy_track[Entity.GetIndex(unit)]
local normal = track and track.normal_speed or NPC.GetBaseSpeed(unit)
normal = math.min(speed, math.max(0, normal))
return speed * boost_left + normal * (lead - boost_left)
end
function helpers.movement_vector(unit)
local track = state.enemy_track[Entity.GetIndex(unit)]
local vel = track and track.vel or Vector(0, 0, 0)
local speed = vel:Length2D()
if speed < cfg.prediction.still_speed then return Vector(0, 0, 0), 0 end
local move_speed = NPC.GetMoveSpeed(unit)
local forward = Entity.GetRotation(unit):GetForward():Normalized()
local run_vel = forward * move_speed
if speed > move_speed then
vel = vel:Normalized() * move_speed
speed = move_speed
end
if NPC.IsRunning(unit) then
local align = vel:Normalized():Dot2D(forward)
if align > 0.35 then
local blend = clamp((align - 0.35) / 0.65, 0, 1)
local blended = vel * (0.45 + blend * 0.2) + run_vel * (0.55 - blend * 0.2)
return blended, math.min(blended:Length2D(), move_speed)
end
return vel:Normalized() * move_speed, move_speed
end
return vel * 0.35, speed * 0.35
end
function helpers.predict_pos(unit, time)
local pos = Entity.GetAbsOrigin(unit)
time = IT.moveTime(unit, time, GameRules.GetGameTime())
if time <= 0.02 then return pos end
local vel, speed = helpers.movement_vector(unit)
if speed <= 10 then return pos end
return pos + vel:Normalized() * helpers.prediction_distance(unit, time, speed)
end
function helpers.predict_intercept(unit, from_pos, base_time, projectile_speed, max_distance)
local pos = Entity.GetAbsOrigin(unit)
if helpers.is_disabled(unit) then return pos, base_time + from_pos:Distance2D(pos) / projectile_speed end
local _, speed = helpers.movement_vector(unit)
if speed <= 10 then return pos, base_time + from_pos:Distance2D(pos) / projectile_speed end
local predicted = helpers.predict_pos(unit, base_time + from_pos:Distance2D(pos) / projectile_speed)
local total_time = base_time
for _ = 1, 5 do
local travel = from_pos:Distance2D(predicted) / projectile_speed
travel = math.min(travel, max_distance / projectile_speed)
total_time = base_time + travel
predicted = helpers.predict_pos(unit, total_time)
end
return predicted, total_time
end
function helpers.caster_position(hero, params)
return helpers.predict_pos(hero, params.cast_point + params.latency)
end
function helpers.prediction_samples(unit, time)
local pos = Entity.GetAbsOrigin(unit)
if time <= 0.02 or helpers.is_disabled(unit) then return { { pos = pos, weight = 1.0 } } end
local vel, speed = helpers.movement_vector(unit)
if speed <= 10 then return { { pos = pos, weight = 1.0 } } end
local lead = math.min(time, cfg.prediction.max_lead)
local dir = vel:Normalized()
local cone = math.rad(13 + clamp(lead * 8, 0, 9))
local back_weight = NPC.IsRunning(unit) and 0.06 or 0.12
local samples = {
{ pos = pos:Extrapolate(dir, helpers.prediction_distance(unit, lead, speed)), weight = 0.46 },
{ pos = pos:Extrapolate(dir:Rotated(cone), helpers.prediction_distance(unit, lead, speed)), weight = 0.16 },
{ pos = pos:Extrapolate(dir:Rotated(-cone), helpers.prediction_distance(unit, lead, speed)), weight = 0.16 },
{ pos = pos, weight = 0.08 },
{ pos = pos:Extrapolate(dir, -helpers.prediction_distance(unit, lead, speed) * 0.34), weight = back_weight },
}
local total = 0
for _, sample in ipairs(samples) do total = total + sample.weight end
for _, sample in ipairs(samples) do sample.weight = sample.weight / total end
return samples
end
function helpers.point_segment_distance(from, to, point)
local line = to - from
local projected = point - from
local len_sqr = line:Length2DSqr()
if len_sqr <= 0.001 then return from:Distance2D(point), 0, from end
local t = clamp(projected:Dot2D(line) / len_sqr, 0, 1)
local closest = from + line * t
return closest:Distance2D(point), t, closest
end
function helpers.spirit_route(target, target_pos, dir, impact_time, fear_duration, fixed_duration)
if #state.calling_spirits == 0 then return 0, nil end
local duration = math.max(0, fear_duration or 0)
if state.legendary_q and not fixed_duration then duration = duration * 0.5 end
local move_speed = math.max(1, NPC.GetMoveSpeed(target))
local path_length = math.min(cfg.fear_distance, move_speed * duration)
if path_length < 35 then return 0, nil end
local fear_end = target_pos:Extrapolate(dir, path_length)
local radius = cfg.calling_hit_radius + NPC.GetHullRadius(target) + cfg.calling_route_margin
local best_score, best_distance = 0, nil
for _, track in ipairs(state.calling_spirits) do
local t, distance = 0, math.huge
for _ = 1, 2 do
local travel = t * path_length / move_speed
local lead = math.min(cfg.calling_predict_cap, impact_time + travel)
local spirit_pos
if track.center ~= nil and track.angular ~= nil then
spirit_pos = track.center + (track.pos - track.center):Rotated(track.angular * lead)
else
spirit_pos = track.pos + track.vel * math.min(lead, 0.35)
end
distance, t = helpers.point_segment_distance(target_pos, fear_end, spirit_pos)
end
if distance <= radius then
local quality = clamp(1 - distance / radius, 0, 1)
local score = cfg.calling_route_bonus * quality * (1 - t * 0.2)
if score > best_score then
best_score = score
best_distance = distance
end
end
end
return best_score, best_distance
end
function helpers.line_hit_chance(unit, start_pos, dir, length, first_time, params)
if helpers.is_disabled(unit) then return 0.98 end
local chance = 0
local samples = ui.line_samples:Get()
local radius = params.radius + NPC.GetHullRadius(unit) + 22
local vel, speed = helpers.movement_vector(unit)
for i = 0, samples do
local step = length * (i / samples)
local time = first_time + step / params.speed
local line_pos = start_pos:Extrapolate(dir, step)
local local_chance = 0
for _, sample in ipairs(helpers.prediction_samples(unit, time)) do
local distance = sample.pos:Distance2D(line_pos)
if distance <= radius then
local_chance = local_chance + sample.weight * clamp(1 - distance / (radius * 1.35), 0.34, 1)
end
end
chance = math.max(chance, local_chance)
end
if speed > 10 then
local target_start = helpers.predict_pos(unit, first_time)
local projectile_vel = dir * params.speed
local rel = target_start - start_pos
local rel_vel = vel - projectile_vel
local rel_len = rel_vel:Length2DSqr()
if rel_len > 1 then
local t = clamp(-rel:Dot2D(rel_vel) / rel_len, 0, length / params.speed)
local bullet_pos = start_pos + projectile_vel * t
local target_pos = helpers.predict_pos(unit, first_time + t)
local distance = bullet_pos:Distance2D(target_pos)
if distance <= radius + 28 then
chance = math.max(chance, clamp(1 - distance / ((radius + 28) * 1.45), 0.32, 0.96))
end
end
end
if NPC.IsTurning(unit) then chance = chance * cfg.prediction.turn_penalty end
return clamp(chance, 0, 1)
end
function helpers.count_line_hits(enemies, target, start_pos, dir, length, first_time, params)
local result = {
heroes = 0,
damage = 0,
target_hit = false,
names = {},
}
local end_pos = start_pos:Extrapolate(dir, length)
local radius = params.radius + 35
for _, enemy in ipairs(enemies) do
if helpers.is_enemy_hero(enemy) then
local predicted = helpers.predict_intercept(enemy, start_pos, first_time, params.speed, length)
local distance = helpers.point_segment_distance(start_pos, end_pos, predicted)
if distance <= radius + NPC.GetHullRadius(enemy) then
result.heroes = result.heroes + 1
result.damage = result.damage + helpers.effective_damage(enemy, params.damage)
result.names[#result.names + 1] = NPC.GetUnitName(enemy)
if enemy == target then result.target_hit = true end
end
end
end
return result
end
function helpers.get_enemies(hero, radius)
local enemies = Entity.GetHeroesInRadius(hero, radius, cfg.team_enemy, true) or {}
local result = {}
local hero_pos = Entity.GetAbsOrigin(hero)
for _, enemy in ipairs(enemies) do
if helpers.is_enemy_hero(enemy) then result[#result + 1] = enemy end
end
table.sort(result, function(a, b)
return Entity.GetAbsOrigin(a):Distance2D(hero_pos) < Entity.GetAbsOrigin(b):Distance2D(hero_pos)
end)
return result
end
function helpers.get_cursor_target(hero, radius)
if cfg.cursor_hero == nil then return nil end
local hero_pos = Entity.GetAbsOrigin(hero)
local ok, target = pcall(cfg.cursor_hero, Entity.GetTeamNum(hero), cfg.team_enemy)
if ok and target and helpers.is_enemy_hero(target) and hero_pos:IsInRange2D(Entity.GetAbsOrigin(target), radius) then
return target
end
return nil
end
function helpers.add_anchor(anchors, hero_pos, entity, kind, pos, priority, params)
if hero_pos:IsInRange2D(pos, params.cast_range + 80) then
anchors[#anchors + 1] = {
entity = entity,
kind = kind,
pos = pos,
priority = priority,
}
end
end
function helpers.build_anchors(hero, enemies, params)
local hero_pos = Entity.GetAbsOrigin(hero)
local anchors = {}
if helpers.source_enabled("hero") then
for _, enemy in ipairs(enemies) do
local pos = Entity.GetAbsOrigin(enemy)
helpers.add_anchor(anchors, hero_pos, enemy, "hero", pos, 1000 - hero_pos:Distance2D(pos) * 0.1, params)
end
end
if helpers.source_enabled("creep") and ui.max_creeps:Get() > 0 then
local units = Entity.GetUnitsInRadius(hero, params.cast_range + 120, cfg.team_enemy, true) or {}
local creeps = {}
for _, unit in ipairs(units) do
if helpers.is_enemy_creep(unit) then
local pos = Entity.GetAbsOrigin(unit)
creeps[#creeps + 1] = {
entity = unit,
pos = pos,
dist = hero_pos:Distance2D(pos),
}
end
end
table.sort(creeps, function(a, b) return a.dist < b.dist end)
for i = 1, math.min(ui.max_creeps:Get(), #creeps) do
helpers.add_anchor(anchors, hero_pos, creeps[i].entity, "creep", creeps[i].pos, 420 - creeps[i].dist * 0.04, params)
end
end
if helpers.source_enabled("tree") and ui.max_trees:Get() > 0 then
local trees = Trees.InRadius(hero_pos, params.cast_range + 120, true) or {}
local sorted = {}
local reach = helpers.ricochet_length(params.cast_range, params) + params.radius
for _, tree in ipairs(trees) do
local pos = Entity.GetAbsOrigin(tree)
local near = math.huge
if hero_pos:IsInRange2D(pos, params.cast_range + 80) then
for _, enemy in ipairs(enemies) do
near = math.min(near, pos:Distance2D(Entity.GetAbsOrigin(enemy)))
end
end
if near <= reach then
sorted[#sorted + 1] = {
entity = tree,
pos = pos,
dist = near,
}
end
end
table.sort(sorted, function(a, b) return a.dist < b.dist end)
for i = 1, math.min(ui.max_trees:Get(), #sorted) do
helpers.add_anchor(anchors, hero_pos, sorted[i].entity, "tree", sorted[i].pos, 260 - sorted[i].dist * 0.1, params)
end
end
if helpers.source_enabled("building") then
local reach = helpers.ricochet_length(params.cast_range, params) + params.radius
for _, unit in ipairs(NPCs.InRadius(hero_pos, params.cast_range + 120, Entity.GetTeamNum(hero), cfg.team_both, true, true) or {}) do
if unit ~= hero and Entity.IsAlive(unit) and (NPC.IsStructure(unit) or NPC.IsTower(unit) or (Entity.GetUnitName(unit) or ""):find("watcher", 1, true) ~= nil) then
local pos = Entity.GetAbsOrigin(unit)
local near = math.huge
for _, enemy in ipairs(enemies) do
near = math.min(near, pos:Distance2D(Entity.GetAbsOrigin(enemy)))
end
if near <= reach then
helpers.add_anchor(anchors, hero_pos, unit, "building", pos, 300 - near * 0.1, params)
end
end
end
end
table.sort(anchors, function(a, b) return a.priority > b.priority end)
while #anchors > ui.max_candidates:Get() do table.remove(anchors) end
return anchors
end
function helpers.choose_direct_direction(hero_pos, target, target_pos, enemies, first_time, params)
local best_dir = target_pos:DirectionTo(hero_pos)
local best_enemy = nil
local best_score = 0
local ricochet_len = helpers.ricochet_length(hero_pos:Distance2D(target_pos), params)
for _, enemy in ipairs(enemies) do
if enemy ~= target and helpers.is_enemy_hero(enemy) then
local predicted = helpers.predict_intercept(enemy, target_pos, first_time, params.speed, ricochet_len)
local distance = target_pos:Distance2D(predicted)
if distance <= ricochet_len + params.radius then
local dir = target_pos:DirectionTo(predicted)
local fear = dir:Dot2D(predicted:DirectionTo(hero_pos))
local chance = helpers.line_hit_chance(enemy, target_pos, dir, ricochet_len, first_time, params)
local score = chance * 140 + math.max(0, fear) * 110 - distance * 0.03
if score > best_score then
best_dir = dir
best_enemy = enemy
best_score = score
end
end
end
end
return best_dir, best_enemy, best_score
end
function helpers.make_plan(hero, ability, target, cast_entity, cast_pos, dir, params, data)
data.hero = hero
data.ability = ability
data.target = target
data.cast_entity = cast_entity
data.cast = cast_pos
data.ricochet_length = data.ricochet_length or params.ricochet
data.end_pos = cast_pos:Extrapolate(dir, data.ricochet_length)
if not data.vector then
if data.anchor_kind == "target" or data.anchor_kind == "hero" or data.anchor_kind == "creep" then
data.vector = Entity.GetAbsOrigin(cast_entity):Extrapolate(dir, data.ricochet_length)
else
data.vector = data.end_pos
end
end
data.dir = dir
data.hero_pos = Entity.GetAbsOrigin(hero)
return data
end
function helpers.evaluate_direct(hero, ability, target, enemies, params)
if not ui.direct_lethal:Get() then return nil end
local current_hero_pos = Entity.GetAbsOrigin(hero)
local hero_pos = helpers.caster_position(hero, params)
local target_pos = Entity.GetAbsOrigin(target)
local predicted, impact_time = helpers.predict_intercept(target, hero_pos, params.cast_point + params.latency, params.speed, params.cast_range)
if not current_hero_pos:IsInRange2D(target_pos, params.cast_range + 85) then return nil end
local damage = helpers.effective_damage(target, params.damage)
local lethal = helpers.is_lethal(target, damage)
local hit_chance = helpers.is_disabled(target) and 0.98 or clamp(0.91 - impact_time * 0.09, 0.54, 0.94)
local dir, secondary, secondary_score = helpers.choose_direct_direction(hero_pos, target, predicted, enemies, impact_time, params)
local ricochet_len = helpers.ricochet_length(hero_pos:Distance2D(predicted), params)
local hits = helpers.count_line_hits(enemies, target, predicted, dir, ricochet_len, impact_time, params)
local score = 520 + hit_chance * 250 + secondary_score
if lethal then score = score + cfg.score.direct_lethal end
if secondary then score = score + 180 end
if not lethal and not secondary then score = score - 330 end
return helpers.make_plan(hero, ability, target, target, predicted, dir, params, {
score = score,
hit_chance = hit_chance,
fear_score = secondary and 1 or 0,
travel_time = impact_time,
reason = lethal and "direct lethal" or (secondary and "direct chain" or "direct damage"),
first_time = impact_time,
anchor_kind = "target",
lethal = lethal,
damage_only = not lethal and not secondary,
hits = hits,
primary_damage = damage,
ricochet_length = ricochet_len,
})
end
function helpers.evaluate_anchor(hero, ability, target, anchor, enemies, params)
if anchor.entity == target then return nil end
local current_hero_pos = Entity.GetAbsOrigin(hero)
local hero_pos = helpers.caster_position(hero, params)
local anchor_pos = anchor.pos
local first_time = params.cast_point + params.latency + hero_pos:Distance2D(anchor_pos) / params.speed
if anchor.kind ~= "tree" and anchor.kind ~= "building" then
for _ = 1, 3 do
anchor_pos = helpers.predict_pos(anchor.entity, first_time)
first_time = params.cast_point + params.latency + hero_pos:Distance2D(anchor_pos) / params.speed
end
end
if not current_hero_pos:IsInRange2D(anchor.pos, params.cast_range + 90) then return nil end
local first_distance = hero_pos:Distance2D(anchor_pos)
local ricochet_len = helpers.ricochet_length(first_distance, params)
local predicted, impact_time = helpers.predict_intercept(target, anchor_pos, first_time, params.speed, ricochet_len)
local bounce_start = anchor_pos
local bounce_dist = bounce_start:Distance2D(predicted)
if bounce_dist < 65 or bounce_dist > ricochet_len + params.radius + NPC.GetHullRadius(target) then return nil end
local dir = bounce_start:DirectionTo(predicted)
local fear_score = dir:Dot2D(predicted:DirectionTo(hero_pos))
local spirit_score, spirit_distance = helpers.spirit_route(target, predicted, dir, impact_time, params.fear_duration)
local damage = helpers.effective_damage(target, params.damage)
local lethal = helpers.is_lethal(target, damage)
local damage_only = fear_score < ui.min_fear:Get() * 0.01 and not lethal
local hit_chance = helpers.line_hit_chance(target, bounce_start, dir, ricochet_len, first_time, params)
local fear_plan = fear_score > 0.38
local long_risk = impact_time > 1.12 or bounce_dist > 720
if fear_plan and long_risk and hit_chance < 0.74 and not lethal then return nil end
if hit_chance < (damage_only and 0.40 or 0.52) and not lethal then return nil end
local hits = helpers.count_line_hits(enemies, target, bounce_start, dir, ricochet_len, first_time, params)
if not hits.target_hit and not lethal then return nil end
local anchor_damage = 0
local anchor_lethal = false
if anchor.kind == "hero" and helpers.is_enemy_hero(anchor.entity) then
anchor_damage = helpers.effective_damage(anchor.entity, params.damage)
anchor_lethal = helpers.is_lethal(anchor.entity, anchor_damage)
end
local score = hit_chance * 330
score = score + spirit_score
score = score + math.max(0, fear_score) * ui.fear_weight:Get()
score = score + hits.heroes * 90
score = score + math.min(hits.damage * 0.18, 220)
score = score + math.min(anchor_damage * 0.22, 160)
score = score - impact_time * cfg.score.travel_penalty
score = score - math.max(0, bounce_dist - 450) * cfg.score.long_bounce_penalty
if anchor.kind == "hero" then
score = score + cfg.score.hero_anchor
if ui.prefer_double:Get() then score = score + cfg.score.prefer_double end
elseif anchor.kind == "creep" then
score = score + cfg.score.creep_anchor
elseif anchor.kind == "tree" or anchor.kind == "building" then
score = score + cfg.score.tree_anchor
end
if fear_plan then
local fast_bonus = clamp(1.15 - impact_time, 0, 0.75)
local close_bonus = clamp((720 - bounce_dist) / 720, 0, 1)
score = score + fear_score * hit_chance * 330
score = score + fast_bonus * 260 + close_bonus * 120
if anchor.kind == "tree" and impact_time < 0.95 and hit_chance >= 0.68 then score = score + 110 end
end
if anchor.kind == "tree" and impact_time > 1.05 and not lethal then score = score - (impact_time - 1.05) * 360 end
if anchor.kind == "tree" and bounce_dist > 760 and not lethal then score = score - (bounce_dist - 760) * 0.35 end
if hits.heroes >= 2 then score = score + cfg.score.double_hit end
if lethal then score = score + cfg.score.target_lethal end
if anchor_lethal then score = score + cfg.score.anchor_lethal end
if damage_only and hits.target_hit then score = score + (anchor.kind == "tree" and 150 or 90) end
local vel, speed = helpers.movement_vector(target)
if speed > 40 then
local away = vel:Normalized():Dot2D(hero_pos:DirectionTo(predicted))
if away > 0.35 and fear_score > 0.35 then score = score + 90 end
end
return helpers.make_plan(hero, ability, target, anchor.entity, anchor_pos, dir, params, {
score = score,
hit_chance = hit_chance,
fear_score = fear_score,
travel_time = impact_time,
reason = anchor.kind .. (spirit_score > 0 and " spirit" or " bounce"),
first_time = first_time,
anchor_kind = anchor.kind,
anchor = anchor.entity,
fear_plan = fear_plan,
spirit_route = spirit_score > 0,
spirit_distance = spirit_distance,
bounce_dist = bounce_dist,
lethal = lethal,
anchor_lethal = anchor_lethal,
damage_only = damage_only,
vector = anchor.kind == "tree" and predicted or nil,
hits = hits,
primary_damage = damage,
anchor_damage = anchor_damage,
ricochet_length = ricochet_len,
})
end
function helpers.accept_plan(plan, manual)
local min_score = ui.min_score:Get()
local min_hit = ui.min_hit:Get() * 0.01
if manual then
min_score = min_score * 0.78
min_hit = math.max(0.25, min_hit - 0.12)
end
if plan.lethal or plan.anchor_lethal then
min_score = min_score * 0.65
min_hit = math.max(0.20, min_hit - 0.18)
end
if plan.damage_only then
min_score = min_score * 0.82
min_hit = math.max(0.30, min_hit - 0.10)
end
return plan.score >= min_score and plan.hit_chance >= min_hit
end
function helpers.ricochet_ok(plan, enemies, params)
if not ui.ricochet_only:Get() then return true end
local rest = {}
for _, enemy in ipairs(enemies) do
if enemy ~= plan.cast_entity then rest[#rest + 1] = enemy end
end
local hits = helpers.count_line_hits(rest, plan.target, plan.cast, plan.dir, plan.ricochet_length, plan.first_time or plan.travel_time or 0, params)
return hits.heroes > 0
end
function helpers.item_base(name)
return (name:gsub("^item_", ""):gsub("_custom$", ""))
end
function helpers.item_label(name)
return (helpers.item_base(name):gsub("_", " "))
end
function helpers.item_icon(name)
local base = helpers.item_base(name)
return "panorama/images/items/" .. (ICON_FIX[base] or base) .. "_png.vtex_c"
end
function helpers.item_skipped(name)
for _, fragment in ipairs(ITEM_SKIP) do
if name:find(fragment, 1, true) ~= nil then return true end
end
return false
end
function helpers.has(value, bit)
return type(value) == "number" and bit > 0 and math.floor(value / bit) % 2 >= 1
end
function helpers.item_kind(item)
local behavior = Ability.GetBehavior(item)
if helpers.has(behavior, cfg.b_passive) or helpers.has(behavior, cfg.b_hidden) or helpers.has(behavior, cfg.b_toggle) then return nil end
if helpers.has(behavior, cfg.b_unit) then
local team = Ability.GetTargetTeam(item)
if helpers.has(team, cfg.target_enemy) then return "enemy" end
if helpers.has(team, cfg.target_friendly) then return "self" end
return nil
end
if helpers.has(behavior, cfg.b_point) then return "point" end
if helpers.has(behavior, cfg.b_no) then return "no" end
return nil
end
function helpers.scan_items(hero)
local labels, ids, signature = {}, {}, ""
for _, slot in ipairs(cfg.item_slots) do
local item = NPC.GetItemByIndex(hero, slot)
if item ~= nil then
local name = Ability.GetName(item)
local label = helpers.item_label(name)
if not helpers.item_skipped(name) and helpers.item_kind(item) ~= nil and ids[label] == nil then
labels[#labels + 1] = label
ids[label] = name
signature = signature .. label .. "=" .. name .. ","
end
end
end
return labels, ids, signature
end
function helpers.refresh_items(hero)
IT.tick()
local labels, ids, signature = helpers.scan_items(hero)
if signature == state.item_sig then return end
local rank, old, enabled = {}, {}, {}
for i, id in ipairs(ui.items:List()) do
rank[id] = i
old[id] = true
end
for _, id in ipairs(ui.items:ListEnabled()) do enabled[id] = true end
table.sort(labels, function(a, b) return (rank[a] or 1000) < (rank[b] or 1000) end)
local rows, selected = {}, {}
for i, label in ipairs(labels) do
local on = not old[label] or enabled[label] == true
rows[i] = { label, helpers.item_icon(ids[label]), on }
if on then selected[#selected + 1] = label end
end
ui.items:Update(rows, true, true)
ui.items:Set(selected)
state.item_sig = signature
state.item_ids = ids
IT.sync(hero, labels, ids, helpers.item_icon)
helpers.log("muerta items refreshed", { items = labels, enabled = selected })
end
function helpers.find_item(hero, label, name)
for _, slot in ipairs(cfg.item_slots) do
local item = NPC.GetItemByIndex(hero, slot)
if item ~= nil and Ability.GetName(item) == name then return item end
end
for _, slot in ipairs(cfg.item_slots) do
local item = NPC.GetItemByIndex(hero, slot)
if item ~= nil and helpers.item_label(Ability.GetName(item)) == label then return item end
end
return nil
end
function helpers.is_jump(name)
return name:find("blink", 1, true) ~= nil or name:find("fallen_sky", 1, true) ~= nil
end
function helpers.item_ready(item, hero)
return item ~= nil and Ability.GetLevel(item) > 0 and Ability.IsCastable(item, NPC.GetMana(hero))
end
function helpers.clamp_point(hero, point, range)
if range <= 0 then return point end
local origin = Entity.GetAbsOrigin(hero)
local dx, dy = point.x - origin.x, point.y - origin.y
local length = math.sqrt(dx * dx + dy * dy)
local cap = math.max(0, range - 25)
if length <= cap or length <= 0 then return point end
local scale = cap / length
return Vector(origin.x + dx * scale, origin.y + dy * scale, point.z)
end
function helpers.combo_reach(hero, ability)
local reach = 0
if ability ~= nil then reach = Ability.GetCastRange(ability) end
for _, label in ipairs(ui.items:ListEnabled()) do
local name = state.item_ids[label]
local item = name ~= nil and not helpers.is_jump(name) and helpers.find_item(hero, label, name) or nil
if item ~= nil and helpers.item_ready(item, hero) then
local kind = helpers.item_kind(item)
if kind == "enemy" or kind == "point" then reach = math.max(reach, Ability.GetCastRange(item) + 75) end
end
end
return reach
end
function helpers.blink_point(hero, target)
local origin = Entity.GetAbsOrigin(hero)
local pos = Entity.GetAbsOrigin(target)
local dx, dy = pos.x - origin.x, pos.y - origin.y
local len = math.max(1, math.sqrt(dx * dx + dy * dy))
return Vector(pos.x - dx / len * cfg.blink_keep, pos.y - dy / len * cfg.blink_keep, pos.z)
end
function helpers.order_move(hero, point, now)
if now < state.move_at then return end
local player = Players.GetLocal()
if player == nil then return end
Player.PrepareUnitOrders(player, cfg.order_move, nil, point, nil, cfg.issuer_passed, hero, false, false, false, false, cfg.identifier)
state.move_at = now + cfg.move_gap
end
function helpers.is_meteor(name)
for _, fragment in ipairs(cfg.meteor_items) do
if name:find(fragment, 1, true) ~= nil then return true end
end
return false
end
function helpers.meteor_plan(target, now, strong_only)
local pos = Entity.GetAbsOrigin(target)
local fear = NPC.GetModifier(target, cfg.fear_mod)
if strong_only then
if fear == nil then return nil end
local full = Modifier.GetDuration(fear)
if (type(full) ~= "number" or full < cfg.strong_fear) and now >= state.strong_until then return nil end
end
if fear ~= nil then
local left = Modifier.GetDieTime(fear) - now
if type(left) == "number" and left > 0 then
local _, speed = helpers.movement_vector(target)
local free = math.max(0, cfg.meteor_delay - left)
if NPC.GetMoveSpeed(target) * free > cfg.meteor_radius - cfg.meteor_margin then return nil end
local vel = helpers.movement_vector(target)
if speed <= 10 then return pos end
return pos + vel:Normalized() * helpers.prediction_distance(target, math.min(left, cfg.meteor_delay), speed)
end
end
if helpers.is_disabled(target) and not strong_only then return pos end
return nil
end
function helpers.strong_meteor(name)
return name:find(cfg.strong_meteor, 1, true) ~= nil
end
function helpers.is_shiva(name)
return name:find("shivas_guard", 1, true) ~= nil or name:find("gold_shiva", 1, true) ~= nil
end
function helpers.is_hex(name)
return name:find("sheepstick", 1, true) ~= nil or name:find("hex", 1, true) ~= nil
end
function helpers.shiva_has_target(hero, item)
local radius = helpers.special(item, { "blast_radius" }, cfg.shiva_radius)
return #helpers.get_enemies(hero, radius) > 0
end
function helpers.use_items(hero, target, ability, now)
if now >= state.cycle_at then
state.done = {}
state.cycle_at = now + cfg.cycle_gap
end
local distance = Entity.GetAbsOrigin(hero):Distance2D(Entity.GetAbsOrigin(target))
for _, label in ipairs(ui.items:ListEnabled()) do
local name = state.item_ids[label]
if name ~= nil and not state.done[name] then
local item = helpers.find_item(hero, label, name)
if item == nil then
state.done[name] = true
elseif not IT.allow(hero, target, name, label) then
elseif helpers.item_ready(item, hero) then
local kind = helpers.item_kind(item)
local range = Ability.GetCastRange(item)
local jump = helpers.is_jump(name)
if kind == nil then
state.done[name] = true
elseif jump and distance <= helpers.combo_reach(hero, ability) then
elseif helpers.is_shiva(name) and not helpers.shiva_has_target(hero, item) then
elseif helpers.is_meteor(name) and helpers.meteor_plan(target, now, helpers.strong_meteor(name)) == nil then
elseif (kind == "enemy" or kind == "point") and not jump and range > 0 and distance > range + 75 then
helpers.order_move(hero, Entity.GetAbsOrigin(target), now)
return true
else
if kind == "enemy" then
Ability.CastTarget(item, target, false, false, true, cfg.identifier)
elseif kind == "self" then
Ability.CastTarget(item, hero, false, false, true, cfg.identifier)
elseif kind == "point" and helpers.is_meteor(name) then
local point = helpers.meteor_plan(target, now, helpers.strong_meteor(name))
local fear = NPC.GetModifier(target, cfg.fear_mod)
Ability.CastPosition(item, helpers.clamp_point(hero, point, range), false, false, true, cfg.identifier)
helpers.log("muerta meteor", {
fear_left = fear ~= nil and math.floor((Modifier.GetDieTime(fear) - now) * 100) / 100 or -1,
disabled = helpers.is_disabled(target),
lead = math.floor(point:Distance2D(Entity.GetAbsOrigin(target))),
speed = math.floor(NPC.GetMoveSpeed(target)),
})
elseif kind == "point" and jump then
Ability.CastPosition(item, helpers.clamp_point(hero, helpers.blink_point(hero, target), range), false, false, true, cfg.identifier)
elseif kind == "point" then
Ability.CastPosition(item, helpers.clamp_point(hero, Entity.GetAbsOrigin(target), range), false, false, true, cfg.identifier)
else
Ability.CastNoTarget(item, false, false, true, cfg.identifier)
end
state.done[name] = true
local delay = math.max(0.08, math.max(0, IT.castPoint(item)) + 0.06)
if kind == "enemy" and helpers.is_hex(name) then delay = math.max(delay, cfg.hex_wait) end
state.next_at = now + delay
IT.chainMark(hero, target, name)
helpers.log("muerta combo item", { item = name, kind = kind })
return true
end
end
end
end
return false
end
function helpers.feared_target(hero, preferred, now)
local function active(unit)
if unit == nil or not helpers.is_enemy_hero(unit) then return false end
local fear = NPC.GetModifier(unit, cfg.fear_mod)
return fear ~= nil and Modifier.GetDieTime(fear) > now
end
if active(preferred) then return preferred end
for _, enemy in ipairs(helpers.get_enemies(hero, cfg.item_search)) do
if active(enemy) then return enemy end
end
return nil
end
function helpers.active_calling_center()
for _, track in ipairs(state.calling_spirits) do
if track.center ~= nil then return track.center end
end
if #state.calling_spirits == 0 then return nil end
local center = Vector(0, 0, 0)
for _, track in ipairs(state.calling_spirits) do center = center + track.pos end
return center / #state.calling_spirits
end
function helpers.calling_enemy_inside(hero)
local center = helpers.active_calling_center()
if center == nil then return nil end
for _, enemy in ipairs(helpers.get_enemies(hero, cfg.calling_search)) do
if center:Distance2D(Entity.GetAbsOrigin(enemy)) <= cfg.calling_legendary_big_radius + NPC.GetHullRadius(enemy) then
return true
end
end
return false
end
function helpers.reset_calling_legendary_progress()
state.calling_w7_seen = 0
state.calling_w7_last = 0
state.calling_w7_progress = 0
state.calling_w7_estimate = 0
end
function helpers.calling_legendary_progress(hero, ability, modifier, now)
if modifier ~= nil then
local stacks = clamp(Modifier.GetStackCount(modifier), 0, cfg.calling_legendary_max)
state.calling_w7_seen = now
state.calling_w7_last = now
state.calling_w7_progress = 0
state.calling_w7_estimate = stacks
return stacks, math.max(0, Modifier.GetDieTime(modifier) - now), true
end
if state.calling_w7_seen <= 0 then
state.calling_w7_seen = now
state.calling_w7_last = now
state.calling_w7_estimate = 1
state.calling_w7_progress = 0
else
local elapsed = clamp(now - state.calling_w7_last, 0, 0.25)
state.calling_w7_last = now
if helpers.calling_enemy_inside(hero) ~= false then
state.calling_w7_progress = state.calling_w7_progress + elapsed
while state.calling_w7_progress >= cfg.calling_legendary_interval
and state.calling_w7_estimate < cfg.calling_legendary_max do
state.calling_w7_progress = state.calling_w7_progress - cfg.calling_legendary_interval
state.calling_w7_estimate = state.calling_w7_estimate + 1
end
end
end
local duration = helpers.special(ability, { "duration" }, 9)
local left = math.max(0, duration - 1 - (now - state.calling_w7_seen))
return state.calling_w7_estimate, left, false
end
function helpers.calling_release_target(hero, preferred, range)
local origin = Entity.GetAbsOrigin(hero)
local cap = math.max(0, range - 25)
if preferred ~= nil and helpers.is_enemy_hero(preferred)
and origin:Distance2D(Entity.GetAbsOrigin(preferred)) <= cap then
return preferred
end
local enemies = helpers.get_enemies(hero, math.max(cfg.calling_search, range + 100))
local best, best_score = nil, -math.huge
for _, enemy in ipairs(enemies) do
local pos = Entity.GetAbsOrigin(enemy)
local distance = origin:Distance2D(pos)
if distance <= cap then
local nearby = 0
for _, other in ipairs(enemies) do
if pos:Distance2D(Entity.GetAbsOrigin(other)) <= cfg.calling_legendary_impact_radius + NPC.GetHullRadius(other) then
nearby = nearby + 1
end
end
local score = nearby * 500 - distance * 0.04
if helpers.is_disabled(enemy) or NPC.GetModifier(enemy, cfg.fear_mod) ~= nil then score = score + 180 end
if score > best_score then
best, best_score = enemy, score
end
end
end
return best
end
function helpers.cast_calling_legendary(hero, preferred, now)
if not helpers.spell_enabled("w") then return false end
local ability = helpers.get_ability(hero, cfg.calling_names)
if ability == nil then return false end
local modifier = NPC.GetModifier(hero, cfg.calling_legendary_mod)
local behavior = Ability.GetBehavior(ability)
local unit_mode = helpers.has(behavior, cfg.b_unit) and not helpers.has(behavior, cfg.b_point)
if modifier == nil and not unit_mode then
helpers.reset_calling_legendary_progress()
return false
end
state.legendary_w = true
local stacks, left, exact = helpers.calling_legendary_progress(hero, ability, modifier, now)
local delay = math.max(0, IT.castPoint(ability)) + helpers.latency()
local release_at = clamp(ui.calling_release:Get(), 1, cfg.calling_legendary_max)
if stacks < release_at and left > delay + cfg.calling_legendary_release_buffer then
return false
end
if not helpers.ability_ready(ability, hero) then return false end
local range = Ability.GetCastRange(ability)
if range <= 0 then range = 1200 end
local target = helpers.calling_release_target(hero, preferred, range)
if target == nil and preferred ~= nil and helpers.is_enemy_hero(preferred) then
local distance = Entity.GetAbsOrigin(hero):Distance2D(Entity.GetAbsOrigin(preferred))
local missing = distance - math.max(0, range - 25)
if missing > 0 and missing <= cfg.calling_legendary_chase then
local walk = missing / math.max(1, NPC.GetMoveSpeed(hero))
if left > walk + delay + cfg.calling_legendary_release_buffer then
helpers.order_move(hero, Entity.GetAbsOrigin(preferred), now)
return true
end
end
return false
end
if target == nil or IT.spellBlocked(target, now, Ability.GetName(ability)) then return false end
Ability.CastTarget(ability, target, false, false, true, cfg.identifier)
state.next_at = now + math.max(0.08, math.max(0, IT.castPoint(ability)) + 0.06)
helpers.log("muerta calling legendary release", {
stacks = stacks,
release_at = release_at,
left = math.floor(left * 100) / 100,
exact = exact,
})
helpers.reset_calling_legendary_progress()
return true
end
function helpers.calling_center(hero, target, ability, delay, legendary)
local impact = helpers.predict_pos(target, delay)
local radius = legendary and cfg.calling_legendary_small_radius
or helpers.special(ability, { "radius" }, cfg.calling_radius)
local hit = helpers.special(ability, { "hit_radius" }, cfg.calling_hit_radius)
local ring = math.max(0, radius - hit)
local range = Ability.GetCastRange(ability)
local origin = Entity.GetAbsOrigin(hero)
local offsets = {
Vector(ring, 0, 0), Vector(-ring, 0, 0), Vector(0, ring, 0), Vector(0, -ring, 0),
}
local best, best_distance = nil, math.huge
for _, offset in ipairs(offsets) do
local center = impact - offset
local distance = origin:Distance2D(center)
if distance <= math.max(0, range - 25) and distance < best_distance then
best, best_distance = center, distance
end
end
return best
end
function helpers.cast_calling(hero, preferred, now)
if not helpers.spell_enabled("w") then return false end
local ability = helpers.get_ability(hero, cfg.calling_names)
if not helpers.ability_ready(ability, hero) then return false end
local behavior = Ability.GetBehavior(ability)
if helpers.has(behavior, cfg.b_autocast) then state.legendary_w = true end
if helpers.has(behavior, cfg.b_unit) and not helpers.has(behavior, cfg.b_point) then return false end
if helpers.has(behavior, cfg.b_point) and #state.calling_spirits > 0 then return false end
local target = helpers.feared_target(hero, preferred, now)
local timed = target ~= nil
if target == nil and state.legendary_w and preferred ~= nil and helpers.is_enemy_hero(preferred) then
target = preferred
end
if target == nil then return false end
local fear = timed and NPC.GetModifier(target, cfg.fear_mod) or nil
local left = fear ~= nil and Modifier.GetDieTime(fear) - now or 0
local delay = math.max(0, IT.castPoint(ability)) + helpers.latency()
local center = nil
if helpers.has(behavior, cfg.b_point) then
center = helpers.calling_center(hero, target, ability, delay, state.legendary_w)
if center == nil then return false end
elseif not helpers.has(behavior, cfg.b_unit) then
return false
end
if timed and left > delay + cfg.calling_timing then return false, true end
if helpers.has(behavior, cfg.b_unit) then
if IT.spellBlocked(target, now, Ability.GetName(ability)) then return false end
Ability.CastTarget(ability, target, false, false, true, cfg.identifier)
else
Ability.CastPosition(ability, center, false, false, true, cfg.identifier)
end
state.next_at = now + math.max(0.08, math.max(0, IT.castPoint(ability)) + 0.06)
helpers.log("muerta calling cast", {
mode = timed and "fear" or "legendary zone",
fear_left = timed and math.floor(left * 100) / 100 or -1,
})
return true, false
end
function helpers.cast_veil(hero, target, now)
if target == nil or not helpers.spell_enabled("r") then return false end
if NPC.GetModifier(hero, cfg.veil_mod) ~= nil then return false end
local ability = helpers.get_ability(hero, cfg.veil_names)
if not helpers.ability_ready(ability, hero) then return false end
local range = NPC.GetAttackRange(hero) + NPC.GetAttackRangeBonus(hero) + cfg.veil_buffer
if Entity.GetAbsOrigin(hero):Distance2D(Entity.GetAbsOrigin(target)) > range then return false end
Ability.CastNoTarget(ability, false, false, true, cfg.identifier)
state.next_at = now + math.max(0.08, math.max(0, IT.castPoint(ability)) + 0.06)
helpers.log("muerta veil cast", { distance = math.floor(Entity.GetAbsOrigin(hero):Distance2D(Entity.GetAbsOrigin(target))) })
return true
end
function helpers.cast_gunslinger(hero, target, now)
if target == nil or not helpers.spell_enabled("e") then return false end
local ability = NPC.GetAbility(hero, cfg.gun_name)
if ability == nil or Ability.IsHidden(ability) or not helpers.ability_ready(ability, hero) then return false end
local behavior = Ability.GetBehavior(ability)
if helpers.has(behavior, cfg.b_passive) or not helpers.has(behavior, cfg.b_point) then return false end
local dash = Ability.GetCastRange(ability)
if dash <= 0 then return false end
local reach = NPC.GetAttackRange(hero) + NPC.GetAttackRangeBonus(hero)
local origin, goal = Entity.GetAbsOrigin(hero), Entity.GetAbsOrigin(target)
local distance = origin:Distance2D(goal)
if distance <= reach or math.abs(dash - distance) > reach * 0.9 then return false end
Ability.CastPosition(ability, goal, false, false, true, cfg.identifier)
state.next_at = now + math.max(0.08, math.max(0, IT.castPoint(ability)) + 0.06)
helpers.log("muerta gunslinger cast", { distance = math.floor(distance), dash = math.floor(dash) })
return true
end
function helpers.veil_attack(hero, target, now)
if target == nil or not helpers.is_enemy_hero(target) then return false end
local reach = NPC.GetAttackRange(hero) + NPC.GetAttackRangeBonus(hero) + NPC.GetHullRadius(hero) + NPC.GetHullRadius(target)
if Entity.GetAbsOrigin(hero):Distance2D(Entity.GetAbsOrigin(target)) > reach then return false end
local target_id = Entity.GetIndex(target)
local changed = state.veil_attack_target ~= target_id
if changed or (now >= state.veil_attack_at and not NPC.IsAttacking(hero) and not NPC.IsTurning(hero)) then
local player = Players.GetLocal()
if player ~= nil then
Player.AttackTarget(player, hero, target, false, false, true, cfg.identifier)
state.veil_attack_at = now + cfg.veil_attack_gap
state.veil_attack_target = target_id
if changed then helpers.log("muerta veil attack", { target = Entity.GetUnitName(target) }) end
end
end
return true
end
function helpers.get_proc(hero)
local proc = NPC.GetAbility(hero, cfg.proc_name)
if proc == nil or Ability.IsHidden(proc) then return nil end
return proc
end
function helpers.cast_legendary(hero, proc, preferred, now)
if now - state.last_cast < 0.28 then return false end
local base = NPC.GetAbility(hero, cfg.ability_names[1])
if base == nil then return false end
local params = helpers.get_params(hero, base)
local speed = params.speed * cfg.proc_speed
local length = params.ricochet
local w0 = params.radius
local w1 = w0 * cfg.proc_width
local origin = helpers.caster_position(hero, params)
local lead = math.max(0, IT.castPoint(proc)) + params.latency
local enemies = helpers.get_enemies(hero, length + w1 + 300)
local targets = {}
if preferred and helpers.is_enemy_hero(preferred) then targets[1] = preferred end
for _, enemy in ipairs(enemies) do
if enemy ~= preferred then targets[#targets + 1] = enemy end
end
local best, best_score, best_hits = nil, -math.huge, 0
for _, target in ipairs(targets) do
local predicted, impact = helpers.predict_intercept(target, origin, lead, speed, length)
local reach = origin:Distance2D(predicted)
if reach > 1 and reach <= length + NPC.GetHullRadius(target) then
local dir = origin:DirectionTo(predicted)
local tip = origin:Extrapolate(dir, length)
local hits = 0
for _, enemy in ipairs(enemies) do
local p = helpers.predict_intercept(enemy, origin, lead, speed, length)
local distance, t = helpers.point_segment_distance(origin, tip, p)
if distance <= w0 + (w1 - w0) * t + NPC.GetHullRadius(enemy) then hits = hits + 1 end
end
local spirit_score = helpers.spirit_route(target, predicted, dir, impact, cfg.proc_fear_duration, true)
local score = hits * 100 - impact * 20 + spirit_score
if target == preferred then score = score + 150 end
if hits > 0 and score > best_score then
best, best_score, best_hits = predicted, score, hits
end
end
end
if best == nil then return false end
Ability.CastPosition(proc, best, false, false, true, cfg.identifier)
state.last_cast = now
state.strong_until = now + cfg.strong_window
helpers.log("muerta legendary shot cast", { heroes = best_hits, dist = math.floor(origin:Distance2D(best)) })
return true
end
function helpers.select_best_plan(hero, ability, preferred, manual)
local params = helpers.get_params(hero, ability)
local enemies = helpers.get_enemies(hero, cfg.search_radius)
local targets = {}
if preferred and helpers.is_enemy_hero(preferred) then
targets[1] = preferred
end
for _, enemy in ipairs(enemies) do
if enemy ~= preferred then targets[#targets + 1] = enemy end
end
while #targets > ui.max_targets:Get() do table.remove(targets) end
local anchors = helpers.build_anchors(hero, enemies, params)
local plans = {}
local best = nil
for _, target in ipairs(targets) do
local direct = helpers.evaluate_direct(hero, ability, target, enemies, params)
if direct and not helpers.ricochet_ok(direct, enemies, params) then direct = nil end
if direct then
if manual and preferred and target == preferred then
if direct.lethal and direct.hit_chance >= 0.70 then
direct.score = direct.score + 360
elseif direct.hit_chance >= 0.82 and direct.hits and direct.hits.heroes >= 2 then
direct.score = direct.score + 180
end
direct.manual_primary = true
end
plans[#plans + 1] = direct
if not best or direct.score > best.score then best = direct end
end
for _, anchor in ipairs(anchors) do
local plan = helpers.evaluate_anchor(hero, ability, target, anchor, enemies, params)
if plan and not helpers.ricochet_ok(plan, enemies, params) then plan = nil end
if plan then
if manual and preferred and target == preferred then
if plan.lethal and plan.hit_chance >= 0.68 then
plan.score = plan.score + 260
elseif plan.hit_chance >= 0.82 and plan.hits and plan.hits.heroes >= 2 then
plan.score = plan.score + 120
end
plan.manual_primary = true
end
plans[#plans + 1] = plan
if not best or plan.score > best.score then best = plan end
end
end
end
table.sort(plans, function(a, b) return a.score > b.score end)
while #plans > 8 do table.remove(plans) end
return best, plans
end
function helpers.cast_plan(plan)
local now = GameRules.GetGameTime()
if now - state.last_cast < 0.28 then return false end
local player = Players.GetLocal()
if player == nil then return false end
if plan.anchor_kind == "tree" then
Player.PrepareUnitOrders(player, cfg.order_vector, nil, plan.vector, plan.ability, cfg.issuer_selected, nil, false, true, false, false, cfg.identifier)
Player.PrepareUnitOrders(player, cfg.order_cast_target_tree, plan.cast_entity, Vector(0, 0, 0), plan.ability, cfg.issuer_selected, nil, false, true, false, false, cfg.identifier)
else
Player.PrepareUnitOrders(player, cfg.order_vector, plan.cast_entity, plan.vector, plan.ability, cfg.issuer_passed, plan.hero, false, true, false, false, cfg.identifier)
Player.PrepareUnitOrders(player, cfg.order_cast_target, plan.cast_entity, Vector(0, 0, 0), plan.ability, cfg.issuer_passed, plan.hero, false, true, false, false, cfg.identifier)
end
state.last_cast = now
local data = {
reason = plan.reason,
score = math.floor(plan.score),
hit = math.floor(plan.hit_chance * 100),
fear = math.floor(math.max(0, plan.fear_score) * 100),
spirit = plan.spirit_route == true,
}
if ui.debug_log:Get() or state.last_reason ~= plan.reason then
state.last_reason = plan.reason
helpers.log("muerta dead shot cast", data)
end
return true
end
function helpers.draw_world_line(from, to, color, thickness)
local a_pos, a_visible = Render.WorldToScreen(from)
local b_pos, b_visible = Render.WorldToScreen(to)
if a_visible and b_visible then Render.Line(a_pos, b_pos, color, thickness or 1) end
end
function helpers.draw_world_circle(pos, radius, color)
local screen, visible = Render.WorldToScreen(pos)
if visible then Render.Circle(screen, radius, color) end
end
function helpers.draw_text(pos, text, color)
local screen, visible = Render.WorldToScreen(pos + Vector(0, 0, 120))
if not visible then return end
Render.Text(render_ctx.font, 13, text, Vec2(screen.x + 1, screen.y + 1), cfg.visual.shadow)
Render.Text(render_ctx.font, 13, text, screen, color or cfg.visual.text)
end
function helpers.draw_plan(plan, index)
helpers.draw_world_line(plan.hero_pos, plan.cast, cfg.visual.first, index and 1 or 2)
helpers.draw_world_line(plan.cast, plan.end_pos, cfg.visual.ricochet, index and 1 or 2.5)
helpers.draw_world_circle(plan.cast, index and 4 or 7, cfg.visual.ricochet)
helpers.draw_world_circle(Entity.GetAbsOrigin(plan.target), index and 4 or 6, plan.hit_chance >= ui.min_hit:Get() * 0.01 and cfg.visual.good or cfg.visual.bad)
if not index then
helpers.draw_text(plan.cast, string.format(
"%s | %d score | %d%% hit | %d%% fear",
plan.reason,
math.floor(plan.score),
math.floor(plan.hit_chance * 100),
math.floor(math.max(0, plan.fear_score) * 100)
), cfg.visual.text)
end
end
function helpers.draw_error()
local title = state.menu_error and localization.Get("panel.menu_failed") or localization.Get("panel.error")
local message = state.menu_error or state.error or state.item_error or "unknown"
Render.FilledRect(Vec2(20, 370), Vec2(780, 418), Color(20, 20, 24, 235), 4)
Render.Text(render_ctx.font, 14, title, Vec2(30, 377), Color(224, 50, 45, 245))
Render.Text(render_ctx.font, 12, message:sub(1, 160), Vec2(30, 397), Color(220, 220, 225, 240))
end
function helpers.run()
if not ui.enable:Get() then
helpers.reset_runtime()
return
end
state.hero = Heroes.GetLocal()
if not helpers.is_local_muerta(state.hero) or not Entity.IsAlive(state.hero) then
helpers.reset_runtime()
return
end
helpers.update_enemy_track(state.hero)
local clock = GameRules.GetGameTime()
helpers.update_calling_spirits(state.hero, clock)
if not state.legendary_q and NPC.GetModifier(state.hero, cfg.dead_legendary_stack) ~= nil then
state.legendary_q = true
end
if clock >= state.item_at and state.item_error == nil then
state.item_at = clock + cfg.item_gap
local ok, err = pcall(helpers.refresh_items, state.hero)
if not ok then
state.item_error = tostring(err)
helpers.log("muerta items refresh failed", { error = state.item_error })
end
end
local manual = ui.key:IsDown()
if not manual then
helpers.reset_runtime()
return
end
if cfg.input_captured ~= nil and cfg.input_captured() then return end
local now = GameRules.GetGameTime()
if now < state.last_think + ui.think_ms:Get() * 0.001 then return end
state.last_think = now
local ability = helpers.get_dead_shot(state.hero)
if ability and Ability.IsInAbilityPhase(ability) then return end
local proc = helpers.get_proc(state.hero)
if proc and Ability.IsInAbilityPhase(proc) then return end
if now < state.next_at or NPC.IsChannellingAbility(state.hero) or NPC.HasModifier(state.hero, "modifier_item_meteor_hammer_custom_cast") or IT.heroDisabled(state.hero) or not order_safe() then return end
local preferred = nil
if ui.target_mode:Get() == cfg.mode.cursor then
preferred = helpers.get_cursor_target(state.hero, cfg.search_radius)
end
local item_target = preferred or helpers.get_enemies(state.hero, cfg.item_search)[1]
if item_target ~= nil and IT.breakLinken(state.hero, item_target, now) then return end
if item_target ~= nil then local mw = IT.meteorCast(state.hero, item_target, now, cfg.identifier) if mw ~= nil then state.next_at = now + mw return end end
if helpers.cast_calling_legendary(state.hero, preferred or item_target, now) then return end
local calling_cast, calling_wait = helpers.cast_calling(state.hero, preferred or item_target, now)
if calling_cast then return end
if calling_wait then
helpers.veil_attack(state.hero, preferred or item_target, now)
return
end
if helpers.cast_veil(state.hero, item_target, now) then return end
if helpers.cast_gunslinger(state.hero, preferred or item_target, now) then return end
if item_target ~= nil and helpers.use_items(state.hero, item_target, ability or proc, now) then return end
if helpers.spell_enabled("q") and proc and Ability.IsCastable(proc, NPC.GetMana(state.hero)) then
state.best_plan = nil
state.plans = {}
if helpers.cast_legendary(state.hero, proc, preferred, now) then return end
end
if not helpers.spell_enabled("q") or not ability or not Ability.IsCastable(ability, NPC.GetMana(state.hero)) then
helpers.veil_attack(state.hero, item_target, now)
return
end
local best, plans = helpers.select_best_plan(state.hero, ability, preferred, manual)
state.best_plan = best
state.plans = plans
if best and helpers.accept_plan(best, manual) then
if helpers.cast_plan(best) then return end
end
local q_target = preferred or (best and best.target) or item_target
if q_target ~= nil and helpers.is_enemy_hero(q_target) then
local range = Ability.GetCastRange(ability) + NPC.GetHullRadius(q_target)
if Entity.GetAbsOrigin(state.hero):Distance2D(Entity.GetAbsOrigin(q_target)) > range then
helpers.order_move(state.hero, helpers.clamp_point(state.hero, Entity.GetAbsOrigin(q_target), Entity.GetAbsOrigin(state.hero):Distance2D(Entity.GetAbsOrigin(q_target)) - range + 50), now)
end
return
end
helpers.veil_attack(state.hero, q_target, now)
end
function script.OnScriptsLoaded()
local ok, result = pcall(helpers.build_menu)
state.ready = ok and result == true
if not state.ready then state.menu_error = ok and "build_menu returned false" or tostring(result) end
render_ctx.font = Render.LoadFont("Tahoma", cfg.font_flag)
helpers.log("muerta_1x6_combo loaded", { ready = state.ready, error = state.menu_error })
end
function script.OnUpdate()
if not state.ready or not Engine.IsInGame() then return end
local ok, err = pcall(helpers.run)
if not ok then
if state.error == nil then helpers.log("muerta combo update failed", { error = tostring(err) }) end
state.error = tostring(err)
helpers.reset_runtime()
end
end
function helpers.drawFrame()
if state.menu_error ~= nil or state.error ~= nil or state.item_error ~= nil then helpers.draw_error() end
if not state.ready or not ui.enable:Get() then return end
if not helpers.is_local_muerta(Heroes.GetLocal()) then return end
if ui.draw_candidates:Get() then
for i, plan in ipairs(state.plans) do
helpers.draw_plan(plan, i)
end
end
if ui.draw_best:Get() and state.best_plan then
helpers.draw_plan(state.best_plan)
end
end
function script.OnDraw()
local ok, err = pcall(helpers.drawFrame)
if not ok and state.error == nil then
state.error = tostring(err)
helpers.log("muerta combo draw failed", { error = state.error })
end
end
function script.OnGameEnd()
IT.reset()
state.enemy_track = {}
state.best_plan = nil
state.plans = {}
state.last_think = 0
state.last_cast = 0
state.error = nil
state.item_error = nil
state.item_sig = ""
state.item_ids = {}
state.item_at = 0
state.done = {}
state.veil_attack_at = 0
state.veil_attack_target = nil
state.calling_spirits = {}
state.spirit_track = {}
state.spirit_scan_at = 0
state.legendary_q = false
state.legendary_w = false
helpers.reset_calling_legendary_progress()
end
return script
end)
