for _, raze in ipairs(RAZES) do
local ability = A.razeAbility(hero, raze)
if ability ~= nil and UI.razes:Get(raze.key) and Ability.GetLevel(ability) > 0 and not Ability.IsHidden(ability) then
local cd = Ability.GetCooldown(ability)
if cd > 0 and cd <= C.razePrep and cd < left and Ability.GetManaCost(ability) <= mana then
soon, left = { ability = ability, range = A.razeRange(ability, raze.range) }, cd
end
end
end
if soon == nil then
A.razePlan("none", NPC.GetMana(hero))
return false
end
local origin = Entity.GetAbsOrigin(hero)
local goal = A.razeGoal(target, soon.ability)
local dx, dy = goal.x - origin.x, goal.y - origin.y
local dist = math.max(1, math.sqrt(dx * dx + dy * dy))
if math.abs(dist - soon.range) <= C.razeRadius - C.razeMargin then
S.stand = nil
A.idle(hero)
return true
end
A.razePlan("prep:" .. Ability.GetName(soon.ability), dist)
S.idleStop = false
