for _, raze in ipairs(RAZES) do
local ability = A.razeAbility(hero, raze)
if ability ~= nil and UI.razes:Get(raze.key) and A.ready(ability, hero) then
ready[#ready + 1] = { ability = ability, range = A.razeRange(ability, raze.range) }
end
end
if #ready == 0 then return A.razePrep(hero, target, now) end
local origin = Entity.GetAbsOrigin(hero)
local goal = A.razeGoal(target, ready[1].ability)
local dx, dy = goal.x - origin.x, goal.y - origin.y
local dist = math.sqrt(dx * dx + dy * dy)
if dist < 1 then dist, dx, dy = 1, 1, 0 end
local ux, uy = dx / dist, dy / dist
local pick = ready[1]
for _, entry in ipairs(ready) do
if math.abs(dist - entry.range) < math.abs(dist - pick.range) then pick = entry end
end
local band = C.razeRadius - C.razeMargin
local off = math.abs(dist - pick.range)
if off > band then
local walk = pick.range + (dist < pick.range and C.overshoot or -C.overshoot)
local stand = Vector(goal.x - ux * walk, goal.y - uy * walk, origin.z)
if off > C.razeRadius - C.razeHitMargin then
A.razePlan("walk:" .. Ability.GetName(pick.ability), dist)
