end
band = C.razeRadius - C.razeHitMargin
end
local forward = C.getRotation ~= nil and C.getRotation(hero):GetForward() or nil
local flat = forward ~= nil and math.sqrt(forward.x * forward.x + forward.y * forward.y) or 0
local along, lateral = dist, 0
if flat > 0.01 then
local fx, fy = forward.x / flat, forward.y / flat
along = dx * fx + dy * fy
lateral = math.abs(dx * fy - dy * fx)
end
local aligned = now >= S.castLock and lateral <= band and math.abs(along - pick.range) <= band
if aligned or (S.aimAt ~= nil and now >= S.aimAt + A.settle()) then
S.aimAt = nil
Ability.CastNoTarget(pick.ability, false, false, true, C.identifier)
S.nextAt = now + A.castDelay(pick.ability)
S.stand = nil
S.plan = nil
A.log("info", "sf raze cast", { raze = Ability.GetName(pick.ability), dist = math.floor(dist), along = math.floor(along), lateral = math.floor(lateral) })
