if rest > left then left = rest end
if word == "cyclone" or word == "wind_waker" then cyclone = true end
disabled = true
end
end
end
if not disabled then return 0, false end
return left, cyclone
end
function A.requiemCast(hero, ability, goal, dist, now, mode)
