local stack = NPC.GetModifier(hero, C.requiemStack)
local count = stack ~= nil and Modifier.GetStackCount(stack) or 0
if not S.legendR then
elseif count < UI.requiemStacks:Get() then
A.requiemWait("stacks", count)
return false
else
