end
local reach = blink + C.requiemReach
if cyclone then
if dist <= reach and left <= cast and left >= cast - C.cycloneEarly then return A.requiemCast(hero, ability, goal, dist, now, "cyclone") end
elseif left >= cast then
if dist <= reach then return A.requiemCast(hero, ability, goal, dist, now, "disable") end
end
local speed = NPC.GetMoveSpeed(hero)
if dist > reach and type(speed) == "number" and speed > 0 and left >= cast + (dist - reach) / speed then
