if not UI.enabled:Get() then
if S.phase ~= "idle" then A.reset("disabled") end
return
end
if not UI.key:IsDown() then
if S.phase ~= "idle" then A.reset("key released") end
return
end
if S.manual then
S.phase = "manual"
return
end
