local forward = C.getRotation(hero):GetForward()
local flat = math.sqrt(forward.x * forward.x + forward.y * forward.y)
if flat < 0.01 then return end
for _, raze in ipairs(RAZES) do
local ability = A.razeAbility(hero, raze)
if ability ~= nil and Ability.GetLevel(ability) > 0 then
local range = A.razeRange(ability, raze.range)
local radius = Ability.GetLevelSpecialValueFor(ability, "shadowraze_radius", -1)
if type(radius) ~= "number" or radius <= 0 then radius = C.razeRadius end
local center = Vector(origin.x + forward.x / flat * range, origin.y + forward.y / flat * range, origin.z)
local seen = S.razeSeen[raze.key]
if seen == nil then
seen = { at = -1, hit = false }
S.razeSeen[raze.key] = seen
end
