local function api(tbl, name)
return type(tbl) == "table" and type(tbl[name]) == "function" and tbl[name] or nil
end
local function order_safe()
local f = api(Humanizer, "IsSafeToCastOrder")
if f == nil then return true end
local ok, safe = pcall(f)
return not ok or safe ~= false
end
local function enum_value(group, key, fallback)
local e = type(Enum) == "table" and Enum[group] or nil
if type(e) == "table" and type(e[key]) == "number" then return e[key] end
return fallback
end
local HAS_ENUM = type(Enum) == "table"
local CAST_READY = HAS_ENUM and type(Enum.AbilityCastResult) == "table" and Enum.AbilityCastResult.READY or -1
local TEAM_ENEMY = enum_value("TeamType", "TEAM_ENEMY", 0)
local TEAM_BOTH = enum_value("TeamType", "TEAM_BOTH", 2)
local KEY_G = enum_value("ButtonCode", "KEY_G", 17)
local ORDER_ATTACK_MOVE = enum_value("UnitOrder", "DOTA_UNIT_ORDER_ATTACK_MOVE", 3)
local ISSUER_PASSED = enum_value("PlayerOrderIssuer", "DOTA_ORDER_ISSUER_PASSED_UNIT_ONLY", 3)
local POINT_VISIBLE = api(FogOfWar, "IsPointVisible")
local TRAVERSABLE = api(GridNav, "IsTraversable")
local ui = {}
local ready = false
local g_menu_error = nil
local S = {
on = false, keyDown = false, phase = "idle", camp = nil, camps = nil, cleared = {},
nextOrder = 0, moveAt = 0, jumpAt = 0, phaseAt = 0, rearmAt = 0, waitAt = 0, channelled = false,
rearmTries = 0, rearmBlock = 0, knockUntil = 0, fleeing = false, dustedCamp = nil, dustFired = false, fleeJumpAt = 0,
lastPos = nil, lastMoveAt = 0, dustWalk = 0, threatPos = nil, threatUntil = 0, heroPos = nil,
homeAt = 0, homeTries = 0, homeSeen = false, baseBlock = 0, fromBase = false,
pauseUntil = 0, selfOrderAt = 0, refreshAt = 0, done = {}, sig = "", seen = {}, ids = {},
typesLogged = false, error = nil, refreshError = nil, font = nil,
}
local function log(level, message, data)
if type(ai_bridge) ~= "table" or type(ai_bridge.mcp_log) ~= "function" then return end
pcall(ai_bridge.mcp_log, level, message, data)
end
local function initialize_menu()
local side = (HAS_ENUM and Enum.GroupSide) or {}
local rawSection = RawMenu.Create("Heroes", "Hero List", "Tinker", "Autofarm")
local section = localization.Wrap(rawSection, true)
local group = section:Create("menu.main", side.Left)
ui.enabled = group:Switch("menu.enabled", true, "\u{f0e7}")
ui.key = group:Bind("menu.key", KEY_G, "panorama/images/spellicons/tinker_march_of_the_machines_png.vtex_c")
ui.key:ToolTip("menu.key_tip")
ui.tier = group:Combo("menu.tier", { "menu.tier_easy", "menu.tier_medium", "menu.tier_hard", "menu.tier_ancient" }, 2)
ui.tier:ToolTip("menu.tier_tip")
ui.dust = group:Switch("menu.dust", true, "\u{f0e7}")
ui.dust:ToolTip("menu.dust_tip")
ui.danger = group:Slider("menu.danger", 600, 2500, 1400, "%d")
ui.danger:ToolTip("menu.danger_tip")
ui.mana = group:Slider("menu.mana", 0, 90, 15, "%d%%")
ui.mana:ToolTip("menu.mana_tip")
local rawGear = rawSection:Create("menu.items", side.Right)
localization.Register(rawGear, "menu.hidden")
local gear = localization.Wrap(rawGear, true)
ui.items = gear:MultiSelect("menu.items", {}, true)
ui.items:ToolTip("menu.items_tip")
ui.items:DragAllowed(true)
return true
end
local function next_spawn(now)
local t = GameRules.GetDOTATime(false, false)
if type(t) ~= "number" then return now + 30 end
return now + (60 - t % 60) + SPAWN_SLACK
end
local function stop(reason)
if S.on then log("info", "farm stopped", { reason = reason, camps_cleared = 0 }) end
S.on = false
S.phase = "idle"
S.camp = nil
S.done = {}
S.channelled = false
S.waitAt = 0
S.fleeJumpAt = 0
S.fromBase = false
S.zone = nil
end
local function set_phase(now, phase)
S.phase = phase
S.phaseAt = now
end
local function castable(h)
return h ~= nil and Ability.GetLevel(h) > 0 and Ability.IsReady(h) and Ability.CanBeExecuted(h) == CAST_READY
end
local function has_bit(mask, bit)
return type(mask) == "number" and mask % (bit * 2) >= bit
end
local function item_kind(h)
local b = Ability.GetBehavior(h)
if has_bit(b, B_PASSIVE) or has_bit(b, B_HIDDEN) or has_bit(b, B_TOGGLE) then return nil end
if has_bit(b, B_UNIT) then
local team = Ability.GetTargetTeam(h)
if has_bit(team, TEAM_BIT_ENEMY) then return "enemy" end
if has_bit(team, TEAM_BIT_FRIENDLY) then return "self" end
return nil
end
if has_bit(b, B_POINT) then return "point" end
if has_bit(b, B_NO_TARGET) then return "no" end
return nil
end
local function item_skipped(name)
for _, frag in ipairs(ITEM_SKIP) do
if name:find(frag, 1, true) ~= nil then return true end
end
return false
end
local function item_base(name)
return (name:gsub("^item_", ""):gsub("_custom$", ""))
end
local function item_label(name)
return (item_base(name):gsub("_", " "))
end
local function item_icon(name)
local fix = ICON_FIX[item_base(name)]
if fix ~= nil and fix:find("^panorama/") ~= nil then return fix end
return "panorama/images/items/" .. (fix or item_base(name)) .. "_png.vtex_c"
end
local function is_tp(name)
return name:find("tpscroll", 1, true) ~= nil
end
local function is_blink(name)
return name:find("blink", 1, true) ~= nil
end
local function is_shiva(name)
return name:find("shiva", 1, true) ~= nil
end
local function is_jump(name)
return is_blink(name) or is_tp(name) or name == FALLEN_SKY
end
local function scepter_tp(hero, h)
if h == nil or not NPC.HasScepter(hero) then return false end
if not has_bit(Ability.GetBehavior(h), B_POINT) then return false end
local range = Ability.GetCastRange(h)
return range > 0 and range <= TP_MAX
end
local function find_item(hero, name)
local h = NPC.GetItem(hero, name, true)
if h ~= nil then return h end
for _, slot in ipairs(SCAN_SLOTS) do
local it = NPC.GetItemByIndex(hero, slot)
if it ~= nil and Ability.GetName(it) == name then return it end
end
return nil
end
local function scan_items(hero)
local labels, ids, sig = {}, {}, ""
for _, slot in ipairs(SCAN_SLOTS) do
local h = NPC.GetItemByIndex(hero, slot)
if h ~= nil then
local name = Ability.GetName(h)
local keep
if is_tp(name) then
keep = scepter_tp(hero, h)
elseif name == FALLEN_SKY then
keep = item_kind(h) ~= nil
elseif slot <= ITEM_SLOTS then
keep = not item_skipped(name) and item_kind(h) ~= nil
else
keep = false
end
local label = item_label(name)
if keep and ids[label] == nil then
labels[#labels + 1] = label
ids[label] = name
sig = sig .. label .. ","
end
end
end
return labels, ids, sig
end
local function refresh_items(hero)
local labels, ids, sig = scan_items(hero)
if sig == S.sig then return end
local rank = {}
for i, id in ipairs(ui.items:List()) do rank[id] = i end
table.sort(labels, function(a, b) return (rank[a] or 1000) < (rank[b] or 1000) end)
local rows = {}
for i, label in ipairs(labels) do
local on = true
if S.seen[label] then on = ui.items:Get(label) == true end
rows[i] = { label, item_icon(ids[label]), on }
end
ui.items:Update(rows, true, true)
S.sig, S.ids = sig, ids
for _, label in ipairs(labels) do S.seen[label] = true end
log("info", "items refreshed", { items = labels })
end
local function build_camps()
if S.camps ~= nil and #S.camps > 0 then return S.camps end
local list, types = {}, {}
for _, handle in pairs(Camps.GetAll()) do
local box = Camp.GetCampBox(handle)
if box ~= nil and box.min ~= nil and box.max ~= nil then
local pos = Vector((box.min.x + box.max.x) * 0.5, (box.min.y + box.max.y) * 0.5, (box.min.z + box.max.z) * 0.5)
local extent = math.max(math.abs(box.max.x - box.min.x), math.abs(box.max.y - box.min.y)) * 0.5
local kind = Camp.GetType(handle)
local idx = #list + 1
list[idx] = { pos = pos, radius = math.max(CAMP_INSIDE, extent + 150), kind = kind, index = idx }
types[tostring(kind)] = (types[tostring(kind)] or 0) + 1
end
end
local clustered, blocked = 0, 0
for _, camp in ipairs(list) do
local sx, sy, n = camp.pos.x, camp.pos.y, 1
for _, other in ipairs(list) do
if other ~= camp and n < CLUSTER_MAX and (other.pos - camp.pos):Length2D() <= CLUSTER_RADIUS then
sx, sy, n = sx + other.pos.x, sy + other.pos.y, n + 1
end
end
camp.mates = n - 1
camp.gather = camp.pos
if n > 1 then
local mid = Vector(sx / n, sy / n, camp.pos.z)
if TRAVERSABLE == nil or TRAVERSABLE(mid) then
clustered = clustered + 1
camp.gather = mid
else
blocked = blocked + 1
end
end
end
local pairs_found = 0
for _, camp in ipairs(list) do
local mate, mateDist = nil, nil
for _, other in ipairs(list) do
local d = (other.pos - camp.pos):Length2D()
if other ~= camp and d <= MARCH_PAIR and (mateDist == nil or d < mateDist) then mate, mateDist = other, d end
end
if mate ~= nil then
local aim = Vector((camp.pos.x + mate.pos.x) / 2, (camp.pos.y + mate.pos.y) / 2, camp.pos.z)
local ux, uy = (mate.pos.x - camp.pos.x) / mateDist, (mate.pos.y - camp.pos.y) / mateDist
local stands = {}
for _, sign in ipairs({ 1, -1 }) do
local st = Vector(aim.x - ux * MARCH_STAND * sign, aim.y - uy * MARCH_STAND * sign, camp.pos.z)
if TRAVERSABLE == nil or TRAVERSABLE(st) then stands[#stands + 1] = st end
end
if #stands > 0 then
camp.march = { aim = aim, stands = stands, mate = mate.index }
pairs_found = pairs_found + 1
end
end
end
S.camps = list
if not S.typesLogged then
S.typesLogged = true
log("info", "camps mapped", { count = #list, types = types, clustered = clustered, blocked = blocked, march_pairs = pairs_found })
end
return list
end
local function neutrals_at(hero, camp)
local out = {}
for _, n in ipairs(NPCs.InRadius(camp.pos, camp.radius, Entity.GetTeamNum(hero), TEAM_BOTH, true, true)) do
if NPC.IsNeutral(n) and Entity.IsAlive(n) and not NPC.IsWaitingToSpawn(n) then out[#out + 1] = n end
end
return out
end
local function march_active(camp)
local m = camp.march
if m == nil or GameRules.GetGameTime() < (S.cleared[m.mate] or 0) then return false end
local mate = S.camps ~= nil and S.camps[m.mate] or nil
return mate ~= nil and (type(mate.kind) ~= "number" or mate.kind <= ui.tier:Get())
end
local function camp_stand(camp)
if march_active(camp) then
local best, bestDist = nil, nil
for _, st in ipairs(camp.march.stands) do
local d = S.heroPos ~= nil and (st - S.heroPos):Length2D() or 0
if bestDist == nil or d < bestDist then best, bestDist = st, d end
end
return best
end
return camp.gather or camp.pos
end
local function approach_point(hero, stand)
local o = Entity.GetAbsOrigin(hero)
local d = (stand - o):Length2D()
if d <= CAMP_STANDOFF then return o end
local k = (d - CAMP_STANDOFF) / d
return Vector(o.x + (stand.x - o.x) * k, o.y + (stand.y - o.y) * k, stand.z)
end
local function camp_arrived(hero, camp)
return (camp_stand(camp) - Entity.GetAbsOrigin(hero)):Length2D() <= CAMP_STANDOFF + CAMP_ARRIVE
end
local function creeps_near(hero)
local out = {}
for _, n in ipairs(NPCs.InRadius(Entity.GetAbsOrigin(hero), FIGHT_RADIUS, Entity.GetTeamNum(hero), TEAM_BOTH, true, true)) do
if NPC.IsNeutral(n) and Entity.IsAlive(n) and not NPC.IsWaitingToSpawn(n) then out[#out + 1] = n end
end
return out
end
local function camp_empty(hero, camp, origin)
if #neutrals_at(hero, camp) > 0 then return false end
if POINT_VISIBLE ~= nil and POINT_VISIBLE(camp.pos) then return true end
return (camp.pos - origin):Length2D() <= CAMP_INSIDE
end
local tp_ready
local function tp_worth(d, speed)
return d > TP_GLOBAL_MIN or (d > TP_FAST and d / speed > TP_TIME)
end
local function pick_camp(hero)
local origin = Entity.GetAbsOrigin(hero)
local now = GameRules.GetGameTime()
local best, bestScore, bestDist, blocked = nil, nil, nil, false
local zoneBest, zoneDist = nil, nil
local tier = ui.tier:Get()
local speed = math.max(200, NPC.GetMoveSpeed(hero))
local canTp = tp_ready(hero)
local threat = now < S.threatUntil and S.threatPos or nil
for i, camp in ipairs(build_camps()) do
local kind = type(camp.kind) == "number" and camp.kind or 1
local safe = threat == nil or (camp.pos - threat):Length2D() > ui.danger:Get() + THREAT_AVOID
local open = now >= (S.cleared[i] or 0) and kind <= tier
if open and not safe then blocked = true end
if open and safe then
local d = (camp.pos - origin):Length2D()
if S.zone ~= nil and (camp.pos - S.zone):Length2D() <= ZONE_RADIUS and (zoneDist == nil or d < zoneDist) then
zoneBest, zoneDist = camp, d
end
local time = d / speed
if canTp and tp_worth(d, speed) then time = math.min(time, TP_TIME) end
local value = (CAMP_VALUE[kind] or 1)
local clear = CAMP_CLEAR[kind] or 5
if march_active(camp) then
local mate = build_camps()[camp.march.mate]
value = value + (CAMP_VALUE[type(mate.kind) == "number" and mate.kind or 1] or 1)
clear = clear + 2
end
local score = value / (time + clear)
if bestScore == nil or score > bestScore then best, bestScore, bestDist = camp, score, d end
end
end
if zoneBest ~= nil then return zoneBest, zoneDist, blocked end
if S.zone ~= nil then
S.zone = nil
log("info", "zone done")
end
return best, bestDist, blocked
end
local function nearest_enemy(hero)
local origin = Entity.GetAbsOrigin(hero)
local radius = ui.danger:Get()
local best, bestDist = nil, radius + 1
for _, enemy in ipairs(Heroes.InRadius(origin, radius, Entity.GetTeamNum(hero), TEAM_ENEMY, true, true)) do
if Entity.IsAlive(enemy) and not NPC.IsIllusion(enemy) and NPC.IsVisible(enemy) then
local d = (Entity.GetAbsOrigin(enemy) - origin):Length2D()
if d < bestDist then best, bestDist = enemy, d end
end
end
return best, bestDist
end
local function order_move(hero, pos, now, attack)
if now < S.moveAt then return end
S.moveAt = now + MOVE_REPEAT
S.selfOrderAt = now
if attack and ORDER_ATTACK_MOVE ~= nil then
local player = Players.GetLocal()
if player ~= nil then
Player.PrepareUnitOrders(player, ORDER_ATTACK_MOVE, nil, pos, nil, ISSUER_PASSED, hero)
return
end
end
NPC.MoveTo(hero, pos)
end
local function jump_toward(hero, dest, now)
if now < S.jumpAt then return false end
local o = Entity.GetAbsOrigin(hero)
local d = (dest - o):Length2D()
if d < JUMP_MIN then return false end
local tp, tpName, fallen, fallenName = nil, nil, nil, nil
for _, label in ipairs(ui.items:ListEnabled()) do
local name = S.ids[label]
if name ~= nil and is_jump(name) then
local h = find_item(hero, name)
if castable(h) then
if is_blink(name) then
local reach = Ability.GetCastRange(h) - BLINK_EDGE
local r = math.min(d, reach)
S.selfOrderAt = now
Ability.CastPosition(h, Vector(o.x + (dest.x - o.x) / d * r, o.y + (dest.y - o.y) / d * r, o.z))
S.jumpAt = now + JUMP_HOLD
S.nextOrder = now + GAP
log("info", "blink", { item = name, jump = r, left = d })
return true
elseif name == FALLEN_SKY then
if fallen == nil then fallen, fallenName = h, name end
elseif tp == nil then
tp, tpName = h, name
end
end
end
end
if fallen ~= nil then
local reach = Ability.GetCastRange(fallen) - BLINK_EDGE
local r = math.min(d, reach)
if r >= JUMP_MIN then
S.selfOrderAt = now
Ability.CastPosition(fallen, Vector(o.x + (dest.x - o.x) / d * r, o.y + (dest.y - o.y) / d * r, o.z))
S.jumpAt = now + FALLEN_AIR
S.nextOrder = now + FALLEN_AIR
log("info", "fallen sky", { item = fallenName, jump = r, left = d })
return true
end
end
if tp == nil or not scepter_tp(hero, tp) then return false end
if now < S.knockUntil then return false end
local range = Ability.GetCastRange(tp)
local r = math.min(d, range - TP_SAFE)
if r < JUMP_MIN then return false end
S.selfOrderAt = now
Ability.CastPosition(tp, Vector(o.x + (dest.x - o.x) / d * r, o.y + (dest.y - o.y) / d * r, o.z))
S.jumpAt = now + JUMP_HOLD
S.nextOrder = now + GAP
log("info", "scepter tp", { item = tpName, jump = r, left = d, range = range })
return true
end
tp_ready = function(hero)
for _, label in ipairs(ui.items:ListEnabled()) do
local name = S.ids[label]
if name ~= nil and is_tp(name) then
local h = find_item(hero, name)
if castable(h) and scepter_tp(hero, h) then return true end
end
end
return false
end
local function global_tp(hero, dest, now)
if now < S.jumpAt then return false end
for _, label in ipairs(ui.items:ListEnabled()) do
local name = S.ids[label]
if name ~= nil and is_tp(name) then
local h = find_item(hero, name)
if castable(h) and scepter_tp(hero, h) then
S.selfOrderAt = now
Ability.CastPosition(h, dest)
S.jumpAt = now + JUMP_HOLD
S.nextOrder = now + GAP
log("info", "global tp", { item = name, dist = (dest - Entity.GetAbsOrigin(hero)):Length2D() })
return true
end
end
end
return false
end
local function jump_pending(hero)
for _, label in ipairs(ui.items:ListEnabled()) do
local name = S.ids[label]
if name ~= nil and is_jump(name) then
local h = find_item(hero, name)
if h ~= nil and not castable(h) then return true end
end
end
return false
end
local function mana_pct(hero)
local max_mana = NPC.GetMaxMana(hero)
if max_mana <= 0 then return 100 end
return NPC.GetMana(hero) / max_mana * 100
end
local function mana_ok(hero)
return mana_pct(hero) >= ui.mana:Get()
end
local function find_tp(hero)
for _, slot in ipairs(SCAN_SLOTS) do
local h = NPC.GetItemByIndex(hero, slot)
if h ~= nil and is_tp(Ability.GetName(h)) then return h end
end
return nil
end
local function go_home(hero, now)
local h = find_tp(hero)
if not castable(h) then return false end
S.selfOrderAt = now
if has_bit(Ability.GetBehavior(h), B_UNIT) then
Ability.CastTarget(h, hero)
else
Ability.CastNoTarget(h)
end
S.homeAt = now
S.homeTries = S.homeTries + 1
S.nextOrder = now + GAP
log("info", "home tp sent", { tries = S.homeTries, mana = NPC.GetMana(hero) })
return true
end
local function send_rearm(hero, now, reason, force)
if now < S.rearmBlock then return false end
local h = NPC.GetAbility(hero, REARM)
if h == nil or (not force and not mana_ok(hero)) then return false end
if not castable(h) then
if S.waitAt == 0 then S.waitAt = now end
return false, now - S.waitAt <= REARM_WAIT
end
S.waitAt = 0
S.selfOrderAt = now
Ability.CastNoTarget(h)
S.rearmAt = now
S.channelled = false
set_phase(now, "channel")
log("info", "rearm sent", { reason = reason, mana = NPC.GetMana(hero) })
return true, false
end
local function resume_phase(hero, now)
if now >= S.baseBlock and not mana_ok(hero) then
return set_phase(now, "base")
end
local camp = S.camp
if camp ~= nil and camp_arrived(hero, camp) then
set_phase(now, "fight")
else
set_phase(now, "travel")
end
end
local function channel_phase(hero, now)
if NPC.IsChannellingAbility(hero) then
S.channelled = true
return
end
if not S.channelled then
if now - S.rearmAt > REARM_START then
S.rearmTries = S.rearmTries + 1
if S.rearmTries > REARM_TRIES then
S.rearmTries = 0
S.rearmBlock = now + REARM_BLOCK
log("warn", "rearm never started", { blocked = REARM_BLOCK })
end
resume_phase(hero, now)
end
return
end
S.rearmTries = 0
S.done = {}
S.nextOrder = now + GAP
resume_phase(hero, now)
log("info", "rearm done", {})
end
local function leave_base(hero, now, level, reason)
S.baseBlock = now + BASE_BLOCK
S.fromBase = true
set_phase(now, "travel")
log(level, reason, { mana = NPC.GetMana(hero), tries = S.homeTries })
end
local function base_phase(hero, now)
if NPC.GetModifier(hero, TP_CHANNEL) ~= nil then
S.homeSeen = true
return
end
if mana_pct(hero) >= MANA_HOME_OK or now - S.phaseAt > BASE_TIMEOUT then
return leave_base(hero, now, "info", "base done")
end
if S.homeSeen or now - S.homeAt < HOME_GAP or now < S.nextOrder or not order_safe() then return end
if go_home(hero, now) then return end
send_rearm(hero, now, "home", true)
end
local function camps_in_dust(pos, now)
local n = 0
for i, camp in ipairs(S.camps or {}) do
if now >= (S.cleared[i] or 0) and (camp.pos - pos):Length2D() <= DUST_REACH then n = n + 1 end
end
return n
end
local function try_dust(hero, now, camp)
if not ui.dust:Get() or S.dustedCamp == camp.index then return false end
local h = NPC.GetAbility(hero, DUST)
if not castable(h) then return false end
local spot = camp_stand(camp)
local reach = camps_in_dust(Entity.GetAbsOrigin(hero), now)
if reach < DUST_MIN_CAMPS then
local best = camps_in_dust(spot, now)
if best >= DUST_MIN_CAMPS and now < S.dustWalk then
order_move(hero, spot, now, false)
return true
end
S.dustedCamp = camp.index
log("info", "dust skipped", { reason = "out of reach", camps = reach, at_spot = best })
return false
end
S.dustedCamp = camp.index
local charges = nil
local mod = NPC.GetModifier(hero, DUST_CHARGES)
if mod ~= nil then charges = Modifier.GetStackCount(mod) end
if charges ~= nil and charges <= 0 then
log("info", "dust skipped", { reason = "no charges", camps = reach })
return false
end
S.selfOrderAt = now
Ability.CastNoTarget(h)
S.nextOrder = now + GAP
S.dustFired = true
log("info", "dust aggro", { camps = reach, charges = charges })
return true
end
local function spend_items(hero, now, pos, creep)
for _, label in ipairs(ui.items:ListEnabled()) do
local name = S.ids[label]
if name ~= nil and not is_jump(name) and not S.done[name] then
S.done[name] = true
if S.dustFired and is_shiva(name) then
log("info", "shiva held", { reason = "dust pulled" })
else
local h = find_item(hero, name)
if castable(h) then
local kind = item_kind(h)
local range = Ability.GetCastRange(h)
local dist = (pos - Entity.GetAbsOrigin(hero)):Length2D()
if kind ~= nil and (kind == "no" or kind == "self" or range <= 0 or dist <= range) then
S.selfOrderAt = now
if kind == "enemy" then
if creep == nil then return false end
Ability.CastTarget(h, creep)
elseif kind == "self" then
Ability.CastTarget(h, hero)
elseif kind == "point" then
Ability.CastPosition(h, pos)
else
Ability.CastNoTarget(h)
end
S.nextOrder = now + GAP
log("info", "item " .. name, { kind = kind })
return true
end
end
end
end
end
return false
end
local function spend_spells(hero, now, pos, creep, small)
for _, name in ipairs(small and { MARCH } or { MARCH, TURRETS, LASER, MISSILE }) do
if not S.done[name] then
S.done[name] = true
local h = NPC.GetAbility(hero, name)
if castable(h) then
local range = Ability.GetCastRange(h)
local dist = (pos - Entity.GetAbsOrigin(hero)):Length2D()
if name == MISSILE then
S.selfOrderAt = now
Ability.CastNoTarget(h)
elseif name == MARCH and S.camp ~= nil and march_active(S.camp)
and (S.camp.march.aim - Entity.GetAbsOrigin(hero)):Length2D() <= range + CAMP_ARRIVE then
S.selfOrderAt = now
Ability.CastPosition(h, S.camp.march.aim)
S.nextOrder = now + Ability.GetCastPoint(h) + GAP
log("info", "march pair", { camp = S.camp.index, mate = S.camp.march.mate })
return true
elseif name == LASER then
if creep == nil or dist > range then return false end
S.selfOrderAt = now
Ability.CastTarget(h, creep)
else
local point = pos
if dist > range then
local o = Entity.GetAbsOrigin(hero)
local k = (range - BLINK_EDGE) / dist
point = Vector(o.x + (pos.x - o.x) * k, o.y + (pos.y - o.y) * k, pos.z)
end
S.selfOrderAt = now
Ability.CastPosition(h, point)
end
S.nextOrder = now + Ability.GetCastPoint(h) + GAP
if name == TURRETS then S.knockUntil = now + TURRET_SETTLE end
log("info", "cast " .. name, { dist = dist })
return true
end
end
end
return false
end
local function flee(hero, now, enemy)
local o = Entity.GetAbsOrigin(hero)
local e = Entity.GetAbsOrigin(enemy)
local dx, dy = o.x - e.x, o.y - e.y
local len = math.sqrt(dx * dx + dy * dy)
if len < 1 then dx, dy, len = 1, 0, 1 end
local want = ui.danger:Get() + FLEE_MARGIN
local dest = Vector(e.x + dx / len * want, e.y + dy / len * want, o.z)
S.pauseUntil = now + FLEE_PAUSE
S.camp = nil
S.done = {}
local first = not S.fleeing
S.fleeing = true
if now >= S.fleeJumpAt and jump_toward(hero, dest, now) then
S.fleeJumpAt = now + FLEE_JUMP_GAP
log("info", "flee jump", { enemy = NPC.GetUnitName(enemy), gap = math.floor(len), want = want })
return
end
order_move(hero, dest, now, false)
if first then log("info", "flee walk", { enemy = NPC.GetUnitName(enemy), gap = math.floor(len) }) end
end
local function stuck(hero, now)
local origin = Entity.GetAbsOrigin(hero)
if S.lastPos == nil or (origin - S.lastPos):Length2D() > STUCK_DIST then
S.lastPos, S.lastMoveAt = origin, now
return false
end
return now - S.lastMoveAt > STUCK_TIME
end
local function drop_camp(hero, now, reason, extra)
local camp = S.camp
if camp ~= nil and camp.index ~= nil then S.cleared[camp.index] = next_spawn(now) end
S.camp = nil
S.lastPos, S.lastMoveAt = nil, now
local data = extra or {}
data.reason = reason
log("warn", "camp dropped", data)
end
local function travel_phase(hero, now)
local camp = S.camp
local origin = Entity.GetAbsOrigin(hero)
local stand = camp_stand(camp)
local dist = (stand - origin):Length2D()
if camp_empty(hero, camp, origin) then
if camp.index ~= nil then S.cleared[camp.index] = next_spawn(now) end
S.camp = nil
log("info", "camp empty on sight", { dist = dist, kind = camp.kind })
return
end
if camp_arrived(hero, camp) then
S.done = {}
S.fromBase = false
S.zone = camp.pos
set_phase(now, "fight")
return
end
local approach = approach_point(hero, stand)
if now - S.phaseAt > TRAVEL_TIMEOUT then
return drop_camp(hero, now, "travel timeout", { dist = math.floor(dist) })
end
if stuck(hero, now) then
return drop_camp(hero, now, "stuck in travel", { dist = math.floor(dist) })
end
if (S.fromBase or tp_worth(dist, math.max(200, NPC.GetMoveSpeed(hero)))) and global_tp(hero, approach, now) then
S.fromBase = false
return
end
if jump_toward(hero, approach, now) then return end
local hop = (approach - origin):Length2D()
if hop > JUMP_MIN and jump_pending(hero) and send_rearm(hero, now, "travel") then return end
order_move(hero, approach, now, false)
end
local function fight_phase(hero, now)
local camp = S.camp
local origin = Entity.GetAbsOrigin(hero)
if now - S.phaseAt > FIGHT_TIMEOUT then
return drop_camp(hero, now, "fight timeout", { dist = math.floor((camp.pos - origin):Length2D()) })
end
if stuck(hero, now) then
return drop_camp(hero, now, "stuck in fight", { dist = math.floor((camp.pos - origin):Length2D()) })
end
local creeps = creeps_near(hero)
if #creeps == 0 then creeps = neutrals_at(hero, camp) end
if #creeps == 0 then
if camp_empty(hero, camp, origin) then
if camp.index ~= nil then S.cleared[camp.index] = next_spawn(now) end
S.camp = nil
log("info", "camp cleared", { kind = camp.kind, dist = (camp.pos - origin):Length2D() })
return
end
order_move(hero, camp.pos, now, false)
return
end
if ui.tier:Get() < 3 then
for _, n in ipairs(creeps) do
if NPC.IsAncient(n) then
if camp.index ~= nil then S.cleared[camp.index] = now + ANCIENT_SKIP end
S.camp = nil
log("info", "ancient camp skipped", { kind = camp.kind })
return
end
end
end
local creep = creeps[1]
local pos = Entity.GetAbsOrigin(creep)
local small = camp.kind == 0 and not march_active(camp)
if small then
if spend_spells(hero, now, pos, creep, true) then return end
order_move(hero, pos, now, true)
return
end
if try_dust(hero, now, camp) then return end
if spend_items(hero, now, pos, creep) then return end
if spend_spells(hero, now, pos, creep, false) then return end
local cast, waiting = send_rearm(hero, now, "fight")
if cast or waiting then return end
order_move(hero, pos, now, true)
end
local function update()
local hero = Heroes.GetLocal()
if hero == nil or NPC.GetUnitName(hero) ~= HERO then return stop("no hero") end
local now = GameRules.GetGameTime()
if now >= S.refreshAt then
S.refreshAt = now + REFRESH
local ok, err = pcall(refresh_items, hero)
if not ok and S.refreshError == nil then
S.refreshError = tostring(err)
log("error", "items refresh failed", { error = S.refreshError })
end
end
local down = ui.key:IsDown()
if down and not S.keyDown then
S.on = not S.on
S.keyDown = true
if S.on then
S.camp = nil
S.done = {}
S.pauseUntil = 0
set_phase(now, "travel")
log("info", "farm started", { camps = #build_camps() })
else
stop("toggled off")
end
elseif not down then
S.keyDown = false
end
if not ui.enabled:Get() then return stop("disabled") end
if not S.on then return end
if not Entity.IsAlive(hero) then return stop("dead") end
S.heroPos = Entity.GetAbsOrigin(hero)
local enemy = nearest_enemy(hero)
if enemy ~= nil then S.threatPos, S.threatUntil = Entity.GetAbsOrigin(enemy), now + THREAT_MEMORY end
if enemy == nil and S.fleeing then
S.fleeing = false
S.camp = nil
log("info", "flee done", { avoid = math.floor(ui.danger:Get() + THREAT_AVOID) })
end
if enemy ~= nil then
if NPC.IsChannellingAbility(hero) or now < S.nextOrder or not order_safe() then return end
return flee(hero, now, enemy)
end
if now < S.pauseUntil then return end
if S.phase == "channel" then return channel_phase(hero, now) end
if NPC.IsChannellingAbility(hero) or NPC.GetModifier(hero, TP_CHANNEL) ~= nil or now < S.nextOrder or not order_safe() then return end
if S.phase == "base" then return base_phase(hero, now) end
if now >= S.baseBlock and not mana_ok(hero) then
S.camp, S.zone = nil, nil
S.homeAt, S.homeTries, S.homeSeen = 0, 0, false
set_phase(now, "base")
log("info", "going home", { mana = NPC.GetMana(hero) })
return
end
if S.camp == nil then
local camp, _, blocked = pick_camp(hero)
if camp == nil then
if not blocked then S.cleared = {} end
return
end
S.camp = camp
S.done = {}
S.dustedCamp = nil
S.dustFired = false
S.dustWalk = now + DUST_WALK
S.lastPos, S.lastMoveAt = nil, now
set_phase(now, "travel")
return
end
if S.phase == "fight" then return fight_phase(hero, now) end
return travel_phase(hero, now)
end
function script.OnScriptsLoaded()
local ok, res = pcall(initialize_menu)
ready = ok and res == true
if not ready then g_menu_error = ok and "initialize_menu returned false" or tostring(res) end
S.font = Render.LoadFont("Arial", 0, 500)
log("info", "tinker_1x6_autofarm loaded", { menu_ready = ready, error = g_menu_error })
end
function script.OnUpdate()
if not ready or not Engine.IsInGame() then return end
local ok, err = pcall(update)
if not ok then
