if S.error == nil then log("error", "update failed", { error = tostring(err) }) end
S.error = tostring(err)
end
end
function script.OnPrepareUnitOrders(data)
if not ready or not S.on or data == nil then return true end
local hero = Heroes.GetLocal()
if hero == nil or data.npc ~= hero then return true end
local now = GameRules.GetGameTime()
if now - S.selfOrderAt <= SELF_ORDER then return true end
S.pauseUntil = now + MANUAL_PAUSE
S.camp = nil
return true
end
function script.OnGameEnd()
stop("game end")
S.camps = nil
S.cleared = {}
S.typesLogged = false
S.error = nil
S.sig = ""
end
local function draw_error_banner()
local title = g_menu_error and localization.Get("panel.menu_failed") or "Tinker Autofarm"
local msg = g_menu_error or S.error
Render.FilledRect(Vec2(20, 460), Vec2(760, 506), Color(20, 20, 24, 235), 4)
Render.Text(S.font, 14, title, Vec2(30, 466), Color(224, 50, 45, 245))
Render.Text(S.font, 12, msg:sub(1, 150), Vec2(30, 486), Color(220, 220, 225, 240))
end
function script.OnDraw()
if g_menu_error ~= nil or S.error ~= nil then pcall(draw_error_banner) end
end
return script
end)
