local function reset(reason, clearLock)
if S.phase ~= "idle" then log("info", "combo end", { reason = reason, cycles = S.cycle }) end
S.phase = "idle"
S.mode = 0
S.target = nil
if clearLock then S.lockedTarget = nil end
S.orbitStep = 0
S.done = {}
S.casts = 0
S.empty = 0
S.cycle = 0
S.channelled = false
S.waitAt = 0
S.missileCast = false
S.missileAt = 0
S.rearmTries = 0
S.fallenBlink = false
S.fallenBlinkUntil = 0
S.orderList = nil
S.retry = {}
S.jumpNeed = nil
end
local function castable(h)
return h ~= nil and Ability.GetLevel(h) > 0 and Ability.IsReady(h) and Ability.CanBeExecuted(h) == CAST_READY
end
local function has_bit(mask, bit)
return type(mask) == "number" and mask % (bit * 2) >= bit
end
local function clear_dodge()
local d = S.dodge
d.at = 0
d.expire = 0
d.name = nil
d.source = nil
d.sentAt = 0
d.nextTry = 0
d.tries = 0
end
local function clear_meteors()
S.dodge.meteors = {}
S.dodge.meteorCasts = {}
S.dodge.starforgeCooldowns = {}
S.dodge.dangerCasts = {}
S.dodge.dangerScanAt = 0
end
local function dodge_rearm(hero)
local h = NPC.GetAbility(hero, REARM)
local available = h ~= nil and Ability.GetLevel(h) > 0 and has_bit(Ability.GetBehavior(h), B_AUTOCAST)
local known = available or NPC.HasModifier(hero, REARM_INVULN_CD)
if known and not S.dodge.talentSeen then
S.dodge.talentSeen = true
log("info", "epic rearm talent detected", { ability = REARM, available = available })
end
return h, available
end
local function arm_dodge(now, impact, name, source)
local d = S.dodge
if d.at ~= 0 and now <= d.expire and d.at <= impact then return false end
d.at = impact
d.expire = impact + DODGE_EXPIRE
d.name = name
d.source = source
d.sentAt = 0
d.nextTry = 0
d.tries = 0
log("info", "dodge armed", { ability = name, source = source, impact = impact - now })
return true
end
local function facing_cone_ok(hero, enemy, radius)
if FORWARD_POS == nil then return true end
local o = Entity.GetAbsOrigin(enemy)
local f = FORWARD_POS(enemy, 100)
if f == nil then return true end
local fx, fy = f.x - o.x, f.y - o.y
local flen = math.sqrt(fx * fx + fy * fy)
if flen < 1 then return true end
local h = Entity.GetAbsOrigin(hero)
local dx, dy = h.x - o.x, h.y - o.y
local dlen = math.sqrt(dx * dx + dy * dy)
if dlen < 1 then return true end
local half = math.asin(math.min(1, (radius + DANGER_SLACK) / dlen)) + DANGER_CONE
if half >= math.pi then return true end
return (fx * dx + fy * dy) / (flen * dlen) >= math.cos(half)
end
local function dangerous_range(hero, enemy, ability, spec)
local distance = (Entity.GetAbsOrigin(hero) - Entity.GetAbsOrigin(enemy)):Length2D()
if spec.kind == "self" then return distance <= spec.radius + DANGER_SLACK end
local castRange = Ability.GetCastRange(ability)
if type(castRange) ~= "number" or castRange < 0 then castRange = 0 end
castRange = math.max(castRange, spec.range or 0)
if spec.kind == "centaur" then
if has_bit(Ability.GetBehavior(ability), B_POINT) then
return distance <= castRange + spec.radius + DANGER_SLACK
end
return distance <= spec.radius + DANGER_SLACK
end
if spec.kind == "target" then
return distance <= castRange + DANGER_SLACK and facing_cone_ok(hero, enemy, 0)
end
local radius = spec.radius or 0
return distance <= castRange + radius + DANGER_SLACK and facing_cone_ok(hero, enemy, radius)
end
local function dangerous_impact(now, ability, spec, modifier)
if modifier ~= nil then
local dieTime = Modifier.GetDieTime(modifier)
if type(dieTime) == "number" and dieTime >= now - 0.05 and dieTime <= now + 10 then
return math.max(now, dieTime)
end
return now
end
local castAt = Ability.GetCastStartTime(ability)
if type(castAt) ~= "number" or castAt < now - 0.25 or castAt > now + 10 then castAt = now end
local castPoint = IT.castPoint(ability)
if type(castPoint) ~= "number" or castPoint < 0 then castPoint = 0 end
return math.max(now, castAt + castPoint + (spec.delay or 0))
end
local function dangerous_cast_update(hero, now)
local d = S.dodge
if now < d.dangerScanAt then return end
d.dangerScanAt = now + DANGER_SCAN
local _, available = dodge_rearm(hero)
if not available then return end
local active = {}
for _, enemy in ipairs(Heroes.GetAll()) do
local specs = DANGER_BY_HERO[NPC.GetUnitName(enemy)]
if specs ~= nil and enemy ~= hero and Entity.IsAlive(enemy) and not NPC.IsIllusion(enemy) and not Entity.IsSameTeam(hero, enemy) then
for _, spec in ipairs(specs) do
local ability = NPC.GetAbility(enemy, spec.name)
if ability ~= nil and Ability.GetLevel(ability) > 0 then
local modifier = spec.modifier ~= nil and NPC.GetModifier(enemy, spec.modifier) or nil
local activeCast = modifier ~= nil or Ability.IsInAbilityPhase(ability)
if activeCast then
active[ability] = true
if not d.dangerCasts[ability] and dangerous_range(hero, enemy, ability, spec) then
local impact = dangerous_impact(now, ability, spec, modifier)
if arm_dodge(now, impact, spec.name, NPC.GetUnitName(enemy)) then
d.dangerCasts[ability] = true
end
end
end
end
end
end
end
for ability in pairs(d.dangerCasts) do
if not active[ability] then d.dangerCasts[ability] = nil end
end
end
local function track_projectile(data)
if data == nil or data.target == nil or data.source == nil or data.ability == nil or data.isAttack == true then return end
local hero = Heroes.GetLocal()
if hero == nil or NPC.GetUnitName(hero) ~= HERO or not Entity.IsAlive(hero) or data.target ~= hero then return end
if not NPC.IsHero(data.source) then return end
if Entity.IsSameTeam(hero, data.source) then return end
local _, available = dodge_rearm(hero)
if not available and not S.dodge.talentSeen then return end
local now = GameRules.GetGameTime()
local speed = data.moveSpeed
if type(speed) ~= "number" or speed <= 0 then speed = data.original_move_speed end
local travel = 0
if type(speed) == "number" and speed > 0 then
travel = (Entity.GetAbsOrigin(hero) - Entity.GetAbsOrigin(data.source)):Length2D() / speed
end
arm_dodge(now, now + travel, Ability.GetName(data.ability), NPC.GetUnitName(data.source))
end
local function track_particle_create(data)
if data == nil or type(data.index) ~= "number" then return end
local name = data.fullName or data.name or ""
if type(name) ~= "string" then return end
local now = GameRules.GetGameTime()
if name:find(METEOR_FX, 1, true) ~= nil then
S.dodge.meteors[data.index] = { kind = "invoker", created = now, at = now + METEOR_FALL, radius = METEOR_RADIUS, armed = false }
elseif name:find(STARFORGE_FX, 1, true) ~= nil then
S.dodge.meteors[data.index] = { kind = "starforge", created = now, at = now + STARFORGE_FALL, radius = STARFORGE_RADIUS, armed = false }
end
end
local function track_particle_update(data)
if data == nil or data.position == nil then return end
local meteor = S.dodge.meteors[data.index]
if meteor == nil then return end
if meteor.kind == "starforge" and data.controlPoint == 0 then
meteor.point = Vector(data.position.x, data.position.y, data.position.z)
if not meteor.logged then
meteor.logged = true
log("info", "starforge particle tracked", { x = meteor.point.x, y = meteor.point.y, impact = meteor.at - GameRules.GetGameTime() })
end
elseif meteor.kind == "starforge" and data.controlPoint == 1 and data.position.x > 0 then
meteor.radius = data.position.x
elseif meteor.kind == "starforge" and data.controlPoint == 2 and data.position.x > 0 and data.position.x < 5 then
meteor.at = meteor.created + math.max(0, data.position.x - 0.1)
elseif data.controlPoint == 1 then
meteor.point = Vector(data.position.x, data.position.y, data.position.z)
if not meteor.logged then
meteor.logged = true
log("info", "meteor tracked", { x = meteor.point.x, y = meteor.point.y, impact = meteor.at - GameRules.GetGameTime() })
end
elseif data.controlPoint == 2 and data.position.x > 0 and data.position.x < 5 then
meteor.at = meteor.created + data.position.x
elseif data.controlPoint == 5 and data.position.x > 0 then
meteor.radius = METEOR_RADIUS * data.position.x
end
end
local function upgraded_meteor(caster)
if caster == nil or not Entity.IsEntity(caster) or not Entity.IsNPC(caster) then return nil end
local ability = NPC.GetAbility(caster, METEOR_ABILITY)
if ability == nil or Ability.GetLevel(ability) <= 0 then return nil end
if not has_bit(Ability.GetBehavior(ability), B_CHANNELLED) then return nil end
return ability
end
local function track_meteor_modifier(entity, modifier)
if entity == nil or modifier == nil then return end
local modifierName = Modifier.GetName(modifier)
if modifierName ~= METEOR_THINKER and modifierName ~= STARFORGE_THINKER then return end
local hero = Heroes.GetLocal()
if hero == nil or NPC.GetUnitName(hero) ~= HERO or not Entity.IsAlive(hero) then return end
local caster = Modifier.GetCaster(modifier)
if caster == nil or Entity.IsSameTeam(hero, caster) then return end
local now = GameRules.GetGameTime()
local point = Entity.GetAbsOrigin(entity)
if modifierName == STARFORGE_THINKER then
local dieTime = Modifier.GetDieTime(modifier)
if type(dieTime) ~= "number" or dieTime <= now then dieTime = now + STARFORGE_FALL end
S.dodge.meteors[modifier] = { kind = "starforge", created = now, at = dieTime, radius = STARFORGE_RADIUS, point = point, armed = false }
log("info", "starforge thinker tracked", { x = point.x, y = point.y, impact = dieTime - now })
return
end
if upgraded_meteor(caster) == nil then return end
S.dodge.meteors[modifier] = { kind = "invoker", created = now, at = now + METEOR_FALL, radius = METEOR_RADIUS, point = point, armed = false }
log("info", "meteor thinker tracked", { x = point.x, y = point.y, impact = METEOR_FALL })
end
local function meteor_cast_update(hero, now)
local _, available = dodge_rearm(hero)
if not available then return end
local seen = {}
for _, enemy in ipairs(Heroes.GetAll()) do
if enemy ~= hero and Entity.IsAlive(enemy) and not Entity.IsSameTeam(hero, enemy) then
local ability = upgraded_meteor(enemy)
local active = NPC.GetChannellingAbility(enemy)
local phase = ability ~= nil and Ability.IsInAbilityPhase(ability)
local channel = ability ~= nil and active ~= nil and Ability.GetName(active) == METEOR_ABILITY
if phase or channel then
seen[enemy] = true
if not S.dodge.meteorCasts[enemy] then
S.dodge.meteorCasts[enemy] = true
local castAt = now
if phase then
local reported = Ability.GetCastStartTime(ability)
if type(reported) == "number" and reported >= now - 0.25 and reported <= now + 10 then castAt = reported end
end
local impact = castAt + METEOR_FALL
arm_dodge(now, impact, METEOR_ABILITY, phase and "invoker meteor phase" or "invoker meteor channel")
log("info", "meteor cast fallback", { phase = phase, impact = impact - now })
end
end
end
end
for enemy in pairs(S.dodge.meteorCasts) do
if not seen[enemy] then S.dodge.meteorCasts[enemy] = nil end
end
end
local function starforge_update(hero, now)
local _, available = dodge_rearm(hero)
if not available then return end
local seen = {}
for _, enemy in ipairs(Heroes.GetAll()) do
if enemy ~= hero and Entity.IsAlive(enemy) and not Entity.IsSameTeam(hero, enemy) then
local item = NPC.GetItem(enemy, STARFORGE, true)
if item ~= nil then
seen[enemy] = true
local cooldown = Ability.GetCooldown(item)
local previous = S.dodge.starforgeCooldowns[enemy]
if type(previous) == "number" and previous <= 0.05 and cooldown > 0.25 then
arm_dodge(now, now + STARFORGE_FALL, STARFORGE, "enemy starforge")
log("info", "starforge cooldown fallback", { source = NPC.GetUnitName(enemy), impact = STARFORGE_FALL })
end
S.dodge.starforgeCooldowns[enemy] = cooldown
end
end
end
for enemy in pairs(S.dodge.starforgeCooldowns) do
if not seen[enemy] then S.dodge.starforgeCooldowns[enemy] = nil end
end
end
local function meteor_update(hero, now)
local origin = Entity.GetAbsOrigin(hero)
local _, available = dodge_rearm(hero)
for index, meteor in pairs(S.dodge.meteors) do
if now > meteor.at + DODGE_EXPIRE then
S.dodge.meteors[index] = nil
elseif available and not meteor.armed and meteor.point ~= nil
and (meteor.point - origin):Length2D() <= meteor.radius + METEOR_SLACK
then
local name = meteor.kind == "starforge" and STARFORGE or METEOR_ABILITY
local source = meteor.kind == "starforge" and "starforge impact" or "invoker meteor"
meteor.armed = arm_dodge(now, meteor.at, name, source)
end
end
end
local function dodge_update(hero, now)
local h, available = dodge_rearm(hero)
local d = S.dodge
if not ui.dodge:Get() then
if d.at ~= 0 then clear_dodge() end
return false
end
if d.at == 0 then return false end
if d.sentAt > 0 and not available then
log("info", "alt rearm accepted", { ability = d.name, source = d.source, tries = d.tries })
clear_dodge()
return true
end
if now > d.expire then
log("info", "dodge expired", { ability = d.name, source = d.source, tries = d.tries })
clear_dodge()
return false
end
if now < d.at - DODGE_LEAD or not available then return false end
if now < d.nextTry then return true end
if d.tries >= DODGE_TRIES then return false end
reset("dodge")
Player.PrepareUnitOrders(Players.GetLocal(), ORDER_AUTO, nil, Entity.GetAbsOrigin(hero), h, ISSUER_UNIT, hero, false, false, false, true, "tinker_rearm_dodge", false)
d.tries = d.tries + 1
d.sentAt = now
d.nextTry = now + DODGE_RETRY
log("info", "alt rearm sent", { ability = d.name, source = d.source, tries = d.tries })
return true
end
local function item_kind(h)
local b = Ability.GetBehavior(h)
if has_bit(b, B_PASSIVE) or has_bit(b, B_HIDDEN) or has_bit(b, B_TOGGLE) then return nil end
if has_bit(b, B_UNIT) then
local team = Ability.GetTargetTeam(h)
if has_bit(team, TEAM_BIT_ENEMY) then return "enemy" end
if has_bit(team, TEAM_BIT_FRIENDLY) then return "self" end
return nil
end
if has_bit(b, B_POINT) then return "point" end
if has_bit(b, B_NO_TARGET) then return "no" end
return nil
end
local function item_skipped(name)
for _, frag in ipairs(ITEM_SKIP) do
if name:find(frag, 1, true) ~= nil then return true end
end
return false
end
local function item_base(name)
return (name:gsub("^item_", ""):gsub("_custom$", ""))
end
local function item_label(name)
return (item_base(name):gsub("_", " "))
end
function item_icon(name)
local base = item_base(name)
if base == "tpscroll" then
return "panorama/images/spellicons/tinker_keen_teleport_png.vtex_c"
end
return "panorama/images/items/" .. (ICON_FIX[base] or base) .. "_png.vtex_c"
end
local function is_tp(name)
return name:find("tpscroll", 1, true) ~= nil
end
local function scepter_tp(hero, h)
if h == nil or not NPC.HasScepter(hero) then return false end
if not has_bit(Ability.GetBehavior(h), B_POINT) then return false end
local range = Ability.GetCastRange(h)
return range > 0 and range <= TP_MAX
end
local function is_blink(name)
return name:find("blink", 1, true) ~= nil
end
local function is_octarine(name)
return name:find("octarine", 1, true) ~= nil
end
local function is_jump(name)
return is_blink(name) or is_tp(name)
end
local function jump_reach(hero, h, name)
local range = Ability.GetCastRange(h)
if is_blink(name) then
local ok, v = pcall(Ability.GetLevelSpecialValueFor, h, "blink_range", -1)
if ok and type(v) == "number" and v > 0 and v < range then range = v end
return range - BLINK_EDGE
end
local innate = NPC.GetAbility(hero, "tinker_innate_custom")
if innate ~= nil then
local ok, v = pcall(Ability.GetLevelSpecialValueFor, innate, "scepter_range", -1)
if ok and type(v) == "number" and v > 0 and v < range then range = v end
end
return range - BLINK_EDGE
end
local function octarine_before()
local selected = ui.octarine:ListEnabled()[1]
if type(selected) ~= "string" then return nil end
local name = S.ids[selected]
if name == nil or is_octarine(name) or is_tp(name) then return nil end
return selected
end
local function find_item(hero, name)
local h = NPC.GetItem(hero, name, true)
if h ~= nil then return h end
for _, slot in ipairs(SCAN_SLOTS) do
local it = NPC.GetItemByIndex(hero, slot)
if it ~= nil and Ability.GetName(it) == name then return it end
end
return nil
end
local function scan_items(hero)
local labels, ids, sig = {}, {}, ""
for _, slot in ipairs(SCAN_SLOTS) do
local h = NPC.GetItemByIndex(hero, slot)
if h ~= nil then
local name = Ability.GetName(h)
local keep
if is_tp(name) then
keep = scepter_tp(hero, h)
elseif name == FALLEN_SKY then
keep = item_kind(h) ~= nil
elseif slot <= ITEM_SLOTS then
keep = not item_skipped(name) and item_kind(h) ~= nil
else
keep = false
end
local label = item_label(name)
if keep and ids[label] == nil then
labels[#labels + 1] = label
ids[label] = name
sig = sig .. label .. ","
end
end
end
return labels, ids, sig
end
local function refresh_items(hero)
for _, pair in ipairs(IT.tick()) do S.seen[pair[1]] = true end
local labels, ids, sig = scan_items(hero)
if sig == S.sig then return end
local rank = {}
for i, id in ipairs(ui.items:List()) do rank[id] = i end
table.sort(labels, function(a, b) return (rank[a] or 1000) < (rank[b] or 1000) end)
local keep = octarine_before()
local rows, picks = {}, {}
for i, label in ipairs(labels) do
local on = true
if S.seen[label] then on = ui.items:Get(label) == true end
rows[i] = { label, item_icon(ids[label]), on }
if not is_octarine(ids[label]) and not is_tp(ids[label]) then
picks[#picks + 1] = { label, item_icon(ids[label]), label == keep }
end
end
ui.items:Update(rows, true, true)
ui.octarine:Update(picks, true, true)
S.sig, S.ids = sig, ids
IT.sync(hero, labels, ids, item_icon)
for _, label in ipairs(labels) do S.seen[label] = true end
log("info", "items refreshed", { items = labels, octarine_before = keep or "none" })
end
local function cooldown_count(hero)
local n = 0
for _, name in ipairs(ON_COOLDOWN) do
local h = NPC.GetAbility(hero, name)
if h ~= nil and Ability.GetLevel(h) > 0 and Ability.GetCooldown(h) > 0 then n = n + 1 end
end
return n
end
local function priority()
local out, placed = {}, false
for _, name in ipairs(IT.spellOrder(ui.spells)) do
out[#out + 1] = name
if name == TURRETS then
out[#out + 1] = DAGON_SECOND
placed = true
end
end
if not placed then out[#out + 1] = DAGON_SECOND end
return out
end
local function order()
local list = priority()
local sig = table.concat(list, ",")
if S.orderList ~= nil and S.orderCycle == S.cycle and S.orderSig == sig then return S.orderList end
local out, missile = {}, nil
for _, name in ipairs(list) do
local step = STEP_BY_ID[name] or { name = name, kind = "dagon" }
if name == MISSILE then missile = step else out[#out + 1] = step end
end
local shuffled = math.random(1, 100) > ui.pattern:Get()
if shuffled then
for i = #out, 2, -1 do
local j = math.random(1, i)
out[i], out[j] = out[j], out[i]
end
end
if missile ~= nil then out[#out + 1] = missile end
S.orderList, S.orderCycle, S.orderSig = out, S.cycle, sig
local names = {}
for i, s in ipairs(out) do names[i] = s.name end
log("info", "cast order", { cycle = S.cycle, shuffled = shuffled, order = table.concat(names, ",") })
return out
end
local function is_dagon(name)
return item_base(name):find("^dagon") ~= nil
end
local function state_dump(hero)
local out = {}
for _, name in ipairs({ GRENADE, LASER, MARCH, TURRETS, MISSILE, REARM }) do
local h = NPC.GetAbility(hero, name)
if h == nil then
out[name] = "absent"
else
out[name] = { level = Ability.GetLevel(h), cd = Ability.GetCooldown(h), result = Ability.CanBeExecuted(h), range = Ability.GetCastRange(h) }
end
end
return out
end
local function pick_target(hero)
local origin = Entity.GetAbsOrigin(hero)
local best, bestDist = nil, SEARCH + 1
for _, enemy in ipairs(Heroes.InRadius(origin, SEARCH, Entity.GetTeamNum(hero), TEAM_ENEMY, true, true)) do
if Entity.IsAlive(enemy) and not NPC.IsIllusion(enemy) then
local d = (Entity.GetAbsOrigin(enemy) - origin):Length()
if d < bestDist then best, bestDist = enemy, d end
end
end
return best
end
local function hovered_target(hero)
