local function detect_q_legendary(hero)
if S.qLegendary then return true end
local laser = NPC.GetAbility(hero, LASER)
if laser == nil or Ability.GetLevel(laser) <= 0 then return false end
local actual = Ability.GetCastRange(laser)
local expected = LASER_BASE_RANGE + NPC.GetCastRangeBonus(hero)
if actual <= 0 or math.abs(actual - expected) <= Q7_RANGE_DELTA then return false end
S.qLegendary = true
ui.keep:Set(Q7_KEEP)
log("info", "legendary Q detected", { range = actual, expected = expected, keep = Q7_KEEP })
return true
end
local function laser_reach(hero)
local h = NPC.GetAbility(hero, LASER)
if h == nil or Ability.GetLevel(h) <= 0 then return nil end
local range = Ability.GetCastRange(h)
return range > 0 and range - CAST_EDGE or nil
end
local function keep_point(hero, point)
local keep = ui.keep:Get()
local t = S.target
if t == nil or not Entity.IsAlive(t) then return point, nil end
local tpos = Entity.GetAbsOrigin(t)
local dx, dy = point.x - tpos.x, point.y - tpos.y
local d = math.sqrt(dx * dx + dy * dy)
local cap = laser_reach(hero)
if cap ~= nil and d > cap and cap > keep then
local k = cap / d
return Vector(tpos.x + dx * k, tpos.y + dy * k, point.z), cap
end
if keep <= 0 then return point, nil end
if d >= keep then return point, d end
if d < 1 then
local o = Entity.GetAbsOrigin(hero)
dx, dy = o.x - tpos.x, o.y - tpos.y
d = math.sqrt(dx * dx + dy * dy)
if d < 1 then return point, nil end
end
local k = keep / d
return Vector(tpos.x + dx * k, tpos.y + dy * k, point.z), keep
end
local function cursor_jump_point(hero, reach, clampRange)
if CURSOR_POS == nil then return nil end
local c = CURSOR_POS()
if c == nil then return nil end
local o = Entity.GetAbsOrigin(hero)
local d = (c - o):Length()
if d < BLINK_MIN or (not clampRange and d > reach) then return nil end
local r = clampRange and math.min(d, reach) or d
local point, hold = keep_point(hero, Vector(o.x + (c.x - o.x) / d * r, o.y + (c.y - o.y) / d * r, o.z))
local jump = (point - o):Length()
if jump < BLINK_MIN or jump > reach then return nil end
return point, hold, d, jump
end
local function orbit_jump_point(hero, reach)
local target = S.target
if target == nil or not Entity.IsAlive(target) then return nil end
local radius = ui.keep:Get()
if radius <= 0 then radius = 600 end
local o = Entity.GetAbsOrigin(hero)
local t = Entity.GetAbsOrigin(target)
local dx, dy = o.x - t.x, o.y - t.y
local distance = math.sqrt(dx * dx + dy * dy)
if distance < 1 then dx, dy, distance = 1, 0, 1 end
local angle = ATAN2(dy, dx)
local maxStep = 2 * math.asin(math.min(1, reach / (2 * radius))) * 0.85
maxStep = math.min(2.094395102, maxStep)
local minStep = 2 * math.asin(math.min(1, ORBIT_JUMP_MIN / (2 * radius))) * 1.05
local step = maxStep
if maxStep > minStep then step = minStep + math.random() * (maxStep - minStep) end
if math.random(0, 1) == 0 then step = -step end
local desired = Vector(t.x + math.cos(angle + step) * radius, t.y + math.sin(angle + step) * radius, t.z)
local jump = (desired - o):Length()
if jump >= ORBIT_JUMP_MIN and jump <= reach then return desired, radius, radius, jump end
local sameSide = Vector(t.x + dx / distance * radius, t.y + dy / distance * radius, t.z)
jump = (sameSide - o):Length()
if jump >= ORBIT_JUMP_MIN and jump <= reach then return sameSide, radius, radius, jump end
if distance <= radius then return nil end
local travel = math.min(reach, distance - radius)
if travel < ORBIT_JUMP_MIN then return nil end
local approach = Vector(o.x + (t.x - o.x) / distance * travel, o.y + (t.y - o.y) / distance * travel, o.z)
return approach, radius, radius, travel
end
local function approach_jump_point(hero, reach)
local t = S.target
if t == nil or not Entity.IsAlive(t) then return nil end
local o, tp = Entity.GetAbsOrigin(hero), Entity.GetAbsOrigin(t)
local d = (tp - o):Length2D()
local cap = laser_reach(hero) or APPROACH_RANGE
local travel = math.min(reach, d - (cap - APPROACH_INSIDE))
if travel < BLINK_MIN then return nil end
local point = Vector(o.x + (tp.x - o.x) / d * travel, o.y + (tp.y - o.y) / d * travel, o.z)
return point, nil, d, travel
end
local function jump_need(hero)
local t = S.target
if t == nil or not Entity.IsAlive(t) then return nil end
local d = (Entity.GetAbsOrigin(t) - Entity.GetAbsOrigin(hero)):Length2D()
local cap = laser_reach(hero) or APPROACH_RANGE
if d > cap + RANGE_SLACK then return "approach" end
local keep = ui.keep:Get()
if keep <= 0 then keep = ESCAPE_DIST end
if d < keep then return "escape" end
return nil
end
local function jump_point(hero, reach, clampRange)
if S.jumpNeed == "approach" then return approach_jump_point(hero, reach) end
if S.mode == 1 then return orbit_jump_point(hero, reach) end
return cursor_jump_point(hero, reach, clampRange)
end
local function jump_to_position(hero, now)
if now < S.blinkAt then return false end
S.jumpNeed = jump_need(hero)
if S.jumpNeed == nil then return false end
local blink, blinkName, blinkLabel, blinkPoint, blinkHold, blinkRequested, blinkJump = nil, nil, nil, nil, nil, nil, nil
local fallen, fallenName, fallenLabel = nil, nil, nil
local tp, tpName = nil, nil
for _, label in ipairs(ui.items:ListEnabled()) do
local name = S.ids[label]
if name ~= nil and (is_jump(name) or name == FALLEN_SKY) then
local h = find_item(hero, name)
if castable(h) then
if blink == nil and is_blink(name) then
local reach = jump_reach(hero, h, name)
local point, hold, requested, jump = jump_point(hero, reach, true)
if point ~= nil then
blink, blinkName, blinkLabel = h, name, label
blinkPoint, blinkHold, blinkRequested, blinkJump = point, hold, requested, jump
end
elseif name == FALLEN_SKY and not S.done[name] then
fallen, fallenName, fallenLabel = h, name, label
elseif is_tp(name) and tp == nil then
tp, tpName = h, name
end
end
end
end
if blink ~= nil then
if not S.fallenBlink and fallen ~= nil and S.target ~= nil and Entity.IsAlive(S.target) then
local point = Entity.GetAbsOrigin(S.target)
local distance = (point - Entity.GetAbsOrigin(hero)):Length()
local range = Ability.GetCastRange(fallen)
if range <= 0 or distance <= range + RANGE_SLACK then
if spend_octarine_before(hero, now, octarine_before(), fallenLabel, S.target, point, distance) then return true end
Ability.CastPosition(fallen, point)
S.done[fallenName] = true
S.fallenBlink = true
S.fallenBlinkUntil = now + FALLEN_SKY_WAIT + 1
S.nextOrder = now + FALLEN_SKY_WAIT
log("info", "fallen sky before blink", { item = fallenName, dist = distance, range = range, wait = FALLEN_SKY_WAIT, cycle = S.cycle })
return true
end
end
if spend_octarine_before(hero, now, octarine_before(), blinkLabel, S.target, blinkPoint, blinkJump) then return true end
Ability.CastPosition(blink, blinkPoint)
S.fallenBlink = false
S.fallenBlinkUntil = 0
S.blinkAt = now + JUMP_REST
S.nextOrder = now + GAP
if S.mode == 1 then S.orbitStep = S.orbitStep + 1 end
log("info", "blink", { need = S.jumpNeed, item = blinkName, requested = blinkRequested, jump = blinkJump, hold = blinkHold, mode = S.mode, step = S.orbitStep, cycle = S.cycle })
return true
end
if S.fallenBlink then
if now <= S.fallenBlinkUntil then return false end
S.fallenBlink = false
S.fallenBlinkUntil = 0
log("warn", "fallen sky blink timeout", { cycle = S.cycle })
end
if tp == nil or not scepter_tp(hero, tp) then return false end
local range = jump_reach(hero, tp, tpName)
local point, hold, requested, jump = jump_point(hero, range, true)
if point == nil then return false end
Ability.CastPosition(tp, point)
S.blinkAt = now + JUMP_REST
S.nextOrder = now + GAP
if S.mode == 1 then S.orbitStep = S.orbitStep + 1 end
log("info", "scepter tp", { need = S.jumpNeed, item = tpName, requested = requested, jump = jump, hold = hold, range = range, mode = S.mode, step = S.orbitStep, cycle = S.cycle })
return true
end
local function start(hero, now)
local mode = ui.mode:Get()
local locked = mode == 1 and S.lockedTarget or nil
local reused = locked ~= nil and Entity.IsAlive(locked) and not NPC.IsIllusion(locked)
local target, fallback = nil, false
if mode == 1 then
target = reused and locked or hovered_target(hero)
if target == nil then
target = pick_target(hero)
fallback = target ~= nil
end
else
target = pick_target(hero)
end
if target == nil then return end
S.phase = "cast"
S.mode = mode
S.target = target
S.lockedTarget = mode == 1 and target or nil
S.orbitStep = 0
S.done = {}
S.casts = 0
S.empty = 0
S.cycle = 0
S.missileCast = false
S.missileAt = 0
S.nextOrder = now
local missile = NPC.GetAbility(hero, MISSILE)
log("info", "combo started", {
target = S.target ~= nil and NPC.GetUnitName(S.target) or "none",
mode = S.mode,
lock_reused = reused,
fallback = fallback,
legendary = missile ~= nil and Ability.GetLevel(missile) > 0,
cooldowns = cooldown_count(hero),
abilities = state_dump(hero),
})
end
local function cast_at(kind, h, point, target)
if kind == "enemy" or kind == "self" then
Ability.CastTarget(h, target)
elseif kind == "point" then
Ability.CastPosition(h, point)
else
Ability.CastNoTarget(h)
end
end
local function turret_point(hero, pos, dist)
if dist <= TURRET_PUSH + RANGE_SLACK then return pos end
local o = Entity.GetAbsOrigin(hero)
local k = TURRET_PUSH / dist
return Vector(pos.x + (o.x - pos.x) * k, pos.y + (o.y - pos.y) * k, pos.z)
end
local function clamp_point(hero, point, range)
local o = Entity.GetAbsOrigin(hero)
local d = (point - o):Length()
if d <= range or d <= 0 then return point end
local k = range / d
return Vector(o.x + (point.x - o.x) * k, o.y + (point.y - o.y) * k, point.z)
end
spend_item = function(hero, now, h, name, target, pos, dist)
local kind = item_kind(h)
S.done[name] = true
if kind == nil then return false end
local range = Ability.GetCastRange(h)
if kind ~= "no" and range > 0 and dist > range + RANGE_SLACK then
log("info", "skip " .. name, { reason = "out of range", dist = dist, range = range })
return false
end
cast_at(kind, h, pos, kind == "self" and hero or target)
IT.chainMark(hero, target, name)
S.casts = S.casts + 1
S.nextOrder = now + GAP
log("info", "item " .. name, { kind = kind, dist = dist, cycle = S.cycle })
return true
end
local function cast_dagon(hero, now, target, pos, dist, key)
if S.done[key] then return false end
S.done[key] = true
for _, label in ipairs(ui.items:ListEnabled()) do
local name = S.ids[label]
if name ~= nil and is_dagon(name) then
local h = find_item(hero, name)
if castable(h) and IT.allow(hero, target, name, label) then
if spend_octarine_before(hero, now, octarine_before(), label, target, pos, dist) then
S.done[key] = nil
return true
end
return spend_item(hero, now, h, name, target, pos, dist)
end
end
end
return false
end
local function auto_items(hero, now, target, pos, dist)
local before = octarine_before()
for _, label in ipairs(ui.items:ListEnabled()) do
local name = S.ids[label]
if name ~= nil and not is_jump(name) and name ~= FALLEN_SKY and not is_dagon(name) then
if spend_octarine_before(hero, now, before, label, target, pos, dist) then return true end
if not (before ~= nil and is_octarine(name)) then
local h = enabled_item(hero, label)
if h ~= nil and IT.allow(hero, target, name, label) and spend_item(hero, now, h, name, target, pos, dist) then return true end
end
end
end
return false
end
local function missile_pending(hero)
if S.missileCast or ui.spells:Get(MISSILE) ~= true then return false end
local h = NPC.GetAbility(hero, MISSILE)
return h ~= nil and Ability.GetLevel(h) > 0
end
local function cast_phase(hero, now, target)
local pos = Entity.GetAbsOrigin(target)
local dist = (pos - Entity.GetAbsOrigin(hero)):Length()
S.retry = S.retry or {}
local cap = laser_reach(hero)
if cap ~= nil and dist > cap + RANGE_SLACK then
local player = Players.GetLocal()
if player ~= nil and now >= (S.moveAt or 0) then
Player.PrepareUnitOrders(player, IT.orderMove, nil, IT.stopPoint(hero, target, cap), nil, IT.issuer, hero, false, false, false, false, "tinker_1x6_rearm_combo")
S.moveAt = now + 0.25
end
return
end
if IT.breakLinken(hero, target, now) then return end
do local mw = IT.meteorCast(hero, target, now, "tinker_1x6_rearm_combo") if mw ~= nil then S.nextOrder = now + mw return end end
if cast_dagon(hero, now, target, pos, dist, DAGON_FIRST) then return end
if auto_items(hero, now, target, pos, dist) then return end
for _, s in ipairs(order()) do
if s.kind == "dagon" then
if cast_dagon(hero, now, target, pos, dist, DAGON_SECOND) then return end
elseif not S.done[s.name] and not (s.kind == "enemy" and IT.spellBlocked(target, now, s.name)) then
local h = resolve_spell(hero, s)
local raw = NPC.GetAbility(hero, s.name)
if h == nil and raw ~= nil and Ability.GetLevel(raw) > 0 and Ability.GetCooldown(raw) <= SPELL_LAG
and (S.retry[s.name] or 0) < SPELL_RETRY then
S.retry[s.name] = (S.retry[s.name] or 0) + 1
S.nextOrder = now + GAP
return
end
S.done[s.name] = true
local range = h ~= nil and Ability.GetCastRange(h) or 0
local point = s.name == TURRETS and turret_point(hero, pos, dist) or pos
local reach = dist
local forced = false
if h ~= nil and s.kind == "point" then
if range > 0 and (point - Entity.GetAbsOrigin(hero)):Length() > range then
point = clamp_point(hero, point, range - CAST_EDGE)
forced = true
end
reach = (point - Entity.GetAbsOrigin(hero)):Length()
