local sec, minute = A.stackSecond()
if st.phase == "travel" then
if #A.visible(A.neutrals(hero, camp)) == 0 then
if (C.pointVisible ~= nil and C.pointVisible(camp.pos)) or (camp.pos - origin):Length2D() <= C.campInside then
S.cleared[st.camp], S.stacks[st.camp] = A.nextSpawn(now), 0
A.release(id, "seen empty")
else
A.order(unit, st, now, C.orderMove, nil, camp.pos)
end
return
end
st.phase = "fight"
end
if st.phase == "pull" then
if now - st.pullAt >= C.pullHold then
local dir = origin - camp.pos
local len = math.max(1, dir:Length2D())
st.away = Vector(camp.pos.x + dir.x / len * C.awayDist, camp.pos.y + dir.y / len * C.awayDist, camp.pos.z)
st.phase, st.awayAt, st.orderAt = "away", now, 0
end
return
end
if st.phase == "away" then
if (minute ~= nil and minute > st.stacked and sec ~= nil and sec >= 0.8) or now - st.awayAt > C.awayTimeout then
st.phase, st.orderAt, st.target = "fight", 0, nil
S.stacks[st.camp] = (S.stacks[st.camp] or 0) + 1
A.log("info", "tb stack done", { unit = id, camp = st.camp, stacks = S.stacks[st.camp] })
else
A.order(unit, st, now, C.orderMove, nil, st.away)
end
return
end
local creeps = A.visible(A.neutrals(hero, camp))
A.track(st, creeps, now)
if #creeps > 0 then st.fought = true end
local fight, hidden = A.targets(unit, st, now)
if #fight == 0 then
if hidden ~= nil then
A.order(unit, st, now, C.orderMove, nil, hidden.pos)
return
end
local seen = C.pointVisible ~= nil and C.pointVisible(camp.pos)
if st.fought or seen or (camp.pos - origin):Length2D() <= C.campInside then
S.cleared[st.camp], S.stacks[st.camp] = A.nextSpawn(now), 0
A.release(id, "cleared")
else
st.phase = "travel"
end
return
end
if UI.stack:Get() and sec ~= nil and minute ~= nil and st.stacked < minute
and sec >= UI.stackSec:Get() and sec < UI.stackSec:Get() + 2 then
local nearest, bestDist = nil, nil
for _, c in ipairs(creeps) do
local d = (Entity.GetAbsOrigin(c) - origin):Length2D()
if bestDist == nil or d < bestDist then nearest, bestDist = c, d end
end
st.stacked, st.phase, st.pullAt, st.orderAt = minute, "pull", now, 0
A.order(unit, st, now, C.orderAttack, nearest)
A.log("info", "tb stack pull", { unit = id, camp = st.camp, second = math.floor(sec * 10) / 10, creeps = #creeps })
return
end
local target, bestDist = nil, nil
for _, c in ipairs(fight) do
local d = (Entity.GetAbsOrigin(c) - origin):Length2D()
if bestDist == nil or d < bestDist then target, bestDist = c, d end
end
if target ~= st.target or now - (st.attackAt or 0) > 2 then
st.target, st.attackAt, st.orderAt = target, now, 0
A.order(unit, st, now, C.orderAttack, target)
end
end
function A.stop(reason)
local player = Players.GetLocal()
for id in pairs(S.units) do
A.release(id, reason)
local unit = Entity.Get(id)
if player ~= nil and A.live(unit) and NPC.IsIllusion(unit) then
Player.PrepareUnitOrders(player, C.orderStop, nil, Entity.GetAbsOrigin(unit), nil, C.issuer, unit, false, false, false, false, C.identifier)
end
end
S.units, S.claim = {}, {}
end
function A.update()
local now = GameRules.GetGameTime()
local hero = Heroes.GetLocal()
