local down = UI.key:IsDown()
if down and not S.keyDown then
S.on = not S.on
if S.on then
A.log("info", "tb farm started", { camps = #A.camps() })
else
A.stop("toggled off")
A.log("info", "tb farm stopped")
end
end
S.keyDown = down
if not S.on or now < S.tickAt then return end
S.tickAt = now + C.tick
local player = Players.GetLocal()
local pid = player ~= nil and Player.GetPlayerID(player) or -1
A.scanCleared(hero, now)
A.creditLegends(hero, now)
local alive = {}
for _, unit in ipairs(Heroes.GetAll() or {}) do
if unit ~= nil and unit ~= hero and NPC.GetUnitName(unit) == C.hero and Entity.IsAlive(unit) and NPC.IsIllusion(unit)
and not NPC.HasModifier(unit, C.legendMod) and NPC.IsControllableByPlayer(unit, pid) then
local id = Entity.GetIndex(unit)
alive[id] = true
A.runUnit(hero, unit, id, now)
end
end
for id in pairs(S.units) do
if not alive[id] then
A.release(id, "illusion gone")
S.units[id] = nil
end
end
end
function A.drawPlate()
local hero = Heroes.GetLocal()
if hero == nil or NPC.GetUnitName(hero) ~= C.hero then return end
local text = localization.Get("panel.farm") .. ": " .. localization.Get(S.on and "panel.on" or "panel.off")
local size = Render.TextSize(S.font, 15, text)
local w, h = size.x + 28, 30
local x, y = S.dragX or UI.plateX:Get(), S.dragY or UI.plateY:Get()
A.dragPlate(x, y, w, h)
local accent = S.on and Color(80, 200, 110, 255) or Color(200, 70, 60, 255)
Render.FilledRect(Vec2(x, y), Vec2(x + w, y + h), Color(18, 18, 22, 215), 5)
Render.FilledRect(Vec2(x, y), Vec2(x + 4, y + h), accent, 2)
Render.Text(S.font, 15, text, Vec2(x + 14, y + (h - size.y) * 0.5), accent)
end
function A.dragPlate(x, y, w, h)
if not (A.api(Menu, "Opened") ~= nil and Menu.Opened()) then
S.drag, S.dragX, S.dragY = nil, nil, nil
return
end
local ok, cx, cy = pcall(Input.GetCursorPos)
if not ok or type(cx) ~= "number" or type(cy) ~= "number" then return end
local down = Input.IsKeyDown(C.mouse1)
if S.drag ~= nil then
if down then
S.dragX, S.dragY = math.max(0, cx - S.drag.dx), math.max(0, cy - S.drag.dy)
else
if S.dragX ~= nil then
UI.plateX:Set(math.floor(S.dragX))
UI.plateY:Set(math.floor(S.dragY))
end
S.drag, S.dragX, S.dragY = nil, nil, nil
end
elseif down and not S.mouseWas and cx >= x and cx <= x + w and cy >= y and cy <= y + h then
S.drag = { dx = cx - x, dy = cy - y }
end
S.mouseWas = down
end
