local cursor = C.cursorPos and C.cursorPos() or Entity.GetAbsOrigin(hero)
local best, bestDistance = nil, math.huge
for _, enemy in ipairs(Heroes.GetAll()) do
if enemy ~= hero and A.valid(enemy) and not Entity.IsSameTeam(hero, enemy) and not NPC.IsIllusion(enemy)
and A.distance(hero, enemy) <= UI.range:Get() then
local distance = (Entity.GetAbsOrigin(enemy) - cursor):Length2D()
if distance < bestDistance then
best, bestDistance = enemy, distance
end
end
end
return best
end
function A.track(target, now)
local pos = Entity.GetAbsOrigin(target)
local trk = S.track
local id = Entity.GetIndex(target)
local dt = now - trk.t
if trk.id ~= id or trk.t <= 0 or dt <= 0 or dt > C.trackReset then
trk.id = id
trk.x, trk.y, trk.t, trk.vx, trk.vy = pos.x, pos.y, now, 0, 0
return
end
if dt < C.trackGap then return end
trk.vx = trk.vx * 0.45 + (pos.x - trk.x) / dt * 0.55
trk.vy = trk.vy * 0.45 + (pos.y - trk.y) / dt * 0.55
trk.x, trk.y, trk.t = pos.x, pos.y, now
end
function A.predict(target, delay)
local pos = Entity.GetAbsOrigin(target)
delay = math.max(0, IT.moveTime(target, delay, GameRules.GetGameTime()))
return Vector(pos.x + S.track.vx * delay, pos.y + S.track.vy * delay, pos.z)
end
function A.order(hero, kind, point, target, ability, fast)
local player = Players.GetLocal()
if player == nil then return end
Player.PrepareUnitOrders(player, kind, target, point, ability, C.issuer, hero, false, true, false, fast, C.identifier)
end
function A.idle(hero, target, now)
local id = Entity.GetIndex(target)
if S.attacking == id and now - (S.attackAt or 0) < 1.0 then return end
A.order(hero, C.orderAttack, Entity.GetAbsOrigin(target), target, nil, true)
S.attacking = id
S.attackAt = now
end
function A.detectLegend(hero)
if not S.legend and A.ability(hero, C.replicantName) ~= nil then
S.legend = true
S.legendShown = false
A.log("info", "void legendary detected", { level = Ability.GetLevel(NPC.GetAbility(hero, C.replicantName)) })
end
if not S.legendShown and UI.legend ~= nil then
S.legendShown = true
pcall(UI.legend.ForceLocalization, UI.legend, localization.Get(S.legend and "menu.legend_yes" or "menu.legend_none"))
end
end
function A.chargeCount(step, hero)
if step == nil or not UI.spells:Get("spell.step") or Ability.GetLevel(step) <= 0 then return 0 end
local count = C.charges ~= nil and C.charges(step) or nil
if type(count) == "number" and count >= 1 then
return NPC.GetMana(hero) >= Ability.GetManaCost(step) and count or 0
end
return A.ready(step, hero) and 1 or 0
end
function A.behind(hero, target, final)
if final then return C.finalBehind end
local reach = NPC.GetAttackRange(hero) + NPC.GetAttackRangeBonus(hero) + NPC.GetHullRadius(target) - C.attackKeep
return math.max(C.behindMin, math.min(C.behindMax, reach))
end
function A.stepPoint(hero, step, from, target, delay, final)
local pos = A.predict(target, delay)
local dx, dy = pos.x - from.x, pos.y - from.y
local len = math.sqrt(dx * dx + dy * dy)
if len < 50 then
local origin = Entity.GetAbsOrigin(hero)
dx, dy = pos.x - origin.x, pos.y - origin.y
len = math.max(1, math.sqrt(dx * dx + dy * dy))
end
local behind = A.behind(hero, target, final)
local point = Vector(pos.x + dx / len * behind, pos.y + dy / len * behind, pos.z)
local origin = Entity.GetAbsOrigin(hero)
local ox, oy = point.x - origin.x, point.y - origin.y
local reach = math.sqrt(ox * ox + oy * oy)
local cap = Ability.GetCastRange(step) - C.rangeTrim
if cap > 0 and reach > cap then
point = Vector(origin.x + ox / reach * cap, origin.y + oy / reach * cap, point.z)
end
return point
end
function A.castStep(hero, step, target, now, final)
local delay = math.max(0, IT.castPoint(step)) + A.settle()
local from = final and S.p0 or Entity.GetAbsOrigin(hero)
Ability.CastPosition(step, A.stepPoint(hero, step, from, target, delay, final), false, false, true, C.identifier)
S.nextAt = now + delay
S.attacking = nil
S.steps = S.steps + 1
A.log("info", "void step", { final = final, left = math.floor((S.windowEnd - now) * 100) / 100, charges = A.chargeCount(step, hero) })
end
function A.plainStep(hero, step, target, now)
if step == nil or A.chargeCount(step, hero) < 1 then return false end
local replicant = A.ability(hero, C.replicantName)
if UI.replicant:Get() and replicant ~= nil and A.ready(replicant, hero)
and (C.isActivated == nil or C.isActivated(replicant)) then
return false
end
local range = Ability.GetCastRange(step)
if A.distance(hero, target) > range then return false end
A.castStep(hero, step, target, now, false)
return true
end
function A.windowActive(hero, now)
local mod = NPC.GetModifier(hero, C.windowMod)
if mod ~= nil then
S.windowEnd = Modifier.GetDieTime(mod)
return true
end
return now < S.windowEnd
end
function A.startWindow(hero, target, now)
if not UI.replicant:Get() then return false end
local replicant = A.ability(hero, C.replicantName)
local step = NPC.GetAbility(hero, C.stepName)
if replicant == nil or not A.ready(replicant, hero) then return false end
if C.isActivated ~= nil and not C.isActivated(replicant) then return false end
if A.chargeCount(step, hero) < 1 then return false end
if A.distance(hero, target) > Ability.GetCastRange(step) then return false end
Ability.CastNoTarget(replicant, false, false, true, C.identifier)
S.p0 = Entity.GetAbsOrigin(hero)
S.windowEnd = now + C.window + A.settle()
S.finalDone = false
S.steps = 0
S.nextAt = now + A.settle()
S.attacking = nil
A.log("info", "void replicant", { charges = A.chargeCount(step, hero), distance = math.floor(A.distance(hero, target)) })
return true
end
function A.spellReady(hero, name, key, now)
if not UI.spells:Get(key) or now - (S.castAt[key] or -10) < C.recastGap then return nil end
local ability = A.ability(hero, name)
if ability == nil or not A.ready(ability, hero) then return nil end
return ability
end
function A.castRemnant(hero, target, now)
local q = A.spellReady(hero, C.qName, "spell.q", now)
if q == nil or IT.immuneBlocked(target, Ability.GetName(q)) then return false end
local origin = Entity.GetAbsOrigin(hero)
local range = Ability.GetCastRange(q)
local pos = A.predict(target, C.remnantDelay + A.settle())
local dx, dy = origin.x - pos.x, origin.y - pos.y
local len = math.max(1, math.sqrt(dx * dx + dy * dy))
local gap = math.min(C.remnantGap, len)
local start = Vector(pos.x + dx / len * gap, pos.y + dy / len * gap, pos.z)
local travel = (start - origin):Length2D()
if travel > range then return false end
if IT.cycloneEarly(target, now, C.remnantDelay + travel / C.remnantSpeed + A.settle()) then return false end
pos = A.predict(target, C.remnantDelay + travel / C.remnantSpeed + A.settle())
if (pos - start):Length2D() > C.remnantWatch - NPC.GetHullRadius(target) then return false end
local finish = Vector(start.x - dx / len * C.remnantWatch, start.y - dy / len * C.remnantWatch, start.z)
A.order(hero, C.orderVector, finish, nil, q, false)
A.order(hero, C.orderCastPosition, start, nil, q, false)
S.castAt["spell.q"] = now
S.nextAt = now + math.max(0, IT.castPoint(q)) + A.settle()
S.attacking = nil
S.remnant = { pos = start, at = now, ready = now + math.max(0, IT.castPoint(q)) + A.settle() + travel / C.remnantSpeed + C.qLegendWait }
A.log("info", "void remnant", { distance = math.floor(len), travel = math.floor(travel) })
return true
end
function A.detectLegendQ(hero)
local ability = NPC.GetAbility(hero, C.qLegend)
local has = ability ~= nil and Ability.GetLevel(ability) > 0 and not Ability.IsHidden(ability)
if has == S.legendQ then return end
S.legendQ = has
if UI.legendQ ~= nil then UI.legendQ:Visible(has) end
A.log("info", "void q legendary", { q = has })
end
function A.castRemnantTp(hero, target, now)
local r = S.remnant
if not S.legendQ or not UI.legendQ:Get() or r == nil then return false end
if now > r.at + C.qLegendLife then
S.remnant = nil
return false
end
if now < r.ready then return false end
local ability = NPC.GetAbility(hero, C.qLegend)
if ability == nil or Ability.GetLevel(ability) <= 0 or Ability.IsHidden(ability) or not A.ready(ability, hero) then return false end
if C.isActivated ~= nil and not C.isActivated(ability) then return false end
local from = Entity.GetAbsOrigin(hero)
local pos = Entity.GetAbsOrigin(target)
local now2 = (pos - from):Length2D()
local after = (pos - r.pos):Length2D()
if now2 < C.qLegendMin or now2 - after < C.qLegendGain then return false end
Ability.CastNoTarget(ability, false, false, true, C.identifier)
S.remnant = nil
S.nextAt = now + 0.15 + A.settle()
S.attacking = nil
A.log("info", "void remnant teleport", { from = math.floor(now2), to = math.floor(after) })
return true
end
function A.castPulse(hero, target, now)
local e = A.spellReady(hero, C.eName, "spell.e", now)
if e == nil or IT.immuneBlocked(target, Ability.GetName(e)) then return false end
local pos = A.predict(target, A.settle())
if (pos - Entity.GetAbsOrigin(hero)):Length2D() > C.pulseRadius - NPC.GetHullRadius(target) then return false end
if IT.cycloneEarly(target, now, A.settle()) then return false end
Ability.CastNoTarget(e, false, false, true, C.identifier)
S.castAt["spell.e"] = now
S.nextAt = now + A.settle()
A.log("info", "void pulse")
return true
end
function A.castDissimilate(hero, target, now)
local w = A.spellReady(hero, C.wName, "spell.w", now)
if w == nil then return false end
local delay = math.max(0, IT.castPoint(w)) + C.portalPhase + A.settle()
if IT.castEarly(target, now, delay, true) then return false end
local reach = C.portalRing + C.portalRadius - NPC.GetHullRadius(target) - 60
if (A.predict(target, delay) - Entity.GetAbsOrigin(hero)):Length2D() > reach then return false end
Ability.CastNoTarget(w, false, false, true, C.identifier)
S.castAt["spell.w"] = now
S.phaseUntil = now + delay + 0.2
S.nextAt = now + math.max(0, IT.castPoint(w)) + A.settle()
S.attacking = nil
A.log("info", "void dissimilate")
return true
end
function A.steerPortal(hero, target, now)
local mod = NPC.GetModifier(hero, C.phaseMod)
if mod == nil and now >= S.phaseUntil then return false end
if now >= S.moveAt then
local left = mod ~= nil and math.max(0, Modifier.GetDieTime(mod) - now) or 0.3
A.order(hero, C.orderMove, A.predict(target, left), nil, nil, true)
S.moveAt = now + C.moveGap
end
return true
end
function A.runWindow(hero, target, now)
local step = NPC.GetAbility(hero, C.stepName)
local charges = A.chargeCount(step, hero)
local left = S.windowEnd - now
local lead = math.max(0, step ~= nil and IT.castPoint(step) or 0) + A.settle() + C.finalPad
if charges >= 1 and not S.finalDone and left <= lead + 0.1 then
S.finalDone = true
A.castStep(hero, step, target, now, true)
return
end
if IT.breakLinken(hero, target, now) then return end
do local mw = IT.meteorCast(hero, target, now, C.identifier) if mw ~= nil then S.nextAt = now + mw return end end
if A.useItems(hero, target, step, now) then return end
if A.castPulse(hero, target, now) then return end
if A.castRemnantTp(hero, target, now) then return end
if A.castRemnant(hero, target, now) then return end
if charges >= 2 or (charges >= 1 and left > C.reserveTime) then
A.castStep(hero, step, target, now, false)
return
end
A.idle(hero, target, now)
end
function A.holdLeft(target, now)
local held = false
for _, state in ipairs(C.holdStates) do
if NPC.HasState(target, state) then held = true end
end
local left = 0
for _, mod in ipairs(NPC.GetModifiers(target) or {}) do
local name = Modifier.GetName(mod)
for _, word in ipairs(C.holdWords) do
if name:find(word, 1, true) ~= nil then
local rest = Modifier.GetDieTime(mod) - now
if rest > left then left = rest end
held = true
end
end
end
if not held then return 0 end
return left
end
function A.meteorPoint(target, item, now)
local delay, radius = C.meteorDelay, C.meteorRadius
if C.special ~= nil then
local ok, value = pcall(C.special, item, "max_duration", -1)
if ok and type(value) == "number" and value > 0 then delay = value end
ok, value = pcall(C.special, item, "impact_radius", -1)
if ok and type(value) == "number" and value > 0 then radius = value end
end
delay = IT.itemFall(item, delay)
local reach = radius - NPC.GetHullRadius(target) - C.meteorMargin
local fall = delay + math.max(0, IT.castPoint(item)) + A.settle() * 0.5
local free = math.max(0, fall - A.holdLeft(target, now))
if NPC.GetMoveSpeed(target) * free <= reach then return Entity.GetAbsOrigin(target) end
return nil
end
function A.itemBase(name)
return (name:gsub("^item_", ""):gsub("_custom$", ""))
end
function A.itemLabel(name)
return (A.itemBase(name):gsub("_", " "))
end
function A.itemIcon(name)
local base = A.itemBase(name)
return "panorama/images/items/" .. (ICON_FIX[base] or base) .. "_png.vtex_c"
end
function A.itemSkipped(name)
for _, fragment in ipairs(ITEM_SKIP) do
if name:find(fragment, 1, true) ~= nil then return true end
end
return false
end
function A.has(value, bit)
return type(value) == "number" and bit > 0 and math.floor(value / bit) % 2 >= 1
end
function A.itemKind(item)
local behavior = Ability.GetBehavior(item)
if A.has(behavior, C.bPassive) or A.has(behavior, C.bHidden) or A.has(behavior, C.bToggle) then return nil end
if A.has(behavior, C.bUnit) then
local team = Ability.GetTargetTeam(item)
if A.has(team, C.targetEnemy) then return "enemy" end
if A.has(team, C.targetFriendly) then return "self" end
return nil
end
if A.has(behavior, C.bPoint) then return "point" end
if A.has(behavior, C.bNo) then return "no" end
return nil
end
function A.scanItems(hero)
local labels, ids, signature = {}, {}, ""
for _, slot in ipairs(C.itemSlots) do
local item = NPC.GetItemByIndex(hero, slot)
if item ~= nil then
local name = Ability.GetName(item)
local label = A.itemLabel(name)
if not A.itemSkipped(name) and A.itemKind(item) ~= nil and ids[label] == nil then
labels[#labels + 1] = label
ids[label] = name
signature = signature .. label .. "=" .. name .. ","
end
end
end
return labels, ids, signature
end
function A.refreshItems(hero)
IT.tick()
local labels, ids, signature = A.scanItems(hero)
if signature == S.itemSig then return end
local rank, old, enabled = {}, {}, {}
for i, id in ipairs(UI.items:List()) do
rank[id] = i
old[id] = true
end
for _, id in ipairs(UI.items:ListEnabled()) do enabled[id] = true end
table.sort(labels, function(a, b) return (rank[a] or 1000) < (rank[b] or 1000) end)
local rows, selected = {}, {}
for i, label in ipairs(labels) do
local on = not old[label] or enabled[label] == true
rows[i] = { label, A.itemIcon(ids[label]), on }
if on then selected[#selected + 1] = label end
end
UI.items:Update(rows, true, true)
UI.items:Set(selected)
S.itemSig = signature
S.itemIds = ids
IT.sync(hero, labels, ids, A.itemIcon)
A.log("info", "void items refreshed", { items = labels, enabled = selected })
end
function A.findItem(hero, label, name)
for _, slot in ipairs(C.itemSlots) do
local item = NPC.GetItemByIndex(hero, slot)
if item ~= nil and Ability.GetName(item) == name then return item end
end
for _, slot in ipairs(C.itemSlots) do
local item = NPC.GetItemByIndex(hero, slot)
if item ~= nil and A.itemLabel(Ability.GetName(item)) == label then return item end
end
return nil
end
function A.isJump(name)
return name:find("blink", 1, true) ~= nil or name:find("fallen_sky", 1, true) ~= nil
end
function A.itemReady(item, hero)
return item ~= nil and Ability.GetLevel(item) > 0 and Ability.IsCastable(item, NPC.GetMana(hero))
end
function A.clampPoint(hero, point, range)
if range <= 0 then return point end
local origin = Entity.GetAbsOrigin(hero)
local dx, dy = point.x - origin.x, point.y - origin.y
local length = math.sqrt(dx * dx + dy * dy)
local cap = math.max(0, range - 25)
if length <= cap or length <= 0 then return point end
local scale = cap / length
return Vector(origin.x + dx * scale, origin.y + dy * scale, point.z)
end
function A.comboReach(hero, ability)
local reach = 0
if ability ~= nil then reach = Ability.GetCastRange(ability) end
for _, label in ipairs(UI.items:ListEnabled()) do
local name = S.itemIds[label]
local item = name ~= nil and not A.isJump(name) and A.findItem(hero, label, name) or nil
if item ~= nil and A.itemReady(item, hero) then
local kind = A.itemKind(item)
if kind == "enemy" or kind == "point" then reach = math.max(reach, Ability.GetCastRange(item) + 75) end
end
end
return reach
end
function A.blinkPoint(hero, target)
local origin = Entity.GetAbsOrigin(hero)
local pos = Entity.GetAbsOrigin(target)
local dx, dy = pos.x - origin.x, pos.y - origin.y
local len = math.max(1, math.sqrt(dx * dx + dy * dy))
local range = NPC.GetAttackRange(hero) + NPC.GetAttackRangeBonus(hero)
local keep = range > 300 and math.max(C.blinkKeep, range - 100) or C.blinkKeep
return Vector(pos.x - dx / len * keep, pos.y - dy / len * keep, pos.z)
end
function A.orderMove(hero, point, now)
if now < S.moveAt then return end
A.order(hero, C.orderMove, point, nil, nil, false)
S.moveAt = now + C.moveGap
end
function A.isMeteor(name)
for _, fragment in ipairs(C.meteorItems) do
if name:find(fragment, 1, true) ~= nil then return true end
end
return false
end
function A.isShiva(name)
return name:find("shivas_guard", 1, true) ~= nil or name:find("gold_shiva", 1, true) ~= nil
end
function A.isHex(name)
return name:find("sheepstick", 1, true) ~= nil or name:find("hex", 1, true) ~= nil
end
function A.shivaHasTarget(hero, item)
local radius = C.shivaRadius
if C.special ~= nil then
local ok, value = pcall(C.special, item, "blast_radius", -1)
if ok and type(value) == "number" and value > 0 then radius = value end
end
for _, enemy in ipairs(Heroes.GetAll()) do
if A.valid(enemy) and not Entity.IsSameTeam(hero, enemy) and not NPC.IsIllusion(enemy)
and A.distance(hero, enemy) <= radius then
return true
end
end
return false
end
function A.useItems(hero, target, ability, now)
if now >= S.cycleAt then
S.done = {}
S.cycleAt = now + C.cycleGap
end
local distance = A.distance(hero, target)
for _, label in ipairs(UI.items:ListEnabled()) do
local name = S.itemIds[label]
if name ~= nil and not S.done[name] then
local item = A.findItem(hero, label, name)
if item == nil then
S.done[name] = true
elseif not IT.allow(hero, target, name, label) then
elseif A.itemReady(item, hero) then
local kind = A.itemKind(item)
local range = Ability.GetCastRange(item)
local jump = A.isJump(name)
if kind == nil then
S.done[name] = true
elseif jump and distance <= A.comboReach(hero, ability) then
elseif A.isShiva(name) and not A.shivaHasTarget(hero, item) then
elseif A.isMeteor(name) and A.meteorPoint(target, item, now) == nil then
elseif (kind == "enemy" or kind == "point") and not jump and range > 0 and distance > range + 75 then
A.orderMove(hero, IT.stopPoint(hero, target, range), now)
return true
else
if kind == "enemy" then
Ability.CastTarget(item, target, false, false, true, C.identifier)
elseif kind == "self" then
Ability.CastTarget(item, hero, false, false, true, C.identifier)
elseif kind == "point" and jump then
Ability.CastPosition(item, A.clampPoint(hero, A.blinkPoint(hero, target), range), false, false, true, C.identifier)
elseif kind == "point" then
Ability.CastPosition(item, A.clampPoint(hero, Entity.GetAbsOrigin(target), range), false, false, true, C.identifier)
else
Ability.CastNoTarget(item, false, false, true, C.identifier)
end
S.done[name] = true
local delay = math.max(0.08, math.max(0, IT.castPoint(item)) + 0.06)
if kind == "enemy" and A.isHex(name) then delay = math.max(delay, C.hexWait) end
S.nextAt = now + delay
S.attacking = nil
IT.chainMark(hero, target, name)
A.log("info", "void combo item", { item = name, kind = kind })
return true
end
end
end
end
return false
end
function A.update()
local hero = Heroes.GetLocal()
if not A.valid(hero) or Entity.GetUnitName(hero) ~= C.hero then
if S.phase ~= "idle" then A.reset("no void spirit") end
return
end
local clock = GameRules.GetGameTime()
if clock >= S.itemAt and S.itemError == nil then
S.itemAt = clock + C.itemGap
A.detectLegend(hero)
A.detectLegendQ(hero)
local ok, err = pcall(A.refreshItems, hero)
if not ok then
S.itemError = tostring(err)
A.log("error", "void items refresh failed", { error = S.itemError })
end
end
if not UI.enabled:Get() or not UI.key:IsDown() then
if S.phase ~= "idle" then A.reset("key released") end
return
end
if C.inputCaptured ~= nil and C.inputCaptured() then return end
if not A.orderSafe() then return end
if IT.heroDisabled(hero) then return end
local now = GameRules.GetGameTime()
if S.phase == "idle" then
S.target = A.pickTarget(hero)
if S.target == nil then return end
S.phase = "running"
S.startedAt = now
A.log("info", "void combo started", { target = Entity.GetUnitName(S.target) })
end
local target = S.target
if IT.fogHold(target, now) then
if A.orderMove ~= nil then A.orderMove(hero, Entity.GetAbsOrigin(target), now) end
return
end
if not A.valid(target) or Entity.IsSameTeam(hero, target) or A.distance(hero, target) > UI.range:Get() + 1000 then
A.reset("target lost")
return
end
if now - S.startedAt > C.maxRun then
A.reset("timeout")
return
end
A.track(target, now)
if NPC.HasModifier(hero, C.strikesMod) or NPC.HasModifier(hero, "modifier_item_meteor_hammer_custom_cast") or now < S.nextAt then return end
local step = NPC.GetAbility(hero, C.stepName)
if step ~= nil and Ability.IsInAbilityPhase(step) then return end
if A.steerPortal(hero, target, now) then return end
if A.windowActive(hero, now) then
A.runWindow(hero, target, now)
return
end
if S.windowEnd > 0 and now < S.windowEnd + C.endGrace then return end
if IT.breakLinken(hero, target, now) then return end
do local mw = IT.meteorCast(hero, target, now, C.identifier) if mw ~= nil then S.nextAt = now + mw return end end
if A.useItems(hero, target, step, now) then return end
if A.startWindow(hero, target, now) then return end
if A.castRemnantTp(hero, target, now) then return end
