{ key = "diffusal_blade", label = "Diffusal Blade", icon = "diffusal_blade", on = true },
{ key = "disperser", label = "Disperser", icon = "disperser", on = true },
{ key = "ethereal_blade", label = "Ethereal Blade", icon = "ethereal_blade", on = true },
{ key = "heavens_halberd", label = "Heaven's Halberd", icon = "heavens_halberd", on = true },
{ key = "nullifier", label = "Nullifier", icon = "nullifier", on = true },
{ key = "orchid", label = "Orchid Malevolence", icon = "orchid", on = false },
{ key = "bloodthorn", label = "Bloodthorn", icon = "bloodthorn", on = false },
},
blinks = { blink = true, swift_blink = true, arcane_blink = true, overwhelming_blink = true },
cpMin = 0.05,
cpScan = 1.0,
reactiveReach = 350,
reactiveMax = 700,
reactivePad = 100,
speedMin = 350,
speedMax = 3000,
listKeys = { "stuns", "hexes", "roots", "linken" },
inline = { stuns = true, hexes = true, roots = true, linken = false },
listLetter = { stuns = "s", hexes = "h", roots = "r", linken = "k" },
letterList = { s = "stuns", h = "hexes", r = "roots", k = "linken" },
kindList = { stun = "stuns", fear = "stuns", freeze = "stuns", hex = "hexes", sheep = "hexes", root = "roots", ensnare = "roots", entangle = "roots" },
catList = { "stuns", "hexes", "roots" },
catWords = { { "hex", "sheep", "voodoo" }, { "root", "ensnare", "entangle" } },
holders = { sphere = true, mirror_shield = true, dandelion_amulet = true },
blockMods = {
"modifier_custom_blink_spell_block", "modifier_sniper_take_aim_custom_block",
"modifier_custom_puck_phase_shift_absorb", "modifier_sandking_epicenter_custom_absorb",
"modifier_custom_reqiuem_spell_absorb", "modifier_templar_assassin_refraction_custom_absorb",
"modifier_antimage_counterspell_custom_active",
},
sessionGrace = 0.2,
gapGrace = 0.35,
radiusKeys = { "radius", "aoe_radius", "effect_radius", "stomp_radius", "stun_radius" },
defaultRadius = 350,
minDur = 0.4,
holdWords = { "stun", "root", "hex", "sheep", "bash", "frozen", "nightmare", "ensnare", "gungir", "cyclone", "wind_waker", "grip", "chains_custom_debuff", "sleep", "fear", "taunt", "entangle", "paralyz", "petrif", "banish" },
learnWords = { "stun", "root", "hex", "sheep", "bash", "frozen", "nightmare", "ensnare", "grip", "sleep", "fear", "taunt", "entangle", "paralyz", "petrif", "banish", "chains" },
linkenMod = "modifier_item_sphere_target",
meteorMod = "modifier_item_meteor_hammer_custom_cast",
tick = 0,
biasMax = 0.3,
cacheGap = 0.25,
castGap = 0.12,
breakWait = 0.7,
blinkGap = 2.5,
blinkStand = 120,
blinkNeed = 0.35,
heroTries = 3,
heroRetry = 1.5,
toastMax = 3,
defaultDur = 1.0,
maxDur = 8,
hasEnum = type(Enum) == "table",
}
C.stateImmune = C.hasEnum and type(Enum.ModifierState) == "table" and Enum.ModifierState.MODIFIER_STATE_MAGIC_IMMUNE or 9
C.stateInvuln = C.hasEnum and type(Enum.ModifierState) == "table" and Enum.ModifierState.MODIFIER_STATE_INVULNERABLE or 8
C.bNo = C.hasEnum and type(Enum.AbilityBehavior) == "table" and Enum.AbilityBehavior.DOTA_ABILITY_BEHAVIOR_NO_TARGET or 4
C.bUnit = C.hasEnum and type(Enum.AbilityBehavior) == "table" and Enum.AbilityBehavior.DOTA_ABILITY_BEHAVIOR_UNIT_TARGET or 8
C.bPoint = C.hasEnum and type(Enum.AbilityBehavior) == "table" and Enum.AbilityBehavior.DOTA_ABILITY_BEHAVIOR_POINT or 16
C.sideLeft = C.hasEnum and type(Enum.GroupSide) == "table" and Enum.GroupSide.Left
C.teamEnemy = C.hasEnum and type(Enum.TeamType) == "table" and Enum.TeamType.TEAM_ENEMY or 0
local UI = {}
local S = {
ready = false,
menuError = nil,
error = nil,
drawError = nil,
font = nil,
tickAt = 0,
nextAt = 0,
listAt = -10,
list = {},
guard = {},
session = {},
lastHold = {},
cast = {},
learned = {},
saved = "",
warned = {},
phase = {},
phaseList = {},
phaseScanAt = -10,
labelOf = {},
listOf = {},
pending = {},
pref = { stuns = {}, hexes = {}, roots = {}, linken = {} },
order = { stuns = {}, hexes = {}, roots = {}, linken = {} },
prefSaved = "",
sig = {},
breakerOf = {},
breakAt = {},
blinkAt = 0,
heroPref = {},
heroSig = nil,
heroTries = 0,
heroAt = 0,
toasts = {},
}
local A = {}
function A.api(tbl, name)
return type(tbl) == "table" and type(tbl[name]) == "function" and tbl[name] or nil
end
C.latency = A.api(NetChannel, "GetAvgLatency")
C.shareGet = type(load) == "function" and load("return X6Shared") or nil
C.shareSet = type(load) == "function" and load("X6Shared = ...") or nil
C.inputCaptured = A.api(Input, "IsInputCaptured")
function A.log(level, message, data)
if type(ai_bridge) == "table" and type(ai_bridge.mcp_log) == "function" then
pcall(ai_bridge.mcp_log, level, message, data)
end
end
function A.orderSafe()
local f = A.api(Humanizer, "IsSafeToCastOrder")
if f == nil then return true end
local ok, safe = pcall(f)
return not ok or safe ~= false
end
function A.has(mask, bit)
return type(mask) == "number" and math.floor(mask / bit) % 2 == 1
end
function A.base(name)
return (name:gsub("^item_", ""):gsub("_custom$", ""))
end
function A.speedOf(seed, learned)
if seed ~= nil then return seed.sp end
return learned ~= nil and learned.speed or nil
end
function A.shared(create)
local shared = nil
if C.shareGet ~= nil then
local ok, value = pcall(C.shareGet)
if ok and type(value) == "table" then shared = value end
end
if shared == nil and create and C.shareSet ~= nil then
shared = { keys = {}, cp = {}, bias = {} }
if not pcall(C.shareSet, shared) then return nil end
end
return shared
end
function A.comboDown()
local shared = A.shared()
if shared == nil or type(shared.keys) ~= "table" then return false end
for _, widget in pairs(shared.keys) do
local ok, down = pcall(widget.IsDown, widget)
if ok and down == true then return true end
end
return false
end
function A.publishLearned()
local shared = A.shared(true)
if shared == nil then return end
shared.bias, shared.dur = shared.bias or {}, shared.dur or {}
for name, entry in pairs(S.learned) do
if (entry.bias or 0) > 0 then shared.bias[name] = entry.bias end
if entry.dur > 0 then shared.dur[name] = entry.dur end
end
end
function A.castPoint(handle)
local api = math.max(0, Ability.GetCastPoint(handle))
local shared = A.shared()
local learned = shared ~= nil and shared.cp ~= nil and shared.cp[Ability.GetName(handle)] or nil
if type(learned) == "number" and learned < api then return learned end
return api
end
function A.liveValue(handle, key, seen)
if key == nil then return nil end
local ok, value = pcall(Ability.GetLevelSpecialValueFor, handle, key, -1)
if not ok or type(value) ~= "number" or value <= 0 then return nil end
if seen ~= nil and math.abs(value - seen) > seen * 0.05 and not S.warned[key .. Ability.GetName(handle)] then
S.warned[key .. Ability.GetName(handle)] = true
A.log("warn", "chain control seed differs from the game", { ability = Ability.GetName(handle), key = key, seed = seen, live = value })
end
return value
end
function A.itemFall(handle, fallback)
local maxDur = A.liveValue(handle, "max_duration")
if maxDur == nil then return fallback end
if Ability.GetName(handle):find("meteor_hammer", 1, true) ~= nil then return maxDur + (A.liveValue(handle, "land_time") or 0.5) end
return maxDur
end
function A.watchPhases(hero, now)
if now - S.phaseScanAt >= C.cpScan then
S.phaseScanAt = now
local found = {}
for slot = 0, C.abilitySlots - 1 do
local handle = NPC.GetAbilityByIndex(hero, slot)
if handle ~= nil and Ability.GetLevel(handle) > 0 and Ability.GetCastPoint(handle) > C.cpMin then found[#found + 1] = handle end
end
S.phaseList = found
end
local shared = nil
for _, handle in ipairs(S.phaseList) do
local name = Ability.GetName(handle)
local ok, phase = pcall(Ability.IsInAbilityPhase, handle)
if ok then
local started = S.phase[name]
if phase and started == nil then
S.phase[name] = now
elseif not phase and started ~= nil then
S.phase[name] = nil
local took = now - started
local api = math.max(0, Ability.GetCastPoint(handle))
if Ability.GetCooldown(handle) > 0 and took >= 0.03 and took <= api + 0.15 then
shared = shared or A.shared(true)
if shared ~= nil then
shared.cp = shared.cp or {}
local old = shared.cp[name]
shared.cp[name] = old == nil and took or (old + took) * 0.5
end
end
end
end
end
end
function A.at(list, level)
if type(list) ~= "table" or #list == 0 then return nil end
return list[math.min(math.max(level, 1), #list)]
end
function A.latencySec()
local ok, value = false, nil
if C.latency ~= nil then ok, value = pcall(C.latency) end
if not ok or type(value) ~= "number" or value < 0 then return 0.06 end
return math.max(0.03, value)
end
function A.matches(word, name)
return name:find(word, 1, true) ~= nil
end
function A.prettyName(name)
local text = name:gsub("_custom", ""):gsub("^custom_", ""):gsub("_", " ")
return (text:gsub("(%a)([%w]*)", function(first, rest) return first:upper() .. rest end))
end
function A.heroLabel(unitName)
local text = unitName:gsub("^npc_dota_hero_", ""):gsub("_", " ")
return (text:gsub("(%a)([%w]*)", function(first, rest) return first:upper() .. rest end))
end
function A.modCat(name)
for index, words in ipairs(C.catWords) do
for _, word in ipairs(words) do
if A.matches(word, name) then return index + 1 end
end
end
return 1
end
function A.listOfAbility(name)
local seed, learned = DATA.abilities[name], S.learned[name]
if seed ~= nil then return C.kindList[seed.k] or "stuns" end
return C.catList[learned ~= nil and learned.cat or 1] or "stuns"
end
function A.iconOf(name)
local seed = DATA.abilities[name]
if seed ~= nil and not seed.i:find("empty_png", 1, true) then return seed.i end
local texture = name:gsub("_legendary$", ""):gsub("_custom_?%d*$", ""):gsub("^custom_", "")
return "panorama/images/spellicons/" .. texture .. "_png.vtex_c"
end
function A.family(name)
return (name:gsub("_legendary$", ""):gsub("_%d+$", ""))
end
function A.itemIcon(icon)
return "panorama/images/items/" .. icon .. "_png.vtex_c"
end
function A.breaker(base)
for _, rule in ipairs(C.breakers) do
if base == rule.key or (rule.key == "dagon" and base:find("^dagon_%d$") ~= nil) then return rule end
end
return nil
end
function A.allowed(name)
local key, label = S.listOf[name], S.labelOf[name]
if key == nil or label == nil then return true end
return S.pref[key][label] ~= false
end
function A.heroAllowed(unit)
return S.heroPref[A.heroLabel(NPC.GetUnitName(unit))] ~= false
end
function A.load()
S.learned = {}
for part in (UI.store:Get() or ""):gmatch("[^|]+") do
local name, rest = part:match("^([^=]+)=(.+)$")
if name ~= nil then
local fields = {}
for value in rest:gmatch("[^:]+") do fields[#fields + 1] = tonumber(value) end
if fields[1] ~= nil then
S.learned[name] = { dur = fields[1], delay = fields[2] or 0, bias = fields[3] or 0, speed = fields[4] and fields[4] > 0 and fields[4] or nil, cat = fields[5] or 1, max = fields[6] or fields[1] }
end
end
end
S.saved = UI.store:Get() or ""
end
function A.save()
local parts = {}
for name, entry in pairs(S.learned) do
parts[#parts + 1] = string.format("%s=%.2f:%.2f:%.3f:%d:%d:%.2f", name, entry.dur, entry.delay or 0, entry.bias or 0, math.floor(entry.speed or 0), entry.cat or 1, entry.max or entry.dur)
end
table.sort(parts)
local text = table.concat(parts, "|")
if text ~= S.saved then
S.saved = text
UI.store:Set(text)
end
end
function A.loadPrefs()
S.pref = { stuns = {}, hexes = {}, roots = {}, linken = {} }
S.order = { stuns = {}, hexes = {}, roots = {}, linken = {} }
local text = UI.prefs:Get() or ""
for part in text:gmatch("[^|]+") do
local letter, label, on = part:match("^(%a)~(.-)=([01])$")
local key = letter ~= nil and C.letterList[letter] or nil
if key ~= nil and label ~= "" then
S.pref[key][label] = on == "1"
S.order[key][#S.order[key] + 1] = label
end
end
S.prefSaved = text
end
function A.savePrefs()
local parts = {}
for _, key in ipairs(C.listKeys) do
for _, label in ipairs(S.order[key]) do
parts[#parts + 1] = string.format("%s~%s=%d", C.listLetter[key], label, S.pref[key][label] == false and 0 or 1)
end
end
local text = table.concat(parts, "|")
if text ~= S.prefSaved then
S.prefSaved = text
UI.prefs:Set(text)
end
end
function A.newRows()
return { stuns = {}, hexes = {}, roots = {}, linken = {}, used = { stuns = {}, hexes = {}, roots = {}, linken = {} }, family = {} }
end
function A.addStatic(rows)
for _, base in ipairs(C.itemOrder) do
local rule = C.items[base]
if rule.list ~= nil and not rows.used[rule.list][rule.label] then
A.addRow(rows, rule.list, rule.label, base, A.itemIcon(rule.icon), true)
end
end
for _, breaker in ipairs(C.breakers) do
A.addRow(rows, "linken", breaker.label, breaker.key, A.itemIcon(breaker.icon), breaker.on)
end
end
function A.primeRows(key)
local rows = A.newRows()
A.addStatic(rows)
for _, label in ipairs(S.order[key]) do
if not rows.used[key][label] then A.addRow(rows, key, label, label, "", true) end
end
local out = {}
for index, row in ipairs(A.ordered(key, rows[key])) do out[index] = { row.label, row.icon, S.pref[key][row.label] ~= false } end
return out
end
function A.collect()
for _, key in ipairs(C.listKeys) do
local list = UI[key]
local ids = list:List()
if #ids > 0 then
local on, seen, order = {}, {}, {}
for _, id in ipairs(list:ListEnabled()) do on[id] = true end
for _, id in ipairs(ids) do
seen[id] = true
order[#order + 1] = id
S.pref[key][id] = on[id] == true
end
for _, id in ipairs(S.order[key]) do
if not seen[id] then order[#order + 1] = id end
end
S.order[key] = order
end
end
local ids = UI.heroes:List()
if #ids > 0 then
local on = {}
for _, id in ipairs(UI.heroes:ListEnabled()) do on[id] = true end
for _, id in ipairs(ids) do S.heroPref[id] = on[id] == true end
end
A.savePrefs()
end
function A.addRow(rows, key, label, alt, icon, default)
if rows.used[key][label] then label = label .. " (" .. alt .. ")" end
rows.used[key][label] = true
local list = rows[key]
list[#list + 1] = { label = label, icon = icon }
if S.pref[key][label] == nil then S.pref[key][label] = default end
return label
end
function A.ordered(key, items)
local rank = {}
for index, label in ipairs(S.order[key]) do rank[label] = index end
local out = {}
for index, row in ipairs(items) do out[index] = { row = row, rank = rank[row.label] or 1000000, index = index } end
table.sort(out, function(a, b)
if a.rank ~= b.rank then return a.rank < b.rank end
return a.index < b.index
end)
local rows = {}
for index, entry in ipairs(out) do rows[index] = entry.row end
return rows
end
function A.apply(rows)
for _, key in ipairs(C.listKeys) do
local parts = {}
for index, row in ipairs(rows[key]) do parts[index] = row.label .. "\1" .. row.icon end
local sig = table.concat(parts, "\2")
if sig ~= S.sig[key] then
S.sig[key] = sig
local list = UI[key]
local out, selected, tips = {}, {}, {}
for index, row in ipairs(A.ordered(key, rows[key])) do
local on = S.pref[key][row.label] ~= false
out[index] = { row.label, row.icon, on }
tips[index] = row.label
if on then selected[#selected + 1] = row.label end
end
list:Update(out, C.inline[key], true)
list:Set(selected)
pcall(list.UpdateToolTips, list, tips)
end
end
end
function A.holdLeft(enemy, now)
local left = 0
for _, mod in ipairs(NPC.GetModifiers(enemy) or {}) do
local name = Modifier.GetName(mod)
for _, word in ipairs(C.holdWords) do
if A.matches(word, name) then
local rest = Modifier.GetDieTime(mod) - now
if rest > left then left = rest end
break
end
end
end
return left
end
function A.linkenKind(enemy)
if NPC.HasModifier(enemy, C.linkenMod) then return "item" end
for _, slot in ipairs(C.itemSlots) do
local item = NPC.GetItemByIndex(enemy, slot)
if item ~= nil and C.holders[A.base(Ability.GetName(item))] and Ability.GetCooldown(item) <= 0 then return "item" end
end
for _, name in ipairs(C.blockMods) do
if NPC.HasModifier(enemy, name) then return "mod" end
end
return nil
end
function A.targetKind(handle)
local behavior = Ability.GetBehavior(handle)
if A.has(behavior, C.bUnit) then return "u" end
if A.has(behavior, C.bPoint) then return "p" end
if A.has(behavior, C.bNo) then return "n" end
return nil
end
function A.refresh(hero, now)
if now - S.listAt < C.cacheGap then return end
S.listAt = now
A.collect()
local rows = A.newRows()
A.addStatic(rows)
local list = {}
S.breakerOf = {}
for slot = 0, C.abilitySlots - 1 do
local handle = NPC.GetAbilityByIndex(hero, slot)
if handle ~= nil and not Ability.IsHidden(handle) then
local name = Ability.GetName(handle)
local seed, learned = DATA.abilities[name], S.learned[name]
if seed ~= nil or learned ~= nil then
local key = A.listOfAbility(name)
local pretty = A.prettyName(name)
local family = key .. A.family(name)
if rows.family[family] == nil then
rows.family[family] = A.addRow(rows, key, seed ~= nil and seed.n or pretty, pretty, A.iconOf(name), true)
end
S.labelOf[name] = rows.family[family]
S.listOf[name] = key
local level = Ability.GetLevel(handle)
local kind = level > 0 and A.allowed(name) and A.targetKind(handle) or nil
if kind ~= nil then
local seedDur = A.at(seed and seed.du, level)
local dur = math.max(learned ~= nil and learned.dur or 0, seed ~= nil and A.liveValue(handle, seed.duk, seedDur) or seedDur or 0)
if dur <= 0 then dur = C.defaultDur end
list[#list + 1] = {
handle = handle, name = name, kind = kind, dur = math.min(dur, C.maxDur),
speed = seed ~= nil and (A.liveValue(handle, seed.spk, seed.sp) or seed.sp) or A.speedOf(seed, learned),
land = seed ~= nil and (A.liveValue(handle, seed.dlk, seed.dl) or seed.dl) or 0,
reactive = seed ~= nil and seed.re == true, tier = seed ~= nil and seed.re == true and 1 or 0,
bias = learned ~= nil and learned.bias or 0,
radius = seed ~= nil and seed.ra or nil, pierce = seed ~= nil and seed.pierce == true,
learnedDelay = learned ~= nil and learned.delay or nil,
}
end
end
end
end
local silence = UI.silence:Get()
for _, slot in ipairs(C.itemSlots) do
local handle = NPC.GetItemByIndex(hero, slot)
if handle ~= nil then
local name = Ability.GetName(handle)
local base = A.base(name)
local rule = C.items[base]
if rule ~= nil then
if rule.list ~= nil then
S.labelOf[name], S.listOf[name] = rule.label, rule.list
end
local kind = (rule.soft ~= true or silence) and A.allowed(name) and A.targetKind(handle) or nil
if kind ~= nil then
list[#list + 1] = {
handle = handle, name = name, kind = kind, dur = rule.dur, speed = rule.speed, land = rule.fall ~= nil and A.itemFall(handle, rule.fall) or 0,
radius = rule.radius, pierce = rule.pierce == true, item = true, soft = rule.soft == true, tier = rule.soft == true and 2 or 0,
bias = S.learned[name] ~= nil and S.learned[name].bias or 0,
}
end
end
local breaker = A.breaker(base)
if breaker ~= nil then S.breakerOf[breaker.label] = handle end
end
end
S.list = list
A.apply(rows)
end
function A.delay(control, hero, enemy)
local delay = A.latencySec() * 2 + 0.06 + A.castPoint(control.handle) + control.land
if control.speed ~= nil and control.kind ~= "n" then
delay = delay + (Entity.GetAbsOrigin(hero) - Entity.GetAbsOrigin(enemy)):Length2D() / control.speed
elseif control.learnedDelay ~= nil and control.land == 0 then
delay = math.max(delay, control.learnedDelay)
end
return delay
end
function A.reach(control, enemy)
local hull = NPC.GetHullRadius(enemy)
if control.reactive then
return math.min(C.reactiveMax, math.max(C.reactiveReach, NPC.GetAttackRange(enemy) + C.reactivePad)) + hull * 0.5
end
local range = Ability.GetCastRange(control.handle)
if control.kind == "n" then
local reach = control.radius or (range > 0 and range or nil)
if reach == nil then
for _, key in ipairs(C.radiusKeys) do
local ok, value = pcall(Ability.GetLevelSpecialValueFor, control.handle, key, -1)
if ok and type(value) == "number" and value > 0 then
reach = value
break
end
end
end
return (reach or C.defaultRadius) + hull * 0.5
end
if range <= 0 then range = control.radius or 0 end
return range > 0 and range + hull or 0
end
function A.inRange(control, hero, enemy)
local reach = A.reach(control, enemy)
return reach > 0 and (Entity.GetAbsOrigin(hero) - Entity.GetAbsOrigin(enemy)):Length2D() <= reach
end
function A.ready(control, hero, enemy, ignoreLinken)
if Ability.GetLevel(control.handle) <= 0 or Ability.GetCooldown(control.handle) > 0 then return false end
if not Ability.IsCastable(control.handle, NPC.GetMana(hero)) then return false end
if control.dur < C.minDur then return false end
if NPC.HasState(enemy, C.stateImmune) and not control.pierce then return false end
if control.kind == "u" and not ignoreLinken and A.linkenKind(enemy) ~= nil then return false end
return true
end
function A.cast(control, hero, enemy)
local handle = control.handle
if control.kind == "u" then
Ability.CastTarget(handle, enemy, false, false, true, C.identifier)
elseif control.kind == "p" then
Ability.CastPosition(handle, Entity.GetAbsOrigin(enemy), false, false, true, C.identifier)
else
Ability.CastNoTarget(handle, false, false, true, C.identifier)
end
end
function A.enemies(hero)
local list = {}
for _, unit in ipairs(Heroes.GetAll() or {}) do
if unit ~= nil and unit ~= hero and not Entity.IsSameTeam(hero, unit) and Entity.IsAlive(unit)
and not Entity.IsDormant(unit) and not NPC.IsIllusion(unit) and A.heroAllowed(unit) then
list[#list + 1] = unit
end
end
return list
end
function A.heroBusy(hero)
if NPC.IsStunned(hero) or NPC.IsChannellingAbility(hero) or NPC.HasModifier(hero, C.meteorMod) then return true end
if C.inputCaptured ~= nil and C.inputCaptured() then return true end
return not A.orderSafe()
end
function A.frame()
local f = A.api(GlobalVars, "GetAbsFrameTime")
local ok, value = false, nil
if f ~= nil then ok, value = pcall(f) end
if not ok or type(value) ~= "number" or value <= 0 or value > 0.1 then return 0.017 end
return value
end
function A.toast(text, now)
if not UI.notify:Get() then return end
table.insert(S.toasts, { text = text, at = now })
while #S.toasts > C.toastMax do table.remove(S.toasts, 1) end
end
function A.breakLinken(hero, enemy, now, id)
if now < (S.breakAt[id] or 0) or A.linkenKind(enemy) ~= "item" or NPC.HasState(enemy, C.stateImmune) then return false end
local wanted = false
for _, control in ipairs(S.list) do
if control.kind == "u" and A.ready(control, hero, enemy, true) and A.inRange(control, hero, enemy) then
wanted = true
break
end
end
if not wanted then return false end
local dist = (Entity.GetAbsOrigin(hero) - Entity.GetAbsOrigin(enemy)):Length2D()
for _, label in ipairs(UI.linken:ListEnabled()) do
local handle = S.breakerOf[label]
if handle ~= nil and Ability.GetLevel(handle) > 0 and Ability.GetCooldown(handle) <= 0
and Ability.IsCastable(handle, NPC.GetMana(hero)) and dist <= Ability.GetCastRange(handle) + NPC.GetHullRadius(enemy) then
Ability.CastTarget(handle, enemy, false, false, true, C.identifier)
local point = math.max(0, Ability.GetCastPoint(handle))
S.breakAt[id] = now + point + C.breakWait
S.nextAt = now + math.max(C.castGap, point + 0.05)
A.toast(string.format(localization.Get("panel.linken"), label, A.heroLabel(NPC.GetUnitName(enemy))), now)
A.log("info", "chain control linken", { item = Ability.GetName(handle) })
return true
end
end
return false
end
function A.blinkItem(hero)
for _, slot in ipairs(C.itemSlots) do
local item = NPC.GetItemByIndex(hero, slot)
if item ~= nil and C.blinks[A.base(Ability.GetName(item))] and Ability.GetCooldown(item) <= 0
and Ability.IsCastable(item, NPC.GetMana(hero)) then
return item
end
end
return nil
end
function A.blink(hero, enemy, now, left, far)
if not UI.blink:Get() or now < S.blinkAt then return false end
local item = A.blinkItem(hero)
if item == nil then return false end
local enemyPos, heroPos = Entity.GetAbsOrigin(enemy), Entity.GetAbsOrigin(hero)
local dist = (heroPos - enemyPos):Length2D()
local stand = math.max(C.blinkStand, far.reach * 0.6)
if dist <= stand or dist - stand > Ability.GetCastRange(item) then return false end
local control = far.control
local need = C.blinkNeed + A.latencySec() * 2 + math.max(0, Ability.GetCastPoint(control.handle)) + control.land
if control.speed ~= nil and control.kind ~= "n" then need = need + stand / control.speed end
if left <= need then return false end
Ability.CastPosition(item, enemyPos + (heroPos - enemyPos) / dist * stand, false, false, true, C.identifier)
S.blinkAt = now + C.blinkGap
S.nextAt = now + C.castGap
A.toast(string.format(localization.Get("panel.blink"), A.heroLabel(NPC.GetUnitName(enemy))), now)
A.log("info", "chain control blink", { left_ms = math.floor(left * 1000) })
return true
end
function A.update()
local now = GameRules.GetGameTime()
if now < S.tickAt then return end
S.tickAt = now + C.tick
local hero = Heroes.GetLocal()
if hero == nil or not Entity.IsAlive(hero) then return end
A.refresh(hero, now)
if #S.list == 0 or now < S.nextAt or A.heroBusy(hero) or A.comboDown() then return end
local pad = UI.pad:Get() + A.frame()
for _, enemy in ipairs(A.enemies(hero)) do
local id = Entity.GetIndex(enemy)
local left = A.holdLeft(enemy, now)
if left > 0 then S.lastHold[id] = now end
local active = now < (S.session[id] or 0) and now - (S.lastHold[id] or -10) <= C.gapGrace
if (left > 0 or active) and now >= (S.guard[id] or 0) then
local invulnerable = NPC.HasState(enemy, C.stateInvuln)
local best, bestDelay, far, near = nil, 0, nil, false
for _, control in ipairs(S.list) do
if A.ready(control, hero, enemy) then
if A.inRange(control, hero, enemy) then
near = true
local delay = A.delay(control, hero, enemy)
local due = invulnerable and left <= pad + 0.05 or (not invulnerable and left <= delay + pad + (control.bias or 0))
if due and (best == nil or control.tier < best.tier or (control.tier == best.tier and control.dur > best.dur)) then
best, bestDelay = control, delay
end
else
local reach = A.reach(control, enemy)
if far == nil or reach > far.reach then far = { control = control, reach = reach } end
end
end
end
if best ~= nil then
A.cast(best, hero, enemy)
S.guard[id] = now + bestDelay + 0.1
S.session[id] = now + bestDelay + best.dur + C.sessionGrace
local dist = (Entity.GetAbsOrigin(hero) - Entity.GetAbsOrigin(enemy)):Length2D()
S.cast[best.name] = { time = now, enemy = id, dist = dist }
S.pending[id] = { name = best.name, endAt = now + left, sched = left > bestDelay and not best.reactive }
S.nextAt = now + math.max(C.castGap, math.max(0, Ability.GetCastPoint(best.handle)) + 0.05)
A.toast(string.format(localization.Get("panel.extend"), S.labelOf[best.name] or A.prettyName(best.name), A.heroLabel(NPC.GetUnitName(enemy))), now)
A.log("info", "chain control", { control = best.name, left_ms = math.floor(left * 1000), delay_ms = math.floor(bestDelay * 1000) })
return
end
if left > 0 and not invulnerable then
if A.breakLinken(hero, enemy, now, id) then return end
if far ~= nil and not near and A.blink(hero, enemy, now, left, far) then return end
end
end
end
end
function A.isControlName(name, words)
for _, word in ipairs(words) do
if A.matches(word, name) then return true end
end
return false
end
function A.learn(entity, modifier)
if not S.ready or UI.store == nil then return end
local hero = Heroes.GetLocal()
if hero == nil or entity == nil or entity == hero or Entity.IsSameTeam(hero, entity) or not Entity.IsHero(entity) then return end
local okCaster, caster = pcall(Modifier.GetCaster, modifier)
if not okCaster or caster ~= hero then return end
local name = Modifier.GetName(modifier)
if not A.isControlName(name, C.learnWords) then return end
local okAbility, ability = pcall(Modifier.GetAbility, modifier)
if not okAbility or ability == nil then return end
local abilityName = Ability.GetName(ability)
local duration = Modifier.GetDuration(modifier)
if type(duration) ~= "number" or duration <= 0 then duration = Modifier.GetDieTime(modifier) - Modifier.GetCreationTime(modifier) end
if type(duration) ~= "number" or duration < 0.2 or duration > C.maxDur then return end
local delay = 0
local seen = S.cast[abilityName]
if seen ~= nil and Modifier.GetCreationTime(modifier) - seen.time >= 0 and Modifier.GetCreationTime(modifier) - seen.time < 3 then
delay = Modifier.GetCreationTime(modifier) - seen.time
end
local old = S.learned[abilityName]
local top = math.max(old ~= nil and (old.max or old.dur) or 0, duration)
local best = old == nil and duration or math.max(duration >= old.dur and duration or old.dur * 0.85 + duration * 0.15, top * 0.5)
local entry = { dur = best, max = top, delay = delay > 0 and delay or (old ~= nil and old.delay or 0), bias = old ~= nil and old.bias or 0, speed = old ~= nil and old.speed or nil, cat = old ~= nil and old.cat or A.modCat(name) }
local changed = old == nil or math.abs(old.dur - best) > 0.05 or (delay > 0 and math.abs((old.delay or 0) - delay) > 0.05)
local id = Entity.GetIndex(entity)
local plan = S.pending[id]
local shared = A.shared()
if (plan == nil or plan.name ~= abilityName) and shared ~= nil and type(shared.plan) == "table" then
local theirs = shared.plan[id]
if theirs ~= nil and theirs.name == abilityName then
plan = theirs
shared.plan[id] = nil
end
end
if plan ~= nil and plan.name == abilityName then
local err = Modifier.GetCreationTime(modifier) - plan.endAt
if plan.sched and err > -3 and err < 3 then
local bias = math.min(C.biasMax, math.max(0, entry.bias + (err > 0 and err * 0.8 + 0.01 or (err < -0.2 and (err + 0.2) * 0.5 or 0))))
if math.abs(bias - entry.bias) >= 0.005 then
entry.bias = bias
changed = true
end
A.log("info", "chain control gap", { control = abilityName, gap_ms = math.floor(err * 1000), bias_ms = math.floor(entry.bias * 1000) })
end
S.pending[Entity.GetIndex(entity)] = nil
end
if seen ~= nil and seen.dist ~= nil and delay > 0 and DATA.abilities[abilityName] == nil then
local travel = delay - math.max(0, Ability.GetCastPoint(ability)) - A.latencySec() * 2 - 0.06
if travel > 0.15 and seen.dist > 300 then
local speed = math.min(C.speedMax, math.max(C.speedMin, seen.dist / travel))
if entry.speed == nil or math.abs(entry.speed - speed) > 100 then
entry.speed = speed
changed = true
end
end
end
if changed then
S.learned[abilityName] = entry
S.listAt = -10
A.save()
A.publishLearned()
A.log("info", "chain control learned", { ability = abilityName, dur = duration, delay = delay })
end
end
function A.watchOrder(data)
local hero = Heroes.GetLocal()
if hero == nil or data == nil or data.ability == nil or data.npc ~= hero then return end
local name = Ability.GetName(data.ability)
local now = GameRules.GetGameTime()
S.cast[name] = { time = now, enemy = data.target ~= nil and Entity.GetIndex(data.target) or nil }
if data.target ~= nil and not Entity.IsSameTeam(hero, data.target) then
for _, control in ipairs(S.list) do
if control.name == name then
S.guard[Entity.GetIndex(data.target)] = now + A.delay(control, hero, data.target) + 0.1
end
end
end
end
function A.syncHeroes(now)
local hero = Heroes.GetLocal()
if hero == nil then return end
local names, seen = {}, {}
for _, unit in ipairs(Heroes.GetAll() or {}) do
if unit ~= nil and unit ~= hero and not Entity.IsSameTeam(hero, unit) and not NPC.IsIllusion(unit) then
local name = NPC.GetUnitName(unit)
if not seen[name] then
seen[name] = true
names[#names + 1] = name
end
end
end
if #names == 0 then return end
table.sort(names)
local sig = table.concat(names, "|")
if sig ~= S.heroSig then
S.heroSig, S.heroTries, S.heroAt = sig, C.heroTries, 0
end
if S.heroTries <= 0 or now < S.heroAt then return end
S.heroTries = S.heroTries - 1
S.heroAt = now + C.heroRetry
local rows, selected, tips = {}, {}, {}
for index, name in ipairs(names) do
local label = A.heroLabel(name)
local on = S.heroPref[label] ~= false
rows[index] = { label, "panorama/images/heroes/icons/" .. name .. "_png.vtex_c", on }
tips[index] = label
if on then selected[#selected + 1] = label end
end
UI.heroes:Update(rows, true, true)
UI.heroes:Set(selected)
pcall(UI.heroes.UpdateToolTips, UI.heroes, tips)
end
function A.drawToasts(now)
if #S.toasts == 0 or S.font == nil then return end
local duration = UI.notifyDur:Get()
local live = {}
for _, toast in ipairs(S.toasts) do
if now - toast.at < duration then live[#live + 1] = toast end
end
S.toasts = live
local screen = Render.ScreenSize()
for _, place in ipairs({ { S.typeTop, 0.12 }, { S.typeSide, 0.4 } }) do
if UI.notifyType:Get(place[1]) then
for index, toast in ipairs(live) do
local size = Render.TextSize(S.font, 14, toast.text)
local w, h = size.x + 24, size.y + 12
local fade = math.min(1, (duration - (now - toast.at)) / 0.4)
local x = place[2] < 0.2 and (screen.x - w) / 2 or screen.x - w - 20
local y = screen.y * place[2] + (index - 1) * (h + 6)
Render.FilledRect(Vec2(x, y), Vec2(x + w, y + h), Color(20, 20, 24, math.floor(235 * fade)), 4)
Render.Text(S.font, 14, toast.text, Vec2(x + 12, y + 6), Color(230, 230, 235, math.floor(245 * fade)))
end
end
end
end
function A.draw()
local now = GameRules.GetGameTime()
A.syncHeroes(now)
A.drawToasts(now)
end
function A.drawError()
local title = S.menuError and localization.Get("panel.menu_failed") or localization.Get("panel.error")
local message = S.menuError or S.error or S.drawError or "unknown"
Render.FilledRect(Vec2(20, 730), Vec2(780, 778), Color(20, 20, 24, 235), 4)
Render.Text(S.font, 14, title, Vec2(30, 737), Color(224, 50, 45, 245))
Render.Text(S.font, 12, message:sub(1, 160), Vec2(30, 757), Color(220, 220, 225, 240))
end
function A.initMenu()
