local C = {
itemSlots = { 0, 1, 2, 3, 4, 5, 16 },
abilitySlots = 24,
stateImmune = type(Enum) == "table" and type(Enum.ModifierState) == "table" and Enum.ModifierState.MODIFIER_STATE_MAGIC_IMMUNE or 9,
stateInvuln = type(Enum) == "table" and type(Enum.ModifierState) == "table" and Enum.ModifierState.MODIFIER_STATE_INVULNERABLE or 8,
sideLeft = type(Enum) == "table" and type(Enum.GroupSide) == "table" and Enum.GroupSide.Left,
gap = 0.2,
enemyGap = 0.1,
damagePhysical = type(Enum) == "table" and type(Enum.DamageTypes) == "table" and Enum.DamageTypes.DAMAGE_TYPE_PHYSICAL or 1,
damagePure = type(Enum) == "table" and type(Enum.DamageTypes) == "table" and Enum.DamageTypes.DAMAGE_TYPE_PURE or 4,
bUnit = type(Enum) == "table" and type(Enum.AbilityBehavior) == "table" and Enum.AbilityBehavior.DOTA_ABILITY_BEHAVIOR_UNIT_TARGET or 8,
barHalf = 84,
barMid = 20,
hold = 0.35,
overlayGap = 2,
overlay = {
groups = { "Item overlay", "Оверлей предметов" },
align = { "Align", "Выровнять" },
enable = { "Enable", "Включить" },
},
linkenItems = { "sphere" },
linkenMod = "modifier_item_sphere_target",
guards = { aeon = "aeon_disk", bkb = "black_king_bar", lotus = "lotus_orb" },
}
local UI = {}
local S = {
ready = false,
menuError = nil,
error = nil,
font = nil,
cache = {},
shown = {},
debugAt = {},
overlayAt = -10,
overlayAlign = nil,
enemiesAt = 0,
enemyList = {},
}
local INK, BONE = Color(12, 12, 14, 235), Color(244, 244, 246, 255)
local A = {}
function A.log(level, message, data)
if type(ai_bridge) == "table" and type(ai_bridge.mcp_log) == "function" then
pcall(ai_bridge.mcp_log, level, message, data)
end
end
function A.has(mask, bit)
return type(mask) == "number" and math.floor(mask / bit) % 2 == 1
end
function A.at(list, level)
if type(list) ~= "table" or #list == 0 then return 0 end
return list[math.min(math.max(level, 1), #list)] or 0
end
function A.base(name)
return (name:gsub("^item_", ""):gsub("_custom$", ""))
end
function A.attributes(hero)
local ok1, int = pcall(Hero.GetIntellectTotal, hero)
local ok2, str = pcall(Hero.GetStrengthTotal, hero)
local ok3, agi = pcall(Hero.GetAgilityTotal, hero)
int, str, agi = ok1 and int or 0, ok2 and str or 0, ok3 and agi or 0
local ok4, primary = pcall(Hero.GetPrimaryAttribute, hero)
local main = primary == 0 and str or primary == 1 and agi or primary == 2 and int or math.max(str, agi, int)
if not ok4 then main = math.max(str, agi, int) end
return int, str, agi, main
end
function A.enemyItems(enemy)
local out = {}
for _, slot in ipairs(C.itemSlots) do
local item = NPC.GetItemByIndex(enemy, slot)
if item ~= nil then out[#out + 1] = item end
end
return out
end
function A.guards(enemy)
local found = { linken = false, aeon = false, bkb = false, lotus = false }
if NPC.HasModifier(enemy, C.linkenMod) then found.linken = true end
for _, item in ipairs(A.enemyItems(enemy)) do
local base = A.base(Ability.GetName(item))
local ready = Ability.GetCooldown(item) <= 0
if ready then
for _, key in ipairs(C.linkenItems) do
if base:find(key, 1, true) ~= nil then found.linken = true end
end
for name, key in pairs(C.guards) do
if base == key then found[name] = true end
end
end
end
return found
end
function A.amp(hero)
local seen, total = {}, 0
for _, slot in ipairs(C.itemSlots) do
local item = NPC.GetItemByIndex(hero, slot)
if item ~= nil then
local name = Ability.GetName(item)
local entry = DATA.items[name]
if entry ~= nil and entry.amp ~= nil and not seen[name] then
seen[name] = true
total = total + entry.amp
end
end
end
return total / 100 + UI.amp:Get() / 100
end
function A.burst(entry, level, ctx)
local d, dps = A.at(entry.d, level), A.at(entry.dps, level)
local du, iv, tk = A.at(entry.du, level), A.at(entry.iv, level), A.at(entry.tk, level)
local sc = 0
if entry.scale ~= nil then
sc = A.at(entry.scale.i, level) * ctx.int + A.at(entry.scale.s, level) * ctx.str + A.at(entry.scale.a, level) * ctx.agi
+ A.at(entry.scale.p, level) * ctx.main
end
local sps = 0
if entry.sd ~= nil then
sps = A.at(entry.sd.i, level) * ctx.int + A.at(entry.sd.s, level) * ctx.str + A.at(entry.sd.a, level) * ctx.agi
end
local lo, hi
if dps > 0 then
local span = du > 0 and math.min(du, ctx.window) or 1
lo = (dps + sps) * span + d + sc
hi = lo
elseif d > 0 or sc > 0 then
local per = d + sc
local count = 1
if tk > 1 then
local span = du > 0 and du or tk
count = math.min(tk, math.floor(ctx.window / math.max(span / tk, 0.05)) + 1)
elseif iv >= 0.25 and du > 0 then
count = math.min(math.floor(du / iv), math.floor(ctx.window / iv) + 1)
end
lo = per
hi = per * math.max(count, 1)
else
lo, hi = 0, 0
end
if entry.ph ~= nil then hi = hi + A.at(entry.ph, level) / 100 * ctx.maxHp end
if entry.tf ~= nil then hi = hi + entry.tf end
return lo, hi
end
function A.mitigate(entry, lo, hi, ctx)
if ctx.invuln then return 0, 0 end
if ctx.immune and not entry.pierce then return 0, 0 end
local factor = entry.ty == "M" and ctx.magic or entry.ty == "P" and ctx.physical or 1
local amp = 1 + ctx.amp
return lo * factor * amp, hi * factor * amp
end
function A.barriers(enemy)
local ok, bars = pcall(NPC.GetBarriers, enemy)
local out = { physical = 0, magic = 0, all = 0 }
if not ok or type(bars) ~= "table" then return out end
for key in pairs(out) do
local bar = bars[key]
local value = type(bar) == "table" and bar.current or 0
if type(value) == "number" and value > 0 then out[key] = value end
end
return out
end
function A.absorb(total, by, bars)
local magic = math.min(by.M, bars.magic)
local physical = math.min(by.P, bars.physical)
local rest = total - magic - physical
return math.max(0, rest - math.min(rest, bars.all))
end
function A.fallbackEntry(ability)
local ok, damage = pcall(Ability.GetDamage, ability)
if not ok or type(damage) ~= "number" or damage <= 0 then return nil end
local kind = Ability.GetDamageType(ability)
return {
ty = kind == C.damagePhysical and "P" or kind == C.damagePure and "U" or "M", known = false, d = { damage },
mana = { Ability.GetManaCost(ability) }, behavior = A.has(Ability.GetBehavior(ability), C.bUnit) and "u" or "p",
}
end
function A.collect(hero, ctx)
local list = {}
local wait = UI.wait:Get()
for slot = 0, C.abilitySlots - 1 do
local ability = NPC.GetAbilityByIndex(hero, slot)
if ability ~= nil then
local name = Ability.GetName(ability)
local entry = DATA.abilities[name] or A.fallbackEntry(ability)
local level = Ability.GetLevel(ability)
if entry ~= nil and level > 0 and not Ability.IsHidden(ability) and Ability.GetCooldown(ability) <= wait then
local lo, hi = A.burst(entry, level, ctx)
lo, hi = A.mitigate(entry, lo, hi, ctx)
if hi > 0 then
list[#list + 1] = { name = name, kind = "spell", ty = entry.ty, lo = lo, hi = hi, mana = A.at(entry.mana, level), unit = entry.behavior == "u", known = entry.known }
end
end
end
end
for _, slot in ipairs(C.itemSlots) do
local item = NPC.GetItemByIndex(hero, slot)
if item ~= nil then
local name = Ability.GetName(item)
local data = DATA.items[name]
if data ~= nil and data.act ~= nil and Ability.GetCooldown(item) <= wait then
local level = math.max(1, Ability.GetLevel(item))
local lo, hi = A.burst(data.act, level, ctx)
lo, hi = A.mitigate(data.act, lo, hi, ctx)
if hi > 0 then
list[#list + 1] = { name = name, kind = "item", ty = data.act.ty, lo = lo, hi = hi, mana = A.at(data.act.mana, level), unit = data.act.behavior == "u", known = data.act.known }
end
end
end
end
return list
end
function A.calc(hero, enemy)
local int, str, agi, main = A.attributes(hero)
local window = UI.window:Get()
local ctx = {
int = int, str = str, agi = agi, main = main, window = window, amp = A.amp(hero),
maxHp = math.max(1, Entity.GetMaxHealth(enemy)),
magic = NPC.GetMagicalArmorDamageMultiplier(enemy),
physical = NPC.GetArmorDamageMultiplier(enemy),
immune = NPC.HasState(enemy, C.stateImmune),
invuln = NPC.HasState(enemy, C.stateInvuln),
}
local list = A.collect(hero, ctx)
local guards = A.guards(enemy)
table.sort(list, function(a, b) return a.lo > b.lo end)
local mana = NPC.GetMana(hero)
local rows, lo, hi = {}, 0, 0
local loBy, hiBy = { M = 0, P = 0, U = 0 }, { M = 0, P = 0, U = 0 }
local linkenCut = nil
if guards.linken then
for _, row in ipairs(list) do
if row.unit and (linkenCut == nil or row.lo < linkenCut.lo) then linkenCut = row end
end
end
for _, row in ipairs(list) do
if mana >= row.mana then
mana = mana - row.mana
if row == linkenCut then
row.note = "linken"
else
lo = lo + row.lo
hi = hi + row.hi
local ty = row.ty == "M" and "M" or row.ty == "P" and "P" or "U"
loBy[ty], hiBy[ty] = loBy[ty] + row.lo, hiBy[ty] + row.hi
end
rows[#rows + 1] = row
else
row.note = "mana"
rows[#rows + 1] = row
end
end
local attacks = UI.attacks:Get()
if attacks > 0 and not ctx.invuln then
local hit = NPC.GetTrueDamage(hero) * ctx.physical
if hit > 0 then
lo = lo + hit * attacks
hi = hi + hit * attacks
loBy.P, hiBy.P = loBy.P + hit * attacks, hiBy.P + hit * attacks
rows[#rows + 1] = { name = "attack", kind = "attack", lo = hit * attacks, hi = hit * attacks, count = attacks, known = true }
end
end
local hp = Entity.GetHealth(enemy)
local bars = A.barriers(enemy)
local loNet, hiNet = A.absorb(lo, loBy, bars), A.absorb(hi, hiBy, bars)
local need = hp * (1 + UI.margin:Get() / 100)
local verdict = loNet >= need and "kill" or hiNet >= hp and "maybe" or "no"
return {
hp = hp, max = ctx.maxHp, lo = lo, hi = hi, rows = rows, verdict = verdict, guards = guards,
immune = ctx.immune, invuln = ctx.invuln, short = math.max(0, hp - hiNet), barrier = bars.physical + bars.magic + bars.all,
}
end
function A.result(hero, enemy, now)
local id = Entity.GetIndex(enemy)
local hit = S.cache[id]
if hit ~= nil and now - hit.at < C.gap then return hit.value end
local value = A.calc(hero, enemy)
if hit == nil then
S.cache[id] = { at = now, value = value }
else
hit.at, hit.value = now, value
end
return value
end
function A.enemies(hero, now)
if now < S.enemiesAt then return S.enemyList end
S.enemiesAt = now + C.enemyGap
local list = {}
S.enemyList = list
local origin = Entity.GetAbsOrigin(hero)
local range = UI.range:Get()
for _, unit in ipairs(Heroes.GetAll() or {}) do
if unit ~= nil and unit ~= hero and not Entity.IsSameTeam(hero, unit) and Entity.IsAlive(unit)
and not Entity.IsDormant(unit) and not NPC.IsIllusion(unit) and (Entity.GetAbsOrigin(unit) - origin):Length2D() <= range then
list[#list + 1] = unit
end
end
return list
end
function A.overlayItemsAlign(now)
if now < S.overlayAt then return S.overlayAlign end
S.overlayAt = now + C.overlayGap
S.overlayAlign = nil
for i = 1, #C.overlay.groups do
local ok, align = pcall(Menu.Find, "Scripts", "1x6", "Hero Overlay", "Main", C.overlay.groups[i], C.overlay.align[i])
if ok and align ~= nil then
local okSwitch, switch = pcall(Menu.Find, "Scripts", "1x6", "Hero Overlay", "Main", C.overlay.groups[i], C.overlay.enable[i])
if not okSwitch or switch == nil or switch:Get() then S.overlayAlign = align:Get() end
break
end
end
return S.overlayAlign
end
function A.skullSide(now)
local mode = UI.side:Get()
if mode == 1 then return -1 end
if mode == 2 then return 1 end
local align = A.overlayItemsAlign(now)
if align == 0 or align == nil then return -1 end
if align == 1 then return 1 end
return 1
end
function A.paintSkull(cx, cy, size)
local r = size * 0.5
local ink, bone = INK, BONE
local head = Vec2(cx, cy - r * 0.12)
Render.FilledCircle(head, r + 2, ink)
Render.FilledRect(Vec2(cx - r * 0.6 - 2, cy + r * 0.3), Vec2(cx + r * 0.6 + 2, cy + r + 2), ink, 3)
Render.FilledCircle(head, r, bone)
Render.FilledRect(Vec2(cx - r * 0.6, cy + r * 0.3), Vec2(cx + r * 0.6, cy + r), bone, 3)
Render.FilledCircle(Vec2(cx - r * 0.38, cy - r * 0.18), r * 0.25, ink)
Render.FilledCircle(Vec2(cx + r * 0.38, cy - r * 0.18), r * 0.25, ink)
Render.FilledTriangle({ Vec2(cx, cy + r * 0.02), Vec2(cx - r * 0.13, cy + r * 0.3), Vec2(cx + r * 0.13, cy + r * 0.3) }, ink)
for k = -1, 1 do
Render.Line(Vec2(cx + k * r * 0.24, cy + r * 0.52), Vec2(cx + k * r * 0.24, cy + r * 0.98), ink, 1)
end
end
function A.drawSkull(enemy, now)
local sp, visible = Render.WorldToScreen(Entity.GetAbsOrigin(enemy) + Vector(0, 0, NPC.GetHealthBarOffset(enemy)))
if not visible then return end
local size = UI.size:Get()
local side = A.skullSide(now)
local cx = sp.x + side * (C.barHalf + UI.gap:Get() + size * 0.5)
A.paintSkull(math.floor(cx + 0.5), math.floor(sp.y - C.barMid + 0.5), size)
end
function A.debugText(enemy, result, now)
local sp, visible = Render.WorldToScreen(Entity.GetAbsOrigin(enemy) + Vector(0, 0, NPC.GetHealthBarOffset(enemy)))
if visible then
local text = string.format("%d..%d / %d  [%d]", math.floor(result.lo + 0.5), math.floor(result.hi + 0.5), math.floor(result.hp + 0.5), #result.rows)
local ts = Render.TextSize(S.font, 12, text)
Render.Text(S.font, 12, text, Vec2(sp.x - ts.x / 2 + 1, sp.y + 13), Color(0, 0, 0, 230))
Render.Text(S.font, 12, text, Vec2(sp.x - ts.x / 2, sp.y + 12), Color(250, 220, 90, 255))
end
local id = Entity.GetIndex(enemy)
if now >= (S.debugAt[id] or 0) then
S.debugAt[id] = now + 4
local names = {}
for _, row in ipairs(result.rows) do
names[#names + 1] = string.format("%s=%d..%d%s", row.name, math.floor(row.lo + 0.5), math.floor(row.hi + 0.5), row.note and ("(" .. row.note .. ")") or "")
end
A.log("info", "damage calc", { enemy = NPC.GetUnitName(enemy), hp = math.floor(result.hp), lo = math.floor(result.lo), hi = math.floor(result.hi),
verdict = result.verdict, immune = result.immune, rows = table.concat(names, ", "):sub(1, 400) })
end
end
function A.draw()
if not S.ready or not UI.enabled:Get() or not Engine.IsInGame() then return end
local hero = Heroes.GetLocal()
if hero == nil or not Entity.IsAlive(hero) then return end
local now = GameRules.GetGameTime()
for _, enemy in ipairs(A.enemies(hero, now)) do
local id = Entity.GetIndex(enemy)
local result = A.result(hero, enemy, now)
if result.verdict == "kill" or (UI.mode:Get() == 1 and result.verdict == "maybe") then S.shown[id] = now end
if S.shown[id] ~= nil and now - S.shown[id] <= C.hold then A.drawSkull(enemy, now) end
if UI.debug:Get() then A.debugText(enemy, result, now) end
end
end
function A.drawError()
local title = S.menuError and localization.Get("panel.menu_failed") or localization.Get("panel.error")
local message = S.menuError or S.error or "unknown"
Render.FilledRect(Vec2(20, 670), Vec2(780, 718), Color(20, 20, 24, 235), 4)
Render.Text(S.font, 14, title, Vec2(30, 677), Color(224, 50, 45, 245))
Render.Text(S.font, 12, message:sub(1, 160), Vec2(30, 697), Color(220, 220, 225, 240))
end
