end
function script.OnScriptsLoaded()
local ok, result = pcall(A.initMenu)
S.ready = ok and result == true
if not S.ready then S.menuError = ok and "initMenu returned false" or tostring(result) end
local aa = type(Enum) == "table" and type(Enum.FontCreate) == "table" and Enum.FontCreate.FONTFLAG_ANTIALIAS or 0
S.font = Render.LoadFont("MuseoSansEx", aa, 500)
A.log("info", "x6_damage_calc loaded", { ready = S.ready, error = S.menuError })
end
function script.OnGameEnd()
S.cache, S.shown, S.debugAt = {}, {}, {}
S.enemiesAt, S.enemyList = 0, {}
end
function script.OnDraw()
if S.menuError ~= nil or S.error ~= nil then
pcall(A.drawError)
return
end
local ok, err = pcall(A.draw)
if not ok then
S.error = tostring(err)
A.log("error", "damage calc failed", { error = S.error })
end
end
return script
end)
