function A.ready(ability, hero)
return ability ~= nil and Ability.GetLevel(ability) > 0 and Ability.IsReady(ability)
and Ability.GetCooldown(ability) <= 0 and Ability.IsCastable(ability, NPC.GetMana(hero))
end
function A.settle()
local ok, latency = false, nil
if C.latency ~= nil then ok, latency = pcall(C.latency) end
if not ok or type(latency) ~= "number" or latency < 0 then latency = 0.1 end
return math.max(C.settleMin, math.min(C.settleMax, latency * 2 + C.settlePad))
end
function A.pickTarget(hero)
local target = nil
if C.cursorHero then
local ok, value = pcall(C.cursorHero, Entity.GetTeamNum(hero), C.teamEnemy)
if ok then target = value end
end
if target and A.valid(target) and not Entity.IsSameTeam(hero, target) and not NPC.IsIllusion(target)
and A.distance(hero, target) <= UI.range:Get() then
return target
end
local cursor = C.cursorPos and C.cursorPos() or Entity.GetAbsOrigin(hero)
local best, bestDistance = nil, math.huge
for _, enemy in ipairs(Heroes.GetAll()) do
if enemy ~= hero and A.valid(enemy) and not Entity.IsSameTeam(hero, enemy) and not NPC.IsIllusion(enemy)
and A.distance(hero, enemy) <= UI.range:Get() then
local distance = (Entity.GetAbsOrigin(enemy) - cursor):Length2D()
if distance < bestDistance then
best, bestDistance = enemy, distance
end
end
end
return best
end
function A.updateRunTrack(unit, now)
local id = Entity.GetIndex(unit)
local pos = Entity.GetAbsOrigin(unit)
local track = S.enemyTrack[id]
if track ~= nil and now - track.last_time > C.trackReset then track = nil end
track = track or {
last_pos = pos,
last_time = now,
vel = Vector(0, 0, 0),
normal_speed = NPC.GetMoveSpeed(unit),
}
local dt = math.max(0.016, now - track.last_time)
local raw = (pos - track.last_pos) / dt
track.vel = raw * 0.58 + track.vel * 0.42
track.last_pos = pos
track.last_time = now
S.enemyTrack[id] = track
if not NPC.HasState(unit, C.stunned) and A.speedModifierLeft(unit, now) == nil then
track.normal_speed = NPC.GetMoveSpeed(unit)
end
end
function A.speedModifierLeft(unit, now)
local track = S.enemyTrack[Entity.GetIndex(unit)]
if track and track.speed_scan_at and now - track.speed_scan_at < 0.04 then return track.speed_left end
local best, generic = nil, nil
for _, modifier in ipairs(NPC.GetModifiers(unit) or {}) do
if not Modifier.IsDebuff(modifier) then
local name = Modifier.GetName(modifier):lower()
local left = Modifier.GetDieTime(modifier) - now
if left > 0.02 and left <= C.prediction.max_lead + 1
and (generic == nil or left < generic) then
generic = left
end
for _, word in ipairs(SPEED_WORDS) do
if name:find(word, 1, true) ~= nil then
if left > 0.02 and left <= C.prediction.max_lead + 1
and (best == nil or left < best) then
best = left
end
break
end
end
end
end
if best == nil and track and track.normal_speed
and NPC.GetMoveSpeed(unit) > track.normal_speed * C.prediction.boost_ratio then
best = generic or C.prediction.boost_fallback
end
if track then
track.speed_scan_at = now
track.speed_left = best
end
return best
end
function A.predictionDistance(unit, time, speed)
local lead = math.min(time, C.prediction.max_lead)
local now = GameRules.GetGameTime()
local boost_left = A.speedModifierLeft(unit, now)
if boost_left == nil or boost_left >= lead then return speed * lead end
local track = S.enemyTrack[Entity.GetIndex(unit)]
local normal = track and track.normal_speed or NPC.GetBaseSpeed(unit)
normal = math.min(speed, math.max(0, normal))
return speed * boost_left + normal * (lead - boost_left)
end
function A.movementVector(unit)
local track = S.enemyTrack[Entity.GetIndex(unit)]
local vel = track and track.vel or Vector(0, 0, 0)
local speed = vel:Length2D()
local move_speed = NPC.GetMoveSpeed(unit)
local forward = Entity.GetRotation(unit):GetForward():Normalized()
local run_vel = forward * move_speed
if speed > move_speed then
vel = vel:Normalized() * move_speed
speed = move_speed
end
if NPC.IsRunning(unit) then
if speed > 80 then
local align = vel:Normalized():Dot2D(forward)
if align > 0.35 then
local blend = math.max(0, math.min(1, (align - 0.35) / 0.65))
local blended = vel * (0.45 + blend * 0.2) + run_vel * (0.55 - blend * 0.2)
return blended, math.min(blended:Length2D(), move_speed)
end
end
return run_vel, move_speed
end
if speed > 18 then return vel * 0.35, speed * 0.35 end
return Vector(0, 0, 0), 0
end
function A.predictRun(unit, time)
local pos = Entity.GetAbsOrigin(unit)
time = IT.moveTime(unit, time, GameRules.GetGameTime())
if time <= 0.02 then return pos end
local vel, speed = A.movementVector(unit)
if speed <= 10 then return pos end
return pos + vel:Normalized() * A.predictionDistance(unit, time, speed)
end
function A.order(hero, kind, point, target, ability, fast)
local player = Players.GetLocal()
if player == nil then return end
S.lastAct = GameRules.GetGameTime()
Player.PrepareUnitOrders(player, kind, target, point, ability, C.issuer, hero, false, true, false, fast, C.identifier)
end
function A.idle(hero, target, now)
local id = Entity.GetIndex(target)
if S.attacking == id and now - (S.attackAt or 0) < C.attackRefresh then return end
A.order(hero, C.orderAttack, Entity.GetAbsOrigin(target), target, nil, true)
S.attacking = id
S.attackAt = now
end
function A.holdLeft(target, now)
local held = false
for _, state in ipairs(C.holdStates) do
if NPC.HasState(target, state) then held = true end
end
local left = 0
for _, mod in ipairs(NPC.GetModifiers(target) or {}) do
local name = Modifier.GetName(mod)
for _, word in ipairs(C.holdWords) do
if name:find(word, 1, true) ~= nil then
local rest = Modifier.GetDieTime(mod) - now
if rest > left then left = rest end
held = true
end
end
end
if not held then return 0 end
return left
end
function A.meteorPoint(target, item, now)
local delay, radius = C.meteorDelay, C.meteorRadius
if C.special ~= nil then
local ok, value = pcall(C.special, item, "max_duration", -1)
if ok and type(value) == "number" and value > 0 then delay = value end
ok, value = pcall(C.special, item, "impact_radius", -1)
if ok and type(value) == "number" and value > 0 then radius = value end
end
delay = IT.itemFall(item, delay)
local reach = radius - NPC.GetHullRadius(target) - C.meteorMargin
local fall = delay + math.max(0, IT.castPoint(item)) + A.settle() * 0.5
local free = math.max(0, fall - A.holdLeft(target, now))
if NPC.GetMoveSpeed(target) * free <= reach then return Entity.GetAbsOrigin(target) end
return nil
end
function A.itemBase(name)
return (name:gsub("^item_", ""):gsub("_custom$", ""))
end
function A.itemLabel(name)
return (A.itemBase(name):gsub("_", " "))
end
function A.itemIcon(name)
local base = A.itemBase(name)
return "panorama/images/items/" .. (ICON_FIX[base] or base) .. "_png.vtex_c"
end
function A.itemSkipped(name)
for _, fragment in ipairs(ITEM_SKIP) do
if name:find(fragment, 1, true) ~= nil then return true end
end
return false
end
function A.has(value, bit)
return type(value) == "number" and bit > 0 and math.floor(value / bit) % 2 >= 1
end
function A.itemKind(item)
local behavior = Ability.GetBehavior(item)
if A.has(behavior, C.bPassive) or A.has(behavior, C.bHidden) or A.has(behavior, C.bToggle) then return nil end
if A.has(behavior, C.bUnit) then
local team = Ability.GetTargetTeam(item)
if A.has(team, C.targetEnemy) then return "enemy" end
if A.has(team, C.targetFriendly) then return "self" end
return nil
end
if A.has(behavior, C.bPoint) then return "point" end
if A.has(behavior, C.bNo) then return "no" end
return nil
end
function A.scanItems(hero)
local labels, ids, signature = {}, {}, ""
for _, slot in ipairs(C.itemSlots) do
local item = NPC.GetItemByIndex(hero, slot)
if item ~= nil then
local name = Ability.GetName(item)
local label = A.itemLabel(name)
if not A.itemSkipped(name) and A.itemKind(item) ~= nil and ids[label] == nil then
labels[#labels + 1] = label
ids[label] = name
signature = signature .. label .. "=" .. name .. ","
end
end
end
return labels, ids, signature
end
function A.refreshItems(hero)
IT.tick()
local labels, ids, signature = A.scanItems(hero)
if signature == S.itemSig then return end
local rank, old, enabled = {}, {}, {}
for i, id in ipairs(UI.items:List()) do
rank[id] = i
old[id] = true
end
for _, id in ipairs(UI.items:ListEnabled()) do enabled[id] = true end
table.sort(labels, function(a, b) return (rank[a] or 1000) < (rank[b] or 1000) end)
local rows, selected = {}, {}
for i, label in ipairs(labels) do
local on = not old[label] or enabled[label] == true
rows[i] = { label, A.itemIcon(ids[label]), on }
if on then selected[#selected + 1] = label end
end
UI.items:Update(rows, true, true)
UI.items:Set(selected)
S.itemSig = signature
S.itemIds = ids
IT.sync(hero, labels, ids, A.itemIcon)
A.log("info", "universal items refreshed", { items = labels, enabled = selected })
end
function A.findItem(hero, label, name)
for _, slot in ipairs(C.itemSlots) do
local item = NPC.GetItemByIndex(hero, slot)
if item ~= nil and Ability.GetName(item) == name then return item end
end
for _, slot in ipairs(C.itemSlots) do
local item = NPC.GetItemByIndex(hero, slot)
if item ~= nil and A.itemLabel(Ability.GetName(item)) == label then return item end
end
return nil
end
function A.isJump(name)
return name:find("blink", 1, true) ~= nil or name:find("fallen_sky", 1, true) ~= nil
end
function A.itemReady(item, hero)
return item ~= nil and Ability.GetLevel(item) > 0 and Ability.IsCastable(item, NPC.GetMana(hero))
end
function A.clampPoint(hero, point, range)
if range <= 0 then return point end
local origin = Entity.GetAbsOrigin(hero)
local dx, dy = point.x - origin.x, point.y - origin.y
local length = math.sqrt(dx * dx + dy * dy)
local cap = math.max(0, range - 25)
if length <= cap or length <= 0 then return point end
local scale = cap / length
return Vector(origin.x + dx * scale, origin.y + dy * scale, point.z)
end
function A.comboReach(hero, ability)
local reach = 0
if ability ~= nil then reach = Ability.GetCastRange(ability) end
for _, label in ipairs(UI.items:ListEnabled()) do
local name = S.itemIds[label]
local item = name ~= nil and not A.isJump(name) and A.findItem(hero, label, name) or nil
if item ~= nil and A.itemReady(item, hero) then
local kind = A.itemKind(item)
if kind == "enemy" or kind == "point" then reach = math.max(reach, Ability.GetCastRange(item) + 75) end
end
end
return reach
end
function A.blinkPoint(hero, target)
local origin = Entity.GetAbsOrigin(hero)
local pos = Entity.GetAbsOrigin(target)
local dx, dy = pos.x - origin.x, pos.y - origin.y
local len = math.max(1, math.sqrt(dx * dx + dy * dy))
local range = NPC.GetAttackRange(hero) + NPC.GetAttackRangeBonus(hero)
local keep = range > 300 and math.max(C.blinkKeep, range - 100) or C.blinkKeep
return Vector(pos.x - dx / len * keep, pos.y - dy / len * keep, pos.z)
end
function A.orderMove(hero, point, now)
if now < S.moveAt then return end
A.order(hero, C.orderMove, point, nil, nil, false)
S.moveAt = now + C.moveGap
end
function A.isMeteor(name)
for _, fragment in ipairs(C.meteorItems) do
if name:find(fragment, 1, true) ~= nil then return true end
end
return false
end
function A.isShiva(name)
return name:find("shivas_guard", 1, true) ~= nil or name:find("gold_shiva", 1, true) ~= nil
end
function A.isHex(name)
return name:find("sheepstick", 1, true) ~= nil or name:find("hex", 1, true) ~= nil
end
function A.shivaHasTarget(hero, item)
local radius = C.shivaRadius
if C.special ~= nil then
local ok, value = pcall(C.special, item, "blast_radius", -1)
if ok and type(value) == "number" and value > 0 then radius = value end
end
for _, enemy in ipairs(Heroes.GetAll()) do
if A.valid(enemy) and not Entity.IsSameTeam(hero, enemy) and not NPC.IsIllusion(enemy)
and A.distance(hero, enemy) <= radius then
return true
end
end
return false
end
function A.blink(hero, target, now)
local distance = A.distance(hero, target)
for _, label in ipairs(UI.items:ListEnabled()) do
local name = S.itemIds[label]
if name ~= nil and A.isJump(name) then
local item = A.findItem(hero, label, name)
if item ~= nil and A.itemReady(item, hero) and IT.allow(hero, target, name, label) then
local range = Ability.GetCastRange(item)
Ability.CastPosition(item, A.clampPoint(hero, A.blinkPoint(hero, target), range), false, false, true, C.identifier)
S.nextAt = now + math.max(0.08, math.max(0, IT.castPoint(item)) + 0.06)
S.attacking = nil
S.lastAct = now
A.say("blink " .. name)
A.log("info", "universal combo blink", { item = name, dist = math.floor(distance) })
return true
end
end
end
return false
end
function A.useItems(hero, target, ability, now)
if now >= S.cycleAt then
S.done = {}
S.cycleAt = now + C.cycleGap
end
local distance = A.distance(hero, target)
if distance > math.max(C.gapMin, A.comboReach(hero, ability) + 100) and A.blink(hero, target, now) then return true end
for _, label in ipairs(UI.items:ListEnabled()) do
local name = S.itemIds[label]
if name ~= nil and not S.done[name] then
local item = A.findItem(hero, label, name)
if item == nil then
S.done[name] = true
elseif not IT.allow(hero, target, name, label) then
elseif A.itemReady(item, hero) then
local kind = A.itemKind(item)
local range = Ability.GetCastRange(item)
local jump = A.isJump(name)
if kind == nil then
S.done[name] = true
elseif jump and distance <= A.comboReach(hero, ability) then
elseif (kind == "no" or kind == "self") and not A.isShiva(name) and distance > C.itemSelfRange then
elseif A.isShiva(name) and not A.shivaHasTarget(hero, item) then
elseif A.isMeteor(name) and A.meteorPoint(target, item, now) == nil then
elseif (kind == "enemy" or kind == "point") and not jump and range > 0 and distance > range + 75 then
A.orderMove(hero, IT.stopPoint(hero, target, range), now)
return true
else
if kind == "enemy" then
Ability.CastTarget(item, target, false, false, true, C.identifier)
elseif kind == "self" then
Ability.CastTarget(item, hero, false, false, true, C.identifier)
elseif kind == "point" and jump then
Ability.CastPosition(item, A.clampPoint(hero, A.blinkPoint(hero, target), range), false, false, true, C.identifier)
elseif kind == "point" then
Ability.CastPosition(item, A.clampPoint(hero, Entity.GetAbsOrigin(target), range), false, false, true, C.identifier)
else
Ability.CastNoTarget(item, false, false, true, C.identifier)
end
S.done[name] = true
S.lastAct = now
local delay = math.max(0.08, math.max(0, IT.castPoint(item)) + 0.06)
if kind == "enemy" and A.isHex(name) then delay = math.max(delay, C.hexWait) end
S.nextAt = now + delay
S.attacking = nil
IT.chainMark(hero, target, name)
A.log("info", "universal combo item", { item = name, kind = kind })
return true
end
end
end
end
return false
end
C.charges = A.api(Ability, "GetCurrentCharges")
C.aoe = A.api(Ability, "GetAOERadius")
function A.castable(ability, hero)
if ability == nil or Ability.GetLevel(ability) <= 0 or Ability.IsHidden(ability) then return false end
if NPC.GetMana(hero) < Ability.GetManaCost(ability) then return false end
local charges = C.charges ~= nil and C.charges(ability) or nil
if type(charges) == "number" and charges >= 1 then return true end
return A.ready(ability, hero)
end
function A.value(ability, key, fallback)
if ability == nil or C.special == nil then return fallback end
local ok, v = pcall(C.special, ability, key, -1)
if ok and type(v) == "number" and v > 0 then return v end
return fallback
end
function A.approach(hero, target, range, now)
if A.distance(hero, target) <= range + C.rangePad then return false end
A.orderMove(hero, IT.stopPoint(hero, target, range), now)
S.attacking = nil
return true
end
function A.castPoint(ability)
local cp = math.max(0, IT.castPoint(ability))
local learned = S.cpLearned[Ability.GetName(ability)]
if learned ~= nil and learned < cp then return learned end
return cp
end
function A.after(ability, now)
local cp = A.castPoint(ability)
S.nextAt = now + math.max(0.1, cp + A.settle())
S.attacking = nil
if cp > C.cpMin then S.cpWatch = { ability = ability, name = Ability.GetName(ability), at = now, phaseAt = nil } end
end
function A.watchCastPoint(now)
local w = S.cpWatch
if w == nil then return end
if now - w.at > C.cpTimeout then
S.cpWatch = nil
return
end
local ok, phase = pcall(Ability.IsInAbilityPhase, w.ability)
if not ok then
S.cpWatch = nil
return
end
if phase then
if w.phaseAt == nil then w.phaseAt = now end
return
end
if w.phaseAt == nil then return end
S.cpWatch = nil
local okCd, cd = pcall(Ability.GetCooldown, w.ability)
if not okCd or cd <= 0 then return end
local took = now - w.phaseAt
local old = S.cpLearned[w.name]
if old == nil or took < old - C.cpStep or took > old + C.cpStep then
S.cpLearned[w.name] = old == nil and took or math.min(took, (old + took) * 0.5)
A.log("info", "cast point learned", { ability = w.name, took = math.floor(took * 1000) / 1000, base = math.floor(math.max(0, IT.castPoint(w.ability)) * 1000) / 1000 })
end
end
C.bVector = C.hasEnum and type(Enum.AbilityBehavior) == "table" and Enum.AbilityBehavior.DOTA_ABILITY_BEHAVIOR_VECTOR_TARGETING or 1073741824
C.sideLeft = C.hasEnum and type(Enum.GroupSide) == "table" and Enum.GroupSide.Left or 0
C.priority = { b = 1, o = 1, c = 2, s = 2, d = 3, m = 4 }
C.orderToggleAuto = C.hasEnum and type(Enum.UnitOrder) == "table" and Enum.UnitOrder.DOTA_UNIT_ORDER_CAST_TOGGLE_AUTO or 20
C.bAuto = C.hasEnum and type(Enum.AbilityBehavior) == "table" and Enum.AbilityBehavior.DOTA_ABILITY_BEHAVIOR_AUTOCAST or 4096
C.bAttack = C.hasEnum and type(Enum.AbilityBehavior) == "table" and Enum.AbilityBehavior.DOTA_ABILITY_BEHAVIOR_ATTACK or 131072
function A.buildHero(npcName, title, side)
local raw = RawMenu.Create("Heroes", "Hero List", title, "1x6 Combo")
local section = localization.Wrap(raw, true)
local main = section:Create("menu.main", side.Left)
local ui = {}
local rows = DATA.heroes[npcName]
ui.enabled = main:Switch("menu.enabled", true, "panorama/images/heroes/icons/" .. npcName .. "_png.vtex_c")
ui.key = main:Bind("menu.key", C.keyF, A.spellIcon(rows[1].n))
ui.key:ToolTip("menu.key_tip")
ui.spells = main:MultiSelect("menu.spells", {}, true)
local spellsReal = type(X6P) == "table" and X6P.widgets[#X6P.widgets] and X6P.widgets[#X6P.widgets].w or nil
ui.spells:ToolTip("menu.spells_tip")
ui.save = main:Input("menu.save_spells", "")
ui.save:Visible(false)
ui.saveOrder = main:Input("menu.save_order", "")
ui.saveOrder:Visible(false)
ui.spells:DragAllowed(true)
if C.rangedHeroes[npcName] then
ui.keep = main:Switch("menu.keep", true, "\u{f21b}")
ui.keep:ToolTip("menu.keep_tip")
end
ui.range = main:Slider("menu.range", 800, 2500, 1500, "%d")
ui.range:Icon("\u{f05b}")
if npcName == "npc_dota_hero_night_stalker" then
ui.orbs = main:Slider("menu.orbs", 1, C.orbMax, C.orbDefault, "%d")
ui.orbs:Icon("\u{f111}")
ui.orbs:ToolTip("menu.orbs_tip")
end
if C.zones[npcName] ~= nil then
ui.zone = main:Switch("menu.zone", true, "\u{f192}")
ui.zone:ToolTip("menu.zone_tip")
end
IT.ui = { heal = {} }
ui.items = IT.build(section, side.Right, A.itemIcon, C.identifier, npcName)
S.menus[npcName] = { ui = ui, itui = IT.ui }
if type(X6P) == "table" then
X6P.panel = X6P.panel or {}
X6P.panel[#X6P.panel + 1] = { heroes = { npcName }, spells = ui.spells, spellsReal = spellsReal, ui = IT.ui, order = true }
end
end
function A.initMenu()
local side = (C.hasEnum and Enum.GroupSide) or {}
local names = {}
for npcName in pairs(DATA.heroes) do names[#names + 1] = npcName end
table.sort(names)
for _, npcName in ipairs(names) do
local ok, err = pcall(A.buildHero, npcName, DATA.titles[npcName] or npcName, side)
if ok then
S.menuCount = S.menuCount + 1
else
S.menuFailed[#S.menuFailed + 1] = npcName .. ": " .. tostring(err)
end
end
if #S.menuFailed > 0 then A.log("error", "universal combo menus failed", { failed = table.concat(S.menuFailed, " | "):sub(1, 400), built = S.menuCount }) end
return S.menuCount > 0
end
function A.activate(npcName)
local menu = S.menus[npcName]
if menu == nil then return false end
for key in pairs(UI) do UI[key] = nil end
for key, value in pairs(menu.ui) do UI[key] = value end
IT.ui = menu.itui
IT.octarine.synced = false
IT.publishKey("universal_1x6_combo", UI.key)
S.itemSig = ""
S.itemAt = 0
return true
end
function A.reset(reason)
if S.phase ~= "idle" then A.log("info", "universal combo stopped", { reason = reason }) end
S.phase = "idle"
S.target = nil
S.startedAt = 0
S.nextAt = 0
S.moveAt = 0
S.attacking = nil
S.done = {}
S.cycleAt = 0
S.lastAct = GameRules.GetGameTime()
end
function A.canon(name)
local row = S.rowOf ~= nil and S.rowOf[name] or nil
return row ~= nil and row.al or name
end
function A.label(name)
local label = A.canon(name):gsub("^custom_", "")
label = label:gsub("_custom", "")
label = label:gsub("_", " ")
return label
end
function A.spellIcon(name)
local base = A.canon(name):gsub("^custom_", ""):gsub("_custom.*$", "")
return "panorama/images/spellicons/" .. base .. "_png.vtex_c"
end
function A.abilityKind(ability)
local behavior = Ability.GetBehavior(ability)
if A.has(behavior, C.bPassive) or A.has(behavior, C.bToggle) or A.has(behavior, C.bVector) then return nil end
if A.has(behavior, C.bUnit) then
local team = Ability.GetTargetTeam(ability)
if A.has(team, C.targetEnemy) then return "unit" end
if A.has(team, C.targetFriendly) then return "self" end
return "unit"
end
if A.has(behavior, C.bPoint) then return "point" end
if A.has(behavior, C.bNo) then return "no" end
return nil
end
function A.say(text)
S.status = text
S.statusAt = GameRules.GetGameTime()
end
function A.heroRows(hero)
local name = Entity.GetUnitName(hero)
if S.heroName ~= name then
S.heroName = name
S.rows = DATA.heroes[name]
S.rowOf = {}
S.spellSig, S.nameSig = "", ""
S.savedMap, S.savedText = nil, nil
S.orderMap, S.orderText = nil, nil
S.groupOf = {}
for _, row in ipairs(S.rows or {}) do
S.rowOf[row.n] = row
if row.al ~= nil then
local group = S.groupOf[row.al]
if group == nil then
group = {}
S.groupOf[row.al] = group
end
group[#group + 1] = row.n
end
end
S.castAt = {}
if S.rows ~= nil and not A.activate(name) then S.rows = nil end
A.log("info", "universal combo hero", { hero = name, data = S.rows ~= nil, abilities = S.rows ~= nil and #S.rows or 0 })
end
return S.rows
end
function A.scanSpells(hero)
local labels, ids, signature, names = {}, {}, "", ""
for slot = 0, C.abilitySlots - 1 do
local ability = NPC.GetAbilityByIndex(hero, slot)
if ability ~= nil then
local name = Ability.GetName(ability)
local row = S.rowOf[name]
if row ~= nil and not Ability.IsHidden(ability) and Ability.GetLevel(ability) > 0 and A.abilityKind(ability) ~= nil then
local label = A.label(name)
if ids[label] == nil then
labels[#labels + 1] = label
ids[label] = name
signature = signature .. label .. ","
names = names .. name .. ","
end
end
end
end
return labels, ids, signature, names
end
function A.defaultOn(row)
return row.r == "c" or row.r == "d" or row.r == "b" or row.r == "s" or row.r == "o" or row.r == "m"
end
function A.loadSaved()
local map = {}
local text = UI.save ~= nil and UI.save:Get() or ""
for name, flag in tostring(text):gmatch("([%w_]+)=([01])") do map[name] = flag == "1" end
return map
end
function A.loadOrder()
local map, n = {}, 0
for name in tostring(UI.saveOrder ~= nil and UI.saveOrder:Get() or ""):gmatch("[%w_]+") do
n = n + 1
map[name] = n
end
return map
end
function A.syncOrder()
if S.orderMap == nil or UI.saveOrder == nil then return end
local names = {}
for _, label in ipairs(UI.spells:List()) do
local name = S.spellIds[label]
if name ~= nil then names[#names + 1] = A.canon(name) end
end
local text = table.concat(names, ",")
if text ~= "" and text ~= S.orderText then
S.orderText = text
UI.saveOrder:Set(text)
end
end
function A.syncSaved()
A.syncOrder()
if S.savedMap == nil then return end
local enabled = {}
for _, id in ipairs(UI.spells:ListEnabled()) do enabled[id] = true end
for label, name in pairs(S.spellIds) do
local row = S.rowOf[name]
if row ~= nil then
local on = enabled[label] == true
local key = A.canon(name)
if on ~= A.defaultOn(row) then S.savedMap[key] = on else S.savedMap[key] = nil end
end
end
local parts = {}
for name, on in pairs(S.savedMap) do parts[#parts + 1] = name .. "=" .. (on and "1" or "0") end
table.sort(parts)
local text = table.concat(parts, "|")
if #text > 1500 then text = text:sub(1, 1500):gsub("|[^|]*$", "") end
if text ~= S.savedText then
S.savedText = text
UI.save:Set(text)
end
end
function A.refreshSpells(hero)
if S.savedMap == nil then
S.savedMap = A.loadSaved()
S.savedText = UI.save:Get()
S.orderMap = A.loadOrder()
S.orderText = UI.saveOrder ~= nil and UI.saveOrder:Get() or ""
end
local labels, ids, signature, names = A.scanSpells(hero)
if signature == S.spellSig then
if names ~= S.nameSig then
S.nameSig, S.spellIds = names, ids
end
A.syncSaved()
return
end
A.syncSaved()
local old, enabled = {}, {}
for _, id in ipairs(UI.spells:List()) do old[id] = true end
for _, id in ipairs(UI.spells:ListEnabled()) do enabled[id] = true end
local pos = {}
for i, id in ipairs(UI.spells:List()) do
local known = S.spellIds[id]
if known ~= nil then pos[A.canon(known)] = i end
end
local seen = next(pos) ~= nil and pos or S.orderMap
local sorted = {}
for i, label in ipairs(labels) do
local name = ids[label]
sorted[i] = { label = label, known = seen[A.canon(name)], rank = C.priority[S.rowOf[name].r] or 3, scan = i }
end
table.sort(sorted, function(a, b)
if (a.known ~= nil) ~= (b.known ~= nil) then return a.known ~= nil end
if a.known ~= nil then return a.known < b.known end
if a.rank ~= b.rank then return a.rank < b.rank end
return a.scan < b.scan
end)
local rows, selected = {}, {}
for i, item in ipairs(sorted) do
local label = item.label
local name = ids[label]
local row = S.rowOf[name]
local on
if old[label] then
on = enabled[label] == true
elseif S.savedMap[A.canon(name)] ~= nil then
on = S.savedMap[A.canon(name)]
else
on = A.defaultOn(row)
end
rows[i] = { label, A.spellIcon(name), on }
if on then selected[#selected + 1] = label end
end
UI.spells:Update(rows, true, true)
UI.spells:Set(selected)
S.spellSig = signature
S.nameSig = names
S.spellIds = ids
A.syncOrder()
A.log("info", "universal combo abilities", { hero = S.heroName, abilities = labels, enabled = selected })
end
function A.verifyCasts(hero, now)
for name, check in pairs(S.castCheck) do
if now - check.at >= C.verifyAfter then
S.castCheck[name] = nil
local ability = check.ability
local okCd, cd = pcall(Ability.GetCooldown, ability)
local okPhase, phase = pcall(Ability.IsInAbilityPhase, ability)
if okCd and cd <= 0 and not (okPhase and phase) and not NPC.IsChannellingAbility(hero) and not A.held(hero, check.target, check.row) then
S.castAt[name] = now + C.verifyBackoff
A.log("info", "universal combo cast ignored", { ability = name })
end
end
end
end
function A.shownOf(hero, group, fallback)
for _, name in ipairs(group) do
local ability = NPC.GetAbility(hero, name)
if ability ~= nil and not Ability.IsHidden(ability) then return name end
end
return fallback
end
function A.variant(row, role)
local v = S.variants[row]
if v == nil then
v = setmetatable({ r = role }, { __index = row })
S.variants[row] = v
end
return v
end
function A.entries(hero)
local list = {}
if NPC.IsSilenced(hero) then return list end
for _, label in ipairs(IT.spellOrder(UI.spells)) do
local name = S.spellIds[label]
local group = name ~= nil and S.groupOf[A.canon(name)] or nil
if group ~= nil then name = A.shownOf(hero, group, name) end
local row = name ~= nil and S.rowOf[name] or nil
local ability = row ~= nil and NPC.GetAbility(hero, name) or nil
if row ~= nil and row.rl == name and ability ~= nil and S.charge == nil and A.abilityKind(ability) == "unit" then
local now = GameRules.GetGameTime()
local mod = row.cm ~= nil and NPC.GetModifier(hero, row.cm) or nil
local since = mod ~= nil and now - Modifier.GetCreationTime(mod) or 0
S.charge = { name = name, release = row.rl, mod = row.cm, at = now - since, full = row.ct or 2.4, dead = (row.mf or 5) - 0.5, speed = row.sp or 2200 }
A.log("info", "universal combo brew adopted", { ability = name, held = math.floor(since * 10) / 10 })
end
local busy = S.charge ~= nil and S.charge.name == name
if ability ~= nil and not busy and not Ability.IsHidden(ability) and (row.r == "o" or A.castable(ability, hero)) then
local kind = A.abilityKind(ability)
if kind ~= nil then
if kind == "no" and row.rn ~= nil then row = A.variant(row, row.rn) end
list[#list + 1] = { h = ability, row = row, kind = kind, name = name, order = #list }
end
end
end
return list
end
function A.stationary(target)
local _, speed = A.movementVector(target)
return speed <= C.stillSpeed
end
function A.chargeRelease(hero, why)
local charge = S.charge
if charge == nil then return false end
local ability = NPC.GetAbility(hero, charge.release)
if ability == nil or (Ability.IsHidden(ability) and charge.release ~= charge.name) then return false end
local now = GameRules.GetGameTime()
if now - (charge.releasedAt or -10) < 0.3 then return true end
if charge.release == charge.name then
local target = S.target
if target == nil or not A.valid(target) then return false end
Ability.CastTarget(ability, target, false, false, true, C.identifier)
else
Ability.CastNoTarget(ability, false, false, true, C.identifier)
end
charge.releasedAt = now
S.lastAct = now
A.say("release " .. charge.release)
A.log("info", "universal combo release", { ability = charge.release, why = why, held = IT.moveLeft(S.target or hero, now) })
return true
end
function A.chargeStep(hero, target, now)
local charge = S.charge
local mod = charge.mod ~= nil and NPC.GetModifier(hero, charge.mod) or nil
local brewing = mod ~= nil
if not brewing and charge.release == charge.name then
local own = NPC.GetAbility(hero, charge.name)
brewing = own ~= nil and A.abilityKind(own) == "unit"
end
if not brewing and now - charge.at > C.chargeStart then
S.charge = nil
return false
end
local elapsed = mod ~= nil and now - Modifier.GetCreationTime(mod) or now - charge.at
if charge.release == charge.name then
local ability = NPC.GetAbility(hero, charge.name)
local range = ability ~= nil and Ability.GetCastRange(ability) or 0
if range <= 0 then range = C.areaDefault end
local ripe = elapsed >= charge.full or elapsed >= charge.dead
if ripe and A.distance(hero, target) <= range + NPC.GetHullRadius(target) then
if A.chargeRelease(hero, elapsed >= charge.dead and "deadline" or "brewed") then return true end
end
A.say(string.format("brew %.1f/%.1f", elapsed, charge.full))
local gap = A.distance(hero, target)
if gap > (ripe and range - 60 or range * 0.8) then
if gap > math.max(C.gapMin, range + 100) and A.blink(hero, target, now) then return true end
if now >= S.moveAt then A.orderMove(hero, Entity.GetAbsOrigin(target), now) end
return true
end
return false
end
local stack = mod ~= nil and Modifier.GetStackCount(mod) or 0
local full = stack >= 100 or (stack <= 0 and elapsed >= charge.full + C.chargePad)
if stack >= 100 and S.chargeTime == nil then
S.chargeTime = elapsed
A.log("info", "universal combo charge time", { ability = charge.release, seconds = math.floor(elapsed * 100) / 100 })
end
local flight = A.distance(hero, target) / charge.speed
local held = IT.moveLeft(target, now)
local hit = held > flight + A.settle()
if full and (hit or elapsed >= charge.dead or (held <= 0 and A.stationary(target))) then
if A.chargeRelease(hero, hit and "held" or elapsed >= charge.dead and "misfire" or "still") then return true end
end
A.say(string.format("charge %d%%", stack))
if now >= S.moveAt then
A.orderMove(hero, A.predictRun(target, flight + A.settle()), now)
end
return true
end
function A.areaRadius(entry)
if C.aoe ~= nil then
local ok, value = pcall(C.aoe, entry.h)
if ok and type(value) == "number" and value > 0 then return value end
end
return A.value(entry.h, "radius", entry.row.ra or C.areaDefault)
end
function A.hasAny(unit, list)
if unit == nil then return false end
for _, mod in ipairs(list) do
local ok, has = pcall(NPC.HasModifier, unit, mod)
if ok and has then return true end
end
return false
end
function A.buffReady(hero, entry, since, dist)
local row, ability = entry.row, entry.h
if row.mo ~= nil and A.hasAny(hero, row.mo) then return false end
if row.sw ~= nil then return dist <= C.fightRange end
local hold = C.buffMin
if row.mo == nil then hold = math.max(C.buffMin, math.min(C.buffMax, row.du or A.value(ability, "duration", C.modeGap))) end
if row.lg then hold = math.max(hold, C.modeGap) end
if since < hold then return false end
local reach = (row.du ~= nil and row.du <= C.shortBuff) and C.shortBuffRange or C.buffRange
if dist > reach then return false end
if row.hl and Entity.GetHealth(hero) > Entity.GetMaxHealth(hero) * C.healBelow then return false end
return true
end
function A.voidReady(target, ability, now)
local per = A.value(ability, "mana_void_damage_per_mana", 0.8)
local missing = math.max(0, NPC.GetMaxMana(target) - NPC.GetMana(target))
local damage = missing * per
local hp = Entity.GetHealth(target)
if damage >= hp or damage >= hp * C.mvShare then return true end
return now - S.startedAt > C.mvWait and damage >= hp * C.mvLate
end
function A.held(hero, target, row)
return row.hm ~= nil and (A.hasAny(hero, row.hm) or (target ~= nil and A.hasAny(target, row.hm)))
end
function A.stacks(unit, name)
local mod = NPC.GetModifier(unit, name)
if mod == nil then return nil end
local ok, count = pcall(Modifier.GetStackCount, mod)
return ok and type(count) == "number" and count or 0
end
function A.orbsReady(hero, since)
local orbs = A.stacks(hero, C.orbTracker)
if orbs == nil then return since >= C.modeGap end
local room = C.orbMax - (A.stacks(hero, C.orbBuff) or 0)
if room <= 0 then return false end
local want = UI.orbs ~= nil and UI.orbs:Get() or C.orbDefault
return orbs >= math.min(want, room)
end
function A.orbOn(hero, entry, now)
local ability = entry.h
local ok, state = pcall(Ability.GetAutoCastState, ability)
if ok and state == true then return end
if now - (S.castAt[entry.name] or -100) < 1.0 then return end
S.castAt[entry.name] = now
S.lastAct = now
A.order(hero, C.orderToggleAuto, nil, nil, ability, false)
A.say("autocast on " .. entry.name)
A.log("info", "universal combo autocast", { ability = entry.name })
end
function A.switchReady(hero, row)
local list = row.sw
local at, shown = nil, nil
for i, name in ipairs(list) do
local ability = NPC.GetAbility(hero, name)
if ability ~= nil and Ability.GetLevel(ability) > 0 and not Ability.IsHidden(ability) then
at, shown = i, ability
break
end
end
if shown == nil or A.castable(shown, hero) then return false end
local following = NPC.GetAbility(hero, list[at % #list + 1])
if following == nil or Ability.GetLevel(following) <= 0 then return false end
return Ability.GetCooldown(following) < Ability.GetCooldown(shown)
end
function A.tryCast(hero, target, entry, now)
local ability, row, kind, name = entry.h, entry.row, entry.kind, entry.name
local since = now - (S.castAt[name] or -100)
if since < C.castGap or S.castCheck[name] ~= nil then return false end
local hull = NPC.GetHullRadius(target)
local dist = A.distance(hero, target)
if A.held(hero, target, row) then return false end
if row.sw ~= nil and not A.switchReady(hero, row) then return false end
if row.ho ~= nil and not A.hasAny(hero, row.ho) then return false end
if row.to ~= nil and not A.hasAny(target, row.to) then return false end
if row.gt == "orbs" then
if not A.orbsReady(hero, since) then return false end
elseif row.r == "b" and not A.buffReady(hero, entry, since, dist) then
return false
end
if row.gt == "mv" and not A.voidReady(target, ability, now) then return false end
if kind ~= "no" and kind ~= "self" and (IT.spellBlocked(target, now, name) or IT.immuneBlocked(target, name)) then return false end
local brew = row.rl ~= nil and row.rl == name
if row.rl ~= nil and not brew then
local need = math.max(C.chargeHold, (S.chargeTime or row.ct or 2.4) * C.chargeShare)
if not (IT.moveLeft(target, now) > need or A.stationary(target) or now - S.startedAt > C.chargeWait) then return false end
end
local cp = math.max(0, A.castPoint(ability))
local lead = cp + A.settle() + (row.dl or 0)
local range = Ability.GetCastRange(ability)
local control = row.r == "c" or row.r == "s"
if kind == "unit" then
if range <= 0 then range = C.areaDefault end
if dist > range + hull + C.rangePad then return "approach", range end
if control and not brew and IT.castEarly(target, now, IT.landLead(hero, target, ability, row.sp, row.dl), true) then return false end
Ability.CastTarget(ability, target, false, false, true, C.identifier)
elseif kind == "self" then
Ability.CastTarget(ability, hero, false, false, true, C.identifier)
elseif kind == "point" then
if range <= 0 then range = C.areaDefault end
local flight = row.sp ~= nil and dist / row.sp or 0
local point = A.predictRun(target, lead + flight)
if (point - Entity.GetAbsOrigin(hero)):Length2D() > range + C.rangePad then return "approach", range end
if control and IT.castEarly(target, now, IT.landLead(hero, target, ability, row.sp, row.dl), true) then return false end
Ability.CastPosition(ability, A.clampPoint(hero, point, range), false, false, true, C.identifier)
else
if brew then
if dist > C.brewStart then return "approach", C.brewStart * 0.8 end
elseif row.r == "b" and row.ra == nil and A.value(ability, "radius", nil) == nil then
if dist > C.fightRange then return false end
else
local radius = A.areaRadius(entry)
if dist > radius + hull - C.areaPad then return "approach", radius * 0.8 end
end
if control and not brew and IT.castEarly(target, now, IT.landLead(hero, target, ability, row.sp, row.dl), true) then return false end
Ability.CastNoTarget(ability, false, false, true, C.identifier)
end
S.castAt[name] = now
S.lastAct = now
A.after(ability, now)
if (row.r == "c" or row.r == "d") and row.rl == nil then S.castCheck[name] = { at = now, ability = ability, row = row, target = target } end
A.say("cast " .. name)
if row.rl ~= nil then
S.charge = { name = name, release = row.rl, mod = row.cm, at = now, full = row.ct or 2.4, dead = (row.mf or 5) - 0.5, speed = row.sp or 2200 }
S.nextAt = now + 0.15
elseif row.ch ~= nil then
S.nextAt = math.max(S.nextAt, now + cp + A.settle() + row.ch)
end
if control and not brew then IT.chainMarkSpell(hero, target, ability) end
A.log("info", "universal combo cast", { ability = name, role = row.r, kind = kind, dist = math.floor(dist) })
return true
end
function A.gapClose(hero, target, entry, now)
local ability, row = entry.h, entry.row
if now - (S.castAt[entry.name] or -100) < C.castGap then return false end
local dist = A.distance(hero, target)
if dist < C.gapMin then return false end
local range = Ability.GetCastRange(ability)
if range <= 0 then range = row.bl or 800 end
if entry.kind == "point" then
local origin, pos = Entity.GetAbsOrigin(hero), Entity.GetAbsOrigin(target)
local stand = math.max(C.gapStand, NPC.GetAttackRange(hero) * 0.7)
local travel = math.min(range, dist - stand)
if travel < 150 then return false end
local point = Vector(origin.x + (pos.x - origin.x) / dist * travel, origin.y + (pos.y - origin.y) / dist * travel, origin.z)
Ability.CastPosition(ability, point, false, false, true, C.identifier)
elseif entry.kind == "unit" then
if dist > range + NPC.GetHullRadius(target) then return false end
Ability.CastTarget(ability, target, false, false, true, C.identifier)
else
return false
end
S.castAt[entry.name] = now
S.lastAct = now
A.after(ability, now)
A.say("gap " .. entry.name)
A.log("info", "universal combo gap close", { ability = entry.name, dist = math.floor(dist) })
return true
end
function A.commandIllusions(hero, target, now)
if now < S.illAt then return end
S.illAt = now + C.illGap
local player = Players.GetLocal()
if player == nil then return end
local pid = Player.GetPlayerID(player)
local name = NPC.GetUnitName(hero)
for _, unit in ipairs(Heroes.GetAll() or {}) do
if unit ~= nil and unit ~= hero and Entity.IsAlive(unit) and NPC.IsIllusion(unit) and NPC.GetUnitName(unit) == name
and NPC.IsControllableByPlayer(unit, pid) then
A.order(unit, C.orderAttack, Entity.GetAbsOrigin(target), target, nil, true)
end
end
end
function A.keeping(hero)
return UI.keep ~= nil and UI.keep:Get() and NPC.GetAttackRange(hero) >= C.rangeKeepMin
end
function A.zone()
local radius = C.zones[S.heroName or ""]
if radius == nil or UI.zone == nil or not UI.zone:Get() then return nil end
return radius - C.zonePad
end
function A.idleKeep(hero, target, now)
local reach = NPC.GetAttackRange(hero) + NPC.GetHullRadius(target) + C.rangePad
local zone = A.zone()
if zone ~= nil then reach = math.min(reach, zone) end
if (A.keeping(hero) or zone ~= nil) and A.distance(hero, target) > reach then
if A.approach(hero, target, math.max(reach - 80, 100), now) then return end
end
A.idle(hero, target, now)
end
function A.step(hero, target, now)
if IT.breakLinken(hero, target, now) then return end
do local mw = IT.meteorCast(hero, target, now, C.identifier) if mw ~= nil then S.nextAt = now + mw return end end
local list = A.entries(hero)
local approach, gap = nil, nil
local itemsTried = false
for _, entry in ipairs(list) do
local role = entry.row.r
if role == "o" then
A.orbOn(hero, entry, now)
elseif role == "m" then
if gap == nil then gap = entry end
else
if not itemsTried and role == "d" then
itemsTried = true
if A.useItems(hero, target, entry.h, now) then return end
end
local ok, result, range = pcall(A.tryCast, hero, target, entry, now)
if not ok then
S.castAt[entry.name] = now + C.failBackoff
A.log("error", "universal combo cast failed", { ability = entry.name, error = tostring(result):sub(1, 200) })
result = false
end
if result == true then return end
if result == "approach" and approach == nil then approach = range end
end
end
if not itemsTried and A.useItems(hero, target, list[1] ~= nil and list[1].h or nil, now) then return end
if gap ~= nil then
local reach = NPC.GetAttackRange(hero)
for _, entry in ipairs(list) do
local role = entry.row.r
if role ~= "m" and role ~= "o" and role ~= "b" then
local r = entry.kind == "no" and A.areaRadius(entry) or Ability.GetCastRange(entry.h)
if r > reach then reach = r end
end
end
if A.distance(hero, target) > math.max(C.gapMin, reach + 200) and A.gapClose(hero, target, gap, now) then return end
end
if approach ~= nil then
local want = approach - 40
if A.keeping(hero) then want = math.max(want, NPC.GetAttackRange(hero) - 40) end
local zone = A.zone()
if zone ~= nil then want = math.min(want, zone - C.rangePad) end
if A.approach(hero, target, math.max(want, 80), now) then
A.say("approach")
return
end
end
A.say("attack")
A.idleKeep(hero, target, now)
end
function A.update()
local hero = Heroes.GetLocal()
if not A.valid(hero) then
if S.phase ~= "idle" then A.reset("no hero") end
return
end
local rows = A.heroRows(hero)
local clock = GameRules.GetGameTime()
if rows == nil then
if S.phase ~= "idle" then A.reset("hero has its own combo") end
return
end
if clock >= S.spellAt then
S.spellAt = clock + C.refreshGap
local ok, err = pcall(A.refreshSpells, hero)
if not ok and S.error == nil then
S.error = tostring(err)
A.log("error", "universal combo abilities failed", { error = S.error })
end
end
if clock >= S.itemAt and S.itemError == nil then
S.itemAt = clock + C.itemGap
local ok, err = pcall(A.refreshItems, hero)
if not ok then
S.itemError = tostring(err)
A.log("error", "universal items refresh failed", { error = S.itemError })
end
end
if not UI.enabled:Get() or not UI.key:IsDown() then
if S.charge ~= nil then
A.chargeRelease(hero, "key released")
if NPC.GetModifier(hero, S.charge.mod or "") == nil then S.charge = nil end
end
if S.phase ~= "idle" then A.reset("key released") end
return
end
if C.inputCaptured ~= nil and C.inputCaptured() then return end
