function A.midasItem(unit)
for _, slot in ipairs(C.slots) do
local it = NPC.GetItemByIndex(unit, slot)
if it ~= nil then
local name = Ability.GetName(it)
for _, m in ipairs(C.midas) do
if name == m and Ability.GetLevel(it) > 0 and Ability.IsReady(it) and Ability.GetCooldown(it) <= 0 then return it end
end
end
end
return nil
end
function A.midasTarget(unit, item)
local origin = Entity.GetAbsOrigin(unit)
local range = Ability.GetCastRange(item) + C.midasSlack
local best, bestHp = nil, -1
for _, n in ipairs(NPCs.InRadius(origin, range, Entity.GetTeamNum(unit), C.teamEnemy, true, true) or {}) do
if Entity.IsAlive(n) and not NPC.IsHero(n) and not NPC.IsAncient(n) and not NPC.IsIllusion(n) and NPC.IsVisible(n)
and not NPC.IsWaitingToSpawn(n) and Entity.GetTeamNum(n) ~= C.bossTeam
and NPC.GetUnitName(n):find("patrol", 1, true) == nil and (NPC.IsCreep(n) or NPC.IsNeutral(n)) then
local hp = Entity.GetHealth(n)
if hp > bestHp then best, bestHp = n, hp end
end
end
return best
end
