if u ~= nil and u ~= hero and NPC.GetUnitName(u) == C.arc and Entity.IsAlive(u) and Entity.IsSameTeam(hero, u) then
for _, mod in ipairs(C.doubleMods) do
if NPC.HasModifier(u, mod) then
list[#list + 1] = u
break
end
end
end
end
return list
end
function A.runMidas(hero, now)
for _, unit in ipairs(A.midasUnits(hero)) do
local id = Entity.GetIndex(unit)
if Entity.IsAlive(unit) and now >= (S.midasAt[id] or 0) and not NPC.IsChannellingAbility(unit)
and not NPC.HasState(unit, C.stateInvisible) and not NPC.IsStunned(unit) then
local item = A.midasItem(unit)
local target = item ~= nil and A.midasTarget(unit, item) or nil
if target ~= nil and A.orderSafe() then
Ability.CastTarget(item, target, false, false, true, C.identifier)
S.midasAt[id] = now + C.midasGap
A.log("info", "utility midas", { unit = unit == hero and "hero" or "double", target = NPC.GetUnitName(target) })
return
end
end
end
end
function A.courierHasSphere(courier)
