local h = A.transfer(courier)
if h ~= nil and Courier.GetCourierState(courier) ~= C.stateDelivering then
S.deliverTries = (S.deliverTries or 0) + 1
Ability.CastNoTarget(h, false, false, true, C.identifier)
S.deliverAt = now + C.deliverGap * math.min(S.deliverTries, 8)
if S.deliverTries <= 2 then A.log("info", "utility sphere deliver", { try = S.deliverTries }) end
end
end
return
end
S.deliverTries = 0
local wait = UI.spheresWait:Get()
