local id = Entity.GetIndex(p)
if item ~= nil and C.spheres[Ability.GetName(item)] and Item.GetPlayerOwnerID(item) == pid then
live[id] = true
local pos = Entity.GetAbsOrigin(p)
local seen = S.seen[id]
if seen == nil or (pos - seen.pos):Length2D() > C.sphereMove then
seen = { at = now, pos = pos }
S.seen[id] = seen
end
if now - seen.at >= wait and now >= (S.skip[id] or 0) and candidate == nil then candidate = { h = p, id = id, pos = pos } end
end
end
for id in pairs(S.seen) do
if not live[id] then S.seen[id] = nil end
end
if S.pick ~= nil and not live[S.pick.id] then S.pick = nil end
if S.pick ~= nil and now - S.pick.at > C.pickupTimeout then
S.skip[S.pick.id] = now + C.pickupSkip
A.log("info", "utility sphere pickup timeout", {})
S.pick = nil
end
local target = S.pick or candidate
if target == nil or not A.courierFree(courier) or now < S.orderAt or not A.orderSafe() then return end
if S.pick == nil then
S.pick = { id = target.id, h = target.h, pos = target.pos, at = now }
A.log("info", "utility sphere pickup", { dist = math.floor((target.pos - Entity.GetAbsOrigin(courier)):Length2D()) })
end
S.orderAt = now + C.orderGap
Player.PrepareUnitOrders(player, C.orderPickup, S.pick.h, S.pick.pos, nil, C.issuer, courier, false, false, false, false, C.identifier)
end
A.clock = type(os) == "table" and type(os.clock) == "function" and os.clock or GlobalVars.GetCurTime
function A.updateUi()
