if S.inGame ~= inGame then
S.inGame = inGame
A.log("info", "utility ui tick", { inGame = inGame })
end
A.runTab(real)
A.runPick(real)
A.runBan(real)
end
function A.update()
local now = GameRules.GetGameTime()
if now < S.tickAt then return end
S.tickAt = now + C.tick
local hero = Heroes.GetLocal()
if hero == nil then return end
if UI.midas:Get() and Entity.IsAlive(hero) then A.runMidas(hero, now) end
if UI.spheres:Get() then A.runSpheres(hero, now) end
if UI.dust:Get() and Entity.IsAlive(hero) then A.runDust(hero, now) end
end
function A.dustReady(hero)
local h = NPC.GetAbility(hero, C.dust)
if h == nil or Ability.IsHidden(h) or NPC.HasModifier(hero, C.dustCd) then return nil end
local mod = NPC.GetModifier(hero, C.dustCharges)
if mod == nil or Modifier.GetStackCount(mod) <= 0 then return nil end
return h
end
function A.dustCovered(pos, now)
