S.dustPending = nil
if pending ~= nil and now - pending.at <= C.dustSeen then
local ok, pos = pcall(Entity.GetAbsOrigin, pending.unit)
if ok and pos ~= nil and (pos - origin):Length2D() <= C.dustReach then return pos, pending.why end
end
local found, why = nil, nil
for _, e in ipairs(Heroes.GetAll() or {}) do
if e ~= hero and Entity.IsAlive(e) and not Entity.IsSameTeam(hero, e) and not NPC.IsIllusion(e) then
if found == nil and NPC.IsVisible(e) and not Entity.IsDormant(e) and NPC.HasState(e, C.stateInvisible) then
local pos = Entity.GetAbsOrigin(e)
if (pos - origin):Length2D() <= C.dustReach then found, why = pos, "state" end
end
end
end
return found, why
end
function A.runDust(hero, now)
