if h == nil then return end
Ability.CastNoTarget(h, false, false, true, C.identifier)
S.dustAt = now + C.dustGap
S.dustArea = { pos = Entity.GetAbsOrigin(hero), untilAt = now + C.dustArea }
A.log("info", "auto dust", { why = why, dist = math.floor((pos - Entity.GetAbsOrigin(hero)):Length2D()) })
end
function A.drafting()
local ok, state = pcall(GameRules.GetGameState)
if not ok or type(state) ~= "number" then return true end
return state ~= C.stateInGame and state ~= C.statePost and state ~= C.stateDisconnect
end
function A.runPick(now)
if not UI.pick:Get() or now < (S.pickAt or 0) or Engine.RunScript == nil or not A.drafting() then return end
