S.pickLogged = list
A.log("info", "auto pick", { heroes = list, ran = ok and ran ~= false })
end
end
function A.runBan(now)
if not UI.ban:Get() or now < (S.banAt or 0) or Engine.RunScript == nil or not A.drafting() then return end
S.banAt = now + C.banGap
local ok, ran = pcall(Engine.RunScript, C.banJs, C.tabContext)
if not S.banLogged then
S.banLogged = true
A.log("info", "auto ban", { ran = ok and ran ~= false })
end
end
function A.runTab(now)
if Engine.RunScript == nil then return end
local held = Input.IsKeyDown(C.keyTab)
