local UI = {}
local S = { saved = {}, widgets = {}, miss = {}, count = 0, nextTick = 0, nextApply = 0, active = false, hold = false, ready = false }
local A = {}
local CONFIG = "x6_umbrella_off"
function A.log(level, message, data)
if type(ai_bridge) == "table" and type(ai_bridge.mcp_log) == "function" and S.ready then
pcall(ai_bridge.mcp_log, level, message, data)
end
end
function A.categoryOf(tab, group)
if tab == "Main Settings" and group == "Hero Settings" then return "combos" end
if tab == "Extra Settings" or tab == "Panels Settings" then return "extras" end
return "usage"
end
function A.isCustom()
local ok, mode = pcall(function() return GameRules.GetGameMode() end)
if not ok then return false end
local group = type(Enum) == "table" and Enum.GameMode or nil
local custom = type(group) == "table" and group.DOTA_GAMEMODE_CUSTOM or 15
return mode == custom
end
function A.find(rule)
local key = rule[1] .. "/" .. rule[2] .. "/" .. rule[3] .. "/" .. rule[4]
local cached = S.widgets[key]
if cached ~= nil then return cached, key end
local now = os.clock()
if S.miss[key] ~= nil and now < S.miss[key] then return nil, key end
local ok, found = pcall(Menu.Find, "Heroes", "Hero List", rule[1], rule[2], rule[3], rule[4])
if ok and found ~= nil then
S.widgets[key] = found
return found, key
end
S.miss[key] = now + 10
return nil, key
end
function A.wanted()
return { combos = UI.combos:Get(), extras = UI.extras:Get(), usage = UI.usage:Get() }
end
function A.persist()
if type(Config) ~= "table" or type(Config.WriteString) ~= "function" then return end
local keys = {}
for key in pairs(S.saved) do keys[#keys + 1] = key end
pcall(Config.WriteString, CONFIG, "saved", table.concat(keys, "|"))
end
function A.status()
if UI.status == nil then return end
pcall(UI.status.ForceLocalization, UI.status, string.format(localization.Get("menu.status"), S.count))
end
function A.apply()
local wanted = A.wanted()
local changed = false
for cat, list in pairs(RULES) do
if wanted[cat] then
for i = 1, #list do
local widget, key = A.find(list[i])
if widget ~= nil and S.saved[key] == nil then
local ok, value = pcall(widget.Get, widget)
if ok and value == true then
pcall(widget.Set, widget, false)
S.saved[key] = { w = widget, cat = cat }
S.count = S.count + 1
changed = true
end
end
end
end
end
for key, rec in pairs(S.saved) do
if not wanted[rec.cat] then
local ok, value = pcall(rec.w.Get, rec.w)
if ok and value == false then pcall(rec.w.Set, rec.w, true) end
S.saved[key] = nil
S.count = S.count - 1
changed = true
end
end
if changed then
A.persist()
A.status()
A.log("info", "umbrella off applied", { count = S.count })
end
end
function A.restoreAll()
local restored = 0
for key, rec in pairs(S.saved) do
local ok, value = pcall(rec.w.Get, rec.w)
if ok and value == false then
pcall(rec.w.Set, rec.w, true)
restored = restored + 1
end
S.saved[key] = nil
end
S.count = 0
S.active = false
A.persist()
A.status()
if restored > 0 then A.log("info", "umbrella off restored", { restored = restored }) end
end
function A.adoptStale()
if type(Config) ~= "table" or type(Config.ReadString) ~= "function" then return end
local ok, text = pcall(Config.ReadString, CONFIG, "saved", "")
if not ok or type(text) ~= "string" or text == "" then return end
local custom = A.isCustom()
for key in text:gmatch("[^|]+") do
local a, b, c, d = key:match("^([^/]+)/([^/]+)/(.+)/([^/]+)$")
if a ~= nil then
local widget = A.find({ a, b, c, d })
if widget ~= nil then
local good, value = pcall(widget.Get, widget)
if good and value == false then
if custom and UI.enabled:Get() then
local cat = A.categoryOf(b, c)
S.saved[key] = { w = widget, cat = cat }
S.count = S.count + 1
S.active = true
else
pcall(widget.Set, widget, true)
end
end
end
end
end
A.persist()
A.status()
end
function A.tick()
local now = os.clock()
if now < S.nextTick then return end
S.nextTick = now + 0.5
if not UI.enabled:Get() then
if S.active or S.count > 0 then A.restoreAll() end
S.hold = false
return
end
local want = (not UI.custom:Get()) or A.isCustom()
if not want then
if S.active or S.count > 0 then A.restoreAll() end
S.hold = false
return
end
if S.hold then return end
S.active = true
if now >= S.nextApply then
S.nextApply = now + 2
A.apply()
end
end
function A.initMenu()
local side = (type(Enum) == "table" and Enum.GroupSide) or {}
local raw = RawMenu.Create("Scripts", "1x6", "Umbrella off", "Main")
local section = localization.Wrap(raw, true)
local main = section:Create("menu.main", side.Left)
UI.enabled = main:Switch("menu.enabled", true)
UI.enabled:Icon("\u{f011}")
UI.enabled:ToolTip("menu.enabled_tip")
UI.custom = main:Switch("menu.custom", true)
UI.custom:Icon("\u{f11b}")
UI.custom:ToolTip("menu.custom_tip")
UI.combos = main:Switch("menu.combos", true)
UI.combos:Icon("\u{f0e7}")
UI.combos:ToolTip("menu.combos_tip")
UI.extras = main:Switch("menu.extras", false)
UI.extras:Icon("\u{f0c9}")
UI.extras:ToolTip("menu.extras_tip")
UI.usage = main:Switch("menu.usage", false)
UI.usage:Icon("\u{f2f1}")
UI.usage:ToolTip("menu.usage_tip")
UI.offNow = main:Button("menu.off_now", function()
S.hold = false
S.active = true
S.nextApply = 0
A.apply()
end)
UI.restore = main:Button("menu.restore", function()
A.restoreAll()
S.hold = true
end)
UI.status = main:Label("menu.status")
return true
end
function script.OnScriptsLoaded()
local ok, err = pcall(A.initMenu)
if not ok then
S.menuError = tostring(err)
return
end
S.ready = true
pcall(A.status)
pcall(A.adoptStale)
A.log("info", "umbrella off loaded", { combos = #RULES.combos, extras = #RULES.extras, usage = #RULES.usage })
end
function script.OnUpdate()
if not S.ready then return end
local ok, err = pcall(A.tick)
if not ok and not S.tickError then
S.tickError = tostring(err)
A.log("error", "umbrella off tick failed", { error = S.tickError })
end
end
function script.OnGameEnd()
if not S.ready then return end
pcall(A.restoreAll)
S.hold = false
end
return script
end)
