-- @gen:end
function A.log(level, message, data)
if type(ai_bridge) == "table" and type(ai_bridge.mcp_log) == "function" and S.ready then
pcall(ai_bridge.mcp_log, level, message, data)
end
end
function A.ensureFont()
if S.font ~= nil then return end
local flags = enumValue("FontCreate", "FONTFLAG_ANTIALIAS", 0)
local weight = enumValue("FontWeight", "BOLD", 700)
for _, name in ipairs(K.FONTS) do
local ok, handle = pcall(Render.LoadFont, name, flags, weight)
if ok and handle and handle ~= 0 then
S.font = handle
return
end
end
S.font = Render.LoadFont(K.FONTS[#K.FONTS], flags, weight)
end
function A.image(path, id)
if path == nil then return nil end
local key = path .. "|" .. tostring(id)
local handle = S.images[key]
if handle == nil then
local ok, value
if type(X6P) == "table" and type(X6P.pic) == "function" then ok, value = pcall(X6P.pic, path, id) end
if not ok or not value then ok, value = pcall(Render.LoadImage, path) end
handle = (ok and value and value ~= 0) and value or false
S.images[key] = handle
end
return handle or nil
end
function A.itemIcon(name)
local base = name:gsub("_custom$", "")
return A.image("panorama/images/items/" .. base .. "_png.vtex_c", name)
end
function A.itemLabel(name)
return (name:gsub("_custom$", ""):gsub("_", " "))
end
function A.parse(row)
local list, flags = row:match("^([%d%.]*)|(%d%d)$")
local items = {}
if list ~= nil then
for n in list:gmatch("%d+") do
local name = ITEMS[tonumber(n) + 1]
if name ~= nil then items[#items + 1] = name end
end
end
flags = flags or "00"
return { items = items, scepter = flags:sub(1, 1) == "1", shard = flags:sub(2, 2) == "1" }
end
function A.find(now)
if now < S.nextFind then return end
S.nextFind = now + K.FIND
local hero = Heroes.GetLocal()
local unit = hero ~= nil and NPC.GetUnitName(hero) or nil
if unit == S.unit then return end
S.unit, S.builds, S.pick, S.icons = unit, nil, 1, {}
local rows = unit ~= nil and DATA[unit] or nil
if rows == nil then return end
local list = {}
for i = 1, #rows do
local row = rows[i]
local stages = {}
for j = 2, 5 do stages[j - 1] = A.parse(row[j]) end
list[i] = { name = row[1], stages = stages }
end
S.builds = list
A.log("info", "ai builds ready", { hero = unit, builds = #list })
end
function A.abilityIcon(index)
local cached = S.icons[index]
if cached ~= nil then return cached or nil end
local hero = Heroes.GetLocal()
local handle = false
if hero ~= nil then
local ok, ability = pcall(NPC.GetAbilityByIndex, hero, index - 1)
if ok and ability ~= nil then
local okName, name = pcall(Ability.GetName, ability)
if okName and type(name) == "string" and name ~= "" then
local base = name:gsub("_custom$", "")
handle = A.image("panorama/images/spellicons/" .. base .. "_png.vtex_c", name) or false
end
end
end
S.icons[index] = handle
return handle or nil
end
function A.active()
if not S.ready or S.error ~= nil then return false end
if not UI.enabled:Get() then return false end
if not Engine.IsInGame() then return false end
if type(Engine.IsShopOpen) == "function" and not Engine.IsShopOpen() then return false end
return true
end
function A.text(size, value, x, y, color)
Render.Text(S.font, size, value, Vec2(x, y), color)
end
function A.slot(x, y, size, name)
Render.FilledRect(Vec2(x, y), Vec2(x + size, y + size), P.SLOT, 3, K.ROUND)
if name == nil then return end
local icon = A.itemIcon(name)
if icon ~= nil then
Render.Image(icon, Vec2(x + 1, y + 1), Vec2(size - 2, size - 2), Color(255, 255, 255, 255), 3, K.ROUND)
else
local label = A.itemLabel(name):sub(1, 7)
A.text(10, label, x + 3, y + size * 0.5 - 6, P.DIM)
end
end
local SHOP_IDS = { "shop", "DOTAHUDShop", "ShopPanel", "shop_container", "GuideFlyout" }
function A.shopRect(now)
if now - S.shopAt < 0.5 then return S.shopBox end
S.shopAt, S.shopBox = now, nil
for i = 1, #SHOP_IDS do
local ok, panel = pcall(Panorama.GetPanelByName, SHOP_IDS[i], false)
if ok and panel ~= nil then
local okr, r = pcall(panel.GetBounds, panel, true)
if not okr or r == nil or (r.w or 0) < 50 then okr, r = pcall(panel.GetBounds, panel) end
if okr and r ~= nil and (r.w or 0) >= 50 then
S.shopBox = r
return S.shopBox
end
end
end
return nil
end
function A.aghs(x, y, w, h, kind, on)
local hud = A.image("panorama/images/hud/reborn/aghsstatus_" .. kind .. (on and "_on" or "_off") .. "_png.vtex_c", kind)
local gray = 0
if hud == nil then
hud = A.image("panorama/images/items/" .. (kind == "scepter" and "ultimate_scepter" or "aghanims_shard") .. "_png.vtex_c", kind)
gray = on and 0 or 1
end
if hud == nil then
Render.FilledRect(Vec2(x, y), Vec2(x + w, y + h), on and (kind == "scepter" and P.SCEPTER or P.SHARD) or P.OFF, 3, K.ROUND)
return
end
Render.Image(hud, Vec2(x, y), Vec2(w, h), on and P.ON or P.DULL, 2, K.ROUND, Vec2(0, 0), Vec2(1, 1), gray)
end
function A.stage(x, y, w, h, index, stage, scale)
local title = localization.Get(K.STAGES[index]) .. "  " .. K.TIMES[index]
local hot = S.buyStage == index and os.clock() - S.buyAt < 1.2
local fs = math.max(9, math.floor(12 * scale))
A.text(fs, title, x, y, hot and P.PICK or P.DIM)
local tw = Render.TextSize(S.font, fs, title)
S.hits[#S.hits + 1] = { x0 = x, y0 = y, x1 = x + tw.x, y1 = y + fs + 2, stage = index }
local gap = math.max(2, math.floor(4 * scale))
local top = y + fs + math.floor(5 * scale)
local list = stage.items
local rows = math.max(1, math.ceil(#list / 4))
local colW = math.max(12, math.floor(20 * scale))
local size = math.floor(math.min((w - colW - gap - 3 * gap) / 4, (h - (top - y) - (rows - 1) * gap) / rows))
if size < 10 then size = 10 end
local cx, cy = Input.GetCursorPos()
for i = 1, #list do
local sx = x + ((i - 1) % 4) * (size + gap)
local sy = top + math.floor((i - 1) / 4) * (size + gap)
A.slot(sx, sy, size, list[i])
if cx >= sx and cx <= sx + size and cy >= sy and cy <= sy + size then
Render.Rect(Vec2(sx, sy), Vec2(sx + size, sy + size), P.HOVER, 3, K.ROUND, 1)
end
S.hits[#S.hits + 1] = { x0 = sx, y0 = sy, x1 = sx + size, y1 = sy + size, item = list[i] }
end
local ax = x + 4 * (size + gap)
local ah = math.floor((rows * size + (rows - 1) * gap - gap) / 2)
A.aghs(ax, top, colW, ah, "scepter", stage.scepter)
A.aghs(ax, top + ah + gap, colW, ah, "shard", stage.shard)
end
function A.draw()
S.hits, S.rect = {}, nil
if not A.active() then return end
A.ensureFont()
A.find(os.clock())
local screen = Render.ScreenSize()
local scale = math.min(1.0, Render.ScreenSize().y / 1080)
local count = S.builds ~= nil and #S.builds or 0
local open = count > 0
local pad = math.max(4, math.floor(8 * scale))
local gap = math.max(3, math.floor(6 * scale))
local box = A.shopRect(os.clock())
local width = math.floor(268 * scale)
local height = math.floor(432 * scale)
local x, y
if box ~= nil then
x = box.x + math.floor(10 * scale)
y = box.y + box.h - height - math.floor(10 * scale)
else
x = math.floor(40 * scale)
y = screen.y - height - math.floor(120 * scale)
end
x = math.max(0, math.min(x, screen.x - 40))
y = math.max(0, math.min(y, screen.y - 40))
width = math.min(width, screen.x - x)
height = math.min(height, screen.y - y)
Render.FilledRect(Vec2(x, y), Vec2(x + width, y + height), P.BG, 5, K.ROUND)
Render.Rect(Vec2(x, y), Vec2(x + width, y + height), P.LINE, 5, K.ROUND, 1)
S.rect = { x, y, x + width, y + height }
if count == 0 then
A.text(math.max(9, math.floor(12 * scale)), localization.Get("ui.none"), x + pad, y + pad, P.DIM)
return
end
local inner = height - pad * 2
local tile = math.floor(math.min(46 * scale, (inner - 3 * gap) / count))
local letter = math.max(10, math.floor(tile * 0.45))
local colW = tile + math.floor(5 * scale) + letter
local colX = x + pad
local top = y + pad
local cx, cy = Input.GetCursorPos()
for i = 1, count do
local ty = top + (i - 1) * (tile + gap)
Render.FilledRect(Vec2(colX, ty), Vec2(colX + tile, ty + tile), P.SLOT, 4, K.ROUND)
local icon = A.abilityIcon(i)
if icon ~= nil then
Render.Image(icon, Vec2(colX + 2, ty + 2), Vec2(tile - 4, tile - 4), Color(255, 255, 255, 255), 4, K.ROUND)
end
if i == S.pick then
Render.Rect(Vec2(colX, ty), Vec2(colX + tile, ty + tile), P.PICK, 4, K.ROUND, 2)
elseif cx >= colX and cx <= colX + tile and cy >= ty and cy <= ty + tile then
Render.Rect(Vec2(colX, ty), Vec2(colX + tile, ty + tile), P.HOVER, 4, K.ROUND, 1)
end
local key = K.KEYS[i] or tostring(i)
local kw = Render.TextSize(S.font, letter, key)
A.text(letter, key, colX + tile + math.floor(5 * scale) + (letter - kw.x) * 0.5, ty + (tile - kw.y) * 0.5, i == S.pick and P.PICK or P.TEXT)
S.hits[#S.hits + 1] = { x0 = colX, y0 = ty, x1 = colX + tile + letter, y1 = ty + tile, pick = i }
end
if not open then return end
local bodyX = colX + colW + gap
local bodyW = x + width - pad - bodyX
local bodyH = (y + height - pad - top) / 4
local build = S.builds[S.pick] or S.builds[1]
for i = 1, 4 do
A.stage(bodyX, top + (i - 1) * bodyH, bodyW, bodyH, i, build.stages[i], scale)
end
end
function A.buy(names, reset)
if type(Engine.SetQuickBuy) ~= "function" then return end
for i = 1, #names do
pcall(Engine.SetQuickBuy, (names[i]:gsub("^item_", "")), reset and i == 1)
end
end
function A.click(x, y)
for i = 1, #S.hits do
local h = S.hits[i]
if x >= h.x0 and x <= h.x1 and y >= h.y0 and y <= h.y1 then
if h.pick ~= nil then
S.pick = h.pick
elseif h.item ~= nil then
A.buy({ h.item }, not Input.IsKeyDown(K.SHIFT))
S.buyAt, S.buyStage = os.clock(), 0
elseif h.stage ~= nil then
local build = S.builds ~= nil and (S.builds[S.pick] or S.builds[1]) or nil
local stage = build ~= nil and build.stages[h.stage] or nil
if stage ~= nil then
A.buy(stage.items, true)
S.buyAt, S.buyStage = os.clock(), h.stage
end
end
return true
end
end
local r = S.rect
return r ~= nil and x >= r[1] and x <= r[3] and y >= r[2] and y <= r[4]
end
