end
end
rows = S.argRows[widget]
end
if type(rows) == "table" then
for _, row in ipairs(rows) do
if type(row) == "table" then
local id, path = row[1] or row.nameId, row[2] or row.imagePath
if id ~= nil and type(path) == "string" then map[id] = path end
end
end
end
return map
end
function A.rows(widget, now, extra)
local cached = S.cache[widget]
if cached ~= nil and now - cached.t < K.TTL then return cached.list end
local ids = A.call(widget, "List")
local list = {}
if type(ids) == "table" then
local map = A.pathMap(widget, extra)
for i = 1, #ids do
local id = ids[i]
list[#list + 1] = { id = id, on = A.call(widget, "Get", id) == true, path = map[id] }
end
S.cache[widget] = { t = now, list = list, map = map }
end
return list
end
function A.invalidate(widget)
