function A.reorder(widget, id, to)
local rows = A.rows(widget, os.clock() + 1, S.entry ~= nil and (S.entry.spellsReal or S.entry.spells) == widget and S.entry.icons or nil)
local from
for i, row in ipairs(rows) do
if row.id == id then from = i end
end
if from == nil or from == to then return end
local moved = table.remove(rows, from)
table.insert(rows, math.max(1, math.min(to, #rows + 1)), moved)
local out, selected = {}, {}
for _, row in ipairs(rows) do
out[#out + 1] = { row.id, row.path or "", row.on }
if row.on then selected[#selected + 1] = row.id end
end
pcall(widget.Update, widget, out, true, true)
pcall(widget.Set, widget, selected)
A.invalidate(widget)
A.log("info", "panel reorder", { id = id, from = from, to = to })
end
