end
local border = row.on and P.ON or P.OFF
Render.Rect(Vec2(x, y), Vec2(x + size, y + size), hot and Color(255, 255, 255, 230) or border, round, K.ROUND, math.max(1.5, size * 0.05))
if number ~= nil then
local bw = math.floor(size * 0.42)
Render.FilledRect(Vec2(x + size - bw, y + size - bw), Vec2(x + size, y + size), P.BADGE, math.floor(bw * 0.3), K.ROUND)
