end
function A.walkRaw(panel)
local b = panel:GetBounds(false)
if type(b) ~= "table" or type(b.w) ~= "number" or b.w <= 4 or b.h <= 4 then return nil end
local x, y = b.x, b.y
local parent = panel:GetParent()
for _ = 1, 40 do
if parent == nil then break end
local pb = parent:GetBounds(false)
x, y = x + pb.x, y + pb.y
parent = parent:GetParent()
end
return { x = x, y = y, w = b.w, h = b.h }
end
function A.walkRect(panel)
