if js ~= nil and walk == nil then S.walk = false end
if js ~= nil and walk ~= nil then
S.walk = math.abs(js.x - walk.x) <= 2 and math.abs(js.y - walk.y) <= 2 and math.abs(js.w - walk.w) <= 2 and math.abs(js.h - walk.h) <= 2
A.log("info", "combo panel bounds", { walk = S.walk, dx = js.x - walk.x, dy = js.y - walk.y, dw = js.w - walk.w, dh = js.h - walk.h })
end
return js or walk
end
function A.bounds(name, now, childId)
