function A.badgeGeom(rect, row)
local w = rect.w
local fs = math.max(10, math.floor(w * 0.2))
local sOn, sOff = Render.TextSize(S.font, fs, S.labelOn), Render.TextSize(S.font, fs, S.labelOff)
local pad = math.max(3, math.floor(fs * 0.3))
local bw = math.floor(math.max(sOn.x, sOff.x)) + pad * 2
local bh = math.floor(sOn.y) + 4
local margin = math.max(2, math.floor(w * 0.04))
local x1, y0 = rect.x + w - margin, rect.y + margin
local x0 = x1 - bw
return {
row = row, fs = fs, p0 = Vec2(x0, y0), p1 = Vec2(x1, y0 + bh),
pOn = Vec2(x0 + (bw - sOn.x) / 2, y0 + (bh - sOn.y) / 2), pOff = Vec2(x0 + (bw - sOff.x) / 2, y0 + (bh - sOff.y) / 2),
}
end
function A.paintHud(layout)
