function A.square(r)
if r.h > r.w * 1.3 then return { x = r.x, y = r.y, w = r.w, h = r.w } end
return r
end
function A.looseIds(loose)
local ids = {}
for i, entry in ipairs(loose) do
if i > 8 then break end
ids[#ids + 1] = tostring(entry.row.id)
end
return table.concat(ids, ",")
end
function A.buildHud(sets, now)
local hero = Heroes.GetLocal()
if hero == nil then return nil end
local vis = A.visible(hero, now)
local loose, used = {}, {}
local layout = { t = now, entry = S.entry, badges = {}, tiles = {}, hits = {} }
S.labelOn, S.labelOff = localization.Get("ui.on"), localization.Get("ui.off")
for _, set in ipairs(sets) do
for _, row in ipairs(set.rows) do
local nm = A.iconName(row.path)
if nm ~= nil then nm = ALIAS[nm] or nm end
local panelName, slot = nil, nil
if set.kind == "spell" then
if nm ~= nil then
for k, name in ipairs(vis.abilities) do
if not used[k] and name == nm then
used[k] = true
panelName = "Ability" .. (k - 1)
break
end
end
end
else
local want = set.names ~= nil and set.names[row.id] or nil
for _, s in ipairs(HUD_SLOTS) do
if not used[100 + s] and ((want ~= nil and vis.full[s] == want) or (want == nil and nm ~= nil and vis.items[s] == nm)) then
used[100 + s] = true
slot = s
break
end
end
end
local rect, image = nil, nil
if slot ~= nil then
rect, image = A.slotBounds(slot, now)
elseif panelName ~= nil then
rect, image = A.bounds(panelName, now, "AbilityImage")
end
if rect ~= nil then
layout.badges[#layout.badges + 1] = A.badgeGeom(image or A.square(rect), row)
layout.hits[#layout.hits + 1] = { x0 = rect.x, y0 = rect.y, x1 = rect.x + rect.w, y1 = rect.y + rect.h, widget = set.widget, id = row.id }
else
loose[#loose + 1] = { row = row, widget = set.widget }
end
end
end
if #layout.badges == 0 then return nil end
local anchor, anchorImage = A.bounds("Ability0", now, "AbilityImage")
if not S.hudLogged then
S.hudLogged = true
A.log("info", "combo panel hud", {
placed = #layout.badges, loose = #loose, looseIds = A.looseIds(loose),
x = anchor and anchor.x, y = anchor and anchor.y, w = anchor and anchor.w, h = anchor and anchor.h,
ix = anchorImage and anchorImage.x, iy = anchorImage and anchorImage.y, iw = anchorImage and anchorImage.w, ih = anchorImage and anchorImage.h,
})
end
if #loose > 0 and anchor ~= nil then
local base = anchorImage or A.square(anchor)
local size = math.max(24, math.floor(base.w * 0.6))
local x, y = base.x, base.y - size - 6
for _, entry in ipairs(loose) do
layout.tiles[#layout.tiles + 1] = { row = entry.row, x = x, y = y, size = size }
layout.hits[#layout.hits + 1] = { x0 = x, y0 = y, x1 = x + size, y1 = y + size, widget = entry.widget, id = entry.row.id }
x = x + size + 4
end
end
return layout
end
function A.draw()
local now = os.clock()
if next(S.hits) ~= nil then S.hits = {} end
if not UI.enabled:Get() or not Engine.IsInGame() then
S.rect, S.drag = nil, nil
return
end
A.find(now)
local entry = S.entry
if entry == nil then
S.rect, S.drag = nil, nil
return
end
if UI.style:Get() == 0 then
local layout = S.hudLayout
if layout ~= nil and layout.entry == entry and now - layout.t < K.HUD then
A.paintHud(layout)
S.rect, S.drag, S.hudMode, S.drawAt, S.hudHits = nil, nil, true, now, layout.hits
return
end
end
local sets = {}
local itemWidget = entry.items or (entry.ui ~= nil and (entry.ui.itemsReal or entry.ui.items) or nil)
if itemWidget ~= nil then sets[#sets + 1] = { kind = "item", widget = itemWidget, rows = A.rows(itemWidget, now), names = entry.ui ~= nil and entry.ui.itemNames or nil } end
local spellWidget = entry.spellsReal or entry.spells
if spellWidget ~= nil then sets[#sets + 1] = { kind = "spell", widget = spellWidget, rows = A.rows(spellWidget, now, entry.icons) } end
local total = 0
for _, set in ipairs(sets) do
if #set.rows > 0 then total = total + 1 end
end
if total == 0 then
S.rect, S.drag = nil, nil
return
end
A.ensureFont()
S.hudLayout = nil
if UI.style:Get() == 0 then
local layout = A.buildHud(sets, now)
if layout ~= nil then
S.hudLayout = layout
A.paintHud(layout)
S.rect, S.drag, S.hudMode, S.drawAt, S.hudHits = nil, nil, true, now, layout.hits
return
end
end
S.hudHits = {}
S.hudMode = false
local screen = Render.ScreenSize()
local scale = UI.scale:Get() / 100
local tile, gap, pad = A.layout(scale)
local widest = 0
for _, set in ipairs(sets) do
local n = #set.rows
if n > 0 then widest = math.max(widest, n * tile + (n - 1) * gap) end
end
local x1 = screen.x - UI.x:Get()
local x0 = x1 - widest - pad * 2
local y0 = UI.y:Get()
local y1 = y0 + total * tile + (total - 1) * gap + pad * 2
S.rect = { x0, y0, x1, y1 }
Render.FilledRect(Vec2(x0, y0), Vec2(x1, y1), P.BG, math.floor(8 * scale), K.ROUND)
Render.Rect(Vec2(x0, y0), Vec2(x1, y1), P.LINE, math.floor(8 * scale), K.ROUND, 1)
local cx, cy = Input.GetCursorPos()
local dragging = S.drag ~= nil and S.drag.moved
local rowY = y0 + pad
for _, set in ipairs(sets) do
local rows = set.rows
if #rows > 0 then
local rowW = #rows * tile + (#rows - 1) * gap
local startX = x0 + pad
local number = 0
local target = nil
if dragging and S.drag.widget == set.widget then
target = math.max(1, math.min(#rows, math.floor((cx - startX) / (tile + gap)) + 1))
S.drag.target = target
end
for i, row in ipairs(rows) do
if row.on then number = number + 1 end
local x = startX + (i - 1) * (tile + gap)
local hot = not dragging and cx >= x and cx <= x + tile and cy >= rowY and cy <= rowY + tile and not A.over(cx, cy)
local skipped = dragging and S.drag.widget == set.widget and S.drag.id == row.id
if not skipped then
A.drawTile(row, x, rowY, tile, row.on and number or nil, hot, false)
else
Render.Rect(Vec2(x, rowY), Vec2(x + tile, rowY + tile), P.HINT, math.floor(tile * 0.14), K.ROUND, 1)
end
S.hits[#S.hits + 1] = { x0 = x, y0 = rowY, x1 = x + tile, y1 = rowY + tile, kind = set.kind, widget = set.widget, id = row.id, index = i }
end
if target ~= nil then
local mx = startX + (target - 1) * (tile + gap) - gap / 2
Render.Line(Vec2(mx, rowY), Vec2(mx, rowY + tile), P.ON, 2)
end
rowY = rowY + tile + gap
end
end
if dragging then
for _, set in ipairs(sets) do
if set.widget == S.drag.widget then
for _, row in ipairs(set.rows) do
if row.id == S.drag.id then A.drawTile(row, cx - tile / 2, cy - tile / 2, tile, nil, true, true) end
end
end
end
end
S.drawAt = now
end
function A.release(cx, cy)
local drag = S.drag
S.drag = nil
if drag == nil or not drag.moved or drag.target == nil then return end
A.reorder(drag.widget, drag.id, drag.target)
end
function A.tickDrag()
local drag = S.drag
if drag == nil then return end
local cx, cy = Input.GetCursorPos()
if not drag.moved and (math.abs(cx - drag.x) > K.DRAG or math.abs(cy - drag.y) > K.DRAG) then drag.moved = true end
if not Input.IsKeyDown(K.MOUSE1, true) then A.release(cx, cy) end
end
function A.active()
return S.ready and (S.rect ~= nil or (S.hudMode and #S.hudHits > 0)) and os.clock() - S.drawAt < 0.5
end
function A.click(key, down)
local cx, cy = Input.GetCursorPos()
if S.hudMode then
if A.over(cx, cy) or key ~= K.MOUSE3 then return false end
for _, h in ipairs(S.hudHits) do
if cx >= h.x0 and cx <= h.x1 and cy >= h.y0 and cy <= h.y1 then
if down then A.toggle(h.widget, h.id) end
return true
end
end
return false
end
if A.over(cx, cy) or not A.inRect(cx, cy) then return false end
local hit = A.hitAt(cx, cy)
if key == K.MOUSE3 then
if down and hit ~= nil then A.toggle(hit.widget, hit.id) end
return true
end
if down and hit ~= nil and (hit.kind == "item" or (S.entry ~= nil and S.entry.order)) then
S.drag = { widget = hit.widget, id = hit.id, x = cx, y = cy, moved = false, target = nil }
end
return true
end
function script.OnScriptsLoaded()
local ok, err = pcall(function()
local side = enumValue("GroupSide", "Left", nil)
local raw = RawMenu.Create("Scripts", "1x6", "Combo panel", "Main")
local section = localization.Wrap(raw, true)
local main = section:Create("menu.main", side)
UI.enabled = main:Switch("menu.enabled", true)
UI.enabled:Icon("\u{f009}")
UI.enabled:ToolTip("menu.enabled_tip")
UI.x = main:Slider("menu.x", 0, 1200, 14, "%d")
UI.x:Icon("\u{f07e}")
UI.y = main:Slider("menu.y", 0, 700, 14, "%d")
UI.y:Icon("\u{f07d}")
UI.scale = main:Slider("menu.scale", 50, 200, 100, "%d%%")
UI.scale:Icon("\u{f065}")
UI.style = main:Combo("menu.style", { "menu.style_hud", "menu.style_corner" }, 0)
UI.style:Icon("\u{f2d0}")
end)
if not ok then
S.error = tostring(err)
return
end
S.ready = true
A.log("info", "combo panel loaded", {})
end
function script.OnDraw()
if not S.ready then return end
local ok, err = pcall(function()
A.draw()
A.tickDrag()
end)
if not ok then
S.rect, S.drag = nil, nil
if S.error == nil then
S.error = tostring(err)
A.log("error", "combo panel draw failed", { error = S.error })
end
end
end
function script.OnKeyEvent(data)
if not data or not A.active() then return true end
local key, ev = data.key, data.event
if key ~= K.MOUSE1 and key ~= K.MOUSE3 then return true end
if ev == K.KEY_DOWN then
if S.swallow[key] then return false end
local handled = false
local ok, result = pcall(A.click, key, true)
if ok then handled = result end
if handled then
S.swallow[key] = true
S.clickAt = os.clock()
return false
end
elseif ev == K.KEY_UP then
if S.swallow[key] then
S.swallow[key] = nil
if key == K.MOUSE1 and S.drag ~= nil then
local cx, cy = Input.GetCursorPos()
A.release(cx, cy)
end
return false
end
end
return true
end
function script.OnPrepareUnitOrders(data)
if S.ready and os.clock() - S.clickAt < 0.25 and A.active() and not S.hudMode then
local cx, cy = Input.GetCursorPos()
if A.inRect(cx, cy) then return false end
end
return true
end
return script
end)
