local function clamp(v, lo, hi)
if v < lo then return lo end
if v > hi then return hi end
return v
end
local function mix(c1, c2, k)
return Color(
math.floor(c1.r + (c2.r - c1.r) * k + 0.5),
math.floor(c1.g + (c2.g - c1.g) * k + 0.5),
math.floor(c1.b + (c2.b - c1.b) * k + 0.5),
math.floor(c1.a + (c2.a - c1.a) * k + 0.5))
end
local function fade(c, a)
if a >= 1 then return c end
return Color(c.r, c.g, c.b, math.floor(c.a * clamp(a, 0, 1) + 0.5))
end
local function px(v)
return math.floor(v * H.s + 0.5)
end
local function ease(k)
local q = 1 - clamp(k, 0, 1)
return 1 - q * q * q
end
local READ = { Visible = true, Disabled = true, Get = true, List = true, Name = true, ToolTip = true }
local function call(w, name, ...)
if READ[name] then
local now = H.now
local cache = H.rc[w]
if cache == nil or now - cache.t > 0.12 then
cache = { t = now }
H.rc[w] = cache
end
local arg = ...
local slot = arg ~= nil and (name .. tostring(arg)) or name
local hit = cache[slot]
if hit ~= nil then return hit[1] end
local ok, result = pcall(w[name], w, ...)
if not ok then result = nil end
cache[slot] = { result }
return result
end
H.rc[w] = nil
local ok, result = pcall(w[name], w, ...)
if ok then return result end
return nil
end
local function loadFont(weight)
