if cx < x0 or cx > x1 or cy < y0 or cy > y1 or H.cover or H.drag then return false end
local clip = H.clip
if clip and (cy < clip[1] or cy > clip[2]) then return false end
if H.layer < 2 and H.popup and inRect(H.popup.rect, cx, cy) then return false end
if H.layer < 1 and H.gear and inRect(H.gear.rect, cx, cy) then return false end
