function H.build()
local list = type(X6P) == "table" and X6P.widgets or nil
if list == nil or #list == H.built then return end
for i = H.built + 1, #list do
local entry = list[i]
local owner = X6P.gears[entry.group]
if owner ~= nil then
local bucket = H.gearItems[owner]
if bucket == nil then
bucket = {}
H.gearItems[owner] = bucket
H.gearTitle[owner] = tostring(entry.group):match("([^/]+)$")
H.gearModule[owner] = entry.module
end
bucket[#bucket + 1] = { w = entry.w, kind = entry.kind, args = entry.args, first = entry.first, group = entry.group, key = tostring(entry.w), module = entry.module }
else
local segs = {}
for seg in tostring(entry.group):gmatch("[^/]+") do segs[#segs + 1] = seg end
local key = table.concat(segs, "/", 1, math.min(3, #segs))
local tab = H.byKey[key]
if tab == nil then
local cat = segs[1] == "Scripts" and "scripts" or (segs[1] == "Heroes" and "heroes" or "other")
tab = { key = key, cat = cat, label = segs[3] or segs[#segs] or "?", items = {}, pages = {}, pageSet = {} }
H.byKey[key] = tab
H.tabs[#H.tabs + 1] = tab
local bucket = H.cats[cat]
bucket[#bucket + 1] = tab
end
local page = segs[4] or "Main"
if not tab.pageSet[page] then
tab.pageSet[page] = true
tab.pages[#tab.pages + 1] = page
end
local sub = #segs > 4 and segs[#segs] or nil
tab.items[#tab.items + 1] = { w = entry.w, kind = entry.kind, args = entry.args, first = entry.first, sub = sub, page = page, group = entry.group, key = tostring(entry.w), module = entry.module }
end
end
H.built = #list
table.sort(H.cats.heroes, function(a, b) return a.label < b.label end)
if #H.cats[H.cat] == 0 then
for _, cat in ipairs(K.CATS) do
if #H.cats[cat] > 0 then
H.cat = cat
break
end
end
end
if H.tab == nil or H.byKey[H.tab] == nil or H.byKey[H.tab].cat ~= H.cat then
local first = H.cats[H.cat][1]
H.selectTab(first and first.key or nil)
end
end
function H.selectTab(key)
