H.selectTab(first and first.key or nil)
end
local function sliderInfo(it)
local a, f = it.args, it.first
local lo, hi = a[f + 1], a[f + 2]
if type(lo) ~= "number" or type(hi) ~= "number" or hi <= lo then return nil end
local fmt = a[f + 4]
local whole = lo == math.floor(lo) and hi == math.floor(hi)
if type(fmt) == "string" and fmt:find("%%d") then whole = true end
return lo, hi, type(fmt) == "string" and fmt or nil, whole
end
local function sliderText(value, fmt, whole)
if type(value) ~= "number" then return "-" end
if fmt then
local ok, s = pcall(string.format, fmt, whole and math.floor(value + 0.5) or value)
if ok then return s end
end
if whole then return tostring(math.floor(value + 0.5)) end
return string.format("%.2f", value)
end
local function itemList(it)
local list = call(it.w, "List")
if type(list) == "table" then return list end
local items = it.args[it.first + 1]
local out = {}
if type(items) == "table" then
for i, v in ipairs(items) do out[i] = type(v) == "table" and (v[1] or v.nameId or "?") or v end
end
return out
end
local function multiInfo(it, rw)
local cache = it.mi
local now = os.clock()
if cache ~= nil and cache.rw == rw and now - cache.t < 0.4 then return cache.info end
local info = H.multiBuild(it, rw)
it.mi = { rw = rw, t = now, info = info }
return info
end
function H.multiBuild(it, rw)
local w = it.w
local list = itemList(it)
local map, any = {}, false
local rows = X6P.rows[w] or it.args[it.first + 1]
if type(rows) == "table" then
for _, row in ipairs(rows) do
if type(row) == "table" then
local rid, rpath = row[1] or row.nameId, row[2] or row.imagePath
if type(rpath) == "string" and rpath ~= "" then
map[rid] = rpath
any = true
end
end
end
end
local info = { list = list, map = map }
if #list == 0 then
info.mode = "empty"
return info
end
if not any then
info.mode = "chip"
return info
end
local tile, gap = px(K.TILE), px(K.GAP)
info.mode = "grid"
info.cols = math.max(1, math.floor((rw - px(28) + gap) / (tile + gap)))
info.rows = math.ceil(#list / info.cols)
