end
local function chars(str)
local out = {}
for ch in tostring(str):gmatch("[^\128-\191][\128-\191]*") do out[#out + 1] = ch end
return out
end
function H.fit(font, size, str, maxw)
if maxw <= 0 then return "" end
if tw(font, size, str) <= maxw then return str end
local key = str .. "|" .. size .. "|" .. math.floor(maxw)
local hit = H.fitCache[key]
if hit ~= nil then return hit end
local list = chars(str)
local out = str
for n = #list - 1, 1, -1 do
out = table.concat(list, "", 1, n):gsub(" +$", "") .. "\u{2026}"
if tw(font, size, out) <= maxw then break end
end
H.fitCache[key] = out
return out
end
function H.wrapLines(str, maxw)
local key = str .. "|" .. math.floor(maxw)
local hit = H.wrapCache[key]
if hit ~= nil then return hit end
local lines, cur = {}, ""
for word in tostring(str):gmatch("[^ ]+") do
local try = cur == "" and word or (cur .. " " .. word)
if cur ~= "" and tw(H.fonts.regular, px(12), try) > maxw then
lines[#lines + 1] = cur
cur = word
else
cur = try
end
end
if cur ~= "" then lines[#lines + 1] = cur end
if #lines == 0 then lines[1] = "" end
H.wrapCache[key] = lines
return lines
end
function H.labelLines(it, rw)
local name = X6P.labels[it.w] or call(it.w, "Name")
name = type(name) == "string" and (name:gsub("%%s", "-")) or "?"
