end
local function rowHeight(it, rw)
local kind = it.kind
if kind == "Slider" then return px(44) end
if kind == "Button" then return px(34) end
if kind == "Label" then
if H.gearItems[it.w] then return px(K.ROW) end
local lines = H.labelLines(it, rw)
