local info = multiInfo(it, rw)
if info.mode == "grid" then
return px(30) + info.rows * (px(K.TILE) + px(K.GAP)) + px(4)
end
end
return px(K.ROW)
end
local function miniSwitch(key, on, x, cy, a, dt)
