rect(x - w, cy - h / 2, x, cy + h / 2, fade(mix(P.OFF, P.ON, k), a), h / 2)
local kx = x - w + h / 2 + (w - h) * k
Render.FilledCircle(Vec2(kx, cy), h / 2 - px(2), fade(mix(P.KNOB, P.WHITE, k), a))
