local function chip(x1, cy, label, a, hot, key, minW, arrow)
local f = H.fonts
local natural = tw(f.medium, px(12), label) + (arrow and px(34) or px(22))
local w = math.min(math.max(minW or px(96), natural), px(190))
local x0 = x1 - w
rect(x0, cy - px(12), x1, cy + px(12), fade(mix(P.FIELD, P.CHIP_ON, approach("ch" .. key, hot and 1 or 0, 16, H.dt)), a), px(7))
label = H.fit(f.medium, px(12), label, w - (arrow and px(34) or px(22)))
Render.PushClip(Vec2(x0 + px(4), cy - px(12)), Vec2(x1 - (arrow and px(22) or px(4)), cy + px(12)), true)
if arrow then
text(f.medium, px(12), label, x0 + px(10), cy, fade(P.TEXT, a))
else
text(f.medium, px(12), label, x0 + (w - tw(f.medium, px(12), label)) / 2, cy, fade(P.TEXT, a))
end
Render.PopClip()
if arrow then glyph("\u{f078}", x1 - px(13), cy, px(9), fade(P.MUTED, a)) end
return x0, w
end
