function H.drawRow(it, x0, x1, y, h, a, dt, n, sep)
local f = H.fonts
local w, kind = it.w, it.kind
local wk = it.key
local k = H.rowK(n)
if k <= 0 then return end
a = a * k
local slide = math.floor(px(14) * (1 - k) + 0.5)
x0, x1 = x0 + slide, x1 + slide
local rowH = px(K.ROW)
local off = isDisabled(w)
local ra = off and a * 0.45 or a
local name = X6P.labels[w] or call(w, "Name")
name = type(name) == "string" and (name:gsub("%%s", "-")) or "?"
if sep then rect(x0 + px(14), y, x1 - px(14), y + math.max(1, px(1)), fade(P.LINE, a)) end
local top = (kind == "Slider") and px(26) or ((kind == "Button") and h or rowH)
local cy = y + (kind == "Slider" and px(15) or h / 2)
if kind == "Switch" or kind == "Combo" or kind == "Bind" or kind == "ColorPicker" or kind == "Input"
or kind == "Label" or kind == "MultiSelect" or kind == "MultiCombo" then
cy = y + rowH / 2
end
local hot = hovered(x0, y, x1, y + top)
local hv = approach("hv" .. wk, hot and 1 or 0, 16, dt)
if hv > 0.01 and kind ~= "Button" then
rect(x0, y + px(1), x1, y + top - px(1), fade(P.HOVER, a * hv), px(8))
end
if hot then
local tip = X6P.tips[w] or call(w, "ToolTip")
if type(tip) == "string" and tip ~= "" then
H.tipCand = { x0 = x0, y0 = y, x1 = x1, y1 = y + top, title = name, body = tip }
end
end
local lx, rx = x0 + px(14), x1 - px(14)
local owner = kind == "Label" and H.gearItems[w] ~= nil
if kind == "Label" and not owner then
local lines = H.labelLines(it, x1 - x0)
local gl, path = widgetIcon(it)
local lxx = lx
if gl ~= nil or path ~= nil then
H.drawIcon(it, lx, y + px(4) + px(8), ra)
lxx = lx + px(24)
end
for i, line in ipairs(lines) do
text(f.regular, px(12), line, lxx, y + px(4) + (i - 0.5) * px(16), fade(P.MUTED, ra))
end
return
end
if kind == "Button" then
local bx0, bx1 = x0 + px(14), x1 - px(14)
local by0, by1 = y + px(3), y + h - px(3)
rect(bx0, by0, bx1, by1, fade(mix(P.FIELD, P.CHIP_ON, hv), ra), px(8))
text(f.semi, px(12), name, (bx0 + bx1) / 2 - tw(f.semi, px(12), name) / 2, (by0 + by1) / 2, fade(P.TEXT, ra))
if not off then hit(bx0, by0, bx1, by1, "button", it) end
return
end
H.drawIcon(it, lx, cy, ra * (0.7 + 0.3 * hv))
local labelLeft = lx + px(24)
local ctrlLeft = rx
if kind == "Switch" then
local on = call(w, "Get") == true
miniSwitch(wk, on, rx, cy, ra, dt)
ctrlLeft = rx - px(26)
if not off then hit(x0, y, x1, y + top, "sw", it) end
elseif kind == "Slider" then
local lo, hi, fmt, whole = sliderInfo(it)
local value = call(w, "Get")
local vt = sliderText(value, fmt, whole)
local vw = text(f.medium, px(12), vt, rx - tw(f.medium, px(12), vt), cy, fade(P.TEXT, ra))
ctrlLeft = rx - vw
if lo ~= nil and type(value) == "number" then
local t0, t1 = lx, rx
local by = y + px(34)
local target = clamp((value - lo) / (hi - lo), 0, 1)
local sk = approach("sl" .. wk, target, 26, dt)
local grab = approach("sg" .. wk, (H.slider and H.slider.it == it) and 1 or hv * 0.6, 20, dt)
rect(t0, by - px(2), t1, by + px(2), fade(Color(255, 255, 255, 30), ra), px(2))
rect(t0, by - px(2), t0 + (t1 - t0) * sk, by + px(2), fade(mix(Color(111, 214, 138, 170), P.GOOD, grab), ra), px(2))
Render.FilledCircle(Vec2(t0 + (t1 - t0) * sk, by), px(5) + px(2) * grab, fade(P.WHITE, ra))
if not off then
hit(t0 - px(6), y + px(24), t1 + px(6), y + h, "slider", { it = it, x0 = t0, x1 = t1, lo = lo, hi = hi, whole = whole })
end
end
elseif kind == "Combo" then
local list = itemList(it)
local cur = call(w, "Get")
local label = type(cur) == "number" and list[cur + 1] or nil
label = label ~= nil and pretty(label) or "-"
local cx0 = chip(rx, cy, label, ra, H.popup ~= nil and H.popup.it == it, wk, px(96), true)
ctrlLeft = cx0
if not off then hit(cx0, y, rx, y + top, "combo", { it = it, x1 = rx, y0 = y, y1 = y + top, x0 = cx0 }) end
elseif kind == "Bind" then
local listening = H.listen == it
local label = listening and "..." or H.keyName(call(w, "Get", 0))
local cx0 = chip(rx, cy, label, ra, listening, wk, px(46), false)
ctrlLeft = cx0
if not off then hit(cx0, y, rx, y + top, "bind", it) end
elseif kind == "ColorPicker" then
local c = call(w, "Get")
local sx0 = rx - px(40)
rect(sx0, cy - px(9), rx, cy + px(9), fade(P.FIELD, ra), px(6))
if type(c) == "table" or type(c) == "userdata" then
local okc, col = pcall(function() return Color(c.r, c.g, c.b, 255) end)
if okc then rect(sx0 + px(2), cy - px(7), rx - px(2), cy + px(7), fade(col, ra), px(5)) end
end
ctrlLeft = sx0
hit(sx0, y, rx, y + top, "open", it)
elseif kind == "Input" then
local value = call(w, "Get")
value = type(value) == "string" and value or ""
local cx0 = chip(rx, cy, value == "" and "..." or H.fit(f.medium, px(12), value, px(150)), ra, false, wk, px(96), false)
ctrlLeft = cx0
hit(cx0, y, rx, y + top, "open", it)
elseif kind == "MultiCombo" or kind == "MultiSelect" then
local info = multiInfo(it, x1 - x0)
local list, map = info.list, info.map
local count = 0
for _, id in ipairs(list) do
if call(w, "Get", id) == true then count = count + 1 end
end
local tile, gap = px(K.TILE), px(K.GAP)
if info.mode == "grid" then
local ct = string.format("%d / %d", count, #list)
local cw_ = text(f.medium, px(11), ct, rx - tw(f.medium, px(11), ct), cy, fade(P.MUTED, ra))
ctrlLeft = rx - cw_
local gx, gy = lx, y + px(30)
local gapX = gap
if info.rows > 1 and info.cols > 1 then gapX = (rx - lx - info.cols * tile) / (info.cols - 1) end
for i, id in ipairs(list) do
local col, row = (i - 1) % info.cols, math.floor((i - 1) / info.cols)
local tx, ty = gx + col * (tile + gapX), gy + row * (tile + gap)
local on = call(w, "Get", id) == true
local th_ = hovered(tx, ty, tx + tile, ty + tile)
H.drawTile(map[id], id, tx, ty, tile, on, th_, ra)
if th_ then H.tipCand = { x0 = tx, y0 = ty, x1 = tx + tile, y1 = ty + tile, title = pretty(id), body = (map[id] and not H.pic(map[id], id)) and ("missing: " .. map[id]) or "" } end
hit(tx, ty, tx + tile, ty + tile, "multiItem", { it = it, id = id })
end
elseif info.mode == "empty" then
local ct = "0 / 0"
ctrlLeft = rx - text(f.medium, px(11), ct, rx - tw(f.medium, px(11), ct), cy, fade(P.DIM, ra))
else
local open = H.popup ~= nil and H.popup.it == it
local cx0 = chip(rx, cy, string.format("%d / %d", count, #list), ra, open, wk, px(76), true)
ctrlLeft = cx0
hit(cx0, y, rx, y + top, "multi", { it = it, x0 = cx0, x1 = rx, y0 = y, y1 = y + top })
end
end
if owner then
hit(x0, y, x1, y + top, "gear", { owner = w, ax0 = x0, ax1 = x1, ay0 = y, ay1 = y + top })
end
if H.gearItems[w] ~= nil then
local gx = owner and (rx - px(7)) or (ctrlLeft - px(16))
local open = H.gear ~= nil and H.gear.owner == w
local gv = approach("gv" .. wk, (hovered(gx - px(10), y, gx + px(10), y + top) or open) and 1 or 0, 16, dt)
glyph(X6P.gearIcons[w] or "\u{f013}", gx, cy, px(13), fade(mix(P.DIM, P.TEXT, gv), ra))
hit(gx - px(11), y, gx + px(11), y + top, "gear", { owner = w, ax0 = gx - px(11), ax1 = gx + px(11), ay0 = y, ay1 = y + top })
ctrlLeft = ctrlLeft - px(26)
end
text(f.medium, px(13), H.fit(f.medium, px(13), name, ctrlLeft - px(8) - labelLeft), labelLeft, cy, fade(P.TEXT, ra))
end
function H.drawContent(x0, y0, x1, y1, a, dt)
local f = H.fonts
local tab = H.tab and H.byKey[H.tab] or nil
if tab == nil then
local label = localization.Get("ui.empty")
text(f.medium, px(13), label, (x0 + x1) / 2 - tw(f.medium, px(13), label) / 2, (y0 + y1) / 2, fade(P.DIM, a))
return
end
local skey = H.scrollKey()
local scroll = clamp(H.scroll[skey] or 0, 0, H.max or 0)
H.scroll[skey] = scroll
local sm = approach("scroll" .. skey, scroll, 22, dt)
if math.abs(sm - scroll) < 0.5 then sm = scroll end
H.contentRect = { x0, y0, x1, y1 }
local pad, gap = px(10), px(10)
local wide = (x1 - x0) >= px(560)
local cols = wide and 2 or 1
local colW = math.floor(((x1 - x0) - pad * 2 - gap * (cols - 1)) / cols)
local rw = colW - px(8)
local blocks, cur = {}, nil
for _, it in ipairs(tab.items) do
if (#tab.pages < 2 or it.page == H.page) and isVisible(it.w) then
if cur == nil or cur.group ~= it.group then
cur = { group = it.group, module = it.module, title = it.sub, items = {}, hs = {}, side = X6P.sides[it.group], height = px(6) }
if cur.title ~= nil then cur.height = px(K.HEAD) end
blocks[#blocks + 1] = cur
end
local h = rowHeight(it, rw)
cur.items[#cur.items + 1] = it
cur.hs[#cur.items] = h
cur.height = cur.height + h
end
end
if #blocks == 0 then
local label = localization.Get("ui.empty")
text(f.medium, px(13), label, (x0 + x1) / 2 - tw(f.medium, px(13), label) / 2, y0 + px(60), fade(P.DIM, a))
end
local right = enumValue("GroupSide", "Right", -99)
local place = {}
local y = y0 + pad - sm
if cols == 1 then
for _, b in ipairs(blocks) do
local h = b.height + px(6)
place[#place + 1] = { b = b, c = 1, y = y, h = h }
y = y + h + gap
end
else
local cy = { y, y }
for _, b in ipairs(blocks) do
local c
if b.side ~= nil and b.side == right then
c = 2
elseif b.side ~= nil then
c = 1
else
c = cy[2] < cy[1] and 2 or 1
end
local h = b.height + px(6)
place[#place + 1] = { b = b, c = c, y = cy[c], h = h }
cy[c] = cy[c] + h + gap
end
y = math.max(cy[1], cy[2])
end
H.contentH = (y - gap) - (y0 + pad - sm) + pad * 2
local ys = { y, y }
local n = 0
H.clip = { y0, y1 }
Render.PushClip(Vec2(x0, y0), Vec2(x1, y1), true)
for _, pl in ipairs(place) do
local b = pl.b
local bx0 = x0 + pad + (pl.c - 1) * (colW + gap)
local bx1 = bx0 + colW
local by, bh = pl.y, pl.h
local seen = by + bh >= y0 and by <= y1
if seen then
local k = H.rowK(n)
rect(bx0, by, bx1, by + bh, fade(P.CARD, a * k), px(10))
outline(bx0, by, bx1, by + bh, fade(P.LINE, a * k), px(10), 1)
end
local ry = by + px(3)
if b.title ~= nil then
if seen then
text(f.semi, px(12), H.fit(f.semi, px(12), X6P.tr(b.title, b.module), colW - px(36)), bx0 + px(18), ry + px(K.HEAD) / 2, fade(P.MUTED, a * H.rowK(n)))
end
ry = ry + px(K.HEAD) - px(3)
end
for i, it in ipairs(b.items) do
local h = b.hs[i]
if ry + h >= y0 and ry <= y1 then H.drawRow(it, bx0 + px(4), bx1 - px(4), ry, h, a, dt, n, i > 1) end
ry = ry + h
n = n + 1
end
end
local total = math.max(ys[1], ys[2])
H.max = math.max(0, total + sm - y1)
Render.PopClip()
H.clip = nil
if H.max > 0 then
local trackH = y1 - y0 - px(8)
local barH = math.max(px(24), trackH * (y1 - y0) / (H.max + y1 - y0))
local barY = y0 + px(4) + (trackH - barH) * (sm / H.max)
rect(x1 - px(5), barY, x1 - px(2), barY + barH, fade(Color(255, 255, 255, 40), a), px(2))
end
end
function H.drawRail(x0, y0, x1, y1, a, dt)
local f = H.fonts
local list = H.cats[H.cat]
local rowH = px(34)
local maxScroll = math.max(0, #list * rowH + px(12) - (y1 - y0))
H.railScroll = clamp(H.railScroll, 0, maxScroll)
local sm = approach("railscroll", H.railScroll, 22, dt)
if math.abs(sm - H.railScroll) < 0.5 then sm = H.railScroll end
H.railRect = { x0, y0, x1, y1 }
H.clip = { y0, y1 }
Render.PushClip(Vec2(x0, y0), Vec2(x1, y1), true)
local base = y0 + px(6) - sm
for i, tab in ipairs(list) do
if tab.key == H.tab then
local rel = (i - 1) * rowH - sm
if H.snapRail then
H.anim.railhy = rel
H.snapRail = false
end
local hy = y0 + px(6) + approach("railhy", rel, 20, dt)
rect(x0 + px(8), hy + px(2), x1 - px(8), hy + rowH - px(2), fade(P.CHIP_ON, a), px(9))
rect(x0 + px(8), hy + px(9), x0 + px(11), hy + rowH - px(9), fade(P.GOOD, a), px(2))
break
end
end
for i, tab in ipairs(list) do
local y = base + (i - 1) * rowH
if y + rowH >= y0 and y <= y1 then
local on = tab.key == H.tab
local hot = hovered(x0 + px(8), y, x1 - px(8), y + rowH)
local hv = approach("rv" .. tab.key, hot and 1 or 0, 16, dt)
if hv > 0.01 and not on then
rect(x0 + px(8), y + px(2), x1 - px(8), y + rowH - px(2), fade(P.HOVER, a * hv), px(9))
end
local ok = approach("ro" .. tab.key, on and 1 or 0, 14, dt)
local tone = mix(P.MUTED, P.TEXT, math.max(ok, hv * 0.6))
H.drawTabIcon(tab, x0 + px(24), y + rowH / 2, a, ok)
Render.PushClip(Vec2(x0 + px(8), y), Vec2(x1 - px(10), y + rowH), true)
text(on and f.semi or f.medium, px(13), H.fit(on and f.semi or f.medium, px(13), tab.label, x1 - x0 - px(62)), x0 + px(44) + math.floor(px(2) * ok), y + rowH / 2, fade(tone, a))
Render.PopClip()
hit(x0 + px(8), y, x1 - px(8), y + rowH, "tab", tab)
end
end
Render.PopClip()
H.clip = nil
end
function H.drawPopup(a)
local pop = H.popup
if pop == nil then return end
local f = H.fonts
H.layer = 2
local list = itemList(pop.it)
local rowH = px(26)
local rows = math.min(#list, 10)
local w = math.max(pop.x1 - pop.x0, pop.multi and px(200) or px(150))
local h = rows * rowH + px(8)
local x1 = pop.x1
local x0 = x1 - w
local screen = Render.ScreenSize()
local pk = ease((os.clock() - (pop.t0 or 0)) / 0.14)
a = a * pk
local y = pop.y1 + px(4)
if y + h > screen.y - 4 then y = pop.y0 - px(4) - h end
y = y + math.floor(px(8) * (1 - pk) + 0.5) * (y > pop.y1 and -1 or 1)
pop.scroll = clamp(pop.scroll or 0, 0, math.max(0, #list - rows))
pop.rect = { x0, y, x1, y + h }
rect(x0 - px(1), y - px(1), x1 + px(1), y + h + px(1), fade(Color(0, 0, 0, 90), a), px(10))
rect(x0, y, x1, y + h, fade(P.POP, a), px(9))
hit(x0, y, x1, y + h, "popbg")
local cur = call(pop.it.w, "Get")
if pop.multi then
for i = 1, rows do
local idx = i + pop.scroll
local id = list[idx]
local ry = y + px(4) + (i - 1) * rowH
local on = call(pop.it.w, "Get", id) == true
if hovered(x0 + px(4), ry, x1 - px(4), ry + rowH) then rect(x0 + px(4), ry, x1 - px(4), ry + rowH, fade(P.CHIP_ON, a), px(6)) end
miniSwitch(tostring(pop.it.w) .. tostring(id), on, x1 - px(14), ry + rowH / 2, a, H.dt)
Render.PushClip(Vec2(x0 + px(8), ry), Vec2(x1 - px(48), ry + rowH), true)
text(on and f.semi or f.medium, px(12), pretty(id), x0 + px(14), ry + rowH / 2, fade(on and P.TEXT or P.MUTED, a))
Render.PopClip()
hit(x0 + px(4), ry, x1 - px(4), ry + rowH, "multiItem", { it = pop.it, id = id })
end
H.layer = 0
return
end
for i = 1, rows do
local idx = i + pop.scroll
local ry = y + px(4) + (i - 1) * rowH
local on = cur == idx - 1
if hovered(x0 + px(4), ry, x1 - px(4), ry + rowH) then rect(x0 + px(4), ry, x1 - px(4), ry + rowH, fade(P.CHIP_ON, a), px(6)) end
text(on and f.semi or f.medium, px(12), pretty(list[idx]), x0 + px(14), ry + rowH / 2, fade(on and P.GOOD or P.TEXT, a))
hit(x0 + px(4), ry, x1 - px(4), ry + rowH, "comboItem", { it = pop.it, index = idx - 1 })
end
H.layer = 0
end
function H.drawGear(a, dt)
local g = H.gear
if g == nil then return end
local f = H.fonts
local list = H.gearItems[g.owner]
if list == nil then
H.gear = nil
return
end
H.layer = 1
local pw = px(400)
local inner = pw - px(12)
local items, hs, total = {}, {}, px(K.HEAD) + px(10)
for _, it in ipairs(list) do
if isVisible(it.w) then
local h = rowHeight(it, inner)
items[#items + 1] = it
hs[#items] = h
total = total + h
end
end
local screen = Render.ScreenSize()
local ph = math.min(total, math.floor(H.h - px(24)))
local maxScroll = math.max(0, total - ph)
g.scroll = clamp(g.scroll or 0, 0, maxScroll)
local pk = ease((os.clock() - g.t0) / 0.14)
local pa = a * pk
local cr = H.contentRect or { 4, 4, screen.x - 4, screen.y - 4 }
local winRight = H.x + H.w - px(6)
local x = g.ax1 + px(8)
if x + pw > winRight then
x = g.ax0 - px(8) - pw
if x < cr[1] then x = g.ax1 - pw end
end
x = clamp(x, math.max(4, cr[1] - px(6)), math.max(4, screen.x - pw - 4))
local y = clamp(g.ay0 - px(6), H.y + px(8), math.max(H.y + px(8), H.y + H.h - ph - px(8))) + math.floor(px(8) * (1 - pk) + 0.5)
g.rect = { x, y, x + pw, y + ph }
rect(x - px(1), y - px(1), x + pw + px(1), y + ph + px(1), fade(Color(0, 0, 0, 100), pa), px(13))
rect(x, y, x + pw, y + ph, fade(P.POP, pa), px(12))
outline(x, y, x + pw, y + ph, fade(P.LINE, pa), px(12), 1)
hit(x, y, x + pw, y + ph, "popbg")
text(f.semi, px(12), H.fit(f.semi, px(12), X6P.tr(H.gearTitle[g.owner] or "", H.gearModule[g.owner]), pw - px(32)), x + px(16), y + px(K.HEAD) / 2 + px(2), fade(P.MUTED, pa))
local top = y + px(K.HEAD) + px(2)
H.clip = { top, y + ph - px(4) }
Render.PushClip(Vec2(x, top), Vec2(x + pw, y + ph - px(4)), true)
local ry = top - g.scroll
for i, it in ipairs(items) do
local h = hs[i]
if ry + h >= top and ry <= y + ph then H.drawRow(it, x + px(6), x + pw - px(6), ry, h, pa, dt, 0, i > 1) end
ry = ry + h
end
Render.PopClip()
H.clip = nil
H.layer = 0
end
function H.drawTip(a)
local c = H.tipCand
H.tipCand = nil
if c == nil or H.popup or not cursorInWindow() then return end
local f = H.fonts
local lines = {}
for line in tostring(c.body):gmatch("[^\n]+") do lines[#lines + 1] = line end
local maxw = px(320)
local wrapped = {}
for _, line in ipairs(lines) do
local cur = ""
for word in line:gmatch("[^ ]+") do
local try = cur == "" and word or (cur .. " " .. word)
if cur ~= "" and tw(f.regular, px(11), try) > maxw then
wrapped[#wrapped + 1] = cur
cur = word
else
cur = try
end
end
if cur ~= "" then wrapped[#wrapped + 1] = cur end
end
local w = tw(f.bold, px(12), c.title)
for _, line in ipairs(wrapped) do w = math.max(w, tw(f.regular, px(11), line)) end
local padX, padY, lineH = px(10), px(8), px(15)
w = math.floor(w + padX * 2 + 0.5)
local h = padY * 2 + px(16) + #wrapped * lineH + (#wrapped > 0 and px(2) or 0)
local screen = Render.ScreenSize()
local x = math.floor(clamp((c.x0 + c.x1) / 2 - w / 2, 4, screen.x - w - 4))
local y = math.floor(c.y1 + px(6))
if y + h > screen.y - 4 then y = math.floor(c.y0 - px(6) - h) end
rect(x, y, x + w, y + h, fade(P.TIP, a), px(8))
local cy = y + padY + px(8)
text(f.bold, px(12), c.title, x + padX, cy, fade(P.TEXT, a))
cy = cy + px(12) + lineH / 2
for _, line in ipairs(wrapped) do
