function H.click()
local cx, cy = Input.GetCursorPos()
local target = nil
for i = #H.hits, 1, -1 do
local item = H.hits[i]
if cx >= item[1] and cx <= item[3] and cy >= item[2] and cy <= item[4] then
target = item
break
end
end
local kind, arg = nil, nil
if target ~= nil then kind, arg = target[5], target[6] end
local inPopup = H.popup ~= nil and inRect(H.popup.rect, cx, cy)
if H.listen ~= nil and kind ~= "bind" then H.listen = nil end
local keepMulti = kind == "multiItem" and H.popup ~= nil and H.popup.multi and arg.it == H.popup.it
if H.popup ~= nil and kind ~= "comboItem" and kind ~= "popbg" and not keepMulti then
local same = (kind == "combo" or kind == "multi") and arg.it == H.popup.it
H.popup = nil
if same then return end
end
if H.gear ~= nil and not inPopup and not inRect(H.gear.rect, cx, cy) then
local same = kind == "gear" and arg.owner == H.gear.owner
H.gear = nil
if same then return end
end
if target == nil then return end
if kind == "close" then
H.open = false
if UI.show:Get() and Menu.Opened() then pcall(UI.show.Set, UI.show, false) end
elseif kind == "drag" then
H.drag = { dx = cx - H.x, dy = cy - H.y }
elseif kind == "cat" then
H.setCat(arg)
elseif kind == "tab" then
H.selectTab(arg.key)
elseif kind == "page" then
H.page = arg
H.touch()
elseif kind == "sw" then
call(arg.w, "Set", not (call(arg.w, "Get") == true))
elseif kind == "slider" then
H.slider = arg
local k = clamp((cx - arg.x0) / math.max(1, arg.x1 - arg.x0), 0, 1)
local v = arg.lo + (arg.hi - arg.lo) * k
if arg.whole then v = math.floor(v + 0.5) else v = math.floor(v * 100 + 0.5) / 100 end
call(arg.it.w, "Set", v)
elseif kind == "combo" then
H.popup = { it = arg.it, x0 = arg.x0, x1 = arg.x1, y0 = arg.y0, y1 = arg.y1, scroll = 0, t0 = os.clock() }
elseif kind == "comboItem" then
call(arg.it.w, "Set", arg.index)
H.popup = nil
elseif kind == "multi" then
H.popup = { it = arg.it, multi = true, x0 = arg.x0, x1 = arg.x1, y0 = arg.y0, y1 = arg.y1, scroll = 0, t0 = os.clock() }
elseif kind == "multiItem" then
if call(arg.it.w, "DragAllowed") == true then
H.tileDrag = { it = arg.it, id = arg.id, sx = cx, sy = cy, moved = false }
else
call(arg.it.w, "Set", arg.id, not (call(arg.it.w, "Get", arg.id) == true))
end
elseif kind == "button" then
local cb = arg.args[arg.first + 1]
if type(cb) == "function" then pcall(cb, arg.w) end
elseif kind == "bind" then
H.listen = H.listen ~= arg and arg or nil
elseif kind == "gear" then
H.gear = { owner = arg.owner, ax0 = arg.ax0, ax1 = arg.ax1, ay0 = arg.ay0, ay1 = arg.ay1, scroll = 0, t0 = os.clock() }
elseif kind == "open" then
call(arg.w, "Open")
end
end
function H.reorder(it, fromId, toId)
local w = it.w
local info = H.multiBuild(it, 0)
local order = {}
for _, id in ipairs(info.list) do
if id ~= fromId then order[#order + 1] = id end
end
local at = #order + 1
for i, id in ipairs(order) do
if id == toId then at = i end
end
local old = 0
for i, id in ipairs(info.list) do
if id == fromId then old = i end
end
local target = 0
for i, id in ipairs(info.list) do
if id == toId then target = i end
end
if target > old then at = at + 1 end
table.insert(order, math.max(1, math.min(at, #order + 1)), fromId)
local rows, selected = {}, {}
for _, id in ipairs(order) do
local on = call(w, "Get", id) == true
rows[#rows + 1] = { id, info.map[id] or "", on }
if on then selected[#selected + 1] = id end
end
call(w, "Update", rows, true, true)
call(w, "Set", selected)
it.mi = nil
end
function H.tileRelease()
local d = H.tileDrag
H.tileDrag = nil
if d == nil then return end
if not d.moved then
call(d.it.w, "Set", d.id, not (call(d.it.w, "Get", d.id) == true))
return
end
local cx, cy = Input.GetCursorPos()
for i = #H.hits, 1, -1 do
local item = H.hits[i]
if item[5] == "multiItem" and item[6].it == d.it and cx >= item[1] and cx <= item[3] and cy >= item[2] and cy <= item[4] then
if item[6].id ~= d.id then H.reorder(d.it, d.id, item[6].id) end
return
end
end
end
function H.drawTileDrag(a)
local d = H.tileDrag
if d == nil then return end
if not Input.IsKeyDown(K.MOUSE1, true) then
H.tileRelease()
return
end
local cx, cy = H.cx, H.cy
if not d.moved and (math.abs(cx - d.sx) > px(6) or math.abs(cy - d.sy) > px(6)) then d.moved = true end
if not d.moved then return end
for i = #H.hits, 1, -1 do
local item = H.hits[i]
if item[5] == "multiItem" and item[6].it == d.it and item[6].id ~= d.id and cx >= item[1] and cx <= item[3] and cy >= item[2] and cy <= item[4] then
outline(item[1], item[2], item[3], item[4], fade(P.TILE_ON, a), px(5), math.max(2, px(2)))
break
end
end
local info = d.it.mi ~= nil and d.it.mi.info or nil
local tile = px(K.TILE)
H.drawTile(info ~= nil and info.map[d.id] or nil, d.id, cx - tile / 2, cy - tile / 2, tile, call(d.it.w, "Get", d.id) == true, true, a * 0.85)
end
function H.error(err)
H.err = H.err or tostring(err)
local font = H.fonts and H.fonts.medium
if font == nil then return end
Render.FilledRect(Vec2(20, 560), Vec2(780, 586), Color(20, 20, 24, 235), 4)
Render.Text(font, 12, ("hub: " .. H.err):sub(1, 150), Vec2(30, 566), Color(224, 50, 45, 245))
end
