if type(ai_bridge) == "table" and type(ai_bridge.mcp_log) == "function" and not H.logged then
H.logged = true
pcall(ai_bridge.mcp_log, "error", "hub draw failed", { error = tostring(err) })
end
elseif H.err ~= nil then
H.error(H.err)
end
