function script.OnKeyEvent(data)
if not H.ready or not data then return true end
H.now = os.clock()
local key, ev = data.key, data.event
if ev == K.KEY_UP and key == K.MOUSE1 and H.swallow[key] then
H.held[key], H.swallow[key] = nil, nil
if H.tileDrag ~= nil then pcall(H.tileRelease) end
return false
end
if not H.shown or os.clock() - H.drawAt > 0.5 then
H.swallow[key] = nil
return true
end
if H.listen ~= nil and ev == K.KEY_DOWN and key ~= K.MOUSE1 and key ~= K.WHEEL_UP and key ~= K.WHEEL_DOWN then
local w = H.listen.w
H.listen = nil
if key ~= K.ESCAPE then
local mode = call(w, "Get", 1)
call(w, "Set", key == K.BACKSPACE and 0 or key, type(mode) == "number" and mode or 0)
end
return false
end
local scroll = 0
if ev == K.SCROLL_UP or ev == K.SCROLL_DOWN then
scroll = ev == K.SCROLL_UP and -1 or 1
elseif (key == K.WHEEL_UP or key == K.WHEEL_DOWN) and ev == K.KEY_DOWN then
scroll = key == K.WHEEL_UP and -1 or 1
end
if scroll ~= 0 then
if not cursorInWindow() then return true end
local cx, cy = Input.GetCursorPos()
local step = px(K.SCROLL)
if H.popup and inRect(H.popup.rect, cx, cy) then
H.popup.scroll = (H.popup.scroll or 0) + scroll
elseif H.gear and inRect(H.gear.rect, cx, cy) then
H.gear.scroll = (H.gear.scroll or 0) + scroll * step
elseif inRect(H.railRect, cx, cy) then
H.railScroll = H.railScroll + scroll * step
elseif inRect(H.contentRect, cx, cy) and H.tab then
H.scroll[H.scrollKey()] = (H.scroll[H.scrollKey()] or 0) + scroll * step
end
return false
end
if key ~= K.MOUSE1 then return true end
if ev == K.KEY_DOWN then
local held = H.held[key]
H.held[key] = true
if held then return not H.swallow[key] end
if cursorInWindow() then
H.swallow[key] = true
H.clickAt = os.clock()
local ok, err = pcall(H.click)
if not ok then H.err = tostring(err) end
return false
end
H.popup, H.gear, H.listen = nil, nil, nil
elseif ev == K.KEY_UP then
H.held[key] = nil
if H.swallow[key] then
H.swallow[key] = nil
return false
end
end
return true
end
function script.OnPrepareUnitOrders(data)
if H.ready and os.clock() - H.clickAt < 0.2 and cursorInWindow() then return false end
return true
end
return script
