local bundle = {}
local names = {}
local prof = { at = nil, frames = 0, acc = {}, slow = 0, worst = 0, mem = 0 }
local function profFlush(now)
local span = now - prof.at
if span < PROFILE_LOG then return end
local rows = {}
for key, a in pairs(prof.acc) do rows[#rows + 1] = { key = key, sum = a.sum, max = a.max, n = a.n } end
table.sort(rows, function(x, y) return x.sum > y.sum end)
local report = {
fps = math.floor(prof.frames / span + 0.5), span = math.floor(span), mem_kb = math.floor(collectgarbage("count")),
draw_slow = prof.slow, draw_worst_ms = math.floor(prof.worst * 10000) / 10,
}
for i = 1, math.min(10, #rows) do
local r = rows[i]
report[string.format("%02d %s", i, r.key)] = string.format("%.2f ms/s, %.3f avg, %.2f max, %d calls", r.sum * 1000 / span, r.sum * 1000 / r.n, r.max * 1000, r.n)
end
if type(ai_bridge) == "table" and type(ai_bridge.mcp_log) == "function" then pcall(ai_bridge.mcp_log, "info", "pack profile", report) end
prof.at, prof.frames, prof.acc, prof.slow, prof.worst = now, 0, {}, 0, 0
end
for _, entry in ipairs(modules) do
for name, fn in pairs(entry.script) do
if type(fn) == "function" and not names[name] then
names[name] = true
local list = {}
for _, item in ipairs(modules) do
if type(item.script[name]) == "function" then list[#list + 1] = item end
end
local count = #list
local timed = name == "OnScriptsLoaded" and pack_clock ~= nil
local profiled = profile_on and pack_clock ~= nil and name ~= "OnScriptsLoaded"
local keys = {}
for i = 1, count do keys[i] = list[i].name .. ":" .. name end
local isDraw = name == "OnDraw"
bundle[name] = function(...)
local blocked, answer = false, nil
local frameStart = profiled and pack_clock() or 0
for i = 1, count do
local item = list[i]
local started = (timed or profiled) and pack_clock() or 0
X6P.module = item.name
local ok, result = pcall(item.script[name], ...)
if timed then item.initMs = (pack_clock() - started) * 1000 end
if profiled then
local dt = pack_clock() - started
local a = prof.acc[keys[i]]
if a == nil then
a = { sum = 0, max = 0, n = 0 }
prof.acc[keys[i]] = a
end
a.sum, a.n = a.sum + dt, a.n + 1
if dt > a.max then a.max = dt end
end
if not ok then
if not item.errored then
item.errored = true
if type(ai_bridge) == "table" and type(ai_bridge.mcp_log) == "function" then
pcall(ai_bridge.mcp_log, "error", "bundle module error", { module = item.name, callback = name, error = tostring(result) })
end
end
elseif result == false then
blocked = true
elseif result ~= nil then
answer = result
end
end
if timed and type(ai_bridge) == "table" and type(ai_bridge.mcp_log) == "function" then
local report, total = {}, 0
for _, item in ipairs(modules) do
local ms = (item.loadMs or 0) + (item.initMs or 0)
total = total + ms
report[item.name] = math.floor(ms * 10 + 0.5) / 10
end
report.total = math.floor(total * 10 + 0.5) / 10
pcall(ai_bridge.mcp_log, "info", "bundle load ms", report)
end
if profiled and isDraw then
local now = pack_clock()
local total = now - frameStart
if prof.at == nil then prof.at = now end
prof.frames = prof.frames + 1
if total > 0.006 then prof.slow = prof.slow + 1 end
if total > prof.worst then prof.worst = total end
profFlush(now)
end
if blocked then return false end
return answer
end
end
end
end
if next(failed_load) ~= nil then
local draw = bundle.OnDraw
local font = nil
bundle.OnDraw = function(...)
if draw ~= nil then draw(...) end
pcall(function()
if font == nil then font = Render.LoadFont("MuseoSansEx", 0, 500) end
local y = 430
for name, err in pairs(failed_load) do
Render.FilledRect(Vec2(20, y), Vec2(780, y + 22), Color(20, 20, 24, 235), 4)
Render.Text(font, 12, (name .. ": " .. err):sub(1, 150), Vec2(30, y + 4), Color(224, 50, 45, 245))
y = y + 26
end
end)
end
end
return bundle
